P.entries["item:handful-of-stardust"] = {n="Горсть звездной пыли",s="Горсти звездной пыли — мерцающий, похожий на иней налет, собираемый с искрящихся кустов на юге Ясеневого леса. Этот порошок из древних Руин Звездной Пыли обладает природными охлаждающими свойствами и ценится целителями ночных эльфов при лечении сильной лихорадки.",h="Горсти звездной пыли — мерцающий, похожий на иней налет, собираемый с искрящихся кустов на юге Ясеневого леса.",kw={"ashenvale","astranaar","orendil","pelturas","poultice","relara","ruins of stardust","stardust","ясеневый лес","астранаар","орендил","пельтур","припарка","релара","руины звездной пыли","звездная пыль"},ang={["profession:Herbalism"]="Хотя звездную пыль собирают вручную с искрящихся кустов, а не добывают как обычный растительный реагент, она показывает, как ночные эльфы полагаются на редкую местную флору в целительной медицине.",["race:NightElf"]="Для кальдораев, защищающих Ясеневый лес, добыча местных средств вроде звездной пыли отражает вечную гармонию между их древними руинами и травяными традициями."},sec={{t="Охлаждающее травяное средство",b="Звездная пыль, прилипшая к листве кустов в древних Руинах Звездной Пыли к югу от Астранаара, выглядит как тонкий светящийся иней. Хотя сами руины населены неупокоенными духами стихий, растительность среди разбитых камней впитывает редкое рассеянное свечение. Традиционная медицина ночных эльфов перерабатывает этот иней в припарки, вытягивающие упорную опасную лихорадку, когда обычные мази и вода лунных колодцев не приносят полного облегчения."},{t="Надежда отца",b="Пельтур Белая Луна, встревоженный отец из Астранаара, искал этот порошок по совету травника Орендила Широколиста. Юная дочь Пельтура, Релара, страдала от упорного магического недуга и кошмаров. Хотя первое благословение от камня, тронутого Элуной, успокоило ее разум, сильная телесная лихорадка не отступала, и отец отправился на поиски звездной пыли, чтобы приготовить охлаждающую пасту и спасти жизнь ребенка."}},faq={{q="Где найти горсть звездной пыли?",a="Ее собирают с блестящих кустов, покрытых звездной пылью, что растут по всем Руинам Звездной Пыли к югу от поселения ночных эльфов Астранаар в центральной части Ясеневого леса.",al={"stardust location","where to find stardust","stardust covered bushes","где звездная пыль","где найти звездную пыль","кусты со звездной пылью"}},{q="Для чего нужна эта звездная пыль?",a="Пельтур Белая Луна в Астранааре использует порошок для приготовления успокаивающей припарки, чтобы сбить неутихающую лихорадку у своей больной дочери Релары.",al={"use of stardust","pelturas cure","stardust purpose","применение звездной пыли","лекарство пельтура","зачем звездная пыль"}},{q="Какие опасности окружают кусты со звездной пылью?",a="В Руинах Звездной Пыли обитают враждебные водные элементали, которые таятся у берега и среди древних упавших колонн, где растут кусты.",al={"ruins of stardust enemies","ruins of stardust mobs","враги руин звездной пыли","монстры руин звездной пыли"}},{q="Связана ли звездная пыль с богиней Элуной?",a="Хотя ночные эльфы почитают небесные силы, а у руин звездное название, звездная пыль служит прежде всего физическим лекарственным ингредиентом, который травники рекомендуют за его инееподобную охлаждающую природу.",al={"is stardust magic","elune connection stardust","магия ли звездная пыль","связь звездной пыли с элуной"}}},fp="19,273,23.505.0,15.410.1,39.174.0,31.156.0,42.152.0,41.202.0"}
P.entries["item:hardened-tortoise-shell"] = {n="Крепкий панцирь черепахи",s="Крепкие панцири черепахи — удивительно прочные щиты, добываемые с блестящепанцирных черепах, бродящих по Мерцающей равнине. Гномы-гонщики с Виражей на Миражах высоко ценят эти грубые органические пластины за непревзойденную стойкость к летучему и едкому экспериментальному топливу.",h="Крепкие панцири черепахи — удивительно прочные щиты, добываемые с блестящепанцирных черепах, бродящих по...",kw={"hardened tortoise shell","mirage raceway","rocket car","shimmering flats","sparkleshell","wizzle brassbolts","крепкий панцирь черепахи","виражи на миражах","ракетный автомобиль","мерцающая равнина","блестящепанцирные","виззл медноштиф"},ang={["profession:Engineering"]="Использовать органические панцири как топливные баки высокого давления нетрадиционно, но когда гномье топливо плавит обычные трубы из сплавов, на помощь нередко приходят прочные природные материалы.",["race:Gnome"]="Только гномья изобретательность, увидев пустынную черепаху, сразу подумает о легком и очень стойком контейнере для опасного ракетного топлива."},sec={{t="Природная броня против опасностей скорости",b="На выжженной солнцем Мерцающей равнине обитают разные виды блестящепанцирных черепах, в том числе щелкунов и бурильщиков, чьи панцири стали исключительно прочной защитой от едкой пустынной соли и бродячих хищников. На соляных равнинах обычные топливные баки из металлических сплавов часто разъедает или разрывает под действием гномьей экспериментальной химии. Механики вроде Виззла Медноштифа ценят эти панцири не как броню или щиты, а как органическое сырье, достаточно прочное, чтобы переделать его в самодельные кислотостойкие баки для летучего ракетного топлива."}},faq={{q="Где найти Крепкие панцири черепахи?",a="Их добывают с блестящепанцирных черепах — Блестящепанцирных щелкунов, Бурильщиков и обычных Блестящепанцирных черепах, — бродящих по открытым соляным просторам Мерцающей равнины в Тысяче Игл.",al={"where to get tortoise shells","hardened shell location","sparkleshell location","где взять панцири черепахи","где крепкий панцирь","где блестящепанцирные"}},{q="Зачем Виззлу Медноштифу эти панцири?",a="Брат Виззла разрабатывает чрезвычайно мощное едкое ракетное топливо, которое грозит прожечь насквозь шасси их гоночной машины. Виззл намерен выдолбить и укрепить исключительно прочные панцири черепах, чтобы использовать их как химически стойкие топливные баки.",al={"why need shells","wizzle shells use","what are shells for","зачем нужны панцири","панцири виззла","для чего панцири"}},{q="Можно ли легко обработать их обычными инструментами мастерской?",a="Нет. Панцири настолько неестественно тверды, что гномы-механики ждут, что погнут и испортят целый ящик металлических инструментов, пока попытаются вырезать, просверлить и придать им форму баков.",al={"are shells hard to craft","bending tools shell","трудно ли обрабатывать панцири","гнутся инструменты панцирь"}}},fp="23,286,36.617.0,43.212.0,45.273.0,46.188.0"}
P.entries["item:hardened-tumor"] = {n="Твердая опухоль",s="Твердая опухоль — редкая биологическая аномалия, которую добывают у мурлоков клана Злобный Плавник, обитающих у озера Лордамер. Впервые упомянутый в исследованиях погибшего аптекаря Берара, этот окаменевший нарост служит необычным реагентом в стараниях Королевского фармацевтического общества создать Новую чуму.",h="Твердая опухоль — редкая биологическая аномалия, которую добывают у мурлоков клана Злобный Плавник, обитающих...",kw={"apothecary faranell","apothecary renferrel","berard","dawning isles","hardened tumor","lake lordamere","murloc","new plague","vile fin","аптекарь фаранелл","аптекарь ренферрел","берар","рассветные острова","твердая опухоль","озеро лордамер","мурлок","новая чума","злобный плавник"},ang={["race:Undead"]="Добыча опухоли продвигает важнейшие исследования Мастера аптекаря Фаранелла над Новой чумой и служит леди Сильване и борьбе Отрекшихся против живых и мертвых врагов."},sec={{t="Редкая биологическая аномалия",b="Изучая местных животных на восточных границах Серебряного бора, аптекарь Берар описал необычный окаменевший нарост, развивающийся у мурлоков Злобного Плавника с озера Лордамер. Такие наросты крайне редки и встречаются только у взрослых особей на берегу и на Рассветных островах. Почему мурлоки Злобного Плавника образуют эти твердые массы, остается неясным, но их плотная болезненная ткань сразу привлекла внимание Королевского фармацевтического общества."},{t="Топливо для Новой чумы",b="После безвременной гибели Берара его полевые записи нашел в Гробнице аптекарь Ренферрел. Осознав потенциал работы Берара, Ренферрел поручил агентам Отрекшихся добыть Твердую опухоль и местные водные мхи. Мастер аптекарь Фаранелл руководит Апотекариумом в Подгороде и ищет реагенты, способные противостоять распаду или изменять живую материю. Он включил этот странный нарост прямо в продолжающееся создание Новой чумы Обществом."}},faq={{q="Что такое Твердая опухоль?",a="Это ненормальная окаменевшая масса, которая редко образуется внутри мурлоков Злобного Плавника, живущих у озера Лордамер. Ее обнаружил исследователь из Отрекшихся аптекарь Берар. Она не поддается обычному физическому разрушению и обладает уникальными биологическими свойствами.",al={"what is this tumor","tumor lore","hardened tumor drop","что такое эта опухоль","предания об опухоли","твердая опухоль добыча"}},{q="Why does the Royal Apothecary Society want it?",a="Master Apothecary Faranell and the Royal Apothecary Society are gathering unusual toxic and biological specimens to synthesize the New Plague. The tumor's abnormal resilience and cellular composition make it a prime candidate for their blight experiments.",al={"why apothecary want tumor","recipe for death tumor use","faranell tumor","зачем аптекарям опухоль","рецепт смерти опухоль","фаранелл опухоль"}},{q="Где находят эти опухоли?",a="Их добывают у мурлоков Злобного Плавника в Серебряном бору, в частности у тех, что обитают на Рассветных островах в восточной части озера Лордамер и на берегах у деревни к северо-востоку от Янтарной мельницы.",al={"where to find hardened tumor","which murlocs drop tumor","tumor location","где найти твердую опухоль","какие мурлоки дают опухоль","где опухоль"}},{q="Кем был аптекарь Берар?",a="Berard was an apothecary of the Royal Apothecary Society stationed in Silverpine Forest. Before his death, he compiled detailed research on local flora, fauna, and murloc mutations, uncovering the utility of the Dawning Isles' mosses and hardened tumors.",al={"who is berard","berard lore","berard journal","кто такой берар","предания о бераре","журнал берара"}}},fp="14,296,25.495.0,23.497.1,25.245.0,46.255.0,29.183.0,26.254.0"}
P.entries["item:harpy-lieutenant-ring"] = {n="Кольцо Лейтенанта гарпий",s="Кольца Лейтенанта гарпий — грубые украшения, которые носят Убийцы Зачарованного Крыла в Сухих холмах на севере Степей. Их носят как знак власти в стае, и они служат доказательством смерти для Дарсока Быстрого Ножа на Перекрестке.",h="Кольца Лейтенанта гарпий — грубые украшения, которые носят Убийцы Зачарованного Крыла в Сухих холмах на...",kw={"crossroads","darsok swiftdagger","dry hills","harpy lieutenant ring","the barrens","witchwing","witchwing slayer","перекресток","дарсок быстрый нож","сухие холмы","кольцо лейтенанта гарпий","степи","зачарованное крыло","убийца зачарованного крыла"},ang={["class:Rogue"]="Дарсок Быстрый Нож предпочитает точные удары по важным целям и ценит убийц, способных проникнуть в гнезда гарпий и устранить командиров напрямую.",["faction:Horde"]="Гарпии Зачарованного Крыла постоянно нападают на пути снабжения между Дуротаром, Мулгором и северными аванпостами; уничтожив их командование, Орда обеспечит безопасный проход караванам через Степи."},sec={{t="Знаки отличия",b="В матриархальной иерархии гарпий Зачарованного Крыла ранг поддерживается безжалостно. Рядовые налетчики, тревожащие Степи, сражаются почти без согласованности, а Убийцы Зачарованного Крыла служат полевыми лейтенантами и руководят нападениями на путников Орды. Чтобы выделиться и утвердить власть над подчиненными, эти ветераны носят особые кольца. Для Дарсока Быстрого Ножа и защитников Перекрестка снять такие кольца с павших гарпий — единственный верный способ убедиться, что среднее звено руководства стаи сломлено."}},faq={{q="Кто носит эти кольца?",a="Кольца носят именно Убийцы Зачарованного Крыла — опытные гарпии, служащие лейтенантами в стае Зачарованного Крыла в Сухих холмах.",al={"who drops harpy lieutenant ring","witchwing slayer rings","which harpies have rings","кто дает кольцо лейтенанта гарпий","кольца убийц зачарованного крыла","у каких гарпий есть кольца"}},{q="Где можно найти Убийц Зачарованного Крыла?",a="Убийцы Зачарованного Крыла гнездятся в Сухих холмах — скалистой возвышенной местности на дальнем севере Степей, к северо-западу от Перекрестка.",al={"witchwing slayer location","where are harpy lieutenants","dry hills harpies","где убийцы зачарованного крыла","где лейтенанты гарпий","гарпии сухих холмов"}},{q="Зачем они нужны Дарсоку Быстрому Ножу?",a="Дарсок хочет разрушить систему командования гарпий. Уничтожение лейтенантов вносит хаос в их отряды налетчиков и наказывает стаю за нападения на караваны и путников Орды по всем Степям.",al={"why collect harpy rings","darsok swiftdagger rings","зачем собирать кольца гарпий","кольца дарсока быстрого ножа"}},{q="Носят ли такие кольца обычные налетчики-гарпии?",a="Нет. Обычные налетчики — подчиненные низкого ранга. Кольца означают власть, и их носят только Убийцы Зачарованного Крыла.",al={"can raiders drop rings","do witchwing raiders have rings","падают ли кольца с налетчиков","есть ли кольца у налетчиков зачарованного крыла"}}},fp="21,232,14.579.0,24.145.0,37.154.0,38.212.0,43.118.0"}
P.entries["item:head-of-arugal"] = {n="Голова Аругала",s="Голова Аругала — жуткий трофей, снятый с безумного верховного мага на вершине Крепости Темного Клыка. Доставленная Отрекшимся в Гробнице, она служит неоспоримым доказательством гибели повелителя местных воргенов.",h="Голова Аругала — жуткий трофей, снятый с безумного верховного мага на вершине Крепости Темного Клыка.",kw={"arugal","arugal must die","dalar dawnweaver","head of arugal","sepulcher","shadowfang keep","silverpine","аругал","смерть аругалу","далар ткач рассвета","голова аругала","гробница","крепость темного клыка","серебряный бор"},ang={["class:Mage"]="Отрубленная голова бывшего верховного мага Кирин-Тора — суровое предостережение о безумии и крахе, которые неудержимые отчаянные призывы могут принести даже одаренным заклинателям.",["race:Undead"]="Для Отрекшихся доставка головы Аругала означает устранение опасного чародея на их южном пороге и обеспечивает Темной Госпоже власть над Серебряным бором."},sec={{t="Трофей безумного верховного мага",b="Верховный маг Аругал давно отбрасывает мрачную тень на Серебряный бор, командуя волчьими чудовищами со стен Крепости Темного Клыка. Добыть его отрубленную голову — главное поручение Далара Ткача Рассвета в Гробнице. Для Отрекшихся голова — не просто жуткий знак: она означает устранение сильного заклинателя, чьи дикие звери мешали леди Сильване полностью овладеть Серебряным бором. Передав ее Ткачу Рассвета, вы подтвердите, что скверное колдовство отступника-мага наконец отсечено от этой земли."}},faq={{q="Кому нужна Голова Аругала?",a="Далар Ткач Рассвета, посланник в Гробнице в Серебряном бору, требует голову в рамках задания «Смерть Аругалу!».",al={"who needs arugals head","arugal head turn in","who takes head of arugal","кому нужна голова аругала","сдать голову аругала","кто принимает голову аругала"}},{q="Где получить Голову Аругала?",a="Ее отсекают у самого верховного мага Аругала, обитающего на высочайшей вершине Крепости Темного Клыка над Деревней Погребальных Костров и лесами Серебряного бора.",al={"how to get arugals head","arugal head drop","where is arugal's head","как получить голову аругала","голова аругала добыча","где голова аругала"}},{q="Почему Отрекшиеся хотят смерти Аругала?",a="Присутствие Аругала и его стаи диких воргенов мешает Отрекшимся закрепиться в Серебряном бору как в безопасном стратегическом оплоте для леди Сильваны и Подгорода.",al={"why kill arugal","forsaken arugal reason","why does dalar want arugal dead","зачем убивать аругала","причина отрекшихся убить аругала","почему далар хочет смерти аругала"}},{q="Что происходит после сдачи головы?",a="Далар Ткач Рассвета клянется истребить остатки скверных чар Аругала и заявляет, что Серебряный бор наконец освобожден из тисков безумного чародея.",al={"after arugal dies","result of arugal must die","после смерти аругала","итог задания смерть аругалу"}}},fp="14,209,26.535.0,29.134.0,39.153.0,37.167.0,41.143.1"}
P.entries["item:head-of-bazil-thredd"] = {n="Голова Базиля Тредда",s="Отрубленная голова Базиля Тредда — неоспоримое доказательство того, что вожак мятежа в Тюрьме уничтожен. Эту мрачную добычу требует Тюремщик Телвотер; она означает конец организованной власти Братства Справедливости над подземной тюрьмой Штормграда.",h="Отрубленная голова Базиля Тредда — неоспоримое доказательство того, что вожак мятежа в Тюрьме уничтожен.",kw={"bazil thredd","defias","hamhock","head of bazil thredd","stockade","the stockade riots","warden thelwater","базиль тредд","братство справедливости","хрупконог","голова базиля тредда","тюрьма","бунты в тюрьме","тюремщик телвотер"},ang={["faction:Alliance"]="Предъявление отрубленной головы Тредда гасит панику в столице и доказывает, что правосудие короны способно достать даже в глубины мятежной Тюрьмы."},sec={{t="Доказательство конца измены",b="Когда по всей Тюрьме под Штормградом вспыхнули бунты, Базиль Тредд быстро утвердился как вдохновитель мятежа. Укрывшись в своем блоке вместе с огром-телохранителем Хрупконогом, Тредд руководил хаосом из глубин подземелья. Не доверяя чужакам и с трудом удерживая порядок, Тюремщик Телвотер потребовал голову Тредда как бесспорное свидетельство его гибели и как проверку истинной верности искателя приключений Штормграду."}},faq={{q="Кому нужна Голова Базиля Тредда?",a="Голову требует Тюремщик Телвотер, стоящий у входа в Тюрьму. Ему нужно неоспоримое доказательство гибели главаря, прежде чем он согласится поделиться сведениями о сообщниках Тредда.",al={"who needs thredd head","where to turn in thredd head","thredd head questgiver","кому нужна голова тредда","куда сдать голову тредда","кто выдает задание голова тредда"}},{q="Кем был Базиль Тредд?",a="Базиль Тредд был высокопоставленным членом Братства Справедливости, заключенным под Штормградом. Когда заключенные подняли бунт, он возглавил мятеж и координировал восстание из глубин восточного блока камер.",al={"who is bazil thredd","thredd lore","what did bazil do","кто такой базиль тредд","предания о тредде","что сделал базиль"}},{q="Где находится Базиль Тредд?",a="Базиль Тредд находится в восточном крыле подземелья Тюрьма. Он заперт в центральной камере в дальнем конце блока, и его охраняет огр по имени Хрупконог.",al={"where is thredd","thredd location","how to find bazil thredd","где тредд","местонахождение тредда","как найти базиля тредда"}}},fp="20,269,22.467.0,35.222.0,21.222.0,28.168.0"}
P.entries["item:head-of-deepfury"] = {n="Голова Гневливого",s="Отрубленная голова Кама Гневливого — мрачное доказательство того, что заговорщик из клана Черного Железа, стоявший за разрушением Моста Тандола, мертв. Убитый во время бунта в Тюрьме Штормграда, он расплатился за личную месть дворфов-защитников Дун Модра.",h="Отрубленная голова Кама Гневливого — мрачное доказательство того, что заговорщик из клана Черного Железа...",ang={["faction:Alliance"]="Эта награда показывает растущее трение внутри Альянса: осторожность человеческого правосудия в Штормграде противопоставлена суровому пограничному правосудию, которого требуют горцы Стальгорна.",["race:Dwarf"]="Для дворфов Стальгорна голова Гневливого — вопрос чистого правосудия клана: она погашает кровный долг за предательство Черного Железа на Мосту Тандола."},sec={{t="Правосудие для заговорщика",b="Kam Deepfury was arrested and locked away in the Stormwind Stockade for political reasons, spared from immediate execution by human diplomatic bureaucracy. To the Ironforge mountaineers stationed at Dun Modr, this restraint was unacceptable. Intelligence uncovered by Roggo revealed that Deepfury orchestrated the devastating attack on the Thandol Span—an assault that cost the lives of King Magni's soldiers and the kin of Longbraid the Grim. Bound by duty to remain at his post, Motley Garmason commissioned Alliance champions to infiltrate the rioting prison and claim Deepfury's head, ensuring true dwarven vengeance was delivered where human diplomacy faltered."}},faq={{q="Кем был Кам Гневливый?",a="Кам Гневливый был вероломным дворфом из клана Черного Железа, помогавшим планировать разрушение Моста Тандола — важнейшего сухопутного моста между Болотиной и Нагорьем Арати. Его заговор привел к гибели дворфов-защитников, в том числе брата Длиннокоса Мрачного.",al={"kam deepfury lore","who is deepfury","kam deepfury backstory","предания о каме гневливом","кто такой гневливый","история кама гневливого"}},{q="Почему Кама Гневливого держали в Тюрьме, а не казнили?",a="Власти Штормграда держали Гневливого живым по политическим причинам. Пока человеческая волокита мирилась с тем, что он гниет в камере, горцы Стальгорна сочли эту снисходительность возмутительной и потребовали крови.",al={"why was deepfury imprisoned","why stockade","почему гневливый в тюрьме","почему тюрьма"}},{q="Кому нужна Голова Гневливого?",a="Motley Garmason, a dwarf stationed at Dun Modr in the northern Wetlands, requests the head. Bound by honor to remain at his post beside Longbraid the Grim, Motley sends an adventurer to finish what he cannot do himself.",al={"who takes deepfury head","fury runs deep turn in","кто принимает голову гневливого","сдать голову гневливого"}},{q="Что дает возвращение головы?",a="Предъявление отрубленной головы Гневливого приносит утешение и справедливость скорбящим семьям дворфов в Дун Модре. Оно мстит за убитого брата Длиннокоса Мрачного и показывает, что преступления против Стальгорна не будут похоронены под политическими уловками людей.",al={"why bring deepfury head","fury runs deep result","зачем нести голову гневливого","итог задания голова гневливого"}}},fp="16,263,23.668.0,21.275.0,57.231.0,31.219.0,44.261.0"}
P.entries["item:head-of-gath-ilzogg"] = {n="Голова Гат'Илзогга",s="Отрубленная голова Гат'Илзогга служит неопровержимым доказательством того, что полководец клана Черной горы убит. Ее добыча лишает осаду Крепости Каменной Стражи руководства и приносит отчаянное облегчение городку Приозерье.",h="Отрубленная голова Гат'Илзогга служит неопровержимым доказательством того, что полководец клана Черной горы...",kw={"blackrock","gath'ilzogg","lakeshire","magistrate solomon","redridge","stonewatch","stonewatch keep","клан черной горы","гат'илзогг","приозерье","мировой судья соломон","красногорье","водопад каменной стражи","крепость каменной стражи"},ang={["faction:Alliance"]="Пока столица занята внутренними распрями, добровольцам Альянса приходится самим брать на себя защиту Красногорья и расправу с вождями клана Черной горы.",["race:Human"]="Для жителей Штормграда победа над Гат'Илзоггом — месть за убийство невинных поселенцев и позорное падение Крепости Каменной Стражи."},sec={{t="Полководец с наградой за голову",b="Гат'Илзогг организовал жестокое нападение Черной горы, захватившее Крепость Каменной Стражи, изгнавшее ее защитников и подвергшее окрестную долину непрерывным набегам. Когда Приозерье было на грани гибели, а Штормград почти не присылал подкреплений, Мировой судья Соломон назначил награду за голову вождя. Убийство Гат'Илзогга на укрепленных верхних уровнях Каменной Стражи и взятие его головы сокрушает местное руководство Черной горы и становится первым реальным шагом к возвращению крепости королевству."}},faq={{q="Кем был Гат'Илзогг?",a="Гат'Илзогг был могущественным орком-полководцем клана Черной горы, который возглавил захват Крепости Каменной Стражи и направлял набеги на поселения Красногорья, доведя Приозерье до грани краха.",al={"who is gath'ilzogg","gathilzogg lore","stonewatch boss","кто такой гат'илзогг","гат'илзогг предыстория","босс каменной стражи"}},{q="Куда нужно отнести голову после того, как ее добудут?",a="Голову относят прямо Мировому судье Соломону в ратушу Приозерья как доказательство того, что награда, объявленная на городской доске объявлений о розыске, заслужена.",al={"who wants the head","turn in gath'ilzogg head","magistrate solomon bounty","кому нужна голова","сдать голову гат'илзогга","награда мирового судьи соломона"}},{q="Что смерть Гат'Илзогга значит для Приозерья?",a="Его смерть лишает захватчиков из Черной горы главного тактика в Красногорье. Хотя много орков Черной горы все еще окопались в Каменной Страже, разрыв их цепи командования дает местной обороне шанс удержать область.",al={"does lakeshire get saved","significance of killing gath'ilzogg","спасено ли приозерье","значение смерти гат'илзогга"}},{q="Где находился Гат'Илзогг?",a="Он занимал верхние ярусы Крепости Каменной Стражи, укрывшись в глубине захваченного укрепления вместе с личными телохранителями и помощниками.",al={"where is gathilzogg","stonewatch keep location","где гат'илзогг","расположение крепости каменной стражи"}}},fp="19,227,18.530.0,20.206.0,39.154.0,49.233.0,28.147.0"}
P.entries["item:head-of-grimson"] = {n="Голова Мрачнона",ang={["race:Undead"]="Захват рудника исполняет стратегические приказы верховного командования Подгорода и доказывает решимость Отрекшихся вернуть жизненно важную инфраструктуру Лордерона у обезумевших остатков."},sec={{t="Securing the Deep Elem Mine",b="While Dalar Dawnweaver studies Archmage Arugal's shadowy enchantments from the safety of the Sepulcher, Forsaken scouts known as Darkstalkers identified a strategic threat brewing in the southeastern hills. Arugal's dark magic had seeped into the Deep Elem Mine, corrupting its workers and driving its overseer, Grimson the Pale, into madness. To secure the subterranean riches for Varimathras's forces, Dawnweaver dispatched champions to cut down Grimson and return with his severed head as undeniable confirmation of the mine's liberation from rogue magics."},{t="Трофей для повелителя ужаса",b="For the Forsaken, grim trophies of war carry pragmatic weight. Claiming the head of Grimson ensures that the subterranean workforce in the Deep Elem Mine is entirely broken, ending any lingering allegiance to Arugal's twisted reign. With Grimson eliminated, the rich mineral veins within the mine can be extracted and reforged into weapons and armor, sustaining the ongoing Forsaken advance across Silverpine Forest and the neighboring reaches of Lordaeron."}},faq={{q="Кем был Мрачнон Белесый?",a="Grimson the Pale was the overseer of the Deep Elem Mine located in the southeastern hills of Silverpine Forest. Exposed to Archmage Arugal's spreading shadow magic, Grimson and his fellow miners fell under its dark sway, transforming the mine into a corrupted stronghold until the Forsaken intervened.",al={"who is grimson","grimson the pale lore","grimson background","кто такой мрачнон","мрачнон белесый","предыстория мрачнона"}},{q="Зачем Далару Ткачу Рассвета нужна голова Мрачнона?",a="Dalar Dawnweaver needs concrete proof that the corrupted foreman has been permanently eliminated. Varimathras desires the Deep Elem Mine's mineral wealth for the Forsaken war effort, and killing Grimson breaks the resistance of the corrupted miners holding the tunnels.",al={"why dalar wants head","head of grimson purpose","why take head","зачем далар голова","голова мрачнона зачем","зачем брать голову"}},{q="Where is the Deep Elem Mine located?",a="The Deep Elem Mine is situated in the hills to the southeast of the Sepulcher in Silverpine Forest. It serves as a vital mineral cache contested by the Forsaken and the corrupted remnants subjected to Arugal's magic.",al={"where is deep elem mine","grimson location","mine location silverpine"}},{q="Какую роль Вариматрас играет в этом задании?",a="Varimathras serves as the military overseer directing Forsaken expansion across Lordaeron from the Undercity. Securing the resources of the Deep Elem Mine directly serves his strategic goals, providing raw materials to fuel his growing war machine in Silverpine.",al={"varimathras role","why does varimathras want mine","varimathras silverpine"}}},fp="15,372,27.559.0,26.457.1,25.301.0,46.269.0,36.216.0,45.262.0"}
P.entries["item:head-of-kelris"] = {n="Голова Келриса",s="Отрубленная голова Повелителя сумрака Келриса — неоспоримое доказательство гибели предводителя Сумеречного Молота в Непроглядной Пучине. Ее вынесли из оскверненных руин храма, и ею интересуются представители Серебряного Рассвета, чтобы убедиться в конце его богомерзких ритуальных жертвоприношений.",h="Отрубленная голова Повелителя сумрака Келриса — неоспоримое доказательство гибели предводителя Сумеречного...",kw={"aku'mai","argent dawn","bashana runetotem","blackfathom deeps","blackfathom villainy","head of kelris","selgorm","twilight lord kelris","аку'май","серебряный рассвет","башана рунический тотем","непроглядная пучина","голова келриса","селгорм","повелитель сумрака келрис"},ang={["faction:Alliance"]="Доставка головы Келриса Рассветному дозорному Селгорму в Дарнасс мстит за осквернение древнего храма ночных эльфов, посвященного Элуне.",["faction:Horde"]="Передача головы Башане Рунический Тотем в Громовом Утесе завоевывает доверие Круга Кенария и доказывает преданность Орды очищению Калимдора от скверны."},sec={{t="Трофей разрушения",b="В затопленных глубинах погруженного храма Элуны Повелитель сумрака Келрис устраивал темные жертвоприношения Аку'май, чудовищной питомице Древних богов. Добыча его головы означает конец его тиранического правления над сумеречными культистами и их союзниками-нагами в пещере. Жуткий трофей нужно доставить в обитаемые земли, чтобы заверить правителей, что кровавые обряды Келриса наконец прекратились."},{t="Доказательство для Рассвета",b="Несколько месяцев Серебряный Рассвет считал Келриса мертвым или пропавшим, но его зловещее влияние вновь проявилось вместе с наступающими тенями Калимдора. Когда голову предъявляют агентам в Дарнассе или Громовом Утесе, она закрывает невыполненные заказы на его поимку и подтверждает, что его попытки вернуть мир в первобытный хаос сорваны."}},faq={{q="Кем был Повелитель сумрака Келрис?",a="Келрис был предводителем секты Сумеречного Молота, обосновавшейся в Непроглядной Пучине. В союзе с нагами он устраивал ритуальные жертвоприношения невинных, чтобы накормить Аку'май, гидру-слугу Древнего бога, в поисках темной силы и древнего хаоса.",al={"who is kelris","kelris lore","twilight lord kelris","кто такой келрис","келрис предыстория","повелитель сумрака келрис"}},{q="Кому нужна Голова Келриса?",a="Бойцы Альянса относят голову Рассветному дозорному Селгорму в Дарнасс, а искатели приключений Орды приносят ее Башане Рунический Тотем на Вершину Старейшин в Громовом Утесе. Рассветный дозорный Селгорм служит Серебряному Рассвету, а Башана Рунический Тотем принадлежит к Кругу Кенария.",al={"who takes kelris head","head of kelris turn in","who do i give kelris head to","кто принимает голову келриса","сдать голову келриса","кому отдать голову келриса"}},{q="Почему Серебряный Рассвет интересуется Келрисом?",a="Серебряный Рассвет выслеживает зловещие угрозы Азероту. Келрис был известным злодеем, долго ускользавшим от них, а его поклонение Древним богам и жертвоприношения невинных создавали страшную угрозу равновесию Калимдора.",al={"why argent dawn kelris","argent dawn blackfathom","почему серебряный рассвет келрис","серебряный рассвет непроглядная пучина"}},{q="Где добывается голова?",a="Ее отсекают от тела Повелителя сумрака Келриса в его святилище в подземелье Непроглядная Пучина, расположенном под Зорамским взморьем на побережье Ясеневого леса.",al={"where to get kelris head","kelris head location","где взять голову келриса","где голова келриса"}}},fp="14,294,16.422.0,18.339.0,29.249.0,29.262.0,43.224.0,27.173.0"}
P.entries["item:head-of-targorr"] = {n="Голова Таргорра",s="Голова Таргорра — мрачное доказательство, которого требует Стражник Бертон в Приозерье, чтобы подтвердить гибель Таргорра Ужасного. Бывший главный палач полководца клана Черной горы Гат'Илзогга в Красногорье, плененный орк был приговорен к смерти в Тюрьме Штормграда, но подозрительное политическое вмешательство остановило казнь.",h="Голова Таргорра — мрачное доказательство, которого требует Стражник Бертон в Приозерье, чтобы подтвердить...",kw={"blackrock","gath'ilzogg","guard berton","head of targorr","lakeshire","redridge","stockade","targorr","targorr the dread","клан черной горы","гат'илзогг","стражник бертон","голова таргорра","приозерье","красногорье","тюрьма","таргорр","таргорр ужасный"},ang={["faction:Alliance"]="Для бойцов Альянса, защищающих Красногорье, победа над Таргорром мстит за убитых защитников Приозерья и обходит продажную знатную бюрократию Штормграда.",["race:Human"]="Солдаты и городская стража людей питают к Таргорру личную ненависть за садистские пытки захваченных королевских воинов во время наступления клана Черной горы."},sec={{t="Отложенная казнь",b="Таргорр Ужасный стал печально известен в Красногорье как жестокий палач на службе полководца клана Черной горы Гат'Илзогга. Он пытал и убивал защитников Королевства Штормград, был в итоге схвачен и приговорен к смерти в Тюрьме Штормграда. Однако бюрократическое вмешательство штормградской знати загадочным образом приостановило приговор, и местные стражники, например Бертон, заподозрили в столице нечистую игру и коррупцию."},{t="Правосудие на границе",b="Опасаясь, что Таргорра используют как политическую пешку или он каким-то образом организует побег, Стражник Бертон поручил стороннему бойцу проникнуть в неспокойную тюрьму и сделать то, что отложили суды. Отсечение головы Таргорра обошло парализованную судебную систему и принесло успокоение скорбящим семьям и осажденным защитникам Приозерья, страдавшим от клинков палача."}},faq={{q="Кем был Таргорр Ужасный?",a="Таргорр был печально известным орком-палачом клана Черной горы в Красногорье. Служа полководцу Гат'Илзоггу, он прославился пытками и казнями захваченных солдат и защитников Штормграда.",al={"targorr","targorr lore","who is targorr","таргорр","таргорр предыстория","кто такой таргорр"}},{q="Почему Таргорра держали живым в Тюрьме?",a="Хотя Таргорра формально приговорили к смерти, его казнь загадочным образом остановили бюрократы из штормградской знати. Стражники Приозерья подозревают политические интриги и коррупцию, опасаясь, что орка берегли как разменную монету.",al={"why not execute targorr","targorr stay of execution","stockade trial","почему не казнили таргорра","отсрочка казни таргорра","суд в тюрьме"}},{q="Кому нужна голова Таргорра?",a="Голову требует Стражник Бертон, стоящий на мосту в Приозерье. Видев бойню, устроенную Таргорром в Красногорье, Бертон хочет неопровержимо убедиться, что палач никогда не выйдет на свободу.",al={"who takes targorr head","guard berton","turn in head of targorr","кто принимает голову таргорра","стражник бертон","сдать голову таргорра"}},{q="Где находится Таргорр?",a="Таргорр Ужасный заключен в Тюрьме Штормграда и сидит за железными решетками в центральных блоках камер среди бунтующих заключенных.",al={"targorr location","find targorr","where in stockade","где таргорр","найти таргорра","где в тюрьме"}}},fp="15,337,19.477.0,16.395.0,26.214.0,43.236.0,25.215.0,23.138.0"}
P.entries["item:head-of-vancleef"] = {n="Голова ван Клифа",s="Отрубленная голова Эдвина ван Клифа — мрачное неопровержимое доказательство того, что предводитель Братства Справедливости пал. Ее принесли из глубин Мертвых копей на Сторожевой холм, и она стала символом нелегко доставшейся мести Народного ополчения.",h="Отрубленная голова Эдвина ван Клифа — мрачное неопровержимое доказательство того, что предводитель Братства...",kw={"deadmines","edwin vancleef","gryan stoutmantle","head of vancleef","peoples militia","sentinel hill","westfall","мертвые копи","эдвин ван клиф","гриан камнегрив","голова ван клифа","народное ополчение","сторожевой холм","западный край"},ang={["class:Rogue"]="Эдвин ван Клиф был одним из самых смертоносных мастеров-разбойников в истории людей; его голова означает окончательный конец непревзойденной карьеры в тенях и диверсиях.",["faction:Alliance"]="Вручение головы ван Клифа — исцеляющая победа Народного ополчения, хотя она подчеркивает тревожное отсутствие Дома знати Штормграда в самый темный час Западного Края."},sec={{t="Доказательство падения главаря",b="Несколько месяцев Эдвин ван Клиф руководил террором Братства Справедливости из самого дальнего убежища Мертвых копей, защищенный тяжеловооруженными разбойниками, гоблинскими инженерами и огромным боевым джаггернаутом. Одних слов никогда не хватило бы, чтобы убедить измученных поселенцев Западного Края, что кошмар окончен. Гриан Камнегрив, предводитель Народного ополчения, потребовал неопровержимых вещественных доказательств, прежде чем объявлять округу безопасной. Отрубленная голова главаря, принесенная на дневной свет, дает измотанным защитникам ощутимую уверенность, что главный виновник их бед больше никогда не будет угрожать Западному Краю."},{t="Мрачная победа",b="Хотя Камнегрив добивался смерти ван Клифа ради блага Западного Края, вручение такого трофея исполнено тяжелой торжественности. Когда-то ван Клиф был уважаемым мастером-строителем, отстроившим Штормград после Первой войны, пока предательство и неоплаченные долги не толкнули его и Гильдию каменщиков на мятеж вне закона. Его отрубленная голова завершает кампанию местного ополчения Западного Края, но и обнажает неспособность королевства справиться с собственными внутренними смутами: высшее правосудие вершат добровольцы-фермеры и чужеземные искатели приключений."}},faq={{q="Кому нужна голова ван Клифа?",a="Гриан Камнегрив, капитан Народного ополчения на Сторожевом холме в Западном Крае, требует голову, чтобы завершить долгую кампанию против Братства Справедливости.",al={"who do i turn this into","who takes vancleef head","where does vancleef head go","кому сдать голову","кто принимает голову ван клифа","куда отнести голову ван клифа"}},{q="Почему Гриан Камнегрив требует именно его голову?",a="Братство Справедливости так долго держало Западный Край в тисках, что слухам о гибели ван Клифа без неопровержимых доказательств никто бы не поверил. Камнегриву нужно явное свидетельство, чтобы успокоить измученных фермеров и показать, что борьба ополчения не была напрасной.",al={"why take his head","why vancleef head","зачем нужна голова","почему голова ван клифа"}},{q="Где добыть голову?",a="Ее забирают у Эдвина ван Клифа на борту его тайного броненосного военного корабля в самом конце Мертвых копей под Луноречьем на юго-западе Западного Края.",al={"where to get vancleef head","how to get head of vancleef","где взять голову ван клифа","как получить голову ван клифа"}},{q="Положит ли конец Братству Справедливости то, что голову ван Клифа забрали?",a="Камнегрив считает его смерть началом конца братства, но отколовшиеся группы, разбойники-одиночки и сочувствующие все еще скрываются в Западном Крае, Элвиннском лесу и за их пределами.",al={"is defias destroyed","what happens to the defias","уничтожены ли defias","что будет с братством справедливости"}}},fp="16,248,26.610.0,14.535.1,31.148.0,56.283.0,27.150.0,55.190.0"}
P.entries["item:heart-of-isha-awak"] = {n="Сердце Иши Авака",s="Сердце Иши Авака взято у могучей молотилки по имени Иша Авак, Глубинный Рок Торгового побережья. Его ищет таурен-провидец Марен Небесная Провидица как доказательство победы над одним из самых грозных хищников океана.",h="Сердце Иши Авака взято у могучей молотилки по имени Иша Авак, Глубинный Рок Торгового побережья.",kw={"deep doom","heart of isha awak","isha awak","mahren skyseer","merchant coast","ratchet","the barrens","глубинный рок","сердце иши авака","иша авак","марен небесная провидица","торговое побережье","кабестан","степи"},ang={["class:Hunter"]="Выследить и победить Глубинный Рок в волнах Торгового побережья — высшее испытание мужества охотника перед водной добычей.",["race:Tauren"]="Для таурен-охотников погоня за Ишей Авак — акт духовного единения с самыми свирепыми хищниками природы по наставлению старейшины Марен Небесной Провидицы."},sec={{t="Трофей Глубинного Рока",b="У залитых солнцем берегов Торгового побережья к югу от Кабестана обитает Иша Авак — огромный морской зверь, которого почитают и боятся моряки и жители побережья. Это существо, известное как Глубинный Рок, погубило немало людей, забредших на берег. Но для мистика Марен Небесной Провидицы зверь — скорее достойный хищник, чем бездумная угроза. Она верит, что яростный дух Иши Авака живет в его сердце, и призывает храбрых охотников нырнуть в волны, одолеть зверя в его стихии и добыть пульсирующий орган как трофей и духовное подношение."}},faq={{q="Что такое Сердце Иши Авака?",a="Это сердце Иши Авак, гигантской водной молотилки, рыскающей в прибрежных водах к югу от Кабестана. Его берут как доказательство убийства зверя для таурена-мистика Марен Небесной Провидицы.",al={"heart of isha awak","isha awak heart","what is this heart","сердце иши авака","сердце иша авак","что за сердце"}},{q="Кому нужно Сердце Иши Авака?",a="Марен Небесная Провидица, таурен-провидец, стоящая лагерем на Торговом побережье к югу от Кабестана, просит охотников принести сердце, чтобы почтить силу зверя и впитать его дух.",al={"who takes the heart","who do i give the heart to","mahren skyseer","кто принимает сердце","кому отдать сердце","марен небесная провидица"}},{q="Где находится Иша Авак?",a="Иша Авак обитает в океанских водах у Торгового побережья в восточных Степях и плавает к югу от гоблинского порта Кабестан.",al={"isha awak location","where is isha awak","where to find isha awak","где иша авак","местонахождение иши авака","где найти иша авака"}},{q="Зачем Марен Небесной Провидице сердце?",a="Марен считает Ишу Авак достойным охотником и противником. Убив зверя и завладев его сердцем, охотник принимает в себя дух морского создания.",al={"why kill isha awak","why does mahren want the heart","зачем убивать иша авака","зачем марен сердце"}}},fp="18,234,23.610.0,31.182.0,33.164.0,25.129.0,39.172.0"}
P.entries["item:heartswood"] = {n="Сердцедрево",s="Сердцедрево — древесина священного дерева, растущего в Руинах Ордил'Арана на северо-западе Ясеневого леса. Оно выросло на месте последнего упокоения двух древних влюбленных, и его созвучие с бессмертной преданностью делает его необходимой приманкой для призыва суккуба.",h="Сердцедрево — древесина священного дерева, растущего в Руинах Ордил'Арана на северо-западе Ясеневого леса.",kw={"anathera","ashenvale","gakin the darkbinder","heartswood","latherion","ordil'aran","succubus","анатера","ясеневый лес","гакин темнопряд","сердцедрево","латерион","ордил'аран","суккуб"},ang={["class:Warlock"]="Для чернокнижников Альянса добыча Сердцедрева — важнейший обряд посвящения под руководством Гакина Темнопряда: оно дает эмоциональную приманку, нужную, чтобы подчинить суккуба-слугу.",["race:NightElf"]="Дерево — трагический священный памятник Войны Древних, поэтому его осквернение чернокнижниками и культистами — горькое оскорбление памяти павших предков."},sec={{t="Памятник преданности",b="Сердцедрево растет среди эльфийских камней Руин Ордил'Арана на северо-западе Ясеневого леса. По легенде, двое влюбленных, Анатера и Латерион, пали бок о бок в катастрофической Войне Древних тысячи лет назад. На самой земле, где они испустили последний вздох, укоренилось необычное дерево, расцветшее вечным свидетельством их преданности. Даже спустя тысячелетия древесина этого дерева гудит памятью о бессмертной страсти, вызывая огромный интерес у тех, кто изучает эмоциональные и духовные узы."},{t="Орудие подчинения",b="Хотя Сердцедрево рождено чистым чувством, оно привлекает мрачное внимание. Суккубов — демонов, питающихся страстью, тоской и эмоциональной эксплуатацией, — сильно влечет к предметам, наполненным подлинной бессмертной любовью. Люди и гномы-чернокнижники из учеников Гакина Темнопряда в Штормграде ищут эту редкую древесину, чтобы создать ритуальную приманку. Используя природное созвучие жертвы влюбленных, практик может заманить суккуба через Пустоту, втянуть ее в круг призыва и подчинить своей воле."}},faq={{q="Что такое Сердцедрево?",a="Сердцедрево — древесина дерева, проросшего в Руинах Ордил'Арана в Ясеневом лесу на месте, где вместе погибли двое древних влюбленных ночных эльфов во время Войны Древних.",al={"heartswood tree","what is heartswood","heartswood lore","дерево сердцедрево","что такое сердцедрево","предания о сердцедреве"}},{q="Кто такие Анатера и Латерион?",a="Анатера и Латерион были влюбленными, сражавшимися бок о бок в Войне Древних. Когда оба пали в бою, их последние объятия напитали землю, и выросло дерево Сердцедрево как вечный символ их преданности.",al={"anathera and latherion","lovers of heartswood","who died at heartswood","анатера и латерион","влюбленные сердцедрева","кто погиб у сердцедрева"}},{q="Зачем чернокнижникам Сердцедрево?",a="Суккубы — демонические создания желания и эмоциональных манипуляций. Поскольку Сердцедрево сильно созвучно сущности несокрушимой вечной любви, чернокнижники используют его как мощную психическую приманку, чтобы соблазнить суккуба и призвать его в физический мир.",al={"why do warlocks want heartswood","heartswood succubus","heartswood purpose","зачем чернокнижникам сердцедрево","сердцедрево суккуб","назначение сердцедрева"}},{q="Где найти Сердцедрево?",a="Сердцедрево находится в Руинах Ордил'Арана на северо-западе Ясеневого леса, близ границы Темных берегов.",al={"heartswood location","where is heartswood","ruins of ordil'aran heartswood","где сердцедрево","местонахождение сердцедрева","руины ордил'арана сердцедрево"}}},fp="10,260,22.556.0,21.537.1,19.192.0,32.238.0,32.254.0,30.141.0"}
P.entries["item:heartswood-core"] = {n="Сердцевина сердцедрева",s="Сердцевина сердцедрева — зачарованный ритуальный фокус, изготовленный из древесины древнего дерева. Ее выдает Гакин Темнопряд в Штормграде, и она направляет магию, необходимую, чтобы пронзить Круговерть Пустоты и призвать суккуба в магический круг призыва.",h="Сердцевина сердцедрева — зачарованный ритуальный фокус, изготовленный из древесины древнего дерева.",kw={"gakin the darkbinder","heartswood core","slaughtered lamb","stormwind","succubus","summoning circle","the binding","warlock","гакин темнопряд","сердцевина сердцедрева","забитый ягненок","штормград","суккуб","круг призыва","связывание","чернокнижник"},ang={["class:Warlock"]="Сердцевина сердцедрева — важнейшая учебная реликвия чернокнижников Альянса, инструмент, с помощью которого они призывают и подчиняют своего первого суккуба."},sec={{t="Фокус для Пустоты",b="В темных склепах под таверной «Забитый ягненок» в Квартале магов Штормграда чернокнижники проводят обряды вдали от глаз городской стражи. Сердцевина сердцедрева служит важнейшим магическим проводником для начала ритуала связывания. Изготовленная из собранного сердцедрева, она хранит достаточно остаточного магического созвучия, чтобы пронзить завесу между мирами. Направляя свои темные искусства через древесину у освященного круга призыва, посвящаемый может открыть проход в Круговерть Пустоты и принудить суккуба пересечь границу миров."},{t="Испытание связыванием",b="Призвать демона — лишь полдела; чтобы управлять им, нужно доказать полное превосходство над его хитрой и соблазнительной натурой. Гакин вверяет Сердцевину сердцедрева многообещающим ученикам, чтобы они сразились с призванным демоном. Суккубы охотятся на слабых и легко подавляют хилые умы, поэтому схватка становится смертельным испытанием. Лишь укротив демона и вернув Гакину израсходованную сердцевину, начинающий чернокнижник доказывает, что его воли хватит, чтобы подчинить слугу навсегда."}},faq={{q="Для чего используется Сердцевина сердцедрева?",a="Чернокнижники используют Сердцевину сердцедрева как ритуальный реагент, чтобы открыть портал у круга призыва под «Забитым ягненком». Этот портал вызывает суккуба из Круговерти Пустоты в наш мир, чтобы с ним можно было сразиться и подчинить его.",al={"what does heartswood core do","heartswood core use","purpose of heartswood core","что делает сердцевина сердцедрева","применение сердцевины сердцедрева","назначение сердцевины сердцедрева"}},{q="Кто выдает Сердцевину сердцедрева?",a="Ее выдает Гакин Темнопряд, мастер-чернокнижник, обучающий новичков в тайных катакомбах под таверной «Забитый ягненок» в Квартале магов Штормграда.",al={"where do i get heartswood core","who gives heartswood core","где взять сердцевину сердцедрева","кто дает сердцевину сердцедрева"}},{q="Где нужно использовать сердцевину?",a="Сердцевину нужно направлять в рунном круге призыва глубоко в склепах под «Забитым ягненком», далеко под улицами Штормграда.",al={"heartswood core location","where to summon succubus","где использовать сердцевину сердцедрева","где призвать суккуба"}},{q="Что происходит после завершения ритуала?",a="Призвав суккуба с помощью сердцевины, вы должны победить демона в бою, чтобы сломить его сопротивление. Когда он будет отправлен обратно в Пустоту, верните Сердцевину сердцедрева Гакину Темнопряду, чтобы узнать тайну управления демоном по своей воле.",al={"what do i do after summoning","turn in heartswood core","что делать после призыва","сдать сердцевину сердцедрева"}}},fp="15,258,22.573.0,20.527.1,37.232.0,33.169.0,28.151.0,42.241.0"}
P.entries["item:heavy-leaden-collection-phial"] = {n="Тяжелый свинцовый коллекционный фиал",s="Тяжелый свинцовый коллекционный фиал — экранированный сосуд для сбора проб, который выдает Оззи Триггервольт в Караносе. Он предназначен для безопасной откачки и хранения крайне нестабильных радиоактивных выделений мутантов в глубинах Гномрегана для текущих исследований по дезактивации.",h="Тяжелый свинцовый коллекционный фиал — экранированный сосуд для сбора проб, который выдает Оззи Триггервольт...",kw={"gnomeregan","hall of gears","heavy leaden collection phial","ozzie togglevolt","phial","radioactive fallout","the only cure is more green glow","гномреган","зал шестеренок","тяжелый свинцовый коллекционный фиал","оззи триггервольт","фиал","радиоактивные осадки"},ang={["race:Gnome"]="Каждая капля нестабильных осадков, собранная в фиал, — отчаянный шаг к возвращению Гномрегана и пониманию химического безумия, укравшего их дом."},sec={{t="Экранированный сосуд",b="The Heavy Leaden Collection Phial is a sampling vessel used to draw volatile residues from living, irradiated creatures in Gnomeregan. Containing this fallout is difficult, and collecting a suitable sample may take several attempts."},{t="В поисках лекарства",b="Оззи Триггервольт выдает фиал в рамках исследования, цель которого — обратить ужасные мутации, поражающие лепрогномов. Прежние образцы от наземных троггов были недостаточно сильны для химического анализа. Применяя свинцовый фиал на ядовитых тварях, таких как облученные слизи и сторожа в Зале Шестеренок, исследователи надеются выделить активные элементы токсичных осадков города и создать действенное противоядие."}},faq={{q="Для чего нужен Тяжелый свинцовый коллекционный фиал?",a="Он служит для откачки концентрированных радиоактивных выделений прямо из живых облученных существ в Гномрегане, давая исследователям в Караносе чистые образцы для опытов по дезактивации.",al={"what does this phial do","phial purpose","what is leaden phial","что делает этот фиал","назначение фиала","что такое свинцовый фиал"}},{q="Кто выдает Тяжелый свинцовый коллекционный фиал?",a="Его выдает гном-исследователь Оззи Триггервольт за пределами Караноса в Дун Мороге в рамках исследования по исцелению облученных и пораженных лепрогномов.",al={"who gives phial","where do i get phial","phial questgiver","кто дает фиал","где взять фиал","выдающий задание фиал"}},{q="Почему фиал сделан из тяжелого свинца?",a="It is described as a heavy leaden phial, but its precise construction is not explained. Ozzie warns that containing the radioactive fallout is difficult and that the sample will collapse quickly.",al={"why lead phial","why heavy lead","почему свинцовый фиал","почему тяжелый свинец"}},{q="У каких существ нужно брать пробы фиалом?",a="Его нужно применять на живых светящихся чудовищах в глубинах Гномрегана, таких как облученные слизи, сторожа и твари, бродящие по нижним уровням Зала Шестеренок.",al={"what do i use it on","target creatures","which monsters glow","на ком использовать","целевые существа","какие монстры светятся"}}},fp="29,264,17.232.0,17.434.0,51.196.0,47.155.0,36.195.0,47.180.0"}
P.entries["item:hezrul-s-head"] = {n="Голова Хэрзула",s="Голова Хэрзула — жуткий трофей, снятый с Хэрзула Кровавой Отметины, вождя кентавров Колкар, обитающих в Степях. Ее приносят Регтару Врата Смерти, что к западу от Перекрестка, и она служит неопровержимым доказательством того, что верховное руководство местных налетчиков пало.",h="Голова Хэрзула — жуткий трофей, снятый с Хэрзула Кровавой Отметины, вождя кентавров Колкар, обитающих в...",kw={"bloodmark","centaur","crossroads","deathgate","hezrul","kolkar","lushwater","regthar","кровавая отметина","кентавр","перекресток","врата смерти","хэрзул","колкар","цветущий оазис","регтар"},ang={["faction:Horde"]="Добыв голову вождя Колкар, Орда обеспечивает себе важные права на воду Цветущего оазиса и защищает путников, пересекающих засушливые Степи.",["race:Orc"]="Регтар Врата Смерти считает Колкар недисциплинированными головорезами, чью необузданную ярость легко одолеть орочьей боевой дисциплиной, и потому этот трофей — свидетельство истинной воинской чести."},sec={{t="Обезглавить Колкар",b="Кентавры Колкар жестко удерживают важнейшие оазисы в засушливых Степях, постоянно угрожая торговым путям Орды и молодым поселениям. Хэрзул Кровавая Отметина управляет своим кланом из Цветущего оазиса на юге. Регтар Врата Смерти, орк-ветеран, отвечающий за безопасность земель к западу от Перекрестка, понимает, что колкарам свойственна яростная злоба, но не хватает настоящей дисциплины. Требуя отрубленную голову Хэрзула, Регтар стремится разрушить структуру командования клана, ввергнуть уцелевших бойцов в смятение и ослабить их согласованные нападения на Орду."}},faq={{q="Кому принадлежит эта голова?",a="Голова принадлежит Хэрзулу Кровавой Отметине, жестокому и хитрому предводителю клана кентавров Колкар, наводнившего центральные Степи.",al={"who is hezrul","hezrul identity","whose head is this","кто такой хэрзул","личность хэрзула","чья это голова"}},{q="Где найти Хэрзула Кровавую Отметину?",a="Хэрзул командует своей бандой у Цветущего оазиса, расположенного к югу от Перекрестка в Степях.",al={"hezrul location","where is hezrul","find hezrul","где хэрзул","местонахождение хэрзула","найти хэрзула"}},{q="Кому нужна Голова Хэрзула?",a="Регтар Врата Смерти, орк, находящийся на военной заставе у дороги к западу от Перекрестка, требует голову как доказательство поражения вождя.",al={"turn in hezrul head","who takes hezrul head","regthar deathgate","сдать голову хэрзула","кто принимает голову хэрзула","регтар врата смерти"}},{q="Почему Орде нужна его голова, а не просто его изгнание?",a="Орде нужна полная уверенность, что Хэрзул мертв. Кентавры по природе непостоянны и склонны к междоусобицам; устранение верховного вождя разрушает их командную структуру и снижает общую угрозу для Перекрестка.",al={"why kill hezrul","why take his head","centaur threat","зачем убивать хэрзула","зачем брать его голову","угроза кентавров"}}},fp="13,266,23.614.0,29.125.0,32.101.0,24.150.0,69.239.0"}
P.entries["item:high-potency-radioactive-fallout"] = {n="Высокомощные радиоактивные осадки",s="Высокомощные радиоактивные осадки — концентрированный нестабильный образец облученной жижи, отравляющей нижние глубины Гномрегана. Их собирают в тяжелые свинцовые контейнеры по приказу гномов-исследователей в надежде создать, изучив их, лекарство для больных лепрогномов.",h="Высокомощные радиоактивные осадки — концентрированный нестабильный образец облученной жижи, отравляющей...",kw={"gnomeregan","green glow","hall of gears","high potency radioactive fallout","irradiated slime","leper gnome","ozzie togglevolt","гномреган","зеленое свечение","зал шестеренок","высокомощные радиоактивные осадки","облученная слизь","лепрогном","оззи триггервольт"},ang={["profession:Engineering"]="Хранение и перевозка нестабильных, распадающихся радиоактивных изотопов требуют специально изготовленных свинцовых склянок, защищающих носителя от губительного облучения.",["race:Gnome"]="Каждая капля токсичных осадков, собранная в глубинах города, — это слабая надежда обратить ужасную мутацию, разорвавшую ваших сородичей во время падения Гномрегана."},sec={{t="Прямо из источника",b="Небольшие образцы радиации можно соскоблить с зараженных падальщиков на поверхности, но истинное сердце катастрофы Гномрегана требует куда более концентрированного вещества. Исследователям, расположившимся у павшей столицы, нужны чистые, неразбавленные радиоактивные осадки, взятые прямо с живых облученных ужасов, соглядатаев и слизей, ползающих по нижним ярусам Зала Шестеренок. Поскольку эта вязкая жижа постоянно распадается, ее нужно хранить в особой свинцовой склянке и быстро доставить, пока образец не утратил стабильность полностью."},{t="В поисках исцеления",b="Отчаянные поиски столь смертоносных материалов служат насущной цели. Оззи Триггервольт и его коллеги считают, что раскрытие тайн облученной жижи — единственный возможный путь к созданию лекарства для лепрогномов. Эти несчастные выжившие, сведенные с ума и изуродованные токсичным выбросом, произведенным по приказу во время вторжения троггов, остаются в плену живого кошмара, и потому даже самые опасные экспедиции за сбором образцов в руинах оправданы."}},faq={{q="Откуда берутся эти радиоактивные осадки?",a="Их берут прямо с живых облученных существ — облученных слизей, ужасов и соглядатаев, — обитающих глубоко на нижних уровнях Зала Шестеренок в Гномрегане.",al={"where to get fallout","fallout location","source of radioactive fallout","где достать осадки","где найти осадки","источник радиоактивных осадков"}},{q="Зачем нужен этот образец?",a="Гномы-исследователи, включая Оззи Триггервольта, нуждаются в неразбавленном, сильно концентрированном образце радиации Гномрегана, чтобы изучить недуг и попытаться создать лекарство для своих искаженных сородичей — лепрогномов.",al={"who wants the fallout","fallout purpose","why collect fallout","кому нужны осадки","назначение осадков","зачем собирать осадки"}},{q="Почему с ним нужно обращаться так осторожно?",a="Осадки крайне нестабильны и быстро разрушаются по мере распада. Для безопасной переноски их нужно держать в тяжелом свинцовом контейнере и доставить исследователям, пока их мощность не угасла и они не превратились в бесполезный остаток.",al={"fallout decay","why lead phial","fallout unstable","распад осадков","зачем свинцовая склянка","осадки нестабильны"}},{q="Почему прежних остатков троггов оказалось недостаточно?",a="Остатки, собранные с троггов, живущих на поверхности за пределами города, оказались слишком слабыми и нечистыми для научных испытаний. Исследователям нужно именно чистое, концентрированное свечение, которое встречается только у существ в глубинах облученного города.",al={"why not trogg glow","trogg radiation vs fallout","previous sample failure","почему не свечение троггов","радиация троггов и осадки","неудачный прошлый образец"}}},fp="32,288,21.557.0,24.468.0,46.174.0,26.218.0,36.218.0,45.253.0"}
P.entries["item:highborne-relic-classic"] = {n="Реликвия высокорожденных (Classic)",s="Реликвии высокорожденных — древние магические предметы, добываемые у неупокоенных духов, населяющих руины Амет'Арана на Темных берегах. Пропитанные тайными изысканиями, расколовшими древний Калимдор, они нужны ученым ночным эльфам, желающим уничтожить их, пока спящая в них сила не причинила новый вред.",h="Реликвии высокорожденных — древние магические предметы, добываемые у неупокоенных духов, населяющих руины...",kw={"ameth'aran","arcane","darkshore","highborne","highborne relic","sentinels","thundris windweaver","амет'аран","тайная магия","темные берега","высокорожденные","реликвия высокорожденных","часовые","тандрис ветропряд"},ang={["class:Mage"]="Маги могут найти тайное мастерство этих реликвий завораживающим, но местные власти ночных эльфов не терпят промедления с их уничтожением.",["race:NightElf"]="Для ночных эльфов эти реликвии — мрачное напоминание о пагубной тайной гордыне, разрушившей их древнюю цивилизацию."},sec={{t="Остатки Раскола",b="Десять тысяч лет назад каста высокорожденных занималась безрассудной тайной магией, что в итоге принесло гибель древнему Калимдору. Сегодня их бывшие поместья лежат в руинах по всем Темным берегам. Среди рушащихся колонн Амет'Арана по лесной земле бродят стонущие, корчащиеся призраки, вечно цепляющиеся за вещественные орудия своего былого колдовства. Эти реликвии остаются стойкими точками тайной порчи, их сжимают призраки, не желающие расстаться с орудиями собственной погибели."},{t="Очищение от тайной порчи",b="Для современного общества ночных эльфов, во многом отвергшего тайную магию после Великого Раскола, такие артефакты — серьезная опасность. Ученые вроде Тандриса Ветропряда в Аубердине, опираясь на донесения Часовых, нанимают путников, чтобы те вырывали эти реликвии из призрачных рук проклятых духов. Собранные реликвии планомерно уничтожаются, чтобы древнее зло и роковые ошибки высокорожденных не повторились."}},faq={{q="Откуда берутся реликвии высокорожденных?",a="Их добывают у призрачных видений, населяющих руины Амет'Арана к востоку от главной дороги на юге Темных берегов. Проклятые, корчащиеся и стонущие духи высокорожденных носят их среди древних камней.",al={"where do i find highborne relics","who drops highborne relics","relic location","где найти реликвии высокорожденных","с кого падают реликвии высокорожденных","где реликвии"}},{q="Зачем Тандрису Ветропряду эти реликвии?",a="Тандрис Ветропряд опасается остаточной тайной порчи, все еще присущей этим древним предметам. Он собирает их, чтобы полностью разобрать и уничтожить, не давая никому возродить опасное колдовство высокорожденных.",al={"why collect relics","what happens to the relics","windweaver goal","зачем собирать реликвии","что делают с реликвиями","цель ветропряда"}},{q="Почему духи высокорожденных все еще в Амет'Аране?",a="Эти духи — древняя знать высокорожденных, погибшая десять тысяч лет назад, когда мир раскололся. Проклятые собственной гордыней и неугасающей привязанностью к тайной магии, их неупокоенные души остаются привязанными к руинам их былого города.",al={"why are ametharan ghosts there","who are the cursed highborne","why ghosts in darkshore","почему призраки в амет'аране","кто такие проклятые высокорожденные","почему призраки на темных берегах"}},{q="Безопасно ли использовать реликвии высокорожденных?",a="Нет. Ночные эльфы считают их оскверненными скверной бесконтрольной тайной магии, вызвавшей Великий Раскол. Их спящая сила считается опасной, поэтому ученые требуют уничтожать их, а не изучать.",al={"can i use highborne relics","are relics dangerous","можно ли использовать реликвии высокорожденных","опасны ли реликвии"}}},fp="25,317,25.506.0,24.481.0,36.217.0,47.230.0,50.238.0,33.234.0"}
P.entries["item:highperch-venom-sac"] = {n="Ядовитая железа виверны Скального гнездовья",s="Ядовитые железы виверн Скального гнездовья добывают у диких виверн, гнездящихся на высоких скалах Скального гнездовья в Тысяче Игл. Хотя орки ценят виверн как воздушных скакунов, некоторые аптекари и торговцы еще больше ценят их сильнодействующие жала, чем живых зверей.",h="Ядовитые железы виверн Скального гнездовья добывают у диких виверн, гнездящихся на высоких скалах Скального...",kw={"auberdine","fiora longears","heartrazor","highperch","poison","thousand needles","venom sac","wyvern","аубердин","фиора длинноушка","сердцерезка","скальное гнездовье","яд","тысяча игл","ядовитая железа","виверна"},ang={["class:Rogue"]="Сильно концентрированный парализующий яд диких виверн Тысячи Игл — один из самых мощных природных токсинов Калимдора.",["faction:Alliance"]="Удар по гнездам Скального гнездовья служит Альянсу двойной цели: собрать ценные биологические реагенты для торговли и сократить дикое поголовье, которое иначе могла бы поймать и объездить Орда."},sec={{t="Ценная добыча",b="На высоких скалах Тысячи Игл обитают многочисленные стаи диких виверн, особенно вокруг возвышенных утесов Скального гнездовья. Эти крылатые хищники полагаются на сильный яд, вводимый шипастыми хвостами, чтобы парализовать и убивать добычу. Хотя Орда часто приручает этих существ как преданных наездников на ветрах, их ядовитые железы стоят удивительно дорого у алхимиков, охотников и оборотистых торговцев по всему Калимдору."},{t="Покупатель издалека",b="Хотя яд происходит из глубоких каньонов центрального Калимдора, он вызывает интерес по всему континенту. В тихом портовом городке Аубердин ночная эльфийка Фиора Длинноушка щедро платит за свежие железы из выводков Скального гнездовья. Ей нужны образцы, набухшие от яда, — обычно они встречаются лишь у молодых виверн или плодовитых самок, — что питает торговлю опасными реагентами вдали от естественной пустынной среды обитания зверей."}},faq={{q="У каких существ есть эти ядовитые железы?",a="Их добывают прямо у диких виверн, населяющих Скальное гнездовье в Тысяче Игл: у виверн Скального гнездовья, патриархов, консортов и матриарха Сердцерезки.",al={"where do venom sacs drop","who drops highperch venom","wyvern venom drop","где падают ядовитые железы","с кого падает яд скального гнездовья","яд виверны"}},{q="Почему Фиоре Длинноушке нужен этот яд на Темных берегах?",a="Фиора Длинноушка понимает, что яд виверн очень ценен в определенных торговых кругах — порой даже выгоднее самих скакунов. Она нанимает путников, отправляющихся в Скальное гнездовье в Тысяче Игл, чтобы те приносили целые железы для торговли.",al={"why fiora want venom","auberdine venom buyer","who buys wyvern venom","зачем фиоре яд","покупатель яда в аубердине","кто покупает яд виверн"}},{q="Одинаковы ли все ядовитые железы виверн?",a="Сила и объем яда различаются. Самые ценные железы набухли и полны яда; обычно они встречаются у молодых виверн или плодовитых самок.",al={"wyvern venom quality","bursting venom sacs","качество яда виверны","набухшие ядовитые железы"}},{q="Как Орда использует этих виверн в сравнении с Альянсом?",a="Орда в основном ловит и разводит виверн как воздушных скакунов и разведчиков, известных как наездники на ветрах. Независимые торговцы и связные Альянса, не имея налаженных способов приручения, вместо этого добывают зверей ради смертоносных химических реагентов.",al={"horde wyvern use","do orcs use the venom","использование виверн ордой","используют ли орки яд"}}},fp="19,260,16.431.0,15.417.0,38.172.0,53.257.0,36.167.0,66.246.0"}
P.entries["item:highperch-wyvern-egg"] = {n="Яйцо виверны Скального гнездовья",s="Яйца виверны Скального гнездовья — кладки, собранные в местах гнездования на высоких плато Тысячи Игл. Их ищут начинающие наездники на ветрах Орды, чтобы вырастить и выдрессировать новых воздушных скакунов.",h="Яйца виверны Скального гнездовья — кладки, собранные в местах гнездования на высоких плато Тысячи Игл.",kw={"elu","freewind post","highperch","highperch wyvern egg","thousand needles","wind rider","wyvern","элу","застава вольного ветра","скальное гнездовье","яйцо виверны скального гнездовья","тысяча игл","наездник на ветрах","виверна"},ang={["class:Hunter"]="Преодоление опасных высот Скального гнездовья требует понимания повадок свирепых хищников: взрослые виверны защищают места гнездования острыми когтями и ядовитыми жалами.",["faction:Horde"]="Надежное воздушное сообщение жизненно важно для связи и боевой готовности на обширных землях Калимдора, поэтому добыча свежего поголовья виверн имеет стратегическое значение."},sec={{t="Гнезда на плато",b="Высокое плато Скального гнездовья в Тысяче Игл — естественное убежище, где местные виверны гнездятся и растят потомство. Эти места гнездования доступны лишь по крутым извилистым тропам вдоль стен каньона, и взрослые звери яростно их охраняют. Яйца в этих гнездах крепкие и теплые, в них развиваются детеныши, способные приспособиться к суровому небу Калимдора."},{t="Воспитание новых наездников на ветрах",b="По всему Калимдору спрос на обученных виверн постоянно превышает предложение, поскольку Орда расширяет сети курьеров и разведки. На Заставе Вольного Ветра ученики, такие как таурен Элу, ищут целые яйца прямо в диких гнездовьях. Вырастив детенышей из скорлупы, дрессировщики надеются выстроить крепкую связь, необходимую для обучения надежных крылатых скакунов для наездников на ветрах Орды."}},faq={{q="Где находят эти яйца?",a="Они разбросаны по гнездам Скального гнездовья — высокого плато вдоль южных скальных стен Тысячи Игл, куда ведет тропа от дна каньона.",al={"egg locations","where to find wyvern eggs","highperch eggs location","где яйца","где найти яйца виверны","яйца скального гнездовья"}},{q="Почему Орда собирает яйца диких виверн?",a="Ряды наездников на ветрах Орды растут, и дрессировщикам трудно обучить достаточно взрослых виверн. Ученики вроде Элу собирают яйца, чтобы растить детенышей с рождения, готовя зверя и всадника к воздушной службе.",al={"why steal wyvern eggs","what are the eggs used for","elu egg quest purpose","зачем красть яйца виверн","для чего яйца","цель задания элу"}},{q="Враждебны ли родители-виверны к собирателям яиц?",a="Да. Дикие виверны яростно защищают свои гнезда и жестоко нападают на любого, кто проникнет в Скальное гнездовье, чтобы тронуть кладки.",al={"do wyverns attack","are wyverns protective","нападают ли виверны","защищают ли виверны гнезда"}},{q="Кто принимает эти яйца на Заставе Вольного Ветра?",a="Элу, начинающий наездник на ветрах, живущий на Заставе Вольного Ветра, собирает яйца в надежде начать собственное обучение скакуна.",al={"who takes wyvern eggs","elu freewind post","кто берет яйца виверны","элу застава вольного ветра"}}},fp="20,202,17.386.0,23.383.0,27.184.0,44.227.0,48.156.0,40.128.0"}
P.entries["item:hildelve-s-journal"] = {n="Записи Хилдельва",s="Записи Хилдельва — последние заметки дворфа-пилота Хильдельва, найденные при его останках в холодных пустошах Дун Морога. На залитых кровью страницах описана его роковая встреча со свирепым медведем и его предсмертное желание отомстить.",h="Записи Хилдельва — последние заметки дворфа-пилота Хильдельва, найденные при его останках в холодных пустошах...",kw={"dun morogh","hildelve","ice claw bear","journal","mangeclaw","pilot hammerfoot","siege brigade","дун морог","хильдельв","ледяной медведь","журнал","шелудивый коготь","пилот большеног","осадная бригада"},ang={["faction:Alliance"]="Возвращение личных вещей павших военных, таких как Хильдельв, укрепляет связь между Альянсом и Осадной бригадой Стальгорна.",["race:Dwarf"]="Журнал чтит несгибаемый дух дворфов-пилотов, которые, не страшась стужи и диких зверей, охраняют высоты Каз Модана."},sec={{t="Последние слова пилота",b="Когда его паровой танк сломался, дворф-пилот Хильдельв оставил напарника Большенога с танками и в одиночку отправился в заснеженные скалы Дун Морога на поиски слухами известной хиронитовой руды. Судя по записям, нацарапанным в его журнале, за ним несколько дней охотились, а затем на него напал чудовищный ледяной медведь по имени Шелудивый Коготь. Хотя Хильдельв отважно сражался и сумел отогнать зверя, он был тяжело изранен и остался один на лютом морозе. В журнале описаны его мучительные последние часы; заканчивается он единственной ясной просьбой перед возвращением хищника: чтобы тот, кто найдет его тело, отомстил за его смерть и выследил Шелудивого Когтя."},{t="Возвращение к осадной бригаде",b="Найденный журнал становится мрачной развязкой для товарища Хильдельва, пилота Большенога, который находится у форта у северных врат на востоке Дун Морога. Как член Осадной бригады Стальгорна, Большеног опасался худшего, когда Хильдельв не вернулся с поисков руды. Передача журнала вместе с отрубленным когтем зверя доказывает, что дух Хильдельва упокоен, а его последняя воля исполнена."}},faq={{q="Кто такой Хильдельв?",a="Хильдельв был дворфом, пилотом парового танка из Осадной бригады Стальгорна. После поломки танка он в одиночку отправился в дебри Дун Морога на поиски хиронской руды и был убит медведем Шелудивым Когтем, не успев вернуться.",al={"hildelve lore","who is hildelve","dwarf pilot hildelve","хильдельв предыстория","кто такой хильдельв","дворф пилот хильдельв"}},{q="Кто такой Шелудивый Коготь?",a="Шелудивый Коготь — необычайно крупный и свирепый ледяной медведь, бродящий по заснеженным хребтам Дун Морога. Он напал на Хильдельва, когда тот остался без помощи, тяжело изранил его и позже вернулся, чтобы прикончить.",al={"who is mangeclaw","what killed hildelve","bear that killed hildelve","кто такой шелудивый коготь","кто убил хильдельва","медведь убивший хильдельва"}},{q="Кому передают журнал, когда он найден?",a="Журнал относят пилоту Большеногу, пилоту осадной машины, который находится у форта у северных врат на востоке Дун Морога. Большеног был близким другом Хильдельва и искал вести о пропавшем пилоте.",al={"where do i take the journal","who gets hildelves journal","turn in hildelves journal","куда отнести журнал","кому отдать записи хильдельва","сдать записи хильдельва"}},{q="О чем просит Хильдельв в журнале?",a="Зная, что его раны смертельны, Хильдельв использовал последние страницы, чтобы описать напавшего зверя, и попросил любого путника, который найдет его останки, выследить Шелудивого Когтя и отомстить за его смерть.",al={"hildelves final wish","what is in the journal","pilot dying wish","последняя воля хильдельва","что в журнале","предсмертное желание пилота"}}},fp="18,246,21.661.0,27.416.1,17.239.0,18.201.0,42.203.0,42.190.0"}
P.entries["item:hillsbrad-human-skull"] = {n="Человеческий череп из Хилсбрада",s="Жуткий боевой трофей, добытый у убитых защитников и горожан-людей в Предгорьях Хилсбрада. Эти черепа собирают Отрекшиеся, расквартированные в Мельнице Таррен, как мрачные памятки о безжалостном наступлении на местные поселения людей.",h="Жуткий боевой трофей, добытый у убитых защитников и горожан-людей в Предгорьях Хилсбрада.",kw={"darthalia","hillsbrad","samsa","skull","southshore","tarren mill","trophy","дарталия","хилсбрад","самса","череп","южнобережье","мельница таррен","трофей"},ang={["race:Undead"]="Для Отрекшихся добыча человеческих черепов в Хилсбраде — одновременно сладкая месть и жуткое напоминание о живых сородичах, которые их сторонятся."},sec={{t="Трофеи жестокой войны",b="Пока идет конфликт между Отрекшимися из Мельницы Таррен и людьми Южнобережья и окрестных поселений, отрубленные черепа служат вещественным доказательством резни. Пока Стражи смерти и солдаты проводят систематическую чистку, приказанную Дарталией во время Битвы за Хилсбрад, другие стражи, застрявшие в карауле, жаждут своей доли кровавой бойни. Страж смерти Самса охотно выпрашивает такие трофеи у бойцов на передовой, находя извращенное удовольствие в собирании останков тех самых людей, среди которых Отрекшиеся когда-то жили."}},faq={{q="Кому нужны эти человеческие черепа?",a="Deathguard Samsa, a Forsaken sentry stationed in Tarren Mill, collects them. Envious of the soldiers sent out to battle and pillage Hillsbrad while he remains confined to guard duty, he asks passing adventurers to bring him thirty skulls to add to his private collection.",al={"who wants skulls","who takes human skulls","deathguard samsa skulls","кто хочет черепа","кто берет человеческие черепа","страж смерти самса черепа"}},{q="Где собирают человеческие черепа из Хилсбрада?",a="Их добывают у людей-бойцов и работников по всем Предгорьям Хилсбрада, особенно у ферм, шахт и городских укреплений под властью людей, атакованных во время Битвы за Хилсбрад.",al={"where do skulls drop","farm human skulls","who drops human skulls","где падают черепа","добыть человеческие черепа","с кого падают черепа"}},{q="Почему Отрекшиеся собирают останки людей?",a="Beyond raw hatred and dark humor, collecting trophies of dead humans is common sport among the Forsaken. Soldiers like Samsa view the skulls as prized curiosities and satisfying proof of Hillsbrad's impending downfall.",al={"why do forsaken want skulls","forsaken skull collection","зачем отрекшимся черепа","коллекция черепов отрекшихся"}}},fp="21,248,24.539.0,29.271.0,42.208.0,42.218.0"}
P.entries["item:hillsbrad-town-registry"] = {n="Регистрационная книга Хилсбрада",s="Регистрационная книга Хилсбрада — официальная городская книга учета, хранящаяся в ратуше Хилсбрадских полей. В ней учтены уцелевшие жители поселения, землевладельцы и гражданские записи, поэтому она — важная стратегическая цель наступления Отрекшихся на оплот людей.",h="Регистрационная книга Хилсбрада — официальная городская книга учета, хранящаяся в ратуше Хилсбрадских полей.",kw={"battle of hillsbrad","darthalia","hillsbrad fields","hillsbrad town hall","hillsbrad town registry","magistrate burnside","битва за хилсбрад","дарталия","хилсбрадские поля","ратуша хилсбрада","регистрационная книга хилсбрада","мировой судья бернсайд"},ang={["faction:Horde"]="Захват регистрационной книги — решающий шаг к подрыву власти людей в предгорьях и укреплению оплота Отрекшихся в Мельнице Таррен.",["race:Human"]="Книга олицетворяет официальное существование и права оставшихся жителей Хилсбрада, поэтому ее утрата — сокрушительный удар по местной общине."},sec={{t="Летопись непокорности",b="Регистрационная книга Хилсбрада лежит в ратуше возле трибуны мирового судьи Бернсайда и содержит сведения о населении, домах и административных правах Хилсбрада. Пока Отрекшиеся из Мельницы Таррен стремятся сломить сопротивление людей в предгорьях, Дарталия приказывает героям Орды проникнуть в ратушу, уничтожить совет и захватить эту книгу. Конфискация книги лишает Хилсбрад гражданского порядка и дает Подгороду ценные сведения об уцелевших жителях и их имуществе."}},faq={{q="Где хранится Регистрационная книга Хилсбрада?",a="Книга хранится в ратуше Хилсбрадских полей, в углу возле лестницы, ведущей на помост мирового судьи Бернсайда.",al={"registry location","where is town registry","find hillsbrad registry","где регистрационная книга","где городская книга","найти книгу хилсбрада"}},{q="Почему Отрекшиеся хотят ее украсть?",a="Верховный палач Дарталия стремится полностью уничтожить власть людей в предгорьях. Захват книги лишает поселение важных сведений о гражданах и имуществе и дает Отрекшимся подробные данные об уцелевшей общине.",al={"why steal registry","darthalia registry quest","purpose of registry","зачем красть книгу","задание дарталии книга","цель регистрационной книги"}},{q="Кто охраняет книгу?",a="Ее охраняют мировой судья Бернсайд и хилсбрадские советники, владеющие защитной магией и собирающиеся в ратуше и вокруг нее.",al={"who protects registry","town hall defenders","кто охраняет книгу","защитники ратуши"}}},fp="23,301,20.524.0,42.150.0,37.261.0,24.135.0"}
P.entries["item:hollow-vulture-bone"] = {n="Полая кость падальщика",s="Полые кости падальщика — легкие и прочные скелетные останки, добываемые у падальщиков Мерцающей равнины. На Виражах на Миражах гоблины-механики ценят их как особый строительный материал, облегчающий ракетные машины без потери прочности конструкции.",h="Полые кости падальщика — легкие и прочные скелетные останки, добываемые у падальщиков Мерцающей равнины.",kw={"hollow vulture bone","load lightening","mirage raceway","pozzik","scavenger","shimmering flats","thousand needles","полая кость падальщика","облегчение груза","виражи на миражах","поззик","падальщик","мерцающая равнина","тысяча игл"},ang={["class:Hunter"]="Падальщики Мерцающей равнины — выносливые трупоеды, поэтому они естественная цель для выслеживания на слепящей соляной равнине.",["profession:Engineering"]="Если обычные схемы опираются на тяжелое железо и бронзу, то применение полых птичьих костей показывает находчивость гоблинов, стремящихся к облегчению, что лежит в основе их гоночных новшеств."},sec={{t="Материалы для гонок на равнине",b="На соли все решает скорость, а вес — ее враг. Обычная инженерия опирается на железо и медь, но гоблинские команды механиков на Виражах на Миражах берут все, что дает пустыня, чтобы получить преимущество. Кости падальщиков полые, но на удивление прочные, и дают идеальное соотношение прочности и веса для внутренних кронштейнов, рулевых механизмов и мелких опор. Для главных умельцев вроде Поззика добыча костей у местных падальщиков — практичный и дешевый способ выиграть драгоценные секунды на трассе."}},faq={{q="Зачем гоблинам кости падальщиков?",a="Гоблины-инженеры вроде Поззика используют полые кости падальщиков, чтобы снизить вес ракетных машин. Птичьи кости легкие и на удивление прочные, поэтому они идеально подходят для рулевых механизмов и мелких элементов каркаса.",al={"why bones","goblin bones use","pozzik bone use","зачем кости","применение костей гоблинами","кости поззика"}},{q="Откуда берутся эти кости?",a="Их добывают у соляных падальщиков и соляных грифов, кружащих над Мерцающей равниной в Тысяче Игл, особенно возле гигантских скелетов, разбросанных по соляной пустыне.",al={"where to find hollow vulture bone","vulture bone location","how to get vulture bones","где найти полую кость падальщика","где достать кости","как получить кости падальщика"}},{q="Кто такой Поззик?",a="Поззик — гоблин-инженер и главный механик на Виражах на Миражах. Он постоянно настраивает и переделывает ракетные машины, чтобы состязаться с командой гномов под началом Пшикса Медноштифа.",al={"who is pozzik","pozzik raceway","who takes the bones","кто такой поззик","поззик трасса","кто берет кости"}}},fp="19,273,29.540.0,38.236.0,31.201.0,14.186.0"}
P.entries["item:honorary-picks"] = {n="Почетные кирки",s="Почетные кирки — связка церемониальных инструментов, изготовленных в Стальгорне для юных дворфов-подмастерьев шахтеров. Их доверяют путникам для доставки по сети гриффонов Броку Камнекопу в Телсамаре как знак готовности его учеников работать на богатых рудных жилах Лок Модана.",h="Почетные кирки — связка церемониальных инструментов, изготовленных в Стальгорне для юных дворфов-подмастерьев...",kw={"brock stoneseeker","gryth thurden","honorary picks","ironforge","loch modan","mining picks","thelsamar","thorgrum borrelson","брок камнекоп","грит турден","почетные кирки","стальгорн","лок модан","кирки шахтера","телсамар","торгрум боррелсон"},ang={["profession:Mining"]="Каждый шахтер Каз Модана знает цену крепкой кирке, и получение почетного инструмента отмечает подлинный переход новичка в профессию.",["race:Dwarf"]="Для дворфа вручение инструментов, выкованных в Стальгорне, подмастерьям, работающим в провинциях, — славная традиция родства и мастерства."},sec={{t="Орудия для нового поколения",b="In dwarven society, mining is far more than a trade; it is a cultural cornerstone that keeps the great forges burning and the kingdom supplied with iron and stone. The Honorary Picks represent formal recognition for novice prospectors learning under Brock Stoneseeker in Thelsamar. Sourced directly from Ironforge, these picks are presented to students who have proven their dedication and are ready to tackle the open ore deposits across Loch Modan."},{t="Испытание путей гриффонов",b="Transporting the picks serves a secondary purpose for the mountaineers and merchants of the Alliance: introducing couriers to the kingdom's gryphon network. Ferried from Ironforge's Great Forge directly to Gryth Thurden and flown across the mountains to Thorgrum Borrelson in Thelsamar, the shipment illustrates how closely tied the capital remains to its outlying outposts through swift aerial passage."}},faq={{q="Для чего нужны Почетные кирки?",a="Почетные кирки изготовлены для учеников-шахтеров Брока Камнекопа в Лок Модане. Это церемониальные, но вполне рабочие инструменты, которые вручают подмастерьям, готовым добывать руду в этом краю.",al={"what are honorary picks","use of honorary picks","honorary picks purpose","что такое почетные кирки","назначение почетных кирок","для чего почетные кирки"}},{q="Кто отправляет кирки и кто их получает?",a="Кирки готовят в Стальгорне и приносят Гриту Турдену на гриффоньей станции города. Оттуда их отправляют на восток, в Телсамар, и лично вручают наставнику по горному делу Броку Камнекопу.",al={"who gets honorary picks","honorary picks delivery","honorary picks recipient","кто получает почетные кирки","доставка почетных кирок","получатель почетных кирок"}},{q="Почему кирки нужно доставлять на гриффоне?",a="Хотя их можно было бы нести пешком через Северные врата, отправка через мастера гриффонов Грита Турдена обеспечивает быструю доставку и учит путников пользоваться установленными маршрутами полета Альянса между Стальгорном и Лок Моданом.",al={"why fly picks","why take gryphon","honorary picks flight","зачем лететь с кирками","зачем гриффон","полет с почетными кирками"}},{q="Являются ли Почетные кирки настоящим оружием или инструментом, который можно надеть?",a="Нет. Посыльный несет их лишь как груз; они предназначены для учеников-шахтеров Брока Камнекопа, которым не терпится применить их на рудных месторождениях Лок Модана.",al={"can i equip honorary picks","are honorary picks an item","honorary picks usable","можно ли надеть почетные кирки","почетные кирки предмет","почетные кирки применять"}}},fp="14,291,29.450.0,25.403.0,37.200.0,43.197.0,49.244.0,61.167.0"}
P.entries["item:horn-of-arra-chea"] = {n="Рог Арра'чеи",s="Рог Арра'чеи — охотничий трофей, добываемый у легендарного кодо Арра'чеи, который бродит по равнинам Мулгора. Рог добывают по велению верховного вождя Кэрна Кровавого Копыта, и он служит неопровержимым доказательством того, что начинающий охотник обладает дисциплиной и навыками выслеживания, необходимыми, чтобы обеспечивать Шу'хало.",h="Рог Арра'чеи — охотничий трофей, добываемый у легендарного кодо Арра'чеи, который бродит по равнинам Мулгора.",kw={"arra'chea","cairne bloodhoof","horn of arra'chea","kodo","mulgore","rites of the earthmother","thunder bluff","арра'чея","кэрн кровавое копыто","рог арра'чеи","кодо","мулгор","обряды матери-земли","громовой утес"},ang={["class:Hunter"]="Выслеживание Арра'чеи по его круговому маршруту через просторы Мулгора проверяет основные навыки скрытного преследования и выживания в дикой природе, которые ценит любой настоящий охотник.",["race:Tauren"]="Вручение этого рога верховному вождю Кэрну — важный обряд посвящения, подтверждающий, что вы готовы кормить и защищать свой народ на Громовом Утесе."},sec={{t="Испытание вождя",b="Хотя прохождение первых Обрядов Матери-Земли дает юноше законное место на Громовом Утесе, верховный вождь Кэрн Кровавое Копыто ждет, что его народ будет постоянно доказывать свою ценность. Для тауренов самосознание неразрывно связано с охотой и неизменной гармонией с землей. Кэрн испытывает молодых охотников, поручая им выследить Арра'чею — огромного одинокого быка кодо, бродящего по травянистым равнинам внизу. Добыв рог Арра'чеи, охотник доказывает, что овладел основным искусством выслеживания добычи на больших расстояниях."},{t="Забота о племени",b="Доставить рог на высокое плато Громового Утеса — это не просто демонстрация боевой силы: это служит выживанию всей общины. В культуре тауренов ничто из убитого зверя не должно пропасть. Получив трофей, Верховный вождь узнает, где лежит павший зверь, и отряды собирателей быстро выдвигаются на равнины, чтобы забрать плотную шкуру и жирное мясо Арра'чеи для молодой столицы."}},faq={{q="Что такое Рог Арра'чеи?",a="Это рог Арра'чеи, могучего и неуловимого кодо, бродящего по равнинам Мулгора. Охотники приносят его Кэрну Кровавому Копыту как обряд посвящения, демонстрируя свое умение выслеживать.",al={"horn of arrachea","arrachea horn","what is this horn","рог арра'чеи","рог арра'чея","что за рог"}},{q="Кто такая Арра'чея?",a="Арра'чея — известный бык кодо, кружащий по равнинам к северо-востоку от Громового Утеса. Благодаря своей силе и длинному миграционному маршруту он становится грозной добычей для охотников, желающих доказать свою ценность племени.",al={"arrachea","who is arrachea","arrachea lore","арра'чея","кто такая арра'чея","предания об арра'чее"}},{q="Почему Кэрн Кровавое Копыто просит этот трофей?",a="Кэрн считает, что для сохранения положения на Громовом Утесе необходимо постоянно доказывать свою службу и способности. Выследив и убив Арра'чею, охотник доказывает приверженность традициям Матери-Земли и добывает ценные ресурсы для общины.",al={"why cairne want horn","cairne arrachea","rites of the earthmother horn","зачем кэрну рог","кэрн арра'чея","обряды матери-земли рог"}},{q="Что происходит с остальной тушей зверя после убийства?",a="По обычаю тауренов, никакая часть добытого зверя не пропадает впустую. Когда рог доставлен в подтверждение убийства, Кэрн отправляет отряд собирателей в Мулгор за шкурой и мясом для Громового Утеса.",al={"arrachea meat","tauren hunting tradition","arrachea carcass","мясо арра'чеи","охотничья традиция тауренов","туша арра'чеи"}}},fp="17,304,18.522.0,23.435.0,30.192.0,17.226.0,46.273.0,57.227.0"}
P.entries["item:horn-of-awakening"] = {n="Рог Пробуждения",s="Рог Пробуждения — сигнальный инструмент, который хранится в сундуке у Керлониана Вечного Сумрака на юге Темных берегов. Им будят сонного друида всякий раз, когда он засыпает на дороге в Ясеневый лес.",h="Рог Пробуждения — сигнальный инструмент, который хранится в сундуке у Керлониана Вечного Сумрака на юге...",kw={"ashenvale","darkshore","druid of the claw","emerald dream","horn of awakening","kerlonian evershade","maestra's post","ясеневый лес","темные берега","друид-медведь","изумрудный сон","рог пробуждения","керлониан вечный сумрак","застава мейстры"},ang={["class:Druid"]="Друиды-медведи поколениями спали в Пещерах Курганов, общаясь с Изумрудным Сном, и возвращение к яви часто оставляет их оглушенными и растерянными.",["race:NightElf"]="Рога пробуждения и традиционные сигнальные инструменты издавна служили у ночных эльфов важным средством для пробуждения спящих стражей при внезапном вторжении."},sec={{t="Средство для сонного друида",b="Керлониан Вечный Сумрак, Друид-медведь, недавно пробудившийся после столетий в Изумрудном Сне, постоянно чувствует вялость в мире яви. Отправляясь на юг к Заставе Мейстры, он вверяет этот рог путникам, согласным его сопровождать. Когда усталость одолевает его на опасной лесной тропе, чистый звук рога встряхивает его чувства и поднимает на ноги, пока дикие звери или сектанты не воспользовались его сном."}},faq={{q="Где найти Рог Пробуждения?",a="Рог лежит в Сундуке Керлониана рядом с лагерем Керлониана Вечного Сумрака на юге Темных берегов, у границы Ясеневого леса.",al={"horn location","where is horn of awakening","kerlonians chest","где рог","где найти рог пробуждения","сундук керлониана"}},{q="Почему Керлониану нужен рог, чтобы не засыпать?",a="Проведя долгие века во сне в Изумрудном Сне, Керлониан с трудом привыкает к бодрствованию смертных и во время путешествия постоянно внезапно проваливается в глубокий сон.",al={"why is kerlonian sleeping","why does he fall asleep","emerald dream slumber","почему керлониан спит","почему он засыпает","сон изумрудного сна"}},{q="Куда пытается добраться Керлониан?",a="Он пытается дойти до Заставы Мейстры на севере Ясеневого леса, чтобы встретиться с Лиладрис Лунная Река.",al={"kerlonian destination","where is he walking","maestras post escort","цель керлониана","куда он идет","застава мейстры сопровождение"}}},fp="17,208,26.465.0,37.130.0,47.173.0,32.101.0"}
P.entries["item:horn-of-echeyakee"] = {n="Рог Ичияки",s="Рог Ичияки — охотничий инструмент, который дает Сергра Черный Шип на Перекрестке. Если протрубить в него среди древних останков кодо к северо-востоку от поселения, появится Белая Дымка — легендарный белый хищник Степей.",h="Рог Ичияки — охотничий инструмент, который дает Сергра Черный Шип на Перекрестке.",kw={"barrens","crossroads","echeyakee","horn","kodo bones","sergra darkthorn","whitemist","степи","перекресток","ичияки","рог","кости кодо","сергра черный шип","белая дымка"},ang={["class:Hunter"]="Для охотников призыв Ичияки — легендарный обряд посвящения: они состязаются в чутье с хищником, известным по всем Степям почти безупречной скрытностью.",["race:Tauren"]="Охота на Ичияки имеет для тауренов духовный смысл: стремительную безболезненную смерть зверя они считают воплощением и милосердия, и суровой необходимости смерти."},sec={{t="Призыв Белой Дымки",b="Рог, который вручают новичкам, испытывающим себя в охоте, разносит свой зов по саванне и призывает Ичияки, чье имя на таурахе означает «Белая Дымка». Король саванных кошек, Ичияки почитается охотниками-тауренами и как милосердие, и как смерть: он бьет так стремительно, что жертва не чувствует ни ужаса, ни страданий. Трубить в рог следует только у логова великого хищника — выбеленного солнцем гнезда из костей гигантских кодо за холмами к северо-востоку от Перекрестка."}},faq={{q="Для чего нужен Рог Ичияки?",a="Рог служит, чтобы выманить Ичияки, неуловимого белого саванного кота. Если протрубить в него возле костей гигантских кодо к северо-востоку от Перекрестка, зверь появится, и охотник сможет сразиться с ним.",al={"use horn of echeyakee","what is horn of echeyakee for","использовать рог ичияки","для чего рог ичияки"}},{q="Откуда берется рог?",a="Сергра Черный Шип, охотница-орк, живущая на Перекрестке в Степях, вверяет рог искателям приключений, желающим доказать свою скрытность и умение выслеживать.",al={"who gives the horn","horn of echeyakee source","кто дает рог","откуда рог ичияки"}},{q="Что означает имя Ичияки?",a="На языке тауренов, тавриянском (Taur-ahe), «Ичияки» означает «Белый туман». Имя отсылает к бледной шкуре зверя и к его бесшумной, подобной туману способности подкрадываться сквозь сухие травы незамеченным.",al={"echeyakee meaning","whitemist meaning","значение ичияки","значение белая дымка"}},{q="Где нужно трубить в рог?",a="В рог нужно трубить среди ребер и скелетов гигантских кодо за холмами к северо-востоку от Перекрестка, где охотится белый лев.",al={"where to use horn","echeyakee location","где использовать рог","где ичияки"}}},fp="17,232,21.505.0,35.202.0,30.161.0,34.191.0,27.170.0"}
P.entries["item:huge-gnoll-claw"] = {n="Коготь большого гнолла",s="Коготь большого гнолла — неподдельный трофей, добываемый у Дробителя, огромного гнолла, рыскающего на юго-западе Элвиннского леса. Он намного больше когтя обычного гнолла и служит официальным доказательством смерти, которого требуют власти Штормграда в Златоземье.",h="Коготь большого гнолла — неподдельный трофей, добываемый у Дробителя, огромного гнолла, рыскающего на...",kw={"bounty","elwynn forest","goldshire","hogger","huge gnoll claw","marshal dughan","riverpaw","награда","элвиннский лес","златоземье","дробитель","коготь большого гнолла","маршал дугхан","речная лапа"},ang={["class:Hunter"]="Добыча когтя такого огромного хищника показывает высочайшее мастерство выслеживания и охоты на зверей против чудовища, которое не раз одолевало вооруженные отряды.",["faction:Alliance"]="Добыв коготь, вы избавляете сердце королевства от самой известной лесной напасти и доказываете доблесть маршалу Дугхану и осажденному гарнизону Златоземья."},sec={{t="Доказательство для охотника за головами",b="Несколько месяцев Дробитель терроризировал южные леса Лесной опушки, не обращая внимания на патрули и сводя на нет все попытки местного гарнизона его загнать или усмирить. Армия Штормграда, измотанная и растянутая по всему Элвиннскому лесу, объявила открытую награду за голову чудовища. Маршал Дугхан в Златоземье требует неопровержимых доказательств перед выплатой награды, а огромный коготь служит бесспорным подтверждением того, что гроза лесов наконец пала."}},faq={{q="Для чего нужен Коготь большого гнолла?",a="Коготь служит официальным доказательством смерти Дробителя. Его приносят прямо маршалу Дугхану в Златоземье, чтобы выполнить объявленное задание и получить награду.",al={"what do i do with hogger claw","huge gnoll claw use","who wants the claw","что делать с когтем дробителя","применение когтя большого гнолла","кому нужен коготь"}},{q="Откуда берется этот коготь?",a="Его берут у Дробителя, элитного гнолла, бродящего возле лагерей Речной Лапы на юго-западных границах Лесной опушки в Элвиннском лесу.",al={"who drops the claw","how to get huge gnoll claw","where to find huge gnoll claw","с кого падает коготь","как получить коготь большого гнолла","где найти коготь большого гнолла"}},{q="Почему маршал Дугхан хочет коготь, а не голову?",a="Дробитель необычно крупен даже для вожака Речной Лапы, а его огромные когти особенные и безошибочно узнаваемы. Принесенный коготь не оставляет Армии Штормграда сомнений, что печально известный разбойник действительно убит.",al={"why proof of demise claw","why not hoggers head","dughan bounty proof","почему коготь доказательство","почему не голова дробителя","доказательство для дугхана"}},{q="Можно ли получить другой коготь, если я потеряю этот?",a="Да. Если коготь потерян до передачи маршалу Дугхану, вы можете снова выследить Дробителя на юго-западе Элвиннского леса и получить новый.",al={"lost huge gnoll claw","can i get claw again","hogger claw respawn","потерял коготь большого гнолла","можно ли получить коготь снова","коготь дробителя повторно"}}},fp="15,254,21.493.0,37.161.0,31.148.0,56.224.0,36.152.0"}
P.entries["item:humbert-s-sword"] = {n="Меч Гумберта",s="Меч Гумберта — личное оружие Стража смерти Гумберта из Мельницы Таррен. Дворфы-солдаты забрали его из лагеря, пока тот разведывал их крепость Дун Гарок.",h="Меч Гумберта — личное оружие Стража смерти Гумберта из Мельницы Таррен.",kw={"darthalia","deathguard humbert","dun garok","hillsbrad","humbert's sword","tarren mill","дарталия","страж смерти гумберт","дун гарок","хилсбрад","меч гумберта","мельница таррен"},ang={["faction:Horde"]="Возвращение меча совпадает с более широкими операциями Орды против дворфийского анклава Дун Гарока, включая сбор дворфийской крови и воинских знаков различия.",["race:Undead"]="Верховный палач Дарталия поддерживает беспощадную дисциплину среди сил Отрекшихся в Хилсбраде, и нерадивые часовые вроде Гумберта отчаянно пытаются скрыть свои ошибки."},sec={{t="Минута беспечности разведчика",b="Страж смерти Гумберт был отправлен Верховным палачом Дарталией наблюдать из укрытия за присутствием дворфов в Дун Гароке. Однажды утром он оставил пост без присмотра, чтобы собрать хворост и вскипятить воду, а дворфийские патрули наткнулись на его лагерь и разграбили все снаряжение, включая личный клинок. Поскольку дворфов слишком много для поисков, Гумберт рассчитывает на агентов Орды, которые проникнут в крепость и вернут потерянное оружие."},{t="Дворфийская добыча",b="После кражи вещи Гумберта унесли за укрепленные баррикады Дун Гарока. Поскольку дворфийские стрелки, горцы и жрецы раздают припасы по всему гарнизону, чтобы найти конкретного вора, придется обыскать защитников, расставленных в окопах и редутах крепости."}},faq={{q="Кому принадлежит этот меч?",a="Клинок принадлежит Стражу смерти Гумберту, часовому Отрекшихся, расквартированному в Мельнице Таррен, которому поручили разведывать Дун Гарок.",al={"whose sword is this","humbert owner","who is humbert","чей это меч","владелец меча гумберта","кто такой гумберт"}},{q="Как дворфы получили меч Гумберта?",a="Страж смерти Гумберт утром покинул свой лагерь разведчика возле Дун Гарока, чтобы собрать хворост. Пока его не было, дворфийский патруль разграбил лагерь и унес его снаряжение.",al={"how did dwarves get it","why do dwarves have sword","how was sword stolen","как дворфы получили меч","почему у дворфов меч","как украли меч"}},{q="Почему Гумберту так отчаянно нужен его меч?",a="Гумберту нужно оружие, чтобы продолжать наблюдение за Дун Гароком, которое поручила ему Верховный палач Дарталия, а из-за множества дворфов в гарнизоне он не надеется найти вора в одиночку.",al={"why humbert want sword","what happens if humbert loses sword","why does humbert care","зачем гумберту меч","что будет если гумберт потеряет меч","почему гумберт переживает"}},{q="Где можно найти меч?",a="Меч находится у дворфийских сил, расквартированных в Дун Гароке на юго-востоке Предгорий Хилсбрада. Его можно забрать у горцев, стрелков или жрецов, стоящих по всей крепости.",al={"where does sword drop","sword location","how to find humbert's sword","откуда падает меч","где меч","как найти меч гумберта"}}},fp="15,196,25.439.0,17.325.0,20.120.0,40.182.0,50.175.0,29.205.0"}
P.entries["item:hyacinth-mushroom"] = {n="Гиацинтовый гриб",s="Гиацинтовые грибы — необычные грибы, растущие у корней деревьев по всей Тенистой долине на Тельдрассиле. Ночные эльфы-травники ценят их за целебные свойства, а проказливые греллы и их сородичи любят есть их и собирать.",h="Гиацинтовые грибы — необычные грибы, растущие у корней деревьев по всей Тенистой долине на Тельдрассиле.",kw={"antidote","dirania silvershine","grell","grellkin","hyacinth mushroom","iverron","shadowglen","teldrassil","противоядие","дирания серебряное сияние","грелл","грелленыш","гиацинтовый гриб","иверрон","тенистая долина","тельдрассил"},ang={["profession:Herbalism"]="Хотя сбор этих грибов в Тенистой долине не требует особого обучения, любой начинающий травник оценит их роль в нейтрализации лютых лесных ядов.",["race:NightElf"]="Для молодых ночных эльфов, обучающихся в Тенистой долине, сбор дикорастущих растений вроде гиацинтовых грибов — первый урок того, как использовать дары природы на благо сородичей."},sec={{t="Флора Тенистой долины",b="Гиацинтовые грибы во множестве растут по всей Тенистой долине, процветая во влажной тени у подножий древних курганов, замшелых камней и раскидистых корней Альдрассила. Они полезны в лесных снадобьях, но привлекли и внимание порченых греллов, которые часто запасают их. Когда молодых ночных эльфов-часовых или учеников жалит местная ядовитая живность, например пауки из Паучьего логова, эти грибы служат основой успокаивающих отваров и противоядий, которые готовят лесные целители."}},faq={{q="Для чего используются гиацинтовые грибы?",a="Жрица Дирания Серебряное Сияние использует их как важный ингредиент для противоядия Иверрону — юному ночному эльфу, которого укусили и отравили ядовитые пауки, когда он исследовал Паучье логово.",al={"hyacinth mushroom use","what does it do","iverron cure","применение гиацинтового гриба","для чего нужен","лекарство иверрона"}},{q="Где растут гиацинтовые грибы?",a="Они растут прямо на земле у стволов и корней больших деревьев, а также рядом с валунами по всей уединенной Тенистой долине на Тельдрассиле.",al={"mushroom location","where to find hyacinth mushroom","shadowglen mushrooms","где растет гриб","где найти гиацинтовый гриб","грибы тенистой долины"}},{q="Почему греллы носят гиацинтовые грибы?",a="Проказливые греллы и их сородичи, наводнившие южную часть Тенистой долины, питают странное пристрастие к этим грибам: они собирают их и запасают в своих лагерях.",al={"grell drop mushrooms","why do grell have them","grellkin mushrooms","грибы с греллов","почему они у греллов","грибы грелленышей"}},{q="Ядовиты ли сами гиацинтовые грибы?",a="Нет. Несмотря на яркий вид и тенистое место, где они растут, местные целители безопасно используют их как ингредиент лечебных припарок и укрепляющих противоядий.",al={"is hyacinth mushroom toxic","poisonous mushroom","ядовит ли гиацинтовый гриб","ядовитый гриб"}}},fp="17,271,19.525.0,37.198.0,33.161.0,42.154.0,44.184.0"}
P.entries["item:hypercapacitor-gizmo"] = {n="Механизм гипервместимости",s="Механизм гипервместимости — причудливое инженерное устройство, найденное на дне каньона Тысячи Игл. Некогда оно висело на шее зверя в клетке среди разрушенного каравана, и его истинное назначение остается загадкой даже для механика, который называет его своим.",h="Механизм гипервместимости — причудливое инженерное устройство, найденное на дне каньона Тысячи Игл.",kw={"centaur","enraged panther","gizmo","hypercapacitor","thousand needles","whitereach post","wizlo bearingshiner","кентавр","разъяренная пантера","механизм","гипервместимость","тысяча игл","застава белого плеса","визло фингалет"},ang={["faction:Horde"]="Путники, помогающие Заставе Белого Плеса, истребляют агрессивных кентавров и возвращают потерянные диковинки из разрушенных караванов на дне каньона.",["profession:Engineering"]="Механизм — классика гоблинской инженерии: сложное устройство с опасным названием, созданное с большим энтузиазмом, прежде чем кто-либо решил, для чего оно предназначено."},sec={{t="Странная реликвия каравана",b="Когда кентавры-мародеры напали на гоблинский караван, шедший через Тысячу Игл, они разграбили почти все на виду. Единственный выживший, Визло Фингалет, сумел доползти до безопасной Заставы Белого Плеса, оставив свое самое ценное изобретение — Механизм гипервместимости. Как ни странно, устройство оказалось закреплено на шее свирепой разъяренной пантеры, запертой в транспортной клетке. Грабители-кентавры так боялись зверя, что оставили клетку нетронутой среди горящих обломков, невольно сохранив странную машину Визло."},{t="Возня впотьмах",b="Визло гордо называет устройство своим лучшим творением, но, получив его обратно, признает, что не знает, что оно на самом деле делает. Как и многие гоблинские приспособления, Механизм гипервместимости — запутанный клубок амбиций и взрывоопасных деталей, обреченный бесконечно занимать создателя возней, а не выполнять какую-либо понятную практическую функцию."}},faq={{q="Что такое Механизм гипервместимости?",a="Это инженерное устройство, созданное гоблином Визло Фингалетом. Несмотря на громкое название, даже Визло не знает, какую функцию оно выполняет, и собирается изучать его, чтобы понять его назначение.",al={"what is gizmo","hypercapacitor","what does the gizmo do","что такое механизм","гипервместимость","что делает механизм"}},{q="Как устройство оказалось на шее пантеры?",a="Караван Визло был атакован и разграблен кентаврами на севере Тысячи Игл. Во время хаоса устройство оказалось закреплено на шее разъяренной пантеры в дорожной клетке, и суеверные кентавры не стали его грабить.",al={"why panther has gizmo","how did panther get it","почему механизм у пантеры","как пантера получила его"}},{q="Кто хочет вернуть Механизм гипервместимости?",a="Его возвращения добивается Визло Фингалет, единственный выживший из разграбленного каравана. Он укрылся на Заставе Белого Плеса — лагере таурен на северо-западе Тысячи Игл.",al={"who needs gizmo","wizlo gizmo","кому нужен механизм","визло механизм"}},{q="Почему кентавры не украли его?",a="Кентавры разграбили весь караван, но до ужаса боялись свирепой пантеры в клетке. Они оставили зверя и его металлический ошейник нетронутыми среди руин.",al={"why didn't centaur take it","centaur and panther","почему кентавры не взяли","кентавры и пантера"}}},fp="20,258,25.559.0,21.363.0,33.220.0,50.250.0,40.173.0,32.179.0"}
P.entries["item:ignition-key"] = {n="Ключ зажигания",s="Ключ зажигания — важный ключ управления, который носит Бригадир Зубовиззл на буровой Торговой Компании в Нефтяном болоте. Он нужен, чтобы разблокировать рулевую колонку и включить управление усовершенствованного крошшера Торговой Компании.",h="Ключ зажигания — важный ключ управления, который носит Бригадир Зубовиззл на буровой Торговой Компании в...",kw={"ignition key","shredder","sludge fen","sputtervalve","supervisor lugwizzle","venture company","wizzlecrank","ключ зажигания","крошшер","нефтяное болото","пароклапан","надсмотрщик лагвиззл","торговая компания","зизгаг"},ang={["profession:Engineering"]="Ключ открывает крошшер с на редкость совершенными механизмами управления, превосходящими обычные гоблинские конструкции и в регулировке скорости, и в точности движений руки."},sec={{t="Недостающая деталь шпионажа",b="Когда Пароклапан из Кабестана отправил агента украсть секретный крошшер Торговой Компании в Нефтяном болоте, все пошло не гладко. Пилот под прикрытием, Зизгаг, проник в кабину машины, но обнаружил, что колонка управления движением полностью заблокирована. Чтобы не вызвать подозрений у бригадиров, он притворялся, что у машины неполадки, и ждал искателя приключений, который добудет нужный Ключ зажигания. Ключ хранит под замком Бригадир Зубовиззл на самой вершине центральной нефтяной вышки; он управляет доступом к современным механизмам руки, скорости и вращения машины."}},faq={{q="Где найти Ключ зажигания?",a="Ключ хранится у Бригадира Зубовиззла, который руководит буровыми работами из диспетчерской на вершине нефтяной вышки в Нефтяном болоте.",al={"ignition key location","who drops ignition key","how to get ignition key","где ключ зажигания","у кого ключ зажигания","как получить ключ зажигания"}},{q="Почему Зизгагу нужен именно этот ключ?",a="В отличие от более простых инженерных машин, у этого усовершенствованного крошшера Торговой Компании заблокирована колонка управления движением. Без нужного ключа зажигания пилот не может управлять вращением, скоростью, устойчивостью и рукой, чтобы увести машину.",al={"why need key","what does key do","shredder key purpose","зачем нужен ключ","что делает ключ","назначение ключа крошшера"}},{q="Кто хочет украсть крошшер?",a="Пароклапан, гоблин-инженер из Кабестана, организовал операцию, чтобы заполучить превосходные инженерные разработки Торговой Компании.",al={"who sent wizzlecrank","why steal shredder","ratchet shredder","кто послал зизгага","зачем красть крошшер","крошшер кабестана"}},{q="Что произойдет после доставки ключа?",a="Когда ключ разблокирует колонку управления, Зизгаг заводит двигатель крошшера и должен отчаянно прорываться через враждебных рабочих Нефтяного болота, чтобы уйти к Кабестану.",al={"after turning in key","the escape","what next","после сдачи ключа","побег","что дальше"}}},fp="12,247,28.614.0,36.146.0,44.222.0,30.149.0,39.184.1"}
P.entries["item:ilkrud-magthrull-s-tome"] = {n="Фолиант Илкруда Магтрулла",s="Фолиант Илкруда Магтрулла — гримуар, добытый у опасного орка-чернокнижника, обитающего в порченых глубинах Ясеневого леса. Если доставить его Делгрену Очистителю, его мерзкое содержание раскроет более широкие темные дела культистов, действующих из Башни Алталакса.",h="Фолиант Илкруда Магтрулла — гримуар, добытый у опасного орка-чернокнижника, обитающего в порченых глубинах...",kw={"ashenvale","delgren the purifier","fire scar shrine","ilkrud magthrull","maestra's post","tome","tower of althalaxx","warlock","ясеневый лес","делгрен очиститель","святилище огненной расщелины","илкруд магтрулл","застава мейстры","фолиант","башня алталакса","чернокнижник"},ang={["class:Paladin"]="Возвращение фолианта помогает брату Делгрену, собрату по служению Свету, который несет бдительную стражу против тьмы и порчи в диких землях Ясеневого леса.",["class:Warlock"]="Гримуар Магтрулла — ценная запись темных подчинений, подробно описывающая порабощение демонов Бездны и суккубов в оскверненном Святилище Огненной Расщелины."},sec={{t="Гримуар порчи",b="Илкруд Магтрулл — грозный орк-чернокнижник, засевший в Святилище Огненной Расщелины на юго-западе Ясеневого леса, месте, отравленном остатками демонического влияния. Окруженный призванными слугами, Магтрулл записывал свои мерзкие ритуалы и темные послания в этом личном фолианте. Паладин Серебряного Рассвета Делгрен Очиститель давно знал о присутствии чернокнижника, но обнаруженная связь между Магтруллом и темными культистами, собирающимися в Башне Алталакса, сделала возвращение книги неотложной задачей."},{t="Раскрытие культа",b="После того как фолиант изъят из рук убитого Магтрулла, его доставляют Делгрену на Заставу Мейстры. Делгрен стремится расшифровать записи чернокнижника, чтобы понять, какая сеть координирует демоническую деятельность по обе стороны границы Темных берегов и Ясеневого леса. Текст дает важные сведения о таинственных заговорщиках, стоящих за порчей, пускающей корни на севере Калимдора."}},faq={{q="Кому принадлежит этот фолиант?",a="Книга принадлежит Илкруду Магтруллу, могущественному орку-чернокнижнику, обосновавшемуся среди демонических руин Святилища Огненной Расщелины на юго-западе Ясеневого леса.",al={"who is ilkrud magthrull","who wrote the tome","ilkrud magthrull","кто такой илкруд магтрулл","кто написал фолиант","илкруд магтрулл"}},{q="Где найти фолиант?",a="Его добывают прямо у Илкруда Магтрулла в Святилище Огненной Расщелины, к югу от Святилища Эссины в Ясеневом лесу.",al={"tome location","how to get the tome","where to find ilkrud","где фолиант","как получить фолиант","где найти илкруда"}},{q="Зачем Делгрену Очистителю эта книга?",a="Делгрен хочет изучить записи Магтрулла, чтобы раскрыть темные связи между местными поклонниками демонов и культистами, обитающими в Башне Алталакса.",al={"why delgren wants the tome","what is in the tome","delgren book purpose","зачем делгрену фолиант","что в фолианте","цель книги делгрена"}},{q="Что происходит после возвращения фолианта?",a="Делгрен изучает текст на Заставе Мейстры, чтобы расшифровать демонические послания Магтрулла и определить следующий шаг в разгроме сети культа.",al={"turn in tome","what does delgren do with the book","сдать фолиант","что делгрен делает с книгой"}}},fp="23,277,24.510.0,19.393.1,19.155.0,24.132.0,44.153.0,41.153.0"}
P.entries["item:incantations-from-the-nether"] = {n="Магическая формула Пустоты",s="Магическая формула Пустоты — гримуар демонической магии, которым владеют культисты Пламенеющего Клинка, скрывающиеся под Оргриммаром. Сильвана Ветрокрылая и ее лорд ужаса-помощник Вариматрас хотят завладеть фолиантом, чтобы использовать его скверные знания на благо Отрекшихся.",h="Магическая формула Пустоты — гримуар демонической магии, которым владеют культисты Пламенеющего Клинка...",kw={"incantations from the nether","ragefire chasm","searing blade","shadow council","spells of shadow","sylvanas","the power to destroy","varimathras","магическая формула пустоты","огненная пропасть","пламенеющий клинок","совет теней","заклинания тьмы","сильвана","сила разрушения","вариматрас"},ang={["class:Warlock"]="Фолианты, добытые прямо из Пустоты, содержат мощную магию Скверны, которой пожелал бы любой честолюбивый практик темных искусств.",["race:Undead"]="Возвращение этой книги напрямую помогает ближнему кругу Темной Госпожи в Подгороде, собирая темные знания, необходимые для войны с Плетью."},sec={{t="Дары Легиона",b="Под красными каменными улицами Оргриммара Пламенеющий Клинок — подземная секта, связанная с Советом Теней, — действует в огненных туннелях Огненной пропасти. Среди ее самых темных сокровищ — Магическая формула Пустоты, книга заклинаний, полная демонических обрядов, дарованных посланниками Пылающего Легиона. Пока культисты используют ее мерзкие тайны, замышляя измену в столице орков, слух о тексте достиг далеко за морем королевских покоев Подгорода."},{t="Амбиции Отрекшихся",b="Леди Сильване Ветрокрылой и лорду ужаса Вариматрасу такие могущественные скверные реликвии кажутся потраченными зря на культистов с, по их мнению, мелким кругозором. Вариматрас отправляет верных искателей приключений из Орды вглубь Огненной пропасти, чтобы добыть Магическую формулу Пустоты вместе с ее сестринским томом — Заклинаниями Тьмы. Темная Госпожа намерена направить силы книги, рожденные в Пустоте, на свой главный крестовый поход: уничтожить Короля-лича и воздать Плети по заслугам."}},faq={{q="Где найти книгу «Магическая формула Пустоты»?",a="Книгу носят культисты и чернокнижники Пламенеющего Клинка, скрывающиеся в Огненной пропасти — сети вулканических пещер прямо под городом Оргриммар.",al={"where to get incantations from the nether","who drops incantations from the nether","incantations from the nether location","где взять магическую формулу пустоты","у кого магическая формула пустоты","магическая формула пустоты где найти"}},{q="Кому нужна эта книга и зачем?",a="Книгу ищут лорд ужаса Вариматрас и леди Сильвана Ветрокрылая. Они считают, что такие демонические дары потрачены зря на мелких культистов Пламенеющего Клинка, и хотят обратить ее темную магию против их заклятого врага — Короля-лича.",al={"who needs incantations from the nether","why does sylvanas want this book","varimathras book quest","кому нужна магическая формула пустоты","зачем сильване эта книга","задание вариматраса на книгу"}},{q="Что такое Пламенеющий Клинок?",a="Пламенеющий Клинок — тайный ковен чернокнижников и культистов, действующий под Оргриммаром и союзный Совету Теней. Они служат Пылающему Легиону и из тени работают над тем, чтобы подорвать новую Орду Тралла.",al={"searing blade lore","who are the searing blade","предания пламенеющего клинка","кто такой пламенеющий клинок"}},{q="Какая другая книга связана с этой?",a="Вариматрасу нужны два тома: Магическая формула Пустоты и второй гримуар — Заклинания Тьмы. Оба нужно отобрать у культистов в Огненной пропасти, чтобы выполнить его задание.",al={"other book for varimathras","power to destroy books","другая книга вариматраса","сила разрушения книги"}}},fp="28,254,19.470.0,17.455.1,53.161.0,28.235.0,26.213.0,40.191.0"}
P.entries["item:incendia-agave"] = {n="Огненная агава",s="Огненная агава — редкое колючее водное растение, произрастающее в Кипящем бассейне под Пиком Темного Облака в Тысяче Игл. Если искусный шаман наложит на него чары, его особые свойства позволяют разжечь священное пламя жизни.",h="Огненная агава — редкое колючее водное растение, произрастающее в Кипящем бассейне под Пиком Темного Облака в...",kw={"arikara","boiling pool","darkcloud pinnacle","incendia agave","magatha grimtotem","sacred fire","thousand needles","арикара","кипящий бассейн","пик темного облака","огненная агава","магата зловещий тотем","священное пламя","тысяча игл"},ang={["class:Shaman"]="Чтобы превратить водный суккулент в порошок, способный зажечь священное ритуальное пламя, агаве требуется чистое шаманское искусство стихий.",["profession:Herbalism"]="Травники сочтут чутье на травы незаменимым, когда будут искать колючие заросли Огненной агавы на илистом дне Кипящего бассейна."},sec={{t="Редкая пустынная трава",b="Огненная агава растет под водами Кипящего бассейна в Тысяче Игл и вокруг них, прямо в тени Пика Темного Облака. Растение охраняют бродящие по округе паровые элементали, поэтому его трудно собрать, и в Калимдоре оно встречается редко. Хотя агава растет под водой, в ней содержатся мощные природные стихии, пригодные для ритуалов пламени."},{t="Священное пламя",b="Таурены-ритуалисты знают, что спящее священное пламя жизни нельзя зажечь обычными искрами. Старейшина Магата Зловещий Тотем с Вершины Старейшин в Громовом Утесе обладает шаманскими познаниями, необходимыми, чтобы превратить собранные пучки Огненной агавы в волшебный порошок. Готовый порошок зажигает церемониальную жаровню, нужную для призыва мстительного ветряного змея Арикару."}},faq={{q="Где растет Огненная агава?",a="Огненная агава растет в озере у Кипящего бассейна и вокруг него, под Пиком Темного Облака на севере Тысячи Игл. Многие растения лежат под водой на дне озера.",al={"where find agave","incendia agave location","where is agave","где найти агаву","огненная агава где растет","где агава"}},{q="Для чего нужна Огненная агава?",a="Для ритуального порошка собирают десять пучков агавы. После того как Магата Зловещий Тотем в Громовом Утесе наложит на порошок чары, им зажигают священное пламя жизни и призывают змея Арикару.",al={"incendia agave purpose","why gather agave","what does agave do","огненная агава для чего","зачем собирать агаву","что делает агава"}},{q="Кто может зачаровать Огненную агаву?",a="Магата Зловещий Тотем, влиятельная шаманка с Вершины Старейшин в Громовом Утесе, владеет ритуальным искусством, позволяющим вплести шаманскую магию в сырое растение.",al={"who enchants agave","magatha agave","who turns agave into powder","кто зачаровывает агаву","магата агава","кто превращает агаву в порошок"}},{q="Какие опасности окружают Огненную агаву?",a="По водам и берегам Кипящего бассейна бродят враждебные паровые элементали, весьма устойчивые к чарам льда и огня.",al={"agave hazards","what guards agave","boiling pool dangers","опасности агавы","кто охраняет агаву","опасности кипящего бассейна"}}},fp="14,222,18.381.0,15.376.1,31.202.0,32.203.0,35.161.0,41.141.0"}
P.entries["item:insane-scribbles"] = {n="Безумные каракули",s="Эти Безумные каракули вырваны из загадочного Сумеречного фолианта — отрывка темной литературы, который носят с собой культисты на Темных берегах. От одного взгляда на пляшущий текст и искаженные узоры начинаются сильное головокружение и душевное напряжение. Древние защитники леса изучают такие обрывки, чтобы разгадать зловещие замыслы Сумеречного Молота.",h="Эти Безумные каракули вырваны из загадочного Сумеречного фолианта — отрывка темной литературы, который носят...",kw={"darkshore","insane scribbles","madness","old gods","onu","twilight tome","twilight's hammer","темные берега","безумные каракули","безумие","древние боги","ону","сумеречный фолиант","сумеречный молот"},ang={["class:Priest"]="Жрецы, чувствительные к ментальным атакам и энергиям Бездны, узнают в извивающихся письменах опасное проявление безумия, прямо противоположное ясности Света.",["race:NightElf"]="Для ночных эльфов реликвии Сумеречного Молота — гибельная угроза древнему покою и священным землям Темных берегов."},sec={{t="Сводящая с ума рукопись",b="Взгляд на страницы Сумеречного фолианта крайне опасен для рассудка смертных. Письмена извиваются на пергаменте, а изящные узоры на глазах читателя превращаются в гротескные, тревожные образы. Даже вырвать один лист — эти Безумные каракули — тяжкое испытание: у владельца кружится голова и мутится сознание. Несмотря на хаотичность письмен, пергамент гудит изначальной, глубоко древней магией, связанной с темными силами, давно погребенными под Азеротом."},{t="Подсказки для Древних",b="Если принести каракули Ону, почтенному древню, управляющему Рощей Древних, они позволяют увидеть, какие посягательства губят Темные берега. Ону узнает хаотическую энергию на пергаменте — несомненный след Древних богов. Для защитников Калимдора разбор этих каракулей — важный шаг к тому, чтобы выяснить, зачем Сумеречный Молот собрался на окутанных туманом берегах."}},faq={{q="Что будет, если попытаться прочесть эти каракули?",a="Текст трудно поддается переводу. От одного взгляда на пергамент буквы плывут, а окружающие узоры превращаются в жуткие формы, вызывая внезапное головокружение и душевное истощение у всякого, кто пытается их разобрать.",al={"reading insane scribbles","what does the text say","can you read the scribbles","читать безумные каракули","что написано в тексте","можно ли прочесть каракули"}},{q="Откуда вырваны эти каракули?",a="Они вырваны из Сумеречного фолианта — мерзкого гримуара, который хранят культисты Сумеречного Молота, действующие на Темных берегах.",al={"where do scribbles come from","twilight tome origin","откуда каракули","сумеречный фолиант происхождение"}},{q="Кто может понять или изучить каракули?",a="Найденный пергамент изучает Древо Мудрости Ону. Опираясь на знания многих веков, Ону чувствует древнюю изначальную магию, связывающую чернила, и пытается выяснить, зачем культ явился в этот край.",al={"who wants the scribbles","onu scribbles","кому нужны каракули","ону каракули"}},{q="Какая сила исходит от пергамента?",a="Пергамент пульсирует хаотической изначальной магией, связанной с Древними богами, — отражением темных божеств, которым поклоняется Сумеречный Молот.",al={"what magic is in the scribbles","magic type","какая магия в каракулях","тип магии"}}},fp="16,345,22.508.0,22.439.1,48.240.0,37.119.0,42.206.0,47.134.0"}
P.entries["item:inscribed-bark"] = {n="Исписанная кора",s="Исписанная кора — живой пергамент, который древнее Древо Оракула доверяет доставить верховному друиду Фэндралу Оленьему Шлему весть о состоянии Тельдрассила. Это официальный отчет о ветвях Мирового Древа и угрозах, все еще тревожащих его леса.",h="Исписанная кора — живой пергамент, который древнее Древо Оракула доверяет доставить верховному друиду...",kw={"cenarion circle","darnassus","fandral staghelm","inscribed bark","oracle tree","teldrassil","круг кенария","дарнасс","фэндрал олений шлем","исписанная кора","древо оракула","тельдрассил"},ang={["class:Druid"]="Друиды видят в этой исписанной коре срочное донесение древнего союзника, указывающее на хрупкое равновесие и постоянные недуги, терзающие юное Мировое Древо.",["race:NightElf"]="Для кальдораев послания на коре древних деревьев — символ священной связи между природой и ее стражами, соединяющий дикие рощи и мраморные террасы Дарнасса."},sec={{t="Послание от Оракула",b="Эта исписанная кора, вырезанная из священной древесины Древа Оракула, служит прямым посланием от древнего стража руководству Круга Кенария в Дарнассе. После того как искатели приключений усмиряют вторгшихся в чащи гарпий, Древо Оракула вверяет им этот знак, не желая рисковать простыми гонцами на оскверненных тропах ветвей. Написанное сообщает верховному друиду Фэндралу Оленьему Шлему как о недавних победах, так и о более глубокой тревожной порче, которая по-прежнему сжимает Тельдрассил."}},faq={{q="Что такое Исписанная кора?",a="Это кусок коры, исписанный Древом Оракула, с отчетом о здоровье и опасностях ветвей, предназначенный верховному друиду Фэндралу Оленьему Шлему в Дарнассе.",al={"what is inscribed bark","oracle tree bark","inscribed bark purpose","что такое исписанная кора","кора древа оракула","для чего исписанная кора"}},{q="Кто отправляет это послание и зачем?",a="Древо Оракула вручает его искателям приключений после того, как они прогонят гарпий из гнезд. Опасаясь посылать обычных гонцов по опасным лесным тропам, древний доверяет доставить отчет проверенному путнику.",al={"who wrote inscribed bark","who gives inscribed bark","oracle tree messenger","кто написал исписанную кору","кто дает исписанную кору","гонец древа оракула"}},{q="Как верховный друид Фэндрал Олений Шлем реагирует на послание?",a="Фэндрал признает, что изгнание гарпий дало передышку, но с досадой отмечает, что более глубокие проблемы остаются. Отчет усиливает его постоянные опасения: вернет ли его работа в Тельдрассиле ночным эльфам утраченное бессмертие.",al={"fandral reaction bark","what does fandral say about bark","реакция фэндрала на кору","что фэндрал говорит о коре"}}},fp="14,252,25.522.0,23.172.0,31.233.0,58.264.1"}
P.entries["item:intact-raptor-horn"] = {n="Невредимый рог ящера",s="Невредимый рог, добытый у хищных ящеров, рыщущих по саваннам Степей. В безупречном состоянии он ценится предприимчивым гоблином, желающим воспользоваться слухами об уме ящеров.",h="Невредимый рог, добытый у хищных ящеров, рыщущих по саваннам Степей.",kw={"intact horn","ishamuhale","mebok mizzyrix","raptor horn","ratchet","smart drinks","sunscale scytheclaw","takk the leaper","невредимый рог","ишамухал","мебок миззрикс","рог ящера","кабестан","умные напитки","солнечный косарь","такк прыгун"},ang={["class:Hunter"]="Чтобы добыть целый трофейный рог, нужно чисто убить зверя, а это доказывает вашу меткость в схватке с одними из самых свирепых хищников саванн.",["profession:Cooking"]="Хотя Мебок собирается растирать рога для настоев на вине, опытные выживальщики знают, что части ящеров обычно лучше подходят для изготовления орудий, чем для приятной кухни."},sec={{t="Сомнительный ингредиент",b="Обычные охотники ценят части ящеров — шкуры, когти и трофеи, но целые рога в полевых условиях добыть сложнее. В портовом городе Кабестан эксцентричный гоблин-алхимик Мебок Миззрикс выдвинул дикую теорию о местной фауне: раз ящеры Степей хитрее своих сородичей в других краях, он подозревает, что их разум хранится прямо в рогах. Растирая целые рога и варя из них тонизирующие настои, Мебок надеется разлить этот предполагаемый гений по бутылкам и продавать как «умные напитки»."},{t="Охота на стаи",b="Безупречные рога нельзя просто отколоть у любого молодого зверя. Чтобы получить пригодный для варки материал, охотникам приходится брать их у особенно свирепых хищников, таких как солнечные косари, бродящие по южным равнинам и северным границам близ Ясеневого леса. Легендарные грозы саванны, такие как Такк Прыгун и неуловимый Ишамухал, тоже носят рога, достаточно крепкие, чтобы уцелеть в схватках на охоте."}},faq={{q="Кому нужны эти невредимые рога ящеров?",a="Их ищет Мебок Миззрикс, гоблин-торговец и начинающий пивовар из Кабестана. Он верит, что целые рога — ключ к его следующему способу быстро разбогатеть.",al={"who needs raptor horns","horn buyer","who buys raptor horn","кому нужны рога ящеров","покупатель рогов","кто покупает рог ящера"}},{q="Почему рога должны быть невредимыми?",a="Мебок собирается растереть их в мелкий порошок для приема внутрь. Сколотые или сломанные рога либо выбрасывают при охоте, либо считают истощенными: в них нет полной силы, на которую гоблин рассчитывает в своих рецептах.",al={"why intact","shattered horns","почему невредимый","сломанные рога"}},{q="У каких ящеров бывают такие рога?",a="Чаще всего они встречаются у взрослых солнечных косарей, бродящих на северных и южных окраинах Степей, а также у известных уникальных ящеров, таких как Ишамухал и Такк Прыгун.",al={"where do horns drop","which raptors","who drops intact horn","где падают рога","какие ящеры","с кого падает невредимый рог"}},{q="Правда ли, что рога ящеров делают умнее?",a="Хотя ящеры Степей известны необычной стайной хитростью и слаженностью, мысль о том, что их разум хранится в рогах или передается через напиток, — недоказанная гоблинская затея.",al={"do smart drinks work","are raptors smart","raptor intelligence","работают ли умные напитки","умны ли ящеры","разум ящеров"}}},fp="18,211,25.550.0,19.428.0,36.164.0,35.223.0,25.191.0,42.194.0"}
P.entries["item:intrepid-strongbox-key"] = {n="Ключ от сейфа на \"Отважном\"",s="Ключ от сейфа на «Отважном» — ржавый железный ключ, который ревниво хранил капитан Халиндор, командир обреченного корабля Альянса «Отважный». Даже в нежизни капитан сжимает его, держа под замком проклятый артефакт, погубивший его команду у побережья Болотины.",h="Ключ от сейфа на «Отважном» — ржавый железный ключ, который ревниво хранил капитан Халиндор, командир...",kw={"captain halyndor","cursed crew","glorin steelbrow","intrepid","shipwreck","strongbox","third fleet","wetlands","капитан халиндор","проклятая команда","глорин стальной лоб","отважный","кораблекрушение","сейф","третья флотилия","болотина"},ang={["class:Priest"]="Ключ отпирает артефакт мерзкой некротической силы: чтобы очистить его и упокоить души команды, нужны священные обряды жреца Менетилов Глорина Стального Лба.",["faction:Alliance"]="Ключ принадлежал командиру Третьей флотилии Альянса, чья трагическая гибель у побережья Гавани Менетилов остается открытой раной для уцелевших в гавани."},sec={{t="Тайна капитана",b="Во время крушения Третьей флотилии у штормовых берегов Болотины военный корабль «Отважный» был разбит, а его команда превратилась в неупокоенных проклятых духов. Капитан Халиндор одержимо охранял загадочный предмет, спрятанный в тяжелом сейфе корабля. После смерти его призрачная фигура по-прежнему бродит по залитой водой палубе и не желает расставаться с ржавым ключом, отпирающим самый глубокий и темный груз трюма."},{t="Разрыв уз",b="Забрать ключ у капитана Халиндора — единственный способ открыть запертый сейф «Отважного» и достать проклятую реликвию, которая удерживает команду в муках. Лишь добыв предмет с помощью этого ключа, его можно передать дворфу-жрецу Глорину Стальному Лбу в Гавани Менетилов для очищения."}},faq={{q="У кого находится Ключ от сейфа на «Отважном»?",a="Ключ у капитана Халиндора, призрачного командира, который расхаживает по верхней палубе северного затонувшего корабля у северо-восточного побережья Болотины.",al={"who has the key","intrepid key drop","halyndor key","у кого ключ","ключ отважного","ключ халиндора"}},{q="Что открывает Ключ от сейфа на «Отважном»?",a="Он отпирает запертый сейф «Отважного», который лежит под водой в разбитом корпусе затонувшего корабля под капитанской палубой.",al={"what does it unlock","intrepid strongbox location","where is the chest","что он открывает","где сейф отважного","где сундук"}},{q="Почему сейф был заперт?",a="Капитан Халиндор запер в сундуке темный проклятый предмет, чтобы спрятать его и уберечь, но его неугасающее зло в итоге погубило корабль и обрекло команду на нежизнь.",al={"what was in the chest","why was it locked","что было в сундуке","почему он был заперт"}},{q="Кто может очистить проклятый предмет из сундука?",a="Глорин Стальной Лоб, дворф-жрец из Гавани Менетилов, обладает священными познаниями, нужными для очищения проклятого артефакта после того, как сундук будет открыт.",al={"who cleanses it","glorin steelbrow chest","кто очищает предмет","глорин стальной лоб сундук"}}},fp="22,284,18.424.0,17.321.1,39.150.0,42.138.0,34.176.0,49.160.0"}
P.entries["item:invisibility-liquor"] = {n="Напиток невидимости",s="Напиток невидимости — крепкое алхимическое зелье, приготовленное из редких листьев хрустальных водорослей, что растут в Элвиннском лесу. Он делает пьющего на короткое время невидимым и становится ключом к тайному плану двух влюбленных, которые хотят обойти враждующие семьи.",h="Напиток невидимости — крепкое алхимическое зелье, приготовленное из редких листьев хрустальных водорослей...",kw={"crystal kelp","elwynn forest","invisibility liquor","maybell maclure","stonefield feud","the escape","tommy joe stonefield","хрустальные водоросли","элвиннский лес","напиток невидимости","мейбелл маклюр","вражда стоунфилдов","побег","томми джо стоунфилд"},ang={["class:Mage"]="Пока арканисты Кирин-Тора годами оттачивают иллюзии и заклинания невидимости, жители Элвинна довольствуются грубой подделкой из перебродившего спирта и размокших водорослей.",["race:Human"]="Это варево показывает абсурдные крайности жестокой деревенской вражды кланов Стоунфилдов и Маклюров в Элвиннском лесу."},sec={{t="Зелье для влюбленных",b="Давняя вражда Стоунфилдов и Маклюров делает мирные встречи между их семьями почти невозможными. Когда юный Томми Джо Стоунфилд хочет встретиться с Мейбелл Маклюр вдали от глаз родни, обычной скрытности недостаточно. Напиток невидимости дает необычное решение: хмельное зелье, отводящее взгляд от выпившего, — его хватает, чтобы незаметно пересечь спорные поля."},{t="Необычная алхимия Элвиннского леса",b="Это снадобье варят из листьев хрустальных водорослей, собранных в местных водах, кишащих мурлоками: простое самогоноварение смешивается с сырыми магическими реагентами. Хотя оно незаконно и, возможно, опасно для питья, его хватает, чтобы Мейбелл исчезла из виду, едва коснувшись губами, и ускользнула в лес на тайное свидание."}},faq={{q="Что делает Напиток невидимости?",a="Это крепкий алкогольный напиток с магическими свойствами, который на время делает выпившего его полностью невидимым.",al={"liquor effects","invisibility brew","what does it do","эффект напитка","зелье невидимости","что он делает"}},{q="Кто использует Напиток невидимости?",a="Напиток приносят Мейбелл Маклюр, чтобы она могла скрыться от семьи и тайком уйти на встречу с возлюбленным, Томми Джо Стоунфилдом, несмотря на вражду их семей.",al={"who drinks it","maybell maclure liquor","кто его пьет","мейбелл маклюр напиток"}},{q="Как делают этот напиток?",a="Его варят из листьев хрустальных водорослей, собранных на речном дне и берегах озер Элвиннского леса, где мурлоки часто прячут эти волшебные растения.",al={"liquor ingredients","crystal kelp liquor","состав напитка","хрустальные водоросли напиток"}},{q="Могут ли игроки сами выпить Напиток невидимости?",a="Нет. Это особый предмет для задания, предназначенный только для передачи Мейбелл Маклюр в рамках ее плана тайком уйти от семьи.",al={"can i drink it","drink invisibility liquor","можно ли выпить","выпить напиток невидимости"}}},fp="19,300,32.449.0,25.363.1,33.126.0,33.177.0,23.146.0,53.144.0"}
P.entries["item:iron-pike"] = {n="Железная пика",s="Железные пики — прочные строительные материалы, которые отправили из Штормграда для ремонта Моста Безмолвия в Приозерье. Груз был захвачен и разграблен гноллами Красногорья, и городу не хватает самого необходимого для восстановления.",h="Железные пики — прочные строительные материалы, которые отправили из Штормграда для ремонта Моста Безмолвия в...",kw={"everstill bridge","foreman oslow","iron pike","iron rivet","lakeshire","redridge gnolls","redridge mountains","мост безмолвия","штейгер ослоу","железная пика","железная клепка","приозерье","гноллы красногорья","красногорье"},ang={["faction:Alliance"]="Возвращение украденных строительных припасов у диких гноллов помогает защитить важные переправы Приозерья и укрепить восточную границу Штормграда от агрессии Черной горы.",["profession:Blacksmithing"]="Эти тяжелые конструкционные пики показывают, какое напряжение легло на местных кузнецов, весь запас сырого железа которых пришлось пустить на оружие."},sec={{t="Похищенный груз каравана",b="Когда Приозерье подверглось недавним нападениям орков Черной горы, городские запасы металла переплавили на доспехи, клинки и боеприпасы для обороны. Из-за нехватки местные строители запросили из Штормграда новую партию железа. Но до города материалы не дошли: стая гноллов Красногорья захватила караван на дороге. Гноллы утащили ящики с железными пиками и клепками на север, в холмы, остановив важный ремонт Моста Безмолвия."},{t="Восстановление пролета",b="Штейгер Ослоу, руководящий восстановлением Моста Безмолвия, рассчитывает на искателей приключений, которые проникнут на земли гноллов и вернут украденные материалы. Без этих тяжелых железных пик, нужных для укрепления каменно-деревянного каркаса, Приозерье остается частично отрезанным от северной дороги и уязвимым для новых набегов."}},faq={{q="Почему у гноллов строительные пики?",a="Гноллы устроили засаду на караван с припасами, следовавший из Штормграда в Приозерье. Они рассеялись по холмам Красногорья с ящиками украденных строительных материалов, среди которых были железные пики и заклепки.",al={"why do gnolls have iron pikes","where did gnolls get iron pikes","почему у гноллов железные пики","откуда у гноллов железные пики"}},{q="Кому в Приозерье нужны эти железные пики?",a="Они нужны Штейгеру Ослоу для восстановления Моста Безмолвия, соединяющего Приозерье через Озеро Безмолвия. В городе нет запасного железа: местные запасы переплавили на оружие и доспехи во время недавних нападений орков.",al={"who wants iron pikes","foreman oslow iron pikes","кому нужны железные пики","штейгер ослоу железные пики"}},{q="Где можно вернуть эти железные пики?",a="Они у гноллов Красногорья, расположившихся в холмах и на хребтах к северу от Приозерья.",al={"where to find iron pikes","iron pike location","где найти железные пики","железные пики местонахождение"}},{q="Почему Приозерье не может само выковать железные пики?",a="Приозерье исчерпало местные запасы железа в борьбе с орками Черной горы, переплавив каждый обрезок металла на мечи, пули и защитное снаряжение. Городу пришлось просить Штормград о новом конструкционном железе.",al={"why did lakeshire order iron","lakeshire iron shortage","почему приозерье заказало железо","нехватка железа в приозерье"}}},fp="9,247,20.497.0,19.340.0,47.192.0,40.226.0,40.89.0,55.214.0"}
P.entries["item:iron-pommel"] = {n="Железное навершие",s="Железное навершие — последний недостающий фрагмент Жезла Дартола, созданного давно умершим чародеем Дартолом. Ночные эльфы Астранаара искали его, чтобы ослабить нападения фурболгов на свой народ. Жезл был передан на хранение друидам Обители Дор'Данил, но был утерян, когда их убежище было разгромлено и захвачено слизями.",h="Железное навершие — последний недостающий фрагмент Жезла Дартола, созданного давно умершим чародеем Дартолом.",kw={"ashenvale","dartol's rod","dor'danil","iron pommel","oso's chest","raene's cleansing","shael'dryn","ясеневый лес","жезл дартола","дор'данил","железное навершие","сундук осо","очищение рейн","шаэл'дрин"},ang={["class:Druid"]="Навершие — мрачный памятник павшим друидам Дор'Данил, чей священный долг закончился бойней на краю леса.",["faction:Alliance"]="Возвращение навершия завершает важный этап в сборе Жезла Дартола — необходимого средства защиты Ясеневого леса от ползучей порчи."},sec={{t="Бремя павшего круга",b="Жезл Дартола разделили и разбросали по Ясеневому лесу, чтобы защитить его таинственную силу. Железное навершие поручили друидам-ночным эльфам, жившим у дороги, ведущей на юг к Степям. В уединенной Обители Дор'Данил случилась трагедия: круг был перебит, а тихое убежище погрузилось в разоренное безмолвие. Навершие исчезло в последствиях бойни, поглощенное жуткими булькающими слизями, что теперь бродят по оскверненной поляне."},{t="Добыто из трясины",b="Друиды мертвы, и чтобы найти навершие, нужно прочесать оскверненную лощину к югу от Заставы Расщепленного Дерева. Реликвия оставалась запертой в прочном сундуке. Искатели приключений, пробиваясь через оскверненные слизи, находят проглоченный сундук целым в едкой массе слизи и наконец добывают последнюю деталь для восстановления жезла."}},faq={{q="Для чего нужно Железное навершие?",a="Железное навершие — последняя деталь, нужная для воссоздания Жезла Дартола. Если принести его Шаэл'дрин у лунного колодца, она починит древний артефакт, и им можно будет ослабить нападения фурболгов на ночных эльфов Ясеневого леса.",al={"iron pommel purpose","why do i need iron pommel","what does iron pommel do","назначение железного навершия","зачем нужно железное навершие","что делает железное навершие"}},{q="У кого навершие было вначале?",a="Его вверили друидам-ночным эльфам, жившим у дороги к Степям. К несчастью, круг был перебит до того, как жезл удалось собрать, и их убежище лежит в руинах.",al={"who guarded the pommel","who had iron pommel","dor'danil druids","кто охранял навершие","у кого было железное навершие","друиды дор'данил"}},{q="Где находится навершие?",a="Навершие заперто в сундуке внутри одной из оскверненных слизей, бродящих по оскверненной лощине к востоку от главной дороги, к югу от Заставы Расщепленного Дерева и к северу от границы Степей.",al={"iron pommel location","where is iron pommel","where do i get iron pommel","где железное навершие","где найти железное навершие","где взять железное навершие"}},{q="Кому нужно отнести навершие?",a="Навершие нужно отнести Шаэл'дрин, дриаде, ухаживающей за лунным колодцем к востоку от Озера Ирис, — она владеет ритуальными знаниями для восстановления Жезла Дартола.",al={"turn in iron pommel","where to take iron pommel","who wants the pommel","сдать железное навершие","куда отнести навершие","кому нужно навершие"}}},fp="11,335,23.480.0,23.343.1,33.241.0,30.195.0,26.190.0,29.153.0"}
P.entries["item:iron-rivet"] = {n="Железная клепка",s="Железные клепки — прочный крепеж, изготовленный в Штормграде для восстановления разрушенного Моста Безмолвия в Приозерье. После того как гноллы Красногорья напали на караван и разграбили его, эти тяжелые металлические детали оказались разбросаны по лагерям гноллов в северных холмах.",h="Железные клепки — прочный крепеж, изготовленный в Штормграде для восстановления разрушенного Моста Безмолвия...",kw={"everstill bridge","foreman oslow","iron pike","iron rivet","lakeshire","redridge gnolls","redridge mountains","мост безмолвия","штейгер ослоу","железная пика","железная клепка","приозерье","гноллы красногорья","красногорье"},ang={["faction:Alliance"]="Возвращение этих украденных припасов напрямую помогает местной инфраструктуре Приозерья и сдерживает осмелевших гноллов, угрожающих городу.",["profession:Blacksmithing"]="Этот прочный крепеж демонстрирует стандартное штормградское кузнечное дело: его ковали специально для крупных гражданских сооружений, таких как каменно-деревянные мосты."},sec={{t="Похищенный груз каравана",b="Когда Приозерье столкнулось с повторными нападениями орков Черной горы, городскому совету пришлось переплавить запасы конструкционного железа на срочное оружие, доспехи и боеприпасы. Как только непосредственная угроза миновала, Штейгер Ослоу запросил в Штормграде новые строительные материалы для ремонта разрушенного Моста Безмолвия. Однако караван с грузом был подло атакован местными гноллами Красногорья еще до прибытия в город. Вьючных животных и повозки утащили в холмы к северу от Озера Безмолвия, и важные материалы, такие как железные клепки и пики, оказались рассеяны между стаями гноллов."},{t="Ремонт моста",b="Без этих тяжелых железных клепок ремонт Моста Безмолвия не может безопасно продолжаться. Каменно-деревянный каркас, перекинутый через озеро, требует усиленного металлического крепежа, чтобы выдерживать вес повозок и путников. Вернуть клепки прямо из лагерей гноллов необходимо, чтобы восстановить важную связь Приозерья с западными долинами и защитить границы города от новых набегов."}},faq={{q="Для чего нужны Железные клепки?",a="Это тяжелый конструкционный крепеж, нужный Штейгеру Ослоу для ремонта поврежденного Моста Безмолвия в Приозерье, лишившегося своего железа во время боев с орками Черной горы.",al={"iron rivet purpose","why need iron rivets","what are iron rivets for","назначение железной клепки","зачем нужны железные клепки","для чего железные клепки"}},{q="Почему эти клепки у гноллов?",a="Караван с припасами, отправленный из Штормграда, был захвачен гноллами Красногорья на дороге. Мародеры увезли строительный груз, утащив клепки и железные пики в свои лагеря к северу от Приозерья.",al={"why gnolls have rivets","how gnolls got iron rivets","who stole the rivets","почему у гноллов клепки","как гноллы получили железные клепки","кто украл клепки"}},{q="Почему в Приозерье изначально не хватало железа?",a="Во время недавнего вторжения орков защитникам Приозерья пришлось переплавить все запасы железа на мечи, пули и доспехи, чтобы пережить осаду.",al={"lakeshire iron shortage","why no iron in lakeshire","нехватка железа в приозерье","почему нет железа в приозерье"}},{q="Кто ищет эти клепки?",a="Штейгер Ослоу, мастер-строитель, руководящий восстановлением Моста Безмолвия на берегу Приозерья.",al={"who wants iron rivets","who takes iron rivets","кому нужны железные клепки","кто принимает железные клепки"}}},fp="10,290,20.609.0,18.418.0,30.186.0,36.215.0,46.158.0,32.112.0"}
P.entries["item:iron-shaft"] = {n="Железная ось",s="Железная ось — металлический фрагмент Жезла Дартола, реликвии, которую друг Раэны Волкопас Теронис искал, надеясь ослабить нападения фурболгов на Ясеневый лес. Ее достают из запертого сундука у границы Оскверненного леса, и она служит важной частью для восстановления реликвии защитниками Ясеневого леса.",h="Железная ось — металлический фрагмент Жезла Дартола, реликвии, которую друг Раэны Волкопас Теронис искал...",kw={"ashenvale","crazed ancient","dartol's rod","felwood","iron shaft","raene's cleansing","shael'dryn","withered ancient","wooden key","ясеневый лес","безумный древень","жезл дартола","оскверненный лес","железная ось","очищение раэны","шаэл'дрин","иссохший древень","деревянный ключ"},ang={["class:Druid"]="Сборка Жезла Дартола тесно связана с друидской заботой о природе: забытые орудия помогают исцелять раненые земли.",["race:NightElf"]="Добыть Железную ось — печальный долг: придется убивать любимых лесных древней, ставших жертвами демонической порчи, сочащейся из Оскверненного леса."},sec={{t="Часть Жезла Дартола",b="Жезл Дартола создал Дартол, а его части были рассеяны по Ясеневому лесу; одну даже передали на хранение друидам Дор'Данила. Железная ось — прочный металлический стержень инструмента, спрятанный в запертом сундуке в укромной поляне у северной границы Ясеневого леса, недалеко от оскверненных земель Оскверненного леса."},{t="Порча леса",b="Чтобы заполучить Железную ось, нужно добыть ее ключ у местных древней, что некогда оберегали эти леса. Из-за демонической порчи, расползающейся на юг из Оскверненного леса, древние стражи, такие как Безумные и Иссохшие древни, лишились рассудка. Дриада Шаэл'дрин поручает путникам добыть ось, чтобы стержень можно было перековать и завершить дело павшего Терониса."}},faq={{q="Для чего нужна Железная ось?",a="Железная ось — часть Жезла Дартола, сломанной реликвии. Ее собирают, чтобы дриада Шаэл'дрин помогла собрать жезл заново и завершить дело Терониса, который искал его, чтобы ослабить нападения фурболгов на Ясеневый лес.",al={"iron shaft purpose","what is this shaft","why do i need iron shaft","для чего железная ось","что это за ось","зачем мне железная ось"}},{q="Где найти Железную ось?",a="Она заперта в сундуке на тихой поляне к западу от дороги к Оскверненному лесу, в северной части Ясеневого леса.",al={"iron shaft location","find iron shaft","where is the chest","где железная ось","найти железную ось","где сундук"}},{q="Как открыть сундук с осью?",a="Для сундука нужен Деревянный ключ. Его носят оскверненные древни — Безумные и Иссохшие древни, — бродящие в лесу к северо-востоку от Приюта в Ночных Лесах.",al={"how to open chest","chest key","iron shaft key","как открыть сундук","ключ от сундука","ключ железной оси"}},{q="Кто ищет Железную ось?",a="Шаэл'дрин, дриада у лунного колодца в центре Ясеневого леса, направляет искателей приключений собирать части Жезла Дартола, чтобы очистить лес.",al={"who wants iron shaft","iron shaft quest giver","кто ищет железную ось","кто выдает задание железная ось"}}},fp="10,303,23.355.0,19.392.1,32.214.0,30.128.0,47.166.0,34.167.0"}
P.entries["item:ironband-s-progress-report"] = {n="Отчет о достижениях Железняка",s="Отчет о достижениях Железняка — письменное донесение о трудностях на раскопках Геолога Сталекрута в восточном Лок Модане. В нем рассказывается о медленной работе, которой мешают агрессивные трогги, и содержится срочная просьба о порохе.",h="Отчет о достижениях Железняка — письменное донесение о трудностях на раскопках Геолога Сталекрута в восточном...",kw={"blastpowder","explorers league","ironband","jern hornhelm","loch modan","prospector stormpike","thelsamar","troggs","порох","лига исследователей","сталекрут","джерн шлеморог","лок модан","геолог грозовая вершина","телсамар","трогги"},ang={["profession:Mining"]="Шахтеры слишком хорошо понимают, как нужен порох для расчистки упрямых скал, и как опасно, когда запасы пропадают на землях троггов.",["race:Dwarf"]="Для дворфов-исследователей и шахтеров это донесение отражает опасную реальность раскопок древних мест титанов в сердце Каз Модана."},sec={{t="Просьба о порохе",b="Раскопки Геолога Сталекрута в Лок Модане постоянно срываются из-за местных троггов. Чтобы дело двигалось, Сталекрут составил этот отчет, вновь заявив об острой нужде во взрывчатом порошке. Отчет несут сперва Джерну Шлеморогу в Телсамар, а затем пересылают в Лигу исследователей в Стальгорне; в нем описаны остановки работ и запрошены тяжелые боеприпасы. Донесение быстро вызывает удивление у руководства лиги: обильный запас взрывчатого порошка был отправлен Сталекруту несколько недель назад, и начальство гадает, куда делись прежние поставки."}},faq={{q="Что такое Отчет о достижениях Железняка?",a="Это официальное донесение, написанное Геологом Сталекрутом о состоянии его раскопок в Лок Модане: он жалуется на помехи от троггов и требует больше пороха.",al={"progress report","ironbands report","what is this report","отчет о достижениях","отчет сталекрута","что это за отчет"}},{q="Кому передают этот отчет?",a="Сначала отчет доставляют Джерну Шлеморогу, местному связному раскопок в Телсамаре. Затем Шлеморог велит доставить его прямо Геологу Грозовой Вершине в штаб Лиги исследователей в Стальгорне.",al={"who gets the report","who do i give the report to","deliver progress report","кому отдать отчет","кто получает отчет","доставить отчет"}},{q="Зачем Сталекруту больше пороха?",a="Сталекрут утверждает, что порох нужен для археологических раскопок, хотя постоянные набеги троггов говорят, что взрывчатка может понадобиться и для защиты. Странно, но и Шлеморог, и Грозовая Вершина считают, что отправили ему много пороха несколько недель назад.",al={"why blastpowder","what happened to the powder","powder shortage","зачем порох","куда делся порох","нехватка пороха"}},{q="Как Геолог Грозовая Вершина реагирует на отчет?",a="Грозовая Вершина в ярости от медленной работы и озадачен тем, что Сталекрут не упоминает огромную партию пороха, отправленную ранее, и спрашивает, куда могли деться боеприпасы.",al={"stormpike reaction","is stormpike mad","реакция грозовой вершины","злится ли грозовая вершина"}}},fp="26,253,20.597.0,35.210.0,25.224.0,40.252.0,50.203.0"}
P.entries["item:ishamuhale-s-fang"] = {n="Клык Ишамухала",s="Клык Ишамухала — охотничий трофей, добытый у Ишамухала, печально известного солнечного ящера по прозвищу Копьезуб в Степях. Его приносят Джорну Заклинателю Небес в Лагере Таурахо, и он служит доказательством победы над одним из самых опасных хищников Калимдора.",h="Клык Ишамухала — охотничий трофей, добытый у Ишамухала, печально известного солнечного ящера по прозвищу...",kw={"barrens","fang","ishamuhale","jorn","raptor","sergra","speartooth","sunscale","taurajo","степи","клык","ишамухал","ящер","джорн","сергра","копьезуб","солнечный ящер","таурахо"},ang={["class:Hunter"]="Добыть клык Копьезуба — важный обряд посвящения в Степях, проверяющий умение следопыта выманить, встретить лицом к лицу и одолеть хитрого верховного хищника.",["race:Tauren"]="Для охотников Таурахо добыча клыка — не бессмысленное убийство, а поглощение дикой силы хищника при сохранении дисциплины и равновесия."},sec={{t="Трофей Копьезуба",b="Ишамухала боятся по всей центральной саванне как самого свирепого из живых солнечных ящеров, верховного охотника, который, как говорят, убивает из хищной страсти, а не от голода. Его выманивают на открытое место свежим мясом жевры у засохшего дерева к северо-западу от Кабестана, и зверь не знает пощады. Отсеченный огромный клык доказывает охотничьим наставникам Орды, что путник победил не просто зверя, но и саму дикость равнин."},{t="Урок умеренности",b="Когда клык приносят Джорну Заклинателю Небес в Лагере Таурахо, его признают чем-то большим, чем кость и кровь. Для таурен лагеря добыть клык Ишамухала значит передать свирепую силу хищника победившему его охотнику. Настоящее испытание после этого — умеренность: овладеть этой дикой яростью, а не позволить ей управлять душой охотника."}},faq={{q="Что такое Клык Ишамухала?",a="Это трофей, снятый с тела Ишамухала, печально известного солнечного ящера по прозвищу Копьезуб, рыщущего по Степям.",al={"ishamuhale tooth","speartooth fang","raptor fang barrens","зуб ишамухала","клык копьезуба","клык ящера степи"}},{q="Кому нужен Клык Ишамухала?",a="Клык приносят Джорну Заклинателю Небес в Лагере Таурахо в рамках охотничих испытаний, которые начинаются у Сергры Черный Шип на Перекрестке.",al={"who do i give ishamuhale fang to","turn in ishamuhale fang","where does ishamuhale fang go","кому отдать клык ишамухала","сдать клык ишамухала","куда нести клык ишамухала"}},{q="Как найти зверя Ишамухала?",a="Ишамухал не бродит открыто. Охотники должны убить свежую жевру и положить ее тушу у мертвого дерева к северо-западу от Кабестана, чтобы выманить ящера из укрытия.",al={"how to get ishamuhale to spawn","summon ishamuhale","where is ishamuhale","как призвать ишамухала","вызвать ишамухала","где ишамухал"}},{q="Что значит для таурен добыча клыка?",a="По словам Джорна Заклинателя Небес, добыча трофея означает, что легендарная сила Ишамухала теперь живет в охотнике, который должен нести бремя применения этой силы с умеренностью и честью.",al={"meaning of the fang","tauren hunter ritual ishamuhale","смысл клыка","ритуал охотников таурен ишамухал"}}},fp="17,251,20.447.0,22.346.1,26.117.0,28.134.0,34.161.0,52.197.0"}
P.entries["item:ivar-s-head"] = {n="Голова Ивара",s="Голова Ивара — жуткое доказательство уничтожения голодного вурдалака Ивара Нечистого в Серебряном бору. Ее ищет Страж смерти Ран Йорик, чтобы обеспечить безопасное выздоровление раненого брата Квинна.",h="Голова Ивара — жуткое доказательство уничтожения голодного вурдалака Ивара Нечистого в Серебряном бору.",kw={"deathstalkers","ivar patch","ivar the foul","ivar's head","quinn yorick","rane yorick","silverpine forest","стражи смерти","делянка ивара","ивар нечистый","голова ивара","квинн йорик","ран йорик","серебряный бор"},ang={["faction:Horde"]="Уничтожение отбившихся остатков Плети вроде Ивара защищает путешествующих гонцов Орды на севере Серебряного бора по пути к Гробнице.",["race:Undead"]="Для разведчиков Отрекшихся дикие вурдалаки — бездумная помеха, срывающая военную разведку и угрожающая зарождающейся безопасности Лордерона."},sec={{t="Отсеченная угроза",b="Разведывая север Серебряного бора по приказу Верховного палача Хадрика, Стражи смерти из Отрекшихся Ран и Квинн Йорик попали в засаду на заброшенной ферме, устроенную диким вурдалаком Иваром Нечистым. Брат с сестрой отбились от твари, но Квинн был тяжело изранен. Оказавшись в ловушке на разрушенной ферме, пока брат поправлялся, Ран не могла безопасно оставить Квинна без присмотра ради выполнения задания. Отсеченная голова Ивара — неоспоримое доказательство, что зверь больше не будет терроризировать усадьбу, и она дает Квинну время восстановиться под присмотром Ран."}},faq={{q="Чья это голова?",a="Голова принадлежала Ивару Нечистому, свирепому вурдалаку, обитавшему на заброшенной ферме под названием Делянка Ивара на севере Серебряного бора.",al={"who is ivar","ivar head identity","what is ivar","кто такой ивар","чья голова ивара","что такое ивар"}},{q="Зачем Ран Йорик голова Ивара?",a="Ран нужно вещественное доказательство гибели Ивара. Ее брат Квинн был сильно изранен тварью и нуждается во времени на исцеление без страха новой засады, прежде чем они смогут доложить Верховному палачу Хадрику.",al={"why rane wants head","ivar head turn in","why kill ivar","зачем рейн голова","сдать голову ивара","зачем убивать ивара"}},{q="Где найти Ивара Нечистого?",a="Ивар Нечистый прячется в ветхом амбаре на Делянке Ивара, наблюдая и выжидая, когда раненые Стражи смерти потеряют бдительность.",al={"ivar location","where is ivar","где ивар","местоположение ивара"}}},fp="11,210,16.614.0,19.138.0,38.210.0,30.142.0"}
P.entries["item:iverron-s-antidote-item"] = {n="Противоядие Иверрона (предмет)",s="Противоядие Иверрона — хрупкое лекарственное снадобье, составленное Диранией Серебряным Сиянием в Тенистой долине. Оно специально сварено, чтобы нейтрализовать смертельный яд местных пауков Паучьего леса, крайне нестабильно и быстро портится после приготовления.",h="Противоядие Иверрона — хрупкое лекарственное снадобье, составленное Диранией Серебряным Сиянием в Тенистой...",kw={"aldrassil","dirania silvershine","iverron","iverron's antidote","shadowglen","spider poison","teldrassil","webwood venom","альдрассил","дирания серебряное сияние","иверрон","противоядие иверрона","тенистая долина","паучий яд","яд паучьего леса","тельдрассил"},ang={["profession:Herbalism"]="Снадобье показывает крайнюю нестабильность местных реагентов Тельдрассила и то, что некоторые травяные средства нужно применять сразу после приготовления.",["race:NightElf"]="Для юных ночных эльфов, начинающих путь в Тенистой долине, спешка с доставкой лекарства Иверрону показывает, как община полагается на быстрые действия и знание трав против подползающей порчи в ветвях Тельдрассила."},sec={{t="Хрупкое лекарство",b="Это противоядие, приготовленное Диранией Серебряным Сиянием в Альдрассиле, рассчитано на то, чтобы побороть сильный яд, поразивший юного ночного эльфа Иверрона. Из-за летучести ингредиентов и травяных катализаторов снадобье годно лишь пять минут после варки. Гонцы должны без промедления бежать на север к пещере Паучьего леса, чтобы доставить зелье, пока оно не превратилось в негодную жижу."}},faq={{q="Для чего нужно Противоядие Иверрона?",a="Оно излечивает Иверрона от ядовитого укуса, полученного от местных пауков Паучьего леса у их пещеры на севере Тенистой долины.",al={"antidote use","what does iverrons antidote do","для чего противоядие","что делает противоядие иверрона"}},{q="Почему у противоядия есть срок годности?",a="Дирания Серебряное Сияние отмечает, что снадобье хрупкое и сохраняет силу лишь пять минут после приготовления. Если его не дать быстро, лечебные свойства полностью разрушаются.",al={"why 5 minutes","antidote timer","why does it expire","почему 5 минут","таймер противоядия","почему оно портится"}},{q="Кто варит противоядие?",a="Дирания Серебряное Сияние, целительница из ночных эльфов в Альдрассиле, в Тенистой долине, варит зелье из собранных ингредиентов, чтобы спасти Иверрона.",al={"who made antidote","antidote maker","кто сделал противоядие","создатель противоядия"}},{q="Что будет, если противоядие испортится?",a="Если время выйдет, зелье портится и больше не действует. Курьер должен вернуться к Дирании Серебряному Сиянию в Альдрассил, чтобы получить свежую порцию.",al={"antidote expired","timer ran out","противоядие испортилось","время вышло"}}},fp="25,241,16.463.0,36.122.0,40.199.0,23.146.0,37.151.0"}
P.entries["item:jade-phial"] = {n="Нефритовый фиал",s="Нефритовый фиал — специально изготовленный сосуд, который выдает ночной эльф-друид Коритрас Лунный Гнев в Доланааре. Он предназначен для того, чтобы безопасно набирать и переносить священную воду из лунных колодцев Тельдрассила и пополнять ею центральный колодец друидов в Дарнассе.",h="Нефритовый фиал — специально изготовленный сосуд, который выдает ночной эльф-друид Коритрас Лунный Гнев в...",kw={"corithras moonrage","crown of the earth","dolanaar","jade phial","moonwell","starbreeze village","teldrassil","коритрас лунный гнев","венец земли","доланаар","нефритовый фиал","лунный колодец","деревня звездного ветра","тельдрассил"},ang={["class:Druid"]="Для юных друидов ношение Нефритового фиала — первый урок попечения: жизненная сила лунных колодцев Тельдрассила требует неизменного почтения и заботы.",["race:NightElf"]="Лунные колодцы воплощают вечную связь кальдораев с Элуной; уход за ними с помощью таких сосудов, как Нефритовый фиал, — священный долг каждого ночного эльфа."},sec={{t="Сосуд для священных вод",b="Тельдрассил усеян лунными колодцами, которые направляют лунную и природную энергию, жизненно важную для общества ночных эльфов и поклонения друидов. Чтобы поддерживать эту гармонию, центральный лунный колодец, которым пользуются друиды в Дарнассе, нужно время от времени пополнять водой из дальних колодцев великой ветви. Коритрас Лунный Гнев вверяет юным посвященным Нефритовый фиал — сосуд, тщательно подготовленный для сбора чистой воды из лунного колодца возле Деревни Звездного Ветра так, чтобы не нарушить ее тонкую духовную силу."}},faq={{q="Для чего нужен Нефритовый фиал?",a="Нефритовый фиал служит для сбора священной воды из лунного колодца недалеко от Деревни Звездного Ветра. Наполненный фиал нужно вернуть Коритрасу Лунному Гневу в Доланааре, чтобы помочь пополнить лунный колодец друидов в Дарнассе.",al={"jade phial purpose","why do i need jade phial","what does jade phial do","назначение нефритового фиала","зачем нужен нефритовый фиал","что делает нефритовый фиал"}},{q="Кто выдает Нефритовый фиал?",a="Коритрас Лунный Гнев, ночной эльф-друид из Доланаара, выдает фиал искателям приключений, проходящим обряд, известный как Венец Земли.",al={"who gives jade phial","where to get jade phial","corithras jade phial","кто выдает нефритовый фиал","где взять нефритовый фиал","коритрас нефритовый фиал"}},{q="Куда попадает вода из этого фиала?",a="Воду, собранную в фиал, доставляют, чтобы поддерживать и пополнять центральный лунный колодец, за которым ухаживают друиды Кенария в столице Дарнасс.",al={"where does moonwell water go","jade phial destination","who uses the water","куда идет вода из лунного колодца","назначение нефритового фиала","кто использует воду"}}},fp="10,245,26.506.0,32.226.0,28.148.0,44.166.0"}
P.entries["item:jennea-s-flask"] = {n="Фляга Джиннии",s="Фляга Джиннии — пустой сосуд, который начинающим магам выдает волшебница Джинния Пушка в Квартале магов Штормграда. Она нужна, чтобы набрать пробу воды из Зеркального озера и изучить возмущения в местных линиях силы.",h="Фляга Джиннии — пустой сосуд, который начинающим магам выдает волшебница Джинния Пушка в Квартале магов...",kw={"elwynn forest","jennea cannon","jennea's flask","mirror lake","stormwind","water sample","wizard's sanctum","элвиннский лес","джинния пушка","фляга джиннии","зеркальное озеро","штормград","проба воды","святилище волшебника"},ang={["class:Mage"]="Для магов-новичков эта фляга — одно из первых полевых поручений Святилища волшебника, доказательство того, что вы способны вести тонкие тайные исследования и следить за устойчивостью линий силы."},sec={{t="Сосуд для тайных исследований",b="После катастрофических магических потрясений по всему Азероту естественный поток тайных энергий вырвался из древних русел. В Штормграде Джинния Пушка стремится понять, насколько глубоко эти магические сдвиги затронули Элвиннский лес. Она выдает эту простую стеклянную флягу многообещающим ученикам и отправляет их к юго-западу от городских ворот, чтобы набрать свежей воды у подножия водопада на Зеркальном озере. Наполненная фляга защищает хрупкую пробу, чтобы ее в целости доставили в Святилище волшебника для тайного анализа."},{t="Защита вод",b="Главная причина использования фляги — общественная безопасность. Если колеблющиеся линии силы начнут просачиваться магической порчей в Зеркальное озеро, окружающая природа и все, кто пьет его воду, могут пострадать от странных или опасных недугов. Чистая проба во фляге Джиннии позволяет магам Штормграда обнаружить невидимые магические следы раньше, чем зараженные потоки незаметно распространятся по окрестностям."}},faq={{q="Для чего нужна Фляга Джиннии?",a="Это пустой сосуд, который выдают вам, чтобы набрать пробу воды из водопада на Зеркальном озере в Элвиннском лесу.",al={"flask purpose","what does the flask do","use of flask","назначение фляги","что делает фляга","для чего фляга"}},{q="Кто выдает эту флягу?",a="Ее выдает Джинния Пушка, наставница магов в Святилище волшебника в Штормграде.",al={"who gives flask","jennea flask source","кто выдает флягу","откуда фляга джиннии"}},{q="Зачем Джиннии вода из Зеркального озера?",a="Недавние магические конфликты нарушили течение магии по всему миру. Джинния опасается, что эти блуждающие потоки просачиваются в природные воды Элвинна, что может угрожать всем, кто пьет из озера.",al={"why mirror lake water","why water sample","зачем вода зеркального озера","зачем проба воды"}},{q="Где нужно наполнить флягу?",a="Флягу нужно отнести к подножию водопада, впадающего в Зеркальное озеро, к юго-западу от главных ворот Штормграда в Элвиннском лесу.",al={"where to fill flask","flask location","lake location","где наполнить флягу","место для фляги","где озеро"}}},fp="14,219,28.557.0,19.431.0,32.114.0,25.104.0,44.206.0,28.147.0"}
P.entries["item:jitters-completed-journal"] = {n="Законченный дневник Трясунчика",s="Законченный дневник Трясунчика — рукописный рассказ о мрачных трагедиях Сумеречного леса, в частности о резне на ферме Свена Йоргена. Опасаясь мести, затворник Трясунчик отдает законченный текст, чтобы очистить свое имя и пролить свет на зловещие силы, преследующие этот край.",h="Законченный дневник Трясунчика — рукописный рассказ о мрачных трагедиях Сумеречного леса, в частности о резне...",kw={"bishop farthing","cathedral of light","dark riders","duskwood","forlorn rowe","jitters","journal","morbent fel","sven yorgen","епископ фартинг","собор света","темные всадники","сумеречный лес","покинутая усадьба","трясунчик","дневник","морбент скверн","свен йорген"},ang={["class:Priest"]="Доставляя дневник епископу Фартингу в Собор Света, жрецы напрямую служат очищению от нечестивой скверны с помощью священных реликвий.",["faction:Alliance"]="Дневник — суровое напоминание о том, как глубоко Сумеречный лес погряз в опасностях, пока руководство Штормграда занято другим."},sec={{t="Признание труса",b="Когда на ферму Свена напали, Трясунчик в ужасе бежал, бросив среди руин свой недописанный дневник. Законченный дневник восполняет пробелы того страшного дня и рассказывает, как таинственные темные всадники перебили семью Свена. Несколько недель дневник был единственным утешением Трясунчика, скрывавшегося в Сумеречном лесу. Он охотно отдает готовый том, отчаянно желая объяснить, что случилось на самом деле, и надеясь, что записанная правда убережет его от яростного гнева Свена."},{t="Раскрытие тьмы",b="Дневник не только утишает старое горе: он побуждает Свена рассказать, что видел всадников в черных плащах, беседовавших с чародеем Морбентом Скверном в Покинутой усадьбе. Свен отправляет законченную рукопись с путниками на север, в Собор Света в Штормграде. Там епископ Фартинг читает слова Трясунчика, чтобы понять мерзкую порчу, гноящуюся в Сумеречном лесу, и с помощью этих сведений создать священное оружие, способное пробить темные обереги Скверна."}},faq={{q="Почему Трясунчик отдал свой дневник?",a="Трясунчик бежал с фермы Свена во время нападения и оставил недописанный дневник. Законченный вариант он отдал искателям приключений, чтобы те доставили его Свену: он надеется, что полная правда оправдает его и убережет от вспыльчивого нрава Свена.",al={"why does jitters give journal","jitters diary","why did jitters write this","почему трясунчик отдает дневник","дневник трясунчика","зачем трясунчик это написал"}},{q="Что дневник раскрывает о ферме Свена?",a="В нем содержится полный рассказ очевидца Трясунчика о трагедии на ферме Свена Йоргена, восполняющий пробелы его незаконченного дневника.",al={"what happened at sven farm","sven family attack","dark riders sven farm","что случилось на ферме свена","нападение на семью свена","темные всадники ферма свена"}},{q="Кто такой Морбент Скверн и как он связан с дневником?",a="Морбент Скверн — некромант, обитающий в Покинутой усадьбе. Дневник подталкивает Свена поделиться сведениями, которые направляют расследование к нему.",al={"morbent fel connection","who is morbent fel","forlorn rowe wizard","связь с морбентом скверном","кто такой морбент скверн","волшебник покинутой усадьбы"}},{q="Почему дневник относят в Штормград?",a="Свен поручает искателям приключений отнести дневник епископу Фартингу в Собор Света. Поскольку Штормград по большей части пренебрегает защитой Темнолесья, мудрость и священные познания Фартинга нужны, чтобы подготовить оружие, способное пробить магические обереги Морбента Скверна.",al={"why bishop farthing","take journal to cathedral","seeking wisdom journal","почему епископ фартинг","отнести дневник в собор","дневник мудрость"}}},fp="26,289,21.483.1,23.449.1,36.244.0,47.134.1,58.143.1,38.265.1"}
P.entries["item:johaan-s-findings"] = {n="Находки Юхана",s="Находки Юхана — связка исследовательских документов, написанных аптекарем Юханом в Брилле. Их поручают курьеру, идущему на юг: эти записи передают аптекарю Ренферрелу в Гробнице новые алхимические достижения в Тирисфальских лесах.",h="Находки Юхана — связка исследовательских документов, написанных аптекарем Юханом в Брилле.",kw={"apothecary johaan","apothecary renferrel","brill","johaan","johaan's findings","new plague","royal apothecary society","sepulcher","аптекарь юхан","аптекарь ренферрел","брилл","юхан","находки юхана","новая чума","королевское фармацевтическое общество","гробница"},ang={["faction:Horde"]="Доставка исследований на юг знаменует переход путника от знакомых земель Тирисфальских лесов к более мрачным конфликтам Серебряного бора.",["race:Undead"]="Эти находки отражают единственную движущую цель Королевского фармацевтического общества: создать Новую чуму, обещанную Темной Госпоже."},sec={{t="Переписка аптекарей",b="Королевское фармацевтическое общество работает под неослабным давлением леди Сильваны Ветрокрылой, требующей создать Новую чуму, способную уничтожить и живых, и Плеть. Поскольку исследователи разбросаны по спорным руинам Лордерона, поддерживать обмен данными между форпостами жизненно важно. Аптекарь Юхан составляет заметки о местных испытаниях в Брилле и отправляет их на юг аптекарю Ренферрелу, который руководит усилиями общества из Гробницы в Серебряном бору. Эти записи — малая часть общих усилий общества по совершенствованию смертоносных зелий."}},faq={{q="Что такое Находки Юхана?",a="Это пакет алхимических заметок и исследований, составленный аптекарем Юханом в Брилле. В бумагах подробно описаны его недавние испытания и опыты в Тирисфальских лесах.",al={"johaans findings","what are johaans findings","johaan research papers","находки юхана","что такое находки юхана","исследования юхана"}},{q="Кому предназначен этот предмет?",a="Находки адресованы аптекарю Ренферрелу, высокопоставленному члену Королевского фармацевтического общества, который находится в Гробнице на севере Серебряного бора.",al={"who gets johaans findings","where do i take johaans findings","renferrel delivery","кому находки юхана","куда отнести находки юхана","доставка ренферрелу"}},{q="Почему аптекари обмениваются этими исследованиями?",a="Королевское фармацевтическое общество полагается на обмен знаниями между рассредоточенными исследователями, чтобы ускорить работу. Сильвана Ветрокрылая требует скорейшей разработки Новой чумы, поэтому исследователям в Серебряном бору необходимо быть в курсе открытий, сделанных в Тирисфале.",al={"why share findings","purpose of johaans findings","royal apothecary society research","зачем делиться находками","назначение находок юхана","исследования фармацевтического общества"}},{q="Кто написал эти документы?",a="Аптекарь Юхан, алхимик Королевского фармацевтического общества, работающий возле виселицы в Брилле. Он проводит опытные испытания на местных образцах ради алхимических целей Отрекшихся.",al={"who is apothecary johaan","who wrote this","apothecary johaan","кто такой аптекарь юхан","кто это написал","аптекарь юхан"}}},fp="17,238,25.584.0,26.165.0,37.157.0,55.282.0,26.186.0"}
P.entries["item:johaan-s-special-drink"] = {n="Особый напиток Юхана",s="Особый напиток Юхана — смертоносное зелье, которое готовит аптекарь Юхан в деревне Брилл. Под видом обычного освежающего питья эта смесь служит полевым испытанием разрабатываемой Королевским фармацевтическим обществом чумы.",h="Особый напиток Юхана — смертоносное зелье, которое готовит аптекарь Юхан в деревне Брилл.",kw={"apothecary johaan","brill","captured mountaineer","gallows' end tavern","johaan","johaan's special drink","new plague","аптекарь юхан","брилл","пленный горный пехотинец","таверна петля висельника","юхан","особый напиток юхана","новая чума"},ang={["race:Dwarf"]="Это зелье показывает мрачную судьбу, ожидающую дворфов-разведчиков, которые забредают слишком близко к Тирисфальским лесам: пленников используют как подопытных в лабораториях.",["race:Undead"]="Для Отрекшихся доставка варева Юхана — практическая служба Королевскому фармацевтическому обществу и грандиозным планам леди Сильваны против живых."},sec={{t="Ядовитое варево",b="Особый напиток Юхана, сваренный в котлах Брилла, совсем не похож на трактирное питье. Аптекарь Юхан готовит его, очищая разные ядовитые составляющие и местные реагенты в единое зелье, рассчитанное на проверку вирулентности против живого организма. Его вручают под видом утоления жажды пленника, и он воплощает неустанное стремление аптекарей Отрекшихся создать оружие, достаточно мощное для исполнения замыслов Сильваны Ветрокрылой относительно Азерота."},{t="Испытание в подвале",b="Напиток находит своего адресата в мрачном подвале под таверной «Петля висельника», который Стражи смерти используют как временную камеру для случайных нарушителей. Когда его предлагают плененному горному пехотинцу-дворфу, томящемуся в цепях, мучимый жаждой пленник жадно выпивает его, приняв за грубый эль. Зелье действует мгновенно, убивая дворфа на месте и доказывая Королевскому фармацевтическому обществу, что их новейший штамм способен быстро губить живые жертвы."}},faq={{q="Что такое Особый напиток Юхана?",a="Это смертоносное зелье, созданное аптекарем Юханом в Брилле. Хотя оно выдается за напиток, в него добавлен штамм разрабатываемой Отрекшимися чумы, призванный проверить ее смертоносность против живых существ.",al={"what is johaans drink","johaan drink","what is this item","что за напиток юхана","напиток юхана","что это за предмет"}},{q="Кому дают этот напиток?",a="Напиток несут в подвал таверны «Петля висельника» в Брилле и дают Пленному горному пехотинцу, взятому в плен местными Стражами смерти.",al={"who drinks it","who do i give the drink to","drink target","кто пьет напиток","кому дать напиток","цель напитка"}},{q="Что происходит, когда его пьют?",a="Пленник залпом выпивает жидкость, ожидая грубого трактирного пойла для утоления жажды, и тут же падает замертво от губительных токсинов варева.",al={"does the dwarf die","effect of the drink","what does it do","умирает ли дворф","действие напитка","что он делает"}},{q="Зачем аптекарь Юхан готовит этот напиток?",a="Аптекарь Юхан проводит испытания новой чумы Королевского фармацевтического общества. Он использует плененного дворфа как ничего не подозревающий живой образец, чтобы проверить, насколько смесь эффективно гасит смертную жизнь.",al={"why did johaan make it","apothecary johaan motive","why test the plague","зачем юхан сделал напиток","мотив аптекаря юхана","зачем испытывать чуму"}}},fp="22,224,12.487.0,16.468.1,31.220.0,26.159.0,36.143.1,43.211.0"}
P.entries["item:jordan-s-ore-shipment"] = {n="Партия руды Джордана",s="Партия руды Джордана — ящик очищенного сплава, предназначенный для кузнеца Джордана Стилвелла. Груз, который везли из Болотины в Стальгорн, перехватили и разграбили огры Мо'грош в северо-восточных холмах Лок Модана.",h="Партия руды Джордана — ящик очищенного сплава, предназначенный для кузнеца Джордана Стилвелла.",kw={"alloy","bailor stonehand","jordan stilwell","jordan's ore shipment","loch modan","mo'grosh","test of righteousness","сплав","балор крепкорук","джордан стилвелл","партия руды джордана","лок модан","мо'грош","испытание доблести"},ang={["class:Paladin"]="Вернуть этот украденный у огров Мо'грош сплав — важный этап заказа Джордана Стилвелла, он докажет вашу преданность во время Испытания доблести.",["profession:Blacksmithing"]="Особый сплав Балора Крепкорука — образец тонкой дворфийской металлургии, столь ценный, что Джордан Стилвелл отказался заменять его обычными материалами."},sec={{t="Засада на груз",b="Этот особый сплав выковал дворф Балор Крепкорук, и первоначально он предназначался Джордану Стилвеллу для его работы по металлу. Когда караван с припасами шел на юг через горы из Болотины в Лок Модан, на него жестоко напали огры Мо'грош. Груз утащили в укрепление огров в глуши, а выжившие стражи умерли от ран. Проект Джордана встал, пока какой-нибудь искатель приключений не отобьет груз у этих громил."}},faq={{q="Что находится в партии?",a="В партии находится особый сплав, изготовленный дворфом Балором Крепкоруком и предназначенный кузнецу Джордану Стилвеллу для работы по металлу в Стальгорне.",al={"what is in jordan's ore shipment","what ore is this","jordan ore contents","что в партии руды джордана","что это за руда","содержимое партии руды джордана"}},{q="Кто украл партию руды Джордана?",a="Огры Мо'грош напали на караван с припасами, когда он шел на юг из Болотины, перебили охрану и утащили ящики в свои владения к северо-востоку от озера Лок.",al={"who took the ore shipment","who stole it","ogres ore shipment","кто забрал партию руды","кто ее украл","огры партия руды"}},{q="Кто такой Балор Крепкорук?",a="Балор Крепкорук — дворф-мастеровой, живущий в Лок Модане, давний друг Джордана Стилвелла. Он организовал отправку сплава, пока его не захватили огры.",al={"bailor stonehand","who is bailor","балор крепкорук","кто такой балор"}},{q="Почему эта партия важна для паладинов?",a="Паладины, проходящие Испытание доблести, ищут этот сплав, чтобы помочь Джордану Стилвеллу выковать освященное оружие Света.",al={"paladin ore shipment","test of righteousness ore","why do paladins need this","руда паладина","руда испытания доблести","зачем паладинам это нужно"}}},fp="21,227,20.473.0,28.154.0,32.186.0,24.167.0,43.131.0"}
P.entries["item:jordan-s-refined-ore-shipment"] = {n="Партия очищенной руды Джордана",s="Партия очищенной руды Джордана — ящик высококачественного металла, подготовленный специально для кузнеца Джордана Стилвелла. Его получают в ходе священных испытаний паладина, и он дает основу для ковки святого оружия добродетели.",h="Партия очищенной руды Джордана — ящик высококачественного металла, подготовленный специально для кузнеца...",kw={"bailor","ironforge","jordan stilwell","paladin weapon","refined ore","test of righteousness","балор","стальгорн","джордан стилвелл","оружие паладина","очищенная руда","испытание доблести"},ang={["class:Paladin"]="Добыча этой очищенной партии испытывает терпение и преданность паладина — это одно из практических испытаний для создания его символического оружия Света.",["profession:Blacksmithing"]="Любой ремесленник знает: для превосходной ковки нужны безупречные, тщательно подготовленные слитки, а не сырая руда."},sec={{t="Материалы кузнеца",b="Когда Джордан Стилвелл решил выковать оружие, достойное преданного паладина, обычных материалов оказалось мало. Кузнецу требовался набор редких и точных компонентов: очищенный самоцвет Кора, прочная древесина белокаменного дуба, его собственный потерянный дробящий молот и особая партия очищенной руды. Этот груз — металлическая основа для священной работы, доставленная в Стальгорн, чтобы завершить Испытание доблести."}},faq={{q="Для чего нужна партия очищенной руды Джордана?",a="Очищенную руду доставляют Джордану Стилвеллу у Стальгорна. Это один из четырех ключевых компонентов для ковки превосходного оружия паладинам, проходящим Испытание доблести.",al={"refined ore purpose","what does jordan do with ore","ore shipment use","назначение очищенной руды","что джордан делает с рудой","зачем партия руды"}},{q="Кто готовит очищенную руду?",a="Партию организует Балор, который руководит очисткой и отправкой особого металла, нужного Джордану Стилвеллу.",al={"who made the ore","bailor ore","who refines jordan's ore","кто сделал руду","балор руда","кто очищает руду джордана"}},{q="Почему Джордану нужна именно эта партия?",a="Джордан Стилвелл хочет создать символ паладинства и Света, и ему нужны материалы лучше обычных кузнечных остатков. Этот особо обработанный металл придает клинку или навершию молота баланс и чистоту, достойные святого рыцаря.",al={"why special ore","why cant jordan use regular iron","refined ore reason","зачем особая руда","почему джордан не может взять обычное железо","причина очищенной руды"}}},fp="29,233,19.437.0,47.185.0,29.133.0,44.252.0"}
P.entries["item:jordan-s-smithing-hammer"] = {n="Дробящий молот Джордана",s="Дробящий молот Джордана — любимая семейная реликвия, которую человеку-кузнецу Джордану Стилвеллу передал отец. Вернуть его из зловещих залов Крепости Темного Клыка необходимо, чтобы выковать святое оружие, освященное Светом.",h="Дробящий молот Джордана — любимая семейная реликвия, которую человеку-кузнецу Джордану Стилвеллу передал отец.",kw={"dun morogh","ironforge","jordan stilwell","paladin weapon","shadowfang keep","smithing hammer","test of righteousness","дун морог","стальгорн","джордан стилвелл","оружие паладина","крепость темного клыка","дробящий молот","испытание доблести"},ang={["class:Paladin"]="Возвращение фамильного молота — часть тяжких испытаний доблести: оно доказывает решимость паладина отправиться в опасные земли за инструментами священного ремесла.",["profession:Blacksmithing"]="Любой кузнец понимает, какая душевная и практическая связь соединяет мастера с молотом, который достался ему от предков."},sec={{t="Наследие мастера",b="Постороннему дробящий молот Джордана может показаться простым кузнечным железом, но для Джордана Стилвелла он — и наследие, и судьба. Этот инструмент достался ему от отца и очень важен для Джордана как мастера кузни у Стальгорна. Молот каким-то образом оказался в покинутых каменных стенах Крепости Темного Клыка в Серебряном бору, и его нужно вернуть, прежде чем Джордан возьмется за главное творение — священное оружие, достойное святого защитника."}},faq={{q="Где находится дробящий молот Джордана?",a="Молот лежит в проклятых стенах Крепости Темного Клыка, в темных лесах Серебряного бора. Паладины, проходящие Испытание доблести, должны проникнуть в захваченную крепость, чтобы вернуть его.",al={"hammer location","where is jordan's hammer","where to find jordan's smithing hammer","местонахождение молота","где молот джордана","где найти дробящий молот джордана"}},{q="Почему этот молот так важен для Джордана Стилвелла?",a="Молот достался Джордану от отца. Он очень дорог ему как память и нужен для создания лучшего творения — святого оружия Света.",al={"why does jordan want the hammer","jordan stilwell hammer lore","почему джордану нужен молот","предание о молоте джордана стилвелла"}},{q="Для чего нужен молот после возвращения?",a="Когда молот вернут Джордану у ворот Стальгорна вместе с древесиной, рудой и самоцветом, он выкует великое священное оружие в награду помогшему ему паладину.",al={"what does the hammer make","test of righteousness hammer use","что делают молотом","молот испытания доблести"}}},fp="24,242,20.457.0,42.205.0,51.177.0,43.177.0"}
P.entries["item:kadrak-s-flag"] = {n="Флаг Кадрака",s="Флаг Кадрака — эмблема Орды, которую дает разведчик Кадрак на границе Степей и Ясеневого леса. Это недвусмысленное предупреждение ночным эльфам и дриадам Пика Каменного Когтя: флаг водружают прямо в Пещере Когтей после гибели Хранительницы ключей Ринтариэль.",h="Флаг Кадрака — эмблема Орды, которую дает разведчик Кадрак на границе Степей и Ясеневого леса.",kw={"barrens","horde presence","kadrak","kadrak's flag","rynthariel","stonetalon","stonetalon peak","talon den","степи","присутствие орды","кадрак","флаг кадрака","ринтариэль","когтистые горы","пик каменного когтя","пещера когтей"},ang={["faction:Horde"]="Водружение этого стяга в глубине Пещеры Когтей — дерзкое утверждение силы на территории: Орда ответит ударом прямо по святилищам ночных эльфов, если ее спровоцировать.",["race:NightElf"]="Осквернение Пещеры Когтей кроваво-красным знаменем Орды — прямое оскорбление и вызов защитникам Пика Каменного Когтя."},sec={{t="Знак вызова",b="На границах Калимдора неспокойно: посланцы и часовые Альянса постоянно испытывают границы земель Орды. Когда расшифрованный свиток раскрывает переписку дриады Ринтариэль, Хранительницы ключей Пещеры Когтей, Кадрак решает, что убить ее недостаточно. Он дает багровый стяг, чтобы водрузить его в глубине Пещеры на пике Когтистых гор. Установив цвета Орды в одном из священных горных оплотов ночных эльфов, Кадрак хочет ясно дать понять: вторжения через Степи получат смелый ответ на земле Альянса."}},faq={{q="Для чего нужен Флаг Кадрака?",a="Флаг водружают в Пещере Когтей на Пике Каменного Когтя после убийства Хранительницы ключей Ринтариэль. Знамя Орды в их твердыне предостерегает ночных эльфов от отправки новых разведчиков и посланцев в Степи.",al={"flag purpose","why plant flag","what does flag do","назначение флага","зачем ставить флаг","что делает флаг"}},{q="Кто дает флаг?",a="Кадрак, орк-разведчик на пограничном посту между северными Степями и Ясеневым лесом, дает стяг искателям приключений Орды в рамках своей кампании по защите региона.",al={"who gives flag","where to get flag","kadrak location","кто дает флаг","где взять флаг","где кадрак"}},{q="Где водружают флаг?",a="Стяг водружают в Пещере Когтей — пещерном святилище на западных склонах Пика Каменного Когтя в Когтистых горах.",al={"where do i plant flag","flag location","talon den flag spot","где ставить флаг","место флага","место флага в пещере когтей"}},{q="Кто такая Ринтариэль?",a="Ринтариэль — дриада, Хранительница ключей Пещеры Когтей. Она направляла посланцев на земли Орды, пока Кадрак не перехватил ее переписку и не приказал ее убить.",al={"rynthariel dryad","who is rynthariel","keymaster","ринтариэль дриада","кто такая ринтариэль","хранительница ключей"}}},fp="13,282,18.604.0,31.234.0,23.182.0,26.140.0,18.191.0"}
P.entries["item:keg-of-shindigger-stout"] = {n="Бочонок \"Землекопского крепкого\"",s="Бочонок «Землекопского крепкого» — бочка крепкого дворфийского эля, который варят и охраняют стрелки и солдаты гарнизона Дун Гарока. Королевское фармацевтическое общество в Мельнице Таррен хочет получить его не для вечерней выпивки, а как коварный способ доставки новых болезней.",h="Бочонок «Землекопского крепкого» — бочка крепкого дворфийского эля, который варят и охраняют стрелки и...",kw={"apothecary lydon","dun garok","dwarven ale","elixir of agony","keg of shindigger stout","shindigger stout","tarren mill","аптекарь лидон","дун гарок","дворфийский эль","эликсир агонии","бочонок землекопского крепкого","землекопское крепкое","мельница таррен"},ang={["faction:Horde"]="Удар по Дун Гароку разрушает опасный военный плацдарм Альянса, расположенный прямо между Альтеракскими горами и нагорьем Арати.",["race:Undead"]="Для Отрекшихся кража бочки ценного дворфийского эля — чисто практическая алхимия: алкоголь скрывает запах и вкус смертельных составов, разработанных для леди Сильваны."},sec={{t="Любимый напиток дворфов",b="Дун Гарок — грозный оплот дворфов на юго-востоке Предгорий Хилсбрада, который упорно удерживают дворфы Стальгорна. В укрепленных казармах и столовых стойкие защитники делят бочки «Землекопского крепкого», чтобы переносить холод и изнурительную осаду местных врагов. Напиток крепкий и в изобилии, он помогает гарнизону выживать изо дня в день."},{t="Сосуд с ядом Аптекаря Лидона",b="Дворфы считают «Землекопское крепкое» честной наградой после боя, но аптекарь Лидон в Мельнице Таррен видит в нем идеальное средство для террора. Разрабатывая зловещий Эликсир агонии Отрекшихся, Лидон отказывается испытывать смертоносный состав на животных. Он ищет целый бочонок эля, чтобы подмешать в него состав и получить отравленное угощение для пленных человеческих фермеров в Мельнице Таррен."}},faq={{q="Для чего нужно «Землекопское крепкое»?",a="Аптекарь Лидон в Мельнице Таррен хочет получить бочонок крепкого, чтобы испытать свежеочищенный Эликсир агонии. Вместо того чтобы тратить ядовитый состав на лабораторных животных, он собирается подмешать его в дворфийский эль и провести смертельное полевое испытание на гуманоидах.",al={"why get shindigger stout","shindigger stout purpose","what does lydon do with the keg","зачем землекопское крепкое","назначение землекопского крепкого","что лидон делает с бочонком"}},{q="Где найти Бочонок «Землекопского крепкого»?",a="Бочонки с крепким хранятся в глубине дворфийской крепости Дун Гарок на юго-востоке Предгорий Хилсбрада. Обычно они стоят в столовых и нижних казарменных помещениях дворфийской пехоты.",al={"keg location","where is shindigger stout","find the stout","где бочонок","где землекопское крепкое","найти крепкое"}},{q="Кто варит «Землекопское крепкое»?",a="Его варят и хранят дворфы Дун Гарока, удерживающие сильно укрепленный гарнизон в Предгорьях Хилсбрада от имени Стальгорна.",al={"who makes shindigger stout","is it dwarven ale","кто делает землекопское крепкое","это дворфийский эль"}},{q="Почему аптекарь Лидон не варит свой алкоголь для испытания?",a="Лидон просит бочонок, уже хранящийся в Дун Гароке, чтобы использовать эль в опыте; в задании не сказано, что он сам варит алкоголь.",al={"why steal dwarven beer","why dun garok beer","зачем красть дворфийское пиво","зачем пиво дун гарока"}}},fp="23,294,18.408.0,32.416.1,34.255.0,45.234.0,27.139.0,63.145.0"}
P.entries["item:ken-zigla-s-draught"] = {n="Зелье Кен'зиглы",s="Зелье Кен'зиглы — сильнодействующий лечебный тоник отвратительного вкуса, который готовит Кен'зигла в Когтистых горах. Он составлен так, чтобы вернуть тяжелораненым достаточно сил для движения без риска истечь кровью.",h="Зелье Кен'зиглы — сильнодействующий лечебный тоник отвратительного вкуса, который готовит Кен'зигла в...",kw={"camp taurajo","dogran","grunt logmar","ken'zigla's draught","kenzigla","stonetalon mountains","succubus quest","the barrens","лагерь таурахо","догран","грант логмар","зелье кен'зиглы","кен'зигла","когтистые горы","задание суккуб","степи"},ang={["class:Warlock"]="Добыча и доставка этого зелья — важный этап испытаний по призыву и подчинению суккуба, который доказывает находчивость чернокнижника и его умение выслеживать в Степях.",["faction:Horde"]="Поскольку в Лагере Таурахо не хватает людей из-за дозоров за пропитанием, это зелье остается единственной надеждой для лазутчика, попавшего в плен в тылу вражеских свинобразов."},sec={{t="Горькое лекарство",b="Это сильнодействующее снадобье, приготовленное Кен'зиглой в Когтистых горах, служит средством экстренной помощи для стоящих на пороге смерти. Тоник чрезвычайно крепок, и его нужно отмерять осторожно: если выпить больше половины дозы сразу, больной может истечь кровью из-за резкого скачка кровообращения. Половина дозы дает достаточно сил, чтобы двигаться и бежать от опасности, а остальное нужно оставить до тех пор, пока тело не окрепнет после полноценного ночного отдыха."},{t="Милосердие в Степях",b="Зелье играет важную роль в поисках Дограна, лазутчика, которого свинобразы схватили и пытали к северу от Лагеря Таурахо. Горькое снадобье доставляют прямо в лагерь враждебных иглошкурых чернокнижники Орды, ищущие знак пожирателя душ. Выпив его, Догран обретает ровно столько сил, чтобы уковылять от своих мучителей, хотя тяжелые раны навсегда лишили его возможности пользоваться конечностями."}},faq={{q="Для чего нужно Зелье Кен'зиглы?",a="Это сильнодействующее лечебное снадобье, созданное, чтобы возвращать силы умирающим или тяжело раненным. При правильном применении оно дает раненому достаточно выносливости, чтобы встать и бежать из плена, не вызвав смертельного кровотечения.",al={"what does kenziglas draught do","draught purpose","why do i need kenziglas draught","что делает зелье кен'зиглы","для чего зелье","зачем мне зелье кен'зиглы"}},{q="Кто готовит это зелье?",a="Его варит Кен'зигла, аптекарь или травник, живущий в Когтистых горах. Она приготовила его, предвидя, что кто-нибудь придет просить помощи для Дограна.",al={"who brews the draught","who is kenzigla","kenzigla location","кто варит зелье","кто такая кен'зигла","где кен'зигла"}},{q="Почему зелье можно принимать только по половине за раз?",a="Это снадобье исключительно тяжело для организма. Половина дозы дает ровно столько сил, чтобы двигаться, не вызывая сильного кровотечения, а вторую половину нужно отложить до тех пор, пока больной не отдохнет ночь, иначе нагрузка окажется смертельной.",al={"how to take kenziglas draught","half dose draught","draught instructions","как принимать зелье кен'зиглы","половина дозы зелья","инструкция к зелью"}},{q="Кому предназначено зелье?",a="В итоге его относят Дограну, лазутчику, которого держат в плену и тяжело ранили в лагере свинобразов к северу от Лагеря Таурахо в Степях.",al={"who drinks the draught","who is dogran","where to deliver draught","кто пьет зелье","кто такой догран","куда доставить зелье"}},{q="Почему за этим лекарством посылают чернокнижников?",a="Чернокнижников Орды, желающих подчинить суккуба, направляют к Дограну, у которого есть предмет глубокого эмоционального значения. Чтобы добраться до него и получить все необходимое для ритуала призыва, нужно помочь доставить зелье.",al={"why do warlocks need this","succubus quest draught","warlock quest kenzigla","зачем чернокнижникам зелье","задание суккуб зелье","задание чернокнижника кен'зигла"}}},fp="19,229,15.466.0,20.421.1,37.231.0,22.169.0,50.220.0,25.137.0,48.224.0"}
P.entries["item:khazgorm-s-journal"] = {n="Записи Хазгорма",s="Записи Хазгорма — личный полевой журнал геолога Хазгорма, начальника дворфийских раскопок Стальгорна в Бейл Модане на юге Степей. В нем описаны вторжения Лиги исследователей на земли, на которые претендует племя тауренов Каменного Копья.",h="Записи Хазгорма — личный полевой журнал геолога Хазгорма, начальника дворфийских раскопок Стальгорна в Бейл...",kw={"bael modan","barrens","dwarf","explorers' league","gann stonespire","journal","khazgorm","prospector","бейл модан","степи","дворф","лига исследователей","ганн каменное копье","журнал","хазгорм","геолог"},ang={["faction:Horde"]="Возвращение этой книги помогает Ганну Каменному Копью защищать Калимдор от вторжений экспедиций Альянса, проникающих вглубь суверенных земель Орды.",["race:Tauren"]="Журнал служит осязаемым доказательством бессердечия захватчиков из Стальгорна, которые взрывали священные земли предков, не считаясь с племенем Каменного Копья."},sec={{t="Хроника разрушения",b="Журнал принадлежит геологу Хазгорму, руководившему тяжелой техникой и взрывными работами, что вгрызались в холмы на юге Степей. Записи совсем не похожи на мирный поиск знаний, о котором заявляла Лига исследователей: они отражают безжалостную кампанию раскопок, вытеснившую племя Каменного Копья. Попытки тауренов договориться миром были отвергнуты, и потому журнал стал ценным трофеем для Ганна Каменного Копья, который стремится понять и разрушить присутствие дворфов на своей родине."},{t="Смена тактики",b="Книга, найденная на останках Хазгорма среди палаток и столбов раскопок, дает Ганну важные сведения о строении, снаряжении и уязвимых местах дворфийской экспедиции. Изучив личные записи геолога, Ганн может перейти от простого изгнания рабочих к целенаправленной порче техники на раскопках, и журнал становится переломным моментом в борьбе за Бейл Модан."}},faq={{q="Кому принадлежит журнал?",a="Журнал принадлежит геологу Хазгорму, одному из руководителей дворфийских раскопок Стальгорна на месте раскопок Бейл Модан на юге Степей.",al={"who owns the journal","khazgorm","prospector khazgorm","чей журнал","хазгорм","геолог хазгорм"}},{q="Зачем Ганну Каменному Копью эта книга?",a="Ганн Каменное Копье ищет журнал, чтобы изучить планы и тайны дворфов-захватчиков, изгнавших его племя, и по записям самого Хазгорма организовать новые удары по лагерю в Бейл Модане.",al={"why gann wants journal","gann quest journal","ganns reclamation book","зачем ганну журнал","задание ганна журнал","книга возвращения ганна"}},{q="Где можно найти журнал?",a="Журнал носит при себе сам геолог Хазгорм. Его можно найти среди палаток и каменных столбов действующих раскопок к югу от Бейл Модана.",al={"where is khazgorms journal","find khazgorms journal","khazgorm location","где журнал хазгорма","найти журнал хазгорма","где хазгорм"}},{q="Что журнал рассказывает о дворфах?",a="Он показывает менее ученую сторону Лиги исследователей: погоня за погребенными реликвиями и наследием Титанов нередко оборачивается прямым насилием над коренными племенами, такими как таурены Каменного Копья.",al={"explorers league barrens","dwarf digsite secrets","bael modan purpose","лига исследователей степи","тайны раскопок дворфов","зачем бейл модан"}}},fp="18,272,23.518.0,18.429.1,31.153.0,40.208.0,31.160.0,47.214.0"}
P.entries["item:klaven-mortwake-s-journal"] = {n="Дневник Клейвена Мортвейка",s="Дневник Клейвена Мортвейка — разведывательный отчет, найденный агентами ШРУ в башне Братства Справедливости на северо-востоке Западного Края. Он хранился в сундуке, привезенном из Сумеречного леса, и описывает тайные попытки Братства варить алхимические составы, способные оживлять мертвых.",h="Дневник Клейвена Мортвейка — разведывательный отчет, найденный агентами ШРУ в башне Братства Справедливости...",kw={"defias tower","duskwood chest","journal","klaven mortwake","mathias shaw","poisons","si:7","zanzil","башня братства справедливости","сундук из сумеречного леса","дневник","клейвен мортвейк","матиас шоу","яды","шру","занзил"},ang={["class:Rogue"]="Проникновение в башню ради дневника Мортвейка становится проверкой для разбойников ШРУ: оно требует умения взламывать замки, скрытности и знакомит с ремеслом изготовления смертоносных ядов.",["faction:Alliance"]="Дневник дает штормградским шпионам неопровержимое доказательство того, что восстание Братства Справедливости не ограничивается недовольными рабочими, и раскрывает связи с тролльскими знахарями и алхимическим некромантством."},sec={{t="Жуткая формула",b="ШРУ давно наблюдало за башней Братства Справедливости, возвышающейся на хребтах севера Западного Края, и отмечало странные грузы, прибывающие с сумрачных границ Сумеречного леса, а также уродливых нечеловеческих стражей. Дневник, найденный в верхнем сундуке, принадлежал Клейвену Мортвейку и раскрывает назначение этих поставок. Мортвейк записал алхимические исследования о том, как алхимики, связанные с троллями Занзила в Тернистой долине, нашли способ поднимать безмозглых немертвых рабов с помощью особых ядов и зелий, и Братство Справедливости пыталось повторить это для своих рядов."},{t="Сведения для ШРУ",b="Мастер Матиас Шоу, глава разведывательной службы Штормграда, считал возвращение дневника Мортвейка первоочередной задачей, чтобы восстановить широкую сеть союзов Братства. Записи подтверждают не только темные опыты по оживлению мертвых, но и незаконную поддержку поставок, связывающую Сумеречный лес, Торговую Компанию и Братство Справедливости. Для разбойников на службе короны возвращение этих темных исследований становится решающим шагом к овладению искусством ядов."}},faq={{q="Что такое Дневник Клейвена Мортвейка?",a="Это исследовательская тетрадь Клейвена Мортвейка, агента Братства Справедливости в башне на северо-востоке Западного Края. В ней содержатся записи об алхимическом некромантстве и тайных путях снабжения.",al={"what is klavens journal","mortwake journal","what is this item","что за дневник клейвена","дневник мортвейка","что это за предмет"}},{q="Где найти дневник?",a="Он заперт в сундуке из Сумеречного леса на верхнем этаже башни Братства Справедливости на севере Западного Края. Его охраняют немертвые стражи, а открыть сундук можно только ключом, который носит один из чудовищных стражей Клейвена.",al={"where to find klavens journal","klaven journal location","duskwood chest location","где найти дневник клейвена","местонахождение дневника клейвена","где сундук из сумеречного леса"}},{q="Какие тайны записаны в дневнике?",a="Текст открывает, что тролли Занзила из Тернистой долины создали ядовитые зелья, способные поднимать мертвых и подчинять их, и Братство Справедливости активно пыталось получить и применить этот смертоносный рецепт.",al={"what does the journal say","journal secrets","zanzil poison","что сказано в дневнике","тайны дневника","яд занзила"}},{q="Кому нужен этот дневник?",a="Мастер Матиас Шоу, глава штормградской разведки ШРУ, требует этот документ, чтобы следить за снабжением Братства Справедливости и учить агентов короны опасностям и применению тактических ядов.",al={"who turns in klaven journal","who do i give the journal to","mathias shaw journal","кому сдать дневник клейвена","кому отдать дневник","матиас шоу дневник"}}},fp="25,290,18.597.1,21.473.0,34.195.0,27.198.0,44.222.0,23.193.0"}
P.entries["item:kodo-horn"] = {n="Рог кодо",s="Рог кодо — прочный природный реагент, добываемый у зверей, что бродят по северным землям Степей. Для друидов Кенария их плотная структура дает силу и мощь для опытных травяных смесей, прежде всего для лечебных мазей, исцеляющих отравленных животных.",h="Рог кодо — прочный природный реагент, добываемый у зверей, что бродят по северным землям Степей.",kw={"barrens","cenarion","earthroot","gazelle","kodo horn","poison","tonga runetotem","степи","кенарий","землекорень","газель","рог кодо","яд","тонга рунический тотем"},ang={["class:Druid"]="Для молодых друидов Орды сбор этих рогов под руководством Тонги Рунического Тотема — важный обряд посвящения, ведущий к врожденному умению владеть ядами природы.",["race:Tauren"]="Таурены глубоко чтят кодо и берут у них лишь с почтением и по необходимости — в данном случае, чтобы защитить хрупкую экосистему Степей."},sec={{t="Реагент равнин",b="Хотя тауренов по всем Степям чтят кодо за выносливость и силу, их рога имеют и практическую лечебную ценность. Тонга Рунический Тотем, работающий на Перекрестке, использует целые рога, чтобы усилить действие своих травяных средств. Для приготовления этих мазей не годятся осколки и обломки: только целые рога взрослых кодо, бродящих по сухим равнинам, достаточно сильны, чтобы стать основой лекарства."}},faq={{q="Для чего нужен Рог кодо?",a="Тонга Рунический Тотем использует их вместе с землекорнем и чистой водой для приготовления лечебной мази. Эта смесь предназначена для лечения отравленных газелей по всем Степям и служит важным этапом обучения друида искусству природных противоядий.",al={"kodo horn purpose","why gather kodo horns","use of kodo horn","для чего рог кодо","зачем собирать рога кодо","применение рога кодо"}},{q="Где собирают эти рога?",a="Их добывают у степных кодо и заблудших степных кодо, бродящих по северным просторам Степей. Обычно их можно встретить пасущимися между Перекрестком и окрестными зарослями.",al={"where to find kodo horns","kodo horn location","which kodos drop horns","где найти рог кодо","где добыть рог кодо","с каких кодо падают рога"}},{q="Почему друиды не могут использовать осколки рогов?",a="Тонга Рунический Тотем отмечает, что простым осколкам и обломкам не хватает силы, чтобы правильно уравновесить мазь. Для лекарства нужны целые рога, чтобы получались дозы, способные противостоять опасным ядам.",al={"why not broken horns","horn chips","почему не сломанные рога","осколки рогов"}},{q="Считается ли охота на кодо уважительной для друида?",a="Да, если она служит великому равновесию природы. Друиды берут у земли и ее созданий только необходимое, чтобы исцелить более серьезные недуги, например загадочное отравление, поражающее местные стада газелей.",al={"druid hunting kodos","balance and kodos","друид охота на кодо","равновесие и кодо"}}},fp="9,302,23.435.0,29.253.0,32.187.0,44.204.0,51.214.0"}
P.entries["item:kodo-liver"] = {n="Печень кодо",s="Печень кодо — увесистый орган, добываемый у огромных кодо, что бродят по равнинам Степей. Хотя это едва ли обычное блюдо, Пивовар Дрон из Кабестана требует ее как важный ингредиент для брожения необычного эля троггов, рецепт которого он узнал от странствующего пивовара Чэня Буйного Портера.",h="Печень кодо — увесистый орган, добываемый у огромных кодо, что бродят по равнинам Степей.",kw={"barrens","brewing","chen stormstout","drohn","kodo","kodo liver","ratchet","trogg ale","степи","пивоварение","чэнь буйный портер","дрон","кодо","печень кодо","кабестан","эль троггов"},ang={["profession:Cooking"]="Хотя обычное мясо кодо служит основным пайком по всему центральному Калимдору, печень кодо считается слишком мерзкой и резкой для обычной домашней кухни, что делает ее применение в эле троггов Кабестана еще более скандальным.",["race:Tauren"]="Таурены чтят каждую часть добытого кодо, но даже самые опытные из их следопытов косо смотрят на гоблинов и чужаков, превращающих священные внутренности кодо в диковинный эль в Кабестане."},sec={{t="Странный реагент для пивоварения",b="На великих кодо Степей охотятся главным образом тауренов и бродячие хищники ради прочной шкуры и питательного мяса. Однако свежая печень кодо находит гораздо более причудливое применение в портовом городе Кабестан. Пивовар Дрон использует этот орган вместе со слюнными железами громового ястреба и железами молний, чтобы воссоздать мощный напиток, которому его научил Чэнь Буйный Портер: эль троггов. Дрон утверждает, что эта необычная смесь обладает грозной крепостью и дарит искателям приключений сытное питье прямо из глуши центрального Калимдора."}},faq={{q="Для чего нужна Печень кодо?",a="Печень кодо относят Пивовару Дрону в Кабестан. Он добавляет ее в рецепт крепкого эля троггов, которому его когда-то научил знаменитый пандарен-пивовар Чэнь Буйный Портер.",al={"kodo liver purpose","why need kodo liver","what is kodo liver for","для чего печень кодо","зачем нужна печень кодо","что делать с печенью кодо"}},{q="Какие существа дают Печень кодо?",a="Ее можно вырезать у разных кодо, бродящих по открытой саванне Степей, включая обычных степных кодо, лохматых кодо, заблудших кодо, больших кодо и редких зверей, таких как Лакота'мани и Бронт.",al={"where to get kodo liver","who drops kodo liver","kodo liver source","где достать печень кодо","с кого падает печень кодо","источник печени кодо"}},{q="Зачем кому-то класть в эль органы животных?",a="Пивовар Дрон варит по экзотическим и причудливым рецептам, которые передал ему Чэнь Буйный Портер. В эле троггов сырые органы, такие как печень кодо и железы элементалей, придают напитку его знаменитую крепость и особый вкус, бьющий как кулаком по зубам.",al={"why liver in beer","kodo liver in alcohol","зачем печень в пиве","печень кодо в алкоголе"}}},fp="10,290,25.543.0,30.182.0,35.200.0,42.239.0"}
P.entries["item:kodobane-s-head"] = {n="Голова Кодобоя",s="Голова Кодобоя — отсеченная голова Барака Кодобоя, хитрого вождя кентавров Колкар. Ее приносят в доказательство его смерти орку-полководцу Регтару Врата Смерти, чтобы показать, что угроза со стороны кентавров у Забытых прудов сломлена.",h="Голова Кодобоя — отсеченная голова Барака Кодобоя, хитрого вождя кентавров Колкар.",kw={"barak","barrens","centaur","crossroads","deathgate","forgotten pools","kodobane","kolkar","regthar","барак","степи","кентавр","перекресток","врата смерти","забытые пруды","кодобой","колкар","регтар"},ang={["faction:Horde"]="Перекресток Степей — важнейшая сухопутная связь между Оргриммаром и Громовым Утесом; подавление вождей кентавров вроде Кодобоя необходимо для безопасности караванных троп.",["race:Tauren"]="Из поколения в поколение кентавры гнали кочевых тауренов по Калимдору, доводя их до грани вымирания. Убийство Барака Кодобоя мстит за века кровопролития и защищает пастбища Мулгора и Степей."},sec={{t="Военный трофей",b="Кентавры Колкар из Степей испокон веков были раздробленной, неорганизованной помехой, однако возвышение честолюбивых полководцев грозит объединить их разбойничьи шайки в армию. Барак Кодобой разбил лагерь у обильных вод Забытых прудов, отрезав доступ к важным ресурсам оазиса и нападая на ближайшие тропы. Регтар Врата Смерти, расквартированный в бункере к западу от Перекрестка, требует его отсеченную голову как неоспоримое доказательство того, что этот командир больше не сможет сплотить своих свирепых сородичей против Орды."}},faq={{q="Кем был Барак Кодобой?",a="Барак Кодобой был видным вождем кентавров Колкар. В отличие от многих недисциплинированных сородичей, Барак обладал хитростью и властностью, нужными для организации отрядов, и разбил лагерь у Забытых прудов, чтобы утвердить господство Колкар в северной части Степей.",al={"barak kodobane","who is kodobane","barak lore","барак кодобой","кто такой кодобой","барак предания"}},{q="Зачем Регтару Врата Смерти нужна его голова?",a="Регтару Врата Смерти поручено обеспечивать безопасность земель Орды в Степях. Поскольку кентавры обычно разобщены, лидеров с подлинным тактическим чутьем выделяют для уничтожения. Требование принести голову Кодобоя гарантирует, что вождь мертв, а не просто изгнан.",al={"why get head","regthar deathgate head","kodobane bounty","зачем голова","регтар врата смерти голова","награда за кодобоя"}},{q="Где находится Барак Кодобой?",a="Барак Кодобой разбил лагерь у северного оазиса, известного как Забытые пруды, к северо-западу от Перекрестка в Степях.",al={"barak location","where is kodobane","barak spawn","барак местонахождение","где кодобой","барак появление"}},{q="Прекратит ли смерть Барака угрозу Колкар?",a="Нет. Барак Кодобой — лишь первый из нескольких полководцев, объединяющих Колкар. Его смерть нарушает их присутствие у Забытых прудов, но другие лидеры, такие как Верог Дервиш и Хэрзул Кровавая Отметина, продолжают направлять агрессию кентавров по всем Степям.",al={"are centaurs defeated","what happens after barak dies","побеждены ли кентавры","что будет после смерти барака"}}},fp="15,245,15.511.0,23.271.0,41.281.0,30.132.0,42.255.0"}
P.entries["item:kravel-s-crate"] = {n="Сундук Крейвела",s="Сундук Крейвела — тяжелая посылка, отправленная Крейвелом Углебрадом с Виражей на Миражах на Мерцающей равнине. Предназначенный для экспедиции Незингвари в Тернистой долине, он содержит особые охотничьи боеприпасы для охоты на самую опасную дичь джунглей.",h="Сундук Крейвела — тяжелая посылка, отправленная Крейвелом Углебрадом с Виражей на Миражах на Мерцающей...",kw={"ammunition","hemet nesingwary","kravel koalbeard","kravel's crate","mirage raceway","shimmering flats","stranglethorn vale","боеприпасы","хемет незингвари","крейвел углебрад","сундук крейвела","виражи на миражах","мерцающая равнина","тернистая долина"},ang={["class:Hunter"]="В сундуке лежат особые тяжелые боеприпасы для дорогих дворфийских охотничьих ружей, созданные для экспедиций на крупную дичь.",["race:Dwarf"]="Эта доставка — дело исключительно дворфов: она связывает торговые дела Крейвела Углебрада на соляных равнинах со знаменитой охотничьей партией Незингвари в Восточных королевствах."},sec={{t="Доставка в джунгли",b="Сундук Крейвела, который выдает расчетливый делец Крейвел Углебрад на Виражах на Миражах, — это незавершенная торговая сделка между континентами. Заказ сделал несколько недель назад богатый покупатель-дворф, но поставка задержалась настолько, что он покинул Калимдор. Чтобы не лишиться расположения состоятельного клиента, уже оплатившего пересылку, Крейвел поручает проходящим искателям приключений довезти сундук до северной части Тернистой долины."},{t="Боеприпасы особого калибра",b="Несмотря на невзрачный вид и корку соляной пыли, собранную на Мерцающей равнине, сундук хранит смертоносный груз: тяжелые боеприпасы особого калибра для охотничьих ружей. Когда сундук доставляют в лагерь экспедиции к северу от Гром'гола, получатель отмечает, что мощные патроны ценятся охотниками на крупную дичь и необходимы для выживания среди хищников, бродящих под пологом джунглей."}},faq={{q="Что внутри Сундука Крейвела?",a="Сундук набит охотничьими боеприпасами особого калибра. Тяжелые заряды предназначены для ружей, которыми охотятся на крупных опасных зверей.",al={"what's in the crate","crate contents","what is in kravels crate","что в сундуке","содержимое сундука","что в сундуке крейвела"}},{q="Кто отправил Сундук Крейвела?",a="Его отправил Крейвел Углебрад, торговец-дворф, ведущий дела среди гонок и азартных игр на Виражах на Миражах на Мерцающей равнине в Тысяче Игл.",al={"who gives the crate","who owns kravels crate","кто дает сундук","чей сундук крейвела"}},{q="Куда нужно доставить этот сундук?",a="Сундук нужно доставить в лагерь охотничьей экспедиции Незингвари в северной части Тернистой долины, расположенный у реки к северу от Лагеря Гром'гол.",al={"where to deliver crate","crate destination","who gets kravels crate","куда доставить сундук","пункт назначения сундука","кто получает сундук крейвела"}},{q="Почему доставка задержалась?",a="Посылка добиралась до соляных равнин Тысячи Игл несколько недель, и за это время покупатель уже собрался и уехал в джунгли Тернистой долины.",al={"why did kravel take so long","why delayed","почему крейвел так долго","почему задержка"}}},fp="14,270,24.473.0,24.405.0,30.174.0,24.158.0,33.152.0,29.176.0"}
P.entries["item:kreenig-snarlsnout-s-tusk"] = {n="Клык Кринига Грознорыла",s="Клык Кринига Грознорыла — жуткий охотничий трофей, снятый с вожака налетчиков-свинобразов Иглогривых на севере Степей. Отсеченный клык служит Торку на Перекрестке неоспоримым доказательством того, что угроза караванам Орды устранена.",h="Клык Кринига Грознорыла — жуткий охотничий трофей, снятый с вожака налетчиков-свинобразов Иглогривых на...",kw={"barrens","crossroads","kreenig","quilboar","razormane","snarlsnout","thork","tusk","степи","перекресток","криниг","свинобраз","иглогривые","грознорыл","торк","клык"},ang={["faction:Horde"]="Караваны с оружием, припасами и поселенцами из Дуротара — жизненная артерия расширения Орды в Степях. Доставив этот клык, вы защитите эти важные пути.",["race:Orc"]="Трофей с побежденного командира отражает суровую практичную войну, которую предпочитают орки Перекрестка: он демонстрирует силу и сеет панику среди врагов."},sec={{t="Трофей сломленных амбиций",b="Караваны снабжения, идущие на запад из Дуротара в Степи, постоянно подвергаются нападениям, но недавние атаки стали все наглее под руководством свирепого вожака Иглогривых по имени Криниг Грознорыл. Чтобы нарушить согласованность действий свинобразов, Торк, командир стражи Перекрестка, приказал уничтожить Грознорыла. Клык вождя не только служит весомым доказательством гибели налетчика, но и становится намеренным оскорблением племени Иглогривых, подрывая их решимость и оставляя бойцов без единого руководства."}},faq={{q="Кем был Криниг Грознорыл?",a="Криниг Грознорыл был видным вожаком свинобразов Иглогривых, расположившихся к северо-востоку от Перекрестка. Он организовывал яростные набеги на караваны снабжения Орды, идущие по главной дороге из Дуротара, и до самой смерти превращал путь снабжения в опасное место.",al={"kreenig snarlsnout","who is kreenig","snarlsnout lore","криниг грознорыл","кто такой криниг","грознорыл предания"}},{q="Почему Торку нужен именно клык?",a="Торк требует клык и как неоспоримое доказательство смерти Кринига, и как жгучее оскорбление племени Иглогривых. Отнять клык у павшего вождя свинобразов — значит унизить их гордость и обескуражить уцелевших налетчиков.",al={"why tusk","why bring tusk to thork","thork tusk","зачем клык","зачем нести клык торку","торк клык"}},{q="Откуда взят этот клык?",a="Клык берут из лагеря Кринига Грознорыла к северо-востоку от Перекрестка, у подножия гор, чуть южнее главной дороги, ведущей из Дуротара в Степи.",al={"where is kreenig","where to get tusk","snarlsnout location","где криниг","где взять клык","грознорыл местонахождение"}},{q="Как гибель Кринига влияет на Степи?",a="Торк полагает, что после устранения Кринига налетчики Иглогривых растеряются без вожака. Гибель их командира вызывает хаос в рядах и резко сокращает нападения на важные поставки.",al={"did raids stop","consequences of kreenig death","прекратились ли набеги","последствия смерти кринига"}}},fp="25,274,28.552.0,27.267.0,42.223.0,26.192.0,57.213.0"}
P.entries["item:kron-s-amulet"] = {n="Амулет Крона",s="Амулет Крона — личная памятная вещь Крона, юного орка-охотника из Дуротара, пропавшего у реки Строптивой.",h="Амулет Крона — личная памятная вещь Крона, юного орка-охотника из Дуротара, пропавшего у реки Строптивой.",kw={"amulet","dreadmaw crocolisk","kron","misha tor'kren","razor hill","southfury river","амулет","крупнозубый кроколиск","крон","майша тор'крен","колючий холм","река строптивая"},ang={["class:Hunter"]="Суровый урок для любого начинающего следопыта о том, как опасно недооценивать свирепых зверей на незнакомой речной территории.",["race:Orc"]="Судьба Крона — трагическое напоминание о том, что хотя гордость и воинская слава движут традициями орков, безрассудство и пренебрежение мудростью старших могут привести к скорой и ненужной смерти."},sec={{t="Трагедия на Строптивой",b="Крон был упрямым молодым орком с фермы к северо-западу от Колючего Холма. Желая доказать свою удаль и пренебрегая опасностью, он отправился охотиться на свирепых крупнозубых кроколисков, обитающих у реки Строптивой на границе со Степями. Не послушав предостережений матери, Майши Тор'крен, он из упрямой гордости попал прямо в пасти речных хищников. Он так и не вернулся, оставив лишь эту проглоченную безделушку как безмолвное подтверждение того, что его убили и сожрали."}},faq={{q="Кем был Крон?",a="Крон был импульсивным юным орком-охотником, жившим с матерью, Майшей Тор'крен, на ферме к северо-западу от Колючего Холма. Желая испытать свою силу, он в одиночку отправился охотиться на речных тварей, несмотря на предупреждения об их свирепости.",al={"who is kron","kron backstory","kron lore","кто такой крон","история крона","крон предания"}},{q="Где найти Амулет Крона?",a="Амулет достают из желудков крупнозубых кроколисков и оскверненных крупнозубых кроколисков, прячущихся на берегах реки Строптивой в Дуротаре.",al={"where do i find the amulet","kron's amulet location","who drops kron's amulet","где найти амулет","где амулет крона","кто роняет амулет крона"}},{q="Кто просит вернуть Амулет Крона?",a="Его скорбящая мать, Майша Тор'крен, ждет вестей о сыне на своей ферме к северо-западу от Колючего Холма. Амулет дает ей последнее, мучительное завершение, необходимое, чтобы начать оплакивать сына.",al={"who needs the amulet","where to turn in kron's amulet","misha tor'kren","кому нужен амулет","куда сдать амулет крона","майша тор'крен"}}},fp="13,131,24.492.1,13.229.0,29.156.1,33.178.1"}
P.entries["item:kuz-s-skull"] = {n="Череп Каза",s="Череп Каза — отсеченная голова Каза, видного налетчика-свинобраза Иглогривых на юге Степей. Каз пришел из Лабиринтов Иглошкурых, помогал организовывать жестокие набеги на форпосты Орды, пока пленный бывший сородич не добился его смерти.",h="Череп Каза — отсеченная голова Каза, видного налетчика-свинобраза Иглогривых на юге Степей.",kw={"barrens","camp taurajo","kuz","kuz's skull","lok orcbane","mangletooth","nak","razormane","степи","лагерь таурахо","каз","череп каза","лок губитель орков","кривозуб","нак","иглогривые"},ang={["faction:Horde"]="Убийство Каза напрямую защищает поселения Орды, такие как Перекресток и Лагерь Таурахо, от организованной войны свинобразов."},sec={{t="Горькая вражда",b="Равнины южных Степей кишат племенем Иглогривых, но их организованная агрессия исходит от определенных вожаков, посланных прямо из Лабиринтов Иглошкурых. Каз вместе с Наком и их безжалостным вождем Локом Губителем Орков координировал жестокие вторжения против путников и поселений вроде Перекрестка. Однако их внутреннее предательство стало их погибелью. Предав своего собрата-свинобраза Кривозуба и бросив его гнить в клетке в Лагере Таурахо, они нажили мстительного врага. Кривозуб выдал местонахождение Каза героям Орды, готовым отсечь голову налетчика и навсегда положить конец его набегам."},{t="Доказательство возмездия",b="Череп Каза, принесенный в Лагерь Таурахо, служит мрачным подтверждением того, что уничтожена треть командования южного отряда. Для Кривозуба эта голова — сладкое удовлетворение за месть племени, бросившему его. Для Орды, расквартированной по всем Степям, гибель Каза ломает хребет согласованным наступлениям Иглогривых, разрушая их руководство и давая временную передышку дорогам снабжения, соединяющим равнины."}},faq={{q="Кем был Каз?",a="Каз был одним из трех хитрых свинобразов Иглогривых, посланных из Лабиринтов Иглошкурых на юг Степей. Вместе с Наком и Локом Губителем Орков он помогал направлять смертоносные засады и набеги на лагеря и пути снабжения Орды.",al={"who is kuz","kuz lore","kuz razormane","кто такой каз","каз предания","каз иглогривый"}},{q="Почему Кривозуб хочет череп Каза?",a="Кривозуба предали и бросили умирать в клетке в Лагере Таурахо его же сородичи. Жаждая мести до собственной смерти, он направляет искателей приключений Орды перебить его вероломных соперников и принести их черепа в доказательство.",al={"why mangletooth wants kuz dead","mangletooth revenge","почему кривозуб хочет смерти каза","месть кривозуба"}},{q="Где в Степях находится Каз?",a="Каз бродит глубоко на юге Степей, расположившись со свинобразами Иглогривыми к югу от Лагеря Таурахо, у колючих пограничных земель.",al={"kuz location","where to find kuz","каз местонахождение","где найти каза"}},{q="Что происходит после гибели Каза?",a="Если принести Кривозубу Череп Каза вместе с головами Нака и Лока Губителя Орков, руководство, направляющее набеги Иглогривых, будет разрушено, что откроет путь к защите южных торговых путей.",al={"kuz quest reward","betrayal from within outcome","награда за каза","итог предательства изнутри"}}},fp="11,256,13.607.0,20.438.1,12.218.0,38.236.0,34.145.0,32.191.0"}
P.entries["item:laced-pumpkin"] = {n="Отравленная тыква",s="Отравленная тыква — обычная тыква, обработанная смертельным составом, который разработал аптекарь Юхан в Брилле. Ее дают голодающему пленному ревнителю из Алого ордена под видом пищи, и она служит живой полевой проверкой растущего арсенала алхимического оружия Отрекшихся.",h="Отравленная тыква — обычная тыква, обработанная смертельным составом, который разработал аптекарь Юхан в...",kw={"apothecary johaan","brill","captured scarlet zealot","gallows' end","laced pumpkin","royal apothecary society","tirisfal glades","аптекарь юхан","брилл","пленный ревнитель из алого ордена","петля висельника","отравленная тыква","королевское фармацевтическое общество","тирисфальские леса"},ang={["faction:Alliance"]="Судьба пленного ревнителя — суровое и ужасное напоминание о том, какая жуткая участь ждет любого живого человека, захваченного в землях Отрекшихся.",["race:Undead"]="Для Отрекшихся превращение обычной еды в оружие показывает практичность Королевского фармацевтического общества, готового на любые средства, чтобы защитить Тирисфаль от рьяных живых крестоносцев."},sec={{t="Горький урожай",b="Неопытному глазу отравленная тыква кажется обычным овощем, спасенным с зараженной земли Тирисфальских лесов. Однако под надзором аптекаря Юхана в Брилле овощ обрабатывают экспериментальными токсинами, призванными раскрыть весь потенциал нежизни. Королевское фармацевтическое общество постоянно ищет новое оружие, чтобы отразить и Плеть на севере, и живых людей, наступающих с юга, превращая даже простые дары урожая в источники заразы и химической смерти."},{t="Эксперимент в подвале",b="Главное назначение отравленной тыквы — практические испытания на живых существах. В сыром подвале Таверны «Петля висельника» Отрекшиеся держат изголодавшегося Пленного ревнителя из Алого ордена. Отчаянно нуждаясь в пище, узник с облегчением принимает отравленное подношение. Съев тыкву, он испытывает жестокое превращение под действием состава аптекаря: человек-ревнитель становится безмозглым вурдалаком, который недолго бредет в муках и падает мертвым на холодный каменный пол."}},faq={{q="Что такое Отравленная тыква?",a="Это полевая тыква, в которую введен экспериментальный состав аптекаря Юхана из Брилла. Она предназначена для проверки действия алхимии Отрекшихся на живых существах.",al={"laced pumpkin","poison pumpkin","johaan pumpkin","отравленная тыква","ядовитая тыква","тыква юхана"}},{q="Кто съедает Отравленную тыкву?",a="Ее съедает Пленный ревнитель из Алого ордена, которого пленители морят голодом в подвале Таверны «Петля висельника» в Брилле.",al={"who eats it","pumpkin target","feed the pumpkin","кто ест тыкву","цель тыквы","накормить тыквой"}},{q="Что происходит, когда кто-то съедает тыкву?",a="The pumpkin is given to the captive zealot as a test of Johaan's latest formula. Its precise effects are revealed when the prisoner eats it.",al={"pumpkin effect","what happens to zealot","zealot ghoul","эффект тыквы","что бывает с ревнителем","ревнитель вурдалак"}},{q="Зачем Отрекшиеся это создали?",a="Аптекарь Юхан и Королевское фармацевтическое общество испытывают новые биологические составы, чтобы бороться и с Плетью на севере, и с наступающими живыми людьми, используя пленных врагов как подопытных.",al={"why make poisoned pumpkin","forsaken plague testing","зачем отравленная тыква","испытание чумы отрекшихся"}}},fp="13,280,16.513.0,21.486.1,26.169.0,27.139.0,43.140.1,31.197.0"}
P.entries["item:laird-s-response"] = {n="Ответ Лайрда",s="Ответ Лайрда — запечатанное послание, написанное солильщиком рыбы Лайрдом в прибрежном порту Аубердин. Письмо адресовано Нессе Песне Теней в Деревне Рут'теран и описывает любопытные экологические различия между морской жизнью материка и необычно крупной рыбой у берегов Тельдрассила.",h="Ответ Лайрда — запечатанное послание, написанное солильщиком рыбы Лайрдом в прибрежном порту Аубердин.",kw={"auberdine","darkshore","fishing","laird","laird's response","nessa shadowsong","rut'theran village","teldrassil","аубердин","темные берега","рыбная ловля","лайрд","ответ лайрда","несса песня теней","деревня рут'теран","тельдрассил"},ang={["race:NightElf"]="Для ночных эльфов, оберегающих берега Тельдрассила, записи Лайрда — любопытная, хотя и слегка тревожная подсказка о том, как молодое Мировое Древо уже оказывает неестественное влияние на окружающую природу."},sec={{t="О чешуе и корнях",b="Изучив отчеты об уловах со всего Сокрытого Моря, Лайрд из Аубердина отметил поразительное расхождение: рыба, выловленная у берегов Тельдрассила, заметно крупнее и многочисленнее той, что ловят на материковых пляжах Темных берегов. В этом письменном ответе Нессе Песне Теней Лайрд излагает свою рабочую гипотезу: неестественное присутствие и необузданная жизненная сила недавно посаженного Мирового Древа могут изменять и стимулировать окрестную морскую жизнь. Письмо доставляют путники, возвращающиеся через воды, и оно вызывает удивление и тихое любопытство среди рыбаков Деревни Рут'теран."}},faq={{q="Что такое Ответ Лайрда?",a="Это письменное послание Лайрда, торговца рыбой и солильщика из Аубердина, написанное в ответ на запрос Нессы Песни Теней из Тельдрассила.",al={"what is this item","lairds response letter","what is lairds response","что это за предмет","письмо ответ лайрда","что такое ответ лайрда"}},{q="Кому пишет Лайрд?",a="Ответ отправлен Нессе Песне Теней, ночной эльфийке, живущей в Деревне Рут'теран у южного основания Тельдрассила.",al={"who receives lairds response","who gets this letter","nessa laird letter","кто получает ответ лайрда","кому письмо","несса письмо лайрда"}},{q="Что говорится в письме о рыбе?",a="Лайрд отмечает, что рыба, пойманная у берегов Тельдрассила, заметно крупнее и обильнее, чем на материковых Темных берегах, и предполагает, что на местную морскую жизнь может влиять само Мировое Древо.",al={"why are the fish big","fish difference darkshore teldrassil","what did laird find","почему рыба большая","разница рыбы темные берега тельдрассил","что обнаружил лайрд"}},{q="Как послание попадает обратно в Деревню Рут'теран?",a="Курьеры могут сесть на обычный паром, отходящий от причалов Аубердина, или договориться о полете на гиппогрифе с распорядительницей полетов Кайлаис Лунное Перо.",al={"how to get back to nessa","ruttheran boat darkshore","auberdine ferry to nessa","как добраться до нессы","рут'теран корабль темные берега","паром аубердин несса"}}},fp="16,298,28.614.0,25.164.0,24.120.0,40.211.0,55.153.0"}
P.entries["item:lake-creeper-moss"] = {n="Мох озерного ползуна",s="Мох озерного ползуна — органическое соединение, добываемое у водных ползунов, обитающих на Рассветных островах озера Лордамер. Это жизненно важный реагент, который Королевское фармацевтическое общество ищет для создания смертоносной новой чумы.",h="Мох озерного ползуна — органическое соединение, добываемое у водных ползунов, обитающих на Рассветных...",kw={"berard","dawning isles","elder lake creeper","faranell","lake creeper","lake creeper moss","lake lordamere","new plague","royal apothecary society","берар","рассветные острова","старший озерный ползун","фаранелл","озерный ползун","мох озерного ползуна","озеро лордамер","новая чума","королевское фармацевтическое общество"},ang={["profession:Herbalism"]="Хотя этот мох растет не на обычной почве, а на водных тварях, он представляет темную, экспериментальную окраину флоры Лордерона, собираемую для аптекарских исследований.",["race:Undead"]="Каждый образец озерного мха, доставленный в Апотекариум, приближает Отрекшихся к совершенству Новой чумы и к мести и Плети, и живым."},sec={{t="Алхимический сбор",b="Мох озерного ползуна растет на шкурах свирепых пресноводных тварей, бродящих по южным Рассветным островам озера Лордамер, и обладает особыми свойствами, рожденными зараженными водами Лордерона. Аптекарь Берар, пока проклятие Аругала не отняло у него разум, описал его в своем дневнике, отметив, что мох напоминает следы на окаменелостях существ, убитых древней чумой в этом озере. Добытые Отрекшимися образцы отправляют прямо в Апотекариум в Подгороде для темных исследований Мастера аптекаря Фаранелла."},{t="Топливо для новой чумы",b="Мох — не просто любопытный водный нарост, а важнейший этап создания фирменного оружия Отрекшихся. Вместе с похожим мхом озерных тихоходов и больными опухолями местных мурлоков Злобного Плавника мох ползуна дает органическую основу для очистки штамма, способного уничтожать и живую ткань, и Плеть. Несмотря на потерю открывшего его пользу аптекаря, Королевское фармацевтическое общество продолжает варить по его рецепту на службе Темной Госпоже."}},faq={{q="Для чего нужен Мох озерного ползуна?",a="Это алхимический реагент, который Мастер аптекарь Фаранелл и Королевское фармацевтическое общество используют для варки и очистки Новой чумы в Подгороде.",al={"creeper moss purpose","why collect lake creeper moss","lake creeper moss use","зачем мох ползуна","зачем собирать мох озерного ползуна","применение мха ползуна"}},{q="Откуда берется этот мох?",a="Его собирают с озерных ползунов и старших озерных ползунов, обитающих в водах у южных Рассветных островов в восточной части озера Лордамер.",al={"where to get creeper moss","creeper moss location","lake creeper location","где взять мох ползуна","где мох ползуна","где озерный ползун"}},{q="Кто открыл алхимическую ценность мха?",a="Аптекарь Берар описал особые свойства мха в полевом дневнике, прежде чем проклятие Аругала превратило его в безмозглого слугу в Деревне Погребальных Костров. Позже его записи нашел аптекарь Ренферрел.",al={"who found the moss","berard moss","who wrote about creeper moss","кто нашел мох","мох берара","кто писал о мхе ползуна"}},{q="Кто принимает собранный мох?",a="Мастер аптекарь Фаранелл принимает мох в Апотекариуме Подгорода и соединяет его с Мхом озерного тихохода и затвердевшей опухолью для продвижения своих исследований.",al={"who wants creeper moss","turn in creeper moss","faranell moss","кому нужен мох ползуна","сдать мох ползуна","фаранелл мох"}}},fp="17,247,18.555.0,22.522.1,35.149.0,31.142.0,43.205.0,32.163.0"}
P.entries["item:lake-skulker-moss"] = {n="Мох озерного тихохода",s="Мох озерного тихохода — биологический реагент, добываемый у земноводных жесткозубов, обитающих в северных частях озера Лордамер. Покойный аптекарь Берар определил его как ключевой органический компонент для исследований Королевского фармацевтического общества по созданию Новой чумы.",h="Мох озерного тихохода — биологический реагент, добываемый у земноводных жесткозубов, обитающих в северных...",kw={"berard","dawning isles","faranell","lake lordamere","lake skulker","lake skulker moss","new plague","renferrel","берар","рассветные острова","фаранелл","озеро лордамер","озерный тихоход","мох озерного тихохода","новая чума","ренферрел"},ang={["race:Undead"]="Каждая партия собранного мха приближает Королевское фармацевтическое общество к совершенству Новой чумы — величайшего оружия Отрекшихся против Плети и живых."},sec={{t="Реагент для чумы",b="Этот влажный водный мох, собираемый со шкур и панцирей озерных тихоходов и старших озерных тихоходов на Рассветных островах, обладает свойствами, ценными для алхимиков Отрекшихся. До своей гибели аптекарь Берар тщательно описывал флору и фауну восточного Серебряного бора и заключил в дневнике, что мхи озерного тихохода и озерного ползуна могут служить стабилизирующими или реактивными средствами. После смерти Берара аптекарь Ренферрел нашел эти записи и поручил защитникам Отрекшихся собрать образцы мха вместе с редкой опухолью местных мурлоков Злобного Плавника и доставить их Мастеру аптекарю Фаранеллу в Подгород."}},faq={{q="Для чего нужен Мох озерного тихохода?",a="Королевское фармацевтическое общество в Подгороде использует его как органическую основу для создания Новой чумы на благо целей леди Сильваны Ветрокрылой и Отрекшихся.",al={"moss use","why collect skulker moss","what does skulker moss do","применение мха","зачем собирать мох тихохода","что делает мох тихохода"}},{q="Откуда берется этот мох?",a="Мох соскребают с тел озерных тихоходов и старших озерных тихоходов, водных тварей, обитающих в водах у Рассветных островов в северо-восточной части озера Лордамер, недалеко от берегов Серебряного бора.",al={"where to get skulker moss","skulker moss location","who drops lake skulker moss","где взять мох тихохода","где мох тихохода","с кого падает мох озерного тихохода"}},{q="Кто открыл пользу этого мха?",a="Аптекарь Берар первым заметил его потенциал во время полевых исследований в Серебряном бору. Хотя Берар погиб, его уцелевший дневник помог аптекарю Ренферрелу и Мастеру аптекарю Фаранеллу продолжить его опыты.",al={"who found the moss","berard moss","apothecary berard research","кто нашел мох","мох берара","исследования аптекаря берара"}},{q="Кому нужен этот реагент?",a="Мастеру аптекарю Фаранеллу, главе Королевского фармацевтического общества, живущему в Апотекариуме Подгорода, нужен мох для продвижения его проектов биологической войны.",al={"who wants skulker moss","faranell skulker moss","кому нужен мох тихохода","фаранелл мох тихохода"}}},fp="17,289,16.662.0,35.188.0,31.209.0,37.234.0,26.179.0"}
P.entries["item:large-candle"] = {n="Большая свеча",s="Большие свечи — восковые свечи, которые ценят и носят кобольды, роющиеся в шахтах Элвиннского леса. Закрепленные на голове, эти грубые светильники освещают подземные туннели и служат надежным источником воска для людей-аптекарей.",h="Большие свечи — восковые свечи, которые ценят и носят кобольды, роющиеся в шахтах Элвиннского леса.",kw={"fargodeep mine","goldshire","goldtooth","jasperlode mine","kobold candles","large candle","wax","william pestle","рудник подземных глубин","златоземье","золотозуб","яшмовая шахта","свечи кобольдов","большая свеча","воск","вильям пест"},ang={["faction:Alliance"]="Отбирая свечи у кобольдов Элвиннского леса, искатели приключений Альянса ослабляют вредителей, заполонивших шахты, и поставляют важные материалы аптекарям Штормграда.",["profession:Mining"]="Шахтеры, работающие на жилах Подземных Глубин и Яшмовой шахты, регулярно сталкиваются с кобольдами, которым нужны и золото, и мерцающий свет этих больших свечей."},sec={{t="Подземный свет и воск",b="Кобольды, роющие туннели под Элвиннским лесом, полагаются на пламя свечей, чтобы ориентироваться в кромешной тьме шахт, и крепят восковые свечи прямо на голову. Кобольды-шахтеры, проходчики и геоманты яростно защищают свечи от чужаков. Несмотря на грубое изготовление, большие свечи из Рудника Подземных Глубин и Яшмовой шахты содержат ценный воск, который торговцам на поверхности трудно производить в больших количествах, и обычный инструмент чудовищ становится алхимическим товаром."},{t="Торговля и аптекарь",b="Вильям Пест, аптекарь из Штормграда, собирает эти огромные свечи в Таверне Гордость Льва в Златоземье. Ему нужен вытопленный воск для составов, бальзамов и мазей его семейной аптеки, и Пест нанимает проходящих искателей приключений, чтобы они очищали зараженные шахты и забирали свечи у подземных захватчиков."}},faq={{q="Для чего нужны Большие свечи?",a="Вильям Пест собирает Большие свечи в Златоземье для аптеки своего брата в Штормграде. Там свечи вытапливают, а воск используют как ингредиент для мазей, бальзамов и алхимических рецептов.",al={"large candle use","why get large candles","who wants large candles","применение большой свечи","зачем большие свечи","кому нужны большие свечи"}},{q="Где можно найти Большие свечи?",a="Их носят кобольды, обитающие в шахтах Элвиннского леса, преимущественно в Руднике Подземных Глубин к югу от Златоземья и в Яшмовой шахте на востоке. Свечи носят проходчики, шахтеры и геоманты.",al={"large candle location","where to get large candles","kobold candle drops","где большие свечи","где взять большие свечи","свечи с кобольдов"}},{q="Почему кобольды носят свечи на голове?",a="Кобольды живут в кромешной тьме подземных туннелей, и им нужен свет, чтобы копать и ориентироваться. Они крепят свечи на голове, чтобы руки оставались свободными для кирок, геомантических заклинаний и оружия.",al={"why do kobolds have candles","kobold head candle lore","почему у кобольдов свечи","свеча на голове кобольда"}},{q="Кто такой Вильям Пест?",a="Вильям Пест — аптекарь из Штормграда, ведущий дела в Таверне Гордость Льва в Златоземье. Он собирает сырье в окрестностях и шахтах для аптеки, которой владеет вместе с братом.",al={"william pestle lore","who is the apothecary guy in goldshire","вильям пест","кто аптекарь в златоземье"}}},fp="12,253,26.490.0,24.353.0,32.240.0,33.200.0,44.203.0,22.233.0"}
P.entries["item:large-soran-ruk-fragment"] = {n="Большой фрагмент Соран'рука",s="Большой фрагмент Соран'рука — крупный осколок древнего артефакта, наполненного демонической энергией. Некогда в нем обитал дух опального демона Пылающего Легиона, а затем осколок попал в руки зловещих чародеев в стенах Крепости Темного Клыка, полных призраков.",h="Большой фрагмент Соран'рука — крупный осколок древнего артефакта, наполненного демонической энергией.",kw={"burning legion","doan karhan","large soran'ruk fragment","orb of soran'ruk","shadowfang keep","soran'ruk","пылающий легион","доан кархан","большой фрагмент соран'рука","сфера соран'рука","крепость темного клыка","соран'рук"},ang={["class:Warlock"]="Вернув Большой фрагмент Соран'рука, вы сможете подчинить заточенного внутри демонического духа и помочь Доану Кархану создать мощное оружие для демонической магии."},sec={{t="Наследие Соран'рука",b="Когда демоны Пылающего Легиона впадают в немилость у своих темных повелителей, их духи порой заточают в зачарованные сферы. Затем эти сосуды раздают магам и чернокнижникам, служащим Легиону, и те черпают скрытую в них мощь Скверны. Даже разбитый на осколки, сосуд хранит остаточную силу плененного демона, поэтому каждый фрагмент ценится честолюбивыми адептами темной магии."},{t="Осколок в Темном Клыке",b="Сфера Соран'рука давным-давно раскололась на две половины. Одну часть раздробили еще сильнее и рассеяли среди сектантов в других местах, а большую половину забрал себе чародей, обитавший в проклятой Крепости Темного Клыка. Там Большой фрагмент Соран'рука носят зловещие Темные души Темного Клыка, и он источает демоническую силу, пока за ним не придут те, кто надеется вновь собрать древний сосуд."}},faq={{q="Что такое Большой фрагмент Соран'рука?",a="Это большая половина Сферы Соран'рука — древнего магического сосуда с заточенным духом опального демона Пылающего Легиона.",al={"large soranruk fragment","soranruk large fragment","what is this fragment","большой фрагмент соран'рука","большой осколок соран'рука","что это за фрагмент"}},{q="Где находится фрагмент?",a="Фрагмент хранится у Темных душ Темного Клыка — злобных чародеев, обитающих в Крепости Темного Клыка, полной призраков, в Серебряном бору.",al={"where do i find the large fragment","large fragment location","who drops large soranruk fragment","где найти большой фрагмент","где взять большой фрагмент","кто выбивает большой фрагмент соран'рука"}},{q="Почему сфера была разбита?",a="Первоначальная сфера раскололась на две основные части. Меньшую половину разбили на мелкие осколки и отнесли в прибрежные пещеры Непроглядной Пучины, а эту большую часть сохранили темные чародеи в Крепости Темного Клыка.",al={"how did the orb break","why is the orb fragmented","orb of soranruk history","как разбилась сфера","почему сфера расколота","история сферы соран'рука"}},{q="Кто хочет собрать ее заново?",a="Доан Кархан, отшельник-затворник, живущий на юге Степей, посвятил жизнь изучению и восстановлению утерянных сфер Пылающего Легиона.",al={"who needs the large fragment","who reassembles the orb","кому нужен большой фрагмент","кто собирает сферу"}}},fp="24,276,23.468.0,23.410.0,37.145.0,28.147.0,23.229.0,27.169.0"}
P.entries["item:laughing-sister-s-hair"] = {n="Волосы смеющейся сестрички",s="Волосы смеющейся сестрички — мягкие волшебные пряди, которые собирают у дриад, обитающих в зачарованных чащах Ясеневого леса. Эти пряди, обладающие природными магическими свойствами, высоко ценятся искусными ткачами и подходят для изготовления тонких одеяний.",h="Волосы смеющейся сестрички — мягкие волшебные пряди, которые собирают у дриад, обитающих в зачарованных чащах...",kw={"ashenvale","cloth","crossroads","deino","dryad","hair","kil'hala","laughing sister","raynewood retreat","ясеневый лес","ткань","перекресток","дейно","дриада","волосы","кил'хала","смеющаяся сестричка","приют в ночных лесах"},ang={["faction:Horde"]="Чтобы добыть эти пряди, нужно проникнуть на земли ночных эльфов в Ясеневом лесу и убить лесных духов, а это показывает готовность Орды брать местную магию силой.",["profession:Tailoring"]="Эфирные волосы дриад — один из самых экзотических источников нити в Калимдоре; их ценят за то, что они вплетают в ткань природную магию."},sec={{t="Редкий материал для ткачества",b="Эти волосы собирают у дриад, известных как смеющиеся сестрички, близ Приюта в Ночных Лесах в Ясеневом лесу, и в них заключена удивительная природная магия. Дриады — священные защитницы лесов, связанные с Кенарием и ночными эльфами, но мастера Орды ценят их волосы лишь как сильный реагент для ремесла. Тролль-портной Кил'хала на Перекрестке прядет эти пряди в зачарованные одеяния для начинающих владеть тайными искусствами."}},faq={{q="Откуда берутся Волосы смеющейся сестрички?",a="Волосы собирают у смеющихся сестричек — дриад, бродящих по зачарованным рощам близ Приюта в Ночных Лесах в центре Ясеневого леса.",al={"where to get laughing sisters hair","laughing sister hair location","dryad hair source","где достать волосы смеющейся сестрички","волосы смеющейся сестрички где найти","откуда волосы дриад"}},{q="Зачем Кил'хале волосы дриад?",a="Кил'хала — искусный портной, живущий на Перекрестке в Степях. Из волшебных прядей он ткет зачарованные тканевые одеяния для многообещающих учеников Дейно.",al={"why kilhala wants hair","use for laughing sister hair","troll tailor dryad hair","зачем кил'хале волосы","применение волос смеющейся сестрички","тролль портной волосы дриад"}},{q="Отдадут ли смеющиеся сестрички свои волосы добровольно?",a="Нет. Смеющиеся сестрички — свирепые стражи природы и верные защитницы Ясеневого леса. Как сухо замечает Кил'хала, дриады ни за что не отдадут свои волосы добровольно слугам Орды.",al={"can you ask dryads for hair","do dryads donate hair","можно ли попросить у дриад волосы","отдают ли дриады волосы"}}},fp="22,244,24.435.0,44.128.0,39.175.0,55.189.0"}
P.entries["item:legacy-of-the-aspects"] = {n="Наследие Аспектов",s="Наследие Аспектов — древний фолиант, спрятанный в глубине Обители Дор'Данил на юге Ясеневого леса. Его добывают в ходе испытания разума, которое проходят в Орде; в книге содержатся важные сведения о Великих Аспектах, повлиявших на древний Азерот.",h="Наследие Аспектов — древний фолиант, спрятанный в глубине Обители Дор'Данил на юге Ясеневого леса.",kw={"ashenvale","barrow den","braug dimspirit","dor'danil","legacy of the aspects","talondeep path","test of lore","ясеневый лес","обитель","брауг тусклый дух","дор'данил","наследие аспектов","туннель когтя","испытание знаний"},ang={["class:Druid"]="Текст лежит глубоко в Обители Дор'Данил, среди трагических, измученных духов павших друидов-ночных эльфов.",["faction:Horde"]="Этот фолиант — центральная часть традиционного обряда посвящения, который проверяет, хватает ли воинам Орды мудрости и знаний, чтобы соответствовать их физической мощи."},sec={{t="Испытание разума",b="Если прежние испытания, назначаемые старейшинами тауренов, проверяют выносливость и стойкость, то поиск Наследия Аспектов призван испытать ум. Получив задание от Брауга Тусклого Духа у входа в Туннель Когтя в Когтистых горах, соискатель должен спуститься в населенные призраками норы Дор'Данил. Древний текст лежит на каменном постаменте, а охраняют его неупокоенные духи павших друидов и свирепые твари, убившие их. Забрать книгу — лишь первый шаг: прежде чем отдать том, соискатель должен запомнить его содержание, ведь его проверят на исторических уроках."}},faq={{q="Где находится книга?",a="Книга лежит на каменном постаменте в нижних залах Обители Дор'Данил на юге Ясеневого леса, к югу от Заставы Расщепленного Дерева.",al={"find legacy of the aspects","book location","where is book","найти наследие аспектов","где книга","где находится книга"}},{q="Зачем Браугу Тусклому Духу эта книга?",a="Брауг Тусклый Дух использует книгу для Испытания знаний. В отличие от физических испытаний, оно призвано выяснить, хватает ли искателю приключений ума и внимательности, чтобы изучить и запомнить важные исторические сведения.",al={"why braug wants book","test of lore purpose","зачем браугу книга","цель испытания знаний"}},{q="Что будет, если не изучить текст до разговора с Браугом?",a="Брауг расспрашивает соискателей о сведениях из книги сразу после того, как они ее принесут. Неверный ответ влечет мгновенное магическое изгнание: неподготовленного просителя переносит далеко, в Лагерь Таурахо в Степях.",al={"wrong answer consequence","failing the test","последствия неверного ответа","провал испытания"}}},fp="21,249,18.619.0,26.148.0,40.234.0,68.231.0"}
P.entries["item:letter-to-delgren"] = {n="Письмо Делгрену",s="Письмо Делгрену — срочное послание, написанное Балтулом Ударом Тени близ Башни Алталакса на севере Темных берегов. Оно адресовано его наставнику, паладину Делгрену Очистителю, и описывает зловещие деяния демонического культа Темной Нити. Доставив его на юг, на Заставу Мейстры в Ясеневом лесу, вы передадите важные сведения.",h="Письмо Делгрену — срочное послание, написанное Балтулом Ударом Тени близ Башни Алталакса на севере Темных...",kw={"ashenvale","balthule shadowstrike","dark strand","darkshore","delgren the purifier","letter to delgren","maestra's post","tower of althalaxx","ясеневый лес","балтул удар тени","темная нить","темные берега","делгрен очиститель","письмо делгрену","застава мейстры","башня алталакса"},ang={["class:Paladin"]="Это послание показывает необычное товарищество: паладин-человек обучает ученика-ночного эльфа Свету, соединяя древние земли кальдораев с воинской верой Восточных королевств.",["faction:Alliance"]="Послание отражает растущее сотрудничество в Альянсе: человеческие воители и Часовые ночных эльфов объединяются против демонических культов, проникающих на север Калимдора."},sec={{t="Предупреждение, посланное на юг",b="Пока сектанты Темной Нити собираются вокруг руин Башни Алталакса, ночной эльф Балтул Удар Тени следит за ростом их злобы. Не имея сил уничтожить культ в одиночку, Балтул пишет это послание, чтобы просить помощи у своего наставника в Свете, Делгрена Очистителя. Поскольку мерзкие обряды культа угрожают не только побережью Темных берегов, послание нужно пронести через весь край на запад Ясеневого леса, где Делгрен вместе с Часовыми ночных эльфов выслеживает демонов и нежить."}},faq={{q="Что такое Письмо Делгрену?",a="Это запечатанное послание Балтула Удара Тени о растущей активности демонического культа Темной Нити у Башни Алталакса. Оно адресовано паладину Делгрену Очистителю.",al={"what is this letter","letter to delgren","balthule's letter","что это за письмо","письмо делгрену","письмо балтула"}},{q="Кто такой Делгрен Очиститель?",a="Делгрен — паладин-человек, живущий на Заставе Мейстры на западе Ясеневого леса. Преданный Свету, он предложил свое боевое мастерство Часовым ночных эльфов в борьбе с демонами и нежитью в древних лесах и наставляет Балтула в священной войне.",al={"who is delgren","delgren lore","where is delgren","кто такой делгрен","делгрен предания","где делгрен"}},{q="Почему Балтул отправляет письмо так далеко?",a="Балтул — ученик Делгрена и рассчитывает именно на опыт наставника в борьбе с демонической порчей. У Делгрена есть и боевое мастерство, и поддержка местных Часовых на Заставе Мейстры, чтобы организованно противостоять темным ритуалам Темной Нити.",al={"why send to ashenvale","why not tell auberdine","почему в ясеневый лес","почему не сообщить в аубердин"}},{q="Куда нужно доставить это письмо?",a="Письмо нужно пронести на юг через все Темные берега и через границу в Ясеневый лес, до Заставы Мейстры по западной дороге.",al={"where do i take the letter","letter delivery location","куда нести письмо","куда доставить письмо"}}},fp="17,335,20.573.0,30.200.0,28.267.0,47.270.0,44.143.0"}
P.entries["item:letter-to-ello"] = {n="Письмо к Элло",s="Письмо к Элло — запечатанное послание, написанное Аберкромби, чудаковатым отшельником, живущим близ Приюта Бродяги в Сумеречном лесу. Оно адресовано мэру Темнолесья Элло Чернодреву, и отшельник вручает его, ссылаясь на старую дружбу, хотя текст написан древними письменами.",h="Письмо к Элло — запечатанное послание, написанное Аберкромби, чудаковатым отшельником, живущим близ Приюта...",kw={"abercrombie","darkshire","duskwood","ello ebonlocke","letter to ello","note to the mayor","sirra von'indi","аберкромби","темнолесье","сумеречный лес","элло эбонлок","письмо к элло","записка мэру","шира фон-инди"},ang={["faction:Alliance"]="Доставлять послания между чудаковатыми затворниками и мэрами городков — обычное дело для путников в Сумеречном лесу, хотя городские чиновники Темнолесья постоянно настороженно относятся к странным письмам."},sec={{t="Странное приветствие",b="После того как искатели приключений помогают отшельнику Аберкромби с поручениями в Сумеречном лесу, старый затворник вручает им эту записку, утверждая, что мэр Элло Эбонлок — его старый друг и порадуется сделанному. На деле мэр Темнолесья не помнит никого по имени Аберкромби. Сломав печать, мэр Эбонлок обнаруживает, что не может разобрать ни единой фразы древнего письма, и отправляет записку для перевода темнолесскому ученому Шире Фон-Инди."},{t="Темные предзнаменования",b="За кажущимся невинным поручением скрываются истинные, мрачные замыслы отшельника. Это вовсе не дружеский обмен между старыми знакомыми: древние руны, начертанные Аберкромби, сулят гибель всему Темнолесью."}},faq={{q="Кто написал Письмо к Элло?",a="Письмо написал Аберкромби, отшельник, живущий в полуразвалившейся хижине близ Кладбища Вороньего Холма на западе Сумеречного леса.",al={"who wrote the letter","letter to ello author","who sent the letter","кто написал письмо","автор письма к элло","кто отправил письмо"}},{q="Может ли мэр Элло Эбонлок прочесть письмо?",a="Нет. Когда письмо доставляют мэру Эбонлоку в Темнолесье, он находит письмена совершенно непонятными и замечает, что они написаны на древнем, незнакомом языке.",al={"can ello read it","why cant ello read the note","ello letter language","может ли элло прочесть","почему элло не может прочесть записку","язык письма элло"}},{q="Кто может перевести записку?",a="Мэр Эбонлок велит посыльным отнести послание Шире Фон-Инди, ученому из Темнолесья, сведущему в древних письменах и тайных языках.",al={"who translates the note","translate abercrombie note","who can read the letter","кто переведет записку","перевод записки аберкромби","кто может прочесть письмо"}},{q="Знает ли мэр Эбонлок Аберкромби на самом деле?",a="Хотя Аберкромби утверждает, что они с мэром старые друзья, Элло Эбонлок уверяет, что никогда не слышал ни о ком по имени Аберкромби.",al={"does ello know abercrombie","are ello and abercrombie friends","abercrombie old friends ello","знает ли элло аберкромби","друзья ли элло и аберкромби","старые друзья аберкромби элло"}}},fp="14,293,18.490.0,10.224.1,29.120.0,41.179.0,27.158.0,47.137.0"}
P.entries["item:letter-to-jin-zil"] = {n="Письмо Джин'Зилу",s="Письмо Джин'Зилу — послание, написанное орком Дарсоком Быстрым Ножом на Перекрестке. Оно было вручено искателю приключений после гибели Серены Кровавое Перо и сообщает тролльскому знахарю из племени Черного Копья Джин'Зилу в Когтистых горах, что северные Степи очищены от угрозы Кровавого Пера.",h="Письмо Джин'Зилу — послание, написанное орком Дарсоком Быстрым Ножом на Перекрестке.",kw={"darsok swiftdagger","harpies","jin'zil","letter to jin'zil","malaka'jin","rokhan","serena bloodfeather","stonetalon","дарсок быстрый нож","гарпии","джин'зил","письмо джин'зилу","малака'джин","рохан","серена кровавое перо","когтистые горы"},ang={["faction:Horde"]="Письмо служит мостом для искателей приключений Орды, переходящих от наведения порядка в Степях к более серьезным конфликтам, назревающим в Когтистых горах.",["race:Troll"]="Доставив письмо, тролли племени Черного Копья попадают прямо к знахарю Джин'Зилу — старейшине, продолжающему традиции вуду вдали от Островов Эха."},sec={{t="Гонец в Когтистые горы",b="После уничтожения гарпий в Сухих холмах и гибели Серены Кровавое Перо Дарсок Быстрый Нож составляет это послание старому товарищу. Зная, что гарпии Степей изначально гнездились на вершинах Когтистых гор, Дарсок использует письмо, чтобы представить многообещающего воина жителям дальних рубежей, и заодно извещает знахаря Джин'Зила о гибели предводительницы гарпий."},{t="Старые воспоминания в Малака'джине",b="Когда письмо доставлено в пещеру в Малака'джине, Джин'Зил встречает новость с ностальгическим удовлетворением. Смерть Серены напоминает старому знахарю об основании Дуротара после Третьей войны, когда его друг Рохан вместе с укротителем зверей из народа мок'нати Рексаром убил старшую сестру Серены — Кровавое Перо. Теперь, когда погибла и Серена, Джин'Зил считает месть рода Кровавого Пера окончательно угасшей."}},faq={{q="Кто написал Письмо Джин'Зилу?",a="Письмо написал Дарсок Быстрый Нож, орк, находящийся на Перекрестке в Степях и руководящий обороной от набегов стай гарпий.",al={"who wrote this","letter sender","darsok letter","кто написал","отправитель письма","письмо дарсока"}},{q="Где находится Джин'Зил?",a="Знахарь Джин'Зил живет в пещере в Малака'джине — форпосте троллей племени Черного Копья, укрывшемся среди скал на юго-востоке Когтистых гор.",al={"where is jinzil","jin'zil location","find jinzil","где джин'зил","местонахождение джин'зила","найти джин'зила"}},{q="Какие новости содержатся в письме?",a="Послание сообщает Джин'Зилу, что Серена Кровавое Перо, предводительница гарпий, спускавшихся в северные Степи, убита, и территория к северу от Перекрестка теперь в безопасности.",al={"what does the letter say","letter message","что в письме","содержание письма"}},{q="Почему Джин'Зила волнуют Кровавые Перья?",a="Джин'Зил помнит основание Дуротара после Третьей войны, когда его соратник Рохан и воин мок'нати Рексар убили старшую сестру Серены. С тех пор Серена искала мести Орде, поэтому ее гибель стала долгожданной развязкой.",al={"why jinzil harpies","bloodfeather history","rokhan and bloodfeather","почему джин'зил гарпии","история кровавого пера","рохан и кровавое перо"}}},fp="17,325,25.425.0,26.416.1,32.154.0,25.147.0,41.181.0,46.246.0"}
P.entries["item:letter-to-jorgen"] = {n="Письмо Йоргену",s="Письмо Йоргену — конфиденциальное послание, составленное, чтобы привлечь старого знакомого в Штормграде. Оно служит рекомендацией для агента на раннем этапе расследования исчезновения высокопоставленного дипломата.",h="Письмо Йоргену — конфиденциальное послание, составленное, чтобы привлечь старого знакомого в Штормграде.",kw={"jaina proudmoore","jorgen","letter to jorgen","missing diplomat","stormwind","theramore","valley of heroes","джайна праудмур","йорген","письмо йоргену","пропавший дипломат","штормград","терамор","аллея героев"},ang={["class:Rogue"]="Действовать через тайные донесения и неохотных уличных осведомителей, а не через городскую стражу — привычный и необходимый способ раскрыть злодеяние в столице.",["faction:Alliance"]="Послание затрагивает хрупкую стабильность Альянса: оно стремится тихо уладить происшествие, угрожающее дипломатическим связям между Штормградом и Терамором."},sec={{t="Бесстрастный вызов",b="Когда высокопоставленный дипломат, направлявшийся в Терамор, не прибыл на назначенные переговоры с леди Джайной Праудмур, королевские следователи поспешили скрыть этот случай. Пока официальные агенты прочесывали столицу, тихо задействовали иные каналы. Это запечатанное письмо составили в обход обычной военной бюрократии, и адресовано оно Йоргену — суровому ветерану, который проводит дни за рыбалкой под колоссальными статуями в Аллее Героев. Записка напоминает о старых долгах и втягивает нехотящего помогать знакомого в тайное расследование, к которому примешиваются слухи о заговоре Братства Справедливости."}},faq={{q="Для чего нужно это письмо?",a="Письмо служит рекомендацией и призывом исполнить старый долг. Оно направляет подателя к Йоргену, агенту в Аллее Героев, чтобы подключить независимых людей к делу пропавшего дипломата, не привлекая внимания общественности.",al={"what does letter to jorgen do","why letter to jorgen","letter purpose","зачем письмо йоргену","для чего письмо йоргену","назначение письма"}},{q="Кто такой Йорген?",a="Йорген — нелюдимый знакомый, живущий сразу за вратами Штормграда и проводящий время за рыбалкой у вод Аллеи Героев. Хотя он недоволен, когда его беспокоят, прошлый долг обязывает его помочь тому, кто принесет это послание.",al={"who is jorgen","jorgen npc","jorgen stormwind","кто такой йорген","йорген нпс","йорген штормград"}},{q="С каким исчезновением связано письмо?",a="Видный дипломат отбыл из Штормграда в Терамор на встречу с леди Джайной Праудмур, но пропал в пути. Подозрения падают на Братство Справедливости, хотя все подробности заговора строго хранятся в тайне.",al={"what diplomat is missing","who disappeared","missing diplomat","какой дипломат пропал","кто исчез","пропавший дипломат"}},{q="Куда доставляют письмо?",a="Письмо относят в Аллею Героев — величественный вход в Штормград, обрамленный памятниками героям Второй войны. Йоргена можно найти на берегу воды у главных врат.",al={"where do i take the letter","jorgen location","where is jorgen","куда нести письмо","где йорген","местонахождение йоргена"}}},fp="16,221,23.602.0,35.241.0,14.248.0,45.240.0,30.202.0"}
P.entries["item:lewis-note"] = {n="Записка Льюиса",s="Записка Льюиса — срочная заявка на снабжение, написанная интендантом Льюисом на Сторожевом холме. Ее доставляет гонец на грифоне, и в ней запрашиваются важные поставки защитного снаряжения у частного оружейника в Старом городе Штормграда.",h="Записка Льюиса — срочная заявка на снабжение, написанная интендантом Льюисом на Сторожевом холме.",kw={"gryphon","lewis' note","limited immunity","old town","osric strang","quartermaster lewis","sentinel hill","thor","грифон","записка льюиса","ограниченный иммунитет","старый город","озрик штранг","интендант льюис","сторожевой холм","тор"},ang={["race:Human"]="Доставка этой заявки учит юных людей-искателей приключений пользоваться грифоньей сетью королевства и ярко показывает, как мало правители Штормграда делают для снабжения защитников Западного Края."},sec={{t="Мольба о стали",b="Народное ополчение на Сторожевом холме живет на скудные средства и почти не получает официальной поддержки от Дома знати в Штормграде. Из-за постоянных стычек с Братством Справедливости гарнизон быстро расходует скудные запасы снаряжения. Чтобы защитники были экипированы, интендант Льюис полагается на частные сделки, а не на королевское снабжение. Эта записка полностью обходит официальные военные каналы: курьер Альянса должен долететь на грифоне до Старого города и передать заказ лично Озрику Штрангу, владельцу лавки «Ограниченный иммунитет»."}},faq={{q="Что такое Записка Льюиса?",a="Это письменный заказ интенданта Льюиса со Сторожевого холма к Озрику Штрангу, оружейнику из Штормграда, с просьбой прислать больше защитного снаряжения бедствующему гарнизону Западного Края.",al={"what is this item","lewis note purpose","what does the note do","что это за предмет","зачем записка льюиса","что делает записка"}},{q="Кто написал эту записку?",a="Ее написал интендант Льюис — офицер, отвечающий за припасы, провиант и вооружение Народного ополчения на Сторожевом холме.",al={"who is lewis","quartermaster lewis","кто такой льюис","интендант льюис"}},{q="Кому предназначена записка?",a="Сначала записку относят укротителю грифонов Тору на Сторожевом холме, а затем доставляют лично Озрику Штрангу в его лавку доспехов «Ограниченный иммунитет» в Старом городе Штормграда.",al={"where does the note go","who gets lewis note","osric strang note","куда отнести записку","кто получает записку льюиса","записка озрику штрангу"}},{q="Почему гарнизон просто не получит доспехи от королевства?",a="Правительство королевства в основном пренебрегает Западным Краем, и местные защитники предоставлены сами себе, без прямого военного финансирования и доспехов от короны. Льюису приходится полагаться на личные торговые связи, такие как Озрик Штранг, чтобы ополчение было снаряжено.",al={"why buy from osric","why no stormwind help","stormwind aid westfall","почему покупать у озрика","почему штормград не помогает","помощь штормграда западному краю"}}},fp="11,225,16.605.0,20.184.0,20.160.0,22.202.0,57.255.0"}
P.entries["item:lieutenant-s-insignia"] = {n="Лейтенантский знак отличия",s="Лейтенантский знак отличия — эмблема, которую носят высокопоставленные члены культа Пылающего Клинка, скрывающегося в Дуротаре. Найденный искателями приключений Орды, он служит важным доказательством деятельности культа в опасной близости от Оргриммара.",h="Лейтенантский знак отличия — эмблема, которую носят высокопоставленные члены культа Пылающего Клинка...",kw={"burning blade","cleft of shadow","durotar","hidden enemies","lieutenant's insignia","neeru fireblade","shadow council","skull rock","thrall","пылающий клинок","расселина теней","дуротар","скрытые враги","лейтенантский знак отличия","нииру огненный клинок","совет теней","скала черепа","тралл"},ang={["class:Warlock"]="Знак показывает, как Пылающий Клинок злоупотребляет магией Скверны на службе Пылающему Легиону, что напрямую осложняет шаткую терпимость Тралла к законопослушным чернокнижникам Орды.",["faction:Horde"]="Для юной Орды этот знак олицетворяет коварную угрозу демонической порчи, пытающейся подорвать новое государство Тралла изнутри."},sec={{t="Знак культа",b="Лейтенантский знак отличия, добытый у культистов, засевших в Скале Черепа на восточном берегу Дуротара, указывает, что его владелец — офицер Пылающего Клинка. Вождь Тралл не терпит предателей в своем новом государстве, но открытая чистка лишь рассеяла бы культ, прежде чем удастся разоблачить его хозяев. Поэтому Тралл превращает знак в поддельное удостоверение и возвращает его доверенному защитнику, чтобы проверить верность подозреваемых лазутчиков, скрывающихся прямо под Оргриммаром."},{t="Расселина Теней",b="Тралл поручает своему агенту отнести знак в Расселину Теней и показать его чернокнижнику Нииру Огненному Клинку. Считая, что приветствует недавно повышенного подчиненного, Нииру полностью попадается на приманку. Ослепленный высокомерием, чернокнижник открыто хвастается, что Пылающий Клинок — прямое орудие Совета Теней и Пылающего Легиона, невольно давая Траллу возможность разоблачить скверну, укоренившуюся под городом."}},faq={{q="Откуда берется Лейтенантский знак отличия?",a="Его добывают у фанатиков и учеников Пылающего Клинка в Скале Черепа — пещере на побережье к востоку от Оргриммара в Дуротаре.",al={"how do i get lieutenants insignia","who drops lieutenants insignia","lieutenant insignia source","как получить лейтенантский знак отличия","с кого падает лейтенантский знак","источник лейтенантского знака"}},{q="Для чего нужен этот знак?",a="Вождь Тралл использует знак, чтобы создать маскировку для своего агента. С ним молодой искатель приключений может сойти за офицера Пылающего Клинка и пойти туда, куда не могут проникнуть агенты самого Тралла, чтобы узнать, кто на самом деле руководит культом.",al={"why do i need lieutenants insignia","lieutenants insignia quest use","what to do with insignia","зачем нужен лейтенантский знак","лейтенантский знак задание","что делать со знаком"}},{q="Кто такой Нииру Огненный Клинок?",a="Нииру Огненный Клинок — орк-чернокнижник, живущий в Расселине Теней в Оргриммаре. Заявляя, что служит Траллу и доказывает пользу чернокнижников для Орды, он втайне является местным главой культа Пылающего Клинка.",al={"who is neeru","neeru fireblade lore","кто такой нииру","нииру огненный клинок предания"}},{q="Почему Тралл не убьет Нииру Огненного Клинка сразу?",a="Тралл знает, что Нииру — предатель, но преждевременный удар лишь предупредил бы истинных хозяев культа и рассеял бы их сеть. Тралл предпочитает использовать Нииру как невольного осведомителя, чтобы раскрыть присутствие Совета Теней в Дуротаре.",al={"why thrall doesnt kill neeru","why keep neeru alive","why infiltrate neeru","почему тралл не убивает нииру","зачем оставлять нииру в живых","зачем внедряться к нииру"}}},fp="21,230,18.517.0,19.448.1,47.143.0,30.223.1,23.214.2,57.244.1"}
P.entries["item:lightning-gland"] = {n="Грозовая железа",s="Грозовые железы добывают у буревестных зверей, бродящих по равнинам Степей. Пропитанные природным стихийным зарядом, они нужны Пивовару Дрону в Кабестане для варки огненного, крепкого троггова эля, рецепт которого он узнал от странствующего пандарена Чэня Буйного Портера.",h="Грозовые железы добывают у буревестных зверей, бродящих по равнинам Степей.",kw={"barrens","brewmaster drohn","chen stormstout","lightning gland","ratchet","stormhide","trogg ale","степи","пивовар дрон","чэнь буйный портер","грозовая железа","кабестан","грозошкур","троггов эль"},ang={["profession:Cooking"]="Хотя грозовые железы не являются обычным кулинарным ингредиентом, они показывают пограничную философию пивоварения Чэня Буйного Портера и Пивовара Дрона: сырые органы зверей добавляются прямо в крепкий напиток."},sec={{t="Шокирующий ингредиент",b="В саваннах Степей водятся разнообразные хищники, затронутые стихиями, в том числе грозошкуры. В их плоти находится грозовая железа — орган, пульсирующий скрытой электрической энергией. Для обычной еды она вряд ли годится, но эти неустойчивые железы ценят эксцентричные пивовары, любящие напиток с настоящим жалом."},{t="Троггов эль Дрона",b="В портовом городе Кабестан Пивовар Дрон продолжает традиции пивоварения, которым его научил Чэнь Буйный Портер. Чтобы сварить крепкий напиток, известный как троггов эль, Дрону требуются пять грозовых желез, слюнная железа громового ястреба и свежая печень кодо. Получившийся напиток обладает неповторимым ударом, который искатели приключений находят и бодрящим, и крепким."}},faq={{q="У каких существ есть грозовые железы?",a="Грозовые железы добывают у грозошкуров, бродящих по обширным саваннам Степей.",al={"where to get lightning gland","who drops lightning gland","stormhide lightning gland","где взять грозовую железу","с кого падает грозовая железа","грозовая железа грозошкура"}},{q="Кому нужны грозовые железы и зачем?",a="Пивовар Дрон в Кабестане собирает их, чтобы сварить партию троггова эля — рецепт ему передал странствующий пивовар Чэнь Буйный Портер.",al={"who needs lightning gland","lightning gland turn in","lightning gland purpose","кому нужна грозовая железа","сдать грозовую железу","зачем грозовая железа"}},{q="Что еще нужно вместе с грозовой железой?",a="По рецепту Дрона требуются пять грозовых желез, слюнная железа большого громового ястреба и свежая печень кодо, добытая у зверей Степей.",al={"drohn trogg ale ingredients","chen's keg 3 items","ингредиенты троггова эля дрона","три предмета для бочонка чэня"}}},fp="15,259,21.334.0,17.360.0,38.87.0,35.140.0,50.162.0"}
P.entries["item:logging-rope"] = {n="Погрузочная веревка",s="Погрузочная веревка — тяжелый трос, жизненно важный для лесозаготовок клана Песни Войны в Ясеневом лесу. Партии этого прочного каната были перехвачены и украдены местными племенами фурболгов, яростно сопротивляющимися расширению Орды в древний лес.",h="Погрузочная веревка — тяжелый трос, жизненно важный для лесозаготовок клана Песни Войны в Ясеневом лесу.",kw={"ashenvale","foulweald","locke okarr","logging rope","splintertree post","thistlefur","warsong lumber camp","warsong supplies","ясеневый лес","гиблая чаща","локе окарр","погрузочная веревка","застава расщепленного дерева","колючий мех","лесозаготовки песни войны","припасы песни войны"},ang={["faction:Horde"]="Возвращение погрузочного каната жизненно важно, чтобы военная машина клана Песни Войны не лишилась леса, несмотря на постоянные засады.",["race:Orc"]="Поселения орков в Калимдоре целиком зависят от древесины Ясеневого леса, поэтому каждый похищенный ящик с лесозаготовительными инструментами — оскорбление, требующее возмездия."},sec={{t="Украденные канаты",b="Для обслуживания построенных гоблинами механизмов и лесопилок Лесозаготовок Песни Войны нужно огромное количество прочных погрузочных канатов. Вместо того чтобы попасть к лесорубам в лагерь, важные партии были перехвачены племенами фурболгов Гиблой Чащи и Колючего Меха. Обезумевшие от порчи и яростно защищающие свои исконные леса, эти фурболги хранят украденные веревки в своих лагерях на севере и в центре Ясеневого леса."},{t="Снабжение военных усилий",b="Локе Окарру на Заставе Расщепленного Дерева поручено вернуть утерянные припасы, пока лесозаготовки Песни Войны не встали. Забирая тяжелую веревку прямо у фурболгов-матерей и воинов, Орда получает возможность заготавливать лес, связывать бревна и обслуживать пилорамы, несмотря на постоянное партизанское сопротивление коренных обитателей леса."}},faq={{q="Для чего нужна погрузочная веревка?",a="Это толстая промышленная веревка, необходимая Лесозаготовкам Песни Войны, чтобы связывать срубленный лес, перетаскивать бревна по пересеченной местности и закреплять тяжелые механизмы в Ясеневом лесу.",al={"logging rope use","why warsong needs rope","warsong logging rope","для чего погрузочная веревка","зачем песни войны нужна веревка","погрузочная веревка песни войны"}},{q="Кто украл погрузочную веревку?",a="Партии были разграблены местными фурболгами Гиблой Чащи и Колючего Меха, которые уносят украденные канаты в свои деревни и лагеря по всему Ясеневому лесу.",al={"who took the rope","rope thief","which furbolgs have rope","кто взял веревку","вор веревки","у каких фурболгов веревка"}},{q="Кто хочет вернуть эту веревку?",a="Локе Окарр, находящийся на Заставе Расщепленного Дерева, просит вернуть веревку вместе с другими утерянными припасами, чтобы работа Лесозаготовок Песни Войны не остановилась.",al={"who needs logging rope","logging rope quest giver","кому нужна погрузочная веревка","кто выдает задание погрузочная веревка"}},{q="Почему фурболги крадут лесозаготовительные припасы?",a="Фурболги яростно противятся вырубке Ясеневого леса Ордой. Перехват обозов с припасами нарушает работу лесопилок и мстит за вторжение на их земли.",al={"furbolg motive","why furbolgs attack shipments","мотив фурболгов","почему фурболги нападают на грузы"}}},fp="12,249,12.446.0,24.366.0,30.170.0,27.161.0,25.159.0,43.174.0"}
P.entries["item:lok-s-skull"] = {n="Череп Лока",s="Череп Лока — отрубленная голова Лока Губителя Орков, свирепого воина из Иглогривых, который возглавлял жестокие набеги свинобразов на торговые пути Орды в южных Степях. Заключенный в тюрьму свинобраз Кривозуб ищет череп, желая отомстить; он служит неопровержимым доказательством того, что предводитель налетчиков пал.",h="Череп Лока — отрубленная голова Лока Губителя Орков, свирепого воина из Иглогривых, который возглавлял...",kw={"betrayal from within","camp taurajo","crossroads","lok orcbane","lok's skull","mangletooth","razormane","thork","предательство изнутри","лагерь таурахо","перекресток","лок губитель орков","череп лока","кривозуб","иглогривые","торк"},ang={["faction:Horde"]="Добыв череп Лока Губителя Орков, вы разрушите руководство южных свинобразов, постоянно нападающих на караваны снабжения между Лагерем Таурахо и Перекрестком.",["race:Orc"]="Возможность показать отсеченную голову вождя свинобразов с гордым прозвищем «Губитель Орков» приносит оркам, защищающим Степи, глубокое личное удовлетворение и безопасность."},sec={{t="Падение вождя",b="Выйдя из Лабиринтов Иглошкурых в южные Степи, Лок Губитель Орков возглавил агрессивные нападения свинобразов Иглогривых на линии снабжения Орды вместе со своими помощниками Наком и Казом. Предав Кривозуба и бросив его в плену в Лагере Таурахо, Лок заслужил мрачную славу среди орочьих защитников, которым никак не удавалось остановить его беспощадные набеги. Добыв череп Лока, вы не только отомстите за преданного пленника, направляющего героев Орды к лагерю Лока, но и сокрушите ядро руководства, стоящее за наступлением Иглогривых."},{t="Доказательство для Перекрестка",b="Хотя Кривозуб требует черепа всех трех заговорщиков ради собственной мести, череп Лока он возвращает, чтобы его отнесли на север Торку на Перекресток. Торк и командование Орды подозревали, что набегами руководит другой свинобраз, поэтому жуткий трофей стал для них полной неожиданностью и неопровержимым доказательством того, что угроза центральным торговым путям Степей окончательно устранена."}},faq={{q="Кем был Лок Губитель Орков?",a="Лок Губитель Орков был грозным воином Иглогривых, который вышел из Лабиринтов Иглошкурых и повел отряды налетчиков-свинобразов по южным Степям. Известный ненавистью к оркам и хитрой тактикой, он организовывал яростные нападения на караваны и форпосты Орды вместе со своими доверенными союзниками Наком и Казом.",al={"who is lok","lok orcbane lore","who was lok orcbane","кто такой лок","предания лока губителя орков","кем был лок губитель орков"}},{q="Почему Кривозубу нужен Череп Лока?",a="Лок Губитель Орков и его приспешники предали Кривозуба, бросив его, и таурены в Лагере Таурахо взяли его в плен и посадили в клетку. Зная, что его гибель неизбежна, Кривозуб жаждет мести сородичам, отвернувшимся от него, и направляет искателей приключений Орды убить его бывших товарищей.",al={"why mangletooth want skull","mangletooth revenge","why kill lok","зачем кривозубу череп","месть кривозуба","зачем убивать лока"}},{q="Почему череп относят Торку на Перекресток?",a="Торк руководит обороной Перекрестка и обеспечивает безопасность важных путей снабжения Орды от вторжений свинобразов. Доставка Черепа Лока доказывает орочьему командиру, что истинный организатор южных набегов убит, и возвращает покой путникам этих мест.",al={"why bring skull to thork","thork lok skull","who gets loks skull","зачем нести череп торку","торк череп лока","кому отдать череп лока"}},{q="Кто такие Нак и Каз?",a="Нак и Каз были соратниками Лока Губителя Орков, предводителями набегов в южных Степях. По словам Кривозуба, один из них заклинатель, а другой следопыт; они дополняли силу воина Лока при организации набегов на Орду.",al={"nak and kuz","lok orcbane lieutenants","kuz and nak","нак и каз","помощники лока губителя орков","каз и нак"}}},fp="11,310,18.521.0,24.408.1,20.299.0,38.295.0,52.276.0,21.222.0"}
P.entries["item:lonebrow-s-journal"] = {n="Дневник Хмурня",s="Дневник Хмурня — потрепанный дневник, найденный в скелетированных руках дворфа-исследователя Хенрига Лонбро у подножия Великого Подъемника. Его страницы описывают последний мрачный путь Лонбро через Тысячу Игл и указывают на опасности, таящиеся в Лабиринтах Иглошкурых.",h="Дневник Хмурня — потрепанный дневник, найденный в скелетированных руках дворфа-исследователя Хенрига Лонбро у...",kw={"crone of the kraul","falfindel waywarder","great lift","henrig lonebrow","razorfen kraul","thalanaar","thousand needles","хозяйка лабиринтов","хранитель дорог фалфиндел","великий подъемник","хенриг лонбро","лабиринты иглошкурых","таланаар","тысяча игл"},ang={["faction:Alliance"]="Последние записи Хенрига Лонбро создают важную связь между разведчиками Альянса и друидами, охраняющими границу с Фераласом, и собирают помощь против угрозы свинобразов.",["race:Dwarf"]="Найти павшего сородича в таких глухих и враждебных землях — мрачное напоминание об опасностях, с которыми сталкиваются дворфы-исследователи, уходя далеко за пределы Каз Модана."},sec={{t="Последняя воля у Великого Подъемника",b="Хенриг Лонбро безвременно погиб у подножия Великого Подъемника, соединяющего Степи с Тысячей Игл. Его скелет, брошенный на скалистом уступе, все еще сжимает этот потрепанный дневник. Дневник — свидетельство его последних странствий; он просит нашедшего передать весть ночному эльфу-друиду, Хранителю дорог Фалфинделу в Таланааре, пограничной заставе на пути в Фералас. Записи Лонбро проливают важный свет на угрозу свинобразов, зреющую в южных Степях."},{t="Связь с Иглошкурыми",b="Когда дневник доставлен Хранителю дорог Фалфинделу, записи Лонбро подтверждают растущую обеспокоенность Альянса свинобразами из Лабиринтов Иглошкурых. Содержание дневника напрямую приводит к призыву к героям нанести удар в сердце терновой норы и победить Чарлгу Остробок, Хозяйку Лабиринтов, стоящую за угрозой свинобразов."}},faq={{q="Кем был Хенриг Лонбро?",a="Хенриг Лонбро был дворфом-путешественником, погибшим у подножия Великого Подъемника в Тысяче Игл. Он умер, сжимая в руке дневник, содержимое которого хотел передать ночным эльфам в Таланааре.",al={"henrig lonebrow","who is lonebrow","dead dwarf lift","хенриг лонбро","кто такой лонбро","мертвый дворф у подъемника"}},{q="Где найти дневник?",a="Дневник лежит рядом со скелетом Хенрига Лонбро недалеко от спуска у подножия Великого Подъемника, на низком скалистом уступе на севере Тысячи Игл.",al={"where is lonebrow journal","find lonebrow journal","skeleton at great lift","где дневник хмурня","найти дневник хмурня","скелет у великого подъемника"}},{q="Кому нужно передать Дневник Хмурня?",a="Дневник следует отнести на запад через Тысячу Игл к Хранителю дорог Фалфинделу, ночному эльфу-друиду в Таланааре на границе Фераласа.",al={"who do i bring journal to","falfindel waywarder","where to turn in journal","кому отнести дневник","хранитель дорог фалфиндел","где сдать дневник"}},{q="К чему ведет дневник?",a="Прочтение дневника и доклад Хранителю дорог Фалфинделу раскрывают сведения о свинобразах и ведут к заданию в Лабиринтах Иглошкурых — победить Хозяйку Лабиринтов Чарлгу Остробок.",al={"crone of the kraul quest","lonebrow journal follow up","задание хозяйка лабиринтов","продолжение дневника хмурня"}}},fp="18,282,30.496.0,20.329.1,24.221.0,27.151.0,38.150.0,30.176.1"}
P.entries["item:lorgalis-manuscript"] = {n="Манускрипт Лоргалиса",s="Манускрипт Лоргалиса — древний текст, связанный с поклонением Древним богам и преданиями о них, сохранившийся из павших руин ночных эльфов под Ясеневым лесом. Он спрятан в затопленном храмовом комплексе Непроглядной Пучины и хранит тайны, которых жаждут темные ученые, стремящиеся пробудить древние спящие силы.",h="Манускрипт Лоргалиса — древний текст, связанный с поклонением Древним богам и преданиями о них, сохранившийся...",kw={"blackfathom deeps","forlorn cavern","gerrig bonegrip","ironforge","lorgalis","manuscript","old god","those who sleep","непроглядная пучина","одинокая пещера","геррик костохват","стальгорн","лоргалис","манускрипт","древний бог","те, кто спит"},ang={["class:Warlock"]="Манускрипт — редкий мост между древними эльфийскими тайными знаниями и запретными сущностями глубин, дающий сведения, которых жаждут те, кто занимается темными искусствами.",["race:NightElf"]="Текст был написан древними предками ночных эльфов до того, как их храм погрузился под воду, но одержимость спящими темными силами делает его трагической реликвией прошлого их цивилизации."},sec={{t="Том тех, кто спит",b="Восходя к великим эльфийским храмам, стоявшим до Великого Раскола, Манускрипт Лоргалиса пережил катастрофическое наводнение, затопившее руины Непроглядной Пучины. Хотя эльфы древности собирали глубокие тайны, часть их архивов описывала и более темные силы. Манускрипт содержит могущественные предания, напрямую связанные с Древними богами, — знания, которые, как говорят, открывают мистические врата и будят древних существ, спящих глубоко под миром. Он хранится в изъеденном железном сундуке среди затопленных коридоров и привлекает внимание как культистов, так и теневых ученых."},{t="Глаза во тьме",b="В Одинокой пещере Стальгорна эксцентричный коллекционер Геррик Костохват нанимает отважных искателей приключений, чтобы те отправились за море и добыли этот текст. Костохват с благоговением говорит о «последних днях» и пробуждении спящих божеств. После возвращения текст будет переписан и распространен среди его тайного круга братьев и сестер, открывая запретные знания, которые жителям поверхности не суждено постичь."}},faq={{q="Что такое Манускрипт Лоргалиса?",a="Это древний эльфийский текст с темными, тайными знаниями о Древних богах. Говорят, что его содержание хранит секреты, необходимые для открытия врат и пробуждения спящих изначальных существ.",al={"what is lorgalis manuscript","lorgalis book lore","what does the manuscript do","что такое манускрипт лоргалиса","книга лоргалиса предания","что делает манускрипт"}},{q="Где находится манускрипт?",a="Манускрипт лежит в изъеденном железном сундуке глубоко в затопленной части Непроглядной Пучины — разрушенного храма ночных эльфов на Зорамском взморье в Ясеневом лесу.",al={"where to find lorgalis manuscript","manuscript location","blackfathom chest","где найти манускрипт лоргалиса","местонахождение манускрипта","сундук непроглядной пучины"}},{q="Кому нужен манускрипт?",a="Геррик Костохват, загадочный хранитель знаний из Одинокой пещеры в Стальгорне, поручает искателям приключений добыть его. Он планирует скопировать древние учения и распространить их среди своих тайных единомышленников.",al={"who wants lorgalis manuscript","gerrig bonegrip quest","who is bonegrip","кому нужен манускрипт лоргалиса","задание геррик костохват","кто такой костохват"}},{q="Почему Геррик Костохват говорит о последних днях?",a="Костохват примыкает к тем, кто изучает и почитает Древних богов. Его интерес к древним эльфийским письменам направлен на знания, способные пробудить «Тех, кто спит», возвещая то, что он считает грядущим концом времен.",al={"gerrig end days","bonegrip cultist","bonegrip old gods","геррик последние дни","костохват культист","костохват древние боги"}}},fp="19,301,25.577.0,19.443.1,32.201.0,32.161.0,25.210.0,49.217.0"}
P.entries["item:lunar-fungus"] = {n="Лунный гриб",s="Лунный гриб — сильнодействующий лечебный гриб, который собирают в грибных зарослях глубоко в пещерах Темных берегов. Начинающие друиды собирают эти грибы вместе с обычными травами, чтобы приготовить целебную мазь для лечения больных животных.",h="Лунный гриб — сильнодействующий лечебный гриб, который собирают в грибных зарослях глубоко в пещерах Темных...",kw={"alanndarian nightsong","auberdine","cure poison","darkshore","earthroot","lunar fungal bloom","lunar fungus","аландариан песня ночи","аубердин","лечение яда","темные берега","землекорень","лунные грибные заросли","лунный гриб"},ang={["class:Druid"]="Молодые друиды ищут лунный гриб в пещерах Темных берегов в рамках начальных обрядов, чтобы овладеть целебной магией и лечить отравленных животных.",["race:NightElf"]="Лечить пораженных порчей лесных тварей вокруг Аубердина местными средствами вроде лунного гриба — постоянный долг стражей Темных берегов."},sec={{t="Свойства и среда обитания",b="Этот необычный гриб, который собирают в лунных грибных зарослях, растет в темных подземных пещерах по всему побережью Темных берегов. Круг Кенария ценит его за усиливающее действие: если смешать гриб с успокаивающей водной основой и обычным землекорнем, он придает составу силу, нужную для создания действенного противоядия от изнурительных недугов. Поскольку он растет главным образом в сырых подземельях, где обитают свирепые лунные совуха, добыть его можно, только осторожно пробираясь по дикой глуши."},{t="Урок исцеления",b="В Аубердине Аландариан Песня Ночи направляет молодых друидов собирать лунный гриб в рамках изучения целительных искусств природы. Наблюдая, как вещественные реагенты вроде этого гриба нейтрализуют сильные яды у местных оленей, новички постигают основы травничества, а затем учатся направлять природные противоядия напрямую — через превращения и силу духа."}},faq={{q="Для чего нужен лунный гриб?",a="Лунный гриб придает целебную силу при приготовлении восстанавливающей мази. Аландариан Песня Ночи смешивает его с землекорнем и чистой водой, чтобы лечить больных оленей в глуши Темных берегов.",al={"lunar fungus purpose","what does lunar fungus do","why collect lunar fungus","для чего лунный гриб","что делает лунный гриб","зачем собирать лунный гриб"}},{q="Где растет лунный гриб?",a="Он вырастает из лунных грибных зарослей в пещерах к востоку от Аубердина на Темных берегах. В этих темных пещерах обитают раздражительные лунные совуха, которые защищают свою территорию от чужаков.",al={"lunar fungus location","where to find lunar fungus","lunar fungus blooms","где растет лунный гриб","где найти лунный гриб","лунные грибные заросли"}},{q="Кому в Аубердине нужен этот гриб?",a="Друид Аландариан Песня Ночи просит лунный гриб у учеников природы в рамках обучения и использует его целебные свойства, чтобы готовить лекарства для больных лесных животных.",al={"who needs lunar fungus","auberdine herbal quest","кому нужен лунный гриб","задание аубердин травы"}},{q="Почему начинающие друиды должны собирать травы, чтобы лечить яд?",a="Понимание вещественных противоядий — основа друидического обучения. Собирая дикие реагенты вроде лунного гриба и наблюдая, как определенные ингредиенты нейтрализуют определенные яды, ученики постигают принципы исцеления, прежде чем научатся изгонять яды напрямую с помощью духовной магии.",al={"why druids gather herbs","druid poison cure training","зачем друиды собирают травы","обучение друидов лечение яда"}}},fp="12,240,22.504.0,19.400.0,30.197.0,29.189.0,38.198.0,68.296.0"}
P.entries["item:lurker-venom"] = {n="Паучий яд",s="Паучий яд — сильнодействующий природный токсин, который добывают у хищных пауков, обитающих в скалистых холмах и лесах Лок Модана. Дворфы-защитники используют этот едкий яд как главный ингредиент алхимического состава, нейтрализующего диверсии клана Черного Железа.",h="Паучий яд — сильнодействующий природный токсин, который добывают у хищных пауков, обитающих в скалистых...",kw={"chief engineer hinderweir","cliff lurker","loch modan","lurker venom","shanda the spinner","spider venom","stonewrought dam","wood lurker","главный инженер киндервейр","скальный охотник","лок модан","паучий яд","шанда пряха","яд пауков","каменная плотина","древесный охотник"},ang={["profession:Engineering"]="Использование органических токсинов для обезвреживания вражеских боеприпасов показывает импровизированное, реактивное направление дворфийской инженерии в боевых условиях.",["race:Dwarf"]="Горцы и защитники Лок Модана привычно используют местные природные опасности, чтобы защитить важные объекты Каз Модана от клана Черного Железа."},sec={{t="Нестабильный реагент",b="Холмы и скалы вокруг Лок Модана кишат хищными паукообразными — от обычных лесных охотников до печально известной матери выводка Шанды Пряхи. Их укусы постоянно угрожают горцам и путникам, но эксперт по взрывчатке Ашлан Камнехмыл назвал их ядовитую отраву одним из ингредиентов обезвреживающей смеси, которую готовит главный инженер Киндервейр. В сочетании с редкими минералами и слезами кроколисков озера паучий яд образует реактивный растворитель, способный обезвреживать сложные взрывные устройства клана Черного Железа."}},faq={{q="Откуда берется паучий яд?",a="Его добывают у разных пауков-охотников Лок Модана, включая скальных, лесных и древесных охотников, а также их матку — Шанду Пряху.",al={"how to get lurker venom","who drops lurker venom","where find lurker venom","как получить паучий яд","с кого падает паучий яд","где найти паучий яд"}},{q="Для чего нужен паучий яд?",a="Главный инженер Киндервейр использует яд как часть особой химической смеси, чтобы нейтрализовать и обезвреживать взрывные устройства, подложенные лазутчиками клана Черного Железа у Каменной Плотины.",al={"why do i need lurker venom","lurker venom purpose","what does hinderweir do with venom","зачем нужен паучий яд","для чего паучий яд","что киндервейр делает с ядом"}},{q="Почему яд используют, чтобы обезвредить взрывчатку?",a="Дворфы-инженеры часто применяют реактивные, кислотные или едкие смеси, чтобы растворять хрупкие механизмы или нейтрализовать нестабильный взрывной порошок, не вызывая взрыва.",al={"why spider poison for bombs","how does venom stop dark iron bombs","зачем паучий яд для бомб","как яд останавливает бомбы черного железа"}},{q="Шанда Пряха — единственный источник?",a="Нет. Хотя Шанда несет яд, его можно получить у любого обычного дикого паука-охотника, обитающего в лесах и на скалах Лок Модана.",al={"do i have to kill shanda","shanda lurker venom","нужно ли убивать шанду","шанда паучий яд"}}},fp="12,267,18.543.0,34.170.0,30.189.0,37.177.0,38.143.0"}
P.entries["item:lydon-s-toxin"] = {n="Отрава Лидона",s="Отрава Лидона — алхимическое средство, которое создал аптекарь Лидон в Мельнице Таррен, чтобы сорвать вырубку лесов Торговой Компанией в Когтистых горах. Ее доверяют авантюристам Орды, чтобы они доставили ее аптекарю Заме в Громовой Утес, и та разработала действенный способ распыления.",h="Отрава Лидона — алхимическое средство, которое создал аптекарь Лидон в Мельнице Таррен, чтобы сорвать вырубку...",kw={"apothecary lydon","apothecary zamah","lydon's toxin","royal apothecary society","thunder bluff","toxic fogger","venture company","аптекарь лидон","аптекарь зама","отрава лидона","королевское фармацевтическое общество","громовой утес","распылитель ядовитого тумана","торговая компания"},ang={["race:Tauren"]="Хотя таурены рады помощи против разрушения природы Торговой Компанией, химические методы Королевского фармацевтического общества испытывают границы их шаманских воззрений.",["race:Undead"]="Доставка Отравы Лидона показывает широкую сеть Королевского фармацевтического общества, координирующего полевые исследования между Лордероном и Калимдором, чтобы показать союзникам полезность Отрекшихся."},sec={{t="Решение Королевского фармацевтического общества",b="Это ядовитое вещество, созданное аптекарем Лидоном в Предгорьях Хилсбрада, предназначено для борьбы с вторгшимися лесорубами Торговой Компании, разоряющими Когтистые горы. По словам Лидона, при контакте состав дает смертельный и потенциально заразный эффект. Однако прежде чем применять его против гоблинских предприятий у Утеса Ветрорезов, его нужно переправить через континенты к аптекарю Заме, представительнице Королевского фармацевтического общества в Громовом Утесе. Заме нужна сырая смесь, чтобы создать прибор широкого распыления — Распылитель ядовитого тумана, — чтобы зелье уничтожило хищных лесорубов, не подвергая ненужной опасности имущество Орды."}},faq={{q="Для чего нужна Отрава Лидона?",a="Аптекарь Лидон создал яд, чтобы разорвать хватку Торговой Компании в районе Утеса Ветрорезов. Он рассчитан на разрушительное и потенциально заразное действие против гоблинов-разрушителей.",al={"lydon toxin purpose","what does the toxin do","why make lydon's toxin","назначение отравы лидона","что делает отрава","зачем делать отраву лидона"}},{q="Кто такой аптекарь Лидон?",a="Аптекарь Лидон — член Королевского фармацевтического общества, находящийся в Мельнице Таррен в Предгорьях Хилсбрада. Он специализируется на создании ядовитых отваров и опытных составов для достижения целей Отрекшихся.",al={"who is lydon","apothecary lydon","lydon creator","кто такой лидон","аптекарь лидон","создатель отравы"}},{q="Почему отраву нужно доставить в Громовой Утес?",a="Лидон довел состав до совершенства, но у него нет практического способа массового применения. Аптекарь Зама живет на Вершине Духов в Громовом Утесе, изучает местную флору и координирует усилия Общества в Калимдоре; она берет отраву, чтобы превратить ее в портативную систему распыления тумана.",al={"why thunder bluff","why bring toxin to zamah","apothecary zamah purpose","почему громовой утес","зачем нести отраву заме","назначение аптекаря замы"}},{q="Что происходит после того, как Зама получает отраву?",a="Получив флакон, аптекарь Зама превращает вещество в аппарат с аэрозолем под давлением — Распылитель ядовитого тумана, — позволяющий агенту распылить его в самом центре лагеря Торговой Компании.",al={"toxic fogger creation","what does zamah do with the toxin","создание распылителя ядовитого тумана","что зама делает с отравой"}}},fp="13,300,27.697.0,31.212.0,24.227.0,47.293.0,44.213.0"}
P.entries["item:macgrann-s-dried-meats"] = {n="Вяленое мясо МакГранна",s="Вяленое мясо МакГранна — месячный запас соленых припасов, которые приготовил охотник Тундра Макгранн, чтобы пережить суровую зиму в Дун Мороге. Весь запас хранился в усиленном ториевом мясном шкафу, и его унес свирепый йети по прозвищу Старый Ледобород.",h="Вяленое мясо МакГранна — месячный запас соленых припасов, которые приготовил охотник Тундра Макгранн, чтобы...",kw={"chill breeze valley","dun morogh","macgrann's dried meats","meat locker","old icebeard","tundra macgrann","долина промозглого ветра","дун морог","вяленое мясо макгранна","мясной шкаф","старый ледобород","тундра макгранн"},ang={["profession:Cooking"]="Соление и вяление дичи — важнейший кулинарный способ выживания в Дун Мороге, позволяющий охотникам вроде Макгранна хранить мясо месяцами, не боясь порчи на морозе.",["race:Dwarf"]="Дворфы-горцы прекрасно знают, что подготовка означает выживание на высоких вершинах, а потерянный зимний запас может решить вопрос жизни и смерти."},sec={{t="Зимний запас",b="Жизнь в промерзших скалах Дун Морога требует тщательного планирования. Готовясь к метелям холодного сезона, охотник-дворф Тундра Макгранн неделями охотился на дичь, солил мясо и убирал его в прочный сундук. Зная, что медведи-падальщики и хищники постоянно донимают его усадьбу, Макгранн не стал рисковать и запер запасы в ториевом мясном шкафу. Но даже при этих мерах он не ждал, что взломщик окажется настолько силен, что унесет весь сундук целиком, а не станет вскрывать его на месте."},{t="В логово йети",b="Пока Макгранн выслеживал оленей, известный йети Старый Ледобород разорил лагерь охотника и утащил тяжелый сундук в свою берлогу в Долине Промозглого Ветра. Хотя зверь не мог пробить прочную ториевую обшивку, из-за раненой ноги Макгранн не мог быстро проникнуть в пещеру. Без посторонней помощи, чтобы вернуть запас до начала зимы, охотнику грозил голод среди горных снегов."}},faq={{q="Что такое Вяленое мясо МакГранна?",a="Это месячный запас соленых припасов, которые Тундра Макгранн заготовил, чтобы пережить суровую зиму в Дун Мороге.",al={"what is macgrann's dried meats","tundra's meat","macgrann meat stash","что такое вяленое мясо макгранна","мясо тундры","запас мяса макгранна"}},{q="Почему мясо заперли в сундуке?",a="Дун Морог кишит голодными хищниками вроде горных медведей. Макгранн хранил вяленое мясо в усиленном ториевом мясном шкафу, чтобы звери-падальщики не добрались до его зимнего запаса.",al={"why lock the meat","why thorium locker","macgrann chest","зачем запирать мясо","зачем ториевый шкаф","сундук макгранна"}},{q="Кто украл мясной шкаф?",a="Грозный йети по имени Старый Ледобород унес весь шкаф, пока Макгранн охотился на оленей, и утащил тяжелый ящик в свою пещерную берлогу в Долине Промозглого Ветра.",al={"who took the meat","who stole it","meat locker thief","кто взял мясо","кто украл","вор мясного шкафа"}},{q="Почему Тундра Макгранн не может сам вернуть свое мясо?",a="У Макгранна раненая нога, и ему не хватает скорости и скрытности, чтобы пробраться в берлогу Старого Ледобороды и выбраться до того, как свирепый йети его настигнет.",al={"why doesn't macgrann get it","why does tundra need help","tundra injured","почему макгранн не вернет сам","зачем тундре помощь","тундра ранен"}}},fp="22,261,14.556.0,20.457.0,32.126.0,37.208.0,26.173.0,53.164.0"}
P.entries["item:mackreel-s-moonshine"] = {n="Самогон Маккрила",s="Самогон Маккрила — крепкий дворфийский напиток, который варит Туманник Маккрил, дежурящий на разрушенном Мосту Тандола к северу от Болотины. Он настолько крепок, что способен свалить часового на посту, и его ценят вплоть до Южнобережья, где Мастер-пивовар Бочкопуз принимает его в уплату долгов.",h="Самогон Маккрила — крепкий дворфийский напиток, который варит Туманник Маккрил, дежурящий на разрушенном...",kw={"brewmeister bilger","dwarf brew","foggy mackreel","mackreel's moonshine","moonshine","southshore","wetlands","мастер-пивовар бочкопуз","дворфийское пиво","туманник маккрил","самогон маккрила","самогон","южнобережье","болотина"},ang={["profession:Cooking"]="Хотя самогон Туманника перегнан как грубый напиток, а не как тонкое кулинарное вино, такие крепкие местные напитки — обычный торговый товар в приграничных тавернах.",["race:Dwarf"]="Дворфы знают хорошую крепкую выпивку по запаху, и самогон Туманника явно достаточно силен, чтобы свалить горца с ног."},sec={{t="Крепкое зелье",b="Этот самогон, который варит стражник Туманник Маккрил на Мосту Тандола, известен своей убойной крепостью. Даже закаленные дворфы-часовые сваливаются после ночи с этим напитком и просыпаются с головной болью, будто над ними прокатилась бригада осадных машин. Несмотря на жестокий удар, он высоко ценится у путников, которым надо согреться в сырую стужу Лордерона и Каз Модана."},{t="Плата для Южнобережья",b="Туманник Маккрил задолжал Мастеру-пивовару Бочкопузу, трактирщику и главному пивовару Южнобережья. Чтобы погасить счет, Туманник расплатился партией самогона вместо монет. Бочкопуз охотно принимает выпивку вместо золота и рад пополнить запасы крепким напитком Маккрила на холодные прибрежные дни Предгорий Хилсбрада."}},faq={{q="Кто делает Самогон Маккрила?",a="Его гонит Туманник Маккрил, дворф-часовой, дежурящий на разрушенном участке Моста Тандола между Болотиной и Нагорьем Арати.",al={"creator of mackreels moonshine","who brewed it","foggy mackreel liquor","создатель самогона маккрила","кто сварил","самогон туманника маккрила"}},{q="Почему этот самогон отправляют в Южнобережье?",a="Туманник Маккрил задолжал Мастеру-пивовару Бочкопузу в Южнобережье. Вместо монет он согласился погасить просроченный долг, отправив Бочкопузу свежую партию своего самогона.",al={"why southshore","moonshine delivery","brewmeister bilger debt","почему южнобережье","доставка самогона","долг бочкопузу"}},{q="Насколько крепок Самогон Маккрила?",a="Он исключительно крепок. Туманник признался, что отключился на посту после того, как выпил его, и потом жаловался на головную боль, будто по его черепу грохотала целая бригада осадных машин.",al={"how potent is it","moonshine strength","effects of mackreels moonshine","насколько крепок","крепость самогона","действие самогона маккрила"}},{q="Почему с доставкой нужно спешить?",a="Туманник много выпил и проспал свою вахту, поняв, проснувшись, что до истечения срока долга перед Мастером-пивоваром Бочкопузом остались считаные минуты.",al={"why timed","is the quest timed","why hurry","почему на время","задание на время","зачем спешить"}}},fp="20,277,13.397.0,21.353.0,31.148.0,47.170.0,35.207.0,40.163.0"}
P.entries["item:maggot-eye-s-paw"] = {n="Лапа Червеглаза",s="Лапа Червеглаза — жуткий трофей, снятый с вождя гноллов Червеглаза на Ферме Гаррена. Доставленная в Брилл, она служит вещественным доказательством казни зверя за разграбление могил в интересах Плети.",h="Лапа Червеглаза — жуткий трофей, снятый с вождя гноллов Червеглаза на Ферме Гаррена.",kw={"bounty","brill","executor zygand","garren's haunt","gnoll","maggot eye","maggot eye's paw","tirisfal glades","награда","брилл","палач зуганд","ферма гаррена","гнолл","червеглаз","лапа червеглаза","тирисфальские леса"},ang={["race:Undead"]="Для Отрекшихся Брилла возвращение лапы Червеглаза — прямой удар по похитителям тел, снабжающим ненавистного Короля-лича сырьем."},sec={{t="Доказательство казни",b="Червеглаз навлек на себя суровый гнев Отрекшихся, грабя могилы и разоряя окрестности Фермы Гаррена и поставляя трупы для пополнения армий Короля-лича. В ответ в Брилле были выставлены официальный смертный приговор и награда за голову. Одних слухов о смерти никогда не хватает таким военным администраторам, как Палач Зуганд, поэтому охотники за головами должны отсечь лапу злодея и принести ее в город, чтобы получить награду и закрыть заказ."}},faq={{q="Зачем Палачу Зуганду лапа Червеглаза?",a="Палач Зуганд требует неопровержимых доказательств того, что приговоренный гнолл действительно уничтожен. Отсеченная лапа служит вещественным подтверждением казни, после чего Брилл выплатит награду.",al={"why paw","maggot eye bounty proof","zygand paw","зачем лапа","доказательство награды за червеглаза","лапа зуганд"}},{q="Какие преступления Червеглаз совершил против Отрекшихся?",a="Червеглаз возглавлял грабительские набеги на север Тирисфальских лесов и крал погребенные трупы с ферм, подобных Ферме Гаррена, чтобы снабжать армии Короля-лича.",al={"maggot eye crimes","why is maggot eye wanted","what did maggot eye do","преступления червеглаза","почему червеглаз в розыске","что сделал червеглаз"}},{q="Где найти Червеглаза?",a="Червеглаз обитает на Ферме Гаррена — разоренной ферме к северо-востоку от Брилла в Тирисфальских лесах, обычно скрываясь в обветшалом фермерском доме.",al={"maggot eye location","where to find maggot eye","garrens haunt gnoll","где червеглаз","как найти червеглаза","гнолл ферма гаррена"}},{q="Почему гноллы действуют заодно с силами Короля-лича?",a="Хотя гноллы по природе оппортунистические падальщики, отбившиеся шайки в Тирисфальских лесах объединились с Плетью или попали под ее влияние и грабят могилы людей и Отрекшихся, поставляя тела некромантам.",al={"gnolls and scourge","why do gnolls steal bodies","scourge gnolls","гноллы и плеть","зачем гноллы крадут тела","гноллы плети"}}},fp="16,220,18.480.0,47.191.0,55.190.0,26.153.0,51.210.0"}
P.entries["item:maggran-s-reserve-letter"] = {n="Письмо Магграна о вызове подкрепления",s="Письмо Магграна о вызове подкрепления — официальное донесение, написанное Землепрядом Магграном в Приюте у Солнечного Камня. Доставленное через Калимдор к Великому Подъемнику, оно дарует несущему службу часовому долгожданную смену, чтобы он мог вернуться домой и навестить семью.",h="Письмо Магграна о вызове подкрепления — официальное донесение, написанное Землепрядом Магграном в Приюте у...",kw={"barrens","earthbinder","grish","letter","lift","longrunner","maggran","reserve","stonetalon","степи","землепряд","гриш","письмо","подъемник","выносливый гонец","маггран","подкрепление","когтистые горы"},ang={["faction:Horde"]="Послание показывает заботу Орды после войны о рассеянных силах: на отдаленные заставы Калимдора по очереди направляются свежие резервы."},sec={{t="Смена для часового",b="Охрана застав на суровых просторах Калимдора требует бдительности, но вожди Орды понимают, что долгая служба на посту сильно подрывает боевой дух. Это простое послание, написанное Землепрядом Магграном в высоких скалах Приюта у Солнечного Камня, служит официальным приказом, уведомляющим Гриша Выносливого Гонца, что на смену ему отправлен другой воин, который займет его пост у Великого Подъемника. Одинокому стражу, наблюдающему за высокими деревянными воротами далеко на юге, письмо сулит то, что редко бывает в тревожные времена: почетный отпуск, чтобы воссоединиться с семьей."}},faq={{q="Для чего нужно Письмо Магграна о вызове подкрепления?",a="В письме содержится официальный приказ Землепряда Магграна, освобождающий часового Гриша Выносливого Гонца от службы у Великого Подъемника в южных Степях, чтобы он мог вернуться домой и навестить семью.",al={"what does this letter do","maggran letter purpose","why deliver letter","для чего это письмо","назначение письма магграна","зачем доставлять письмо"}},{q="Кто написал письмо?",a="Письмо написал Землепряд Маггран, старейшина, живущий в Приюте у Солнечного Камня в Когтистых горах.",al={"who wrote it","author of reserve letter","maggran earthbinder","кто написал","автор письма","землепряд маггран"}},{q="Кому оно адресовано?",a="Оно адресовано Гришу Выносливому Гонцу, стражнику Орды на вершине Великого Подъемника, соединяющего южные Степи с Тысячей Игл.",al={"who gets the letter","letter recipient","where does it go","кто получает письмо","адресат письма","куда нести"}},{q="Куда нужно доставить письмо?",a="Его нужно отнести на юг через Степи к краю каньона Тысяча Игл, где стоит Великий Подъемник.",al={"delivery location","where is grish","great lift location","место доставки","где гриш","где великий подъемник"}}},fp="24,235,17.589.0,48.205.0,21.113.0,27.142.0,30.116.0"}
P.entries["item:mangy-claw"] = {n="Грязный коготь",s="Грязный коготь — отсеченный коготь, снятый с огромного ледяного медведя Шелудивого Когтя в Дун Мороге. Он служит мрачным доказательством того, что смертоносный зверь, убивший застрявшего дворфийского пилота, наконец повержен.",h="Грязный коготь — отсеченный коготь, снятый с огромного ледяного медведя Шелудивого Когтя в Дун Мороге.",kw={"dun morogh","hildelve","ice claw bear","mangeclaw","mangy claw","pilot hammerfoot","siege brigade","дун морог","хильдельв","ледяной медведь","шелудивый коготь","грязный коготь","пилот большеног","осадная бригада"},ang={["class:Hunter"]="Выслеживание известного хищника вроде Шелудивого Когтя в жестоких горных метелях проверяет умение охотника справляться с опасными, территориальными зверями.",["race:Dwarf"]="Для дворфов исполнить предсмертную волю павшего товарища и отомстить за бойца Осадной бригады Стальгорна — вопрос глубокой личной и клановой чести."},sec={{t="Предсмертная воля пилота",b="Когда паровой танк пилота Хильдельва сломался в заснеженных холмах Дун Морога, он продолжил поиски руды пешком и остался один на один с горной глушью. Как записано в найденном дневнике, Хильдельв отбился от первого нападения чудовищного ледяного медведя по имени Шелудивый Коготь, но был жестоко изранен. Позже зверь вернулся, чтобы прикончить ослабевшего пилота. Последняя запись Хильдельва содержала мольбу о мести хищнику — ее исполняют, забрав Грязный коготь с убитого медведя."},{t="Месть за Осадную бригаду",b="Принеся Грязный коготь Пилоту Большеногу, вы приносите покой Осадной бригаде Стальгорна. Большеног отправил поисковиков в снежные заносы в надежде найти друга живым, но узнал о его печальной участи. Дневник Хильдельва и отсеченный коготь хищника доказывают, что предсмертная просьба Хильдельва исполнена, а это дарует ему покой и обеспечивает благодарность пилотов Стальгорна."}},faq={{q="Что такое Грязный коготь?",a="Это трофей, отсеченный от Шелудивого Когтя, свирепого ледяного медведя, обитающего в Дун Мороге. Он служит вещественным доказательством того, что зверя выследили и убили.",al={"mangy claw purpose","what is this claw","mangeclaw item","назначение грязного когтя","что за коготь","предмет шелудивого когтя"}},{q="Кому нужен Грязный коготь?",a="Пилот Большеног, стоящий у горных перевалов Дун Морога, ищет коготь вместе с дневником своего погибшего друга Хильдельва, чтобы убедиться, что медведь-убийца мертв.",al={"who takes the mangy claw","mangy claw hand in","pilot hammerfoot turn in","кто принимает грязный коготь","сдать грязный коготь","пилот большеног сдать"}},{q="Почему на Шелудивого Когтя пришлось охотиться?",a="Дворфийский пилот Хильдельв, искавший руду пешком после поломки парового танка, был изранен и в итоге убит Шелудивым Когтем. Предсмертная воля Хильдельва, записанная в его личном дневнике, — чтобы кто-нибудь отомстил зверю.",al={"why kill mangeclaw","who died to mangeclaw","hildelve lore","зачем убивать шелудивого когтя","кто погиб от шелудивого когтя","предания хильдельв"}},{q="Где бродит зверь Шелудивый Коготь?",a="Шелудивый Коготь рыщет по заснеженным хребтам и холмам Дун Морога неподалеку от места, где нашли останки пилота Хильдельва.",al={"mangeclaw location","where is mangeclaw","mangeclaw dun morogh","где шелудивый коготь","местонахождение шелудивого когтя","шелудивый коготь дун морог"}}},fp="10,211,20.540.0,31.399.1,23.160.0,25.170.0,36.239.0,36.118.0"}
P.entries["item:marshal-haggard-s-badge"] = {n="Знак маршала Хаггарда",s="Знак маршала Хаггарда — символ звания и власти, который носил маршал Хаггард на службе королевству Штормград. Украденный хитростью бандитом из Братства Справедливости Джеком Мертвозубом, знак представляет опасность как средство для выдачи себя за городских чиновников.",h="Знак маршала Хаггарда — символ звания и власти, который носил маршал Хаггард на службе королевству Штормград.",kw={"dead-tooth jack","defias","elwynn forest","marshal dughan","marshal haggard","marshal haggard's badge","stormwind","strongbox","джек мертвозуб","братство справедливости","элвиннский лес","маршал дугхан","маршал хаггард","знак маршала хаггарда","штормград","сундук"},ang={["class:Warrior"]="Возвращение знака Хаггарда доказывает вашу доблесть ветерану штормградской армии, который награждает многообещающих воинов хорошо сохранившимся лишним оружием со времен своих сражений.",["faction:Alliance"]="Возвращение знака сохраняет целостность военного командования Штормграда и мешает Братству Справедливости подрывать местную оборону изнутри."},sec={{t="Украденный знак отличия",b="Хотя маршал Хаггард давно удалился на свою небольшую ферму в холмах Элвиннского леса, его старый знак маршала Штормграда по-прежнему имеет вес. Под покровом ночи разбойник из Братства Справедливости Джек Мертвозуб надел штормградский табард и выдал себя за маршала Дугхана, командира гарнизона Златоземья. Поверив, что бывшим соратникам знак нужен по службе, пожилой Хаггард без подозрений отдал его. Джек скрылся в лесу прежде, чем отставной офицер понял обман. В руках Братства Справедливости такой символ власти Штормграда позволил бы преступникам проходить мимо застав или сеять смятение среди местных патрулей."}},faq={{q="Что такое Знак маршала Хаггарда?",a="Это официальный знак отличия маршала Хаггарда со времен его службы королевству Штормград. Даже в отставке такой знак говорит о прежнем военном положении и дает настоящую власть.",al={"haggard badge","marshal badge","haggards badge","знак хаггарда","знак маршала","значок хаггарда"}},{q="Как Джек Мертвозуб получил знак?",a="Джек Мертвозуб подошел к дому маршала Хаггарда под покровом темноты в штормградском табарде. В тусклом свете Хаггард принял его за маршала Дугхана из Златоземья и по просьбе отдал знак.",al={"how was badge stolen","who stole the badge","dead-tooth jack trick","как украли знак","кто украл знак","уловка джека мертвозуба"}},{q="Чем знак опасен в руках Братства Справедливости?",a="Имея настоящий знак маршала и маскировочную форму, агент Братства Справедливости мог бы выдавать себя за высокопоставленных штормградских чиновников, чтобы обходить часовых, проникать в гарнизоны или отдавать ложные приказы городской страже.",al={"why does jack want the badge","defias badge use","badge danger","зачем джеку знак","применение знака братством справедливости","опасность знака"}},{q="Где хранится знак?",a="Джек Мертвозуб запер украденный знак в своем сундуке, спрятанном в лагере к югу от фермы маршала Хаггарда в Элвиннском лесу.",al={"badge location","where to find badge","dead tooth strongbox","местонахождение знака","где найти знак","сундук мертвозуба"}}},fp="23,290,17.675.0,32.203.0,38.208.0,54.201.0,24.147.0"}
P.entries["item:mary-s-looking-glass"] = {n="Зеркальце Мэри",s="Зеркальце Мэри — брошенное ручное зеркало, некогда дорогое Слепой Мэри, пока трагедия не отняла у нее зрение и жизнь. Оно было оставлено в зловещих рощах Сумеречного леса, его подобрал бродячий вурдалак, а затем его отыскали, чтобы завершить телескоп Виктора Призм’Антраса.",h="Зеркальце Мэри — брошенное ручное зеркало, некогда дорогое Слепой Мэри, пока трагедия не отняла у нее зрение...",kw={"blind mary","darkshire","duskwood","insane ghoul","look to the stars","looking glass","mary's looking glass","tranquil gardens cemetery","viktori prism'core","слепая мэри","темнолесье","сумеречный лес","безумный вурдалак","взгляд на звезды","зеркальце","зеркальце мэри","безмятежное кладбище","виктор призм’антрас"},ang={["faction:Alliance"]="Возвращение реликвий от ужасов, бродящих по Безмятежному кладбищу, приносит жителям многострадального Темнолесья отраду и помогает городским начинаниям.",["profession:Engineering"]="Инженеры оценят изобретательность Виктора, превратившего старинное домашнее зеркало в действующий оптический отражатель для астрономического прибора."},sec={{t="Сокровище Отрекшейся",b="Before her terrible fate, Blind Mary treasured this polished looking glass. After her death and the loss of her eyes, looking upon her reflection became an agonizing reminder of what she had lost. She cast the mirror away behind her barn, leaving it to the encroaching gloom of Duskwood. There it fell into the clutching claws of an Insane Ghoul that wandered the ruined outskirts, carrying the trinket south into the crypts of Tranquil Gardens Cemetery."},{t="Взор к небесам",b="В Темнолесье чудаковатый звездочет Виктор Призм’Антрас мечтал заглянуть сквозь вечные сумерки Сумеречного леса в чистые небеса. Для постройки телескопа нужны были особые оптические линзы и отражающее стекло. Узнав о его нужде, Мэри направила искателей приключений выследить одичавшую нежить, бродящую у разрушенной часовни кладбища, и вернуть зеркальце, чтобы оно стало отражателем в его великом звездном приборе."}},faq={{q="Почему Мэри выбросила зеркальце?",a="The looking glass was once one of Mary's finest treasures, but she discarded it behind the barn after an incident she does not fully describe. In another encounter she explains that she tore out her own eyes, unable to bear her appearance.",al={"why mary threw it away","why discard mirror","blind mary mirror lore","почему мэри выбросила зеркальце","зачем выбросила зеркало","предания слепая мэри зеркало"}},{q="Кому досталось зеркальце после того, как Мэри его выбросила?",a="Выброшенное зеркальце подобрал безумный вурдалак, бродивший по лесу за старой фермой Мэри. Безумная нежить в итоге поселилась в заброшенной часовне Безмятежного кладбища.",al={"who has the mirror","who dropped looking glass","where is looking glass","у кого зеркальце","кто уронил зеркальце","где зеркальце"}},{q="Зачем Виктору Призм’Антрасу зеркальце Мэри?",a="Виктор строит сложный телескоп, чтобы пронзить мрак Сумеречного леса и изучать звезды. Ему нужна хорошая отражающая поверхность, чтобы направлять свет через прибор, и сохранившееся стекло Мэри идеально подходит для его замысла.",al={"why does viktori need mirror","viktori looking glass use","telescope mirror","зачем виктору зеркало","применение зеркальца виктором","зеркало для телескопа"}},{q="Где найти безумного вурдалака с зеркальцем?",a="Безумный вурдалак скрывается в дальнем юго-восточном углу Сумеречного леса и обычно бродит у разрушенной каменной часовни на Безмятежном кладбище.",al={"insane ghoul location","where is insane ghoul","tranquil gardens ghoul","где безумный вурдалак","местонахождение безумного вурдалака","вурдалак безмятежного кладбища"}}},fp="20,269,19.454.0,19.443.0,42.239.0,53.200.0,56.227.0,55.147.0"}
P.entries["item:mathystra-relic"] = {n="Реликвия Матистры",s="Реликвии Матистры — древние артефакты ночных эльфов, разбросанные среди заросших руин Матистры на севере Темных берегов. Хотя это остатки павшего эльфийского оплота, в них сохранились дремлющие осколки магии, привлекшие внимание культа Сумеречного Молота.",h="Реликвии Матистры — древние артефакты ночных эльфов, разбросанные среди заросших руин Матистры на севере...",kw={"darkshore","grove of the ancients","master's glaive","mathystra","mathystra relic","onu","ruins of mathystra","twilight's hammer","темные берега","роща древних","меч властителя","матистра","реликвия матистры","ону","руины матистры","сумеречный молот"},ang={["class:Druid"]="Друиды, тесно работая с древними вроде Ону, помогают охранять хрупкое равновесие Темных берегов и следят, чтобы забытые магические остатки не питали темные призывы.",["race:NightElf"]="Для кальдораев возвращение этих реликвий — это и защита опасной древней магии от Сумеречного Молота, и дань наследию города, утраченного в Расколе."},sec={{t="Остатки павшего оплота",b="До Великого Раскола Матистра была гордым городом и оплотом эльфийской цивилизации на побережье Калимдора. Сегодня ее упавшие колонны и треснувшие камни наполовину скрыты кустарником и морским туманом, а по руинам бродят неупокоенные духи и хищные звери. Среди развалин разбросаны древние реликвии той золотой эпохи. Хотя за десять тысяч лет забвения они обветшали, в этих артефактах еще сохранились слабые следы эльфийского тайного мастерства, поэтому без присмотра они опасны."},{t="Надвигающаяся угроза",b="Древо Мудрости Ону ищет эти реликвии: он узнал, что зловещий культ Сумеречного Молота пытается превратить в оружие забытые эльфийские записи, найденные у Меча Властителя. Культисты хотят использовать древнюю магию кальдораев, чтобы ускорить возвращение своих темных повелителей. Изучая эти разрозненные остатки, Ону и стражи Темных берегов надеются раскрыть замыслы культа и не дать угасающей силе Матистры обратиться ко злу."}},faq={{q="Что такое Реликвии Матистры?",a="Это обломки и артефакты, оставшиеся от древнего города ночных эльфов Матистры. Несмотря на возраст в тысячи лет, в них еще сохранились следы волшебного мастерства эльфийской цивилизации времен до Раскола.",al={"what is mathystra relic","elven relics mathystra","what are these relics","что такое реликвия матистры","эльфийские реликвии матистры","что это за реликвии"}},{q="Где найти эти реликвии?",a="Они разбросаны среди разбитых камней, упавших колонн и высокой травы в Руинах Матистры на севере Темных берегов.",al={"mathystra relic location","where to find relics","relic locations","где реликвия матистры","где найти реликвии","места реликвий"}},{q="Кому нужны Реликвии Матистры?",a="Древо Мудрости по имени Ону, обитающий в Роще Древних на юге Темных берегов, просит путников собрать их для изучения.",al={"who needs relics","who do i bring relics to","onu relics","кому нужны реликвии","кому отнести реликвии","ону реликвии"}},{q="Почему Сумеречный Молот интересуется ими?",a="Культ расшифровывает древние эльфийские тексты, найденные неподалеку у Меча Властителя. Он стремится исказить и использовать магические тайны древних эльфов, чтобы призвать в мир своих теневых повелителей.",al={"why twilight hammer wants relics","twilight's hammer mathystra","зачем сумеречному молоту реликвии","сумеречный молот матистра"}}},fp="15,261,28.491.0,15.479.1,30.227.0,29.153.0,31.135.0,48.223.0"}
P.entries["item:melenas-head"] = {n="Голова Меленаса",s="Голова Меленаса — отрубленная голова лорда Меленаса, предводителя сатиров, расположившегося в Пещере Бесов. Ее приносят как неоспоримое доказательство его смерти: трофей знаменует тихое устранение остаточной демонической угрозы на ветвях Тельдрассила.",h="Голова Меленаса — отрубленная голова лорда Меленаса, предводителя сатиров, расположившегося в Пещере Бесов.",kw={"fel rock","grell","lord melenas","melenas' head","satyr","teldrassil","twisted hatred","пещера бесов","грелл","лорд меленас","голова меленаса","сатир","тельдрассил","искаженная ненависть"},ang={["class:Warrior"]="Отрубленная голова вражеского полководца — безошибочное, первобытное доказательство того, что опасный противник и его воинство греллов разбиты.",["race:NightElf"]="Сатиры — трагическое, демоническое искажение древнего рода ночных эльфов, и потому тихая казнь лорда Меленаса — это и необходимость, и повод для стыда всего народа."},sec={{t="Невысказанный позор",b="Для ночных эльфов, охраняющих Тенистую долину и ближние земли Тельдрассила, само присутствие сатиров на их новом Мировом Древе — горький позор. Лорд Меленас устроил логово в извилистых пещерах Пещеры Бесов к северу от эльфийских поселений и собрал под свои знамена воинственных греллов. Поскольку кальдораи предпочитают осмотрительность там, где скверна подступает так близко к их землям, этот кровавый трофей служит тайным доказательством того, что его замыслы пресечены до того, как его влияние распространилось."}},faq={{q="Кем был лорд Меленас?",a="Лорд Меленас был предводителем сатиров, скрывавшимся в пещере под названием Пещера Бесов в Тельдрассиле. Он собрал под своим началом отряд греллов, чтобы строить козни против ближних застав кальдораев.",al={"lord melenas lore","who is melenas","melenas story","лорд меленас предания","кто такой меленас","история меленаса"}},{q="Почему его смерть должна остаться тихой?",a="Присутствие сатиров — древних проклятых ночных эльфов, искаженных демонической скверной, — так близко к священным ветвям Тельдрассила кальдораи считают глубоким позором. Быстрая и тихая расправа с ним предотвращает панику и уменьшает стыд.",al={"why secrecy","twisted hatred secret","why quiet","почему тайна","тайна искаженной ненависти","почему тихо"}},{q="Откуда взята Голова Меленаса?",a="Голову достают в глубине Пещеры Бесов — оскверненной пещеры к северу от Доланаара и Тенистой долины в центре Тельдрассила.",al={"where to find melenas","fel rock location","melenas location","где найти меленаса","пещера бесов где","где меленас"}}},fp="13,248,20.532.0,21.187.0,32.253.0,35.131.0"}
P.entries["item:menethil-statuette"] = {n="Статуэтка Менетила",s="Статуэтка Менетила — редкая серебристая фигурка, изображающая покойного короля Теренаса Менетила II молодым паладином с поднятым боевым молотом. Утерянная при кораблекрушении у побережья Болотины, она — исключительно редкая память о павшем правителе Лордерона.",h="Статуэтка Менетила — редкая серебристая фигурка, изображающая покойного короля Теренаса Менетила II молодым...",kw={"blind princess","bluegill","bolvar fordragon","cathedral of light","grayson shadowbreaker","menethil statuette","terenas menethil","wetlands","слепая принцесса","синежабрые","болвар фордрагон","собор света","грейсон тенелом","статуэтка менетила","теренас менетил","болотина"},ang={["class:Paladin"]="Статуэтка показывает покойного короля Теренаса юным воином Света с поднятым молотом — глубоко трогательный образ для святых рыцарей, скорбящих о павшем королевстве.",["faction:Alliance"]="Теренас был объединяющим вождем, основавшим Великий Альянс, и потому любой сохранившийся памятник ему — вдохновляющее сокровище в расколотом мире."},sec={{t="Редкая реликвия Лордерона",b="Статуэтка изображает короля Теренаса Менетила II в молодые годы — длинноволосым паладином, поднимающим молот к небесам. Теренас славился скромностью во время правления и не любил памятников себе, поэтому статуй и изображений в его честь почти не заказывали. После падения Королевства Лордерон под натиском Плети почти все такие реликвии были уничтожены, и потому эта уцелевшая фигурка чрезвычайно ценна для Альянса."},{t="Потеря на болотах",b="Статуэтка находилась в грузе торгового судна «Слепая принцесса», шедшего в союзную гавань Менетилов. Когда у болотистого берега корабль атаковали свирепые мурлоки Синежабрые, груз разбросало, и статуэтка оказалась в полузасыпанной бочке на берегу. Поскольку поблизости рыскали такие враги, как орки Драконьей Пасти, местные защитники поспешили отправить найденную фигурку на юг, в Штормград, где верховный лорд Болвар Фордрагон передал ее на хранение в Собор Света."}},faq={{q="Кто изображен на статуэтке?",a="Это король Теренас Менетил II, прежний правитель Лордерона и создатель первоначального Альянса. Он показан не старым монархом, а молодым паладином, потрясающим боевым молотом.",al={"who is on the statue","what does the statuette depict","who is the menethil statuette","кто на статуе","что изображает статуэтка","что такое статуэтка менетила"}},{q="Как была потеряна статуэтка?",a="Ее перевозили через Великое море на торговом судне «Слепая принцесса». Когда корабль атаковали мурлоки Синежабрые в Болотине, груз выбросило на берег, и его занесло грязью.",al={"how did it get lost","who lost the statuette","shipwreck wetlands statue","как она потерялась","кто потерял статуэтку","кораблекрушение болотина статуя"}},{q="Почему изображения короля Теренаса так редки?",a="Король Теренас был скромным правителем и не жаловал памятники самому себе, поэтому его статуй было изваяно совсем мало. Почти все оставшиеся портреты и фигуры на севере были уничтожены, когда Плеть разорила Лордерон.",al={"why are there few statues of terenas","terenas memorials","почему мало статуй теренаса","памятники теренасу"}},{q="Куда попадает статуэтка в итоге?",a="После того как ее находят в Болотине, ее приносят верховному лорду Болвару Фордрагону в Крепость Штормграда. Болвар понимает, что в реликвии воплотился Свет, и велит лорду Грейсону Тенелому беречь ее в Соборе Света.",al={"where do i take the statuette","who keeps the statuette","statuette cathedral","куда отнести статуэтку","кто хранит статуэтку","статуэтка собор"}}},fp="18,267,25.469.0,16.499.0,30.204.0,27.203.0,43.247.0,32.260.1"}
P.entries["item:merrin-s-letter"] = {n="Письмо Меррин",s="Письмо Меррин — срочное послание Меррин Камнепряд, археолога, оказавшейся в ловушке на месте раскопок в Болотине. В нем рассказано о катастрофическом разгроме их археологической экспедиции свирепыми ящерами-хищниками и о том, что она пока жива, о чем сообщается близким.",h="Письмо Меррин — срочное послание Меррин Камнепряд, археолога, оказавшейся в ловушке на месте раскопок в...",kw={"explorers' league","merrin rockweaver","merrin's letter","mottled raptors","tarrel rockweaver","wetlands","whelgar's excavation","лига исследователей","меррин камнепряд","письмо меррин","пестрые ящеры","таррел камнепряд","болотина","раскопки вельгара"},ang={["faction:Alliance"]="Доставка этой записки приносит ценные сведения и горькое утешение часовым Альянса, несущим дозор на дороге через Болотину.",["race:Dwarf"]="Письмо показывает, какую высокую цену платит Лига исследователей, раскрывая древнюю историю в опасных глухих землях Каз Модана."},sec={{t="Весточка из руин",b="Во время раскопок огромных доисторических окаменелостей и реликвий на месте раскопок Вельгара в Болотине дворфийская экспедиция потревожила гнездо свирепых пестрых ящеров. Звери заполонили траншеи, убили нескольких рабочих и отрезали уцелевшим исследователям путь к отступлению. Среди хаоса Меррин Камнепряд написала записку мужу Таррелу в Гавань Менетилов: раскопки разгромлены, но она, геолог Вельгар и Ормер Сталеплет выжили, укрывшись за баррикадами."}},faq={{q="Кто написал Письмо Меррин?",a="Письмо написала Меррин Камнепряд, исследовательница, участвующая в археологической экспедиции на месте раскопок в южных холмах Болотины.",al={"author of merrins letter","who is merrin","автор письма меррин","кто такая меррин"}},{q="Кому адресовано письмо?",a="Оно адресовано Таррелу Камнепряду, который с тревогой ждет вестей на мосту в Гавани Менетилов.",al={"recipient of merrins letter","who gets merrins letter","адресат письма меррин","кто получает письмо меррин"}},{q="Что случилось с командой раскопок?",a="Пока команда откапывала огромные окаменелые кости, на археологов напала и смяла стая пестрых ящеров. Многие рабочие-дворфы погибли, и лишь горстка выживших укрылась в наспех устроенном лагере.",al={"what happened to the dig","why did the expedition fail","что случилось с раскопками","почему экспедиция провалилась"}},{q="Кто помог Меррин пережить нападение?",a="Ормер Сталеплет храбро сражался, защищая Меррин и главного геолога, и позволил им отступить и укрыться, пока остальные раскопки пали под натиском ящеров.",al={"who saved merrin","ormer ironbraid","кто спас меррин","ормер сталеплет"}}},fp="15,269,25.531.0,26.155.0,31.100.0,37.228.0,37.161.0"}
P.entries["item:middle-of-gelkak-s-key"] = {n="Средняя часть ключа Гелхака",s="Средняя часть ключа Гелхака — сломанный металлический фрагмент, принадлежавший потерпевшему кораблекрушение гному-пирату Гелхаку Гиромачту. После крушения его судна у берегов Темных берегов эта средняя часть была похищена падальщиками из местных мурлоков Серой Мглы.",h="Средняя часть ключа Гелхака — сломанный металлический фрагмент, принадлежавший потерпевшему кораблекрушение...",kw={"clockwork","darkshore","gelkak gyromast","greymist","middle of gelkak's key","murloc","shipwreck","заводной механизм","темные берега","гелхак гиромачт","серая мгла","средняя часть ключа гелхака","мурлок","кораблекрушение"},ang={["profession:Engineering"]="Ключ — особая механическая деталь для завода и управления заводным помощником, и она демонстрирует классическую гномью изобретательность даже в руках пирата."},sec={{t="Осколок в иле",b="Когда корабль Гелхака Гиромачта утащили под воду дикие жесткозубы, гном-пират выбрался на берег, а его самые ценные пожитки разбились о скалистые отмели. Среди обломков был особый заводной ключ для его механического помощника. При крушении ключ сломался на три части, разлетевшиеся по берегу. Верхнюю и нижнюю унесли прибрежные звери, а среднюю заметили мурлоки Серой Мглы, рыскавшие у прибоя Темных берегов, и быстро спрятали блестящую металлическую вещицу в своих лагерях и среди обломков."}},faq={{q="Для чего нужна Средняя часть ключа Гелхака?",a="Это один из трех фрагментов, нужных потерпевшему кораблекрушение пирату Гелхаку Гиромачту на побережье Темных берегов. Когда ее соберут с верхней и нижней частями, целый ключ используется, чтобы вновь запустить его механического помощника.",al={"what does gelkaks key do","middle of gelkaks key use","why do i need this key","для чего ключ гелхака","средняя часть ключа гелхака","зачем нужен этот ключ"}},{q="Где оказалась эта часть ключа?",a="Среднюю часть унесло племя мурлоков Серой Мглы. Ее можно получить с налетчиков, оракулов, сетеметателей, охотников приливов и других мурлоков племени, бродящих по пляжам и среди обломков кораблей Темных берегов.",al={"who has the middle key","where to find middle of gelkak key","middle key dropped by","у кого средняя часть ключа","где найти среднюю часть ключа гелхака","с кого падает средняя часть"}},{q="Почему ключ вообще сломался?",a="Корабль Гелхака потопили у самого берега свирепые жесткозубы. Когда гнома выбросило на берег среди щепок, ключ разбился о прибрежные скалы на три части, и местные падальщики унесли их.",al={"how did the key break","why is it in pieces","как сломался ключ","почему он на части"}}},fp="22,254,22.598.0,44.212.0,32.208.0,42.242.0"}
P.entries["item:milly-s-harvest"] = {n="Урожай Милли",s="Урожай Милли — это ящики и ведра со свежесобранным виноградом, который Милли Осворт собрала на Виноградниках Североземья. Когда поля заняли бандиты из Братства Справедливости, урожай бросили, и плоды могли украсть воры или растоптать сапогами стражники аббатства.",h="Урожай Милли — это ящики и ведра со свежесобранным виноградом, который Милли Осворт собрала на Виноградниках...",kw={"defias","elwynn forest","grapes","milly osworth","milly's harvest","northshire abbey","northshire vineyards","братство справедливости","элвиннский лес","виноград","милли осворт","урожай милли","аббатство североземья","виноградники североземья"},ang={["faction:Alliance"]="Угроза простым фермерам Североземья показывает, насколько поредел военный гарнизон Штормграда: обычные жители вынуждены полагаться на странствующих героев, защищающих их средства к существованию.",["race:Human"]="Для людей, начинающих путь в Североземье, возвращение урожая Милли часто становится первой встречей с растущим беззаконием Братства Справедливости на родной земле."},sec={{t="Хрупкий урожай",b="Плодородная почва Долины Североземья дает виноград, жизненно важный для местных виноделов и общины аббатства. Когда наступил сезон сбора, Милли Осворт работала на лозах и складывала свежие плоды в ведра. Ее труд грубо прервали вооруженные разбойники в красных масках, ворвавшиеся на виноградники: ей пришлось бежать обратно на территорию аббатства, а урожай остался разбросанным между рядами."},{t="Побочный ущерб",b="Хотя стражи Штормграда охраняют вход в долину, нехватка людей сделала Североземье уязвимым. Гарнизон обещал выгнать бандитов из Братства Справедливости, но Милли опасалась, что любая затяжная схватка между стражниками в доспехах и безжалостными ворами полностью уничтожит плоды ее труда. Если вернуть ящики до того, как их затопчут или унесут как провизию, одним из немногих мирных урожаев Североземья не пожертвуют."}},faq={{q="Что такое Урожай Милли?",a="Это собранный виноград, упакованный в ящики и ведра, который оставила Милли Осворт, когда головорезы из Братства Справедливости захватили Виноградники Североземья.",al={"millys harvest","what is the harvest","milly osworth grapes","урожай милли","что за урожай","виноград милли осворт"}},{q="Почему ящики остались на винограднике?",a="Бандиты из Братства Справедливости напали на виноградники прямо во время сбора урожая Милли, и ей пришлось бросить плоды и бежать в безопасное Аббатство Североземья.",al={"why abandoned","why did milly leave the grapes","why leave harvest","почему брошен","почему милли оставила виноград","почему оставили урожай"}},{q="Почему стража Североземья не смогла забрать урожай?",a="Стражи в Североземье и так перегружены борьбой с вылазками Братства Справедливости и другими местными угрозами. Милли также боялась, что даже если стражники прогонят бандитов, их тяжелые сапоги растопчут и погубят нежный виноград.",al={"why not guards","why cant guards get it","stormwind guards northshire","почему не стража","почему стража не может забрать","стража штормграда североземье"}},{q="Кто эти бандиты, угрожающие урожаю?",a="Нарушители — головорезы из Братства Справедливости, шайки преступников и разбойников, вызывающей масштабные беспорядки по всему Элвиннскому лесу.",al={"who took the vineyards","who is attacking the vineyard","vineyard bandits","кто захватил виноградники","кто нападает на виноградник","бандиты виноградников"}}},fp="15,292,15.412.0,17.448.0,24.158.0,48.177.0,56.235.0,44.145.0"}
P.entries["item:miners-gear"] = {n="Инструменты шахтеров",s="Инструменты шахтеров — это прочные дворфийские кирки, лопаты и землеройные орудия, хранящиеся в Руднике у Серебряного ручейка. После нашествия вредителей Лига шахтеров поручила героям вернуть эти ценные инструменты до того, как местная стража начнет штурм.",h="Инструменты шахтеров — это прочные дворфийские кирки, лопаты и землеройные орудия, хранящиеся в Руднике у...",kw={"filthy paws","kobold","loch modan","miners gear","miners league","mountaineer stormpike","silver stream mine","грязные лапы","кобольд","лок модан","инструменты шахтеров","лига шахтеров","горный пехотинец грозовая вершина","рудник у серебряного ручейка"},ang={["profession:Mining"]="Каждый шахтер знает цену хорошо откованного дворфийского железа; оставить первоклассные кирки и лопаты в руках падальщиков со свечами на головах считается маленькой трагедией.",["race:Dwarf"]="Для дворфов то, что кобольды хватают грязными лапами дворфийские изделия, — нестерпимое оскорбление, требующее немедленно очистить рудник."},sec={{t="Припасы Лиги шахтеров",b="Когда в Руднике у Серебряного ручейка на востоке Лок Модана закончилась руда, Лига шахтеров превратила тихие туннели в подземный склад горного снаряжения. К несчастью, обитающие в туннелях кобольды быстро захватили комплекс, растащили припасы и устроили гнезда среди ящиков. Опасаясь, что ценные дворфийские инструменты погибнут при полномасштабном штурме горных пехотинцев или будут испорчены падальщиками, Лига надеется на смелых героев, которые проникнут внутрь и вынесут ящики в безопасное место."}},faq={{q="Что такое Инструменты шахтеров?",a="Инструменты шахтеров — это ящики с дворфийскими землеройными орудиями, такими как кирки и лопаты, принадлежащие Лиге шахтеров и хранящиеся в сухих туннелях Рудника у Серебряного ручейка.",al={"what is miners gear","miners gear items","miners gear loch modan","что такое инструменты шахтеров","предметы инструменты шахтеров","инструменты шахтеров лок модан"}},{q="Почему инструменты оставили в руднике?",a="Когда в Руднике у Серебряного ручейка закончилась руда, Лига шахтеров превратила пустые туннели в склад. Инструменты лежали там, пока штольни неожиданно не заполонили кобольды.",al={"why is gear in silver stream mine","why leave gear there","почему инструменты в руднике у серебряного ручейка","почему оставили инструменты"}},{q="Кто хочет вернуть эти инструменты?",a="Горный пехотинец Грозовая Вершина руководит возвращением инструментов от имени Лиги шахтеров. Он хочет спасти их до того, как его товарищи-воины войдут в рудник истреблять кобольдов.",al={"who wants miners gear","who needs the gear","mountaineer stormpike gear","кто хочет инструменты шахтеров","кому нужны инструменты","горный пехотинец грозовая вершина инструменты"}},{q="Где найти Инструменты шахтеров?",a="Инструменты упакованы в ящики Лиги шахтеров, разбросанные по штольням Рудника у Серебряного ручейка в восточных холмах Лок Модана.",al={"miners gear location","where to find miners gear","miners league crates location","где инструменты шахтеров","где найти инструменты шахтеров","ящики лиги шахтеров где"}}},fp="12,271,30.521.0,21.178.0,34.179.0,30.180.0,32.151.0"}
P.entries["item:minshina-s-skull"] = {n="Череп Миншины",s="Череп Миншины хранит плененную душу тролля из племени Черного Копья Миншины, брата Мастера Гадрина. Захваченный вероломным колдуном Залазаном на Островах Эха, череп служит мрачным сосудом для темных ритуалов.",h="Череп Миншины хранит плененную душу тролля из племени Черного Копья Миншины, брата Мастера Гадрина.",kw={"circle of power","darkspear","echo isles","gadrin","minshina","sen'jin village","skull","zalazane","круг силы","черное копье","острова эха","гадрин","миншина","деревня сен'джин","череп","залазан"},ang={["faction:Horde"]="Возвращение черепа наносит ранний удар по извращенной власти Залазана над Островами Эха у побережья Дуротара.",["race:Troll"]="Для племени Черного Копья осквернение Миншины Залазаном — тяжкое оскорбление традиций предков, поэтому возвращение его черепа становится вопросом племенной чести."},sec={{t="Плененный дух",b="Когда Залазан захватил Острова Эха и изгнал племя Черного Копья, Миншина оказался среди плененных и убитых. Не позволив жертве уйти в смерть, вероломный колдун привязал душу Миншины к его отсеченному черепу. Помещенный в омерзительный круг силы на самом южном острове, череп стал нитью магического рабства. Мастер Гадрин, которого мучают видения брата, зовущего его во снах, ищет отважных путников, чтобы те проникли на захваченные острова, вернули реликвию и разрушили власть Залазана над духом его брата."}},faq={{q="Кем был Миншина?",a="Миншина был троллем из племени Черного Копья и братом Мастера Гадрина из Деревни Сен'джин. Он был убит во время смуты, вызванной предательством Залазана на Островах Эха.",al={"minshina lore","who is minshina","master gadrin brother","миншина предания","кто такой миншина","брат мастера гадрина"}},{q="Почему душа Миншины заточена в его черепе?",a="Залазан темной магией привязал дух Миншины прямо к его отсеченной голове. Помещенная в ритуальный круг силы на главном острове, плененная душа оставалась во власти Залазана, а не уходила к предкам.",al={"why trap his soul","zalazane skull ritual","soul trapped in skull","зачем заточили душу","ритуал черепа залазана","душа в черепе"}},{q="Где находится череп?",a="Череп находится на самом большом, южном острове Островов Эха. Он лежит на вершине холма в круге силы, украшенном свечами, ритуальными знаками и другими черепами, которые охраняют прислужники Залазана.",al={"where is minshinas skull","circle of power location","skull location echo isles","где череп миншины","круг силы где","череп острова эха"}},{q="Что произойдет, если принести череп Мастеру Гадрину?",a="Возвращение черепа Мастеру Гадрину в Деревне Сен'джин разрушает темные чары. Когда мерзкая связь разорвана, призрак Миншины ненадолго появляется, кланяется в благодарность и мирно уходит в мир предков.",al={"freeing minshina","gadrin skull reward","what happens to minshina","освобождение миншины","награда гадрина за череп","что станет с миншиной"}}},fp="16,228,16.585.0,17.169.0,44.238.0,27.203.0,56.231.1"}
P.entries["item:mirror-lake-water-sample"] = {n="Проба воды Зеркального озера",s="Проба воды Зеркального озера — это фляга свежей озерной воды, набранной у подножия водопада в Элвиннском лесу. Новички-маги собирают ее по поручению Джиннии Пушка в Квартале магов Штормграда, чтобы выяснить, не просачиваются ли измененные арканные потоки в местные источники воды.",h="Проба воды Зеркального озера — это фляга свежей озерной воды, набранной у подножия водопада в Элвиннском лесу.",kw={"arcane taint","elwynn forest","flask","jennea cannon","mirror lake","stormwind","water sample","wizard's sanctum","арканная порча","элвиннский лес","фляга","джинния пушка","зеркальное озеро","штормград","проба воды","святилище волшебника"},ang={["class:Mage"]="Сбор пробы — один из первых ритуалов долга для магов Альянса, обучающихся в Святилище волшебника: он учит следить за потоками силы в природе и распознавать неконтролируемое магическое просачивание."},sec={{t="Проверка вод Элвинна",b="После катастрофических мировых потрясений, сбивших мистические потоки мира с устойчивых путей, маги Святилища волшебника в Штормграде всерьез обеспокоены остаточными арканными нарушениями. Джинния Пушка поручает перспективным ученикам наполнить особую флягу у подножия водопада Зеркального озера к юго-западу от Ворот Штормграда. Анализируя пробу, маги хотят выяснить, не проникла ли блуждающая магическая порча в природные водоемы, которыми пользуется окрестное население."}},faq={{q="Что такое Проба воды Зеркального озера?",a="Это пузырек воды, набранной у водопада на Зеркальном озере в Элвиннском лесу, во Фляге Джиннии. Новички-маги собирают ее, чтобы Святилище волшебника могло проверить воду на магическое загрязнение.",al={"mirror lake sample","water sample item","jennea water","проба зеркального озера","проба воды предмет","вода джиннии"}},{q="Зачем Джиннии Пушка эта проба воды?",a="Недавние мистические потрясения по всему Азероту нарушили устойчивые магические потоки. Джинния Пушка опасается, что неуправляемая магическая энергия может менять природную среду и отравлять местную питьевую воду.",al={"why test mirror lake","jennea cannon purpose","magical taint water","зачем проверять зеркальное озеро","цель джиннии пушка","магическая порча воды"}},{q="Где берут пробу?",a="Ее берут у подножия водопада, впадающего в Зеркальное озеро, к юго-западу от Ворот Штормграда в Элвиннском лесу.",al={"where to get sample","mirror lake location","sample waterfall","где взять пробу","где зеркальное озеро","водопад проба"}},{q="Что будет, если вода окажется магически испорченной?",a="Джинния Пушка опасается, что те, кто долго пьет воду из Зеркального озера, могут пострадать от вредных магических воздействий, если потоки силы загрязнили источник воды.",al={"tainted water effects","is mirror lake poisoned","последствия порчи воды","отравлено ли зеркальное озеро"}}},fp="24,301,28.549.0,37.189.0,46.197.0,30.130.0,60.174.0"}
P.entries["item:mist-veil-s-lockbox"] = {n="Денежный ящик Туманной Пелены",s="Денежный ящик Туманной Пелены — прочный сундук, лежащий в затонувших обломках ночно-эльфийского корабля «Туманная Пелена» у побережья Темных берегов. В нем хранятся судовой журнал капитана и личные вещи, потерянные, когда корабль был атакован прибрежными мурлоками и затонул.",h="Денежный ящик Туманной Пелены — прочный сундук, лежащий в затонувших обломках ночно-эльфийского корабля...",kw={"auberdine","darkshore","gorbold steelhand","lockbox","mist veil","murloc","shipwreck","silver dawning","аубердин","темные берега","горбольд сталерук","ящик","туманная пелена","мурлок","кораблекрушение","серебряный рассвет"},ang={["faction:Alliance"]="Возвращая этот ящик, вы чтите павшую команду и помогаете испытывающей трудности общине моряков в Аубердине.",["race:NightElf"]="Павший капитан был уважаемым мореходом из ночных эльфов, и возвращение его журнала помогает упокоить достойный дух в водах у Темных берегов."},sec={{t="Потерянный в глубинах",b="Корабль ночных эльфов «Туманная Пелена» погиб, плывя по опасным прибрежным водам к Аубердину. Мурлоки напали на него вместе с его собратом, «Серебряным рассветом», и корабль, не выдержав натиска, пошел ко дну. Капитан погиб во время нападения, оставив судовой журнал и ценные личные вещи, запечатанные в этом ящике. Сундук лежит в затопленном трюме — мрачный трофей среди тех самых существ, что виновны в катастрофе."},{t="Покой для команды",b="Для уцелевших моряков, добравшихся до Аубердина, потеря корабля и командира остается открытой раной. Горбольд Сталерук ищет Денежный ящик Туманной Пелены, чтобы последние вещи капитана были почтены и преданы покою. Отважившись проникнуть в затопленные руины за сундуком, вы хоть немного утешите скорбящих выживших, оказавшихся на материке."}},faq={{q="Что внутри Денежного ящика Туманной Пелены?",a="В ящике лежат судовой журнал капитана и его личные вещи. Капитан погиб, когда корабль затонул, а уцелевшие члены команды в Аубердине хотят вернуть эти памятные вещи, чтобы почтить павшего командира.",al={"contents of mist veil lockbox","what does the lockbox hold","what is in the box","содержимое ящика туманной пелены","что лежит в ящике","что в ящике"}},{q="Как затонула «Туманная Пелена»?",a="«Туманную Пелену» атаковали прибрежные мурлоки, когда корабль шел к Аубердину. Не выдержав натиска, он пошел ко дну вместе с судном-спутником, «Серебряным рассветом».",al={"why did the ship wreck","who sank mist veil","what happened to the mist veil","почему корабль разбился","кто потопил туманную пелену","что случилось с туманной пеленой"}},{q="Где находится ящик?",a="Он лежит под водой у побережья Темных берегов, к северу от Аубердина. Сундук находится в затопленном корпусе обломков «Туманной Пелены», где кишат мурлоки.",al={"where is mist veil's lockbox","mist veil location","lockbox location","где денежный ящик туманной пелены","где туманная пелена","где ящик"}},{q="Кто хочет вернуть ящик?",a="Горбольд Сталерук в Аубердине ищет ящик от имени уцелевших членов команды, надеясь успокоить память павшего капитана.",al={"who takes the lockbox","who gives the quest","gorbold lockbox quest","кто принимает ящик","кто дает задание","задание горбольда с ящиком"}}},fp="19,260,18.493.0,17.391.0,35.204.0,27.215.0,27.190.0,32.155.0"}
P.entries["item:mo-grosh-crystal"] = {n="Мо'грошский кристалл",s="Мо'грошские кристаллы — редкие минеральные образования, которые добывают и копят огры Мо'грош на северо-востоке Лок Модана. Ценимые за необычные алхимические свойства, они служат важным компонентом для обезвреживания взрывчатки Черного Железа.",h="Мо'грошские кристаллы — редкие минеральные образования, которые добывают и копят огры Мо'грош на...",kw={"dark threat looms","hinderweir","loch modan","mo'grosh crystal","mogrosh","stonewrought dam","надвигается темная угроза","хиндервейр","лок модан","мо'грошский кристалл","мо'грош","каменная плотина"},ang={["profession:Mining"]="Хотя эти сырые образцы минерала добывают в глубине земель огров, они проявляют уникальную химическую активность при смешивании с органическими реагентами.",["race:Dwarf"]="Оборона Каменной Плотины зависит от дворфийской изобретательности: добытое кланом огров сокровище превращается в защиту от коварства Черного Железа."},sec={{t="Редкий огрский товар",b="В скалах северо-востока Лок Модана огры Мо'грош добывают эти необычные кристаллы возле своего оплота. Хотя грубые огры редко сведущи в тонкой металлургии, мо'грошские кристаллы — ценное сокровище клана: их носят и простые громилы, и мистики-шаманы, и грозные вожди. Кристаллы довольно редки, поэтому их тщательно охраняют в Оплоте Мо'грош."},{t="Противодействие угрозе Черного Железа",b="Когда разведка сообщает, что диверсанты Черного Железа замышляют удар по Каменной Плотине, главный инженер Хиндервейр ищет Мо'грошский кристалл, а также яд паука-охотника и слезы кроколисков. Смешав кристаллический минерал с этими реагентами, дворфийские инженеры составляют особый состав, способный обезвредить и разрядить опасную взрывчатку Черного Железа, пока долина не оказалась затоплена."}},faq={{q="Откуда берутся Мо'грошские кристаллы?",a="Их добывают и хранят огры Мо'грош на северо-востоке Лок Модана. Кристалл может оказаться у любого члена клана в Оплоте Мо'грош — мистиков, громил, головорезов и шаманов.",al={"mogrosh crystal location","where to find mogrosh crystal","who drops mogrosh crystal","где мо'грошский кристалл","где найти мо'грошский кристалл","с кого падает мо'грошский кристалл"}},{q="Для чего нужен кристалл?",a="Главному инженеру Хиндервейру у Каменной Плотины нужен кристалл для приготовления обезвреживающей смеси. В сочетании с ядом паука-охотника и слезами кроколисков она обезвреживает взрывчатку Черного Железа, предназначенную для подрыва плотины.",al={"what does mogrosh crystal do","use of mogrosh crystal","why hinderweir wants crystal","для чего мо'грошский кристалл","применение мо'грошского кристалла","зачем хиндервейру кристалл"}},{q="Зачем огры добывают эти кристаллы?",a="Огры Мо'грош добывают кристаллы в окрестных холмах как ценный ресурс клана. Мистики и шаманы используют странные минералы в ритуалах, а воины копят их как редкий товар.",al={"why ogres have crystals","ogre crystal lore","почему у огров кристаллы","предания о кристаллах огров"}}},fp="16,241,23.451.0,31.417.1,37.204.0,29.223.0,40.215.0"}
P.entries["item:modr-fragment"] = {n="Фрагмент Модр",s="Фрагмент Модр — один из четырех недостающих осколков древнего Камня Гоаз, реликвии, найденной в Болотине. Обнаруженный среди древностей и рыхлой земли в Раскопках Вельгара, он несет древние письмена Титанов, необходимые для восстановления забытого пророчества.",h="Фрагмент Модр — один из четырех недостающих осколков древнего Камня Гоаз, реликвии, найденной в Болотине.",kw={"ados","excavation","goaz stone","golm","modr fragment","neru","old gods","titan","wetlands","whelgar","адос","раскопки","камень гоаз","голм","фрагмент модр","неру","древние боги","титан","болотина","вельгар"},ang={["faction:Alliance"]="Путники Альянса помогают геологу Вельгару пробиться на захваченные раскопки, чтобы сберечь бесценные исторические исследования для Стальгорна.",["race:Dwarf"]="Для дворфийской Лиги исследователей возвращение утраченных частей вроде Фрагмента Модр необходимо, чтобы расшифровать наследие Титанов и раскрыть глубокую историю их народа."},sec={{t="Часть Камня Гоаз",b="Прежде чем свирепые ящеры вытеснили Лигу исследователей с раскопок в Болотине, геолог Вельгар обнаружил Камень Гоаз — огромную плиту с древними письменами Титанов. Переведенный текст резко обрывался в четырех местах, скрывая предупреждения о божественном замысле и обреченном пророчестве. Фрагмент Модр — один из этих четырех утраченных осколков, оставленный среди древних реликвий и развороченной земли, когда землекопам пришлось спасаться бегством."},{t="Тайны под землей",b="Сложив Фрагмент Модр с фрагментами Адос, Голм и Неру, геолог Вельгар наконец сможет восстановить надпись целиком. Переведенный текст раскрывает поразительные предания зари мира, в частности упоминая «Древних богов... скованных под землей». Простые раскопки в болотах обнажили следы первобытной борьбы, запертой под землей."}},faq={{q="Что такое Фрагмент Модр?",a="Это осколок камня с письменами, отколотый от Камня Гоаз — древней реликвии Титанов, найденной в Раскопках Вельгара в Болотине.",al={"modr fragment","what is modr","modr relic","фрагмент модр","что такое модр","реликвия модр"}},{q="Кто ищет этот фрагмент?",a="Его ищет геолог Вельгар, археолог Лиги исследователей, расположившийся на краю кишащих ящерами раскопок, чтобы восполнить недостающий текст плиты.",al={"who wants modr fragment","whelgar fragment quest","кому нужен фрагмент модр","задание вельгара с фрагментом"}},{q="Что будет, если собрать все четыре фрагмента?",a="Соединив Фрагмент Модр с фрагментами Адос, Голм и Неру, геолог Вельгар сможет восстановить Камень Гоаз. Прочитав весь текст Титанов, он обнаруживает зловещие упоминания «Древних богов... скованных под землей».",al={"goaz stone completed","uncovering the past ending","what does the goaz stone say","камень гоаз собран","раскрытие прошлого окончание","что написано на камне гоаз"}},{q="Где найти фрагмент?",a="Он разбросан по Раскопкам Вельгара на юге Болотины, спрятан в древних сосудах-реликвиях или кучах рыхлой земли, которые охраняют агрессивные ящеры.",al={"modr fragment location","where to find modr","где фрагмент модр","где найти модр"}}},fp="13,269,25.468.0,25.427.1,26.146.0,33.163.0,50.229.1,28.165.0"}
P.entries["item:moldy-tome"] = {n="Заплесневелый фолиант",s="Заплесневелый фолиант — подмоченный, спасенный остаток, содержащий половину изначального Фолианта заговора. Потерянный при кораблекрушении у берегов Предгорий Хилсбрада, он хранит темные тайные ритуалы, желанные чернокнижникам, стремящимся овладеть призывом демонов.",h="Заплесневелый фолиант — подмоченный, спасенный остаток, содержащий половину изначального Фолианта заговора.",kw={"azurelode","felhunter","hillsbrad","moldy tome","southshore","tattered manuscript","tome of the cabal","warlock","лазуритовый рудник","охотник скверны","хилсбрад","заплесневелый фолиант","южнобережье","потрепанный манускрипт","фолиант заговора","чернокнижник"},ang={["class:Warlock"]="Возвращение этого промокшего гримуара — важный обряд посвящения для чернокнижников, стремящихся собрать ритуалы, необходимые для подчинения охотника Скверны."},sec={{t="Потерянный волнами",b="Фолиант заговора был единственным в своем роде, незаменимым трудом о темных искусствах, некогда хранившимся в королевстве Лордерон. В какой-то момент своей мрачной истории гримуар был безжалостно изуродован и разорван надвое. Часть, ныне именуемая Заплесневелым фолиантом, перевозилась на юг на корабле к Гавани Менетилов и Стальгорну. Судно так и не достигло цели, погибнув в коварных водах к западу от Южнобережья. Выброшенная на берег к югу от Лазуритового рудника, уцелевшая половина лежала испорченная сыростью и прибоем среди мурлоков-мародеров, бродящих по побережью Хилсбрада."},{t="Возвращение темного труда",b="Несмотря на заплесневелый и гниющий пергамент, Заплесневелый фолиант хранит могучие знания о демонах. Практики темных искусств, наставляемые такими учителями, как Кром Крепкорук в Стальгорне или Йорах Аннисон в Подгороде, отважно идут в прибрежные лагеря, чтобы вернуть его. Соединенный со своей парой — Потрепанным манускриптом из пыльных пещер Тысячи Игл — восстановленный труд дает точные заклинания, нужные для призыва и подчинения охотника Скверны."}},faq={{q="Что такое Заплесневелый фолиант?",a="Это половина редкого Фолианта заговора, оккультного гримуара с ритуалами призыва демонов. Промокшая и истлевшая, она — часть оригинального текста, потерпевшая кораблекрушение.",al={"moldy book","what is this item","moldy tome lore","заплесневелая книга","что это за предмет","предания заплесневелого фолианта"}},{q="Где оказался Заплесневелый фолиант?",a="Его выбросило на берег Предгорий Хилсбрада, к западу от Южнобережья и к югу от Лазуритового рудника. Он попал в руки местных прибрежных мурлоков, которые копят его в своем лагере.",al={"moldy tome location","where is moldy tome","where to find moldy tome","где заплесневелый фолиант","где находится заплесневелый фолиант","где найти заплесневелый фолиант"}},{q="Почему фолиант оказался на корабле?",a="Эта часть, изначально хранившаяся в Лордероне, была отправлена на корабле в Гавань Менетилов, чтобы попасть к ученым Стальгорна. Корабль затонул у побережья Хилсбрада и не завершил путь.",al={"why was it lost at sea","shipwreck tome","tome transit","почему потерян в море","фолиант кораблекрушения","перевозка фолианта"}},{q="Что нужно для завершения Фолианта заговора?",a="Заплесневелый фолиант нужно соединить с Потрепанным манускриптом — другой оторванной половиной книги, которая оказалась далеко, в Оплоте Треснувшего Копыта в Тысяче Игл.",al={"other half of the tome","missing pages","tome of the cabal parts","другая половина фолианта","недостающие страницы","части фолианта заговора"}}},fp="10,249,17.574.0,24.444.1,23.187.0,32.187.0,27.205.0,49.163.0"}
P.entries["item:moonpetal-lily"] = {n="Лунная лилия",s="Лунные лилии — крупные светящиеся растения, произрастающие в Тельдрассиле и цветущие вокруг пресных водоемов. Известные мощными целебными свойствами, их лепестки ценятся как ключевые ингредиенты природных снадобий и целебных отваров.",h="Лунные лилии — крупные светящиеся растения, произрастающие в Тельдрассиле и цветущие вокруг пресных водоемов.",kw={"aldrassil","antidote","dirania silvershine","iverron","moonpetal","moonpetal lily","shadowglen","teldrassil","альдрассил","противоядие","дирания серебряное сияние","иверрон","лунный лепесток","лунная лилия","тенистая долина","тельдрассил"},ang={["profession:Herbalism"]="Хотя Лунные лилии собирают вручную в срочных нуждах, они ясно показывают богатый целебный ботанический потенциал Тельдрассила.",["race:NightElf"]="Для юных кальдораев, обучающихся в Тенистой долине, изучение целебных свойств местных растений вроде Лунной лилии — важный первый урок жизни в гармонии с природой."},sec={{t="Растения водоемов",b="Лунные лилии растут только на влажных берегах пресных водоемов и прудов, особенно часто — на северо-западной стороне Альдрассила в Тенистой долине. Как и многие растения на недавно выросшем Мировом Древе, они впитывают особую сущность укрытых рощ Тельдрассила. Их широкие лепестки нежны и сияют, и их легко заметить у тихого берега, где влага позволяет им процветать."},{t="Природные противоядия",b="Целители и травники ночных эльфов ценят Лунную лилию за ее необыкновенные целебные свойства. В сочетании с другими лесными растениями, например гиацинтовыми грибами, лилия служит сильным успокаивающим и стабилизирующим средством. Это делает ее необходимой при варке противоядий от смертельных токсинов, в особенности от едкого яда чащобных тенетников, обитающих в Паучьем логове."}},faq={{q="Где растут Лунные лилии?",a="Они растут по берегам двух пресных прудов на северо-западной стороне Альдрассила в Тенистой долине в Тельдрассиле.",al={"where to find moonpetal lilies","moonpetal lily location","lily spots","где найти лунные лилии","где растет лунная лилия","места лилий"}},{q="Для чего нужны Лунные лилии?",a="Лилии обладают заметными восстанавливающими и целебными свойствами. В Тенистой долине Дирания Серебряное Сияние использует их вместе с гиацинтовыми грибами и Лимфой чащобного тенетника, чтобы сварить сильное противоядие от паучьего яда.",al={"moonpetal lily uses","what does moonpetal lily do","применение лунной лилии","для чего лунная лилия"}},{q="Кому нужно противоядие из этих лилий?",a="Ночному эльфу по имени Иверрон, ставшему жертвой ядовитого укуса чащобных тенетников у Паучьего логова, нужно противоядие из Лунных лилий, чтобы выжить.",al={"who is the antidote for","iverron poison","для кого противоядие","яд иверрона"}},{q="Можно ли собирать Лунные лилии за пределами Тельдрассила?",a="Они связаны с уединенными водоемами Тельдрассила и известны местным жителям под защищенными ветвями Тенистой долины.",al={"do lilies grow elsewhere","moonpetal lily other zones","растут ли лилии в других местах","лунная лилия другие зоны"}}},fp="14,236,18.439.0,17.428.0,31.133.0,35.198.0,45.176.0,55.123.0"}
P.entries["item:moonstalker-fang"] = {n="Клык лунопарда",s="Клыки лунопардов — острые зубы хищных лунопардов, обитающих в туманных лесах Темных берегов. Их собирают путники, помогающие Бацбаху Кривошипу обслуживать его автоматические устройства для взятия проб.",h="Клыки лунопардов — острые зубы хищных лунопардов, обитающих в туманных лесах Темных берегов.",kw={"buzzbox 323","darkshore","moonstalker","moonstalker fang","shadowclaw","wizbang cranktoggle","жужжалка 323","темные берега","лунопард","клык лунопарда","тенекоготь","бацбах кривошип"},ang={["class:Hunter"]="Чтобы одолеть лунопардов, нужно держать обостренные чувства настороже: эти хищники устраивают засады и сливаются с темной листвой побережья.",["race:Gnome"]="Необычные устройства дальней связи Бацбаха Кривошипа — образец классической гномьей инженерии, пусть даже его невнятная речь и странный выбор проб вызывают недоумение."},sec={{t="Перемалывающий механизм",b="Лунопарды — скрытные саблезубые кошки, обитающие на лесных опушках Темных берегов и выслеживающие добычу среди тенистых сосен. Их длинные клыки — грозное охотничье оружие, способное рассекать плоть и кости. Однако для эксцентричного гнома-механика Бацбаха Кривошипа эти зубы служат совсем иной, механической цели. Его автоматическое устройство, известное как Жужжалка 323, стоит к северу от Аубердина возле моста и настроено именно на то, чтобы измельчать прочные клыки в пыль в рамках его беспорядочных экологических исследований."}},faq={{q="Откуда берутся клыки лунопардов?",a="Их добывают из различных лунопардов, обитающих на Темных берегах: детенышей, взрослых особей, самцов, матерей и неуловимого хищника по имени Тенекоготь.",al={"where to get moonstalker fangs","who drops moonstalker fangs","fang source","где достать клыки лунопарда","кто роняет клыки лунопарда","источник клыков"}},{q="Кому нужны клыки лунопардов?",a="Гному-инженеру Бацбаху Кривошипу нужны шесть таких клыков, чтобы загрузить их в Жужжалку 323 — автоматическое устройство наблюдения к северу от Аубердина возле речного моста.",al={"who needs fangs","what quest uses fangs","buzzbox 323 turn in","кому нужны клыки","какое задание требует клыки","жужжалка 323 сдать"}},{q="Что происходит с клыками внутри машины?",a="Когда клыки помещают в Жужжалку 323, внутренние шестерни приходят в движение и тут же перемалывают твердые клыки в мелкую пыль, продвигая странные полевые опыты Бацбаха.",al={"what does buzzbox 323 do","why grind fangs","что делает жужжалка 323","зачем измельчать клыки"}}},fp="16,233,20.533.0,37.170.0,28.173.0,45.160.0"}
P.entries["item:moonwell-water-tube"] = {n="Колба для воды из лунного колодца",s="Колба с освященной водой, набранной из лунного колодца в Аубердине. Ее мощная очищающая магия природы используется, чтобы испытать таинственный красный кристалл в восточных отрогах Темных берегов.",h="Колба с освященной водой, набранной из лунного колодца в Аубердине.",kw={"as water cascades","auberdine","darkshore","empty water tube","felwood","moonwell water tube","red crystal","вода стекает","аубердин","темные берега","пустая колба для воды","оскверненный лес","колба для воды из лунного колодца","красный кристалл"},ang={["class:Druid"]="Друиды считают воду лунного колодца важным проводником равновесия природы, особенно подходящим для борьбы с неестественной порчей.",["race:NightElf"]="Использование благословенных вод лунного колодца для изучения чужеродной порчи отражает упование кальдораев на милость Элуны, открывающую скрытую истину."},sec={{t="Сосуд очищающих вод",b="Колба для воды из лунного колодца наполнена водой, взятой прямо из мерцающего лунного колодца в Аубердине и пропитанной благословенной энергией Элуны. Лунные колодцы служат поселениям ночных эльфов священными хранилищами целительной магии и чистоты, поэтому даже небольшая склянка весьма действенна против порчи и неизвестных магических явлений."},{t="Исследование Красного кристалла",b="Колба была подготовлена специально для испытания огромного чужеродного красного кристалла, появившегося на восточном склоне Темных берегов. Поскольку над горной стеной нависают оскверненные высоты Оскверненного леса, исследователи опасались, что багровое образование имеет такое же темное происхождение. Когда благословенная вода стекает по граням кристалла, магия на время делает непрозрачный камень прозрачным, открывая гудящие тайны внутри."}},faq={{q="Откуда набирают воду?",a="Воду черпают прямо из священного лунного колодца в убежище ночных эльфов Аубердине, в самом сердце Темных берегов.",al={"where do i fill the tube","water tube source","auberdine moonwell water","где наполнить колбу","источник воды для колбы","вода лунного колодца аубердина"}},{q="Зачем лить воду из лунного колодца на красный кристалл?",a="Вода лунного колодца содержит сконцентрированную магию природы и луны. Если полить ею странный красный кристалл, можно проверить его магический состав: возникает эфирная реакция, и непрозрачная поверхность минерала на миг становится прозрачной.",al={"why moonwell water","purpose of the water tube","what does the water do","зачем вода лунного колодца","назначение колбы","что делает вода"}},{q="Почему исследователей беспокоит кристалл?",a="Кристалл находится прямо под восточными горами на границе с Оскверненным лесом. Учитывая глубокую демоническую скверну Оскверненного леса, ученые опасаются, что чужеродное образование может быть продолжением этой порчи, просачивающейся на Темные берега.",al={"why test the crystal","red crystal danger","felwood connection","зачем проверять кристалл","опасность красного кристалла","связь с оскверненным лесом"}}},fp="19,208,28.336.0,29.443.1,30.132.0,42.218.0,52.213.0"}
P.entries["item:mossy-tumor"] = {n="Мшистая опухоль",s="Мшистая опухоль — мерзкий ядовитый нарост, срезанный с коры и плоти оскверненных древней Тельдрассила. Эти наросты, встречающиеся главным образом возле Родникового озера, служат внешним признаком тревожной злобы, распространяющейся по молодому Мировому Древу.",h="Мшистая опухоль — мерзкий ядовитый нарост, срезанный с коры и плоти оскверненных древней Тельдрассила.",kw={"corruption","darnassus","mossy tumor","rellian greenspyre","teldrassil","timberling","wellspring lake","порча","дарнасс","мшистая опухоль","релиан зеленый костер","тельдрассил","древень","родниковое озеро"},ang={["class:Druid"]="Для друидов, преданных равновесию природы, вид стражей-растений, таких как древни, покрытых ядовитыми опухолями, — тревожный знак того, что с Тельдрассилом творится что-то неладное.",["race:NightElf"]="Ночные эльфы посадили Тельдрассил, чтобы восстановить утраченную связь с природой, поэтому быстрое появление больных наростов на их новом доме — тревожное предзнаменование."},sec={{t="Признак недуга Тельдрассила",b="Древни Тельдрассила были созданы, чтобы растить и беречь ветви великого дерева, но многие из них стали враждебными и больными. Мшистые опухоли — физическое проявление этой внутренней болезни. Насыщенные токсинами наросты вырастают на телах трясинных чудищ, топтунов и старших древней, бродящих у Родникового озера. Релиан Зеленый Костер и хранители в Дарнассе поручили путникам срезать опухоли, чтобы их можно было полностью сжечь и не дать яду глубже укорениться в почве острова."}},faq={{q="Что такое мшистая опухоль?",a="Это болезненный нарост, добытый с тел оскверненных древней. Наполненные мерзким ядом опухоли показывают, что духи природы Тельдрассила страдают от неестественной порчи.",al={"mossy tumor","what is this tumor","timberling tumor","мшистая опухоль","что за опухоль","опухоль древня"}},{q="Где найти мшистые опухоли?",a="Их собирают с оскверненных древней — топтунов, трясинных чудищ и старших древней, — бродящих возле Родникового озера на севере Тельдрассила.",al={"where to get tumors","mossy tumor drop","timberling location","где достать опухоли","мшистая опухоль добыча","где древни"}},{q="Зачем Релиану Зеленому Костру эти опухоли?",a="Релиан стремится сдержать порчу, поражающую Тельдрассил. Собирая опухоли и сжигая их дотла, он не дает сконцентрированному яду просочиться обратно в почву и воду.",al={"rellian greenspyre tumors","why burn tumors","релиан зеленый костер опухоли","зачем сжигать опухоли"}},{q="Почему древни заболевают?",a="Темная злоба начала охватывать Тельдрассил, искажая его хранителей и диких существ. Ночные эльфы активно ищут истинный источник недуга, но древни с заметными опухолями считаются безнадежными.",al={"why are timberlings sick","timberling corruption","почему древни больны","порча древней"}}},fp="11,263,33.546.0,22.203.0,31.170.0,46.197.0,42.255.0"}
P.entries["item:mountain-lion-blood"] = {n="Кровь горного льва",s="Кровь горного льва — реагент, который собирают с хищников Предгорий Хилсбрада и снежных склонов Альтерака. Аптекарь Лидон из Мельницы Таррен ищет свежую кровь для приготовления грозного Эликсира боли Королевского фармацевтического общества.",h="Кровь горного льва — реагент, который собирают с хищников Предгорий Хилсбрада и снежных склонов Альтерака.",kw={"alterac","apothecary lydon","elixir of pain","hillsbrad","mountain lion blood","royal apothecary society","tarren mill","альтерак","аптекарь лидон","эликсир боли","хилсбрад","кровь горного льва","королевское фармацевтическое общество","мельница таррен"},ang={["faction:Horde"]="Сбор звериных реагентов возле Мельницы Таррен напрямую укрепляет позиции Орды против враждебных людских поселений в Хилсбраде.",["race:Undead"]="Каждый собранный флакон помогает Королевскому фармацевтическому обществу создавать разрушительное биологическое оружие, чтобы закрепить Лордерон за Отрекшимися."},sec={{t="Реагент холмов",b="В нагорьях и предгорьях вокруг Хилсбрада и Альтерака рыщут дикие и голодные горные львы. Обычные охотники ценят этих хищников за шкуры и когти, а Отрекшиеся из Королевского фармацевтического общества ищут то, что течет в их жилах. Свежая кровь горного льва обладает особыми свойствами, и аптекарь Лидон из Мельницы Таррен считает, что она станет основой нового сильного ядовитого зелья, призванного нести страдания живым."},{t="Топливо для Новой чумы",b="Опыты аптекаря Лидона в Мельнице Таррен напрямую служат главной задаче Королевского фармацевтического общества — совершенствованию Новой чумы Отрекшихся. Собирая кровь сильных диких зверей, Лидон надеется довести до ума состав, который называет Эликсиром боли, и проверить, насколько действенным оружием против врагов Темной Госпожи могут стать местные органические соединения."}},faq={{q="Для чего нужна кровь горного льва?",a="Аптекарю Лидону в Мельнице Таррен нужно десять флаконов крови горного льва, чтобы перегнать смертоносное зелье — Эликсир боли, часть исследований Королевского фармацевтического общества в области новых болезней.",al={"what is mountain lion blood for","who needs lion blood","elixir of pain blood","для чего кровь горного льва","кому нужна кровь льва","кровь для эликсира боли"}},{q="Где можно собрать кровь горного льва?",a="Ее собирают с горных львов, охотящихся в Предгорьях Хилсбрада и в соседних снежных утесах Альтеракских гор.",al={"where to find mountain lion blood","mountain lion blood location","which lions drop blood","где найти кровь горного льва","кровь горного льва где","какие львы дают кровь"}},{q="Почему аптекарю Лидону нужна именно кровь диких кошек?",a="Лидон считает, что жизненные соки агрессивных и выносливых горных львов — идеальная биологическая основа для особенно мучительного ядовитого зелья, предназначенного для живых обитателей Хилсбрада.",al={"why lion blood","why does lydon want lion blood","зачем кровь льва","зачем лидону кровь льва"}},{q="Нужна ли кровь горного льва для рецептов алхимии?",a="Нет. Это исключительно экспериментальный исследовательский реагент, который собирают для личной работы аптекаря Лидона; он не входит в состав обычных алхимических рецептов.",al={"can alchemists use mountain lion blood","is lion blood for alchemy","могут ли алхимики использовать кровь горного льва","кровь льва для алхимии"}}},fp="19,253,20.474.0,22.370.0,37.200.0,43.139.0,59.206.0,59.158.0"}
P.entries["item:muddy-journal-pages"] = {n="Испачканные страницы записей",s="Эти потрепанные, испачканные землей листы были найдены много лет назад на месте жестокого убийства в Сумеречном лесу. Хозяин таверны Смиттс долго хранил их, не имея доказательств авторства, и они остаются ключевой уликой в нераскрытом местном расследовании.",h="Эти потрепанные, испачканные землей листы были найдены много лет назад на месте жестокого убийства в...",kw={"darkshire","ebonlocke","haggard","legend of stalvan","muddy journal pages","smitts","stalvan","темнолесье","чернодрев","хаггард","легенда о сталване","испачканные страницы записей","смиттс","сталван"},ang={["class:Rogue"]="Сопоставление забытых образцов почерка и истрепанных клочков дневника показывает, какая методичная криминалистическая работа нужна, прежде чем нанести удар по скрывающемуся убийце.",["faction:Alliance"]="Раскрытие тайны убийства дворян из Штормграда приносит давно ожидаемую развязку старому нераскрытому делу в осажденных поселениях Сумеречного леса."},sec={{t="Улики резни",b="За годы до нынешних бед в Сумеречном лесу свита знатных гостей была жестоко убита в глуши. Хозяин таверны Смиттс вместе с сыщиком Хаггардом пришел на залитое кровью место и вытащил из грязи эти испачканные страницы записей. Тогда в городе не было ни образцов почерка, ни подтвержденных записей, чтобы связать текст с каким-либо подозреваемым. Смиттс тихо хранил страницы в таверне Темнолесья, ожидая, пока сыщик соберет достаточно разрозненных записей по южным королевствам, чтобы сопоставить почерк с отшельником, живущим в глубине леса."}},faq={{q="Где были найдены испачканные страницы записей?",a="Их несколько лет назад нашли Хозяин таверны Смиттс и Хаггард на месте, где в чащах Сумеречного леса была убита семья приезжих дворян.",al={"where did smitts find the pages","origin of muddy pages","muddy journal location","где смиттс нашел страницы","происхождение испачканных страниц","где найдены страницы записей"}},{q="Почему Смиттс не мог использовать страницы, когда нашел их?",a="Хотя страницы были найдены на месте преступления, местные следователи не могли сверить почерк. Без подтвержденных образцов письма от прежних нанимателей Сталвана Мистмантла городская стража не могла доказать его вину.",al={"why keep the pages secret","why didn't smitts turn them in","smitts evidence problem","почему страницы скрывали","почему смиттс не сдал страницы","проблема улик смиттса"}},{q="Кому нужно показать эти страницы?",a="Их нужно принести прямо командиру Алтее Чернодрев, предводителю Ночного Дозора в Темнолесье, чтобы официально сообщить о завершении расследования убийств, связанных с Мистмантлом.",al={"who do i give the muddy pages to","turn in muddy journal pages","ebonlocke muddy pages","кому отдать испачканные страницы","сдать страницы записей","чернодрев страницы"}},{q="С каким преступлением связаны эти страницы?",a="Страницы связывают Сталвана Мистмантла с хладнокровной резней знатной семьи Лунный Плач, у которой Сталван служил наставником, прежде чем впал в безумие и одержимость.",al={"what massacre","what did stalvan do","visiting nobles slaughtered","какая резня","что сделал сталван","убитые дворяне"}}},fp="19,249,28.594.1,41.160.0,59.245.1,29.188.1,37.185.1"}
P.entries["item:mudsnout-blossom"] = {n="Цветок Грязного Рыла",kw={"apothecary lydon","elixir of agony","hillsbrad foothills","mudsnout blossom","mudsnout gnolls","nethander stead","tarren mill","аптекарь лидон","эликсир агонии","предгорья хилсбрада","цветок грязного рыла","гноллы грязного рыла","владение нетандера","мельница таррен"},ang={["profession:Herbalism"]="Хотя ботаники и травники могут принять его название за обычный цветок, цветок Грязного Рыла — это на самом деле нестабильный зловонный гриб, ценимый токсикологами и темными алхимиками."},sec={{t="Ядовитый гриб",b="Despite their floral name, Mudsnout Blossoms are actually large, foul-smelling mushrooms that flourish primarily in the soiled dirt of Nethander Stead, south of Tarren Mill. They grow amidst the camps of the local Mudsnout gnolls, who defend the territory fiercely. To living organisms, the spores and flesh of the mushroom act as a virulent poison, causing agony and rapid biological deterioration."},{t="Сырье для Королевского фармацевтического общества",b="В Мельнице Таррен аптекарь Лидон ищет цветки Грязного Рыла как сырье для своих химических опытов. По поручению леди Сильваны Ветрокрылой Королевское фармацевтическое общество неустанно трудится над созданием новой чумы, способной уничтожить и Плеть, и живое человечество. Едкие, иссушающие плоть свойства этих грибов делают их идеальной основой для зелья Лидона — печально известного Эликсира агонии."}},faq={{q="Что такое цветок Грязного Рыла?",a="Несмотря на название, это крупный едкий ядовитый гриб, растущий во влажной почве Предгорий Хилсбрада.",al={"mudsnout blossom lore","is mudsnout blossom a flower","what kind of plant is mudsnout blossom","цветок грязного рыла","цветок грязного рыла это цветок","что за растение цветок грязного рыла"}},{q="Где растут цветки Грязного Рыла?",a="Они растут по всему Владению Нетандера — заброшенной ферме к югу от Мельницы Таррен и к востоку от реки, текущей мимо Южнобережья. Эта местность кишит гноллами Грязного Рыла.",al={"mudsnout blossom location","where to find mudsnout blossoms","nethander stead mushrooms","цветок грязного рыла где растет","где найти цветки грязного рыла","грибы владения нетандера"}},{q="Зачем Королевское фармацевтическое общество их собирает?",a="Аптекарю Лидону в Мельнице Таррен они нужны для варки Эликсира агонии. Отрекшиеся изучают токсины, чтобы создать новую чуму, способную уничтожить и живых, и Плеть.",al={"why does lydon want mudsnout blossoms","elixir of agony ingredients","apothecary lydon mushroom","зачем лидону цветки грязного рыла","эликсир агонии ингредиенты","аптекарь лидон гриб"}},{q="What does the Royal Apothecary Society use the blossoms for?",a="Apothecary Lydon gathers the foul-smelling mushrooms for his next elixir, as part of the Forsaken's research into disease and poisons.",al={"mudsnout blossom experiments","mudsnout blossom elixir use"}}},fp="16,254,14.399.0,37.429.1,27.120.0,32.181.0,52.192.0,60.134.0"}
P.entries["item:mudsnout-composite"] = {n="Смесь Грязного Рыла",s="Смесь Грязного Рыла — алхимическая паста, которую аптекарь Лидон готовит в Мельнице Таррен из собранных цветков Грязного Рыла. Она служит важной основой, которую доставляют в Подгород для исследований Королевского фармацевтического общества над новой чумой.",h="Смесь Грязного Рыла — алхимическая паста, которую аптекарь Лидон готовит в Мельнице Таррен из собранных...",kw={"apothecarium","apothecary lydon","elixir of agony","master apothecary faranell","mudsnout blossom","mudsnout composite","royal apothecary society","апотекариум","аптекарь лидон","эликсир агонии","мастер аптекарь фаранелл","цветок грязного рыла","смесь грязного рыла","королевское фармацевтическое общество"},ang={["profession:Herbalism"]="Цветки Грязного Рыла доказывают, что даже скромную местную флору можно растереть и превратить в оружие под опытным взглядом аптекаря.",["race:Undead"]="Каждая такая партия смеси напрямую служит воле Темной Госпожи: обеспечить будущее Отрекшихся созданием чумы, способной уничтожить и живых, и Плеть."},sec={{t="Основа для распада",b="Эту тонкую смесь аптекарь Лидон готовит прямо на месте из цветков Грязного Рыла, собранных в Предгорьях Хилсбрада. Сама по себе она ядовита, но чтобы проявились ее смертоносные свойства, нужен особый коллоид распада, который составляет сам Мастер аптекарь Фаранелл. После соединения смесь становится ключевым химическим компонентом при создании Эликсира агонии Темной Госпожи."},{t="Переписка аптекарей",b="Доставка смеси из Мельницы Таррен в Апотекариум Подгорода отражает децентрализованный, поэтапный характер алхимии Отрекшихся. Полевые исследователи постоянно собирают местные реагенты и отправляют образцы мастерам в столицу для доработки. Хотя леди Сильвана требует поскорее получить результат против живых людей и Плети, Фаранелл называет смесь гениальной основой на пути к общей цели."}},faq={{q="Для чего нужна Смесь Грязного Рыла?",a="Это промежуточная паста из цветков Грязного Рыла. Мастер аптекарь Фаранелл в Подгороде должен обработать ее коллоидом распада, чтобы получить Эликсир агонии.",al={"mudsnout composite purpose","what does mudsnout composite do","смесь грязного рыла назначение","что делает смесь грязного рыла"}},{q="Кто создал смесь?",a="Аптекарь Лидон, исследователь из Отрекшихся, работающий в Мельнице Таррен в Предгорьях Хилсбрада, растер свежие цветки и приготовил пасту, прежде чем отправить ее на север.",al={"who made mudsnout composite","mudsnout composite creator","кто сделал смесь грязного рыла","создатель смеси грязного рыла"}},{q="Зачем она нужна Мастеру аптекарю Фаранеллу?",a="Фаранелл руководит великим трудом Королевского фармацевтического общества по созданию новой чумы. Смесь Лидона дает особую растительную основу, необходимую для продвижения исследований смертоносных токсинов.",al={"why bring it to faranell","faranell mudsnout","зачем нести фаранеллу","фаранелл грязное рыло"}}},fp="18,249,16.417.0,25.449.1,40.196.0,26.157.0,44.190.0"}
P.entries["item:mudsnout-mixture"] = {n="Микстура Грязного Рыла",s="Микстура Грязного Рыла — ядовитая алхимическая основа, которую составляет Мастер аптекарь Фаранелл в Подгороде. Ее получают, смешивая смесь Грязного Рыла с алхимическим коллоидом распада, и она служит основой смертоносного Эликсира агонии Королевского фармацевтического общества.",h="Микстура Грязного Рыла — ядовитая алхимическая основа, которую составляет Мастер аптекарь Фаранелл в...",kw={"apothecary","colloid of decay","elixir of agony","faranell","hillsbrad","lydon","mudsnout mixture","undercity","аптекарь","коллоид распада","эликсир агонии","фаранелл","хилсбрад","лидон","микстура грязного рыла","подгород"},ang={["faction:Horde"]="Авантюристы Орды, работающие в Мельнице Таррен, служат посыльными и полевыми агентами: они переносят ядовитые составы через Лордерон, закрепляя позиции Отрекшихся в Хилсбраде.",["race:Undead"]="Это зелье показывает безжалостную изобретательность Королевского фармацевтического общества, которое превращает простые природные ингредиенты в химическое оружие для истребления живых."},sec={{t="Коллоид распада",b="Когда аптекарь Лидон в Мельнице Таррен задумывает создать смертоносное биологическое оружие, он отправляет на север, в Подгород, основу из цветков Грязного Рыла — ядовитых грибов из Владения Нетандера, где хозяйничают гноллы. Впечатленный потенциалом смеси, Мастер аптекарь Фаранелл добавляет в нее собственный коллоид распада, получая нестабильную Микстуру Грязного Рыла. Раствор стабилизирует грибное соединение и готовит его смертоносные свойства к дальнейшей каталитической обработке в предгорьях."},{t="Катализ агонии",b="Хотя микстура Грязного Рыла сильна сама по себе, без ключевых катализаторов она инертна и не запускает свои заражающие компоненты. Фаранелл поручает посыльным вернуть флакон в Мельницу Таррен вместе с сильным эликсиром тролльей крови, ядовитой чешуей нага Пронзающего Гребня и глазами мурлоков Рваного Плавника. После катализа Лидоном эта микстура становится смертоносным Эликсиром агонии — фирменным ядом, призванным нести гибель живым врагам Отрекшихся."}},faq={{q="Для чего нужна Микстура Грязного Рыла?",a="Это промежуточная химическая основа Эликсира агонии — экспериментального яда, который аптекарь Лидон совершенствует в Мельнице Таррен, чтобы истреблять врагов Отрекшихся.",al={"mudsnout mixture purpose","what does mudsnout mixture do","mudsnout mixture use","микстура грязного рыла назначение","что делает микстура грязного рыла","применение микстуры грязного рыла"}},{q="Кто создает Микстуру Грязного Рыла?",a="Ее создает Мастер аптекарь Фаранелл, глава Королевского фармацевтического общества, живущий в Апотекариуме Подгорода: он насыщает необработанную смесь Грязного Рыла собственным коллоидом распада.",al={"who makes mudsnout mixture","mudsnout mixture creator","кто делает микстуру грязного рыла","создатель микстуры грязного рыла"}},{q="Почему для нее нужны компоненты гноллов?",a="Не нужны, несмотря на название. Смесь делают из цветков Грязного Рыла — ядовитых грибов, растущих во Владении Нетандера среди гноллов Грязного Рыла. Аптекарь Лидон превращает их в смесь, а затем Фаранелл добавляет свой коллоид распада.",al={"why mudsnout","gnoll poison lore","почему грязное рыло","яд гноллов предания"}},{q="Как активировать микстуру?",a="Чтобы пробудить дремлющие заражающие компоненты микстуры, аптекарю Лидону нужны сильный эликсир тролльей крови, а также чешуя нага Пронзающего Гребня и глаза мурлоков Рваного Плавника, добытые на побережье Хилсбрада.",al={"activate mudsnout mixture","elixir of agony reagents","активировать микстуру грязного рыла","реагенты эликсира агонии"}}},fp="16,266,18.511.0,20.436.1,38.184.0,33.196.0,37.235.0,29.216.0"}
P.entries["item:murloc-head"] = {n="Голова мурлока",s="Головы мурлоков — мрачные трофеи, отсеченные у земноводных тварей, рыщущих на Западном побережье в Предгорьях Хилсбрада. Лейтенант Фаррен Оринель из Южнобережья требует их как вещественное доказательство истребленной угрозы, чтобы удовлетворить своего начальника, маршала Редпата.",h="Головы мурлоков — мрачные трофеи, отсеченные у земноводных тварей, рыщущих на Западном побережье в Предгорьях...",kw={"farren orinelle","farren's proof","hillsbrad foothills","marshal redpath","murloc","murloc head","southshore","western strand","фаррен оринель","доказательство фаррена","предгорья хилсбрада","маршал редпат","мурлок","голова мурлока","южнобережье","западное побережье"},ang={["faction:Alliance"]="Зачистка Западного побережья защищает хрупкую рыболовную экономику Южнобережья и обеспечивает безопасность побережья для уязвимого оплота Альянса в Лордероне."},sec={{t="Более жуткое доказательство",b="Южнобережью угрожают опасности со всех сторон, но агрессивные мурлоки, скопившиеся на Западном побережье, — непосредственная угроза местным рыбакам и путникам на побережье. Хотя авантюристы Альянса часто прочесывают пляжи, истребляя тварей, маршал Маркус Редпат требует неопровержимого подтверждения, прежде чем подписывать отчеты об обороне. Чтобы потешить бюрократию, лейтенант Фаррен Оринель нанимает бойцов, которые приносят холодные, истекающие кровью головы мурлоков. Фаррену эта работа совершенно отвратительна, тем более что от такого зрелища у него пропал аппетит к местным морепродуктам Южнобережья."}},faq={{q="Почему Фаррену Оринелю нужны головы мурлоков?",a="Маршала Маркуса Редпата не удовлетворяли простые донесения об очистке пляжей от мурлоков. Чтобы убедиться, что угроза действительно уменьшилась, он потребовал вещественных доказательств, и лейтенанту Фаррену пришлось собирать отсеченные головы.",al={"farren proof","why murloc heads","who wants murloc heads in southshore","доказательство фаррена","зачем головы мурлоков","кто хочет головы мурлоков в южнобережье"}},{q="Где обитают эти мурлоки?",a="Их добывают у племен мурлоков, заполонивших Западное побережье — береговую линию к западу от Южнобережья в Предгорьях Хилсбрада.",al={"murloc head location","where to get murloc heads hillsbrad","western strand murlocs","голова мурлока где взять","где достать головы мурлоков хилсбрад","мурлоки западного побережья"}},{q="Почему Фаррену они так противны?",a="Фаррен считает ходячих рыб неестественными и тошнотворными. Вид склизких, кровоточащих отсеченных голов, капающих на пол, вызывает у него такое отвращение, что он отказывается есть рыбу — основу рациона в портовом городе вроде Южнобережья.",al={"farren reaction","farren eating fish","реакция фаррена","фаррен не ест рыбу"}},{q="Решает ли сбор голов проблему мурлоков Южнобережья?",a="Головы служат доказательством, которое просил маршал Редпат. Он принимает их и затем велит Фаррену обратить внимание на угрозы на Восточном побережье.",al={"do murlocs stop attacking","farren quest chain","прекратят ли мурлоки нападать","цепочка заданий фаррена"}}},fp="11,253,24.630.0,43.239.0,30.138.0,35.248.0,60.158.0"}
P.entries["item:musquash-root"] = {n="Мускусный корень",s="Мускусный корень — редкое растение, которое растет только во влажной почве под огромными водопадами Каменной Плотины в Болотине. Он служит важным компонентом зелья, которое варят культисты, скрывающиеся под Штормградом.",h="Мускусный корень — редкое растение, которое растет только во влажной почве под огромными водопадами Каменной...",kw={"a noble brew","lord wishock","musquash root","stonewrought dam","tear of tilloa","wetlands","zardeth","благородное зелье","лорд вишлок","мускусный корень","каменная плотина","слеза тиллоа","болотина","зардет"},ang={["class:Warlock"]="Для чернокнижников, действующих под Забитым ягненком, добыча этого корня необходима, чтобы заставить замолчать любопытных дворян и защитить свое хрупкое убежище в городе.",["profession:Herbalism"]="Хотя это не обычная торговая трава, корень показывает, как особые микроклиматы, например у подножия Каменной Плотины, могут порождать уникальную и опасную флору."},sec={{t="Редкий ингредиент",b="Мускусный корень процветает в вечно пропитанной туманом земле, куда обрушивается каскад Каменной Плотины в Болотине. Из-за уединенного и сырого места произрастания собрать его чрезвычайно трудно. Обычные травники редко ищут его, но некоторые приверженцы темных искусств ценят корень за сильные химические и алхимические свойства."},{t="Замысел чернокнижника",b="Под улицами Штормграда, в сумрачных трущобах, известных как Забитый ягненок, Зардет Черный Коготь ищет этот корень вместе со Слезой Тиллоа. Вместе эти редкие растения составляют основу тонкого зелья, призванного обезвредить лорда Вишлока, члена Дома знати, который начал совать нос в тайный круг чернокнижников города."}},faq={{q="Где найти Мускусный корень?",a="Мускусный корень растет только в Болотине, у самого подножия больших водопадов под Каменной Плотиной.",al={"where is musquash root","musquash root location","how to find musquash root","где мускусный корень","мускусный корень местонахождение","как найти мускусный корень"}},{q="Для чего нужен Мускусный корень?",a="Зардет Черный Коготь просит его вместе со Слезой Тиллоа для зелья, которое должно отвлечь лорда Вишлока и остановить его попытки добиться расследования в отношении шабаша чернокнижников Штормграда.",al={"what does musquash root do","musquash root purpose","why do i need musquash root","что делает мускусный корень","мускусный корень назначение","зачем мне мускусный корень"}},{q="Кто хочет, чтобы этот корень собрали?",a="Зардет Черный Коготь, чернокнижник, живущий в катакомбах под Забитым ягненком в Квартале магов Штормграда, посылает агентов за ним.",al={"who needs musquash root","musquash root quest giver","who asks for musquash root","кому нужен мускусный корень","мускусный корень персонаж, выдающий задание","кто просит мускусный корень"}},{q="Кто такой лорд Вишлок?",a="Лорд Вишлок — член Дома знати Штормграда, узнавший о круге чернокнижников, действующем в городе, и начавший добиваться у совета официального расследования.",al={"who is wishock","lord wishock","кто такой вишлок","лорд вишлок"}}},fp="13,234,17.354.0,20.367.1,29.122.0,31.190.0,30.151.0,20.176.0"}
P.entries["item:mysterious-fossil"] = {n="Таинственная окаменелость",s="Таинственная окаменелость — древний образец, найденный на побережье Темных берегов геологом Сомнамбулером. Ее необычные свойства вызвали живой интерес у дворфийской Лиги исследователей, и ученые решили переправить находку через море, чтобы раскрыть ее тайны.",h="Таинственная окаменелость — древний образец, найденный на побережье Темных берегов геологом Сомнамбулером.",ang={["faction:Alliance"]="Передача реликвии показывает, насколько важна цепочка снабжения, связывающая форпосты Альянса: от разведчиков на Темных берегах до ученых в Дарнассе и Гавани Менетилов.",["race:Dwarf"]="Для дворфов эта окаменелость — еще один недостающий фрагмент в поисках Лиги исследователей, стремящейся собрать воедино наследие древних титанов и раскрыть забытые тайны."},sec={{t="Любопытная находка",b="While conducting fieldwork among the wild shores of Darkshore, Prospector Remtravel uncovered a fossil unlike the common petrified stone scattered across Kalimdor. Deeming it of monumental historical importance, Remtravel arranged for the specimen to be delivered to dwarven scholars rather than let it languish in the wilderness. When brought before Chief Archaeologist Greywhisker in Darnassus, the relic immediately stood out as an extraordinary find."},{t="Связи за океаном",b="Главный археолог Седоус заметил, что образец удивительно похож на другую редкую окаменелость, которую когда-то показывали на собрании Лиги исследователей в Стальгорне. Ту находку изучал археолог Бутылопуз, который подозревал, что в камне скрыта дремлющая сила, ожидающая пробуждения. Чтобы подтвердить происхождение находки и раскрыть ее тайны, Седоус поручил курьерам доставить окаменелость через океан Бутылопузу, который ждет отправки в таверне «Большая вода» в Гавани Менетилов."}},faq={{q="Где была найдена Таинственная окаменелость?",a="The fossil was discovered in Darkshore by Prospector Remtravel during his fieldwork along the ancient northern coastline of Kalimdor.",al={"fossil location","where is it found","origin of fossil","место находки окаменелости","где ее найти","происхождение окаменелости"}},{q="Почему Лиге исследователей нужна эта окаменелость?",a="Лига исследователей занимается изучением древних артефактов и происхождения мира. Главный археолог Седоус полагает, что этот образец связан с исследованиями археолога Бутылопуза, который предполагал, что такие окаменелости могут хранить скрытую силу.",al={"why do dwarves want it","explorers league interest","what does the fossil do","зачем она дворфам","интерес лиги исследователей","что делает окаменелость"}},{q="Кто такой археолог Бутылопуз?",a="Археолог Бутылопуз — исследователь Лиги исследователей. Он известен изучением подобных окаменевших реликвий и сейчас остановился в таверне «Большая вода» в Гавани Менетилов, ожидая сопровождения к Раскопкам Вельгара в Болотине.",al={"who is flagongut","flagongut location","where is flagongut","кто такой бутылопуз","где бутылопуз","местонахождение бутылопуза"}},{q="Кто такой главный археолог Седоус?",a="Главный археолог Седоус — старший представитель Лиги исследователей в Дарнассе. Он руководит дворфийскими исследованиями и археологическими работами на севере Калимдора.",al={"greywhisker","who is greywhisker","darnassus dwarf archaeologist","седоус","кто такой седоус","дворф археолог в дарнассе"}}},fp="17,282,19.454.0,21.507.1,38.133.0,48.268.0,31.248.0,39.190.0"}
P.entries["item:nak-s-skull"] = {n="Череп Нака",s="Череп Нака — жуткий охотничий трофей, снятый с Нака, одного из трех видных командиров свинобразов-Иглогривых, которые руководят отрядами на юге Степей. Его взяли как доказательство победы над налетчиком, и его добивается пленный свинобраз Кривозуб, желающий отомстить за горькое предательство соплеменников.",h="Череп Нака — жуткий охотничий трофей, снятый с Нака, одного из трех видных командиров свинобразов-Иглогривых...",kw={"barrens","betrayal from within","camp taurajo","kuz","lok orcbane","mangletooth","nak","nak's skull","quilboar","razormane","степи","предательство изнутри","лагерь таурахо","каз","лок губитель орков","кривозуб","нак","череп нака","свинобраз","иглогривые"},ang={["faction:Horde"]="Головы военачальников Иглогривых, таких как Нак, заметно ослабляют давление на линии снабжения Орды между Лагерем Таурахо и Перекрестком."},sec={{t="Знак мести",b="Выйдя из Лабиринтов Иглошкурых, трое — Нак, Каз и Лок Губитель Орков — начали жестокие набеги на поселения и дороги Орды в Степях. Защитники Перекрестка не знали, что эти военачальники затевали нападения гораздо хитрее обычных племенных стычек. Когда пленного Иглогривого Кривозуба бросили умирать в клетке в Лагере Таурахо, его жажда возмездия обратилась против бывших собратьев. Требуя вещественных доказательств гибели Нака, Кривозуб просит авантюристов Орды принести его череп вместе с черепами его сообщников, чтобы сломить южные отряды налетчиков."}},faq={{q="Кем был Нак?",a="Нак был хитрым вожаком свинобразов-Иглогривых, вышедшим из Лабиринтов Иглошкурых вместе с Казом и Локом Губителем Орков. Втроем они руководили смертоносными стычками и набегами на путников и поселения Орды на юге Степей.",al={"who is nak","nak lore","nak barrens","кто такой нак","предания о наке","нак степи"}},{q="Кому нужен Череп Нака?",a="Череп требует Кривозуб, пленный свинобраз-Иглогривый, которого держат в деревянной клетке в Лагере Таурахо. Озлобленный тем, что соплеменники бросили его на произвол судьбы, Кривозуб жаждет кровавой мести вожакам, предавшим его.",al={"who wants the skull","who do i give naks skull to","mangletooth skull","кому нужен череп","кому отдать череп нака","череп кривозуб"}},{q="Почему Кривозуб хочет получить черепа своих сородичей?",a="Нак, Каз и Лок Губитель Орков отвернулись от Кривозуба и оставили его умирать в плену. В отместку за предательство Кривозуб помогает Орде: он выдает их местонахождение и требует их отрубленные головы как доказательство их гибели.",al={"why betray his tribe","mangletooth motive","why does mangletooth want skulls","почему предал свое племя","мотив кривозуба","зачем кривозубу черепа"}},{q="Поможет ли Череп Нака защитить Перекресток?",a="Да. По словам Кривозуба, Нак и его соратники были хитрыми умами, стоявшими за агрессивными набегами Иглогривых на Перекресток и центральные торговые пути. Их уничтожение наносит сокрушительный удар по согласованным действиям племени.",al={"crossroads safe","stop quilboar raids","перекресток в безопасности","остановить набеги свинобразов"}}},fp="11,277,20.637.0,12.236.0,22.237.0,55.251.0,56.248.0"}
P.entries["item:nek-rosh-s-head"] = {n="Голова Некроша",s="Голова Некроша — жуткое доказательство гибели вождя Нек'роша, предводителя клана Драконьей Пасти в Болотине. Добытый авантюристами Альянса трофей относят капитану Крепкому Кулаку, чтобы подтвердить, что орочья угроза Гавани Менетилов уничтожена.",h="Голова Некроша — жуткое доказательство гибели вождя Нек'роша, предводителя клана Драконьей Пасти в Болотине.",kw={"captain stoutfist","chieftain","dragonmaw","menethil","nek'rosh","nekrosh","wetlands","капитан крепкий кулак","вождь","драконья пасть","менетил","нек'рош","некрош","болотина"},ang={["faction:Alliance"]="Вручив этот мрачный трофей капитану Крепкому Кулаку, вы убережете Гавань Менетилов от неминуемого нападения и заслужите большое расположение королевства Стальгорна.",["race:Dwarf"]="Клан Драконьей Пасти терзает Каз Модан со времен Второй войны; отрубленная голова вождя несет защитникам болот долгожданное возмездие."},sec={{t="Решающий удар",b="Клан Драконьей Пасти постоянно угрожает болотам: он стягивает войска и осадные орудия к порту Альянса — Гавани Менетилов. После сожжения их катапульт оборона порта зависит от убийства самого вождя Нек'роша. Его отрубленная голова станет бесспорным доказательством для капитана Крепкого Кулака и властей Стальгорна, что власть военачальника над Болотиной сломлена."}},faq={{q="Кем был Нек'рош?",a="Нек'рош был вождем остатков клана Драконьей Пасти в Болотине и организовывал нападения и военные действия против соседних земель Альянса.",al={"who is nek'rosh","chieftain nek'rosh","who was nekrosh","кто такой нек'рош","вождь нек'рош","кто был некрош"}},{q="Кому нужна Голова Некроша?",a="Капитан Крепкий Кулак, командующий обороной Гавани Менетилов, требует голову как вещественное доказательство гибели вождя, прежде чем наградить героя от имени Стальгорна.",al={"who takes the head","nekrosh head turn in","where do i bring nek'rosh's head","кто принимает голову","сдать голову некроша","куда нести голову нек'роша"}},{q="Почему Нек'роша решили убить?",a="Нек'рош командовал силами Драконьей Пасти, угрожавшими Гавани Менетилов. Уничтожив их осадные орудия и убив вождя, Альянс стремился нанести клану сокрушительный удар в этом регионе.",al={"why kill nekrosh","why defeat nek'rosh","зачем убивать некроша","зачем побеждать нек'роша"}}},fp="15,281,17.395.0,17.175.0,26.198.0,36.220.0"}
P.entries["item:nessa-s-collection"] = {n="Коллекция Нессы",s="Коллекция Нессы — пакет с рыбьими костями и чешуей, собранными в водах у Деревни Рут'теран. Подготовленная для изучения торговцем рыбой Лайрдом в Аубердине, она показывает необычайно крупные размеры морских обитателей вокруг корней Тельдрассила.",h="Коллекция Нессы — пакет с рыбьими костями и чешуей, собранными в водах у Деревни Рут'теран.",kw={"auberdine","fish bones","laird","nessa shadowsong","nessa's collection","rut'theran village","teldrassil","vesprystus","аубердин","рыбьи кости","лайрд","несса песня теней","коллекция нессы","деревня рут'теран","тельдрассил","весприст"},ang={["race:NightElf"]="Коллекция впервые показывает ночным эльфам необычайную силу вод вокруг Тельдрассила, когда они переселяются с родного острова на материк."},sec={{t="Дары Мирового Древа",b="Несса Песня Теней, рыбачка из Деревни Рут'теран у подножия Тельдрассила, собрала рыбьи кости и чешую, чтобы сравнить морскую жизнь острова с морской жизнью материка Калимдора. Воды, омывающие Великое Древо, дают невероятно крупный улов, и Несса решила отправить вещественное доказательство через море Лайрду, торговцу рыбой на причалах Аубердина. Посылку передают через укротителя гиппогрифов деревни, Весприста, и она служит практическим свидетельством растущей жизненной силы Тельдрассила."},{t="Любопытное сравнение",b="Осмотрев содержимое на Темных берегах, Лайрд обнаруживает, что образцы намного крупнее материковых. В коллекции есть челюсти почти вдвое больше, чем у рыб, обитающих у берегов Темных берегов, и отдельные чешуйки размером со сжатый кулак. Для прибрежных ночных эльфов эта посылка ясно показывает, насколько воды вокруг Тельдрассила отличаются от мрачных берегов севера Калимдора."}},faq={{q="Что внутри Коллекции Нессы?",a="Коллекция состоит из рыбьих костей, огромных челюстей и чешуи размером с кулак от рыбы, пойманной в водах у Деревни Рут'теран.",al={"nessas collection contents","what is in the package","fish bones parcel","содержимое коллекции нессы","что в посылке","посылка с рыбьими костями"}},{q="Кому отправляют коллекцию?",a="Ее отправляют Лайрду, торговцу рыбой из числа ночных эльфов, который живет в портовой деревне Аубердин на побережье Темных берегов.",al={"who gets nessas collection","who is laird","delivery destination","кто получает коллекцию нессы","кто такой лайрд","место доставки"}},{q="Зачем Несса собрала эти образцы рыбы?",a="Несса хотела сравнить необычайно крупную рыбу, обитающую вокруг Тельдрассила, с морской жизнью материкового Калимдора.",al={"why send fish bones","nessa fish comparison","bounty of teldrassil reason","зачем отправлять рыбьи кости","сравнение рыбы нессы","причина даров тельдрассила"}},{q="Как коллекция попадает в Аубердин?",a="Путник относит посылку укротителю гиппогрифов Рут'терана, Веспристу, который организует переправу через воду в Аубердин, чтобы посылку можно было доставить Лайрду.",al={"how is it delivered","vesprystus delivery","hippogryph parcel","как доставить","доставка весприста","посылка на гиппогрифе"}}},fp="18,266,24.555.0,20.434.0,34.145.0,36.113.0,42.128.0,40.169.0"}
P.entries["item:nether-gem"] = {n="Самоцвет Пустоты",s="Самоцвет Пустоты — зачарованный магический камень, доверенный отшельником-некромантом Гюнтером Чародеем. Наделенный магической силой, он служит каналом дальней связи: с его помощью Гюнтер создает чародейскую проекцию и напрямую общается со своим старым соратником Бетором Ледострелом в Подгороде.",h="Самоцвет Пустоты — зачарованный магический камень, доверенный отшельником-некромантом Гюнтером Чародеем.",kw={"bethor iceshard","brightwater lake","gunther arcanus","nether gem","prodigal lich","undercity","бетор ледострел","озеро ясноводное","гюнтер чародей","самоцвет пустоты","блудный лич","подгород"},ang={["class:Mage"]="Для чародеев тайных искусств Самоцвет Пустоты показывает, как великие маги преодолевают огромные расстояния с помощью магического наблюдения и проецируемых образов, не рискуя путешествием.",["race:Undead"]="Доставка камня становится крупной дипломатической победой Отрекшихся: могущественный Гюнтер Чародей получает статус союзника против Плети и Алого ордена."},sec={{t="Канал магического общения",b="Самоцвет Пустоты, созданный или зачарованный Гюнтером Чародеем на его уединенном острове на Озере Ясноводном, служит мистической связью через Тирисфальские леса. Гюнтер освободился от власти Короля-лича силой собственной воли и долго избегал молодого народа Отрекшихся из подозрительности. Получив свою утерянную книгу заклинаний, он в знак доброй воли доверяет самоцвет посланнику. Когда камень приносят Бетору Ледострелу на вершину Магического квартала в Подгороде, он направляет магический облик Гюнтера прямо к главе гильдии магов, открывая одинокому магу путь к союзу с леди Сильваной и Отрекшимися."}},faq={{q="Что делает Самоцвет Пустоты?",a="Самоцвет Пустоты позволяет Гюнтеру Чародею общаться на большом расстоянии с Бетором Ледострелом. Когда Бетор направляет магию в камень в Подгороде, тот проецирует призрачный облик Гюнтера, и два могущественных мага могут говорить напрямую.",al={"nether gem purpose","what is nether gem","what does nether gem do","назначение самоцвета пустоты","что такое самоцвет пустоты","что делает самоцвет пустоты"}},{q="Кто создал Самоцвет Пустоты?",a="Самоцвет дает Гюнтер Чародей, могущественный некромант, живущий на острове на Озере Ясноводном. Он поручает искателю приключений доставить его старому товарищу Бетору после возвращения своей утерянной книги заклинаний.",al={"who made nether gem","where does nether gem come from","gunther gem","кто сделал самоцвет пустоты","откуда самоцвет пустоты","самоцвет гюнтера"}},{q="Почему Самоцвет Пустоты важен для Отрекшихся?",a="Он становится инструментом, который приводит Гюнтера Чародея в ряды Отрекшихся. Гюнтер изначально не доверял другой нежити, опасаясь, что она все еще служит Плети; самоцвет позволяет ему вновь связаться с Бетором Ледострелом и присягнуть на верность леди Сильване.",al={"why is nether gem important","gunther forsaken","forsaken nether gem","почему важен самоцвет пустоты","гюнтер отрекшиеся","отрекшиеся самоцвет пустоты"}}},fp="10,295,29.636.0,28.250.0,27.218.0,50.288.1"}
P.entries["item:ng-5"] = {n="NG-5",s="NG-5 — краткое обозначение нитромирглицерония, печально известного нестабильного химического соединения. Его добывают для гнома-изобретателя Гаксима Ржавошиппи в Когтистых горах, где оно служит главным катализатором его взрывных инженерных замыслов.",h="NG-5 — краткое обозначение нитромирглицерония, печально известного нестабильного химического соединения.",kw={"dynamite","explosives","gaxim rustfizzle","gnome","ng-5","ng5","nitromirglyceronium","stonetalon","динамит","взрывчатка","гаксим ржавошиппи","гном","нитромирглицероний","когтистые горы"},ang={["profession:Engineering"]="Инженеры узнают в NG-5 нитромирглицероний — капризный химический катализатор, ценимый механиками, когда обычному черному пороху не хватает силы, чтобы воспламенить тяжелые боеприпасы.",["race:Gnome"]="Взрывать целые повозки с динамитом ради простого отвлечения с помощью нестабильного раствора — классический рискованный гномий подход к решению проблем."},sec={{t="Нестабильный реагент",b="NG-5, официально называемый нитромирглицеронием, — крайне опасный химический раствор, с которым обращаются только с предельной осторожностью или с безрассудным гномьим энтузиазмом. Гаксиму Ржавошиппи, действующему в Когтистых горах, это вещество нужно как важнейший воспламенитель. По словам Гаксима, NG-5 дает точную реакцию, необходимую, чтобы взорвать целые повозки с динамитом и устроить мощный взрыв, который отвлечет его противников в этом районе."}},faq={{q="Что такое NG-5?",a="NG-5 — это нитромирглицероний, крайне нестабильная и летучая химическая смесь, которую в основном используют как взрывной воспламеняющий реагент в сложных подрывных работах и гномьей инженерии.",al={"what is ng5","what is nitromirglyceronium","ng 5 item","что такое ng5","что такое нитромирглицероний","предмет ng-5"}},{q="Кому нужен NG-5 и зачем?",a="Это вещество нужно гному-инженеру Гаксиму Ржавошиппи в Когтистых горах. Оно необходимо, чтобы надежно поджечь несколько повозок, набитых динамитом, для эффектного отвлекающего маневра.",al={"who needs ng-5","gaxim rustfizzle ng-5","why get ng5","кому нужен ng-5","гаксим ржавошиппи ng-5","зачем доставать ng5"}},{q="Опасно ли обращаться с NG-5?",a="Крайне опасно. Поставщик предупреждает курьеров обращаться с соединением с предельной осторожностью и в шутку замечает, что любой, кто не союзник Гаксима, скорее всего, взорвет сам себя на куски.",al={"is ng5 safe","ng-5 explosive","will ng5 blow up","безопасен ли ng5","ng-5 взрывчатка","взорвется ли ng5"}}},fp="4,253,18.509.0,13.183.0,23.224.0,28.187.0"}
P.entries["item:nida-s-necklace"] = {n="Ожерелье Ниды",s="Ожерелье Ниды — дорогая сердцу память из детства, потерянная под водой Озера Безмолвия в Красногорье. Подаренная юной Ниде отцом безделушка соскользнула в мутную воду, когда дети Приозерья ловили рыбу на причалах.",h="Ожерелье Ниды — дорогая сердцу память из детства, потерянная под водой Озера Безмолвия в Красногорье.",kw={"effsee","glinting mud","lake everstill","lakeshire","nida","nida's necklace","redridge","shawn","эффси","поблескивающий ил","озеро безмолвия","приозерье","нида","ожерелье ниды","красногорье","шоун"},ang={["faction:Alliance"]="Защитники Приозерья едва справляются с окружающими угрозами, и небольшие добрые дела, такие как помощь местным детям вернуть потерянные памятные вещи, остаются странствующим искателям приключений Альянса."},sec={{t="Потеряно в глубине",b="Ловя рыбу у берега Приозерья вместе с другом Шоуном, юная Нида случайно уронила любимое ожерелье в Озеро Безмолвия. Эта семейная ценность дорога ей как подарок отца. Страх перед свирепыми зверями и агрессивными мурлоками, обитающими в глубине, удерживает местных детей на причалах, и ожерелье остается лежать в иле на дне, пока искатель приключений не решится нырнуть в мутную воду и достать его."}},faq={{q="Кому принадлежит это ожерелье?",a="Ожерелье принадлежит Ниде, маленькой девочке из городка Приозерье в Красногорье. Это был особый подарок от ее отца.",al={"who owns the necklace","nida necklace owner","whose necklace is this","чье ожерелье","владелец ожерелья ниды","чье это ожерелье"}},{q="Как ожерелье оказалось в Озере Безмолвия?",a="Нида проводила день за рыбалкой у воды со своим другом Шоуном, когда ожерелье соскользнуло и утонуло, упав на дно в кучу поблескивающего ила.",al={"how did it get in the lake","why is necklace in water","how was necklace lost","как оно попало в озеро","почему ожерелье в воде","как потеряли ожерелье"}},{q="Почему дети не нырнули, чтобы достать его?",a="Родители строго запрещают им плавать в Озере Безмолвия. В глубоких водах обитают опасные водные хищники и агрессивные мурлоки, которые смертельно опасны для местных жителей.",al={"why didn't nida swim for it","why can't shawn get the necklace","почему нида не нырнула","почему шоун не достанет ожерелье"}},{q="Кто такая Эффси?",a="Эффси — домашняя кошка Ниды, которая не отходит от нее в Приозерье и радостно встречает возвращение ожерелья вместе с юной хозяйкой.",al={"who is the kitty","nida cat","кто такая кошка","кошка ниды"}}},fp="15,262,18.485.0,33.154.0,46.169.0,47.193.0,14.130.0"}
P.entries["item:nightmare-shard"] = {n="Кошмарный осколок",s="Кошмарный осколок — кристаллическая реликвия, которую Фолла Ветер Мудрости вручает посыльным после изучения оскверненного светящегося осколка, найденного в Пещерах Стенаний. Содержащий чистую, но потревоженную сущность Изумрудного Сна, он несет тревожное видение, из-за которого старшие друиды Дарнасса и Громового Утеса немедленно предупреждают остальных и требуют хранить тайну.",h="Кошмарный осколок — кристаллическая реликвия, которую Фолла Ветер Мудрости вручает посыльным после изучения...",kw={"emerald dream","falla sagewind","glowing shard","hamuul runetotem","in nightmares","mathrengyl bearwalker","nightmare shard","wailing caverns","изумрудный сон","фолла ветер мудрости","светящийся осколок","хамуул рунический тотем","в кошмарах","матренгил медвежья лапа","кошмарный осколок","пещеры стенаний"},ang={["class:Druid"]="Для друидов осколок — леденящее открытие: их священное убежище, Изумрудный Сон, больше не защищено от порчи, что подтверждает опасения за судьбу Наралекса в Пещерах Стенаний.",["faction:Horde"]="Осколок приносит мрачные вести прямо на Вершину Старейшин в Громовом Утесе, где Хамуул Рунический Тотем стремится закрепить место тауренов в более широком братстве Кенария."},sec={{t="Оскверненное видение",b="Осмотрев таинственный светящийся осколок, найденный в глубине Пещер Стенаний, Фолла Ветер Мудрости понимает, что его энергия куда мрачнее, чем она ожидала. Вместо безмятежной жизненной силы Изумрудного Сна осколок отражает извращенную, неестественную порчу — наяву увиденный кошмар. Опасаясь того, что это значит, она заключает оскверненную сущность в Кошмарный осколок и велит без промедления доставить его старейшинам Круга Кенария."},{t="Приглушенные предзнаменования",b="Когда осколок доставляют верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин или Матренгилу Медвежьей Лапе в Дарнассе, оба наставника в оцепенении и тревоге заглядывают в его глубину. Видение внутри потрясает их выдержку и подтверждает их тихие опасения, что в самом Сне случилось нечто ужасное. Не желая сеять панику среди людей, друиды быстро забирают осколок и просят посыльного больше не говорить о том, что он увидел."}},faq={{q="Что такое Кошмарный осколок?",a="Это осколок, который Фолла Ветер Мудрости доверяет искателям приключений; он содержит плененную сущность Изумрудного Сна и происходит от артефакта, вынесенного из Пещер Стенаний. Вместо мирных сил природы он излучает мрачное, порочное видение сна.",al={"what is nightmare shard","nightmare shard lore","что такое кошмарный осколок","предание кошмарного осколка"}},{q="Кто создал Кошмарный осколок?",a="Фолла Ветер Мудрости передает осколок посыльному после изучения светящегося фрагмента из Пещер Стенаний. Осознав серьезность и порочность его природы, она поручает посыльному доставить его прямо старшим друидам для изучения.",al={"who made the nightmare shard","where does the shard come from","кто создал кошмарный осколок","откуда осколок"}},{q="Почему предводители друидов так встревожены?",a="Заглянув в осколок, Хамуул Рунический Тотем и Матренгил Медвежья Лапа видят, что Изумрудный Сон активно искажается кошмаром. Из-за опасности и возможной паники оба старейшины тут же прекращают разговоры и держат дело в тайне среди старших членов Круга Кенария.",al={"why is hamuul worried","why does mathrengyl hide the shard","почему хамуул встревожен","почему матренгил прячет осколок"}},{q="Куда нужно доставить осколок?",a="Искателям приключений Орды велено доставить его верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин в Громовом Утесе, а путники Альянса несут его Матренгилу Медвежьей Лапе в Круг Кенария в Дарнассе.",al={"who do i bring the shard to","nightmare shard turn in","кому нести осколок","сдать кошмарный осколок"}}},fp="15,344,18.487.0,12.467.1,28.253.0,32.245.0,43.337.1,42.208.0"}
P.entries["item:nightsaber-fang"] = {n="Клык ночного саблезуба",s="Острый зуб, добытый у хищных ночных саблезубов, бродящих по диким ветвям Тельдрассила. Это обычный охотничий трофей, но клыки также ищут как сырые реагенты местные лесные обитатели с сомнительными намерениями.",h="Острый зуб, добытый у хищных ночных саблезубов, бродящих по диким ветвям Тельдрассила.",kw={"dolanaar","fang","nightsaber","reagent","satyr","teldrassil","zenn foulhoof","доланаар","клык","ночной саблезуб","реагент","сатир","тельдрассил","зенн грязное копыто"},ang={["class:Hunter"]="Убить ночного саблезуба и взять его клык — доказательство базового мастерства в дикой природе, но поставка звериных частей оскверненным лесным духам искажает дух охоты.",["race:NightElf"]="Ночные саблезубы — любимые спутники и символы богини Элуны, поэтому охота на этих священных хищников ради коварного сатира глубоко постыдна."},sec={{t="Охотничий трофей",b="Ночные саблезубы — одни из самых смертоносных природных хищников северного Калимдора; ночные эльфы почитают их за ловкость, свирепость и глубокую духовную связь с Элуной. На огромных ветвях Тельдрассила эти кошачьи звери охотятся в тени под кроной. Убив одного, охотник получает острые клыки — неоспоримое доказательство мастерства, хотя некоторые сомнительные личности в лесу ищут их для менее благородных ритуалов."},{t="Реагент сатира",b="Возле поселения Доланаар скрывается Зенн Грязное Копыто, коварный сатир, охотящийся на доверчивых и неопытных путников. Заявляя, что ему нужны лесные реагенты, Зенн уговаривает начинающих искателей приключений собирать клыки ночных саблезубов, перья совиных и паучий шелк. Передавая такие хищные реагенты, герой прямо помогает обманщику, который при получении открыто насмехается над наивным простаком."}},faq={{q="Откуда берутся клыки ночного саблезуба?",a="Клыки ночного саблезуба добывают у хищных ночных саблезубов, бродящих по дебрям Тельдрассила, особенно в лесу вокруг Доланаара.",al={"where to get nightsaber fangs","who drops nightsaber fangs","nightsaber fang source","где взять клыки ночного саблезуба","с кого падают клыки саблезуба","источник клыков саблезуба"}},{q="Кому в Тельдрассиле нужны клыки ночного саблезуба?",a="Зенн Грязное Копыто, сатир, околачивающийся у главной дороги недалеко от Доланаара, просит их в рамках задания, которое он дает странствующим искателям приключений.",al={"who needs nightsaber fangs","nightsaber fang turn in","who buys nightsaber fangs","кому нужны клыки саблезуба","сдать клыки саблезуба","кто покупает клыки саблезуба"}},{q="Зачем Зенну Грязному Копыту клыки ночного саблезуба?",a="Зенн утверждает, что ему нужны животные реагенты для дел в лесу, но точный характер своей работы держит в секрете и с удовольствием обманывает легковерных путников, заставляя их служить себе.",al={"why zenn wants fangs","zenn foulhoof reagent purpose","zenn bidding motive","зачем зенну клыки","зенн грязное копыто реагент","мотив зенна"}},{q="Какие еще реагенты Зенн просит вместе с клыками?",a="Помимо двух клыков ночного саблезуба, Зенн требует два пера совы и два отреза паучьего шелка чащобных тенетников.",al={"what else does zenn need","zenn bidding items","other reagents for zenn","что еще нужно зенну","предметы для зенна","другие реагенты для зенна"}}},fp="15,233,18.458.0,17.384.1,36.153.0,41.140.0,45.187.0,58.111.0"}
P.entries["item:nissa-s-remains"] = {n="Останки Ниссы",s="Останки Ниссы — это найденные бренные останки Ниссы Агамонд, благородной дамы из некогда богатого рода Агамондов на севере Тирисфальских лесов. Убитые и поднятые Плетью в качестве безмозглых слуг во время Третьей войны, она и ее семья теперь становятся целью бывших работников, жаждущих мести.",h="Останки Ниссы — это найденные бренные останки Ниссы Агамонд, благородной дамы из некогда богатого рода...",kw={"agamand mills","brill","coleman farthing","deaths in the family","nissa agamand","nissa's remains","tirisfal glades","мельницы агамондов","брилл","колман фартинг","смерти в семье","нисса агамонд","останки ниссы","тирисфальские леса"},ang={["faction:Horde"]="Уничтожение восставших Агамондов и зачистка их мельниц защищает север Тирисфальских лесов от остатков Плети, угрожающих Бриллу и Подгороду.",["race:Undead"]="Для Отрекшихся возвращение Тирисфаля означает избавление и от прежних угнетателей из Плети, и от богатых аристократов, чья глупая гордыня обрекла простых работников на нежизнь."},sec={{t="Наследие гордыни",b="До Третьей войны род Агамондов был самой богатой и влиятельной династией Тирисфальских лесов и владел процветающими мельницами на северных холмах. Когда Чума нежизни расползлась по Лордерону, главы семьи упрямо отказались эвакуироваться. Вместо этого они укрепили свои поместья и убедили слуг и работников стоять до конца. Эта заносчивость стоила всем жизни. Агамонды пали перед Плетью и поднялись не с сохраненной гордой независимостью, а как бредущие безмозглые рабы, подчиненные воле Короля-лича."},{t="Горькое возмездие",b="В Брилле выжившие, позже освободившиеся под началом королевы Сильваны Ветрокрылой, не забыли роковую гордыню этой семьи. Колман Фартинг, бывший работник мельниц Агамондов, питает горькую обиду на своих прежних хозяев за то, что они завлекли работников в пасть нежизни. Он поручает искателям приключений уничтожить восставших Агамондов и забрать их останки, например останки Ниссы. Для Фартинга и других Отрекшихся сожжение или уничтожение этих реликвий дает мрачное чувство окончательного завершения и злорадной мести."}},faq={{q="Кто такая Нисса Агамонд?",a="Нисса была членом семьи Агамондов, дворян Лордерона, владевших обширными Мельницами Агамондов в Тирисфальских лесах. Когда Плеть захлестнула Лордерон, она погибла вместе с родными и была воскрешена как нежить-прислужница под властью Короля-лича.",al={"who is nissa","nissa lore","nissa agamand","кто такая нисса","предания о ниссе","нисса агамонд"}},{q="Зачем Колману Фартингу останки Ниссы?",a="Колман Фартинг при жизни работал на мельницах Агамондов. Он горько обижен на семью: их высокомерный отказ бежать убедил преданных работников остаться и погибнуть. Собирая их останки, он мстит прежним хозяевам.",al={"why coleman want remains","why kill agamands","coleman farthing motive","зачем колману останки","зачем убивать агамондов","мотив колмана фартинга"}},{q="Где собирают эти останки?",a="Нисса Агамонд бродит по разрушенным Мельницам Агамондов на севере Тирисфальских лесов среди обветшалых домов вместе с воскрешенными родственниками и безмозглыми рабами Плети.",al={"where do i find nissa","nissa agamand location","где найти ниссу","где находится нисса агамонд"}},{q="Сохранила ли Нисса свободную волю, как Отрекшиеся?",a="Нет. В отличие от Отрекшихся, порвавших с Королем-личом, Нисса и ее семья остались рабами Плети в виде безмозглой нежити и лишены разума и свободы, которыми обладают жители Подгорода.",al={"is nissa forsaken","did nissa have free will","is nissa scourge","нисса отрекшаяся","была ли у ниссы свободная воля","нисса плеть"}}},fp="15,298,17.567.0,18.540.0,22.260.0,47.246.0,33.194.0,49.197.0"}
P.entries["item:nitroglycerin"] = {n="Нитроглицерин",s="Нитроглицерин — летучее химическое вещество, которое носят дворфийские солдаты и офицеры гарнизона Бейл Модана на юге Степей. Он служит промышленной взрывчаткой для их раскопок, но может быть обращен и против них самих.",h="Нитроглицерин — летучее химическое вещество, которое носят дворфийские солдаты и офицеры гарнизона Бейл...",kw={"bael modan","bael'dun","barrens","explosives","gann stonespire","nitroglycerin","revenge of gann","бейл модан","бейл'дан","степи","взрывчатка","ганн каменное копье","нитроглицерин","месть ганна"},ang={["profession:Engineering"]="Инженеры сразу узнают в нитроглицерине классическую составную взрывчатку, которая становится стабильной и пригодной для подрыва, будучи впитанной пористой древесной массой вместе с окислителем, например нитратом натрия.",["race:Tauren"]="Летучие химикаты, которыми изуродовали землю вокруг Бейл Модана, горько напоминают о промышленном разорении, постигшем племя Каменного Копья."},sec={{t="Промышленный подрыв",b="Дворфы из Бейл'дана вгрызлись в исконные земли таурен Каменного Копья тяжелыми буровыми машинами и взрывчатой химией. Чтобы взрывать глубокие ямы и разрушать холмы, дворфы на раскопках Бейл Модана и в его укрепленной крепости держат под рукой запасы чистого нитроглицерина. И рядовые солдаты, и офицеры, например лорд Сирик Черная Кузня, носят при себе склянки с этой летучей жидкостью для продолжающихся разрушительных работ."},{t="Вкус собственного лекарства",b="После смерти геолога Хазгорма изгнанный из родных мест тауренский храбрец Ганн Каменное Копье решил полностью уничтожить наступающую дворфийскую крепость. Изучив дворфийские чертежи, Ганн понял, что конфискованный нитроглицерин в сочетании с древесной массой и нитратом натрия дает заряд, достаточно мощный, чтобы нанести ответный удар по укрепленному гарнизону Бейл Модана."}},faq={{q="Откуда берется нитроглицерин?",a="Нитроглицерин носят дворфийские войска в Бейл Модане на юге Степей, в том числе солдаты Бейл'дана, стрелки, офицеры и лорд Сирик Черная Кузня в крепости.",al={"where to find nitroglycerin","who drops nitroglycerin","nitroglycerin source","где найти нитроглицерин","с кого падает нитроглицерин","источник нитроглицерина"}},{q="Для чего нужен нитроглицерин?",a="Ганн Каменное Копье использует его вместе с древесной массой и нитратом натрия для создания мощного взрывного заряда, обращая подрывные методы самих дворфов против их военной крепости в Бейл Модане.",al={"what is nitroglycerin for","nitroglycerin purpose","revenge of gann ingredients","для чего нужен нитроглицерин","назначение нитроглицерина","месть ганна ингредиенты"}},{q="Зачем дворфы вообще его носили?",a="Старатели и гарнизон Бейл Модана сильно зависят от взрывчатки, паровых машин и летучих химикатов, чтобы вскрывать землю и вести свои археологические раскопки.",al={"why do dwarves have nitroglycerin","bael modan explosives","почему у дворфов нитроглицерин","взрывчатка бейл модана"}},{q="Кто такой Ганн Каменное Копье?",a="Ганн Каменное Копье — изгнанный тауренский воин, потерявший родные земли, когда дворфы основали в Бейл Модане раскопки и крепость и промышленными разрушениями вытеснили его племя.",al={"who is gann","gann stonespire","кто такой ганн","ганн каменное копье"}}},fp="13,256,21.476.0,29.384.1,35.187.0,35.202.0,52.174.0,23.199.0"}
P.entries["item:nondescript-letter"] = {n="Ненадписанное письмо",s="Ненадписанное письмо — запечатанное письмо без пометок, которое поручают недавно пробудившимся Отрекшимся, покидающим Могильник. Кальвин Монтеччи передает его под видом поручения, и оно направляет подателя по дороге к хозяйке таверны Ренни в таверне «Петля висельника» в Брилле.",h="Ненадписанное письмо — запечатанное письмо без пометок, которое поручают недавно пробудившимся Отрекшимся...",kw={"a rogue's deal","brill","calvin montague","deathknell","innkeeper renee","nondescript letter","renee","сделка разбойника","брилл","кальвин монтеччи","могильник","хозяйка таверны ренни","ненадписанное письмо","ренни"},ang={["class:Rogue"]="Подозрительная поза Кальвина Монтеччи и резкая перемена в поведении Ренни несут все приметы мелкой разбойничьей интриги и скрытой связи преступного мира.",["race:Undead"]="Для новоявленных Отрекшихся это письмо — один из первых стимулов покинуть пределы Могильника и исследовать другие поселения Тирисфальских лесов."},sec={{t="Поручение курьера",b="К недавно восставшим Отрекшимся, желающим выйти за пределы Могильника, подходит Кальвин Монтеччи, подозрительный разбойник возле границы поселения. Заявив, что устал сражаться с безмозглыми зомби и паукообразными, Кальвин просит путников отнести простой конверт без пометок по восточной дороге в Брилл. Письмо небрежно адресовано хозяйке таверны по имени Ренни и служит предлогом выманить путников из долины в таверну «Петля висельника», хотя обещания Кальвина о богатой награде с самого начала звучат пусто."},{t="Подозрительная переписка",b="При доставке в Брилле хозяйка таверны Ренни сначала разыгрывает преувеличенно веселый спектакль, утверждая, что письмо — приятная весть от ее святой матушки из Могильника. Поняв, что курьер видит ее неловкую игру насквозь, она сменяет любезность резким раздражением. Она выхватывает письмо, отказывается говорить, кто его на самом деле прислал и что в нем, и грубо прогоняет подателя, если тот не собирается платить за комнату."}},faq={{q="Что такое Ненадписанное письмо?",a="Это простой неприметный конверт, который Кальвин Монтеччи в Могильнике дает новоявленным Отрекшимся-искателям приключений для доставки хозяйке таверны Ренни в Брилле.",al={"nondescript letter","what is this letter","calvin's letter","ненадписанное письмо","что это за письмо","письмо кальвина"}},{q="Кто отправляет письмо и кто его получает?",a="Кальвин Монтеччи, разбойник, находящийся в Могильнике, дает письмо курьерам. Оно адресовано хозяйке таверны Ренни в таверне «Петля висельника» в Брилле.",al={"who sent the letter","who gets the letter","letter sender","кто отправил письмо","кто получает письмо","отправитель письма"}},{q="Что на самом деле сказано в письме?",a="Содержание письма игроку не раскрывается. Когда ее расспрашивают, хозяйка таверны Ренни отбрасывает веселую маску и зло заявляет, что происхождение и содержание письма вас не касаются.",al={"what does the letter say","letter contents","can you read the letter","что написано в письме","содержание письма","можно ли прочитать письмо"}},{q="Зачем Кальвину Монтеччи нужно доставить письмо?",a="Кальвин утверждает, что слишком занят борьбой с местными зомби и пауками, чтобы выполнить поручение самому. На деле доставка выводит путников из Могильника и знакомит их с удобствами и местами отдыха в Брилле.",al={"why send the letter","calvin's motive","why brill","зачем отправлять письмо","мотив кальвина","почему брилл"}}},fp="18,263,18.530.0,25.447.1,31.163.0,42.151.0,34.214.0,43.230.0"}
P.entries["item:nori-s-mug"] = {n="Кружка Нори",s="Кружка Нори — личный сосуд Нори Гордоступ, в котором доставляют жгучую бражку сквозь холодные сугробы Дун Морога. Согрев выпивкой от пронизывающего горного холода, путники должны вернуть пустую кружку ее бережливому владельцу.",h="Кружка Нори — личный сосуд Нори Гордоступ, в котором доставляют жгучую бражку сквозь холодные сугробы Дун...",kw={"bring back the mug","dun morogh","durnan furcutter","mornbrew","nori pridedrift","nori's mug","верни кружку","дун морог","дарнан мехорез","жгучая бражка","нори гордоступ","кружка нори"},ang={["race:Dwarf"]="Для дворфов, переживающих бури Дун Морога, разделить горячий напиток — вторая натура, но позволить хорошей посуде пропасть в сугробе — непростительная трата."},sec={{t="Возвращение курьера",b="В студеных горных перевалах Дун Морога кружка горячего утреннего пива — одно из немногих утешений, способных пробиться сквозь лютый холод. Нори Гордоступ доверяет свою кружку путникам, доставляющим свежую, дымящуюся порцию Дарнану Мехорезу в Старую Наковальню. Опорожненный прочный сосуд нужно вернуть. Как замечает Нори, кружки на деревьях не растут, а учет прочной дворфийской посуды — важное дело, когда гостеприимство встречается со снежной глушью."}},faq={{q="Для чего нужна Кружка Нори?",a="Она служит сосудом для доставки обжигающе горячего утреннего пива Дарнану Мехорезу в Старую Наковальню. Когда Дарнан вдоволь напьется и согреется, пустую кружку нужно вернуть Нори Гордоступу.",al={"purpose of noris mug","what was in the mug","noris cup","назначение кружки нори","что было в кружке","чашка нори"}},{q="Кому принадлежит эта кружка?",a="Кружка принадлежит Нори Гордоступ, дворфу из Дун Морога, который дорожит своими вещами и требует, чтобы курьеры возвращали посуду, а не бросали ее на снегу.",al={"who is nori","owner of mug","whose mug is it","кто такой нори","владелец кружки","чья это кружка"}},{q="Почему Нори настаивает на возвращении кружки?",a="Хорошая глиняная посуда и прочные кружки — нужные припасы в суровом горном климате. Как прямо замечает Нори, кружки на деревьях не растут, поэтому для него дело гордости и практичности — чтобы каждая одолженная кружка вернулась к нему.",al={"why return the mug","why does nori want it back","mugs dont grow on trees","зачем возвращать кружку","почему нори хочет кружку назад","кружки на деревьях не растут"}},{q="Что пили из этой кружки?",a="В ней была жгучая бражка — сытный теплый напиток, любимый дворфами Дун Морога: он спасает от пронизывающего холода и согревает душу.",al={"what was in the cup","what is mornbrew","mornbrew drink","что было в чашке","что такое жгучая бражка","напиток жгучая бражка"}}},fp="10,276,18.476.0,28.196.0,18.189.0,45.242.0,28.136.0"}
P.entries["item:notched-rib"] = {n="Зазубренное ребро",s="Зазубренное ребро — костяной трофей, добываемый у безмозглой нежити, бродящей по Тирисфальским лесам. Страж смерти Диллинжер в Брилле собирает эти изрубленные останки как доказательство усилий по подрыву позиций Плети на Мельницах Агамондов.",h="Зазубренное ребро — костяной трофей, добываемый у безмозглой нежити, бродящей по Тирисфальским лесам.",kw={"agamand mills","brill","cracked skull soldier","deathguard dillinger","notched rib","rattlecage soldier","scourge","tirisfal glades","мельницы агамондов","брилл","воин с треснувшим черепом","страж смерти диллинжер","зазубренное ребро","гремящий воин","плеть","тирисфальские леса"},ang={["race:Undead"]="Для Отрекшихся сбор этих расколотых костей — часть непрекращающейся войны за выживание против безмозглых приспешников Короля-лича, которые хотят вернуть их в рабство."},sec={{t="Мрачное доказательство боя",b="Силы Плети, собирающиеся на северных полях Тирисфальских лесов, состоят из поднятых скелетов в разбитых доспехах. Среди них Воины с треснувшим черепом и Гремящие воины бросаются на любое живое или свободное существо. Удары по их хрупким остовам оставляют на костях зазубрины и борозды. Чтобы Отрекшиеся-разведчики и добровольцы действительно истребляли безмозглых захватчиков, а не просто наблюдали, Стражи смерти требуют вещественных доказательств. Зазубренное ребро со следами боя — неоспоримое свидетельство того, что еще один раб Короля-лича разбит."},{t="Защита мельниц",b="Мельницы Агамондов — важная стратегическая позиция к северо-западу от Брилла. Если Плеть прочно закрепится среди разрушенных ферм и ветряков, у нее появится прямой плацдарм для ударов в самое сердце Тирисфаля. Страж смерти Диллинжер следит за дорогами на север и отправляет бойцов громить скелетов, пока те не укрепились. Груды зазубренных ребер, принесенные в Брилл, показывают, что линии Отрекшихся держатся, понемногу, кость за костью, перемалывая авангард Плети."}},faq={{q="Что такое Зазубренное ребро?",a="Это изрубленная кость скелета, снятая с оживших солдат Плети, занимающих север Тирисфальских лесов. Ее приносят Стражу смерти Диллинжеру как вещественное подтверждение уничтоженных врагов.",al={"notched rib","what is notched rib","notched rib item","зазубренное ребро","что такое зазубренное ребро","предмет зазубренное ребро"}},{q="Откуда берутся Зазубренные ребра?",a="Их добывают у Воинов с треснувшим черепом и Гремящих воинов, патрулирующих территорию Мельниц Агамондов к северо-западу от Брилла.",al={"where to find notched rib","who drops notched ribs","notched rib source","где найти зазубренное ребро","с кого падает зазубренное ребро","источник зазубренного ребра"}},{q="Кому нужны эти кости?",a="Их собирает Страж смерти Диллинжер, стоящий на дороге у Брилла, вместе с Обугленными черепами, чтобы убедиться, что наступление Плети отбито.",al={"who takes notched ribs","notched rib turn in","who needs notched rib","кто принимает зазубренные ребра","сдать зазубренное ребро","кому нужно зазубренное ребро"}},{q="Почему Плеть собирается на Мельницах Агамондов?",a="Безмозглая нежить пытается устроить на мельницах плацдарм. Оттуда силы Плети могли бы легко наносить удары по Тирисфальским лесам и угрожать поселениям Отрекшихся.",al={"scourge at agamand mills","why are skeletons at the mills","agamand mills scourge threat","плеть на мельницах агамондов","почему скелеты на мельницах","угроза плети на мельницах агамондов"}}},fp="11,236,20.629.0,18.542.0,22.191.0,32.141.0,22.157.0,46.196.0"}
P.entries["item:nugget-slug"] = {n="Металлическая заготовка для детали",s="Металлические заготовки для деталей — специализированные механические крепежные элементы калибра 17,5, применяемые в промышленной инженерии. Торговая Компания хранит их в ящиках с инструментами в Нефтяном болоте, и они очень нужны механикам, пытающимся починить неисправные механизмы.",h="Металлические заготовки для деталей — специализированные механические крепежные элементы калибра 17,5...",kw={"barrens","nugget slug","samophlange","sludge fen","tool bucket","venture company","wenikee boltbucket","степи","металлическая заготовка для детали","самофланж","нефтяное болото","ящик с инструментами","торговая компания","венаки бенике"},ang={["profession:Engineering"]="Любой инженер знает: сочетание особого крепежа калибра 17,5 с неисправным гоблинским самофланжем — прямая дорога к быстрой и взрывной разборке."},sec={{t="Промышленный крепеж Нефтяного болота",b="Металлические заготовки для деталей — прочный металлический крепеж, изготовленный для требовательных промышленных конструкций. Эти детали калибра 17,5 — важная часть тяжелого оборудования на добывающих площадках Торговой Компании. Как обычный товар они бесполезны, но незаменимы для механиков, работающих с нестандартной гоблинской техникой."},{t="Возня с самофланжем",b="Венаки Бенике нужно большое количество металлических заготовок для детали, чтобы перебрать нестабильный самофланец, найденный в Степях. Поскольку Торговая Компания регулярно оставляет ящики с инструментами разбросанными по своим буровым площадкам в Нефтяном болоте, сбор утиля выгоден для старателей — даже если итогом ремонта Венаки становится внезапный взрывной отказ."}},faq={{q="Что такое металлическая заготовка для детали?",a="Металлическая заготовка для детали — специализированный металлический крепеж калибра 17,5, применяемый в тяжелых механизмах. Она служит конструктивной деталью в сложных промышленных устройствах, например в нефтяных буровых установках и самофланжах.",al={"what are nugget slugs","nugget slug lore","slug fastener","что такое металлическая заготовка","заготовка для детали предания","крепеж заготовка"}},{q="Где найти металлические заготовки для деталей?",a="Они хранятся в ящиках с инструментами, разбросанных по Нефтяному болоту — буровому лагерю Торговой Компании на северо-востоке Степей.",al={"where do i find nugget slugs","nugget slug location","sludge fen tool buckets","где найти металлические заготовки","заготовка для детали местонахождение","ящики с инструментами нефтяное болото"}},{q="Зачем они нужны Венаки Бенике?",a="Венаки Бенике хочет починить найденный самофланж. Крепеж калибра 17,5 у нее закончился, поэтому она посылает искателей приключений добыть его в соседнем лагере Торговой Компании.",al={"who needs nugget slugs","why wenikee wants slugs","samophlange repair","кому нужны заготовки","зачем венаки заготовки","ремонт самофланжа"}},{q="Чинит ли самофланж использование заготовок?",a="Нет. Как только Венаки вставляет добытые заготовки и начинает обслуживание, самофланж внезапно взрывается прямо перед ней.",al={"does the machine work","samophlange explosion","wenikee repair result","заработает ли машина","взрыв самофланжа","результат ремонта венаки"}}},fp="11,232,38.358.0,30.376.1,22.206.0,29.133.0,38.215.0,48.156.1"}
P.entries["item:ogre-s-monocle"] = {n="Монокль огров",s="Монокль огров — огромное стекло, которое носит Зарк'Вул, огр из Лощины Вул'Гол на юге Сумеречного леса. Его огромная линза имеет точные размеры, нужные Виктору Призм’Антрасу из Темнолесья для сборки сложного телескопа.",h="Монокль огров — огромное стекло, которое носит Зарк'Вул, огр из Лощины Вул'Гол на юге Сумеречного леса.",kw={"cog","darkshire","look to the stars","ogre's monocle","telescope","viktori prismafire","vul'gol ogre mound","zzarc'vul","зубец","темнолесье","монокль огров","телескоп","виктор призм’антрас","лощина вул'гол","зарк'вул"},ang={["faction:Alliance"]="Забрав линзу у огров Вул'Гола, Альянс избавляет южные леса от опасного громилы и помогает осажденным жителям Темнолесья найти утешение в звездах.",["profession:Engineering"]="Чертеж Зубца демонстрирует типичный гномий размах: использовать нестандартные детали, например гигантские очки, когда точно отшлифованных линз в полевых условиях нет."},sec={{t="Необычная линза",b="Огры редко славятся ученостью, но Зарк'Вул каким-то образом завладел огромным моноклем, подходящим его гигантскому росту. Когда житель Темнолесья Виктор Призм’Антрас взялся строить прибор для наблюдения за звездами по чертежам гнома-инженера Зубца, обычные линзы оказались слишком малы. Очки Зарк'Вула оказались единственным полированным стеклом в округе с нужной кривизной и размером, чтобы фокусировать свет в готовом устройстве."},{t="Добыча из Вул'Гола",b="Чтобы добыть монокль, придется отправиться в Лощину Вул'Гол в тени юга Сумеречного леса. Зарк'Вул живет среди сородичей-громил и вовсе не склонен добровольно расставаться со своей приметной вещью. Чтобы забрать линзу, нужно победить громилу на его земле, а затем вернуть стекло в Темнолесье, чтобы Виктор наконец смог обратить взор к ночному небу."}},faq={{q="У кого находится монокль огров?",a="Монокль носит Зарк'Вул, известный огр, бродящий по Лощине Вул'Гол на юге Сумеречного леса.",al={"who drops the monocle","who has the ogre monocle","zzarc'vul item","кто носит монокль","у кого монокль огра","предмет зарк'вула"}},{q="Зачем Виктору Призм’Антрасу огровский монокль?",a="Виктор строит телескоп по чертежам гнома Зубца. Для устройства нужна необычно большая оптическая линза, а огромный монокль Зарк'Вула — единственное стекло в Сумеречном лесу, подходящее по размерам.",al={"why need monocle","what is the monocle for","telescope lens","зачем нужен монокль","для чего монокль","линза для телескопа"}},{q="Как огр получил гигантский монокль?",a="The source does not explain how Zzarc'Vul acquired the monocle. It establishes only that he possesses one large enough for Viktori's telescope.",al={"why does an ogre have a monocle","ogre reading glasses lore","почему у огра монокль","очки огра предания"}},{q="Где находится Лощина Вул'Гол?",a="Лощина Вул'Гол лежит в южных холмах Сумеречного леса, к югу от главной дороги между Темнолесьем и западной границей.",al={"where is vulgol","ogre mound duskwood","где вул'гол","лощина огров сумеречный лес"}}},fp="14,266,14.496.0,22.382.0,31.114.0,54.233.0,36.143.0,40.137.0"}
P.entries["item:okra"] = {n="Окра",s="Окра — культурный овощ, растущий на возделанных грядках Западного Края. Местные поселенцы высоко ценят ее: она служит важным загустителем в сытных, импровизированных похлебках региона.",h="Окра — культурный овощ, растущий на возделанных грядках Западного Края.",kw={"crop","farm","okra","saldean","salma saldean","vegetable","westfall stew","урожай","ферма","окра","сальден","сальма сальден","овощ","похлебка западного края"},ang={["faction:Alliance"]="Пока знать Штормграда ест привозное мясо, поселенцы Альянса на границе выживают, выращивая упрямые культуры вроде окры среди руин Западного Края.",["profession:Cooking"]="Любой странствующий повар знает: для хорошей похлебки нужно не только сырое мясо; окра дает необходимые крахмал и густоту, превращая жесткую добычу из глуши в настоящую горячую еду."},sec={{t="Основа Фермы Сальдена",b="Хотя большая часть Западного Края лежит под паром из-за угрозы Братства Справедливости и нападений взбесившихся жнецов-големов, упрямые фермеры вроде Сальденов все же вырастают на земле сытные овощи. Окра растет низкой и зеленой на возделанной земле вокруг Фермы Сальдена. Несмотря на суровые условия, культура держится и дает поселенцам необходимую сытность и питание, когда торговля и поставки из Штормграда совсем прекращаются."},{t="Похлебка Западного Края",b="Окра известна как незаменимая основа знаменитой Похлебки Западного Края Сальмы Сальден. В сочетании с любым мясом, добытым на пыльных равнинах, — мясом стервятников, рылами свирепых вепрей и глазами прибрежных мурлоков — нарезанные стручки разваривается и превращает жидкий бульон в сытное, питательное блюдо. Для поселенцев, цепляющихся за свои дома, свежие стручки окры превращают скудную добычу в горячий сытный ужин."}},faq={{q="Где растет окра в Западном Крае?",a="Окра растет на возделанных грядках Фермы Сальдена на центральной дороге Западного Края. Путники могут найти характерные зеленые растения на бороздах возле дома Фермера Сальдена.",al={"okra location","where to find okra","where does okra grow","окра местонахождение","где найти окру","где растет окра"}},{q="Для чего нужна окра?",a="Окру собирают для Сальмы Сальден на Ферме Сальдена, чтобы приготовить ее фирменную Похлебку Западного Края. Природный крахмал загущает бульон и объединяет грубые ингредиенты — мясо стервятников, рыла вепрей и глаза мурлоков — в сытное блюдо.",al={"okra uses","what is okra for","why do i need okra","применение окры","для чего окра","зачем мне окра"}},{q="Почему окра важна для Сальденов?",a="Из-за нарушенной торговли и скудной помощи от королевства поселенцам приходится полагаться лишь на то, что они вырастят и добудут сами. Окра — одна из немногих оставшихся культур на Ферме Сальдена, которая кормит семью и случайных путников.",al={"saldean okra","why okra matters","окра сальденов","почему важна окра"}}},fp="4,198,26.460.0,13.448.0,33.206.0,22.223.0,38.254.0"}
P.entries["item:ordanus-head"] = {sec={{t="Давняя обида",b="Keeper Ordanus was an ancient keeper of the grove, one of the elder scions of the forest god Cenarius. When Braelyn Firehand climbed the heights of Stonetalon Mountains on orders from her master, she sought to cleanse the sacred Highborne ruins from night elven presence and exact vengeance on Ordanus. However, the keeper was spirited away to the heart of Ashenvale before she could strike. Using arcane scrying to peer through the forest canopy, Firehand located his sanctuary in the boughs of Raynewood Retreat, demanding his severed head as proof that the wild demigod's arrogance had finally been answered."},{t="Цена высокомерия",b="Braelyn holds a centuries-deep grievance against Ordanus and the druids who dared condemn arcane casting while occupying ruins once sanctified to Queen Azshara. In life, Ordanus considered himself superior even to the ancient Highborne nobility. By taking his head, Firehand symbolically strikes back against the legacy of Cenarius, declaring that no guardian of the wild can stem the return of raw magical power."}},faq={{q="Who was Keeper Ordanus?",a="Keeper Ordanus was an ancient keeper of the grove and an elder son of Cenarius. Long ago, he clashed with the arcane practitioners of the night elven nobility, holding a reputation for deep arrogance toward those who practiced the arcane arts.",al={"who is ordanus","ordanus lore","what is ordanus"}},{q="Где добывается эта голова?",a="The head is claimed from Keeper Ordanus atop the elevated wooden platform at Raynewood Retreat, a fortified night elven canopy enclave situated in central Ashenvale.",al={"where to find ordanus head","ordanus location","raynewood retreat ordanus"}},{q="Why does Braelyn Firehand want his head?",a="Braelyn Firehand seeks vengeance for an ancient feud dating back to before the Great Sundering, when Ordanus and his kin looked down upon the Highborne. She also despises the night elves for defiling the ancient ruins of Azshara atop Stonetalon Peak.",al={"why braelyn wants ordanus head","braelyn grudge","why kill ordanus"}},{q="Что происходит после доставки головы?",a="Delivering Ordanus' Head to Braelyn at Sunrock Retreat satisfies her blood debt, prompting her to reward the mercenary handsomely before directing her wrath toward deeper druidic strongholds in the region.",al={"ordanus head turn in","after ordanus dies","braelyn firehand quest reward"}}},fp="13,250,22.611.0,19.413.1,23.243.0,29.165.0,40.250.0,41.205.1"}
P.entries["item:orendil-s-cure"] = {n="Лекарство Орендила",s="Лекарство Орендила — целебное снадобье, приготовленное травником Орендилом Широколистом на севере Ясеневого леса. Оно создано из редкой травы Батранов волос и предназначено для лечения загадочной смертельной болезни Релары Белой Луны в Астранааре.",h="Лекарство Орендила — целебное снадобье, приготовленное травником Орендилом Широколистом на севере Ясеневого...",kw={"ashenvale","astranaar","bathran's hair","orendil broadleaf","orendil's cure","pelturas whitemoon","relara","ясеневый лес","астранаар","батранов волос","орендил широколист","лекарство орендила","пельтур белая луна","релара"},ang={["profession:Herbalism"]="Это средство показывает целебную силу местной флоры Ясеневого леса, особенно Батранова волоса, который растет лишь в отдельных затененных уголках леса.",["race:NightElf"]="Для ночных эльфов Астранаара спасение Релары — неотложное дело общины, сочетающее лесные знания отшельников вроде Орендила с верой в Элуну."},sec={{t="Надежда отца",b="Когда юная Релара Белая Луна тяжело заболела в Астранааре, обычные средства оказались бессильны. Ее отчаявшийся отец Пельтур Белая Луна обратился к Орендилу Широколисту, отшельнику и мастеру природной медицины с севера Ясеневого леса. Из пучков редкого растения Батранов волос, собранного в призрачных руинах Убежища Батрана, Орендил сварил это особое снадобье. Хотя это лишь первый шаг к стабилизации ухудшающегося состояния ребенка, появление флакона дарит Пельтуру проблеск надежды в мрачном бдении."}},faq={{q="Для чего нужно Лекарство Орендила?",a="Лекарство создано, чтобы облегчить и лечить Релару Белую Луну, юную ночную эльфийку в Астранааре, внезапно сраженную тяжелой болезнью.",al={"orendil cure purpose","what does the cure do","who is the cure for","назначение лекарства орендила","что делает лекарство","для кого лекарство"}},{q="Кто приготовил лекарство?",a="Его приготовил Орендил Широколист, замкнутый ночной эльф-травник из северных чащ Ясеневого леса, известный мастерством в области лесных растений и снадобий.",al={"who made orendils cure","creator of orendils cure","кто сделал лекарство орендила","создатель лекарства орендила"}},{q="Какие ингредиенты использовались?",a="Главный ингредиент — Батранов волос, нежное и нечастое растение, собираемое среди руин Убежища Батрана на севере Ясеневого леса.",al={"cure ingredients","what is in orendil's cure","ингредиенты лекарства","что в лекарстве орендила"}},{q="Излечивает ли это зелье ребенка полностью?",a="Оно дарит Пельтуру надежду и стабилизирует состояние дочери, но недуг оказывается глубоким, и для полного исцеления нужны другие священные реагенты, включая Слезы Элуны.",al={"did it cure relara","is relara healed","вылечило ли релару","исцелена ли релара"}}},fp="14,245,15.601.0,32.151.0,21.175.0,38.136.0,43.172.1"}
P.entries["item:oslow-s-toolbox"] = {n="Ящик инструментов Ослоу",s="Ящик инструментов Ослоу содержит жизненно важные строительные инструменты, необходимые штейгеру Ослоу в Приозерье. На пути из Златоземья припасы переправляли через Озеро Безмолвия, но лодку потопил обстрел из орочьей катапульты.",h="Ящик инструментов Ослоу содержит жизненно важные строительные инструменты, необходимые штейгеру Ослоу в...",kw={"foreman oslow","lake everstill","lakeshire","oslow","redridge","sunken chest","the lost tools","toolbox","штейгер ослоу","озеро безмолвия","приозерье","ослоу","красногорье","затонувший сундук","потерянные инструменты","ящик с инструментами"},ang={["faction:Alliance"]="Приозерье почти отрезано осадой Черной горы, поэтому возвращение припасов Ослоу крайне важно для сохранности оборонительных сооружений города."},sec={{t="Роковая переправа",b="Поддерживать оборону и инфраструктуру Приозерья — тяжелая задача, особенно когда орки Черной горы осаждают Красногорье. Штейгер Ослоу распорядился доставить из Златоземья важный набор строительных инструментов. Поскольку главный мост к Приозерью был разрушен врагом, груз пришлось погрузить в лодку, чтобы пересечь Озеро Безмолвия. Переправа резко оборвалась: силы Черной горы накрыли судно катапультным снарядом, и лодка вместе с тяжелым сундуком Ослоу ушла на дно, кишащее мурлоками."}},faq={{q="Почему Ящик инструментов Ослоу лежит на дне озера?",a="Груз с инструментами перевозили из Златоземья. Мост у Приозерья был разрушен во время осады, поэтому припасы пришлось переправлять через Озеро Безмолвия на лодке. Орки Черной горы обстреляли лодку из катапульты, судно затонуло, а ящик с инструментами оказался на дне.",al={"why is the toolbox in the water","how did oslow lose his tools","sunken toolbox lore","почему ящик с инструментами в воде","как ослоу потерял инструменты","затонувший ящик с инструментами"}},{q="Кому принадлежит этот ящик с инструментами?",a="Ящик принадлежит штейгеру Ослоу, который руководит строительством и ремонтом в Приозерье. Без нужного снаряжения почти невозможно поддерживать укрепления города под постоянными атаками.",al={"who is oslow","oslow owner","foreman oslow tools","кто такой ослоу","владелец ящика ослоу","инструменты штейгера ослоу"}},{q="Где в Озере Безмолвия затонули инструменты?",a="Инструменты лежат в затонувшем сундуке рядом с обломками разбитой лодки в Озере Безмолвия, среди подводных валунов к югу от крупного мурлокского лагеря на берегу.",al={"toolbox location","where is sunken chest","where did the boat sink","где ящик с инструментами","где затонувший сундук","где затонула лодка"}},{q="Какие угрозы охраняют затонувший сундук?",a="Воды вокруг обломков кишат враждебными мурлоками и хищными водными тварями, в том числе опасными озерными молотильщиками, что бродят на глубине озера.",al={"dangers near toolbox","lake everstill enemies","what is guarding oslows tools","опасности у ящика","враги озера безмолвия","кто охраняет инструменты ослоу"}}},fp="15,215,18.576.0,49.284.0,22.215.0,43.182.0,36.175.0"}
P.entries["item:osric-s-crate"] = {n="Ящик Озрика",s="Ящик Озрика — тяжелая посылка со свежеизготовленными доспехами, отправленная из Штормграда измотанным защитникам Сторожевого холма. Ее доставляют на грифоне по сети полетов королевства, и она дает Народному ополчению необходимое снаряжение, чтобы удерживать Западный Край против разбойничьих банд.",h="Ящик Озрика — тяжелая посылка со свежеизготовленными доспехами, отправленная из Штормграда измотанным...",kw={"dungar longdrink","gryphon","osric","osric's crate","peoples militia","quartermaster lewis","sentinel hill","westfall","дунгар долгопив","грифон","озрик","ящик озрика","народное ополчение","интендант льюис","сторожевой холм","западный край"},ang={["faction:Alliance"]="Каждая партия оружия и доспехов, дошедшая до Сторожевого холма, помогает не дать западным границам королевства полностью пасть перед Братством Справедливости."},sec={{t="Снабжение для фронта",b="Западный Край страдает от набегов Братства Справедливости и мародерствующих гноллов, а армия Штормграда так и не появилась. Местные защитники, объединенные в Народное ополчение Сторожевого холма, лишены официальной поддержки короны и вынуждены довольствоваться случайными поставками. Ящик Озрика содержит свежую партию защитных доспехов, присланных из столицы интенданту Льюису, чтобы раздать их напрямую бойцам-добровольцам ополчения."},{t="Сеть крылатых курьеров",b="Перевозить снаряжение по суше из Штормграда через Элвиннский лес и границу Западного Края медленно, к тому же на дорогах поджидают бандитские засады. Чтобы обойти дороги, ящик поручают искателю приключений, который летит от грифонюшни Дунгара Долгопива в Торговом квартале Штормграда к Тору на Сторожевой холм. Такая быстрая доставка показывает, какую важную роль играют грифоны в снабжении приграничных гарнизонов во время войны."}},faq={{q="Что находится в Ящике Озрика?",a="В ящике лежат защитные доспехи, изготовленные в Штормграде. Интендант Льюис проверяет доставку и сразу готовится раздать доспехи бойцам, защищающим Сторожевой холм.",al={"what's in the crate","contents of osrics crate","osric crate contents","что в ящике","содержимое ящика озрика","что внутри ящика озрика"}},{q="Кто такой Озрик?",a="Озрик — оружейник из Штормграда, подготовивший эту партию снаряжения для Народного ополчения, удерживающего Западный Край.",al={"who is osric","who sent osrics crate","кто такой озрик","кто отправил ящик озрика"}},{q="Кто получает ящик?",a="Груз адресован интенданту Льюису, офицеру, который ведает припасами и снаряжением Народного ополчения на Сторожевом холме в Западном Крае.",al={"where does the crate go","who do i give osric's crate to","crate recipient","куда доставить ящик","кому отдать ящик озрика","получатель ящика"}},{q="Почему ящик доставляют на грифоне?",a="Бандиты и разбойники делают дороги между Штормградом, Элвиннским лесом и Западным Краем опасными. Перелет на грифоне от Дунгара Долгопива в Штормграде прямо к Тору на Сторожевом холме гарантирует, что доспехи прибудут быстро и безопасно.",al={"why fly the crate","why use gryphons","osric crate flight","почему ящик летит","почему грифоны","полет с ящиком озрика"}}},fp="13,284,22.458.0,22.421.0,29.192.0,13.116.0,23.148.0,38.228.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Упаковка пустых коробочек для слизней",s="Эта упаковка — набор специальных пустых банок для образцов, предоставленный гномом-исследователем Ларис Обалдуй в Стальгорне. Он предназначен для опасного сбора образцов в погибающих чащах Оскверненного леса и содержит банки, способные безопасно удерживать оскверненные и проклятые экстракты слизи, не растворяясь.",h="Эта упаковка — набор специальных пустых банок для образцов, предоставленный гномом-исследователем Ларис...",kw={"containers","cursed","felwood","ironforge","jars","laris geardawdle","ooze","package","slime","tainted","коробочки","проклятая","оскверненный лес","стальгорн","банки","ларис обалдуй","слизь","упаковка","слизни","оскверненная"},ang={["faction:Alliance"]="Сбор этих образцов помогает Альянсу не отставать от тревожных исследований Королевского фармацевтического общества Отрекшихся.",["race:Gnome"]="Ларис Обалдуй видит в исследовании слизи важную возможность показать дворфам Стальгорна, что приютить гномов-беженцев стоило хлопот."},sec={{t="Полевое исследовательское оборудование",b="Набор из дюжины пустых банок — часть для проклятой слизи, часть для оскверненной — собрала Ларис Обалдуй для отважных путников, отправляющихся в Оскверненный лес. Сырые образцы слизи крайне едки и разъедают обычную поклажу, поэтому для перевозки кислотных остатков через континенты к рабочему столу механика в Стальгорне необходимо прочное запечатанное стекло."},{t="Тайна слизи",b="Geardawdle's interest in ooze is far from a simple eccentric hobby. Noticing that Forsaken researchers from the Royal Apothecary Society routinely harvest these bizarre organisms across Azeroth, he suspects oozes may hold profound secrets about the world's origin. Geardawdle theorizes that slimes might be primordial secretions connected to the planet's very creation, and he relies on field agents using this kit to collect the evidence he needs to win acclaim within the Explorers' League."}},faq={{q="Что находится в упаковке пустых коробочек для слизней?",a="В упаковке двенадцать банок для образцов: шесть пустых, рассчитанных на проклятую слизь, и шесть для оскверненной слизи.",al={"package contents","what does package contain","ooze jars inside","содержимое упаковки","что в упаковке","банки для слизи"}},{q="Кто выдает эту упаковку?",a="Ее вручает искателям приключений из Альянса Ларис Обалдуй, гномка-ученая и исследователь, работающая в Стальгорне.",al={"who gives the jars","laris geardawdle quest item","where do i get the ooze package","кто дает банки","предмет задания ларис обалдуй","где взять упаковку для слизи"}},{q="Где нужно использовать эти коробочки?",a="Они предназначены для использования в искаженных землях Оскверненного леса, где искатели приключений должны побеждать оскверненную и проклятую слизь, чтобы собирать образцы остатков прямо с павших существ.",al={"where do i use ooze jars","which zone for oozes","ooze jar location","где использовать банки для слизи","в какой зоне слизь","место для банок слизи"}},{q="Зачем Ларис Обалдуй нужны образцы слизи?",a="Ларис заметила, что Королевское фармацевтическое общество Отрекшихся собирает слизь по всему миру, и хочет раскрыть их тайны. Кроме того, у нее есть необычная теория, что слизь может быть первичными выделениями, связанными с созданием Азерота, и она надеется, что доказательство принесет ей положение в Лиге исследователей.",al={"why collect slime","geardawdle research","why does laris want ooze","зачем собирать слизь","исследования обалдуй","зачем ларис слизь"}}},fp="32,289,24.409.0,23.492.0,52.121.0,26.116.0,44.183.0,50.308.0"}
P.entries["item:painted-gnoll-armband"] = {n="Раскрашенные поручи гнолла",s="Раскрашенные поручи гнолла — грубые украшения, которые носят гноллы Речной Лапы, рыскающие на окраинах Элвиннского леса. Гарнизон у Западного ручья собирает эти меченые повязки как вещественное доказательство выполненных заданий по уничтожению наступающих стай.",h="Раскрашенные поручи гнолла — грубые украшения, которые носят гноллы Речной Лапы, рыскающие на окраинах...",kw={"bounty","deputy rainer","elwynn forest","gnolls","painted gnoll armband","riverpaw","stone cairn lake","westbrook garrison","награда","заместитель судьи рейнер","элвиннский лес","гноллы","раскрашенные поручи гнолла","речная лапа","озеро каменных столбов","гарнизон у западного ручья"},ang={["faction:Alliance"]="Сбор этих поручей напрямую помогает Гарнизону у Западного ручья, укрепляя западный рубеж Штормграда, пока постоянная армия города занята в других местах."},sec={{t="Знаки Речной Лапы",b="The Riverpaw pack marks its warriors and scavengers with rough armbands painted in crude tribal patterns. The painted bands are collected from the Riverpaw gnolls along the wilderness borders of Elwynn Forest. To the defenders of Stormwind, however, they represent a growing territorial menace encroaching near Stone Cairn Lake and the woods south of Westbrook Garrison."},{t="Награда для Гарнизона у Западного ручья",b="Поскольку Армия Штормграда растянута по всему королевству, Гарнизон у Западного ручья с трудом удерживает западную границу от вторжений. Заместитель судьи Рейнер назначил постоянную награду за вторгшиеся стаи и велел искателям приключений убивать бегунов и заморышей Речной Лапы. Раскрашенные поручи служат неоспоримым доказательством убийства, позволяя помощникам гарнизона вести учет наград и сокращать число гноллов у соседних ферм."}},faq={{q="Зачем Гарнизону у Западного ручья эти поручи?",a="Заместитель судьи Рейнер из Гарнизона у Западного ручья собирает поручи как доказательство гибели гноллов Речной Лапы. Поскольку солдаты гарнизона не справляются с наступающими стаями в одиночку, Штормград платит награду любому искателю приключений, принесшему эти знаки.",al={"why armbands","who wants painted gnoll armbands","deputy rainer bounty","зачем поручи","кому нужны раскрашенные поручи гнолла","награда заместителя рейнера"}},{q="Какие гноллы носят эти раскрашенные поручи?",a="Их носят гноллы Речной Лапы в Элвиннском лесу, а именно бегуны и заморыши Речной Лапы, наводнившие леса к югу от Гарнизона у Западного ручья и берега вокруг Озера Каменных Столбов.",al={"where do armbands drop","who drops painted gnoll armband","which gnolls have armbands","где падают поручи","кто роняет раскрашенные поручи гнолла","у каких гноллов поручи"}},{q="Почему гноллы Речной Лапы оказались в Элвиннском лесу?",a="Стаи Речной Лапы продвинулись на восток вдоль границ Элвиннского леса и устроили лагеря у Озера Каменных Столбов и на опушках. Они пользуются ослаблением военного присутствия королевства, чтобы охотиться, мародерствовать и угрожать ближним поселениям.",al={"why are gnolls here","gnoll invasion elwynn","riverpaw elwynn","почему здесь гноллы","вторжение гноллов в элвиннский лес","речная лапа элвиннский лес"}},{q="Что означает краска на поручах?",a="The bands identify trophies taken from the Riverpaw gnolls and serve as proof for Deputy Rainer. The source does not assign specific ranks or meanings to the painted patterns.",al={"why are they painted","gnoll armband markings","почему они раскрашены","знаки на поручах гнолла"}}},fp="21,230,22.370.0,29.441.0,48.231.0,41.201.0,41.247.0,54.175.0"}
P.entries["item:panther-cage-key"] = {n="Ключ от клетки пантеры",kw={"centaur","hypercapacitor gizmo","panther cage key","thousand needles","whitereach post","wizlo bearingshiner","кентавры","гиперконденсаторная штуковина","ключ от клетки пантеры","тысяча игл","застава белого плеса","визло фингалет"},ang={["faction:Horde"]="Помощь Визло помогает обезопасить дороги Тысячи Игл вокруг Заставы Белого Плеса от опасных последствий набегов кентавров.",["profession:Engineering"]="Ключ открывает клетку с нестабильным прототипом механика, доказывая, что эксцентричные изобретатели прячут самые хрупкие механизмы в самых опасных местах, какие только можно представить."},sec={{t="Ненадежный замок",b="Когда кентавры-налетчики напали на караван к северу от Заставы Белого Плеса и разграбили его, гоблин-механик Визло Фингалет едва спасся. Среди развалин повозок и награбленного груза мародеры не тронули одно: прочную клетку со свирепой редкой пантерой. На шее хищника висело любимое изобретение Визло — гиперконденсаторная штуковина. Не решаясь приблизиться к рычащему зверю, кентавры обходили клетку стороной, и ключ Визло остался единственным способом открыть дверь и забрать устройство."}},faq={{q="Кто выдает Ключ от клетки пантеры?",a="Ключ вручает искателям приключений Визло Фингалет, гоблин-механик, отдыхающий на Заставе Белого Плеса на северо-западе Тысячи Игл.",al={"who gives panther key","where to get panther cage key","panther cage key source","кто дает ключ от пантеры","где взять ключ от клетки пантеры","источник ключа от клетки пантеры"}},{q="Что открывает этот ключ?",a="Он открывает железную клетку среди сломанных повозок разгромленного каравана к северу от Заставы Белого Плеса, в которой сидит разъяренная опасная пантера.",al={"what does panther key open","panther cage location","where is the cage","что открывает ключ пантеры","где клетка пантеры","где находится клетка"}},{q="Почему кентавры не разграбили клетку?",a="Кентавры разграбили остальной караван, но пленная пантера внутри была так свирепа и опасна, что даже налетчики не решились трогать ее клетку.",al={"why did centaur leave panther","centaur afraid of panther","почему кентавры оставили пантеру","кентавры боятся пантеры"}},{q="Что находится в клетке, кроме зверя?",a="Любимая гиперконденсаторная штуковина Визло закреплена на шее пантеры, поэтому каждому, кто хочет вернуть изобретение, придется открыть клетку и столкнуться с хищником лицом к лицу.",al={"why open the cage","what is on the panther","зачем открывать клетку","что на пантере"}}},fp="16,219,17.550.0,34.133.0,25.147.0,37.165.0,42.176.0"}
P.entries["item:parker-s-lunch"] = {n="Обед Паркера",s="Обед Паркера — свежеприготовленная еда, которую собрала Дарси в Приозерье. Она предназначена для Стражника Паркера, несущего дозор, и дает простое представление о повседневных связях и скромных радостях защитников Красногорья.",h="Обед Паркера — свежеприготовленная еда, которую собрала Дарси в Приозерье.",kw={"a free lunch","darcy","guard parker","lakeshire","parker's lunch","redridge","бесплатный обед","дарси","стражник паркер","приозерье","обед паркера","красногорье"},ang={["faction:Alliance"]="Столица не спешит присылать подкрепления, и Приозерье держится на солидарности жителей и немногих оставшихся стражников.",["profession:Cooking"]="Теплая еда в дорогу — часто единственное утешение, которое поддерживает пограничных стражников в долгие часы дозора среди враждебных зверей."},sec={{t="Еда в дорогу",b="Пока Красногорье страдает от нападений гноллов и орков Черной горы, маленькие жесты повседневной жизни не исчезают. Дарси, подавальщица в таверне Приозерья, собирает этот сытный обед для Стражника Паркера, который патрулирует открытую дорогу на юг, к Сумеречному лесу. Гарнизон Красногорья малочислен и отрезан от помощи Штормграда, поэтому стражникам приходится в одиночку нести долгие дозоры. Доставка этого свертка не только кормит часового, но и дает начало долгому застенчивому ухаживанию между двумя жителями городка."}},faq={{q="Кто приготовил Обед Паркера?",a="Обед приготовила Дарси, подавальщица из таверны Приозерья. Беспокоясь за Стражника Паркера, который ушел в опасный дозор, она рассчитывает на странствующих искателей приключений, которые безопасно доставят ему еду.",al={"who made parker's lunch","who gave me parker's lunch","darcy redridge lunch","кто приготовил обед паркера","кто дал мне обед паркера","дарси красногорье обед"}},{q="Где найти Стражника Паркера?",a="Стражник Паркер патрулирует главную грунтовую дорогу, идущую от Приозерья на юго-запад к границе Сумеречного леса. Он ходит взад и вперед по этому маршруту, высматривая бродячих гноллов.",al={"guard parker location","where is guard parker","find guard parker","где стражник паркер","местонахождение стражника паркера","найти стражника паркера"}},{q="Что делает Стражник Паркер после того, как получает обед?",a="Паркер глубоко тронут заботой Дарси. Благодарный за теплую еду во время трудного дозора, он вскоре ищет способ отплатить ей добром и просит помощи, чтобы отправить ей свежие нарциссы от травницы.",al={"parker lunch follow up","darcy and parker","parker reaction to lunch","что дальше с обедом паркера","дарси и паркер","реакция паркера на обед"}},{q="Почему Дарси не доставляет обед сама?",a="Дороги за пределами Приозерья кишат агрессивными гноллами Красногорья и захватчиками из Черной горы. Стражник Паркер обучен сражаться и имеет доспехи, чтобы выжить в дозоре, а обычные жители, такие как Дарси, не могут рисковать, отправляясь в путь в одиночку.",al={"why cant darcy bring it","why deliver lunch redridge","почему дарси не может отнести","зачем доставлять обед красногорье"}}},fp="14,201,19.526.0,28.194.0,32.182.0,52.210.1,44.241.0"}
P.entries["item:partially-filled-vessel"] = {n="Наполовину полный сосуд",s="Наполовину полный сосуд — зачарованная емкость, в которой переносят благословенную воду лунного колодца по Тельдрассилу. Ее выдает юным ночным эльфам-неофитам Тенарон Хватка Бури в Альдрассиле, а в ней вода из Тенистой долины, которую несут в поселение Доланаар.",h="Наполовину полный сосуд — зачарованная емкость, в которой переносят благословенную воду лунного колодца по...",kw={"aldrassil","corithras moonrage","crown of the earth","dolanaar","moonwell","partially filled vessel","shadowglen","tenaron stormgrip","vessel","альдрассил","коритрас лунный гнев","корона земли","доланаар","лунный колодец","наполовину полный сосуд","тенистая долина","тенарон хватка бури","сосуд"},ang={["class:Druid"]="Перенос освященной воды — важная обязанность на службе Круга Кенария, который стремится заботиться о здоровье Мирового Древа и проверять его.",["race:NightElf"]="Перенос этого сосуда — обряд посвящения: он уводит юных ночных эльфов из безопасной Тенистой долины к более широким обязанностям по заботе о Тельдрассиле."},sec={{t="Священная доставка",b="В ветвях Альдрассила неофиты кальдораев собирают благословенную воду из уединенного лунного колодца Тенистой долины. Тенарон Хватка Бури наливает эту чистую пробу в особый сосуд, готовя его к путешествию по Мировому Древу. Сосуд заполнен лишь наполовину, потому что его путь только начался: со всего Тельдрассила предстоит собрать еще больше священной воды, чтобы поддерживать здоровье острова."},{t="Вперед, в Доланаар",b="Чтобы доставить сосуд, нужно пройти на юг через ворота долины и по мощеным дорогам на запад до Доланаара. Это путешествие знаменует уход юного искателя приключений из защищенной колыбели Тенистой долины в дикие просторы Тельдрассила. У центрального лунного колодца Доланаара Коритрас Лунный Гнев принимает сосуд, чтобы руководить следующим этапом ритуала."}},faq={{q="Что находится внутри сосуда?",a="В нем чистая вода лунного колодца, набранная из священного источника в Тенистой долине и налитая в емкость друидом Тенароном Хваткой Бури.",al={"what's in the vessel","vessel contents","what water is in it","что в сосуде","содержимое сосуда","какая в нем вода"}},{q="Почему он заполнен лишь наполовину?",a="Лунный колодец Тенистой долины дает только первую пробу. Чтобы заполнить емкость, в рамках постоянных забот о Тельдрассиле нужно собрать воду из нескольких лунных колодцев на дереве.",al={"why partly filled","why is it not full","почему наполовину полный","почему он не полный"}},{q="Кому нужно отнести этот сосуд?",a="Отнесите сосуд на юг из Тенистой долины и идите по мощеной дороге на запад до Доланаара. Там передайте его Коритрас Лунный Гнев, которая заботится о лунном колодце поселения.",al={"who gets the vessel","where do i bring it","vessel turn in","кому отдать сосуд","куда его нести","сдать сосуд"}},{q="Почему воду лунных колодцев переносят по Тельдрассилу?",a="Друиды и жрицы следят за Тельдрассилом и питают его водой лунных колодцев. Перенос воды между колодцами помогает поддерживать их благословения на неспокойных ветвях недавно выросшего Мирового Древа.",al={"why transport moonwell water","purpose of the water","why move water","зачем переносить воду лунного колодца","назначение воды","зачем носить воду"}}},fp="23,257,17.421.0,18.376.0,26.135.0,32.190.0,29.161.0,52.216.0"}
P.entries["item:pendant-of-shadow"] = {n="Подвеска Тени",s="Подвеска Тени — темный талисман, который носил отступник-чернокнижник Моргант на вершине Башни Илгалара в Красногорье. Ее приносят магу Теокриту в Башню Азоры как неоспоримое доказательство того, что чародей-отступник уничтожен, прежде чем его зловещие замыслы осуществились.",h="Подвеска Тени — темный талисман, который носил отступник-чернокнижник Моргант на вершине Башни Илгалара в...",kw={"morganth","pendant of shadow","redridge","scythe of elune","theocritus","tower of azora","tower of ilgalar","моргант","подвеска тени","красногорье","коса элуны","теокрит","башня азоры","башня илгалара"},ang={["class:Mage"]="Возвращение темного талисмана по поручению Теокрита подчеркивает постоянную ответственность магов — следить за безрассудными чародеями-отступниками, угрожающими королевству.",["class:Warlock"]="Моргант олицетворяет опасность чрезмерного внимания со стороны Башни Азоры при поиске неустойчивых запретных артефактов, таких как Коса Элуны."},sec={{t="Знак темного чернокнижника",b="Подвеска Тени, которую носил отступник-чернокнижник Моргант в своем убежище в Башне Илгалара, пропитана темным колдовством. Моргант стремился разгадать тайны Косы Элуны, древней реликвии огромной и неустойчивой силы. Опасаясь бедствий, которые чернокнижник мог обрушить на Красногорье и королевство Штормград, маг Теокрит поручил искателям приключений проникнуть в Илгалар, положить конец замыслам Морганта и отнять у него талисман как доказательство его гибели."}},faq={{q="Где найти Подвеску Тени?",a="Подвеску носит чернокнижник Моргант, живущий на самой вершине Башни Илгалара на северо-востоке Красногорья.",al={"pendant of shadow location","where is pendant of shadow","how to get pendant of shadow","где подвеска тени","где найти подвеску тени","как получить подвеску тени"}},{q="Кому нужна Подвеска Тени?",a="Талисман нужно принести волшебнику Теокриту, живущему в Башне Азоры на востоке Элвиннского леса.",al={"who takes pendant of shadow","turn in pendant of shadow","theocritus pendant","кто принимает подвеску тени","сдать подвеску тени","теокрит подвеска"}},{q="Зачем Теокриту эта подвеска?",a="Теокриту нужна подвеска как осязаемое доказательство того, что Моргант убит и его погоня за опасной Косой Элуны закончена.",al={"why theocritus wants it","purpose of pendant of shadow","зачем она теокриту","назначение подвески тени"}},{q="Какую угрозу представлял Моргант с этой подвеской?",a="Моргант искал неуловимую Косу Элуны. Теокрит опасался, что, если темный чернокнижник завладеет артефактом, он обрушит чудовищную силу на Красногорье и окрестные земли.",al={"what was morganth doing","morganth lore","что делал моргант","предания о морганте"}}},fp="17,310,23.500.0,38.135.0,32.122.0,38.160.0,47.209.0"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Подвеска Морского Льва",s="Подвеска Морского Льва — священный талисман друидов, воплощающий союз подводной ловкости и выносливости. Ее собирают в Святилище Ремулоса на Лунной поляне, и она служит доказательством того, что неофит готов овладеть водным обликом.",h="Подвеска Морского Льва — священный талисман друидов, воплощающий союз подводной ловкости и выносливости.",kw={"aquatic form","dendrite starblaze","mathrengyl bearwalker","moonglade","pendant of the sea lion","remulos","turak runetotem","водный облик","дендрит блеск звезд","матренгил медвежья лапа","лунная поляна","подвеска морского льва","ремулос","тюрак рунический тотем"},ang={["class:Druid"]="Сборка этого талисмана — важная веха в обучении друида: она открывает способность дышать под водой и быстро плавать в облике морского льва.",["race:Tauren"]="Для шу'хало, идущих путем Круга Кенария, возвращение подвески Тюраку Руническому Тотему чтит и предков, и учения Лунной поляны."},sec={{t="Знак глубин",b="Чтобы обрести водный облик морского льва, друид должен доказать, что овладел главными опасностями воды. Подвеску создают из двух частей: одна воплощает ловкость, нужную, чтобы ускользать от подводных хищников, а другая дает выносливость, необходимую, чтобы долго оставаться под водой. У Святилища Ремулоса на Лунной поляне эти две части соединяют в одно целое."},{t="Доказательство мастерства",b="Выкованную подвеску приносят старшим наставникам — например, Тюраку Руническому Тотему на возвышенностях Громового Утеса или Матренгил Медвежья Лапа в Дарнассе. Талисман служит неоспоримым доказательством испытаний неофита под руководством Дендрита Блеска Звезд и позволяет старейшинам открыть секреты превращения в водный облик."}},faq={{q="Для чего нужна Подвеска Морского Льва?",a="Она служит доказательством того, что неофит-друид прошел испытания водной ловкости и выносливости и готов освоить водный облик.",al={"what does pendant of the sea lion do","sea lion pendant use","why get pendant of the sea lion","что дает подвеска морского льва","применение подвески морского льва","зачем нужна подвеска морского льва"}},{q="Где собирают подвеску?",a="Две половины — ловкость и выносливость — нужно соединить в Святилище Ремулоса в священной обители Лунной поляны.",al={"how to make sea lion pendant","where combine pendant halves","как сделать подвеску морского льва","где соединить половины подвески"}},{q="Кому в Громовом Утесе нужно вручить подвеску?",a="Друиды-таурены вручают готовую подвеску Тюраку Руническому Тотему на Вершине Старейшин в Громовом Утесе, чтобы завершить обучение.",al={"who takes pendant thunder bluff","turak runetotem pendant","horde aquatic form turn in","кто принимает подвеску громовой утес","тюрак рунический тотем подвеска","водный облик орда сдать"}},{q="Могут ли ночные эльфы тоже получить эту подвеску?",a="Да. Друиды-ночные эльфы проходят то же испытание на Лунной поляне, но приносят собранную подвеску Матренгил Медвежья Лапа в Дарнассе.",al={"alliance sea lion pendant","darnassus sea lion pendant","подвеска морского льва альянс","подвеска морского льва дарнасс"}}},fp="23,237,19.408.0,16.338.0,51.166.0,31.148.0,49.125.0,39.138.0"}
P.entries["item:perenolde-tiara"] = {n="Тиара Перенольда",s="Тиара Перенольда — украшенная изумрудами семейная реликвия павшего королевского дома Альтерака, изначально созданная дворфийскими мастерами Стальгорна. Утерянная при разрушении королевства, она в итоге попала в алчные руки огра, бродившего среди руин, а затем привлекла интерес коллекционеров Штормграда.",h="Тиара Перенольда — украшенная изумрудами семейная реликвия павшего королевского дома Альтерака, изначально...",kw={"alterac","emeralds","grel'borg","ironforge","miser","perenolde","remington","ridgewell","tiara","альтерак","изумруды","грел'борг","стальгорн","скряга","перенольд","ремингтон","риджвелл","тиара"},ang={["faction:Alliance"]="Артефакт — горькое напоминание о доме Перенольдов, чье предательство во Второй войне едва не уничтожило первоначальный Альянс Лордерона.",["race:Dwarf"]="Тиара свидетельствует о прославленном ювелирном искусстве Стальгорна, чьи мастера гранили и оправляли изумруды для человеческой знати севера."},sec={{t="Реликвия разрушенного королевства",b="До того как горное королевство Альтерак бесславно рухнуло в руины во время Второй войны, им правил дом Перенольдов. Среди их сокровищ была эта изящная тиара, заказанная у лучших ювелиров Стальгорна и украшенная сверкающими изумрудами. Когда Альтерак пал после предательства короля Эйдена Перенольда, главная драгоценность исчезла в хаосе разорения высоких скал."},{t="Добыча скряги",b="Тиара не осталась навечно погребенной под снегом: ее откопал Грел'борг Скряга, огр-маг, роющийся в руинах Альтерака в поисках брошенных богатств. Весть об уцелевшей реликвии дошла до графа Ремингтона Риджвелла, богатого дворянина из Штормграда, жаждущего приобретать знаменитые реликвии для семейного музея, и начались поиски, чтобы вырвать тиару из цепких рук огра."}},faq={{q="Что такое Тиара Перенольда?",a="Это семейная реликвия, некогда принадлежавшая королевскому роду Перенольдов из Альтерака. Ее создали мастера-ювелиры дворфов из Стальгорна и украсили тонкими изумрудами, после чего она была потеряна при падении Альтерака.",al={"perenolde tiara lore","what is this tiara","alterac tiara","предания о тиаре перенольда","что это за тиара","тиара альтерака"}},{q="У кого сейчас тиара?",a="Огр-маг по имени Грел'борг Скряга нашел тиару среди заснеженных руин Альтерака. Он ревниво охраняет ее, обыскивая разрушенное королевство в поисках других потерянных сокровищ.",al={"where is the tiara","who drops the tiara","grelborg tiara","где тиара","с кого падает тиара","грел'борг тиара"}},{q="Зачем графу Ремингтону Риджвеллу тиара?",a="Граф Ремингтон Риджвелл собирает исторические и ценные древности для семейного музея в Штормграде. Подлинная главная драгоценность павшего человеческого королевства станет внушительным центром его коллекции.",al={"who wants the tiara","why does remington want it","remington ridgewell motive","кому нужна тиара","зачем ремингтону тиара","мотив ремингтона риджвелла"}},{q="Кто такие Перенольды?",a="Перенольды были правящей династией королевства Альтерак. Во время Второй войны король Эйден Перенольд предал Альянс и перешел на сторону Орочьей Орды, что привело к падению и гибели его державы.",al={"perenolde family","house of perenolde","rulers of alterac","семья перенольд","дом перенольд","правители альтерака"}}},fp="15,311,27.406.0,17.401.0,28.211.0,28.183.0,43.223.0,24.209.0"}
P.entries["item:phial-of-scrying"] = {n="Фиал Виденья",kw={"darkshore","master's glaive","onu","phial of scrying","scrying bowl","twilight's hammer","темные берега","меч властителя","ону","фиал виденья","чаша для наблюдения","сумеречный молот"},ang={["class:Druid"]="Друиды видят в чашах для наблюдения гармоничное сочетание природной воды и магии общения, позволяющее стражам леса обмениваться шепотом над оскверненной землей.",["race:NightElf"]="Для ночных эльфов Темных берегов древние средства прорицания, такие как воды видения, жизненно важны для охраны священных лесов от чужеродных культов."},sec={{t="Взор через Темные берега",b="Фиал Виденья вверяют разведчикам, исследующим глубины Темных берегов. В нем хранится волшебная вода, создающая на земле временную чашу для наблюдения. Это средство позволяет гадать на большом расстоянии, и путники, отправившиеся в опасные места вроде Меча Властителя, могут говорить с Ону напрямую, не возвращаясь сразу в его рощу."},{t="Раскрытие культа",b="Ону дает фиал специально для того, чтобы следить за тревожным присутствием культистов Сумеречного Молота. Установив связь через чашу в месте, где огромный меч пронзил древнего павшего властителя, разведчик убеждается, что темные культисты собираются у древних останков в поисках крупиц забытой силы, которая таится даже в смерти."}},faq={{q="Для чего нужен Фиал Виденья?",a="When uncorked, the phial manifests a magical scrying bowl on the ground, allowing an adventurer in the field to contact and speak with the ancient of lore Onu across vast distances.",al={"use phial of scrying","scrying bowl function","what is this phial for","использовать фиал виденья","как работает чаша для наблюдения","для чего этот фиал"}},{q="Кто выдает Фиал Виденья?",a="Древний лесной страж Ону вверяет фиал разведчикам в Темных берегах, когда поручает им разведать Меч Властителя на юге.",al={"who gives phial of scrying","where do i get the phial","кто дает фиал виденья","где взять фиал"}},{q="Что будет, если фиал потерян или израсходован?",a="Если фиал потерян или использован до выполнения вашей задачи, Ону может выдать другой, пока медитирует в Темных берегах.",al={"lost phial of scrying","get another phial","replace phial","потерял фиал виденья","получить другой фиал","заменить фиал"}},{q="Почему Ону наблюдает за Мечом Властителя?",a="Onu knows the Master's Glaive is where an old lord fell and asks you to search for Twilight's Hammer cultists there. Their purpose is revealed as the investigation continues.",al={"why scry master's glaive","onu glaive mission","почему наблюдать за мечом властителя","задание ону меч властителя"}}},fp="16,194,23.356.0,19.359.1,34.181.0,34.136.0,47.121.0,44.174.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Кусок знамени Кром'зара",s="Рваный лоскут ткани со знамен полководца Кром'зара, командира карательного отряда Колкаров. Он служит Регтару Врата Смерти осязаемым доказательством того, что вторжение кентавров из Пустошей сломлено.",h="Рваный лоскут ткани со знамен полководца Кром'зара, командира карательного отряда Колкаров.",kw={"banner","centaur","counterattack","crossroads","deathgate","kolkar","krom'zar","regthar","знамя","кентавр","ответный удар","перекресток","врата смерти","колкар","кром'зар","регтар"},ang={["faction:Horde"]="Победа над Кром'заром и захват его знамени останавливают крупное наступление кентавров и защищают северные пути между Дуротаром, Мулгором и Перекрестком.",["race:Tauren"]="Агрессия кентавров давно терзает кочевые племена, поэтому уничтожение авангарда Кром'зара — отрадный знак безопасности на тропах к Мулгору."},sec={{t="Трофей после набега кентавров",b="После планомерного разгрома вождей Колкаров в Степях разъяренный отряд двинулся на восток из Пустошей, жаждя мести. Захватчики под предводительством полководца Кром'зара напали на оборонительные блиндажи к западу от Перекрестка. Лоскут павшего боевого знамени полководца — неоспоримое доказательство для Регтара Врата Смерти того, что нападение отбито, а южные торговые пути сохранены для Орды."}},faq={{q="Для чего нужен этот кусок знамени?",a="Рваную ткань приносят Регтару Врата Смерти в его блиндаж к западу от Перекрестка. Она доказывает, что полководец Кром'зар убит, а его отряд разгромлен, и завершает оборону северных Степей.",al={"banner purpose","why keep banner","what do i do with banner piece","для чего знамя","зачем хранить знамя","что делать с куском знамени"}},{q="Кто такой полководец Кром'зар?",a="Кром'зар был свирепым командиром Колкаров, посланным из земель Пустошей. Он повел прямой ответный удар по заставам Орды в ответ на гибель местных вождей Колкаров.",al={"who is kromzar","krom'zar lore","warlord krom'zar","кто такой кромзар","кром'зар предание","полководец кром'зар"}},{q="Почему Колкары напали на блиндаж?",a="После того как защитники Орды уничтожили местных вождей Степей, включая Барака, Верога и Хезрула, разъяренные кентавры призвали подкрепление из Пустошей, чтобы отомстить Орде к западу от Перекрестка.",al={"why counterattack","kolkar invasion why","barrens counterattack reason","почему ответный удар","почему вторжение колкаров","причина нападения в степях"}},{q="Узнает ли Тралл об этой победе?",a="Да. Получив обрывок знамени, Регтар Врата Смерти обещает направить официальное донесение прямо вождю Траллу в Оргриммар, отметив защитников, сорвавших вторжение.",al={"thrall reward","does thrall know","награда от тралла","знает ли тралл"}}},fp="26,216,31.423.0,35.207.0,25.182.0,37.222.0,33.178.0"}
P.entries["item:plainstrider-beak"] = {n="Клюв долгонога",s="Клювы долгоногов добывают у высоких нелетающих птиц, бродящих по кустарниковым равнинам Степей. Мастера охоты на Перекрестке собирают эти клювы как доказательство того, что охотник истребил местных птиц, угрожающих запасам поселения.",h="Клювы долгоногов добывают у высоких нелетающих птиц, бродящих по кустарниковым равнинам Степей.",kw={"barrens","crossroads","plainstrider beak","plainstrider menace","sergra darkthorn","tallstrider","степи","перекресток","клюв долгонога","угроза долгоногов","сергра черный шип","долгоног"},ang={["class:Hunter"]="Охота на долгоногов и добыча их клювов дает начинающим следопытам вводный урок выслеживания и добычи зверя на открытых равнинах Калимдора.",["faction:Horde"]="Истребление докучливых стай к востоку от Перекрестка напрямую защищает хрупкие торговые пути и пути снабжения, которые кормят заставу Орды."},sec={{t="Мера охоты",b="Обширные саванны вокруг Перекрестка населяют разные виды долгоногов, в том числе крупные, проворные и норовистые. Хотя это сравнительно простая добыча по сравнению с более свирепыми зверями центрального Калимдора, их назойливые поиски корма делают их постоянной помехой для поселений. Сергра Черный Шип поручает прибывающим охотникам принести Клювы долгоногов, чтобы подтвердить, что стаю отогнали от важных путей снабжения и складов."}},faq={{q="Зачем Сергре Черный Шип нужны Клювы долгоногов?",a="Сергра Черный Шип просит охотников истреблять долгоногов, потому что агрессивные птицы регулярно разоряют запасы еды вокруг Перекрестка. Клювы служат осязаемым доказательством удачной охоты и подтверждают, что угроза путям снабжения уменьшилась.",al={"why collect beaks","sergra plainstrider beak quest","why beaks","зачем собирать клювы","задание сергры клюв долгонога","зачем клювы"}},{q="С каких существ можно получить эти клювы?",a="Их добывают у разных видов долгоногов, бродящих по саванне, включая крупных, проворных и норовистых долгоногов в Степях.",al={"what drops plainstrider beaks","plainstrider beak sources","where to get beaks","с кого падают клювы долгонога","источники клюва долгонога","где взять клювы"}},{q="Почему не со всех долгоногов выпадает клюв?",a="В хаосе боя, особенно с быстрыми и бьющимися птицами, клюв часто трескается, разбивается или становится непригодным как охотничий трофей, поэтому собирают только целые экземпляры.",al={"why bad drop rate","plainstrider beak not dropping","низкий шанс выпадения","клюв долгонога не падает"}}},fp="17,249,21.464.0,50.264.0,34.174.0,54.199.0"}
P.entries["item:plainstrider-feather"] = {n="Перо долгонога",s="Перья долгонога, выщипанные у быстрых птиц равнин Мулгора, — важный материал, который собирают юные охотники на плато Красного Облака. Таурены Лагеря Нараче используют их в основном для изготовления одежды и племенных украшений, почитая существ, что кормят селение.",h="Перья долгонога, выщипанные у быстрых птиц равнин Мулгора, — важный материал, который собирают юные охотники...",kw={"camp narache","feather","grull hawkwind","mulgore","plainstrider","red cloud mesa","the hunt begins","лагерь нараче","перо","грулл соколиный ветер","мулгор","долгоног","плато красного облака","начинается охота"},ang={["class:Hunter"]="Выслеживание быстрых долгоногов на плато Красного Облака — основное испытание новичка в терпении, выслеживании и почитании добычи.",["race:Tauren"]="Для юного таурена сбор перьев долгонога — важный первый урок: не принимать как должное ничего от созданий Матери-Земли и использовать каждую часть добычи для пищи и одежды."},sec={{t="Первое подношение охотника",b="На плато Красного Облака юные таурены рано узнают, что выживание зависит от меткого выслеживания и охоты. Долгоноги бегают на воле по травянистому плато, давая и пищу, и полезные материалы. Из их прочных перьев в лагере делают традиционную одежду и снаряжение. Принести эти перья вместе со свежим мясом Груллу Соколиному Ветру — значит выказать уважение к нуждам племени и пройти самое первое испытание на пути к признанию вождем Соколиным Ветром и встрече в Громовом Утесе."}},faq={{q="Для чего нужны Перья долгонога?",a="Таурены Лагеря Нараче используют их в основном для изготовления одежды и обрядовых предметов. Грулл Соколиный Ветер собирает их у начинающих охотников, чтобы пополнить племенные запасы.",al={"feather purpose","plainstrider feather use","why collect feathers","для чего перья","применение пера долгонога","зачем собирать перья"}},{q="Кто собирает Перья долгонога на плато Красного Облака?",a="Грулл Соколиный Ветер просит их от имени Лагеря Нараче, чтобы пополнить запасы селения и проверить, хватает ли юным охотникам дисциплины, чтобы обеспечивать племя.",al={"who wants feathers","who needs feathers","grull hawkwind feathers","кому нужны перья","кто просит перья","перья грулл соколиный ветер"}},{q="Где можно найти долгоногов?",a="Они бродят по открытым лугам плато Красного Облака и по холмистым равнинам Мулгора.",al={"where to find plainstriders","plainstrider location","feather farm","где найти долгоногов","местонахождение долгоногов","добыча перьев"}},{q="Зачем Груллу Соколиному Ветру эти перья для племенных обрядов?",a="Охота — основа культуры тауренов, ею занимаются и ради выживания, и ради состязания. Вернувшись с мясом и оперением, посвящаемый доказывает вождю Соколиному Ветру, что может прокормить племя, прежде чем отправиться дальше в Громовой Утес.",al={"the hunt begins lore","proving hunt tauren","why hunt plainstriders","начинается охота предание","испытание охотой таурены","зачем охотиться на долгоногов"}}},fp="20,300,25.496.0,40.164.0,52.172.0,33.97.0,64.234.0"}
P.entries["item:plainstrider-kidney"] = {n="Почка долгонога",s="Орган, добытый у быстроногих долгоногов, бродящих по засушливым равнинам Степей. Хотя большинству путников он кажется неаппетитным, он служит странным, но важным ингредиентом в необычных пивоваренных традициях Калимдора.",h="Орган, добытый у быстроногих долгоногов, бродящих по засушливым равнинам Степей.",kw={"brewmaster drohn","chen stormstout","plainstrider","plainstrider kidney","ratchet","stormstout","the barrens","пивовар дрон","чэнь буйный портер","долгоног","почка долгонога","кабестан","буйный эль","степи"},ang={["class:Hunter"]="Свежевание долгоногов в саванне проверяет меткость охотника: внутренние органы должны остаться целыми для обмена с пивоварами Кабестана.",["profession:Cooking"]="Кулинары-путешественники могут поморщиться при мысли о брожении птичьих почек в хороший напиток, но выживание в диком Калимдоре часто зависит от использования каждой части добычи."},sec={{t="Необычный ингредиент для пива",b="Обширные просторы Степей населяют высокие нелетающие птицы — долгоноги. Охотники забирают их перья и мясо для инструментов и простых пайков, но Пивовар Дрон из Кабестана ищет их внутренние органы для совсем иной цели. По словам эксцентричного пивовара, почки долгонога необходимы, чтобы воссоздать легендарный крепкий эль Чэня Буйного Портера: они придают особую остроту, передающуюся через необычную череду пивоваров."}},faq={{q="Для чего нужна Почка долгонога?",a="Пивовару Дрону из Кабестана они нужны, чтобы воссоздать легендарную партию эля Буйный эль. Он утверждает, что рецепт напрямую его наставнику передал странствующий пандарен-пивовар Чэнь Буйный Портер.",al={"plainstrider kidney use","why do i need plainstrider kidneys","plainstrider kidney purpose","применение почки долгонога","зачем мне почки долгонога","для чего почка долгонога"}},{q="Зачем варить эль с органами животных?",a="Экзотические напитки в Калимдоре часто содержат крепкие части местных диких животных, чтобы получить насыщенный, запоминающийся вкус и особую крепость. Пивовар Дрон отмечает, что создание таких мощных диких рецептов с теплотой напоминает ему о необычных творениях, например о пиве троггов.",al={"kidney in beer","why kidney in stormstout","animal parts in alcohol","почка в пиве","зачем почка в буйном эле","части животных в алкоголе"}},{q="С каких существ можно получить эти почки?",a="Их добывают у разных видов долгоногов, бегающих по Степям, включая проворных, норовистых и крупных долгоногов.",al={"where do plainstrider kidneys drop","who drops plainstrider kidney","plainstrider kidney source","где падают почки долгонога","с кого падает почка долгонога","источник почки долгонога"}},{q="Какие еще ингредиенты нужны вместе с почками?",a="Чтобы завершить свое варево, Пивовар Дрон просит пять почек долгонога, пять клыков саванного льва и один рог громоящера.",al={"other brew ingredients","what else does drohn need","stormstout ingredients","другие ингредиенты для пива","что еще нужно дрону","ингредиенты буйного эля"}}},fp="19,224,32.498.0,39.200.0,46.250.0,36.143.0,56.140.0"}
P.entries["item:plainstrider-meat"] = {n="Мясо долгонога",s="Мясо долгонога — свежая дичь, добытая из нелетающих птиц, что бродят по равнинам Мулгора. Для молодых таурен, достигающих зрелости на Плато Красного Облака, добыча этой пищи — и жизненно важный зимний запас, и основной обряд посвящения.",h="Мясо долгонога — свежая дичь, добытая из нелетающих птиц, что бродят по равнинам Мулгора.",kw={"camp narache","chief hawkwind","grull hawkwind","mulgore","plainstrider","plainstrider meat","red cloud mesa","the hunt begins","лагерь нараче","вождь соколиный ветер","грулл соколиный ветер","мулгор","долгоног","мясо долгонога","плато красного облака","охота начинается"},ang={["class:Hunter"]="Быстрый долгоног дает начинающим охотникам первое испытание в выслеживании и меткости на открытых равнинах Мулгора.",["race:Tauren"]="Для юных таурен, впервые выходящих на Плато Красного Облака, охота на долгоногов — первый практический шаг к уважению вождя Соколиного Ветра и праву войти в Громовой Утес."},sec={{t="Пища для плато",b="Жизнь таурен неразрывно связана с землей: они уважают природу, но должны и выживать. На Плато Красного Облака поселение Лагерь Нараче во многом зависит от дичи, добытой на окрестных равнинах. Мясо долгонога служит важным запасом пищи для деревни, когда припасы истощаются, а оперение птиц идет на одежду и обрядовые украшения."},{t="Испытание юного охотника",b="Охота на долгоногов — одно из первых испытаний для юношей, стремящихся заслужить уважение племени. Грулл Соколиный Ветер посылает начинающих охотников выслеживать быстрых птиц на плато и собирать мясо и перья, чтобы доказать свое умение выслеживать и самостоятельность, прежде чем предстать перед его отцом, вождем Соколиным Ветром."}},faq={{q="Для чего нужно Мясо долгонога?",a="Мясо долгонога собирают молодые охотники на Плато Красного Облака, чтобы пополнить истощенные запасы пищи Лагеря Нараче. Это важное поручение Грулла Соколиного Ветра.",al={"why plainstrider meat","plainstrider meat quest","what do i do with plainstrider meat","зачем мясо долгонога","задание мясо долгонога","что делать с мясом долгонога"}},{q="Кто просит это мясо?",a="Грулл Соколиный Ветер, сын вождя Соколиного Ветра, поручает новичкам охотиться на долгоногов на плато, чтобы пополнить запасы пищи племени и доказать, что они достойные добытчики.",al={"who wants plainstrider meat","grull hawkwind meat","кто хочет мясо долгонога","грулл соколиный ветер мясо"}},{q="Где можно найти Мясо долгонога?",a="Его добывают из нелетающих долгоногов, бродящих по равнинам Мулгора, особенно на холмах Плато Красного Облака.",al={"where to get plainstrider meat","plainstrider locations","farm plainstrider meat","где взять мясо долгонога","где водятся долгоноги","добыча мяса долгонога"}},{q="Почему охота на долгоногов так важна для таурен?",a="Таурены охотятся и по практической необходимости, и ради духовной практики. Принести дичь в лагерь — значит проявить уважение к Матери-Земле, самостоятельность и способность прокормить племя.",al={"tauren hunting culture","why hunt plainstriders","охота таурен","зачем охотиться на долгоногов"}}},fp="17,257,23.401.0,22.311.0,35.162.0,23.166.0,37.138.0,64.202.0"}
P.entries["item:plainstrider-scale"] = {n="Чешуя долгонога",s="Прочная чешуя, которую добывают у долгоногов, бродящих по просторным равнинам Мулгора. Она служит важным компонентом традиционного лекарства, которое готовит Маур Заклинатель Дождя, чтобы побороть опасную инфекцию.",h="Прочная чешуя, которую добывают у долгоногов, бродящих по просторным равнинам Мулгора.",kw={"bloodhoof village","maur raincaller","mazzranache","mulgore","plainstrider","remedy","scale","tallstrider","деревня кровавого копыта","маур заклинатель дождя","маззранач","мулгор","долгоног","снадобье","чешуя","долгонога"},ang={["race:Tauren"]="Сбор лекарств из даров земли отражает традиционные навыки выживания, которым учат юных охотников Мулгора: использовать каждую часть животных равнин, чтобы поддерживать племя."},sec={{t="Редкий ингредиент",b="Долгоногов лучше всего знают по мягким перьям и постному мясу, но их мощные ноги покрыты прочной защитной чешуей. Она выдерживает суровую местность и когти хищников. Найти целую чешуйку, пригодную для лекарства, непросто: лишь у некоторых долгоногов Мулгора чешуя достаточно твердая, чтобы ее растереть и приготовить народные снадобья."},{t="Снадобье от ядовитого укуса",b="Когда Маур Заклинатель Дождя из Деревни Кровавого Копыта столкнулся с Маззраначем — легендарным долгоногом с демоническими красными глазами и ядовитым укусом, — он получил тяжелую рану в плечо. Впав в горячечный бред, Маур нуждается в Чешуе долгонога, а также в сердце волка, бедренной кости пумы и потрохах перепелятника, чтобы очистить распространяющуюся инфекцию, пока она не стала смертельной."}},faq={{q="Для чего нужна Чешуя долгонога?",a="Это важный лекарственный ингредиент, который собирают для Маура Заклинателя Дождя в Деревне Кровавого Копыта. Вместе с частями других хищников Мулгора из нее варят снадобье от зараженной ядовитой раны, нанесенной бешеным долгоногом Маззраначем.",al={"what does plainstrider scale do","plainstrider scale use","why need plainstrider scale","для чего чешуя долгонога","применение чешуи долгонога","зачем нужна чешуя долгонога"}},{q="Где найти Чешую долгонога?",a="Чешую добывают, охотясь на диких долгоногов, бродящих по открытым равнинам Мулгора.",al={"where to get plainstrider scale","how to get plainstrider scale","plainstrider scale location","где взять чешую долгонога","как получить чешую долгонога","чешуя долгонога где"}},{q="Почему Маур Заклинатель Дождя заразился?",a="Во время странствий по равнинам на Маура напал Маззранач, жуткий долгоног, известный ядовитым укусом и багровыми глазами, и укусил его в плечо. После укуса у него началась усиливающаяся горячка с бредом, которую не излечить обычным отдыхом.",al={"how did maur get sick","why is maur sick","mazzranache bite","как маур заболел","почему маур болен","укус маззранача"}},{q="Какие еще ингредиенты нужны Мауру для снадобья?",a="Помимо Чешуи долгонога, Мауру нужны Сердце койота, Бедренная кость пумы плоскогорья и Потроха перепелятника, чтобы завершить лекарственную смесь.",al={"maur raincaller ingredients","cure for mazzranache","mazzranache quest items","ингредиенты маура заклинателя дождя","лекарство от маззранача","предметы задания маззранач"}}},fp="18,201,17.395.0,28.371.1,40.252.0,39.107.0,32.247.0,53.149.0"}
P.entries["item:plainstrider-talon"] = {n="Коготь долгонога",s="Коготь долгонога — острый коготь крупных нелетающих долгоногов, обитающих в Мулгоре. Шаманы таурен используют такие когти вместе с другими природными реагентами для создания священных очищающих тотемов, когда водные источники земли оскверняются.",h="Коготь долгонога — острый коготь крупных нелетающих долгоногов, обитающих в Мулгоре.",kw={"bloodhoof village","cleansing totem","mulgore","mull thunderhorn","plainstrider","plainstrider talon","poison water","winterhoof water well","деревня кровавого копыта","очищающий тотем","мулгор","мулл громовой рог","долгоног","коготь долгонога","отравленная вода","колодец заиндевевшего копыта"},ang={["class:Shaman"]="Использование частей зверей, например когтей, для создания очищающих тотемов — пример традиционной шаманской практики таурен, черпающей силу прямо из местных духов земли.",["race:Tauren"]="Почтение к жертве животных Мулгора — основа охоты таурен: каждый добытый зверь помогает исцелить Мать-Землю, когда ей вредит гоблинская эксплуатация."},sec={{t="Узы равнин",b="Крупные нелетающие долгоноги бродят по открытым степям Мулгора и защищаются от хищников сильными ногами и острыми когтями, а также ищут корм в жесткой земле прерий. Для таурен Деревни Кровавого Копыта каждая часть убитого зверя несет духовный отклик. Когда гоблины осквернили священные источники вроде Колодца Заиндевевшего Копыта, шаман Мулл Громовой Рог стал искать когти долгонога и лапы койота. В обрядовом ремесле таурен сбор реагентов у местных хищников и собирателей позволяет направить духовную суть земли в тотемы, способные изгнать неестественные яды."}},faq={{q="С каких существ выпадает Коготь долгонога?",a="Когти долгонога добывают у взрослых долгоногов, старых долгоногов и печально известного Маззранача на равнинах Мулгора.",al={"who drops plainstrider talon","where to get plainstrider talons","plainstrider talon source","с кого падает коготь долгонога","где взять когти долгонога","источник когтей долгонога"}},{q="Для чего нужны Когти долгонога?",a="Мулл Громовой Рог из Деревни Кровавого Копыта просит когти долгонога и лапы койота, чтобы создать очищающий тотем, которым очищают оскверненный Колодец Заиндевевшего Копыта.",al={"plainstrider talon use","why do i need talons","plainstrider talon quest","применение когтя долгонога","зачем нужны когти","задание коготь долгонога"}},{q="Почему Мулл Громовой Рог использует части животных для очистки воды?",a="Шаманизм таурен основан на гармонии с природными духами Мулгора. Вплетая части местных животных в обрядовый тотем, шаман призывает сырую силу самой земли, чтобы бороться с чужеродными загрязнениями, принесенными гоблинами Торговой Компании.",al={"why animal paws and claws","shaman cleansing ritual talons","зачем лапы и когти","шаманский обряд очищения когти"}},{q="Кто отравил колодцы в Мулгоре?",a="Гоблины — в частности, агенты Торговой Компании, действующие в Мулгоре, — и их приспешники осквернили священные колодцы племен, нарушив местную природу и угрожая племенам таурен.",al={"who tainted the wells","who poisoned mulgore water","poison water culprit","кто осквернил колодцы","кто отравил воду мулгора","виновник отравления воды"}}},fp="18,249,19.620.0,41.151.0,38.177.0,63.258.0,40.205.0"}
P.entries["item:podrig-s-order"] = {n="Заказ Подрига",s="Заказ Подрига — письменная военная заявка, составленная Стражем смерти Подригом в Гробнице. В ней запрашивается новая партия оружия у торговца Подгорода Гордона Уиндема, чтобы гарнизон Отрекшихся в Серебряном бору был надлежащим образом вооружен.",h="Заказ Подрига — письменная военная заявка, составленная Стражем смерти Подригом в Гробнице.",kw={"gordon wendham","hadrec","karos razok","podrig","podrig's order","sepulcher","silverpine","гордон уиндем","хадрик","карос раззок","подриг","заказ подрига","гробница","серебряный бор"},ang={["profession:Blacksmithing"]="Кованое оружие жизненно важно на передовой, где постоянные бои неуклонно истощают запасы гарнизона.",["race:Undead"]="Заявка показывает, что Подгород — снабженческая артерия для дальних застав вроде Гробницы: она обеспечивает воинов Темной Госпожи оружием против Плети."},sec={{t="Вооружение Гробницы",b="Серебряный бор — опасное приграничье для Отрекшихся, зажатых между наступающей Плетью, дикими зверями и другими скрытыми угрозами. После проверки снаряжения, проведенной Стражем смерти Подригом по приказу Палача Хадрика, выяснилось, что запасы Гробницы в основном достаточны, но заменяемого оружия отчаянно не хватает. Это официальное донесение перечисляет клинки и вооружение, необходимые Стражам смерти, удерживающим форпост."},{t="Доставка через повелителя летучих мышей",b="Поскольку в сырых склепах Серебряного бора оружие не выковать, заявка адресована Гордону Уиндему, торговцу оружием из шумного Торгового квартала Подгорода. Чтобы ускорить заказ, гонцы относят документ прямо укротителю летучих мышей Каросу Раззоку, пользуясь воздушными маршрутами Отрекшихся, чтобы быстро получить припасы из столицы."}},faq={{q="Что написано в Заказе Подрига?",a="Это официальная заявка со списком оружия на замену, необходимого Стражам смерти в Гробнице после обычных потерь в боях.",al={"what does the order say","contents of podrig's order","podrig order details","что написано в заказе","содержание заказа подрига","подробности заказа подрига"}},{q="Кто написал Заказ Подрига?",a="Его составил Страж смерти Подриг по указанию Палача Хадрика после проверки оружейной Гробницы.",al={"who wrote it","author of podrig order","кто написал","автор заказа подрига"}},{q="Кому предназначен заказ?",a="Он предназначен Гордону Уиндему, торговцу оружием, ведущему дела в Торговом квартале Подгорода.",al={"who gets the order","where does podrig order go","recipient of podrig order","кто получает заказ","куда идет заказ подрига","получатель заказа подрига"}},{q="Почему Гробнице нужно новое оружие?",a="Постоянные стычки с Плетью и другими враждебными силами в Серебряном бору часто приводят к поломке или потере снаряжения у защищающих Гробницу Стражей смерти.",al={"why need weapons","sepulcher weapon shortage","зачем оружие","нехватка оружия гробница"}}},fp="14,228,20.431.0,24.366.0,34.139.0,25.133.0,23.106.0,40.164.0"}
P.entries["item:pork-belly-pie"] = {n="Пирог со свининой",s="Пирог со свининой — сытное домашнее блюдо, которое печет «тетушка» Бернис Стоунфилд в Элвиннском лесу. Несмотря на давнюю и злую вражду семей Стоунфилдов и Маклюров, юный Билли Маклюр не может устоять перед стряпней Тетушки Бернис и требует пирог в качестве взятки за сведения о пропавшей семейной реликвии.",h="Пирог со свининой — сытное домашнее блюдо, которое печет «тетушка» Бернис Стоунфилд в Элвиннском лесу.",kw={"auntie bernice stonefield","back to billy","billy maclure","elwynn forest","maclure","pork belly pie","stonefield","тетушка бернис стоунфилд","назад к билли","билли маклюр","элвиннский лес","маклюр","пирог со свининой","стоунфилд"},ang={["faction:Alliance"]="Для путников Альянса, помогающих сельскому Элвинну, такие поручения, как доставка пирогов, проливают свет на мелкие, но глубоко укоренившиеся распри в земледельческом сердце Штормграда.",["profession:Cooking"]="Пирог показывает, что домашняя утешительная еда может по-настоящему влиять на местные споры, пусть даже рецепт остается тщательно хранимым секретом Тетушки Бернис."},sec={{t="Взятка между враждующими фермами",b="Семьи Стоунфилдов и Маклюров годами питают злое соперничество, споря из-за земли и гордости в сердце Элвиннского леса. Несмотря на эту вражду, у юного Билли Маклюра есть явная слабость: он обожает знаменитый пирог Тетушки Бернис со свининой. Когда пропадает ценное семейное ожерелье, Билли отказывается говорить, что знает, пока искатель приключений не принесет ему теплый кусок. Бернис печет его с большой неохотой — и с колким пожеланием, чтобы жадный мальчишка подавился, — доказывая, что кулинарная слава порой пересиливает даже самую упрямую семейную вражду."}},faq={{q="Для чего нужен Пирог со свининой?",a="Пирог печет Тетушка Бернис Стоунфилд, чтобы подкупить юного Билли Маклюра. Билли знает важные подробности о пропавшем ожерелье — семейной реликвии Стоунфилдов, но отказывается говорить, пока не утолит аппетит стряпней Тетушки Бернис.",al={"pie use","why pork belly pie","what do i do with the pie","применение пирога","зачем пирог со свининой","что делать с пирогом"}},{q="Кто печет Пирог со свининой?",a="Свежий пирог печет Тетушка Бернис Стоунфилд на Ферме Стоунфилдов. Хотя она глубоко презирает Билли Маклюра и всю его семью, она все равно готовит его, чтобы вернуть потерянное ожерелье своей семьи.",al={"who made the pie","pie baker","granny stonefield pie","кто испек пирог","пекарь пирога","бабушка стоунфилд пирог"}},{q="Почему Билли Маклюр хочет еды от семьи соперников?",a="Несмотря на жестокую и шумную вражду Стоунфилдов и Маклюров, стряпня Тетушки Бернис хорошо известна по всей долине. Билли куда больше заботят его желудок и вкусная свинина, чем сохранение семейных обид.",al={"why billy wants pie","why maclure wants stonefield food","почему билли хочет пирог","почему маклюр хочет еду стоунфилдов"}},{q="Можно ли съесть Пирог со свининой?",a="Нет. Пирог — предмет задания, предназначенный только для Билли Маклюра. Вы не можете съесть его сами, чтобы восстановить здоровье или ману, как бы аппетитно он ни звучал.",al={"can i eat it","is pork belly pie edible","можно ли съесть","съедобен ли пирог со свининой"}}},fp="14,318,29.572.0,36.258.0,29.212.0,53.232.0,35.153.0"}
P.entries["item:powdered-azurite"] = {n="Толченый азурит",s="Толченый азурит — измельченный минеральный реагент, который добывают в Лазуритовом руднике в Предгорьях Хилсбрада. Он нужен мастеру-оружейнику Тун'гриму Огневзору для закалки и ковки доспехов жестокости для молодых воинов Орды.",h="Толченый азурит — измельченный минеральный реагент, который добывают в Лазуритовом руднике в Предгорьях...",kw={"azurelode mine","azurite","brutal armor","hillsbrad","powdered azurite","reagent","thun'grim firegaze","лазуритовый рудник","азурит","доспехи жестокости","хилсбрад","толченый азурит","реагент","тун'грим огневзор"},ang={["class:Warrior"]="Добыча толченого азурита проверяет вашу выносливость вдали от дома: вы собираете особые реагенты, которые нужны Тун'гриму Огневзору для ковки личных доспехов дикой мощи.",["faction:Horde"]="Чтобы добыть эту очищенную пыль, нужно проникнуть вглубь Восточных королевств и забрать ресурсы прямо из рук Альянса в Предгорьях Хилсбрада."},sec={{t="Редкое минеральное соединение",b="Толченый азурит — очищенная пыль из минеральных жил под Предгорьями Хилсбрада. Люди, работающие в Лазуритовом руднике, вгрызаются в землю, добывая этот особый синий камень, измельчают его и упаковывают для торговли и металлургии. В руках умелого кузнеца эта пыль служит важным флюсом или добавкой при работе с плотными металлами: она повышает прочность и придает готовым доспехам особую стойкость."},{t="Ковка доспехов жестокости",b="Хотя толченый азурит добывают в человеческих копях за Великим морем, опытные кузнецы Орды ценят его за исключительные металлургические свойства. Тун'грим Огневзор, стареющий орк-оружейник, живущий в Степях, требует небольшое количество измельченного камня вместе с очищенным железом и огненными реагентами. Добавленный в плавку порошок позволяет ему выковывать тяжелые, сокрушительные пластины, которыми отличаются его лучшие боевые доспехи."}},faq={{q="Для чего нужен толченый азурит?",a="Это важный металлургический компонент для Тун'грима Огневзора, мастера-оружейника из Степей. Он смешивает измельченный минерал с железными слитками и летучими реагентами, чтобы выковывать части доспехов жестокости для бойцов Орды.",al={"powdered azurite use","what is powdered azurite","применение толченого азурита","что такое толченый азурит"}},{q="Где найти толченый азурит?",a="Его добывают у шахтеров-людей, работающих в Лазуритовом руднике на южном побережье Предгорий Хилсбрада в Восточных королевствах.",al={"where to find powdered azurite","powdered azurite location","who drops powdered azurite","где найти толченый азурит","местонахождение толченого азурита","с кого падает толченый азурит"}},{q="Почему оружейнику из Степей нужны реагенты из Хилсбрада?",a="Тун'грим Огневзор ищет лучшие материалы, чтобы создавать доспехи, достойные легендарных воинов. Железо найти легко, но особые закалочные свойства лазуритовой руды стоят того, чтобы его бойцы отправлялись за ней через море.",al={"why hillsbrad","thungrim mineral source","почему хилсбрад","источник минерала тун'грима"}}},fp="16,217,23.418.0,20.454.0,34.245.0,36.156.0,67.267.0"}
P.entries["item:powers-of-the-void"] = {n="Силы Бездны",s="«Силы Бездны» — редкий магический том, изначально хранившийся в закрытом крыле библиотеки Аббатства Североземья. После того как заблудший послушник украл его, перебежав к Братству Справедливости, наставница чернокнижников Друзилла ла Салле стремится вернуть книгу, чтобы продолжить собственное изучение темной магии.",h="«Силы Бездны» — редкий магический том, изначально хранившийся в закрытом крыле библиотеки Аббатства...",kw={"defias brotherhood","drusilla la salle","imp","khadgar","northshire abbey","powers of the void","stolen books","the stolen tome","warlock","братство справедливости","друзилла ла салле","бес","кадгар","аббатство североземья","силы бездны","украденные книги","украденный том","чернокнижник"},ang={["class:Warlock"]="Возвращение этого украденного гримуара — основное испытание для юных чернокнижников-людей: оно показывает, достаточно ли у них силы воли, чтобы узнать тайну призыва беса.",["race:Human"]="Присутствие тома в Североземье показывает, что Священный орден хранит опасные магические записи рядом с обычными церковными текстами, скрывая их от глаз послушников."},sec={{t="Закрытый текст Североземья",b="В архивах Аббатства Североземья хранится гораздо больше, чем священные писания и церковные записи. В защищенном крыле библиотеки аббатства находились «Силы Бездны» — научный труд о тени и энергиях Пустоты, предположительно написанный верховным магом Кадгаром. Из-за опасного характера таких исследований власти аббатства строго охраняли книгу и не допускали к ней случайных посетителей. Поэтому она оставалась недоступной для местной наставницы чернокнижников Североземья, Друзиллы ла Салле, которая не могла подолгу задерживаться у закрытых полок, не вызывая подозрений у священников."},{t="Кража Братства Справедливости и возвращение книги",b="Том покинул стены аббатства не по воле Друзиллы, а из-за предательства изнутри. Послушник Североземья отказался от обетов и примкнул к Братству Справедливости, прихватив несколько ценных томов и бежав в соседние виноградники. Воспользовавшись корыстью вора, Друзилла посылает многообещающих чернокнижников-новичков прямо в лагерь бандитов Братства Справедливости, чтобы они забрали книгу из палаток. Возвращение текста служит двойной цели: темное знание попадает в руки наставницы и проверяется, хватит ли новичку смелости, нужной для подчинения демонов из иных миров."}},faq={{q="Что такое «Силы Бездны»?",a="Это редкая оккультная книга о темных энергиях и понятиях Пустоты, которую, как считается, написал верховный маг Кадгар. Она хранилась в закрытом крыле Аббатства Североземья, пока ее не похитили.",al={"what is powers of the void","powers of the void book","what is the stolen tome","что такое силы бездны","книга силы бездны","что за украденный том"}},{q="Почему книгу заперли в Аббатстве Североземья?",a="Аббатство Североземья хранит исторические архивы, в том числе опасные тексты о запретной магии. Книги об энергиях Бездны и демонологии держат под замком, чтобы послушники и заблудшие маги не могли ими злоупотребить.",al={"why was it in the abbey","why did the priests have it","northshire library wing","почему она была в аббатстве","почему она была у священников","крыло библиотеки североземья"}},{q="Как книга попала к Братству Справедливости?",a="Послушник аббатства перешел на сторону Братства Справедливости и унес с собой несколько ценных томов из закрытой библиотеки Североземья, спрятав их в лагере бандитов на виноградниках Североземья.",al={"who stole the book","defias stolen books","how did defias get it","кто украл книгу","украденные книги братства справедливости","как братство справедливости получило ее"}},{q="Зачем Друзилле ла Салле «Силы Бездны»?",a="Друзилла — местная наставница чернокнижников Североземья. Она жаждет эзотерических знаний тома для своего темного искусства, но не могла проникнуть в защищенный архив библиотеки аббатства, не подняв тревогу.",al={"why does drusilla want it","who wants the book","drusilla la salle stolen tome","зачем книга друзилле","кому нужна книга","украденный том друзиллы ла салле"}},{q="Что возвращение тома доказывает Друзилле?",a="Добыв том, новичок доказывает Друзилле, что обладает хитростью, силой и решимостью, необходимыми для управления демонами-слугами, и получает наставление о том, как призвать своего первого беса.",al={"why do warlocks need the book","imp summoning test","stolen tome reward","зачем чернокнижникам книга","испытание призыва беса","награда за украденный том"}}},fp="18,280,28.591.0,25.595.0,27.203.0,47.227.0,44.200.0,51.200.0,48.190.0"}
P.entries["item:prairie-alpha-tooth"] = {kw={"bloodhoof village","mulgore","mull thunderhorn","prairie alpha tooth","prairie wolf alpha","water well","wildmane totem","деревня кровавого копыта","мулгор","мулл громовой рог","зуб могучего волка прерий","вожак волков прерий","колодец","тотем буйногривых"},ang={["class:Shaman"]="Духов водных колодцев нужно умилостивить земным равновесием, а подношение клыков главного хищника закрепляет эту природную гармонию.",["race:Tauren"]="Взять клык вожака прерий — значит исполнить священный долг охотника: брать только необходимое и с уважением, возвращая эту первобытную сущность, чтобы исцелить отравленную землю."},sec={{t="Очищающее подношение",b="Колодцы Мулгора — жизненно важные источники для таурен, а сохранение их духовной чистоты требует обрядов уважения и жертвы. Чтобы очистить колодец Буйногривых, Мулл Громовой Рог из Деревни Кровавого Копыта просит зубы вожаков волков прерий, что бродят в тени Громового Утеса. Как главные хищники холмистых травянистых равнин, эти вожаки воплощают дикую силу природы. Подношение их зубов чтит равновесие между охотником, добычей и духами земли."}},faq={{q="What is a Prairie Alpha Tooth used for?",a="Мулл Громовой Рог использует восемь таких зубов в обряде очищения колодца Буйногривых — последнего загрязненного колодца возле Деревни Кровавого Копыта.",al={"alpha tooth purpose","what are wolf teeth for mulgore","wildmane totem item","назначение зуба вожака","для чего волчьи зубы в мулгоре","предмет тотема буйногривых"}},{q="Где бродят вожаки волков прерий?",a="Вожаки волков прерий рыщут по открытым травянистым равнинам центрального и северного Мулгора, особенно кружат у утесов у подножия Громового Утеса.",al={"where are prairie wolf alphas","alpha wolf locations","prairie wolf alpha spots","где вожаки волков прерий","места вожаков волков","где искать вожака волков прерий"}},{q="Почему для обряда очищения воды нужны волчьи зубы?",a="Обряды таурен чтят равновесие природы. Для очищения колодцев нужны священные компоненты, взятые у свирепых исконных зверей этой земли: они символизируют и жертву, и жизненную силу дикой природы Мулгора.",al={"why wolf teeth for water","mull thunderhorn tooth ritual lore","почему волчьи зубы для воды","предание об обряде муллы громового рога"}}},fp="19,216,20.495.0,39.142.0,34.148.0,53.212.0"}
P.entries["item:prairie-wolf-heart"] = {ang={["class:Hunter"]="Выслеживание определенных волчьих стай на равнинах показывает раннее понимание добычи и экологии зверей Мулгора.",["race:Tauren"]="Использование частей животных для создания целебных средств отражает практичные, близкие к земле традиции таурен в диких землях Мулгора."},sec={{t="Средство от ядовитого укуса",b="Волки равнин — свирепые хищники, выносливые и упорные среди просторных трав Мулгора. Их сердца ищет Маур Заклинатель Дождя, таурен из Деревни Кровавого Копыта, ставший жертвой легендарного бегуна по равнинам Маззранача. Пораженный едким ядом, вызывающим лихорадку, Маур прибегает к традиционной медицине равнин, чтобы остановить распространение яда. Наряду с другими сильными реагентами, такими как кость пумы и зоб птицы, жизненная сущность только что убитого волка прерий дает очищающие свойства, нужные для лекарства, пока бред не стал смертельным."}},faq={{q="What is a Prairie Wolf Heart used for?",a="Его собирают для Маура Заклинателя Дождя в Деревне Кровавого Копыта. Мауру нужны оно и еще несколько частей животных, чтобы сварить сильное народное лекарство от ядовитого укуса, нанесенного печально известным бегуном Маззраначем.",al={"wolf heart use","why get wolf heart","prairie wolf heart purpose"}},{q="Where does one obtain a Prairie Wolf Heart?",a="It is taken from the bodies of prairie wolves, prairie wolf alphas, and prairie stalkers found hunting across the rolling plains of Mulgore.",al={"wolf heart location","who drops wolf heart","how to find prairie wolf heart"}},{q="Почему Мауру Заклинателю Дождя нужны органы животных для лечения раны?",a="Mazzranache inflicts a terrible, infected bite that causes fever and delirium. Maur uses traditional tauren plains remedies composed of potent reagents—wolf heart, cougar femur, plainstrider scale, and swoop gizzard—to cleanse the infection before it proves lethal.",al={"why wolf heart for medicine","maur remedy"}},{q="Подойдет ли любое волчье сердце для лекарства?",a="Только сердца волков прерий, обитающих в Мулгоре, обладают жизненной силой и свойствами, которых требует традиционный рецепт равнин Маура Заклинателя Дождя.",al={"any wolf heart","which wolves drop it"}}},fp="18,243,28.598.0,38.211.0,43.140.0,63.269.0,42.154.0"}
P.entries["item:prairie-wolf-paw"] = {kw={"bloodhoof village","mulgore","mull thunderhorn","plainstrider talon","poison water","prairie wolf","prairie wolf paw","winterhoof water well","деревня кровавого копыта","мулгор","мулл громовой рог","коготь бегуна по равнинам","отравленная вода","волк прерий","лапа койота","колодец заиндевевшего копыта"},ang={["class:Shaman"]="Создание очищающих тотемов из местных частей животных показывает принцип стихий: живая сущность земли изгоняет неестественную порчу.",["race:Tauren"]="Для таурен сбор волчьих лап — торжественный долг хранителей: они призывают исконных зверей земли исцелить древние колодцы, оскверненные гоблинской жадностью."},sec={{t="Природные реагенты равнин",b="Волки прерий рыщут в холмистых травах Мулгора, охотясь стаями вместе со следопытами прерий и их вожаками. Хотя они опасны для молодых охотников и местного скота, эти создания тесно связаны с духовным равновесием равнин. Шаманы таурен видят в волчьих лапах не просто трофеи, а важные проводники природной жизненной силы земли."},{t="Очищение колодцев",b="Когда затеи гоблинов осквернили священные запасы воды Мулгора, шаману Муллу Громовому Рогу понадобилась помощь самой земли, чтобы справиться с загрязнением. Лапы койота вместе с когтями бегунов по равнинам дают первозданный духовный отклик, нужный для создания очищающих тотемов, и начинают важную работу по очищению Колодца Заиндевевшего Копыта."}},faq={{q="С каких существ падает лапа койота?",a="Их добывают у койотов, следопытов прерий и могучих волков прерий, охотящихся на равнинах Мулгора, главным образом к юго-западу от Деревни Кровавого Копыта.",al={"who drops prairie wolf paw","where to get prairie wolf paws","prairie wolf paw source","с кого падает лапа койота","где взять лапы койота","источник лапы койота"}},{q="Кому нужны лапы койота?",a="Их просит Мулл Громовой Рог, шаман таурен из Деревни Кровавого Копыта, чтобы создать очищающий тотем и очистить оскверненные колодцы.",al={"who needs prairie wolf paws","mull thunderhorn wolf paws","prairie wolf paw turn in","кому нужны лапы койота","лапы койота мулл громовой рог","сдать лапу койота"}},{q="Почему для очищения воды нужны волчьи лапы?",a="Шаманизм таурен основан на направлении природной жизненной силы земли против порчи. Волчьи лапы вместе с птичьими когтями позволяют шаману вложить живой дух Мулгора в тотем стихии, способный изгнать гоблинские яды.",al={"why wolf paws","prairie wolf paw lore","why does mull want paws","почему волчьи лапы","предание о лапе койота","зачем мулл просит лапы"}},{q="Какой колодец помогают очистить эти лапы?",a="Лапы собирают именно для создания очищающего тотема для Колодца Заиндевевшего Копыта, отравленного гоблинами-чужаками и их приспешниками.",al={"which well","winterhoof well cleansing","какой колодец","очищение колодца заиндевевшего копыта"}}},fp="16,244,30.370.0,19.354.0,39.166.0,28.147.0,42.251.0,44.154.0"}
P.entries["item:pridewing-venom-sac"] = {n="Ядовитая железа величавой виверны",s="Ядовитые железы величавых виверн добывают у смертоносных виверн, гнездящихся у Мутного озера в Когтистых горах. Ночные эльфы Астранаара стремятся собирать и уничтожать эти железы: по данным разведки, оперативники Орды добывают из них сильный яд для тайных убийств.",h="Ядовитые железы величавых виверн добывают у смертоносных виверн, гнездящихся у Мутного озера в Когтистых...",kw={"astranaar","mirkfallon lake","pridewing","shindrell swiftfire","stonetalon","venom sac","wyvern","астранаар","мутное озеро","величавая виверна","шиндрелл огненный всполох","когтистые горы","ядовитая железа","виверна"},ang={["faction:Alliance"]="Не позволить Орде добывать яд величавых виверн жизненно важно для защиты пограничных патрулей от невидимых убийц на спорных рубежах Когтистых гор и Ясеневого леса.",["race:NightElf"]="Хотя руководство Часовых сожалеет о необходимости истреблять невинных диких зверей, защита жизней эльфов от отравленных клинков важнее гармонии с природой."},sec={{t="Угроза в скалах",b="Величавые виверны Когтистых гор — опасные хищники, обитающие в горах к югу от Ясеневого леса, особенно у Мутного озера. Дикие виверны ядовиты от природы, а разведка Альянса в Тераморе сообщает, что убийцы Орды стали «доить» их ради яда, которым смазывают клинки для тайных налетов на поселения ночных эльфов. Чтобы защитить сородичей и сорвать снабжение врага, Часовые в Астранааре нанимают разведчиков: те выслеживают зверей и собирают ядовитые железы раньше, чем до них доберется Орда."}},faq={{q="С каких существ можно получить ядовитую железу величавой виверны?",a="Эти ядовитые железы добывают у разных виверн, обитающих в скалах у Мутного озера в Когтистых горах, в том числе у молодых величавых виверн, небесных охотников, патриархов и самок.",al={"where to get pridewing venom sac","who drops pridewing venom sac","pridewing venom sources","где взять ядовитую железу величавой виверны","с кого падает ядовитая железа величавой виверны","источники яда величавых виверн"}},{q="Почему Астранаару нужны ядовитые железы величавых виверн?",a="Шиндрелл Огненный Всполох получила сведения, что агенты Орды добывают яд величавых виверн, чтобы смазывать им оружие для бесшумных убийств в рядах Альянса. Уничтожение или изъятие желез предотвращает такие удары.",al={"why collect venom sacs","shindrell swiftfire venom","зачем собирать ядовитые железы","шиндрелл огненный всполох яд"}},{q="Кто принимает эти ядовитые железы в Ясеневом лесу?",a="Шиндрелл Огненный Всполох, находящаяся в городе ночных эльфов Астранаар в Ясеневом лесу, собирает их, чтобы защитить свой народ от тайных нападений.",al={"who takes pridewing venom","pridewing quest turn in","кто принимает яд величавых виверн","сдать задание величавых виверн"}},{q="Союзны ли величавые виверны Орде?",a="Нет. Дикие величавые виверны у Мутного озера — звери, которые не помогают Орде по своей воле, хотя орочьи агенты используют их ядовитую природу в своей войне.",al={"are pridewings horde","do pridewings work for orcs","величавые виверны орда","работают ли величавые виверны на орков"}}},fp="19,286,21.530.0,43.192.0,45.209.0,42.140.0,51.166.0"}
P.entries["item:prismatic-punch-card"] = {n="Призматическая перфокарта",s="Призматическая перфокарта — карта данных с высшим уровнем допуска, найденная в павшем Гномрегане. Ее последовательно улучшают на ряде терминалов «Матричный перфограф», и она содержит данные, которые отчаянно ищут гномы-беженцы в Стальгорне.",h="Призматическая перфокарта — карта данных с высшим уровнем допуска, найденная в павшем Гномрегане.",kw={"castpipe","data rescue","engineering labs","gnomeregan","matrix punchograph","prismatic punch card","чугонотрубз","спасение данных","инженерные лаборатории","гномреган","матричный перфограф","призматическая перфокарта"},ang={["profession:Engineering"]="Последовательное программирование перфокарт и сеть автоматических терминалов показывают высокий уровень вычислительных машин, созданных умельцами Гномрегана.",["race:Gnome"]="Сложная система безопасности «Перфограф» — яркий пример гномьей изобретательности и бюрократии, уцелевших даже после падения их дома."},sec={{t="Вопрос безопасности",b="Когда гномы бежали от вторжения троггов и радиоактивного заражения Гномрегана, огромные массивы исследований и городских записей остались в глубинах. Для защиты важных систем гномы применяли протокол безопасности с нарастающими уровнями. Чтобы получить доступ к терминалу «Матричный перфограф 3005-D» в нижних Инженерных лабораториях, нужно пройти цепочку перфокарт: начав с простой белой перфокарты, пройти уровни допуска желтый, синий и красный на отдельных терминалах и лишь затем проштамповать итоговую призматическую перфокарту. Ее закодированный уровень допуска причудливо назван ожидающим изобретения совершенно нового числа."},{t="Жизненно важная передача",b="Главный механик Чугонотрубз, ныне живущий среди беженцев в Стальгорне, отправляет отважных искателей приключений обратно в зараженные залы Гномрегана спасать важные данные. Чугонотрубз называет их жизненно необходимыми, без которых не прожить, но расшифрованное двоичное сообщение на последней призматической карте раскрывает забавную правду гномьей повседневности: автоматическое уведомление для Чугонотрубза о том, что его белье готово к выдаче."}},faq={{q="Как создать призматическую перфокарту?",a="Призматическую перфокарту получают, вставив красную перфокарту в терминал «Матричный перфограф 3005-D» на нижнем уровне Инженерных лабораторий Гномрегана. Чтобы дойти до этой стадии, нужно последовательно улучшить базовую белую перфокарту на терминалах моделей A, B и C в разных частях комплекса.",al={"how to get prismatic punch card","make prismatic punch card","punch card upgrade sequence","как получить призматическую перфокарту","создать призматическую перфокарту","порядок улучшения перфокарт"}},{q="Какие данные хранятся на призматической перфокарте?",a="На карте указано, что ее уровень допуска так высок, что ожидает изобретения нового числа, а далее следует длинная строка двоичного кода. Главный механик Чугонотрубз уверяет, что данные крайне важны.",al={"what does the card say","punch card binary translation","decoded punch card","что написано на карте","перевод двоичного кода перфокарты","расшифрованная перфокарта"}},{q="Кому нужна призматическая перфокарта?",a="Главный механик Чугонотрубз, изгнанный гном-инженер, живущий в Стальгорне, просит принести карту в задании «Спасение данных». Он считает ее содержимое срочной и бесценной информацией, оставленной при эвакуации Гномрегана.",al={"who turns in prismatic punch card","castpipe quest","who needs the card","кому сдать призматическую перфокарту","задание чугонотрубза","кому нужна карта"}},{q="Где находятся терминалы «Матричный перфограф»?",a="Терминалы разбросаны по Гномрегану в зависимости от уровня допуска. «Перфограф 3005-A» находится у наземного Депо и входа в мастерскую, модель B — в Общежитии за Чистой зоной, модель C — глубже в комплексе, а модель D — в нижних Инженерных лабораториях.",al={"terminal locations","where are the punchographs","where to punch cards","расположение терминалов","где перфографы","где пробивать карты"}}},fp="20,249,20.637.0,22.483.1,41.311.0,48.205.1,35.242.0,51.303.0"}
P.entries["item:pristine-spider-silk"] = {n="Нетронутая паутина",s="Безупречная паутина — исключительно тонкая нить, добываемая у ядовитых паукообразных Сумеречного леса. Маги Штормграда заказывают этот редкий материал, чтобы ткать прочные зачарованные одеяния, достойные признанных знатоков тайных искусств.",h="Безупречная паутина — исключительно тонкая нить, добываемая у ядовитых паукообразных Сумеречного леса.",kw={"black widow hatchling","carrion recluse","duskwood","mage robe","pristine spider silk","wizard's sanctum","wynne larson","птенец черной вдовы","падальный отшельник","сумеречный лес","мантия мага","безупречная паутина","святилище волшебника","уинн ларсон"},ang={["class:Mage"]="Магов Штормграда отправляют прямо в Сумеречный лес собирать эту безупречную нить как обряд посвящения, чтобы заслужить мантию, подобающую их растущему тайному положению.",["profession:Tailoring"]="Эти хрупкие, но прочные нити, добытые у смертоносных паукообразных, — вершина природных тканей, из которых плетут волшебные одеяния."},sec={{t="Плетение тайного",b="Не всякая нить выдержит чары и нагрузки, которых требует практикующий маг. Обычная паутина достаточно распространена среди портных, но нужной стойкостью обладают лишь безупречные нити падальных отшельников и птенцов черных вдов из тенистых рощ Сумеречного леса. Маги Святилища волшебника в Штормграде отправляют своих подающих надежды адептов в эти опасные леса за безупречными мотками, поручая местной мастерице-портнихе Уинн Ларсон сшить из материала одеяние, достойное адепта."}},faq={{q="Откуда берется безупречная паутина?",a="Ее добывают у паукообразных, обитающих в Сумеречном лесу, а именно у падальных отшельников и птенцов черных вдов, гнездящихся под мрачным пологом леса.",al={"where to get pristine spider silk","who drops pristine spider silk","pristine spider silk location","где взять безупречную паутину","с кого падает безупречная паутина","где найти безупречную паутину"}},{q="Кто шьет одеяния из этой паутины?",a="Уинн Ларсон, портниха из Квартала магов Штормграда, шьет собранные мотки в изысканную мантию по заказу Святилища волшебника.",al={"who uses pristine spider silk","who turns silk into robes","wynne larson robe","кто использует безупречную паутину","кто шьет мантии из паутины","мантия уинн ларсон"}},{q="Почему магам нужна именно эта паутина?",a="Магам нужны одеяния, отражающие их растущее мастерство в тайной магии. Лишь самая чистая, неповрежденная паутина смертоносных пауков Сумеречного леса дает прочность и качество, необходимые для мантии адепта.",al={"why pristine silk","magic spider silk use","зачем безупречная паутина","применение магической паутины"}}},fp="20,240,18.520.0,42.149.0,35.152.0,44.193.0"}
P.entries["item:prowler-claws"] = {n="Когти хищника саванны",s="Когти хищника саванны — отсеченные трофеи, добытые у хищников саванны, рыскающих по залитым солнцем равнинам Степей. Их приносят Сергре Черный Шип на Перекрестке как наглядное доказательство того, что охотник способен выследить и одолеть самых опасных скрытных хищников Калимдора.",h="Когти хищника саванны — отсеченные трофеи, добытые у хищников саванны, рыскающих по залитым солнцем равнинам...",kw={"barrens","crossroads","prowler claws","prowlers of the barrens","savannah prowler","sergra darkthorn","степи","перекресток","когти хищника саванны","хищники степей","хищник саванны","сергра черный шип"},ang={["class:Hunter"]="Убить хищников саванны и забрать их когти — обязательный обряд посвящения для молодых охотников, постигающих искусство скрытности, выслеживания и обращения со зверями в ближнем бою.",["faction:Horde"]="Истребление опасных хищников у Перекрестка помогает защитить гонцов, караваны и поселенцев Орды на опасных центральных дорогах Калимдора."},sec={{t="Трофеи охотника",b="В высокой траве Степей скрываются хищники саванны — крупные кошачьи, известные терпением, хитростью и смертоносными ударами. Охота на них — важное испытание для молодых воинов и разведчиков Орды. В отличие от травоядной добычи вроде бегунов или жевр, хищники сами нападают из засады на всех, кто входит на их охотничьи угодья. Добыть их острые изогнутые когти значит победить зверя, полагающегося на полную скрытность и защиту территории, и доказать охотнице лагеря, что охотник стал добычей."},{t="Доказательство для охотницы",b="На Перекрестке Сергра Черный Шип требует эти когти, чтобы оценить готовность новичка к более серьезным испытаниям. Горсть принесенных когтей показывает, что охотник освоил выслеживание в золотой траве саванны и выдержит когти, способные рвать кожу и плоть. Те, кто вернулся с добычей, доказали, что обладают внимательностью, нужной для выживания среди еще более опасных зверей равнин."}},faq={{q="Где достать когти хищника саванны?",a="Когти хищника саванны добывают у хищников саванны, бродящих по равнинам центральных Степей, особенно к юго-западу от Перекрестка.",al={"prowler claw location","how to get prowler claws","where to find prowler claws","где взять когти хищника саванны","как получить когти хищника","где найти когти хищника"}},{q="Кому нужны эти когти и зачем?",a="Сергра Черный Шип, опытная охотница на Перекрестке, просит охотников принести ей семь когтей хищника саванны, чтобы проверить их навыки выслеживания и боя с опасными хищниками.",al={"who needs prowler claws","turn in prowler claws","sergra claws quest","кому нужны когти хищника","сдать когти хищника","задание сергры про когти"}},{q="Почему охота на хищников саванны считается серьезной?",a="В отличие от пасущихся стад Степей, хищники саванны — скрытные плотоядные, которые выслеживают путников и добычу из укрытий в высоких зарослях. Охота на них проверяет умение избегать засад и побеждать смертоносного хитрого зверя.",al={"why hunt prowlers","prowlers dangerous","зачем охотиться на хищников","опасны ли хищники саванны"}}},fp="13,273,23.532.0,22.418.0,29.161.0,30.192.0,56.250.0"}
P.entries["item:pure-hearts"] = {n="Чистые сердца",s="Чистые сердца — ритуальные реагенты, которые Отрекшимся чернокнижникам дает Карендин Халгар в Подгороде. С их помощью заманивают и призывают суккуба через Круговерть Пустоты, чтобы практик мог победить демоницу и подчинить ее.",h="Чистые сердца — ритуальные реагенты, которые Отрекшимся чернокнижникам дает Карендин Халгар в Подгороде.",kw={"carendin halgar","magic quarter","pure hearts","succubus","summoning","the binding","undercity","карендин халгар","магический квартал","чистые сердца","суккуб","призыв","подчинение","подгород"},ang={["class:Warlock"]="Для Отрекшихся чернокнижников получение и применение этих сердец — важный рубеж в демонологии: испытание силы духа перед соблазнами Круговерти Пустоты.",["race:Undead"]="Среди гнили и порчи Подгорода использование совершенно чистых сердец для управления демоническими аппетитами — пример холодного, прагматичного колдовства Отрекшихся."},sec={{t="Приманка для Пустоты",b="Демонология основана на использовании низменных желаний и духовных слабостей. Чтобы призвать суккуба в Магический квартал Подгорода, Карендин Халгар выдает чернокнижникам Чистые сердца. Положенные на круг призыва, эти незапятнанные духовные сущности служат сильной приманкой и влекут соблазнительную демоницу через Круговерть Пустоты в мир смертных. Когда демон появляется, чернокнижник должен противостоять ее порабощающим чарам разума и сразить ее в бою. Победа над суккубом утверждает мистическое господство и изгоняет ее обратно в Круговерть Пустоты, пока чернокнижник не произнесет ее истинное имя, чтобы навечно подчинить ее."}},faq={{q="Для чего нужны Чистые сердца?",a="Они служат мистическим катализатором у круга призыва в Магическом квартале Подгорода: заманивают и призывают суккуба через пустоту, позволяя чернокнижнику сразиться с ней и подчинить ее.",al={"pure hearts use","why pure hearts","what do pure hearts do","для чего чистые сердца","зачем чистые сердца","что делают чистые сердца"}},{q="Кто выдает Чистые сердца?",a="Карендин Халгар, Отрекшийся учитель чернокнижников в Магическом квартале под руинами Лордерона, отдает их начинающим практикам, готовым освоить призыв суккуба.",al={"who gives pure hearts","pure hearts quest giver","кто дает чистые сердца","кто выдает задание чистых сердец"}},{q="Почему суккуб откликается на Чистые сердца?",a="Суккубы питаются порчей, соблазном и растлением невинности. Сияние незапятнанных чистых сердец — непреодолимая приманка через Круговерть Пустоты, влекущая их прямо в подготовленный круг призыва чернокнижника.",al={"why succubus wants pure hearts","lore behind pure hearts","почему суккуб хочет чистые сердца","предание о чистых сердцах"}},{q="Остаются ли Чистые сердца у вас после ритуала?",a="Нет. Когда суккуб призван и усмирен, остатки Чистых сердец возвращают Карендину Халгару как доказательство прохождения испытания подчинения.",al={"do i keep pure hearts","what happens to pure hearts","остаются ли чистые сердца","что будет с чистыми сердцами"}}},fp="11,222,19.642.0,34.185.0,29.188.0,43.227.0,52.152.0"}
P.entries["item:purified-kor-gem"] = {n="Очищенный самоцвет Кора",s="Очищенный самоцвет Кора — редкий освященный кристалл, который нужен оружейнику Джордану Стилвеллу у Стальгорна. Когда-то оскверненный темной энергией, он должен быть извлечен из глубин Калимдора и очищен эльфийской магией, прежде чем его выкуют в священное оружие Света.",h="Очищенный самоцвет Кора — редкий освященный кристалл, который нужен оружейнику Джордану Стилвеллу у...",kw={"auberdine","blackfathom deeps","corrupted kor gem","dun morogh","jordan stilwell","purified kor gem","test of righteousness","thundris windweaver","аубердин","непроглядная пучина","оскверненный самоцвет кора","дун морог","джордан стилвелл","очищенный самоцвет кора","испытание доблести","тандрис ветропряд"},ang={["class:Paladin"]="Добыча и очищение этого самоцвета доказывает преданность паладина: он проходит путь от глубин Калимдора обратно в Дун Морог, чтобы выковать легендарное оружие Света.",["faction:Alliance"]="Добыча очищенного самоцвета объединяет усилия всего Альянса: мудрость ночных эльфов в Аубердине помогает человеку-кузнецу, работающему на склонах Дун Морога."},sec={{t="От скверны к святости",b="Камень начинает свой путь как Оскверненный самоцвет Кора в руках мерзких наг, обитающих в Непроглядной Пучине глубоко под побережьем Ясеневого леса. Чтобы очистить камень от водной, теневой порчи, паладин должен найти ночного эльфа Тандриса Ветропряда в Аубердине. Используя тайные и природные искусства, Тандрис изгоняет скверну из камня и превращает его в сияющий Очищенный самоцвет Кора. Лишь в таком чистом виде он годится в качестве проводника священной силы."},{t="Шедевр кузнеца",b="Неподалеку от Стальгорна, в заснеженных скалах Дун Морога, человек-оружейник Джордан Стилвелл ищет этот самоцвет как важнейший компонент для ковки великолепного оружия. Стилвелл давно обладал чертежами оружия, достойного Серебряной Длани, но ему недоставало редких материалов для воплощения замысла. Очищенный самоцвет Кора вместе с Древесиной белокаменного дуба и редкой рудой образует духовное ядро, необходимое, чтобы направить праведный гнев паладина."}},faq={{q="Для чего нужен Очищенный самоцвет Кора?",a="Его приносят кузнецу Джордану Стилвеллу, стоящему у ворот Стальгорна в Дун Мороге. Стилвелл использует освященный самоцвет как важнейший компонент при ковке священного оружия для паладина, проходящего испытания.",al={"purified kor gem use","why do i need kor gem","what is kor gem for","для чего нужен очищенный самоцвет кора","зачем мне самоцвет кора","зачем нужен самоцвет кора"}},{q="Откуда берется самоцвет?",a="Камень происходит из подземных руин Непроглядной Пучины на побережье Ясеневого леса, где наги хранят его как оскверненный артефакт.",al={"kor gem origin","where does kor gem drop","who drops kor gem","происхождение самоцвета кора","где добыть самоцвет кора","с кого падает самоцвет кора"}},{q="Кто очищает самоцвет?",a="Тандрис Ветропряд, эльфийский ученый, живущий в прибрежном поселении Аубердин в Темных берегах, изгоняет темную энергию из Оскверненного самоцвета Кора и возвращает ему чистоту.",al={"how to cleanse kor gem","who cleanses kor gem","thundris windweaver kor gem","как очистить самоцвет кора","кто очищает самоцвет кора","тандрис ветропряд самоцвет кора"}},{q="Может ли любой искатель приключений использовать Очищенный самоцвет Кора?",a="Самоцвет ищут именно паладины, проходящие Испытание доблести. Джордан Стилвелл оставляет свое мастерство для священных воинов, которые приносят ему очищенный кристалл вместе с другими редкими материалами.",al={"is kor gem paladin only","can anyone use purified kor gem","самоцвет кора только для паладинов","может ли любой использовать очищенный самоцвет кора"}}},fp="16,274,27.493.0,23.438.0,38.235.0,29.155.0,21.188.0,52.200.0"}
P.entries["item:putrid-claw"] = {n="Гнилой коготь",s="Гнилые когти — разлагающиеся кисти, отрубленные у безмозглой нежити, бродящей по лесам к западу от Брилла. Страж смерти Диллинжер собирает их как неоспоримое доказательство того, что угроза Плети у старого моста сдерживается.",h="Гнилые когти — разлагающиеся кисти, отрубленные у безмозглой нежити, бродящей по лесам к западу от Брилла.",kw={"a putrid task","brill","deathguard dillinger","putrid claw","ravaged corpse","rotting dead","scourge","tirisfal glades","гнилая задача","брилл","страж смерти диллинжер","гнилой коготь","истерзанный труп","гниющий мертвец","плеть","тирисфальские леса"},ang={["race:Undead"]="Для новых Отрекшихся, покидающих Могильник, уничтожение этой безмозглой Плети — раннее напоминание о том, что свобода требует постоянной обороны от безмозглых оболочек, которыми они когда-то были."},sec={{t="Трофей безмозглых",b="Даже на родной земле Отрекшиеся не в полной безопасности от длани Короля-лича. Группы безмозглой Плети — гниющих мертвецов и истерзанных трупов — регулярно забредают через восточные границы в Тирисфальские леса, собираясь вдоль дорог и у старого моста к западу от Брилла. Чтобы обеспечить безопасность путников и линий снабжения гарнизона, Стражи смерти назначают награды за этих блуждающих чудовищ. Отрубленный гнилой коготь — несомненное вещественное доказательство того, что еще один шатающийся труп уничтожен навсегда."}},faq={{q="Для чего нужны гнилые когти?",a="Страж смерти Диллинжер в Брилле собирает их в качестве награды, чтобы убедиться, что местные новобранцы Отрекшихся прореживают Плеть, бродящую по Тирисфальским лесам.",al={"putrid claw use","why collect putrid claws","who wants putrid claws","для чего гнилой коготь","зачем собирать гнилые когти","кому нужны гнилые когти"}},{q="Откуда берутся гнилые когти?",a="Их добывают у гниющих мертвецов и истерзанных трупов, бродящих по зловещим лесам к западу от Брилла, особенно у старого речного моста.",al={"where to get putrid claws","putrid claw drops","rotting dead drops","где взять гнилые когти","гнилой коготь добыча","гниющие мертвецы добыча"}},{q="Почему Плеть находится в Тирисфальских лесах?",a="После разрушения Лордерона остатки безмозглой Плети Короля-лича непрерывно просачиваются на запад через границы в Тирисфаль, угрожая дорогам и поселениям, если их не истреблять.",al={"why are zombies near brill","scourge in tirisfal","почему зомби возле брилла","плеть в тирисфале"}},{q="Почему Отрекшиеся не оставят безмозглую нежить в покое?",a="В отличие от Отрекшихся, которые освободились под началом королевы Сильваны и обрели волю, безмозглая Плеть подчиняется лишь темным инстинктам или остаткам приказа Короля-лича и нападает на любое живое существо или свободную нежить на месте.",al={"forsaken vs mindless zombies","why kill other undead","отрекшиеся и безмозглые зомби","зачем убивать другую нежить"}}},fp="11,231,22.526.0,31.161.0,32.141.0,38.203.0,59.211.0"}
P.entries["item:pyrewood-shackle"] = {n="Кандалы из деревни Погребальных Костров",s="Кандалы из деревни Погребальных Костров — зачарованные оковы, которые носят измученные жители деревни Погребальных Костров на юге Серебряного бора. Пропитанные странной магией верховного мага Аругала, эти путы связаны с жутким проклятием, которое с наступлением ночи превращает обычных горожан в кровожадных воргенов.",h="Кандалы из деревни Погребальных Костров — зачарованные оковы, которые носят измученные жители деревни...",kw={"arugal","dawnweaver","moonrage","pyrewood","sepulcher","shackle","silverpine","worgen","аругал","ткач рассвета","лунный гнев","погребальные костры","гробница","кандалы","серебряный бор","воргены"},ang={["class:Mage"]="Маги, изучающие работу Аругала, узнают безрассудное применение магии трансмутации и связывания, вплетенной в обычную сталь.",["race:Undead"]="Ученые Отрекшихся в Гробнице считают разнузданное колдовство Аругала серьезной угрозой своим границам, поэтому сбор этих зачарованных пут важен для ослабления влияния Крепости Темного Клыка."},sec={{t="Связывающая магия Аругала",b="Проклятая деревня Погребальных Костров хранит тревожную тайну: днем ее жители ведут обычную жизнь и выглядят как простые люди, но с заходом солнца превращаются в диких воргенов Лунной Ярости. Верховный маг Аругал заковал этих селян в зачарованные кандалы в рамках своих извращенных опытов с магией воргенов. Далар Ткач Рассвета, исследователь тайной магии из Гробницы Отрекшихся, изучает эти кандалы, чтобы разгадать чары, создающие это двойное существование. Собирая и анализируя остаточную энергию на путах, Ткач Рассвета стремится глубже понять магию Аругала в надежде разрушить власть безумного верховного мага над этим краем."}},faq={{q="Для чего нужны Кандалы из деревни Погребальных Костров?",a="Далар Ткач Рассвета в Гробнице просит принести эти кандалы, чтобы изучить их чары. Высасывая их магию, он надеется разгадать заклинания верховного мага Аругала и найти способ уничтожить влияние мага в Серебряном бору.",al={"pyrewood shackles use","why gather shackles","dalar dawnweaver shackles","кандалы из деревни погребальных костров для чего","зачем собирать кандалы","далар ткач рассвета кандалы"}},{q="Кто носит эти кандалы?",a="Кандалы носят проклятые жители деревни Погребальных Костров на юге Серебряного бора — и в человеческом облике днем, и при ночном превращении в воргенов Лунной Ярости.",al={"who drops pyrewood shackles","shackle source","where to find pyrewood shackles","с кого падают кандалы из деревни погребальных костров","источник кандалов","где найти кандалы из деревни погребальных костров"}},{q="Почему жители превращаются по ночам?",a="Верховный маг Аругал подверг жителей Погребальных Костров безрассудным магическим опытам и чарам. Кандалы поддерживают заклятие, благодаря которому днем они выглядят как обычные люди, а с наступлением тьмы принимают дикий облик воргенов.",al={"why pyrewood turns into worgen","pyrewood village curse","pyrewood werewolf secret","почему погребальные костры превращаются в воргенов","проклятие деревни погребальных костров","тайна оборотней погребальных костров"}},{q="Кто такой Далар Ткач Рассвета?",a="Далар Ткач Рассвета — маг из Отрекшихся, живущий в Гробнице в Серебряном бору. Он активно изучает тайные аномалии, оставленные верховным магом Аругалом, стремясь разобрать и разрушить проклятия безумного мага.",al={"dalar dawnweaver","who is dalar","далар ткач рассвета","кто такой далар"}}},fp="16,295,22.656.0,36.232.0,27.194.0,40.256.0,24.223.0"}
P.entries["item:quinn-s-potion"] = {n="Зелье Квинна",s="Зелье Квинна — восстанавливающий отвар, приготовленный аптекарем Ренферрелом в Гробнице. Он сварен, чтобы стабилизировать состояние и вернуть силы раненому Стражу смерти Квинну Йорику после неудачного разведывательного патруля в Серебряном бору.",h="Зелье Квинна — восстанавливающий отвар, приготовленный аптекарем Ренферрелом в Гробнице.",kw={"apothecary renferrel","deathstalker","ivar patch","quinn yorick","quinn's potion","sepulcher","silverpine","аптекарь ренферрел","страж смерти","делянка ивара","квинн йорик","зелье квинна","гробница","серебряный бор"},ang={["race:Undead"]="Королевское фармацевтическое общество редко тратит силы на простые полевые снадобья, если только они не спасают разведчиков Отрекшихся, жизненно важных для защиты границ Серебряного бора."},sec={{t="Лекарство Ренферрела",b="После того как Страж смерти Квинн Йорик был тяжело избит и лишился способности двигаться у Делянки Ивара, весть дошла до Королевского фармацевтического общества в Гробнице. Аптекарь Ренферрел поспешно составил этот особый отвар, чтобы помочь Квинну поправиться. Хотя Ренферрел редко позволяет мелким потерям в поле отвлекать его от более важных и зловещих исследований для леди Сильваны, он дал это снадобье, чтобы раненый разведчик встал на ноги и смог передвигаться."}},faq={{q="Для чего нужно Зелье Квинна?",a="Зелье предназначено для восстановления Стража смерти Квинна Йорика, который лежит раненый в северных лесах Серебряного бора. Выпив его, он обретет достаточно сил, чтобы снова отправиться в путь.",al={"quinn potion purpose","what does quinn potion do","why brew quinn potion","назначение зелья квинна","что делает зелье квинна","зачем варить зелье квинна"}},{q="Кто сварил это зелье?",a="Отвар приготовил аптекарь Ренферрел, алхимик Королевского фармацевтического общества, расположившийся в склепах Гробницы.",al={"who made quinn's potion","who brewed it","renferrel potion","кто сделал зелье квинна","кто его сварил","зелье ренферрела"}},{q="Куда нужно доставить зелье?",a="Его нужно отнести к северу от Гробницы Квинну Йорику, который укрылся возле хутора, известного как Делянка Ивара.",al={"where do i take the potion","quinn location","quinn yorick spot","куда отнести зелье","где квинн","где квинн йорик"}},{q="Почему Квинну Йорику понадобилось зелье?",a="Квинн входил в патруль Стражей смерти, разведывавший север Серебряного бора. У Делянки Ивара разведчиков застал врасплох вурдалак Ивар Нечистый со своими приспешниками из Плети, и Квинн остался там тяжело раненым и не смог уйти.",al={"why is quinn hurt","what happened to quinn yorick","quinn injured","почему квинн ранен","что случилось с квинном йориком","квинн ранен"}}},fp="14,231,16.466.0,32.212.0,23.131.0,43.120.0,41.214.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Череп Рэна Кровавого Клыка",s="Череп Рэна Кровавого Клыка — жуткий трофей, снятый с вождя оскверненных фурболгов Ясеневого леса. Доставленный ночным эльфам Астранаара, он служит весомым доказательством того, что свирепая угроза лесному краю устранена.",h="Череп Рэна Кровавого Клыка — жуткий трофей, снятый с вождя оскверненных фурболгов Ясеневого леса.",kw={"ashenvale","astranaar","bloodtooth skull","bloodtooth","furbolg","raene wolfrunner","raene's cleansing","ran bloodtooth","ясеневый лес","астранаар","череп кровавого клыка","кровавый клык","фурболг","раэна волкопас","очищение раэны","рэн кровавый клык"},ang={["faction:Alliance"]="Доставка этого мрачного трофея доказывает доблесть защитников Альянса, обороняющих хрупкие границы Ясеневого леса вместе с Часовыми."},sec={{t="Трофей обороны Ясеневого леса",b="Чащи Ясеневого леса сильно пострадали от демонической порчи и скверны диких земель, которая довела некогда мирные племена фурболгов до убийственного безумия. Одним из свирепейших среди этих враждебных вождей был Рэн Кровавый Клык. Возвращение его черепа дает Часовым ночных эльфов бесспорное доказательство гибели этого зверя, разрушает его власть над местными фурболгами и приносит небольшую передышку измученному городку Астранаар."},{t="Память павших",b="Если предъявить его часовому Раэне Волкопас в Астранааре, череп знаменует завершение расследования, начатого павшим разведчиком Теронисом. Наряду с Жезлом Дартола — древним артефактом, очищенным от порчи, — череп Рэна Кровавого Клыка выставлен на всеобщее обозрение как свидетельство мужества тех, кто сражался за сохранение священного леса."}},faq={{q="Кто такой был Рэн Кровавый Клык?",a="Рэн Кровавый Клык был вождем оскверненных фурболгов Ясеневого леса, которого Часовые ночных эльфов считали одной из свирепейших угроз региона.",al={"who is ran bloodtooth","ran bloodtooth lore","who was bloodtooth","кто такой рэн кровавый клык","предания о рэне кровавом клыке","кто был кровавый клык"}},{q="Почему Часовым нужен его череп?",a="Раэна Волкопас в Астранааре требует вещественное доказательство победы над Рэном Кровавым Клыком. Череп помещают рядом с Жезлом Дартола как символ победы и память о тех, кто погиб, защищая Ясеневый лес.",al={"why do i need the skull","raene wolfrunner skull","what is the skull for","зачем мне череп","раэна волкопас череп","для чего нужен череп"}},{q="Кто такой Теронис?",a="Теронис был Часовым ночных эльфов, погибшим при попытке очистить зачарованный жезл и выяснить источник безумия фурболгов, терзавшего Ясеневый лес. Его дело продолжили Раэна Волкопас и приезжие искатели приключений.",al={"teronis lore","who is teronis","teronis astranaar","предания о теронисе","кто такой теронис","теронис астранаар"}}},fp="22,242,31.443.0,19.338.1,23.147.0,36.199.0,16.224.0"}
P.entries["item:raptor-head"] = {n="Голова ящера",s="Отрубленная голова ящера — кровавое доказательство того, что в Степях убит зверь. Газрог с Перекрестка требует эти мрачные трофеи, чтобы истребить местные стаи после невероятной кражи жалованья стражи.",h="Отрубленная голова ящера — кровавое доказательство того, что в Степях убит зверь.",kw={"barrens","crossroads","gazrog","raptor head","raptor thieves","stolen silver","sunscale","степи","перекресток","газрог","голова ящера","ящеры-воры","украденное серебро","солнечные ящеры"},ang={["class:Hunter"]="Выслеживание ящеров на сухих зарослях Степей проверяет способность охотника перехитрить одних из самых агрессивных и хитрых стайных хищников саванны.",["faction:Horde"]="Перекресток — логистическое сердце путешествий Орды в центральном Калимдоре. Уничтожение хищников-воров защищает припасы и жалованье гарнизона."},sec={{t="Награда Перекрестка",b="Жизнь в засушливых равнинах Степей и так сурова, а тут еще местные звери нападают на сторожевые башни поселения. Когда сундук с жалованьем стражи исчез из сторожевой башни Перекрестка, защитники застали на месте преступления невероятного виновника — дикого ящера. Озадаченный и разъяренный Газрог тут же назначил награду за хитрых рептилий, рыскающих по саванне. Отрубленные головы ящеров, принесенные в форпост, доказывают, что эти хищные вредители истребляются прежде, чем успеют украсть еще какие-либо припасы Орды."}},faq={{q="Зачем Газрогу головы ящеров?",a="Партию серебра, предназначенную для жалованья стражи Перекрестка, украли прямо из их башни. К всеобщему изумлению, одним из воров, пойманных на месте, оказался ящер. Газрог хочет, чтобы этих зверей истребили по всем Степям и они больше не нападали на поселение.",al={"why collect raptor heads","gazrog raptors","raptor head bounty","зачем собирать головы ящеров","газрог ящеры","награда за голову ящера"}},{q="Зачем диким ящерам красть серебро?",a="Газрог признает, что понятия не имеет, зачем диким зверям металлические монеты. Однако ящеры Калимдора известны своей пугающей хитростью, и случившееся смутило стражу Перекрестка и вызвало у нее жажду возмездия.",al={"why do raptors want silver","raptors stealing coins","raptor thieves mystery","зачем ящерам серебро","ящеры крадут монеты","загадка ящеров-воров"}},{q="С каких ящеров можно получить эти головы?",a="Головы ящеров можно получить с разных ящеров Солнечной Чешуи, обитающих в центральной и южной частях Степей, в том числе с хлещущих хвостов, крикунов и косоклювов Солнечной Чешуи. Голову также дают известные чудовища, такие как Ишамухал и Мчащийся Такк.",al={"where to get raptor heads","which raptors drop heads","barrens raptors","где взять головы ящеров","с каких ящеров падают головы","ящеры степей"}},{q="Что происходит после сдачи голов?",a="Когда Газрог получает двенадцать голов и видит, что угроза со стороны ящеров ослабла, внимание переключается на поиски того места, куда на самом деле унесли украденную партию серебра.",al={"what follows raptor thieves","after collecting raptor heads","что дальше после ящеров-воров","после сбора голов ящеров"}}},fp="11,202,24.506.0,34.274.0,36.246.0,32.220.0,40.155.0"}
P.entries["item:rare-earth"] = {n="Горсть редкой земли",s="Горсть редкой земли — особая посылка богатой минералами почвы, добытой в Дарнассе для ботанических опытов в Тельдрассиле. Ее отправляют с посыльным из Доланаара травнику-исследователю Деналану в его лагерь на берегу озера близ Озера Аль'Амет.",h="Горсть редкой земли — особая посылка богатой минералами почвы, добытой в Дарнассе для ботанических опытов в...",kw={"darnassus","denalan","dolanaar","herbalism","lake al'ameth","rare earth","syral bladeleaf","дарнасс","деналан","доланаар","травничество","озеро аль'амет","редкая земля","сирел остролист"},ang={["profession:Herbalism"]="Травники оценят кропотливый труд исследователей вроде Сирел Остролист и Деналана, изучающих, как особая земля может изменить рост и свойства саженцев Тельдрассила.",["race:NightElf"]="Для ночных эльфов, ухаживающих за молодым Мировым Древом, каждый ботанический опыт у Озера Аль'Амет — возможность понять, как жизнь приспосабливается к диким ветвям Тельдрассила."},sec={{t="Почва Дарнасса",b="Новая экосистема Тельдрассила требует тщательного наблюдения и ухода, и травники острова изучают, как разные растения реагируют на чужую или обогащенную почву. Эту посылку редкой земли напрямую запросил из Дарнасса Деналан, чудаковатый ботаник, живущий на восточном берегу Озера Аль'Амет. Посылка долго пролежала в пути и поздно оказалась в Доланааре, поэтому травница Сирел Остролист просит путников, идущих на юг, доставить скоропортящуюся почву Деналану, пока она не утратила силу."}},faq={{q="Для чего нужна горсть редкой земли?",a="Редкая земля предназначена Деналану, травнику и ботанику-исследователю, разбившему лагерь на берегу Озера Аль'Амет. Он использует особые минеральные смеси и обогащенную почву из Дарнасса, чтобы выращивать местную флору Тельдрассила и ставить на ней опыты.",al={"rare earth use","what does denalan do with rare earth","rare earth purpose","для чего редкая земля","что деналан делает с редкой землей","назначение редкой земли"}},{q="Кто посылает редкую землю Деналану?",a="Посылка у Сирел Остролист, травницы из Доланаара. Земля прибыла из Дарнасса с опозданием, и Сирел просит проходящих на юг к Озеру Аль'Амет искателей приключений доставить ее вместо нее.",al={"who gives rare earth","where do you get rare earth","syral bladeleaf parcel","кто дает редкую землю","где взять редкую землю","посылка сирел остролист"}},{q="Почему Деналан беспокоился из-за доставки?",a="Посылку задержали по пути в Доланаар, и Деналан довольно долго ждал на берегу озера. Получив ее, он сразу тревожится, сохранила ли земля свежесть и силу для его ботанических опытов.",al={"is rare earth ruined","denalan fresh earth","why late earth","испортилась ли редкая земля","деналан свежая земля","почему земля опоздала"}}},fp="10,233,17.537.0,28.252.0,36.208.0,43.244.0"}
P.entries["item:rattlecage-skull"] = {n="Череп гремучего скелета",s="Черепа гремучих скелетов — разбитые останки безмозглой нежити, бродящей по разрушенным окраинам Могильника. Начинающие чернокнижники из числа Отрекшихся должны собрать эти окаменевшие трофеи для Вении Мартанд, чтобы показать зарождающуюся волю и получить право на темное искусство призыва.",h="Черепа гремучих скелетов — разбитые останки безмозглой нежити, бродящей по разрушенным окраинам Могильника.",kw={"deathknell","imp summoning","piercing the veil","rattlecage skeleton","rattlecage skull","tirisfal glades","venya marthand","могильник","призыв беса","прорыв сквозь завесу","гремучий скелет","череп гремучего скелета","тирисфальские леса","вения мартанд"},ang={["class:Warlock"]="Для чернокнижников из числа Отрекшихся сбор этих черепов — первая веха их пути, доказывающая, что у них достаточно холодной воли, чтобы поработить первого демона.",["race:Undead"]="Разбивая низших, неразумных скелетов, Отрекшиеся утверждают господство силой воли, отличая свободных духом мертвецов от безмозглых рабов."},sec={{t="Испытание неофита",b="В лишенных солнца пределах Могильника недавно восставших Отрекшихся, склонных к темной магии, наставляет Вения Мартанд. Чтобы доказать, что начинающий обладает стойкостью подчинять существ иных миров, Вения поручает им одолеть оставшихся гремучих скелетов возле разрушенной кузницы. Убийство этих низших мертвецов и добыча их отсеченных черепов — и практическая проверка дисциплины, и ритуальная основа перед тем, как научиться прорывать Пустоту и порабощать первого демона-прислужника."}},faq={{q="Для чего нужны черепа гремучих скелетов?",a="Их собирает Вения Мартанд в Могильнике. Чернокнижники из числа Отрекшихся должны принести ей три черепа, чтобы доказать сосредоточенность и решимость, после чего она обучит их обряду призыва и подчинения беса.",al={"what are rattlecage skulls","rattlecage skull use","who wants rattlecage skulls","что такое черепа гремучих скелетов","применение черепа гремучего скелета","кому нужны черепа гремучих скелетов"}},{q="Откуда берутся черепа гремучих скелетов?",a="Их берут из разбитых останков гремучих скелетов — безмозглой нежити, бродящей по заросшим дорогам и разрушенным землям возле заброшенной кузницы Могильника.",al={"where to get rattlecage skulls","who drops rattlecage skulls","rattlecage skull location","где взять черепа гремучих скелетов","с кого падают черепа гремучих скелетов","где череп гремучего скелета"}},{q="Почему Вения Мартанд требует скелетные черепа для испытания чернокнижников?",a="Вения считает, что сила ускользает от невежд, а мастерство требует подчинить внешние силы своей воле. Убийство безмозглых скелетов и добыча их голов показывает, что ученик обладает основополагающей волей, чтобы управлять хаотичной энергией, а не быть поглощенным ею.",al={"why skulls for warlocks","venya marthand test","зачем чернокнижникам черепа","испытание вении мартанд"}},{q="Какие знания дает сбор этих черепов?",a="Когда черепа принесены, Вения Мартанд передает тайный ритуал призыва и подчинения беса, давая молодым чернокнижникам их первого настоящего демона-прислужника.",al={"what do you get from rattlecage skulls","piercing the veil reward","что дают черепа гремучих скелетов","награда за прорыв сквозь завесу"}}},fp="16,267,17.530.0,36.202.0,37.169.0,68.285.0,55.164.0"}
P.entries["item:raven-claw-talisman"] = {n="Талисман Когтя Ворона",s="Талисман Когтя Ворона — священная реликвия ночных эльфов, связанная с Друидами Когтя. Он хранится в глубине Обители Бен'этиль в Тельдрассиле и входит в число четырех важнейших Реликвий Пробуждения, нужных, чтобы безопасно вернуть спящих друидов из Изумрудного Сна.",h="Талисман Когтя Ворона — священная реликвия ночных эльфов, связанная с Друидами Когтя.",kw={"athridas bearmantle","ban'ethil","barrow den","dolanaar","druids of the talon","raven claw talisman","relics of wakening","teldrassil","атридас медвежья шкура","бен'этиль","обитель","доланаар","друиды когтя","талисман когтя ворона","реликвии пробуждения","тельдрассил"},ang={["class:Druid"]="Талисман — эмблема Друидов Когтя, показывающая, как ритуальные средоточия оберегают дух друида, блуждающего по Изумрудному Сну.",["race:NightElf"]="Возвращение этой реликвии защищает и древние традиции ночных эльфов, и жизни спящих сородичей, которым угрожает безумие фурболгов Скверной Сосны."},sec={{t="Ключ к пробуждению",b="Талисман Когтя Ворона хранится в особом сундуке внутри Обители Бен'этиль — подземного убежища, где Друиды Когтя Тельдрассила погрузились в глубокий медитативный сон. Друидская спячка — хрупкий духовный порог. Если связь друида с миром бодрствования разорвана без должного ритуального средоточия, его дух рискует навсегда застрять в Изумрудном Сне. Вместе с Черным пером, Небесным сапфиром и Руной Размещения талисман необходим Атридасу Медвежьей Шкуре в Доланааре, чтобы провести ритуал пробуждения и благополучно вернуть спящих."},{t="Угроза в Обители",b="Когда оскверненные фурболги Скверной Сосны захватили Обитель Бен'этиль, священные сундуки и спящие друиды оказались в смертельной опасности. Осквернение фурболгами отрезало святилище от помощи извне, и реликвии могли быть утрачены или уничтожены. Атридас Медвежья Шкура поручает защитникам Тельдрассила пройти по извилистым земляным ходам обители и добыть Талисман Когтя Ворона, пока изгнанные друиды не потеряны для Сна навсегда."}},faq={{q="Для чего нужен Талисман Когтя Ворона?",a="Это одна из четырех священных Реликвий Пробуждения, необходимых для ритуала, который пробуждает Друидов Когтя от глубокой спячки в Изумрудном Сне.",al={"what does the raven claw talisman do","raven claw talisman purpose","why do i need raven claw talisman","что делает талисман когтя ворона","назначение талисмана когтя ворона","зачем нужен талисман когтя ворона"}},{q="Где найти Талисман Когтя Ворона?",a="Он лежит в Сундуке Когтя Ворона, спрятанном в земляных туннелях Обители Бен'этиль, к западу от Доланаара в Тельдрассиле.",al={"where is raven claw talisman","chest of the raven claw location","how to find raven claw talisman","где талисман когтя ворона","сундук когтя ворона где","как найти талисман когтя ворона"}},{q="Кому нужен Талисман Когтя Ворона?",a="Атридасу Медвежьей Шкуре, друиду-ночному эльфу из Доланаара, талисман нужен, чтобы подготовить обряд пробуждения для своих изгнанных сородичей.",al={"who wants raven claw talisman","who takes the raven claw talisman","who do i turn this in to","кому нужен талисман когтя ворона","кто принимает талисман когтя ворона","кому это сдавать"}},{q="Почему друиды не могут проснуться без него?",a="Вход в Изумрудный Сон через друидскую спячку — сложный и хрупкий транс. Без особого средоточия Реликвий Пробуждения, закрепляющего ритуал, дух спящего рискует навсегда остаться потерянным в Сне.",al={"why do druids need relics to wake up","why relics of wakening","can druids wake up without relics","зачем друидам реликвии для пробуждения","зачем реликвии пробуждения","могут ли друиды проснуться без реликвий"}}},fp="19,260,18.627.0,28.447.0,41.158.0,39.135.0,34.136.0,40.243.0"}
P.entries["item:razorflank-s-medallion"] = {n="Медальон Чарлги Остробок",s="Медальон Чарлги Остробок — личный знак Чарлги Остробок, старухи, правящей Лабиринтами Иглошкурых. Добытый в сердце оплота свинобразов, он служит неоспоримым доказательством того, что матриарх повержена.",h="Медальон Чарлги Остробок — личный знак Чарлги Остробок, старухи, правящей Лабиринтами Иглошкурых.",kw={"agamaggan","charlga razorflank","falfindel waywarder","lonebrow","razorfen kraul","razorflank's medallion","thalanaar","агамагган","чарлга остробок","хранитель дорог фалфиндел","лонбро","лабиринты иглошкурых","медальон чарлги остробок","таланаар"},ang={["faction:Alliance"]="Возвращение медальона мстит за павшего разведчика Гералата и дворфа-исследователя Лонбро и обеспечивает безопасность пограничного пути Таланаара в Фералас.",["race:NightElf"]="Убив Чарлгу и забрав ее медальон, ночные эльфы смогут безопасно изучать оскверненные священные места упокоения Агамаггана."},sec={{t="Доказательство падения старухи",b="Этот медальон носила сама Чарлга Остробок, и он представляет власть старухи, возглавляющей свинобразов Иглошкурых. Когда Хранитель дорог Фалфиндел из Таланаара узнает о судьбе павших исследователей, таких как Гералат и дворф Лонбро, он поручает воинам Альянса нанести удар прямо по предводительнице свинобразов. Медальон старухи подтверждает ее смерть и успокаивает стражей-ночных эльфов, охраняющих границы Фераласа: собранные в Лабиринтах силы потеряли вожака."}},faq={{q="Кто носит Медальон Чарлги Остробок?",a="Медальон принадлежит Чарлге Остробок, старухе и бесспорной предводительнице свинобразов в Лабиринтах Иглошкурых. Она носит его при себе в глубине колючих лабиринтов оплота.",al={"who drops razorflanks medallion","razorflank medallion source","charlga medallion","с кого падает медальон чарлги остробок","источник медальона чарлги","медальон чарлги"}},{q="Кто хочет получить этот медальон?",a="Медальон просит Хранитель дорог Фалфиндел, стоящий на пограничном посту Таланаар между Фераласом и Тысячей Игл. Он ищет его как окончательное доказательство того, что Чарлга убита.",al={"who wants razorflank medallion","turn in razorflanks medallion","falfindel medallion","кому нужен медальон чарлги остробок","сдать медальон чарлги остробок","фалфиндел медальон"}},{q="Зачем Фалфинделу доказательство смерти Чарлги?",a="Чарлга собирала враждебное войско свинобразов в Лабиринтах Иглошкурых, угрожая окрестным землям, и из-за нее погибли разведчики, такие как Гералат и Лонбро. Принесенный медальон убеждает ночных эльфов, что непосредственная угроза сломлена, и позволяет продолжить исследования в этой местности.",al={"why kill charlga","purpose of medallion","why need medallion","зачем убивать чарлгу","назначение медальона","зачем нужен медальон"}}},fp="22,237,25.505.0,35.200.0,41.189.0,49.323.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Мешочек с реагентами (шаман)",s="Мешочек с реагентами, который носят культисты Пылающего Клинка, скрывающиеся в скалах Дуротара. Шаманам, стремящимся общаться с огнем, нужны эти собранные компоненты заклинаний, чтобы приготовить свою первую огненную сапту.",h="Мешочек с реагентами, который носят культисты Пылающего Клинка, скрывающиеся в скалах Дуротара.",kw={"burning blade","call of fire","durotar","dustwind cave","fire sapta","fire totem","reagent pouch","telf joolam","пылающий клинок","зов огня","дуротар","пещера пыльного ветра","огненная сапта","тотем огня","мешочек с реагентами","телф джулам"},ang={["class:Shaman"]="Добыча мешочка — важный обряд на пути к получению Тотема огня. Он учит, что даже оскверненные стихийные средства можно вернуть на службу равновесию.",["class:Warlock"]="Эти мешочки отражают обычные колдовские припасы культистов Скверны: в них лежат ритуальные компоненты для демонической пиромантии, а не для общения с природой."},sec={{t="Компоненты пламени",b="Чтобы создать огненную сапту и приобщить юного шамана к духам пламени, необходимы особые ритуальные катализаторы. Культисты Пылающего Клинка носят небольшие сумки с реагентами для демонических огненных призываний. Отшельник Телф Джулам использует эти порошки и масла вместе с огненной смолой иглогривых свинобразов, чтобы приготовить настой, дарующий зрение в мир огня."},{t="Оскверненные источники, чистое видение",b="Хотя Пылающий Клинок обращает пламя на разрушение и магию Скверны, вещества в их мешочках остаются связанными с изначальной природой жара и горения. Философия шаманов учит, что все стихии существуют в напряжении: огонь — и созидатель, и разрушитель. Забрав похищенные культистами орудия, шаман возвращает себе стихийное средство для подлинного общения с духами."}},faq={{q="Для чего нужен мешочек с реагентами?",a="Он служит важным материалом для Телфа Джулама, который варит огненную сапту. Выпив этот эликсир, шаман обретает провидческое зрение, необходимое, чтобы найти духов стихий и получить свой Тотем огня.",al={"reagent pouch use","what does reagent pouch do","reagent pouch shaman quest","для чего мешочек с реагентами","что делает мешочек с реагентами","задание шамана мешочек с реагентами"}},{q="Где найти мешочек с реагентами?",a="Мешочек добывают у культистов Пылающего Клинка в Пещере Пыльного Ветра, расположенной в скалистых возвышенностях к северо-востоку от Колючего Холма в Дуротаре.",al={"reagent pouch drop","where to get reagent pouch","burning blade pouch location","мешочек с реагентами добыча","где взять мешочек с реагентами","мешочек пылающего клинка где"}},{q="Почему шаману нужны реагенты чернокнижника?",a="Пылающий Клинок наполняет свои мешочки ингредиентами, пропитанными огненной магией. Поскольку их ритуалы во многом строятся на пламени, их реагенты — готовые стихийные катализаторы, которые можно использовать для приготовления огненной сапты.",al={"why warlock items","why burning blade reagents","shaman using fel items","почему вещи чернокнижника","почему реагенты пылающего клинка","шаман использует вещи скверны"}}},fp="22,197,23.400.0,28.406.0,35.198.0,32.145.0,40.224.0"}
P.entries["item:reconstructed-tome"] = {n="Восстановленный фолиант",s="Восстановленный фолиант — собранный по частям гримуар темных знаний заговора, созданный для чернокнижников, стремящихся расширить свое мастерство над демонскими слугами. В нем содержатся тайные знания и ритуалы, необходимые, чтобы призвать из Круговерти Пустоты хищного охотника Скверны и подчинить его.",h="Восстановленный фолиант — собранный по частям гримуар темных знаний заговора, созданный для чернокнижников...",kw={"binding","dragonmaw","felhunter","ratchet","reconstructed tome","strahad farsan","tome of the cabal","подчинение","драконья пасть","охотник скверны","кабестан","восстановленный фолиант","страхад фарсан","фолиант заговора"},ang={["class:Warlock"]="Сборка Восстановленного фолианта — необходимый обряд, открывающий темные ритуалы, с помощью которых чернокнижник подчиняет охотника Скверны и обращает его пожирающий магию голод против вражеских заклинателей."},sec={{t="Вновь собранный гримуар",b="Восстановленный фолиант, найденный в обрывках и кропотливо собранный заново, — редкое собрание учений заговора, официально известное как Фолиант заговора. Чернокнижники Альянса и Орды идут на многое, чтобы восстановить его истрепанные листы, и обращаются к знатокам тайных наук, жаждущим хотя бы взглянуть на его сокровенное содержание, прежде чем отдать готовую рукопись."},{t="Ключ к охотнику Скверны",b="Восстановленный труд относят Страхаду Фарсану, опытному мастеру призыва, живущему возле порта Кабестан в Степях. Вместе с волшебными жезлами направления, добытыми у заклинателей Драконьей Пасти, ритуалы из фолианта дают точные заклинания, с помощью которых круг служителей Страхада поможет чернокнижнику призвать, одолеть и подчинить своей воле ненасытного охотника Скверны."}},faq={{q="Для чего нужен Восстановленный фолиант?",a="Книга содержит темные ритуалы и учения заговора, необходимые, чтобы призвать и покорить охотника Скверны. Чернокнижник доставляет ее вместе с жезлами направления Страхаду Фарсану в Кабестан, чтобы подготовить ритуал подчинения.",al={"purpose of reconstructed tome","why need reconstructed tome","reconstructed tome use","назначение восстановленного фолианта","зачем нужен восстановленный фолиант","восстановленный фолиант применение"}},{q="Кто такой Страхад Фарсан?",a="Страхад Фарсан — опытный призыватель, живущий над портовым городом Кабестан в Степях. Он следит за трудными испытаниями начинающих чернокнижников, стремящихся поработить более опасных демонических существ.",al={"who is strahad","strahad farsan role","кто такой страхад","страхад фарсан роль"}},{q="Почему ученые, изучающие книгу, хотят получить копию?",a="Ученые, помогающие разбирать разорванные страницы, находят тайные тексты заговора невероятно увлекательными и редкими. Исследователи-дворфы и Отрекшиеся считают свое обычное чтение скудным по сравнению с этим и жаждут редких демонических знаний, сохранившихся на страницах.",al={"who translated it","scholars reconstructed tome","кто перевел","ученые восстановленный фолиант"}},{q="Что еще нужно для ритуала вместе с фолиантом?",a="Страхаду нужны три жезла направления, чтобы его служители могли поддерживать ритуал призыва. Эти жезлы нужно добыть у заклинателей Драконьей Пасти, засевших в Болотине.",al={"other items needed","what goes with reconstructed tome","другие нужные предметы","что нужно вместе с восстановленным фолиантом"}}},fp="18,269,22.395.0,20.401.1,40.208.0,22.198.0,51.264.0,54.179.0"}
P.entries["item:recruitment-letter"] = {n="Письмо о найме",s="Письмо о найме — официальное послание, которое получают многообещающие искатели приключений, покидающие Дуротар для службы в Степях. Его выдает разведчик Такрин Торитель Путей; письмо направляет здоровых добровольцев к пограничной заставе, которой командует Каргал Боевой Шрам.",h="Письмо о найме — официальное послание, которое получают многообещающие искатели приключений, покидающие...",kw={"barrens","conscript of the horde","crossroads","kargal battlescar","razor hill","recruitment letter","takrin pathseeker","степи","рекрут орды","перекресток","каргал боевой шрам","колючий холм","письмо о найме","такрин торитель путей"},ang={["faction:Horde"]="Это письмо означает переход новобранца от местной обороны в Дуротаре к активной военной службе на границе Калимдора.",["race:Orc"]="Для молодых орков вручение подписанного письма ветерану вроде Каргала Боевого Шрама — важный ранний шаг к чести в новой Орде вождя Тралла."},sec={{t="Набор на границу",b="Пока молодые воины и разведчики проявляют себя вокруг Колючего Холма, взор Орды обращается на запад, к обширным диким просторам Степей. Такрин Торитель Путей выбирает перспективных новобранцев, способных нести службу на передовой, и вручает им это письмо. Переход через мост на реке Строптивой становится обрядом посвящения: новобранец оставляет защищенную красную землю Дуротара и вступает в ряды Орды, стоящей на страже против свинобразов, кентавров и разведчиков Альянса."},{t="Доклад Боевому Шраму",b="Письмо предназначено для Каргала Боевого Шрама, закаленного ветерана, командующего заставой сразу за рекой. Каргал оценивает каждого призывника, прежде чем официально подтвердить его зачисление. Но письмо — лишь первый шаг: пограничные заставы всегда испытывают нехватку людей, и каждого зачисленного быстро отправляют дальше на запад, в стратегический узел — на Перекресток."}},faq={{q="Кто написал это письмо о найме?",a="Письмо выдает Такрин Торитель Путей, орк-разведчик, стоящий на дороге из Колючего Холма и высматривающий способных новобранцев, идущих на запад.",al={"who gives recruitment letter","who wrote it","takrin pathseeker letter","кто выдает письмо о найме","кто написал письмо","такрин торитель путей письмо"}},{q="Куда нужно отнести это письмо?",a="Вы относите его Каргалу Боевому Шраму на орочий сторожевой пост сразу за мостом через реку Строптивую, на границе Дуротара и Степей.",al={"where do i take recruitment letter","turn in recruitment letter","who do i give it to","куда отнести письмо о найме","сдать письмо о найме","кому отдать письмо"}},{q="Что происходит после подписания письма?",a="Каргал подписывает документ, подтверждая ваше зачисление, но тут же приказывает вам идти дальше в степь и явиться на службу на Перекресток, где срочно нужны подкрепления.",al={"what happens after kargal signs","next quest after recruitment letter","что после подписи каргала","следующее задание после письма о найме"}},{q="Почему Орда призывает искателей приключений в Степях?",a="Степи — обширная и опасная территория, соединяющая крупные поселения Орды. Из-за постоянных угроз от местных кланов кентавров, агрессивных дыбогривов-свинобразов и действий Альянса командирам на передовой нужен каждый боеспособный.",al={"why are they recruiting","why conscription barrens","почему вербуют","почему призыв в степях"}}},fp="18,253,27.482.0,23.395.0,34.157.0,34.152.0,39.187.0,57.256.0"}
P.entries["item:red-burlap-bandana"] = {n="Красная холщовая бандана",s="Красные холщовые банданы — грубые окрашенные тканевые маски, которые носят рядовые разбойники и воры Братства Справедливости. В Долине Североземья Заместитель судьи Виллем собирает эти лоскуты как доказательство гибели воров, подбирающихся к виноградникам аббатства.",h="Красные холщовые банданы — грубые окрашенные тканевые маски, которые носят рядовые разбойники и воры Братства...",kw={"bandana","brotherhood of thieves","defias","mask","northshire","red burlap bandana","willem","бандана","братство воров","братство справедливости","маска","североземье","красная холщовая бандана","виллем"},ang={["class:Rogue"]="Для начинающего разбойника снимать красные маски с неуклюжих грабителей Североземья — урок того, как быстро недисциплинированные преступники становятся легкой добычей местной стражи.",["faction:Alliance"]="Появление этих красных бандан у самого порога Аббатства Североземья показывает, насколько сильно сельские границы королевства выходят из-под контроля Штормграда."},sec={{t="Знак Братства",b="Красная холщовая бандана, повязанная на нижнюю часть лица, служит опознавательным знаком рядовых членов Братства Справедливости. Она сделана из дешевой грубой ткани, пропитанной красной краской, скрывает черты вора и показывает верность растущему мятежу. В Североземье молодые новобранцы и обычные головорезы носят эти повязки в восточные сады, не зная, что местная стража использует яркую красную ткань как мрачную метку награды."}},faq={{q="Зачем Заместителю судьи Виллему эти банданы?",a="Заместитель судьи Виллем собирает банданы как вещественное доказательство того, что искатель приключений уничтожил головорезов Братства Справедливости, подбирающихся через реку к Аббатству Североземья. Поскольку воры открыто носят красную ткань, сданные банданы подтверждают выплату наград за местных разбойников.",al={"why collect bandanas","willem bandanas","brotherhood of thieves turn in","зачем собирать банданы","виллем банданы","братство воров сдать"}},{q="Кто носит красные холщовые банданы?",a="Их носят грабители и головорезы из Братства Справедливости — организованной шайки преступников, действующей по всему Элвиннскому лесу и Западному Краю. Грубая красная ткань служит и маскировкой, и знаком верности их подпольному союзу.",al={"who wears red bandana","defias mask lore","who drops red bandanas","кто носит красную бандану","маска братства справедливости","с кого падают красные банданы"}},{q="Почему воры Братства Справедливости орудуют в Североземье?",a="Разведчики и разбойники Братства Справедливости устроили лагеря за ручьем к востоку от Аббатства Североземья, чтобы мародерствовать, красть припасы и следить за движением из Штормграда. Гарнизон аббатства малочислен, поэтому разбойники низкого уровня свободно бродят по ближним садам.",al={"why are defias in northshire","thieves near abbey","почему братство справедливости в североземье","воры у аббатства"}},{q="Почему банданы красные?",a="Банданы — просто куски дешевой мешковины, окрашенные в багровый цвет. Этот особый цвет служит знаменем и формой Братства Справедливости, чтобы соратники узнавали друг друга.",al={"why are defias masks red","red cloth meaning","почему маски братства красные","значение красной ткани"}}},fp="18,254,25.446.0,43.285.0,34.248.0,47.264.0,28.221.0"}
P.entries["item:red-leather-bandana"] = {n="Красная кожаная бандана",s="Характерная часть одежды членов Братства Справедливости в Западном Крае. Сделана из окрашенной в багровый цвет кожи и служит и практичной повязкой на лицо, и безошибочным символом неповиновения Короне Штормграда.",h="Характерная часть одежды членов Братства Справедливости в Западном Крае.",kw={"brotherhood","defias","galiaan","mask","red leather bandana","sentinel hill","westfall","братство","братство справедливости","галиан","маска","красная кожаная бандана","сторожевой холм","западный край"},ang={["class:Rogue"]="Багровая маска — синоним подпольного бандитизма в землях людей, безошибочный знак воров, организованных с военной четкостью.",["faction:Alliance"]="Каждая красная бандана, снятая с павшего преступника, означает на одного разбойника меньше, угрожающего голодающим фермерам и осажденному ополчению Западного Края."},sec={{t="Знак Братства",b="На пыльных полях и заброшенных фермах Западного Края эти багровые банданы скрывают лица разбойников, мародеров и мятежных работников. Для Народного ополчения, расквартированного в Сторожевом холме, этот головной убор — не просто ткань, а явное доказательство верности шайке Эдвина ван Клифа. Разведчик Галиан собирает эти банданы у проходящих мимо искателей приключений, чтобы следить за перемещениями и сокращающейся численностью братства в регионе."}},faq={{q="Почему Братство Справедливости носит красные кожаные банданы?",a="Красная бандана — единая форма Братства Справедливости. Она скрывает личности при набегах на фермы и дороги и открыто заявляет о верности восстанию Эдвина ван Клифа против Штормграда.",al={"defias mask","why red bandana","defias bandana meaning","маска братства справедливости","почему красная бандана","значение банданы братства справедливости"}},{q="Кто просит собирать эти банданы в Западном Крае?",a="Разведчик Галиан, расквартированный с Народным ополчением в Сторожевом холме, просит путников собирать их. Он использует их, чтобы отслеживать передвижения отрядов банды и подтверждать гибель бродячих бандитов.",al={"who takes red bandanas","galiaan bandana quest","sentinel hill bandana turn in","кто принимает красные банданы","задание галиана бандана","сдать бандану сторожевой холм"}},{q="Где найти эти банданы?",a="Их можно снять почти с любого разбойника, грабителя или контрабандиста на службе Братства Справедливости в лагерях, на полях и в шахтах Западного Края.",al={"red bandana drop","farm red bandanas","who drops red leather bandana","красная бандана добыча","фарм красных бандан","с кого падает красная кожаная бандана"}}},fp="19,236,23.473.0,44.220.0,47.184.0,31.139.0"}
P.entries["item:red-linen-bandana"] = {n="Красная льняная бандана",s="Красная льняная бандана — характерная маска, которую носят члены Братства Справедливости в Элвиннском лесу. Помимо того что она скрывает личность разбойника, ткань сделана из качественного льна, и находчивые местные жители часто пускают ее на полезную одежду.",h="Красная льняная бандана — характерная маска, которую носят члены Братства Справедливости в Элвиннском лесу.",kw={"defias mask","eastvale","elwynn forest","linen","red linen bandana","sara timberlain","маска братства","восточная долина","элвиннский лес","лен","красная льняная бандана","сара тимберлейн"},ang={["class:Rogue"]="Алая ткань, повязанная на нижнюю часть лица, стала привычным обликом грабителей с большой дороги и карманников в лесах вокруг столицы.",["profession:Tailoring"]="Банданы показывают, как ценен необработанный тканый лен в сельском Элвинне, где простые ткачи превращают цвета бандитов в рабочую одежду."},sec={{t="Знак Братства Справедливости",b="Если рядовые новички и простые головорезы в Долине Североземья обходятся грубыми масками из мешковины, то полноправные агенты Братства Справедливости по всему Элвиннскому лесу носят тканые красные льняные банданы. Ярко-алая ткань служит и формой, и заявлением о верности разбойничьему братству Эдвина ван Клифа: она скрывает лица и в то же время выражает мятеж против короны Штормграда."},{t="Ткань на новый лад",b="Несмотря на жестокие ассоциации, банданы скроены из добротной ткани. Практичные поселенцы, такие как Сара Тимберлейн из Лесопилки Восточной долины, постоянно просят путников собирать их в лагерях преступников. После стирки и шитья запрещенная ткань превращается в прочную одежду и бинты для трудового люда леса."}},faq={{q="Почему члены Братства Справедливости носят красные льняные банданы?",a="Красная бандана служит формой и знаком неповиновения Штормграду: она скрывает личность владельца и показывает его верность братству Эдвина ван Клифа.",al={"defias mask meaning","why red masks","defias red bandana","значение маски братства","почему красные маски","красная бандана братства справедливости"}},{q="Чем они отличаются от масок, которые носят в Североземье?",a="Головорезы в Долине Североземья носят грубые маски из мешковины, а опытные агенты Братства Справедливости по всему Элвиннскому лесу — более тонкий красный лен.",al={"burlap vs linen","northshire masks","burlap bandana","мешковина и лен","маски североземья","бандана из мешковины"}},{q="Кому нужны эти банданы?",a="Их собирает Сара Тимберлейн на Лесопилке Восточной долины. Будучи швеей, которой не хватает ткани, она стирает и распускает бандитские маски, чтобы выткать из них практичную одежду.",al={"who takes red linen bandanas","sara timberlain bandana","bandana quest turn in","кто берет красные льняные банданы","сара тимберлейн бандана","сдать задание на банданы"}},{q="У каких врагов есть красные льняные банданы?",a="Они есть почти у всех агентов Братства Справедливости в Элвиннском лесу, включая бандитов, налетчиков, мятежных чародеев, портовых рабочих и главарей, таких как Морган Вымогатель.",al={"who drops red linen bandana","where to farm bandanas","defias bandana drops","кто роняет красную льняную бандану","где добыть банданы","банданы братства с врагов"}}},fp="17,253,18.390.0,16.360.0,42.167.0,54.146.0,36.169.0,39.168.0"}
P.entries["item:red-wool-bandana"] = {n="Красная шерстяная бандана",s="Красные шерстяные банданы — самодельные символы, которые мастерят заключенные головорезы из Братства Справедливости в Тюрьме Штормграда. Их рвут из тюремных шерстяных одеял, и они служат вызывающими знаками братства даже за решеткой.",h="Красные шерстяные банданы — самодельные символы, которые мастерят заключенные головорезы из Братства...",kw={"defias","mac raskol","nikova raskol","red wool bandana","stormwind","the color of blood","the stockade","братство справедливости","мак раскол","никова раскол","красная шерстяная бандана","штормград","цвет крови","тюрьма"},ang={["faction:Alliance"]="Для защитников Альянса возвращение этих бандан — суровый акт справедливости для юного Мака Раскола и удар по бунтовщикам, захватившим городскую тюрьму.",["profession:Tailoring"]="Эти грубые банданы показывают, что даже жесткие шерстяные одеяла можно распустить и переделать в руках отчаявшихся узников."},sec={{t="Сшито назло",b="Даже запертые за высокими каменными стенами Тюрьмы Штормграда, члены Братства Справедливости не желают отказываться от своей принадлежности. Из обрывков тюремных шерстяных одеял заключенные тайно мастерят красные банданы как опознавательные цвета. Для стражи эти повязки — запрещенный предмет, вызывающий смертельные мятежи; для заключенных — знак того, что их братство и бунт живы даже в оковах."},{t="Месть бабушки",b="Банданы приобрели горькую известность после того, как четырнадцатилетний тюремный стражник Мак Раскол застал заключенных за раздиранием одеял. Когда он попытался их наказать, осужденные из Братства Справедливости ударили его ножом в спину. После его гибели скорбящая бабушка Никова ищет искателей приключений, которые спустятся в охваченную бунтом темницу, перебьют мятежников и принесут алую ткань как доказательство мести."}},faq={{q="Где заключенные Тюрьмы берут эти банданы?",a="Заключенные из Братства Справедливости делают их, разрывая выданные в тюрьме шерстяные одеяла. Хотя они разоружены и сидят в заключении, скудную постель они превращают в символы неповиновения и носят их в камерах.",al={"where do bandanas come from","stockade bandana source","how do they make red bandanas","откуда банданы","источник бандан в тюрьме","как делают красные банданы"}},{q="Кто просит собрать эти банданы?",a="Никова Раскол, скорбящая бабушка из Штормграда, просит искателей приключений собрать их. Ее четырнадцатилетний внук Мак был стражником Тюрьмы и был убит заключенными после того, как застал их за изготовлением бандан.",al={"who needs red wool bandanas","color of blood quest giver","nikova raskol bandana","кому нужны красные шерстяные банданы","цвет крови задание","никова раскол бандана"}},{q="Почему заключенным так важно носить красные повязки?",a="Братство Справедливости носит красные маски и банданы как основные цвета и форму банды. За решеткой изготовление и ношение этих лоскутов позволяет заключенным сохранять иерархию, боевой дух и единство.",al={"why red bandanas","defias red symbol","meaning of red bandana","почему красные банданы","красный символ братства","значение красной банданы"}},{q="У каких заключенных они есть?",a="Они есть почти у любого бунтующего члена Братства Справедливости в Тюрьме, включая пленников, заключенных, арестантов, мятежников и осужденных.",al={"who drops red wool bandana","stockade bandana drops","кто роняет красную шерстяную бандану","банданы из тюрьмы"}}},fp="16,210,20.424.0,25.415.0,54.196.0,35.205.0,60.197.0,25.142.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Оставшиеся капли чистейшей воды",s="Оставшиеся капли чистейшей воды — последний остаток особого отвара, приготовленного провидицей воды Брин. Шаманы с этими сильными каплями отправляются через королевства, чтобы очистить священное водное святилище, оскверненное мертвой чумой Плети.",h="Оставшиеся капли чистейшей воды — последний остаток особого отвара, приготовленного провидицей воды Брин.",kw={"brazier of everfount","brine","call of water","corrupt manifestation","purest water","silverpine","water totem","жаровня вечного источника","брин","зов воды","оскверненное воплощение","чистейшая вода","серебряный бор","тотем воды"},ang={["class:Shaman"]="Эти капли — венец ваших испытаний в овладении водой. Чтобы получить Тотем воды, их необходимо донести из засушливых Степей до зараженного побережья Серебряного бора.",["faction:Horde"]="Паломничество шамана связывает земли Орды в Калимдоре с шаткими владениями Отрекшихся в Серебряном бору и показывает, как далеко простирается духовное исцеление против порчи Плети."},sec={{t="Лекарство для оскверненных вод",b="Этот концентрированный эликсир, созданный обрядовым сбором по Калимдору и Лордерону, хранит чистейшую сущность воды; его приготовила отшельница Брин в Степях. Часть отвара расходуется, чтобы даровать шаманам видение далеких стихий, а оставшиеся капли берегут для куда более опасной задачи. Их доставляют на пораженный чумой берег Серебряного бора возле Гробницы, где они служат главным очищающим средством на Жаровне Вечного источника. Сгорая в обрядовом пламени вместе с наручами павшего оскверненного элементаля, чистая вода рассекает мертвенную скверну и призывает незапятнанного духа воды, чтобы он общался с шаманом и завершил его единение со стихией."}},faq={{q="Для чего нужны эти капли?",a="Их помещают на Жаровню Вечного источника на побережье Серебряного бора вместе с наручами оскверненного воплощения воды. Обряд очищает оскверненное святилище стихии и призывает неоскверненного духа воды.",al={"what do remaining drops do","remaining drops purpose","use purest water","что делают оставшиеся капли","назначение оставшихся капель","применение чистейшей воды"}},{q="Откуда взялась эта жидкость?",a="Это остатки очищающего отвара, сваренного Брин, орчихой-шаманкой, которая живет на холме в южных Степях. Отвар создается во время духовных испытаний, которые проходят начинающие шаманы.",al={"who made purest water","origin of drops","brine water drops","кто сделал чистейшую воду","происхождение капель","капли воды брина"}},{q="Почему обряд проводят так далеко, в Серебряном бору?",a="Водное святилище на побережье Серебряного бора к западу от Гробницы было осквернено чумой нежизни, и его духи стихий стали враждебными и искаженными. Очищение именно этого пруда доказывает преданность и мастерство шамана на больших расстояниях.",al={"why silverpine","why travel to silverpine","silverpine water shrine","почему серебряный бор","зачем идти в серебряный бор","водное святилище серебряного бора"}},{q="Что происходит, когда капли касаются жаровни?",a="Когда капли выливают на пламя жаровни вместе с оскверненными наручами, они потрескивают в огне, и вспыхивает заклинание, которое очищает остатки чумы и призывает чистое воплощение воды.",al={"brazier ritual","what happens on brazier","brazier of everfount ritual","обряд на жаровне","что происходит на жаровне","обряд жаровни вечного источника"}}},fp="31,249,27.730.0,30.228.0,31.194.0,61.246.0,41.206.0"}
P.entries["item:remedy-of-arugal"] = {kw={"arugal","arugal's folly","dalar dawnweaver","dusty spellbooks","moonrage","remedy of arugal","sepulcher","silverpine forest","аругал","безумие аругала","далар ткач рассвета","пыльные книги заклинаний","лунный гнев","зелье аругала","гробница","серебряный бор"},ang={["class:Mage"]="Маги из числа Отрекшихся разделяют профессиональное презрение Далара Ткача Рассвета к неуклюжим и безрассудным опытам Аругала, но признают опасность, скрытую в неукрощенной магии призыва.",["race:Undead"]="Для Отрекшихся добыча этого заклинания — ранний и важный шаг в отпоре одичавшим воргенам, угрожающим границам Серебряного бора."},sec={{t="Наследие мага",b="Перед захватом Крепости Темного Клыка верховный маг Аругал укрывался на заброшенной пшеничной ферме к северу от речного моста в Серебряном бору. Там, среди забытых сельских орудий и гнилых половиц, он записал свои странные искусства в нескольких пыльных книгах заклинаний. Свиток под названием «Зелье Аругала» входит в эти записи: в нем изложены ранние методы и магические составы, которые он придумал, занимаясь опасными превращениями, проклявшими местных жителей."},{t="Пристальный взгляд Отрекшихся",b="Далар Ткач Рассвета, опытный заклинатель из числа Отрекшихся, действующий из Гробницы, невысоко ценит происхождение Аругала и считает ум бывшего даларанского чародея хрупким и прозрачным. Тем не менее Ткач Рассвета понимает, что необходимо срочно разобраться в точном устройстве проклятия воргенов. Добывая Зелье Аругала, агенты Отрекшихся дают Ткачу Рассвета основы тайных знаний, нужные для борьбы с растущей угрозой Аругала и для удержания Серебряного бора за леди Сильваной."}},faq={{q="Что такое Зелье Аругала?",a="Это магическая формула, записанная мятежным магом Аругалом. Это не лечебное снадобье, а письменное заклинание с тайными приемами, которые он применял, когда начал опыты с магией воргенов в Серебряном бору.",al={"what is remedy of arugal","arugal remedy item","remedy spell","что такое зелье аругала","предмет зелье аругала","заклинание зелье"}},{q="Где осталось Зелье?",a="Аругал оставил его среди пыльных книг заклинаний на верхнем этаже заброшенной пшеничной фермы к северу от моста через реку в Серебряном бору.",al={"where to find remedy of arugal","remedy of arugal location","farm spellbook","где найти зелье аругала","местонахождение зелья аругала","книга заклинаний на ферме"}},{q="Зачем Далару Ткачу Рассвета это заклинание?",a="Далар Ткач Рассвета хочет изучить именно ту магию, которую применял Аругал, чтобы Отрекшиеся могли создать защиту от нее и, обратив методы чародея против него самого, удержать область.",al={"why does dalar want the remedy","dalar dawnweaver remedy","зачем далару зелье","далар ткач рассвета зелье"}},{q="Кто охраняет книги заклинаний на ферме?",a="Ферма кишит волкоподобными слугами Аругала. Когда кто-то пытается потревожить пыльные книги заклинаний на втором этаже, из тени выпрыгивает Темный бегун Лунной Ярости, защищая имущество хозяина.",al={"what attacks at the farm","spellbook ambush","кто нападает на ферме","засада у книг заклинаний"}}},fp="16,250,18.455.0,17.498.0,29.235.0,33.172.0,42.198.0,38.205.0"}
P.entries["item:rendered-spores"] = {n="Топленые споры",s="Топленые споры — летучая эмульсия, приготовленная из образцов грибов, собранных в Степях. Ее создает аптекарь Хелбрим на Перекрестке, и смесь быстро портится, если не доставить ее аптекарю Заме под Громовым Утесом для стабилизации.",h="Топленые споры — летучая эмульсия, приготовленная из образцов грибов, собранных в Степях.",kw={"apothecary helbrim","apothecary zamah","barrens","crossroads","emulsion","pools of vision","rendered spores","thunder bluff","аптекарь хелбрим","аптекарь зама","степи","перекресток","эмульсия","пруды видений","топленые споры","громовой утес"},ang={["race:Tauren"]="Присутствие аптекарей Отрекшихся, ставящих опыты на странной флоре Степей в священных Прудах Видений, отражает непростой, но практичный союз, сложившийся в Громовом Утесе.",["race:Undead"]="Королевское фармацевтическое общество постоянно ищет по всему Калимдору новые биологические соединения для помощи Отрекшимся и полагается на быстрых курьеров, связывающих полевых исследователей вроде Хелбрима с лабораторными специалистами вроде Замы."},sec={{t="Нестойкая смесь",b="Добыв странные грибные споры из грибов у сырых оазисов Степей, аптекарь Хелбрим перерабатывает их в активную химическую эмульсию, известную как Топленые споры. Тонкая экстракция удерживает сильнодействующие вещества грибов в жидкой среде, но раствор химически нестабилен. Его действенность сохраняется лишь сорок пять минут, после чего он распадается и становится совершенно бесполезным для научных исследований."},{t="Доставка к Прудам Видений",b="Поскольку в своей глухой стоянке у Хелбрима нет нужного оборудования или времени, чтобы завершить очистку, эмульсию нужно срочно доставить его коллеге из Отрекшихся — аптекарю Заме. Она скрывается в подземных Прудах Видений под Вершиной Духов в Громовом Утесе, где у нее есть специальное оборудование и реагенты, чтобы закрепить и завершить обработку спор для Королевского фармацевтического общества."}},faq={{q="Для чего нужны Топленые споры?",a="Это грибное вещество, которое аптекарь Хелбрим извлекает и превращает в эмульсию для исследований Королевского фармацевтического общества. Аптекарь Зама использует эту сильную смесь в Громовом Утесе, продолжая изучать странные наросты, расползающиеся по Степям.",al={"purpose of rendered spores","what does zamah do with spores","why rendered spores","назначение топленых спор","что зама делает со спорами","зачем топленые споры"}},{q="Почему у эмульсии есть срок годности?",a="Химическая эмульсия, созданная Хелбримом, крайне нестабильна и начинает портиться сразу после смешивания. Ее сила держится лишь сорок пять минут, поэтому курьер должен быстро доставить ее через равнины в Громовой Утес, пока она не стала инертной.",al={"why are rendered spores timed","why do spores expire","rendered spores duration","почему топленые споры на время","почему споры портятся","срок действия топленых спор"}},{q="Кто создал эти споры?",a="Аптекарь Хелбрим, исследователь из Отрекшихся, расквартированный на Перекрестке в Степях, растопил сырые грибные споры, собранные с грибов у оазисов, в это нестабильное жидкое соединение.",al={"who made rendered spores","who renders the spores","helbrim spores","кто сделал топленые споры","кто топит споры","хелбрим споры"}},{q="Куда нужно доставить смесь?",a="Споры нужно доставить аптекарю Заме. Она живет глубоко в Прудах Видений — системе пещер под Вершиной Духов в столице тауренов Громовом Утесе.",al={"where to bring rendered spores","zamah location","pools of vision location","куда нести топленые споры","где зама","где пруды видений"}}},fp="15,257,18.452.0,31.417.0,34.273.0,40.261.0,25.187.0,34.177.0"}
P.entries["item:renferrel-s-findings"] = {n="Находки Ренферрела",s="«Находки Ренферрела» — собрание исследовательских записей, составленных аптекарем Ренферрелом в Серебряном бору. Эти документы доверяют курьерам Орды, и те несут важные данные на юг, аптекарю Лидону в Мельницу Таррен, чтобы помочь в создании Новой чумы Отрекшихся.",h="«Находки Ренферрела» — собрание исследовательских записей, составленных аптекарем Ренферрелом в Серебряном...",kw={"findings","lydon","new plague","renferrel","royal apothecary society","sepulcher","tarren mill","находки","лидон","новая чума","ренферрел","королевское фармацевтическое общество","гробница","мельница таррен"},ang={["faction:Horde"]="Курьеры, доставляющие бумаги Ренферрела, помогают укрепить позиции Орды в Лордероне, связывая обособленные оплоты, такие как Гробница и Мельница Таррен.",["race:Undead"]="Исследования в этих документах служат главной цели Сильваны Ветрокрылой: создать совершенную Новую чуму, чтобы истребить и Плеть, и живых врагов, вторгающихся в земли Отрекшихся."},sec={{t="Чума в разработке",b="Королевское фармацевтическое общество трудится не покладая рук по прямому приказу Темной Госпожи, леди Сильваны Ветрокрылой, чтобы создать Новую чуму. Для такого прорыва необходимо постоянное сотрудничество исследователей, разбросанных по всему Лордерону. Аптекарь Ренферрел, находящийся в Гробнице в Серебряном бору, собирает эти записи, чтобы фиксировать свои успехи и опыты, и отправляет собранные сведения на юг, в Мельницу Таррен, чтобы коллеги могли развить его результаты."},{t="В Мельницу Таррен",b="Доставка этих бумаг через границу из Серебряного бора в Предгорья Хилсбрада — важное звено алхимической сети Отрекшихся. В Мельнице Таррен аптекарь Лидон с нетерпением ждет записей Ренферрела, чтобы сверить их и усовершенствовать собственные составы против живых и Плети. Без надежных курьеров на спорных дорогах Хилсбрада разрозненные исследования Общества быстро застопорились бы."}},faq={{q="Что содержится в «Находках Ренферрела»?",a="В пакете находятся новейшие экспериментальные данные и исследовательские записи, собранные аптекарем Ренферрелом во время работы в Серебряном бору, в частности по синтезу Новой чумы для Отрекшихся.",al={"what are the findings","renferrel research","what is in the notes","что за находки","исследования ренферрела","что в записях"}},{q="Кто должен получить это исследование?",a="Документы получает аптекарь Лидон. Он проводит исследования чумы в Мельнице Таррен — поселении Отрекшихся в Предгорьях Хилсбрада.",al={"who gets renferrels findings","where do the findings go","delivery target","кто получает находки ренферрела","куда доставить находки","получатель"}},{q="Почему аптекари делятся записями?",a="Леди Сильвана Ветрокрылая сильно давит на Королевское фармацевтическое общество, требуя создать Новую чуму. Аптекари считают, что прорыв наступит гораздо скорее, если согласовывать действия и сравнивать результаты, а не работать поодиночке.",al={"why share findings","why send to lydon","apothecary communication","зачем делиться находками","зачем отправлять лидону","связь аптекарей"}},{q="Где аптекарь Ренферрел проводит свои опыты?",a="Аптекарь Ренферрел находится в Гробнице — главном оплоте Отрекшихся в сердце Серебряного бора.",al={"where is renferrel","apothecary renferrel location","who wrote renferrels findings","где ренферрел","где находится аптекарь ренферрел","кто написал находки ренферрела"}}},fp="20,264,23.486.0,14.425.0,36.213.0,41.143.0,39.254.0,56.123.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Донесение Братства Справедливости",s="«Донесение Братства Справедливости» — официальный документ, составленный городским архитектором Баросом Алекстоном; в нем описаны действия и угроза заговорщиков Эдвина ван Клифа. Он предназначен для королевского двора и доверен искателю приключений, раскрывшему заговор в Мертвых копях, для личной доставки в Крепость Штормграда.",h="«Донесение Братства Справедливости» — официальный документ, составленный городским архитектором Баросом...",kw={"audience with the king","baros alexston","defias","report","stormwind keep","vancleef","westfall","аудиенция у короля","барос алекстон","братство справедливости","донесение","крепость штормграда","ван клиф","западный край"},ang={["faction:Alliance"]="Доставка этого донесения завершает долгую борьбу за безопасность Западного Края и предупреждает руководство Штормграда о мятеже, зреющем на его границах.",["race:Human"]="Для людей королевства доставка этого донесения подчеркивает трагический неразрешенный конфликт между благородным домом Штормграда и каменщиками, отстроившими город."},sec={{t="Донесение для трона",b="После долгого расследования беспорядков в Западном Крае и окрестных землях городской архитектор Барос Алекстон подготовил это официальное донесение, чтобы предупредить руководство Штормграда о всей серьезности угрозы Братства Справедливости. Вместо обычного королевского гонца Алекстон доверил документ герою, распутавшему заговор. Донесение доставляется прямо в Крепость Штормграда и должно сопровождаться личной аудиенцией, на которой будут изложены замыслы Эдвина ван Клифа и опасность, которую они несут королевству."},{t="Прием в Крепости",b="Хотя донесение адресовано королю Вариану Ринну, курьер приходит в тронный зал и обнаруживает, что монарха нет: он отбыл в тайную дипломатическую поездку. Вместо него донесение принимают королевские советники и регентский совет при юном короле Андуине. Хотя за пресечение козней ван Клифа выражается королевская благодарность, присутствие при дворе таких фигур, как леди Катрана Престор, бросает тень сомнения на то, насколько серьезно отнесутся к предупреждениям в документе."}},faq={{q="Что такое «Донесение Братства Справедливости»?",a="Это официальный отчет, написанный Баросом Алекстоном, в котором собраны все сведения об Эдвине ван Клифе, его подземной армии и более широком заговоре Братства Справедливости против Штормграда.",al={"what is this report","defias report item","baros alexston report","что это за донесение","предмет донесение братства справедливости","донесение бароса алекстона"}},{q="Кто написал это донесение?",a="Документ подготовил Барос Алекстон, городской архитектор Штормграда, который некогда работал вместе с каменщиками, прежде чем те откололись и образовали Братство Справедливости.",al={"who made the defias report","report author","кто составил донесение","автор донесения"}},{q="Почему я должен доставить это в Крепость Штормграда?",a="Барос Алекстон считает, что искатель приключений, раскрывший заговор, заслуживает чести лично представить выводы трону и получить королевское признание за защиту королевства.",al={"why do i deliver this","audience with the king delivery","зачем доставлять это","доставка на аудиенцию к королю"}},{q="Читает ли король Вариан это донесение?",a="Нет. Когда вы прибываете в Крепость Штормграда, короля Вариана Ринна там нет: по слухам, он отбыл в тайную дипломатическую поездку. Документ принимают его королевский двор и регентский совет.",al={"does the king read it","varian wrynn audience","читает ли король","аудиенция вариана ринна"}}},fp="32,323,25.528.0,21.473.1,45.199.0,22.174.0,43.192.0,33.177.0"}
P.entries["item:resonite-crystal"] = {n="Кристалл резонита",kw={"boulderslide","crystal","earthen","kobold","mor'rogal","resonite","stonetalon","titans","камнепады","кристалл","земельные","кобольд","мор'рогал","резонит","когтистые горы","титаны"},ang={["class:Shaman"]="Кристаллы резонита несут для шаманов тревожный резонанс: они чувствуют дремлющую изначальную магию земли, оставленную творениями Титанов, давно погребенными под горами.",["profession:Mining"]="В отличие от обычных медных или оловянных жил, резонит — исключительно концентрированное минеральное образование, для добычи которого нужно пробиться мимо агрессивных кобольдов в самые глубокие подземные пласты."},sec={{t="Древний резонанс",b="Кристаллы резонита, скрытые в глубинах Ущелья Камнепадов, стали предметом внезапной лихорадочной добычи кобольдов. Обычные пещерные рудокопы ищут простую руду или блестящие безделушки, а одержимость кобольдов именно этими образованиями сразу встревожила шаманов Приюта у Солнечного Камня. При внимательном осмотре камни гудят слабым магическим резонансом, связанным с изначальным созданием мира. Мор'рогал определил эти слабые энергии как следы магии земельных, а значит, роющие твари проникли в древний пласт, созданный Титанами."},{t="Прикосновение к земле",b="Открытие резонита подтверждает тревожные вести для Орды в Когтистых горах: кобольды-копатели забрались достаточно глубоко, чтобы потревожить древних земельных. Поскольку Титаны создали земельных, чтобы те высекали и формировали основы мира, остаточная магия упорно держится в окружающей породе. Собирая эти кристаллы, агенты Орды надеются разгадать лихорадочные замыслы кобольдов и обратить силу зачарованного камня против тех дремлющих сил, что были потревожены внизу."}},faq={{q="Где найти кристаллы резонита?",a="Кристаллы резонита находятся в Пещере Камнепадов — глубокой пещере в Ущелье Камнепадов на юго-востоке Когтистых гор.",al={"resonite location","where to get resonite","resonite crystal farm","где резонит","где достать резонит","фарм кристаллов резонита"}},{q="Почему кобольды добывают кристаллы резонита?",a="The kobolds are frantically mining the rare crystals, but Mor'rogal does not yet know why. He asks for samples and an investigation of the cave's depths to understand their activity.",al={"why kobolds mining","kobold crystal plot","boulderslide kobolds","зачем кобольды добывают","замысел кобольдов с кристаллами","кобольды камнепадов"}},{q="Какая сила заключена в кристалле резонита?",a="Mor'rogal suspects the crystals are connected to something troubling beneath the mountains. Their magical nature is identified after samples and news from the cavern reach him.",al={"resonite crystal magic","what is resonite","is resonite magical","магия кристалла резонита","что такое резонит","магический ли резонит"}},{q="Кто изучает эти кристаллы?",a="Мор'рогал, таурен из Приюта у Солнечного Камня в Когтистых горах, исследует кристаллы, чтобы понять внезапный всплеск активности кобольдов и найти способ противостоять тому злу, что было раскрыто.",al={"who wants resonite","mor'rogal crystals","sun rock retreat resonite","кому нужен резонит","мор'рогал кристаллы","резонит приют у солнечного камня"}},{q="Кто такие земельные, упоминаемые в связи с кристаллом?",a="The Earthen are creatures said to have been created by the Titans to shape the land. Their possible connection to Resonite is investigated during Mor'rogal's quest.",al={"what are earthen","earthen titan connection","кто такие земельные","земельные и титаны"}}},fp="16,193,17.587.1,17.518.1,34.159.0,45.182.0,44.176.0,31.214.0,60.164.0"}
P.entries["item:restabilization-cog"] = {n="Зубец рестабилизации",s="Зубцы рестабилизации — точные механические детали, добываемые у лепрогномов, бродящих у облученных руин Гномрегана. В Караносе гномы-изобретатели нуждаются в этих целых деталях, чтобы построить Рекомбобулятор — дерзкую машину, призванную обратить мутацию прокаженных.",h="Зубцы рестабилизации — точные механические детали, добываемые у лепрогномов, бродящих у облученных руин...",kw={"dun morogh","gibblewilt","gnomeregan","kharanos","leper gnome","operation recombobulation","razzle sprysprocket","restabilization cog","дун морог","гиббвилт","гномреган","каранос","лепрогном","операция рекомбобуляция","раззл шустрец","зубец рестабилизации"},ang={["profession:Engineering"]="Точные допуски зубцов рестабилизации отражают классический гномский подход: они рассчитаны на опасное трение и баланс хрупких механических узлов вроде Рекомбобулятора.",["race:Gnome"]="Для изгнанных гномов Дун Морога добыча этих деталей — мрачный долг: они снимают механизмы с павших собратьев в отчаянной надежде создать лекарство для павших жителей Гномрегана."},sec={{t="Детали для лекарства",b="Когда радиация затопила Гномреган в катастрофической попытке уничтожить вторгшихся троггов, бесчисленные гномы превратились в больных, враждебных лепрогномов. Несмотря на безумие, эти изгнанники все еще носят сложные гномские механизмы и пригодные детали. Изобретатели Оззи Триггервольт и Раззл Шустрец считают, что ужасное превращение можно последовательно обратить. Чтобы завершить прототип устройства рекомбобуляции, они рассчитывают на искателей приключений, которые добудут важные детали прямо у пораженных за воротами Гномрегана, в том числе целые зубцы рестабилизации для баланса внутренних систем сгорания машины."}},faq={{q="Для чего нужен зубец рестабилизации?",a="Зубцы рестабилизации нужны изобретателю Раззлу Шустрецу в Караносе. Вместе с гиромеханическими шестеренками они служат важнейшими конструктивными элементами Рекомбобулятора — экспериментального изобретения для излечения облученных лепрогномов.",al={"cog purpose","what does restabilization cog do","why collect cogs","назначение зубца","что делает зубец рестабилизации","зачем собирать зубцы"}},{q="Где можно найти эти зубцы?",a="Их носят обезумевшие лепрогномы и их безумный предводитель Гиббвилт, бродящие у внешних ворот и траншей Гномрегана в западном Дун Мороге.",al={"restabilization cog location","who drops cogs","where to farm cogs","где найти зубец рестабилизации","с кого падают зубцы","где фармить зубцы"}},{q="Действительно ли Рекомбобулятор может излечить лепрогномов?",a="Раззл Шустрец и Оззи Триггервольт уверены, что правильно настроенный механизм способен обратить мутацию. Однако гномская инженерия славится своей нестабильностью, и сможет ли Рекомбобулятор действительно вернуть разум и тело их народу, пока неизвестно: это непроверенная затея.",al={"does recombobulator work","is there a cure for leper gnomes","работает ли рекомбобулятор","есть ли лекарство для лепрогномов"}}},fp="19,289,21.623.0,39.247.0,30.166.0,54.289.0"}
P.entries["item:ring-of-zoram"] = {n="Кольцо Зорама",s="Кольцо Зорама — древняя реликвия кальдораев, восходящая к славным дням затонувшего города Зорам до Великого Раскола. Оно было создано как мастер-ключ ко всем замкам и хранилищам затонувшего города, а недавно попало в руки наступающих на побережье нага.",h="Кольцо Зорама — древняя реликвия кальдораев, восходящая к славным дням затонувшего города Зорам до Великого...",kw={"ancient statuette","ashenvale","lady vespia","ring of zoram","ruuzel","talen","zoram strand","древняя статуэтка","ясеневый лес","леди веспия","кольцо зорама","руузель","тален","зорамское взморье"},ang={["faction:Alliance"]="Возвращение кольца у нага помогает ученому-ночному эльфу Талену вернуть похищенную историю кальдораев на спорных границах Ясеневого леса.",["race:NightElf"]="Кольцо — осязаемая часть наследия времен до Раскола, эпохи, когда империя кальдораи еще не была разорвана чародейской гордыней и поглощающими морями."},sec={{t="Мастер-ключ затонувшего города",b="До того как Источник Вечности рухнул, а океаны поглотили западные земли Калимдора, Зорам был прибрежной жемчужиной империи ночных эльфов. Кольцо Зорама носили правители города, и оно обладало особыми свойствами: по легенде, оно служило универсальным ключом к любому сложному замку и хранилищу, созданному в пределах Зорама. Когда Великий Раскол десять тысяч лет назад разбил континент, кольцо затонуло вместе с городом и пропало под бушующими волнами в месте, которое теперь называется Зорамским взморьем."},{t="Reclamation by the Naga",b="Тысячелетиями кольцо лежало под илом и руинами, пока нага не начали прочесывать побережье Ясеневого леса. Руузель, предводительница нага, обитающая на островке у северного берега, нашла артефакт среди затонувших обломков. Ученые, такие как ночной эльф Тален, ищут кольцо не только из-за его древности, но и потому, что оно — единственный ключ, способный открыть другие реликвии, поднятые со дна, в том числе запечатанные древние статуэтки, найденные на морском дне."}},faq={{q="Для чего нужно Кольцо Зорама?",a="Исторически кольцо принадлежало правителям Зорама и служило зачарованным мастер-ключом, способным открыть любой замок в городе. В наши дни Тален ищет его, чтобы открыть запертую древнюю статуэтку, найденную в затонувших руинах.",al={"ring of zoram purpose","what does the ring do","ring of zoram lore","назначение кольца зорама","что делает кольцо","кольцо зорама предания"}},{q="У кого находится Кольцо Зорама?",a="Кольцо было поднято из руин прибрежными нагами, вторгшимися на Зорамское взморье. Оно хранится в основном у их предводительницы Руузель на острове у северного берега, хотя известно, что его носила и другая видная нага по имени леди Веспия.",al={"who has the ring","ring of zoram drop","where to get ring of zoram","у кого кольцо","кольцо зорама добыча","где взять кольцо зорама"}},{q="Зачем Талену нужно кольцо?",a="Тален хочет раскрыть тайны древней статуэтки, найденной на Зорамском взморье. Без Кольца Зорама, служащего ей ключом, древний механизм статуэтки открыть нельзя.",al={"why talen wants ring","talen ring quest","зачем талену кольцо","задание талена кольцо"}},{q="Куда исчез город Зорам?",a="Зорам был древним городом ночных эльфов на западной окраине Калимдора до Великого Раскола десять тысяч лет назад. Когда Источник Вечности обрушился внутрь себя, город был разрушен и ушел под воду, оставив после себя лишь Зорамское взморье.",al={"what happened to zoram","city of zoram lore","что случилось с зорамом","город зорам предания"}}},fp="13,278,29.517.0,23.481.0,35.256.0,32.242.0,29.189.0,31.264.0"}
P.entries["item:robo-mechanical-guts"] = {n="Механические внутренности робота",s="Механические внутренности робота — это пригодные для повторного использования шестерни, проводники и механизмы, добытые из неисправных механизмов, бродящих по руинам Гномрегана. Гномьи инженеры в Штормграде нуждаются именно в этих деталях для ремонта тяжелых туннельных машин, которые помогут отвоевать Гномреган в Дун Мороге.",h="Механические внутренности робота — это пригодные для повторного использования шестерни, проводники и...",kw={"clockwork","dun morogh","gnomeregan","gyrodrillmatic excavationators","robo-mechanical guts","shoni","stormwind","заводной механизм","дун морог","гномреган","гиробуровые землекопы","механические внутренности робота","шони","штормград"},ang={["profession:Engineering"]="Каждый добытый клубок проводов и гиро-шестерня напоминает о вершине гномьего конструирования автоматов, ныне трагически одичавшего из-за радиации и одиночества.",["race:Gnome"]="Разбирать взбесившихся заводных часовых вашего утраченного дома горько, но их внутренние механизмы дают те самые детали, что нужны, чтобы вернуть Гномреган."},sec={{t="Детали для флота",b="Когда главный механик Гелбин Меггакрут и уцелевшие гномы покидали Гномреган, внутри остались тысячи автоматических механизмов, заводных часовых и промышленных роботов. После радиоактивной катастрофы эти машины продолжают самостоятельно бродить по коридорам города. В Штормграде механик Шони хочет собрать флот гиробуровых землекопов, чтобы прорвать оборону Гномрегана и вернуть потерянный город. Не имея свежего сырья, она поручает отважным искателям приключений пробраться по зараженным залам Гномрегана и добыть рабочие внутренности роботов — пружины, провода и гироэлементы — для переоснащения землеройных машин."}},faq={{q="Для чего нужны механические внутренности робота?",a="Их собирает Шони в Штормграде, чтобы починить флот гиробуровых землекопов — специальных туннельных машин, предназначенных для поддержки операции по возвращению Гномрегана в Дун Мороге.",al={"what are robot guts for","robo-mechanical guts use","why collect mechanical guts","для чего внутренности роботов","механические внутренности робота применение","зачем собирать механические внутренности"}},{q="Где найти эти детали?",a="Их можно добыть из различных враждебных заводных автоматов, механизмов и зараженных существ, бродящих как на окраинах, так и в глубинах Гномрегана.",al={"where to get robo mechanical guts","robot guts drop location","gnomeregan robot parts","где взять механические внутренности робота","внутренности роботов где добыть","гномреган детали роботов"}},{q="Кто такая Шони и зачем ей так много деталей?",a="Шони — честолюбивый гномий инженер, работающий в Квартале Дворфов Штормграда. Ей поручено подготовить целую дивизию подземных землеройных машин — почти четыреста штук, — чтобы прорваться в захваченные руины Гномрегана.",al={"who is shoni","shoni stormwind","gyrodrillmatic excavationator fleet","кто такая шони","шони штормград","флот гиробуровых землекопов"}}},fp="20,315,21.658.0,39.198.0,35.160.0,49.245.0"}
P.entries["item:rocket-car-parts"] = {n="Детали болида",s="Обломки болидов — это разбросанные искореженные металлические остатки скоростных аварий на Мерцающей равнине в Тысяче Игл. Безрассудные гномы и гоблины-гонщики постоянно разбивают экспериментальные болиды, а оппортунисты собирают обломки, чтобы превратить аварии на трассе в быструю наживу.",h="Обломки болидов — это разбросанные искореженные металлические остатки скоростных аварий на Мерцающей равнине...",kw={"engineering","gnome","goblin","kravel koalbeard","mirage raceway","rocket car parts","salvage","shimmering flats","thousand needles","инженерное дело","гном","гоблин","крейвел углебрад","виражи на миражах","утиль","мерцающая равнина","тысяча игл"},ang={["profession:Engineering"]="Россыпь сгоревших шестерен и искореженных выхлопных узлов на соляной равнине свидетельствует о хаотичных крайностях инженерной философии гномов и гоблинов.",["race:Dwarf"]="Пока гномов и гоблинов волнует лишь сама гонка, предприимчивые дворфы вроде Крейвела Углебрада доказывают, что настоящая прибыль — в сборе обломков, остающихся после нее."},sec={{t="Скорость, аварии и выгодная торговля",b="Виражи на Миражах на Мерцающей равнине — место нескончаемого, взрывоопасного соперничества гоблинской и гномьей инженерии. В погоне за непревзойденной скоростью гонщики регулярно страдают от катастрофических поломок, взрывных осечек и аварий на огромной скорости, разбрасывающих металл по соляной равнине. Эти брошенные остатки — от погнутых цилиндров и сгоревших шестерен до смятых листов металла — долго не лежат. Старатели и торговцы, прежде всего предприимчивый дворф Крейвел Углебрад, нанимают проходящих искателей приключений, чтобы те прочесывали слепяще-белые просторы и собирали обломки. Поскольку обеим командам вечно нужны запчасти для сборки следующего прототипа, подобранные обломки легко перепродать тем же командам, которые их разбили."}},faq={{q="Откуда берется столько обломков болидов?",a="Это последствия постоянных аварий, взрывов и поломок на Виражах на Миражах. Гномы и гоблины-пилоты регулярно доводят нестабильные экспериментальные ракетные машины до разрушения на огромных соляных равнинах Тысячи Игл.",al={"why are there parts on the salt flats","rocket car scrap origin","where do the parts come from","почему детали на соляной равнине","откуда обломки болидов","откуда берутся детали"}},{q="Кто покупает эти обломки?",a="Торговцы вроде дворфа Крейвела Углебрада собирают обломки у странников и перепродают шестерни, обшивку и устройства гномам и гоблинам, которым всегда нужны запчасти для ремонта и улучшения гоночных машин.",al={"who wants rocket car parts","kravel koalbeard rocket parts","who buys the wreckage","кому нужны обломки болидов","крейвел углебрад обломки","кто покупает обломки"}},{q="Опасно ли собирать эти детали?",a="Сами обломки безвредны, хотя порой несут мрачные следы жестоких аварий, например оторванные конечности, зажатые в металле. Главная опасность исходит от враждебных обитателей соляной равнины: василисков, обожженных скорпидов и хищных соляных стервятников, кружащих над полями обломков.",al={"is it safe to pick up parts","threats while gathering parts","безопасно ли собирать детали","опасности при сборе деталей"}},{q="Заботит ли гномов и гоблинов, что детали взяты с разбитых машин?",a="Ничуть. Ни гномы, ни гоблины-соперники не брезгуют переработанными материалами. Их единственная цель — достать рабочие устройства, шестерни и металлическую обшивку, чтобы собрать машину быстрее и обогнать друг друга на трассе.",al={"do racers care about wreckage","why do goblins reuse junk","заботят ли гонщиков обломки","почему гоблины используют хлам"}}},fp="16,342,34.812.0,46.251.0,31.246.0,36.309.0,68.237.0"}
P.entries["item:rod-of-channeling"] = {n="Жезл направления",s="Жезл направления — магический фокус, который носят заклинатели клана Драконьей Пасти в Болотине. Чернокнижники, желающие овладеть призывом охотника Скверны, должны собрать несколько таких жезлов для помощников Страхада Фарсана, чтобы надежно закрепить ритуальный круг в Кабестане.",h="Жезл направления — магический фокус, который носят заклинатели клана Драконьей Пасти в Болотине.",kw={"angerfang encampment","bonewarder","dragonmaw","felhunter","rod of channeling","shadowwarder","strahad farsan","tome of the cabal","лагерь злого клыка","костяной страж","драконья пасть","охотник скверны","жезл направления","теневой страж","страхад фарсан","фолиант заговора"},ang={["class:Warlock"]="Добыча трех Жезлов направления — важный этап испытаний Фолианта заговора: они обеспечивают удержание, необходимое, чтобы подчинить вашего первого охотника Скверны."},sec={{t="Орудия связывания",b="Когда чернокнижник стремится подчинить такого неукротимого хищника, как охотник Скверны, одной силы воли редко бывает достаточно. Страхад Фарсан требует три одинаковых жезла, чтобы его помощники могли направлять магию согласованно, удерживая круг призыва, пока заклинатель проводит связывание. Темные заклинатели клана Драконьей Пасти, в том числе костяные стражи и теневые стражи, обитающие в Лагере Злого Клыка и окрестных руинах Болотины, носят эти предметы для собственных злых ритуалов. Хотя жезлы обычно потерты и покрыты зарубками от боев, они остаются мощными фокусами, способными направлять хаотическую энергию Пустоты."}},faq={{q="Для чего нужен Жезл направления?",a="Жезлы передают чернокнижнику Страхаду Фарсану над Кабестаном. Его помощники используют их, чтобы направлять и стабилизировать магический круг, необходимый для призыва и подчинения враждебного охотника Скверны.",al={"what is rod of channeling","rod of channeling purpose","why do i need rod of channeling","что такое жезл направления","жезл направления назначение","зачем нужен жезл направления"}},{q="Где можно найти Жезлы направления?",a="Они есть у заклинателей клана Драконьей Пасти — в частности, у костяных стражей и теневых стражей Драконьей Пасти — в Болотине, особенно вокруг Лагеря Злого Клыка.",al={"where to get rods of channeling","who drops rod of channeling","rod of channeling location","где взять жезлы направления","с кого падает жезл направления","жезл направления где найти"}},{q="Почему Страхаду нужны три жезла?",a="Страхад привлекает нескольких помощников для ритуала призыва охотника Скверны. Каждому помощнику нужен отдельный фокус, чтобы надежно поддерживать канал, пока чернокнижник усмиряет зверя.",al={"why three rods","why 3 rods of channeling","почему три жезла","зачем 3 жезла направления"}},{q="Почему Драконья Пасть использует эти жезлы?",a="Клан Драконьей Пасти практикует темное шаманство и остатки теневого колдовства Старой Орды. Его костяные стражи и теневые стражи используют жезлы для направления проклятий, некромантии и магии Тьмы в непрекращающихся войнах за территорию в Болотине.",al={"dragonmaw rods","why do dragonmaw have them","жезлы драконьей пасти","почему они у драконьей пасти"}}},fp="17,268,22.603.0,39.175.0,38.165.0,33.188.0,39.236.0"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Медальоны Рольфа и Малакаи",s="Медальоны Рольфа и Малакаи — служебные знаки двух стражников Штормграда, пропавших во время патруля в восточной части Элвиннского леса. Эти предметы с королевской символикой разыскивает Стражник Томас, чтобы узнать судьбу своих пропавших товарищей.",h="Медальоны Рольфа и Малакаи — служебные знаки двух стражников Штормграда, пропавших во время патруля в...",kw={"eastvale","elwynn","guard thomas","malakai","medallions","murloc","rolf","stormwind guard","восточная долина","элвиннский лес","стражник томас","малакай","медальоны","мурлок","рольф","стражник штормграда"},ang={["faction:Alliance"]="Медальоны — суровое напоминание о том, что даже в сердце Альянса местные стражники подвергаются смертельной опасности, охраняя сельские торговые пути.",["race:Human"]="Для людей Элвиннского леса эти знаки — память о погибших сыновьях и защитниках, чья смерть показывает уязвимость королевства, пока армия занята в других местах."},sec={{t="Мрачное подтверждение",b="Когда стражники Рольф и Малакай пропали на берегах реки в восточной части Элвиннского леса, их начальник, Стражник Томас, заподозрил худшее. Найденные личные медальоны стражников — неопровержимое доказательство их гибели от рук наступающих мурлоков. Для гарнизона Штормграда эти знаки — не просто безделушки: они напоминают о павших солдатах, державших рубежи против растущих угроз дикой природы, когда армия королевства была крайне ограничена в силах."},{t="Знаки службы",b="Как и многие члены городской стражи Штормграда и сельских патрулей, стражники-люди носят опознавательные медальоны, означающие их верность и полномочия от имени короны. Вернув эти предметы Стражнику Томасу, вы позволите ему официально учесть пропавших людей, записать их жертву в полевой отчет и поднять тревогу из-за агрессивных племен мурлоков, селящихся возле торговых дорог."}},faq={{q="Что такое Медальоны Рольфа и Малакаи?",a="Это официальные служебные опознавательные знаки стражников Рольфа и Малакаи, двух стражников Штормграда, служивших в восточной части Элвиннского леса и убитых мурлоками из засады.",al={"what are the medallions","rolfs medallion","malakais medallion","что за медальоны","медальон рольфа","медальон малакаи"}},{q="Кому принадлежат эти медальоны?",a="Они принадлежали стражникам Рольфу и Малакаи, товарищам, служившим под началом Стражника Томаса и охранявшим реку и дороги между Златоземьем и Лесопилкой Восточной долины.",al={"who were rolf and malakai","whose medallions","кто такие рольф и малакай","чьи медальоны"}},{q="Кому следует отнести эти медальоны?",a="Отнесите их Стражнику Томасу, который несет дозор у восточного моста на дороге между Златоземьем и Лесопилкой Восточной долины.",al={"who wants the medallions","where do i turn these in","medallion turn in","кому нужны медальоны","куда сдать медальоны","сдать медальоны"}},{q="Почему эти медальоны важны для Стражника Томаса?",a="Стражник Томас отправил обоих стражников в патруль и опасался, что их постигла дурная участь. Получив медальоны, он убеждается в их гибели, может задокументировать их жертву и предупредить Штормград о растущей угрозе мурлоков.",al={"why does thomas want them","guard thomas reaction","почему томас хочет медальоны","реакция стражника томаса"}}},fp="29,250,19.485.0,17.383.0,39.184.1,34.170.0,39.134.0,51.214.1"}
P.entries["item:rot-blossom"] = {n="Цветок гнили",s="Цветок гнили — отвратительное некротическое растение, растущее среди оскверненных могил Сумеречного леса. Питаясь отравленной почвой и останками нежити, эти цветы ценятся за мощные, нездоровые алхимические свойства.",h="Цветок гнили — отвратительное некротическое растение, растущее среди оскверненных могил Сумеречного леса.",kw={"althea ebonlocke","darkshire","duskwood","rot blossom","skeletal fiend","skeletal horror","tranquil gardens cemetery","zombie juice","алтея чернодрев","темнолесье","сумеречный лес","цветок гнили","скелет-изверг","скелет-ужас","безмятежное кладбище","сок зомби"},ang={["faction:Alliance"]="Поход в проклятую землю за этими мрачными цветами заодно служит помощью Ночному Дозору: он помогает держать границы Темнолесья свободными от голодных скелетов.",["profession:Herbalism"]="В отличие от обычных трав, взращенных светом и дождем, цветки гнили — отвратительные ботанические аномалии, питающиеся лишь некротической гнилью и кладбищенской землей, и мрачный предмет изучения порченой флоры."},sec={{t="Растение склепов",b="Неестественная порча Сумеречного леса порождает причудливые и жуткие растения, и среди них нет более тревожного, чем цветок гнили. Эти мрачные цветы укореняются в оскверненной земле кладбищ, таких как Безмятежное кладбище, и процветают рядом со смертью. По местным слухам, они могут даже прорастать в треснувших черепах ходячих мертвецов, особенно Скелетов-ужасов и Скелетов-извергов, бродящих среди курганов. Для жителей Темнолесья сбор этих цветов — и мрачная повинность, и опасная необходимость, ведь потревожить их почву значит столкнуться с неупокоенными мертвецами."},{t="Жуткий ингредиент",b="Несмотря на отвратительный вид, цветки гнили служат особой цели в местных зельях. Эти цветы содержат темные эссенции, необходимые для приготовления сока зомби — мерзкого напитка, связанного с мрачными попытками выжить в Сумеречном лесу. Те, кого посылают за цветами, нередко невольно помогают Ночному Дозору, истребляя беспокойных скелетов, бродящих по зловещим местам захоронений."}},faq={{q="Где можно найти цветок гнили?",a="Цветок гнили растет в оскверненной почве мест захоронений Сумеречного леса, особенно на Безмятежном кладбище, и, как известно, прорастает из останков скелетов-извергов.",al={"where do rot blossoms grow","rot blossom location","find rot blossoms","где растет цветок гнили","цветок гнили где найти","найти цветок гнили"}},{q="Для чего нужен цветок гнили?",a="Это ключевой ингредиент, который местные пивовары и алхимики используют для получения мощной мерзкой смеси — сока зомби.",al={"rot blossom use","why gather rot blossoms","what makes rot blossoms useful","применение цветка гнили","зачем собирать цветок гнили","чем полезен цветок гнили"}},{q="Почему эти цветы растут в скелетах?",a="Затянувшаяся темная магия Сумеречного леса заражает и землю, и неупокоенных мертвецов. Цветки гнили питаются некротической порчей и разложением, поэтому прорастают в черепах и грудных клетках бродячих скелетов.",al={"rot blossoms in skulls","skeletal horror flower","skeletons rot blossom","цветок гнили в черепах","цветок скелет-ужас","скелеты цветок гнили"}},{q="Как сбор цветков гнили помогает Темнолесью?",a="Всякий, кто отправляется в такие места, как Безмятежное кладбище, за цветами, неизбежно уничтожает Скелетов-ужасов и Скелетов-извергов, досаждающих этим землям, и тем самым приносит столь необходимое облегчение Алтее Чернодрев и осажденному Ночному Дозору.",al={"althea ebonlocke rot blossom","night watch rot blossom","helping darkshire","алтея чернодрев цветок гнили","ночной дозор цветок гнили","помощь темнолесью"}}},fp="11,212,19.561.0,21.398.0,32.201.0,31.119.0,40.215.0,47.242.0"}
P.entries["item:rot-hide-ichor"] = {n="Лимфа Гнилошкуров",s="Лимфа Гнилошкуров — отвратительная телесная жидкость, добываемая у нежити-гноллов Гнилошкуров, заполонивших Остров Фенриса на озере Лордамер. Аптекарь Ренферрел собирает образцы этого вещества в Гробнице, чтобы выяснить источник порчи гноллов и разработать план борьбы с ними.",h="Лимфа Гнилошкуров — отвратительная телесная жидкость, добываемая у нежити-гноллов Гнилошкуров, заполонивших...",kw={"apothecary renferrel","fenris isle","lordamere lake","rot hide gnolls","rot hide ichor","sepulcher","silverpine forest","аптекарь ренферрел","остров фенриса","озеро лордамер","гноллы гнилошкуры","лимфа гнилошкуров","гробница","серебряный бор"},ang={["race:Undead"]="Для Отрекшихся изучение лимфы — жизненно важная военная разведка, чтобы защитить восточный фланг Серебряного бора и упрочить превосходство Королевского фармацевтического общества в науке о чуме."},sec={{t="Чума в крови",b="Гноллы Гнилошкуры с Острова Фенриса — не обычные дикие звери: они заметно разложились и искажены неестественной порчей. Вместо обычной крови по их жилам течет едкая лимфа, поддерживающая их оживленную плоть. Королевское фармацевтическое общество подозревает, что эта жидкость хранит тайну порчи стаи и имя того, кто управляет ею из разрушенной крепости на Острове Фенриса."},{t="Исследования аптекарей",b="Аптекарь Ренферрел собирает флаконы с этой лимфой, чтобы изучить ее свойства в Гробнице. Выделив химические и магические компоненты, питающие гноллов, Отрекшиеся надеются найти уязвимые места, прежде чем бросать войска в полномасштабный штурм через озеро Лордамер."}},faq={{q="Откуда берется лимфа Гнилошкуров?",a="Ее добывают из тел гноллов Гнилошкуров, обитающих на Острове Фенриса, который находится на озере Лордамер к востоку от материковой части Серебряного бора.",al={"where to get rot hide ichor","how to find rot hide ichor","gnoll ichor location","где взять лимфу гнилошкуров","как найти лимфу гнилошкуров","лимфа гноллов где"}},{q="Зачем аптекарю Ренферрелу эта лимфа?",a="Ренферрел хочет исследовать странную жидкость, чтобы выяснить, что исказило гноллов, и найти их физические или алхимические слабости, которыми Отрекшиеся смогут воспользоваться перед нападением на остров.",al={"why does renferrel need ichor","renferrel quest reason","purpose of rot hide ichor","зачем ренферрелу лимфа","причина задания ренферрела","для чего лимфа гнилошкуров"}},{q="Гноллы Гнилошкуры — это Плеть?",a="Это гноллы-нежить, искаженные чумой, но Отрекшиеся активно выясняют, кто или что их создало и повелевает их присутствием на Острове Фенриса.",al={"are rot hides scourge","who controls rot hides","what are rot hide gnolls","гнилошкуры плеть","кто управляет гнилошкурами","кто такие гноллы гнилошкуры"}},{q="Есть ли эта лимфа у всех гноллов?",a="Нет. Эта жидкость свойственна только стае Гнилошкуров, чья плоть и кровь были испорчены мерзкой некромантической заразой.",al={"do all gnolls drop ichor","normal gnoll blood","у всех ли гноллов лимфа","кровь обычных гноллов"}}},fp="14,276,21.387.0,19.279.0,36.146.0,46.187.0,32.161.0,30.116.0"}
P.entries["item:rough-quartz"] = {n="Грубый кварц",s="Грубый кварц — скромный камень стихий, который начинающим шаманам дарует Низшее воплощение земли. Хотя он мал и неочищен, он служит жизненно важным духовным ядром для создания первого Тотема земли шамана.",h="Грубый кварц — скромный камень стихий, который начинающим шаманам дарует Низшее воплощение земли.",kw={"call of earth","canaga earthcaller","earth totem","minor manifestation of earth","rough quartz","valley of trials","зов земли","канага заклинатель земли","тотем земли","низшее воплощение земли","грубый кварц","долина испытаний"},ang={["class:Shaman"]="Грубый кварц олицетворяет ваше первое общение со стихией земли: он закрепляет ваши заклинания и отмечает ваш путь истинного проводника духов."},sec={{t="Сердце Тотема земли",b="Неискушенному глазу грубый кварц кажется обычной пустынной галькой. Но для шамана, общающегося с духами в Дуротаре или Мулгоре, это дар стихий, предлагаемый непосредственно Низшим воплощением земли. Камень олицетворяет стойкость, терпение и непоколебимую силу. Когда его приносят старейшине, например Канаге заклинателю земли в Долине Испытаний, кварц вставляют в резное дерево Тотема земли, и он становится духовным средоточием, связывающим начинающего шамана с живой землей Азерота."}},faq={{q="Для чего нужен грубый кварц?",a="Он служит доказательством того, что начинающий шаман общался с духом стихии земли. Старейшина-шаман использует этот камешек как духовное ядро при вырезании самого первого Тотема земли посвященного.",al={"what does rough quartz do","rough quartz use","why do i need rough quartz","для чего грубый кварц","применение грубого кварца","зачем нужен грубый кварц"}},{q="Кто дает вам грубый кварц?",a="Его дарует Низшее воплощение земли после того, как вы пообщаетесь с духом во время ритуала Зов Земли в Дуротаре или Мулгоре.",al={"where do i get rough quartz","who drops rough quartz","где взять грубый кварц","с кого падает грубый кварц"}},{q="Кому в Дуротаре нести этот камень?",a="Отнесите его Канаге заклинателю земли, наставнику шаманов, живущему в Долине Испытаний: он изготовит из него ваш Тотем земли.",al={"where to turn in rough quartz","rough quartz turn in","who takes rough quartz","кому сдать грубый кварц","сдать грубый кварц","кто берет грубый кварц"}},{q="Используется ли этот кварц для чего-то еще?",a="Нет. Это исключительно священный ритуальный предмет, предназначенный лишь для создания Тотема земли, и в обычной торговле он не применяется.",al={"can i sell rough quartz","is rough quartz used in crafting","можно ли продать грубый кварц","используется ли грубый кварц в ремесле"}}},fp="12,211,24.543.0,40.192.0,31.136.0,40.127.0,38.114.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Боеприпасы Громострела",s="Боеприпасы Громострела — потерянный ящик с боеприпасами, предназначавшийся оружейнику Хегнару Громострелу в Дун Мороге. Напуганный курьер бежал от голодных вендиго и потерял его, и тяжелый ящик лежит брошенный в снегу возле Серой берлоги.",h="Боеприпасы Громострела — потерянный ящик с боеприпасами, предназначавшийся оружейнику Хегнару Громострелу в...",kw={"ammo","crate","dun morogh","grizzled den","hegnar","loslor","rumbleshot","wendigo","боеприпасы","ящик","дун морог","серая берлога","хегнар","лослор","громострел","вендиго"},ang={["class:Hunter"]="Для стрелков, бродящих по лютому холоду Дун Морога, сухой порох и запас пуль Хегнара обеспечивают постоянный приток боеприпасов для дворфийского огнестрельного оружия.",["profession:Engineering"]="Дворфийские инженеры и изобретатели сильно зависят от постоянного притока пуль и пороха для испытаний своего огнестрельного и экспериментального оружия."},sec={{t="Застрявшая поставка",b="Хегнар Громострел держит придорожную оружейную лавку на горной тропе, ведущей вниз от Туннеля Холодной долины к Старой Наковальне. Стрелки, горные пехотинцы и расчеты дворфийских минометов Стальгорна постоянно тренируются на заснеженных высотах, и его запасы тают почти так же быстро, как вспыхивает порох. Эту партию боеприпасов отправил Лослор из Караноса, но до прилавков она не добралась. Курьер, которому поручили доставку, разбил лагерь слишком близко к хищным вендиго Серой берлоги, запаниковал при нападении и бежал, спасая жизнь, оставив тяжелый ящик глубоко в охотничьих угодьях зверей."}},faq={{q="Кто такой Хегнар Громострел?",a="Хегнар Громострел — дворф-оружейник, который держит лавку у дороги к Старой Наковальне. Он обслуживает местных стрелков, охотников и военных стрелков, быстро расходующих боеприпасы на тренировках среди скал Дун Морога.",al={"rumbleshot","who is hegnar","gun vendor","громострел","кто такой хегнар","торговец оружием"}},{q="Как был потерян ящик с боеприпасами?",a="Курьер, посланный с ящиком, совершил ошибку и разбил лагерь у входа в Серую берлогу. Когда вендиго, охраняющие свою территорию, напали на его лагерь, перепуганный курьер убежал, оставив тяжелый ящик в снегу.",al={"why was ammo lost","what happened to the ammo","courier ammo","почему потеряны боеприпасы","что случилось с боеприпасами","курьер боеприпасы"}},{q="Где находится Серая берлога?",a="Серая берлога — система пещер в горах к юго-западу от Караноса. Это известное логово свирепых вендиго Дун Морога, из-за чего окрестные склоны опасны для одиноких путников.",al={"grizzled den location","where is wendigo cave","серая берлога где","где пещера вендиго"}}},fp="17,229,19.631.0,25.224.0,32.242.0,26.212.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Рунический пергамент",s="Письменное послание, которое вручают начинающим шаманам-оркам в Долине Испытаний. Его написал наставник Шикрик, а передает Горнек; оно призывает посвящаемых принять свою роль духовных вождей и проводников духов стихий.",h="Письменное послание, которое вручают начинающим шаманам-оркам в Долине Испытаний.",kw={"durotar","gornek","parchment","rune-inscribed parchment","shaman","shikrik","valley of trials","дуротар","горнек","пергамент","рунический пергамент","шаман","шикрик","долина испытаний"},ang={["class:Shaman"]="Эта записка с рунами отмечает ваш самый первый шаг на пути стихий: она отдает вас под опеку Шикрика, чтобы вы изучили почитание предков и власть над стихиями.",["race:Orc"]="Возрождение шаманских традиций — основа новой Орды, и этот пергамент олицетворяет продолжение мудрости предков в Дуротаре."},sec={{t="Призыв к духам",b="В залитом солнцем каньоне Долины Испытаний новые шаманы-орки начинают обучение под бдительным взором опытных надзирателей. Пока посвящаемый выполняет первые испытания для Горнека, ему вручают этот покрытый рунами документ. Пергамент, присланный непосредственно Шикриком, местным наставником шаманов, служит официальным призывом к глубинным тайнам общения со стихиями. В культуре орков шаман — не просто боевой заклинатель, а необходимый посредник между живыми и предками. Это краткое предписание знаменует переход от простой грубой силы к дисциплинированному пути почитания предков."}},faq={{q="Что такое рунический пергамент?",a="Это рукописное послание, которое Горнек в Долине Испытаний вручает начинающим шаманам-оркам. В нем читателю предписывается явиться к наставнику шаманов Шикрику, чтобы начать формальное обучение.",al={"rune parchment","what is this item","shaman parchment","рунический пергамент","что за предмет","пергамент шамана"}},{q="Кто написал пергамент?",a="Пергамент написал Шикрик, наставник шаманов в Долине Испытаний, желавший обучить юных посвященных путям стихий и духов предков.",al={"who sent the parchment","parchment author","кто прислал пергамент","автор пергамента"}},{q="Почему шаманов считают избранными среди орков?",a="Шаманы-орки служат духовными проводниками и посредниками предков, прислушиваясь к духам стихий, чтобы вести свой народ. Шикрик напоминает ученикам, что их долг включает и исцеление союзников, и обрушивание яростного гнева стихий на врагов.",al={"why be a shaman","orc shaman role","зачем быть шаманом","роль шамана орка"}}},fp="24,234,24.631.0,37.182.0,24.181.0,49.263.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Исписанная рунами подвеска",s="Исписанная рунами подвеска — магический талисман, найденный в поставках из Даларана, предназначенных для Янтарной мельницы. Кирин-Тор высоко ценит такие подвески: они служат проводниками мощной тайной энергии.",h="Исписанная рунами подвеска — магический талисман, найденный в поставках из Даларана, предназначенных для...",kw={"allister","ambermill","dalar dawnweaver","dalaran","kirin tor","pendant","rune-inscribed pendant","sepulcher","алистер","янтарная мельница","далар ткач рассвета","даларан","кирин-тор","подвеска","исписанная рунами подвеска","гробница"},ang={["class:Mage"]="Маги без труда узнают работу Кирин-Тора: руны на подвеске призваны стабилизировать неустойчивые потоки при проведении заклинаний высшего порядка.",["race:Undead"]="Для Отрекшихся, охраняющих Серебряный бор, перехваченные фокусы Даларана, как эта подвеска, дают важные сведения о сборе сил сопротивления людей за стенами Янтарной мельницы."},sec={{t="Реликвия Кирин-Тора",b="Эта подвеска с затейливыми тайными письменами найдена среди ящиков с картографическими припасами, направлявшихся в анклав Даларана на Янтарной мельнице. Высокопоставленные маги Кирин-Тора часто используют такие предметы, чтобы сфокусировать и усилить свои заклинания. Множество подвесок-проводников, поступающих в этот край, сразу вызывает подозрения у Отрекшихся из Гробницы: это знак грядущего проекта огромной магической мощи."},{t="Намек на планы Янтарной мельницы",b="Когда подвеску приносят в Гробницу, жрец Тени Алистер понимает, какую угрозу представляет укрепленная позиция магов Даларана, но передает реликвию Далару Ткачу Рассвета для более глубокого изучения. Ткач Рассвета определяет, что подвеска — ключевая часть замыслов магов, и делает вывод, что Кирин-Тор накапливает тайные проводники силы для крупных оборонительных или наступательных чар, скрытых за границами Янтарной мельницы."}},faq={{q="Для чего нужна Исписанная рунами подвеска?",a="Маги Кирин-Тора используют подвеску, чтобы направлять мощные потоки магической энергии. Она служит тайным фокусом для сложных чар, а не простым украшением.",al={"what does the pendant do","pendant purpose","rune pendant use","что делает подвеска","назначение подвески","для чего подвеска с рунами"}},{q="Откуда взялась эта подвеска?",a="Ее перехватили из поставок, направлявшихся на Янтарную мельницу в Серебряном бору, где остатки Кирин-Тора сильно укрепились.",al={"where do i find the pendant","pendant origin","where was it found","где найти подвеску","происхождение подвески","где ее нашли"}},{q="Кто изучает подвеску в Гробнице?",a="Жрец Тени Алистер бегло осматривает ее вместе с захваченными картами, а затем отправляет Далару Ткачу Рассвета, знатоку тайной магии в Гробнице, который узнает работу Кирин-Тора.",al={"who studies the pendant","who wants the pendant","dalar pendant","кто изучает подвеску","кому нужна подвеска","далар подвеска"}},{q="Почему Отрекшихся это тревожит?",a="Поставки большого числа подвесок-проводников говорят о том, что Кирин-Тор на Янтарной мельнице готовит крупное магическое предприятие, угрожающее власти Отрекшихся в Серебряном бору.",al={"why do forsaken care","ambermill threat","why is the pendant dangerous","почему отрекшиеся беспокоятся","угроза янтарной мельницы","чем опасна подвеска"}}},fp="22,208,15.444.0,27.417.1,44.182.0,33.141.0,42.180.0,40.188.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Руническая табличка",s="Руническая табличка — каменное послание, которое вручают юным шаманам-тролльям из племени Черного Копья в Долине Испытаний. Ее передает Горнек, направляя многообещающих мистиков к началу обучения общению со стихиями под руководством орка-наставника Шикрика.",h="Руническая табличка — каменное послание, которое вручают юным шаманам-тролльям из племени Черного Копья в...",kw={"darkspear","durotar","gornek","rune-inscribed tablet","shaman","shikrik","trainer","valley of trials","черное копье","дуротар","горнек","руническая табличка","шаман","шикрик","наставник","долина испытаний"},ang={["class:Shaman"]="Табличка — первый официальный шаг шамана к овладению стихиями земли, огня, воды и воздуха; она напоминает ученикам, что их сила течет от духов предков.",["race:Troll"]="Для троллей Черного Копья ответ на призыв орка-наставника подчеркивает растущую связь и общий духовный путь троллей и их новых союзников по Орде."},sec={{t="Призыв к духам",b="Эта табличка с рунами стихий служит официальным приглашением для начинающих шаманов-троллей, делающих первые шаги в Дуротаре. Когда новичок проявляет себя в Долине Испытаний, надзиратель Горнек вручает камень, присланный шаманом-троллем Ишь-йо, чтобы направить новичка к наставнику шаманов Шикрику. Для троллей Черного Копья, чьи духовные традиции глубоки и самобытны, табличка знаменует начало общего пути с орками, соединяющего древнее тролльское мистическое знание с возрожденным наследием шаманизма, которое отстаивает вождь Тралл."}},faq={{q="Для чего нужна Руническая табличка?",a="Табличка — вводное послание, которое Горнек передает юным шаманам-троллям в Долине Испытаний. Она предписывает новичку явиться к Шикрику, местному наставнику шаманов, чтобы начать формальное духовное обучение.",al={"tablet purpose","what does the tablet do","rune tablet use","назначение таблички","что делает табличка","руническая табличка"}},{q="Кто посылает табличку?",a="Табличка подписана Ишь-йо, шаманом-троллем, давшим новичку первые уроки. Она направляет его к Шикрику, орку-наставнику шаманов, стоящему у Логова в Долине Испытаний, который уже знает о его приходе.",al={"who wrote the tablet","tablet sender","who carved it","кто написал табличку","отправитель таблички","кто ее вырезал"}},{q="Кто получает эту табличку?",a="Эту табличку от Горнека как первое назначение класса в Дуротаре получают только недавно прибывшие шаманы-тролли из племени Черного Копья.",al={"who gets rune-inscribed tablet","which class gets the tablet","кто получает руническую табличку","какой класс получает табличку"}}},fp="21,253,24.578.0,43.234.0,21.237.0,25.126.0"}
P.entries["item:rune-of-nesting"] = {n="Руна Размещения",s="Руна Размещения — одна из четырех священных Реликвий Пробуждения, хранящихся в Обители Бен'этиль на Тельдрассиле. Она необходима для тонкого ритуала друидов, позволяющего безопасно вернуть спящих Друидов Когтя из Изумрудного Сна.",h="Руна Размещения — одна из четырех священных Реликвий Пробуждения, хранящихся в Обители Бен'этиль на...",kw={"athridas bearmantle","ban'ethil barrow den","chest of nesting","druids of the talon","emerald dream","relics of wakening","rune of nesting","атридас медвежья шкура","обитель бен'этиль","ларец размещения","друиды когтя","изумрудный сон","реликвии пробуждения","руна размещения"},ang={["class:Druid"]="Для друидов Руна Размещения воплощает священные ритуалы Круга Кенария и показывает уязвимость спящих собратьев, когда священные убежища осквернены.",["race:NightElf"]="Осквернение обителей и утрата этих реликвий пробуждения подчеркивают растущую порчу, поражающую животных и фурболгов Тельдрассила."},sec={{t="Священный фокус пробуждения",b="Друиды ночных эльфов погружаются в глубокую циклическую спячку в подземных обителях, чтобы общаться с природой через Изумрудный Сон. Выйти из этого глубокого транса — дело непростое: одного пробуждения мало, нужен точный ритуал со священными предметами. Руна Размещения, надежно хранящаяся в Ларце Размещения в извилистых залах Обители Бен'этиль, служит основой этого действа. Вместе с Талисманом Когтя Ворона, Черным пером и Небесным сапфиром руна становится проводником, призывающим Друидов Когтя обратно в мир бодрствования."},{t="Беда в Бен'этиль",b="Когда оскверненные фурболги Скверной Сосны захватили Обитель Бен'этиль, спящие защитники обители оказались в смертельной опасности. Без доступа к реликвиям друиды могли остаться в Изумрудном Сне навсегда, пока захватчики оскверняют их убежище. Возвращение Руны Размещения и других реликвий позволяет Атридасу Медвежьей Шкуре в Доланааре подготовить ритуал, необходимый для безопасного пробуждения друидов."}},faq={{q="Для чего нужна Руна Размещения?",a="Это одна из четырех Реликвий Пробуждения, необходимых Атридасу Медвежьей Шкуре для ритуала, безопасно пробуждающего Друидов Когтя от глубокого сна в Изумрудном Сне.",al={"what does rune of nesting do","rune of nesting purpose","что делает руна размещения","назначение руны размещения"}},{q="Где найти Руну Размещения?",a="Она хранится в Ларце Размещения в подземных туннелях Обители Бен'этиль к западу от Доланаара на Тельдрассиле.",al={"where is rune of nesting","chest of nesting location","где руна размещения","где ларец размещения"}},{q="Почему спящие друиды не могут просто проснуться сами?",a="Вход в Изумрудный Сон в спячке — хрупкое, подобное трансу состояние. Без руководства священных реликвий и ритуала пробуждения вернуться бывает невозможно: разум остается блуждать, а тело подвергается опасности.",al={"why do druids need waking ritual","why can't druids wake up","зачем друидам ритуал пробуждения","почему друиды не могут проснуться"}},{q="Какие еще реликвии нужны вместе с Руной Размещения?",a="Для полного ритуала нужны четыре Реликвии Пробуждения: Руна Размещения, Талисман Когтя Ворона, Черное перо и Небесный сапфир.",al={"other relics of wakening","relics of wakening items","другие реликвии пробуждения","предметы реликвий пробуждения"}}},fp="15,260,28.574.0,19.448.0,37.183.0,35.142.0,58.245.0,59.145.0"}
P.entries["item:runes-of-summoning"] = {n="Руны Призыва",s="Руны Призыва — ритуальный предмет, который выдает наставник чернокнижников Карендин Халгар в Магическом квартале Подгорода. С их помощью в круг призыва вызывают свободного демона Бездны, чтобы начинающий чернокнижник подчинил его своей воле.",h="Руны Призыва — ритуальный предмет, который выдает наставник чернокнижников Карендин Халгар в Магическом...",kw={"carendin halgar","magic quarter","runes of summoning","the binding","undercity","voidwalker","warlock","карендин халгар","магический квартал","руны призыва","подчинение","подгород","демон бездны","чернокнижник"},ang={["class:Warlock"]="Чернокнижники Отрекшихся используют руны, чтобы доказать свою власть над Пустотой, превращая хаотичную тень в стойкого и верного слугу.",["race:Undead"]="В подземных глубинах Подгорода Отрекшиеся, нарушая древние запреты, подчиняют существ Пустоты прямо под руинами Лордерона."},sec={{t="Подчинение в Магическом квартале",b="В темных закоулках Магического квартала Подгорода Отрекшиеся, практикующие темные искусства, изучают управление Пустотой. Карендин Халгар доверяет Руны Призыва только чернокнижникам, готовым взять под контроль демона Бездны. Бросив руны в действующий круг призыва под местом Халгара, чернокнижник разрывает ткань Пустоты и вытягивает существо, которое нужно одолеть и подчинить."}},faq={{q="Для чего нужны Руны Призыва?",a="Их используют в круге призыва в Магическом квартале Подгорода, чтобы вытянуть свободного демона Бездны из Круговерти Пустоты в материальный мир, где чернокнижник может победить и подчинить его.",al={"runes of summoning purpose","what do runes of summoning do","how to use runes of summoning","назначение рун призыва","что делают руны призыва","как использовать руны призыва"}},{q="Кто выдает Руны Призыва?",a="Их выдает Карендин Халгар, наставник чернокнижников из числа Отрекшихся в Магическом квартале Подгорода, на последнем этапе обучения подчинению демона Бездны.",al={"who gives runes of summoning","runes of summoning trainer","carendin halgar runes","кто дает руны призыва","наставник рун призыва","карендин халгар руны"}},{q="Где нужно активировать руны?",a="Их нужно принести к фиолетовому кругу призыва, расположенному прямо под площадкой Карендин Халгар в Магическом квартале.",al={"where do i use runes of summoning","runes of summoning location","summoning circle undercity","где использовать руны призыва","местонахождение рун призыва","круг призыва подгород"}},{q="Что происходит после призыва существа?",a="Демон Бездны сразу нападает. Чернокнижник должен усмирить его магией и оружием. После победы существо оказывается в услужении, и Карендин Халгар передает постоянное заклинание для его призыва.",al={"what happens after using runes","voidwalker subdued","after summoning voidwalker","что бывает после рун","демон бездны усмирен","после призыва демона бездны"}}},fp="18,256,32.474.0,41.192.0,36.163.0,34.124.0,42.193.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Мешок с головами мурлоков",s="Мешок с головами мурлоков — жуткая ноша, собранная на берегах Предгорий Хилсбрада. Собранный как доказательство боевых действий против прибрежных вредителей, он перекладывается лейтенантом Фарреном Оринелем на проходящих искателей приключений для доставки маршалу Редпату в Южнобережье.",h="Мешок с головами мурлоков — жуткая ноша, собранная на берегах Предгорий Хилсбрада.",kw={"bounty","farren orinelle","heads","hillsbrad","marshal redpath","murloc","southshore","награда","фаррен оринель","головы","хилсбрад","маршал редпат","мурлок","южнобережье"},ang={["faction:Alliance"]="Это поручение показывает расшатанное снабжение и неблагодарные повседневные тяготы защитников Южнобережья, удерживающих северный оплот Альянса."},sec={{t="Бюрократия и прибрежные вредители",b="Южнобережье постоянно осаждают разбойники Синдиката, отряды Отрекшихся и дикие мурлоки, наводнившие побережье. Чтобы получить средства и расположение руководства города, местные офицеры должны доказывать, что прибрежные угрозы активно истребляются. Лейтенант Фаррен Оринель собирает доказательства в виде отрубленных голов, но из-за неприятности груза и собственной брезгливости он передает сочащийся мешок путникам, а не относит жуткие доказательства маршалу Редпату сам."}},faq={{q="Что такое Мешок с головами мурлоков?",a="Это холщовый мешок с отрубленными головами мурлоков, собранными на западных берегах Хилсбрада. Он служит вещественным доказательством усмирения побережья для командира гарнизона Южнобережья.",al={"sack of heads","murloc sack","what is this item","мешок с головами","мешок мурлоков","что это за предмет"}},{q="Почему лейтенант Фаррен не доставит его сам?",a="Фаррен находит отвратительным носить зловонный мешок с гниющими головами рыбоподобных тварей. Желая сохранить чистыми мундир и руки, он поручает неприятную работу по городу Южнобережье услужливому искателю приключений.",al={"why farren makes you carry it","farren's excuse","lazy farren","почему фаррен заставляет нести","отговорка фаррена","ленивый фаррен"}},{q="Кто получает мешок?",a="Мешок доставляют маршалу Редпату, командиру, отвечающему за оборону Южнобережья, который оценивает безопасность города и требует веских доказательств усилий по защите.",al={"who gets the heads","where do i bring it","marshal redpath turn in","кто получает головы","куда нести мешок","маршал редпат сдать"}},{q="Почему Южнобережье требует головы мурлоков как доказательство?",a="Мурлоки постоянно нападают на побережье и угрожают гавани. Офицеры должны проверять, что патрули охраняют периметр, а осязаемые трофеи не позволяют солдатам присваивать заслуги за праздные дозоры.",al={"why collect murloc heads","proof of kill","зачем собирать головы мурлоков","доказательство убийства"}}},fp="20,285,29.515.0,33.189.0,47.208.0,22.171.0,50.226.0"}
P.entries["item:sack-of-supplies"] = {n="Мешок припасов",s="Эти мешки с припасами входили в караван, предназначенный гоблину-инженеру Резлаку близ Оргриммара. Груз везли через Дуротар, но его перехватили гарпии Пыльного Ветра, гнездящиеся в скалах Каньона Колючего Ветра.",h="Эти мешки с припасами входили в караван, предназначенный гоблину-инженеру Резлаку близ Оргриммара.",kw={"durotar","dustwind harpies","gazlowe","razorwind canyon","rezlak","sack of supplies","дуротар","гарпии пыльного ветра","газлоу","каньон колючего ветра","резлак","мешок припасов"},ang={["faction:Horde"]="Возвращение утраченных припасов у местных хищников позволяет строительству на границе вокруг юной столицы Оргриммара идти без дорогостоящих задержек."},sec={{t="Разграбленный караван",b="Резлак, инженер, нанятый Газлоу в Кабестане, полагается на регулярные караваны через Дуротар, снабжающие его стройки для Орды. Но дикая природа Дуротара далеко не мирная. Когда обещанный груз проезжал по дороге у каньона к югу от Оргриммара, на него напали и разграбили местные гарпии Пыльного Ветра. Свирепые твари утащили груз в свои гнезда в Каньоне Колючего Ветра, разбросав мешки в грязи и осыпях рядом с гнездовьями."}},faq={{q="Что внутри этих мешков с припасами?",a="В мешках — строительные материалы и товары, отправленные по заказу инженерных работ Газлоу для поддержки строек орков близ Оргриммара. Без них Резлак остался без припасов для завершения работы.",al={"supply sack contents","what are in the sacks","rezlak supplies","содержимое мешков","что в мешках","припасы резлака"}},{q="Кто украл припасы?",a="Припасы украли гарпии Пыльного Ветра — свирепая крылатая раса, населяющая высокие расселины и ущелья Каньона Колючего Ветра.",al={"who took the supplies","who stole the sacks","кто забрал припасы","кто украл мешки"}},{q="Кто такой Резлак?",a="Резлак — гоблин-инженер, посланный Газлоу из Кабестана, чтобы помогать Орде со строительством и прокладкой инфраструктуры в Дуротаре.",al={"who is rezlak","rezlak lore","кто такой резлак","резлак предания"}}},fp="16,228,19.496.0,34.232.0,23.133.0,14.132.0"}
P.entries["item:salty-scorpid-venom"] = {n="Соленый яд скорпида",s="Соленый яд скорпида — едкая жидкость, которую добывают из скорпидов, обитающих на Мерцающей равнине в Тысяче Игл. Он насыщен природными солями пустынной почвы, и гномы-гонщики на ракетах высоко ценят его как сырье для летучего, сверхгорячего топлива.",h="Соленый яд скорпида — едкая жидкость, которую добывают из скорпидов, обитающих на Мерцающей равнине в Тысяче...",kw={"fizzle brassbolts","mirage raceway","salty scorpid venom","scorpid reaver","scorpid terror","scorpid venom","shimmering flats","thousand needles","пшикс медноштиф","виражи на миражах","соленый яд скорпида","скорпид-разоритель","скорпид-ужас","яд скорпида","мерцающая равнина","тысяча игл"},ang={["profession:Engineering"]="Изобретатели, мастерящие на Мерцающей равнине, постоянно ищут что-то помимо обычной нефти и угля и испытывают органические токсины как летучие ускорители горения.",["race:Gnome"]="Только гномья изобретательность могла додуматься взять смертельный пустынный яд, смешать его с нега-катализаторами и закачать в ракетный двигатель ради того, чтобы выиграть пару секунд на круге."},sec={{t="Летучее горючее вещество",b="Скорпиды, ползающие по засушливым просторам Мерцающей равнины, приспособились к среде с огромным содержанием минералов. За многие поколения яд таких тварей, как скорпиды-разорители и скорпиды-ужасы, впитал огромное количество местной соли. Гномы-механики вроде Пшикса Медноштифа не варят из него противоядия или обычные яды, а ценят это едкое соединение как возможную добавку к топливу для двигателей с высокой температурой горения."},{t="Топливо для соперничества на трассе",b="На Виражах на Миражах инженерное соперничество гномов и гоблинов толкает изобретателей испытывать на ракетных болидах все более опасные материалы. Пшикс Медноштиф считает, что если выпарить соленый яд, обработать его особыми катализаторами и добавить в топливные баки, то получится жар, необходимый, чтобы обогнать гоблинов-гонщиков на солончаках."}},faq={{q="Какие существа производят соленый яд скорпида?",a="Его добывают из опасных скорпидов, бродящих по солончакам Тысячи Игл, в первую очередь из скорпидов-разорителей и скорпидов-ужасов.",al={"who drops salty scorpid venom","where to get scorpid venom","scorpid venom source","кто дропает соленый яд скорпида","где взять яд скорпида","источник яда скорпида"}},{q="Почему яд такой соленый?",a="Скорпиды живут исключительно на покрытой минеральной коркой земле Мерцающей равнины. Их организм впитывает плотные соли высохшего озерного дна, поэтому в ядовитых железах образуется заметная соленая концентрация.",al={"why is it salty","salt flat venom explanation","scorpid salt lore","почему он соленый","объяснение соленого яда","предания о соли скорпидов"}},{q="Кому нужен этот яд и зачем?",a="Пшикс Медноштиф, гном-инженер, работающий на Виражах на Миражах, ищет яд, чтобы создать экспериментальную топливную смесь, которая горит достаточно жарко, чтобы привести его ракетный болид к победе.",al={"who needs scorpid venom","why does fizzle want venom","fizzle brassbolts quest item","кому нужен яд скорпида","зачем Пшиксу яд","предмет задания Пшикса Медноштифа"}}},fp="19,253,27.425.0,27.377.0,43.138.0,26.212.0,29.185.0"}
P.entries["item:samophlange-item"] = {n="Самофланж (предмет)",s="Самофланж — загадочная механическая деталь, извлеченная из глубины автоматической панели управления в Степях. Несмотря на сложный вид, его точное назначение остается инженерной загадкой даже для гоблинов-механиков, которые за ним охотились.",h="Самофланж — загадочная механическая деталь, извлеченная из глубины автоматической панели управления в Степях.",kw={"barrens","console","ratchet","samophlange","sputtervalve","tinkers union","undermine","степи","панель управления","кабестан","самофланж","пароклапан","союз механиков","подкопье"},ang={["profession:Engineering"]="Инженеры оценят самофланж как образец чрезмерно усложненной конструкции, где затейливый фасад скрывает механизм, настолько хрупкий, что он ломается, едва коснувшись пола."},sec={{t="Загадочное устройство",b="Самофланж спрятан за лабиринтом лишней проводки и пустых трубок внутри панели управления в Степях. Чтобы выдернуть его из гнезда, приходится долго рыться в намеренно запутанном механизме. Неопытному глазу он кажется важнейшим узлом часовых и паровых технологий. Для гоблинов-механиков это неотразимая механическая головоломка, предназначенная для отправки в Союз механиков в Подкопье, хотя из-за хрупкости он редко переживает небрежное обращение настолько, чтобы его успели понять."},{t="Любопытство и катастрофа",b="Когда деталь приносят Пароклапану в Кабестан, инженер собирается отправить ее на изучение высокопоставленным умам Союза. Однако гоблинское любопытство неизбежно берет верх над профессиональной сдержанностью. Стоит просто положить хрупкое устройство, чтобы осмотреть его внутренности, и оно нередко рассыпается в негодный лом."}},faq={{q="Что такое самофланж?",a="Это странная механическая деталь, извлеченная из сердца панели управления в Степях. Ее настоящее назначение неизвестно: механизм вокруг набит трубками и проводами, которые, похоже, не выполняют никакой полезной работы.",al={"what does a samophlange do","samophlange purpose","what is this item","что делает самофланж","назначение самофланжа","что это за предмет"}},{q="Кому нужен самофланж?",a="Пароклапан, инженер из портового города Кабестан, просит путников добыть деталь, чтобы изучить ее и со временем отправить в Союз механиков.",al={"who needs the samophlange","who do i give the samophlange to","кому нужен самофланж","кому отдать самофланж"}},{q="Что Пароклапан делает с самофланжем?",a="Хотя он собирается отправить его в Подкопье для подробного изучения исследователями Союза механиков, сначала он пытается рассмотреть его сам. Стоит положить деталь на землю, как хрупкий механизм тут же ломается.",al={"sputtervalve samophlange","what happens to the samophlange","пароклапан самофланж","что будет с самофланжем"}},{q="Откуда взялся самофланж?",a="Он находится внутри сложной панели управления на севере Степей, скрытый за слоями запутанной и, на первый взгляд, бесполезной инженерии.",al={"samophlange location","where is it found","где найти самофланж","где он находится"}}},fp="18,261,22.542.0,25.355.1,22.241.0,26.178.0,34.231.1,36.167.0"}
P.entries["item:samophlange-manual"] = {n="Руководство по самофланжу",s="Руководство по самофланжу — техническое руководство по эксплуатации, описывающее устройство неуловимого самофланжа. Торговая Компания держит его под замком, а его разрозненные страницы содержат указания, необходимые гоблинам-инженерам, чтобы чинить и использовать это странное устройство.",h="Руководство по самофланжу — техническое руководство по эксплуатации, описывающее устройство неуловимого...",kw={"barrens","boss copperplug","boulder lode mine","engineering","manual","rilli greasygob","samophlange","sputtervalve","venture company","степи","начальник медноклин","каменный карьер","инженерное дело","руководство","рилли грязегоб","самофланж","пароклапан","торговая компания"},ang={["faction:Horde"]="Возвращение руководства позволяет гоблинам Оргриммара, союзным Орде, изучить и приспособить буровую технику корпорации прямо под носом у Торговой Компании.",["profession:Engineering"]="Руководство представляет собой закрытую технологию Торговой Компании и показывает, как гоблины-механики одержимо скрывают от коллег производственные тайны и рабочие чертежи."},sec={{t="Секреты устройства",b="Инженерные чертежи и руководства гоблинские предприятия охраняют как золото, и Руководство по самофланжу не исключение. Работая в Торговой Компании, честолюбивый надсмотрщик по имени Начальник Медноклин ревниво копил знания об устройстве и раздавал лишь разрозненные страницы самым преданным подчиненным, чтобы сохранить власть над механизмом. Когда устройство вышло из-под контроля Торговой Компании, починить его без сбора разорванной и розданной документации у надсмотрщика и его людей в Каменном карьере оказалось невозможно."},{t="Амбиции соперника",b="Порвав с Торговой Компанией, гоблин-инженер Рилли Грязегоб поселился в Оргриммаре в надежде освоить постройку самофланжа. Не пользуясь расположением Медноклина во время прежней службы, Рилли полагается на предприимчивых путников, которые добудут обложку и отдельные листы руководства. Восстановление руководства дает гоблинам-механикам, работающим вместе с Ордой, редкую возможность заглянуть в закрытые инженерные разработки Торговой Компании."}},faq={{q="Что такое Руководство по самофланжу?",a="Это инженерное руководство, описывающее, как использовать и чинить самофланж — сложное и эксцентричное механическое устройство, которое Торговая Компания применяла в Степях.",al={"what is samophlange manual","samophlange book","samophlange guide","что такое руководство по самофланжу","книга о самофланже","гайд по самофланжу"}},{q="Кто изначально владел руководством?",a="Его копил Начальник Медноклин, надсмотрщик Торговой Компании в Каменном карьере на северо-востоке Степей. Медноклин тщательно хранил его тайны и выдавал отдельные страницы только самым доверенным рабочим.",al={"who has the manual","boss copperplug manual","who wrote the manual","у кого руководство","начальник медноклин руководство","кто написал руководство"}},{q="Почему руководство разорвано на страницы?",a="Начальник Медноклин намеренно разделил книгу, чтобы соперники и ненадежные подчиненные не поняли устройство целиком. Обложку он оставил себе, а пять отдельных страниц раздал шахтерам и операторам.",al={"why find manual pages","scattered manual pages","why are pages missing","зачем искать страницы руководства","разрозненные страницы руководства","почему нет страниц"}},{q="Кто хочет прочесть собранное руководство?",a="Рилли Грязегобу, инженеру из Оргриммара, нужно собранное руководство, чтобы понять и починить сломанный самофланж, найденный в Степях.",al={"who needs the manual","rilli greasygob","who wants samophlange manual","кому нужно руководство","рилли грязегоб","кому нужно руководство по самофланжу"}},{q="Для чего используется самофланж?",a="Точное назначение самофланжа — эксцентричная гоблинская тайна, но Торговая Компания применяет их на промышленных раскопках, например на водяных промыслах и буровых установках в Степях.",al={"what does samophlange do","purpose of samophlange","samophlange purpose","что делает самофланж","назначение самофланжа","для чего нужен самофланж"}}},fp="18,280,26.574.0,18.455.0,31.166.0,32.230.0,34.226.0,39.162.0,31.209.0"}
P.entries["item:sample-ichor"] = {n="Образец лимфы",s="В этом флаконе — очищенный экстракт мерзкой жидкости, питающей гноллов-гнилошкуров Серебряного бора. Аптекарь Ренферрел разложил его на основные составляющие, и в веществе остались следы как некромантии, так и колдовства чернокнижников.",h="В этом флаконе — очищенный экстракт мерзкой жидкости, питающей гноллов-гнилошкуров Серебряного бора.",kw={"apothecary renferrel","bethor iceshard","magic quarter","rot hide","rot hide origins","sample ichor","silverpine","undercity","аптекарь ренферрел","бетор ледострел","магический квартал","гнилошкуры","происхождение гнилошкуров","образец лимфы","серебряный бор","подгород"},ang={["class:Mage"]="Бетор Ледострел использует особые заклинания прорицания, чтобы прочесть остатки в образце, что показывает ценность классического тайного анализа при столкновении с темным колдовством.",["class:Warlock"]="Аптекарь Ренферрел особо отмечает, что в лимфе искусства чернокнижников переплетены с некромантией, что намекает на роль скверны в создании этих зверей-нежити."},sec={{t="Разгадка Гнилошкуров",b="Гноллы-гнилошкуры, бродящие по Серебряному бору, — не обычные звери. Получив образцы от существ и их останков, аптекарь Ренферрел из Королевского фармацевтического общества разложил мерзкую жидкость на составные элементы. Его химический анализ показал, что лимфа создана искусственно на стыке темных школ: некромантические обряды переплетены с магией чернокнижников. Поскольку это искусство граничит с тайными дисциплинами, выходящими за рамки простой алхимии, Ренферрел упаковал образец и отправил его в Подгород, чтобы Бетор Ледострел исследовал его с помощью прорицания."}},faq={{q="Что такое образец лимфы?",a="Это очищенный экстракт, который аптекарь Ренферрел приготовил из телесных жидкостей гноллов-гнилошкуров. Ренферрел разделил его на основные составляющие, чтобы изучить магические методы, которыми создавались эти ходячие мертвые звери.",al={"sample ichor","what is this ichor","what is sample ichor","образец лимфы","что это за лимфа","что такое образец лимфы"}},{q="Кому нужно показать этот образец?",a="The sample must be delivered to Bethor Iceshard, an undead mage stationed within the Magic Quarter of the Undercity. Bethor's expertise in divination and magical traditions allows him to identify traces of magic that standard alchemy cannot discern.",al={"who do i bring the ichor to","sample ichor turn in","bethor iceshard ichor","кому нести лимфу","сдать образец лимфы","бетор ледострел лимфа"}},{q="Какая магия заключена в лимфе?",a="Ренферрел обнаружил в жидкости сочетание магии чернокнижников и некромантии. Осмотрев флакон, Бетор Ледострел отмечает, что в нее вплетены мощные древние чары, для раскрытия которых требуется более глубокое заклинание прорицания.",al={"what magic is in the ichor","ichor magic type","rot hide magic","какая магия в лимфе","тип магии лимфы","магия гнилошкуров"}},{q="Почему аптекари не закончили анализ сами?",a="Хотя Королевское фармацевтическое общество сильно в алхимии, ядах и телесных недугах, расшифровка сложных тайных плетений требует специального чародея. Бетор Ледострел умеет определять магические школы и разгадывать эзотерические заклинания, недоступные обычному оборудованию аптекаря.",al={"why apothecary sent to bethor","why not renounce rot hide ichor","почему аптекарь отправил к бетору","почему не изучили лимфу гнилошкуров сами"}}},fp="12,252,24.620.0,25.222.0,29.249.0,39.246.0,59.278.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Образец видоизмененной смеси Занзила",s="В этом флаконе находится сильнодействующий образец зелья, сваренного знахарем Занзилом. Его добыли во время тайного проникновения в Степи. Образец доставляет агент, страдающий от его изнуряющего действия, и отправляет через море на Мельницу Таррен в надежде найти противоядие и раскрыть смертоносные тайны ремесла ядов.",h="В этом флаконе находится сильнодействующий образец зелья, сваренного знахарем Занзилом.",kw={"altered mixture","hillsbrad","poisons","rogue","serge hinott","sludge fen","tarren mill","zanzil","видоизмененная смесь","хилсбрад","яды","разбойник","серж хинотт","нефтяное болото","мельница таррен","занзил"},ang={["class:Rogue"]="Доставка этого мерзкого образца — обряд посвящения для разбойников Орды, ведущий прямо к продвинутым урокам Сержа Хинотта по приготовлению, обращению и нанесению смертельных ядов.",["faction:Horde"]="Перевозка этого опасного зелья требует путешествия через континенты: по дирижабельным башням и проложенным дорогам, связывающим Калимдор с землями Отрекшихся в Лордероне."},sec={{t="Ядовитая весть",b="Проникнув в башню Торговой Компании у Нефтяного болота и забрав из сундука Галливикса запас смеси Занзила, агент оказывается поражен скверной Занзила. Шентул приказывает больному агенту отправиться через Великое море с образцом зелья. Чтобы найти лекарство, нужно отыскать Сержа Хинотта, аптекаря с Мельницы Таррен в Предгорьях Хилсбрада, обладающего редкими знаниями, необходимыми для выделения яда и расшифровки его состава."},{t="Тайны ремесла ядов",b="Образец — не только неотложная медицинская задача, но и бесценный экземпляр для разбойников Орды, стремящихся постичь темные стороны своего ремесла. Серж Хинотт исследует видоизмененную смесь не просто чтобы очистить отравленного курьера, но и чтобы показать, какое точное химическое мастерство нужно для приготовления сильных ядов и обращения с ними в полевых условиях."}},faq={{q="Что это за смесь?",a="Это образец алхимического зелья, связанного со знахарем Занзилом, добытый во время задания в башне Торговой Компании у Нефтяного болота в Степях. В нем содержится сильный яд, вызывающий затяжные изнуряющие последствия у всех, кто вступает с ним в прямой контакт.",al={"what is zanzils mixture","sample of zanzils altered mixture","zanzil poison sample","что за смесь занзила","образец видоизмененной смеси занзила","образец яда занзила"}},{q="Почему я должен доставить это Сержу Хинотту?",a="Серж Хинотт — опытный аптекарь с Мельницы Таррен в Предгорьях Хилсбрада. Он обладает специальными знаниями, необходимыми, чтобы нейтрализовать действие зелья и создать надежное лекарство, пока яд не причинил непоправимый вред.",al={"who is serge hinott","why take to tarren mill","cure for zanzil mixture","кто такой серж хинотт","почему отнести на мельницу таррен","лекарство от смеси занзила"}},{q="Кто такой Занзил?",a="Занзил Отверженный — известный знахарь из троллей джунглей, создающий эликсиры безумия, яды и мутагены. Его ядовитые рецепты распространились далеко за пределы родных джунглей и попали в наемные и промышленные предприятия, такие как Торговая Компания.",al={"who is zanzil","zanzil the outcast","zanzil lore","кто такой занзил","занзил отверженный","занзил предания"}},{q="Как добраться до Мельницы Таррен, чтобы доставить образец?",a="Путникам нужно сесть на дирижабль из Дуротара в Подгород в Тирисфальских лесах. Оттуда следует идти по главной дороге на юг через Серебряный бор, затем по указателям на восток в Предгорья Хилсбрада, пока не дойдете до города Мельница Таррен.",al={"how to get to tarren mill","travel to hillsbrad","tarren mill directions","как добраться до мельницы таррен","путь в хилсбрад","дорога к мельнице таррен"}}},fp="34,334,13.478.0,22.344.1,21.277.0,41.236.0,14.274.0,43.245.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Образец панциря хрустогрыза",s="Образец панциря хрустогрыза — прочный черепаший панцирь, добытый у пресноводных оазисов Степей. Благодаря своей необычной жизненной силе он отправляется через Великое море, чтобы помочь друидам исследовать возрождение оскверненных лесов Серебряного бора.",h="Образец панциря хрустогрыза — прочный черепаший панцирь, добытый у пресноводных оазисов Степей.",kw={"barrens","mura runetotem","oasis","sample snapjaw shell","sepulcher","silverpine","snapjaw","turtle shell","степи","муура рунический тотем","оазис","образец панциря хрустогрыза","гробница","серебряный бор","хрустогрыз","черепаший панцирь"},ang={["class:Druid"]="Для друидов круга Кенария изучение стойкой жизненной силы хрустогрызов оазисов дает важные уроки о том, как жизнь упорствует и как оскверненную землю однажды можно исцелить.",["race:Tauren"]="Доставка этого панциря подчеркивает преданность тауренов Матери-Земле и их готовность предложить помощь и природное исцеление даже своим союзникам-нежити за морем."},sec={{t="Искра жизни оазиса",b="Щелкающие черепахи, обитающие в пышных оазисах Степей, отмеченных аномалиями, обладают панцирями удивительной силы. В отличие от обычного материала панциря, свежий образец панциря хрустогрыза долго после отделения от существа сохраняет слабое внутреннее сияние и живой пульс. Для друидов-тауренов, наблюдающих за быстрыми переменами в природе этих земель, эти панцири воплощают стойкую, приспосабливающуюся искру дикой природы Калимдора и говорят о том, что природа способна расцветать даже в суровой засушливой местности."},{t="Исцеление далеких земель",b="Распознав скрытую жизненную силу панциря, натуралисты-тауренов отправляют курьеров через море, чтобы доставить образцы Мууре Рунический Тотем в Гробницу. Находясь в оскверненных просторах Серебряного бора, Муура стремится помочь Отрекшимся, ища способы исцелить пораженные северные земли. Изучая стойкую жизненную силу, сохранившуюся внутри панциря хрустогрыза, она надеется найти тайны, способные возродить больной лес и вызвать рост на умирающей почве."}},faq={{q="Чем особенен этот панцирь хрустогрыза?",a="В отличие от хрупкой обычной кости, этот панцирь хранит внутреннее свечение и, кажется, все еще пульсирует жизнью после добычи. Он принадлежит хрустогрызам, процветающим у странных пресноводных оазисов Степей, где природные силы необычайно сильны.",al={"why is shell special","what is snapjaw shell","glowing shell","чем особенен панцирь","что такое панцирь хрустогрыза","светящийся панцирь"}},{q="Кому нужен этот образец?",a="Панцирь предназначен для Муура Рунический Тотем, друида-тауренки, живущей в Гробнице в Серебряном бору. Она отправилась в Восточные королевства, чтобы помочь Отрекшимся и изучить, как вернуть умирающие земли к жизни.",al={"who wants the shell","where do i bring shell","mura runetotem quest","кому нужен панцирь","куда отнести панцирь","задание муура рунический тотем"}},{q="Зачем отправлять панцирь из Степей так далеко, в Серебряный бор?",a="Серебряный бор — больной, оскверненный лес, тогда как оазисы Степей внезапно наполнились упорной, стойкой жизнью. Друиды считают, что изучение мощной жизненной силы зверей Калимдора может помочь понять, как исцелить оскверненную почву Лордерона.",al={"why send to silverpine","shell connection to silverpine","зачем отправлять в серебряный бор","связь панциря с серебряным бором"}},{q="Опасен ли панцирь, оскверен ли он?",a="Нет. Панцирь излучает чистую жизненную силу, а не темную магию. Хотя внезапный разрост зелени в оазисах Степей загадочен, друиды видят в этой остаточной энергии природную стойкость, которую стоит развивать.",al={"is shell evil","is the shell corrupted","панцирь злой","панцирь осквернен"}}},fp="20,263,21.492.0,21.481.0,38.251.0,22.213.0,51.261.0,34.210.0"}
P.entries["item:samuel-s-remains"] = {n="Останки Самуэля",s="Останки Самуэля — найденные бренные остатки Самуэля Фиппса, бывшего жителя Тирисфальских лесов, павшего от рук Плети. Искатели приключений собирают их возле Могильника и погребают рядом с его женой Марлой, исполняя ее предсмертное желание.",h="Останки Самуэля — найденные бренные остатки Самуэля Фиппса, бывшего жителя Тирисфальских лесов, павшего от...",kw={"deathknell","marla fipps","marla's grave","marla's last wish","novice elreth","samuel fipps","samuel's remains","могильник","марла фиппс","могила марлы","последнее желание марлы","новобранец элрет","самуэль фиппс","останки самуэля"},ang={["race:Undead"]="Погребение останков Самуэля — ранний урок самосознания Отрекшихся: уважение к трагически погибшим отделяет свободную нежить от бездумных рабов Плети."},sec={{t="Трагическая встреча",b="Прежде чем чума нежизни охватила Лордерон, Самуэль Фиппс мирно жил с женой Марлой. Когда пришла зараза, Самуэль погиб и был обращен в бездумного слугу Плети. Марла избежала нежизни, но пала от руки любимого мужа. Несмотря на жестокий конец, ее последним желанием была не месть, а вечность вместе: она просила похоронить ее рядом с Самуэлем, когда его проклятая плоть обретет покой. Новобранец Элрет в Могильнике поручает недавно пробудившимся Отрекшимся найти блуждающего Самуэля к северо-востоку от поселения, забрать его кости и похоронить их в первом ряду местного кладбища."}},faq={{q="Кем был Самуэль Фиппс?",a="Самуэль Фиппс был человеком, жившим в Тирисфальских лесах до Третьей войны. Когда нагрянула чума Плети, он умер и восстал нежитью, рабом Короля-лича. Движимый бездумным голодом, он в конце концов убил собственную жену Марлу.",al={"samuel fipps","who is samuel","samuel backstory","самуэль фиппс","кто такой самуэль","история самуэля"}},{q="Где найти останки Самуэля?",a="Их забирают у самого Самуэля Фиппса, который бродит среди разрушенного лагеря у дороги к северо-востоку от Могильника. Положив конец его бездумному существованию, можно забрать его бренные останки.",al={"find samuel remains","where is samuel fipps","samuel location","найти останки самуэля","где самуэль фиппс","местонахождение самуэля"}},{q="Почему Отрекшиеся хоронят его рядом с женой?",a="Предсмертным желанием Марлы было покоиться рядом с любимым мужем, хотя именно он ее убил. Новобранец Элрет исполняет эту просьбу, чтобы доказать, что освободившиеся Отрекшиеся сохранили сострадание, уважение к мертвым и человечность, отличающие их от Плети.",al={"why bury samuel","marla grave","marlas last wish","зачем хоронить самуэля","могила марлы","последнее желание марлы"}}},fp="16,242,16.635.0,21.233.0,33.202.0,45.279.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Сапфир Аку'май",s="Сапфиры Аку'май — светящиеся скопления минералов, пропитанные водой, растущие в подземных туннелях Непроглядной Пучины. Наступающие наги начали собирать эти самоцветы, и Служители Земли стремятся найти их, пока их мощную тайную силу не использовали во зло.",h="Сапфиры Аку'май — светящиеся скопления минералов, пропитанные водой, растущие в подземных туннелях...",kw={"aku'mai","blackfathom deeps","crystals","je'neu sancrea","naga","sapphire","water spirits","zoram strand","аку'май","непроглядная пучина","кристаллы","дже'неу санкри","наги","сапфир","духи воды","зорамское взморье"},ang={["class:Mage"]="Природная насыщенность водой делает эти необработанные сапфиры весьма ценными проводниками мощных тайных компонентов.",["class:Shaman"]="Шаманы Служителей Земли, такие как Дже'неу Санкри, легко ощущают духов воды, заключенных в этих самоцветах, и считают сбор нагами стихийной угрозой."},sec={{t="Самоцветы глубин",b="Сапфиры Аку'май — кристаллические образования, богатые стихийной энергией, — найдены у водяных входов в пещеры Непроглядной Пучины на Зорамском взморье в Ясеневом лесу. Духи воды крепко держатся за них, делая их превосходными катализаторами магических ритуалов. Когда разведчики сообщили, что подземные наги принялись добывать эти скопления из стен пещер, шаман Дже'неу Санкри обратился к искателям приключений с просьбой изъять их. В руках змеиного народа камни могли бы легко питать разрушительные тайные обряды."}},faq={{q="Что такое сапфир Аку'май?",a="Это яркие сапфировые кристаллы, покрывающие стены Непроглядной Пучины. Тесно связанные со стихийными духами воды, они обладают глубоким тайным и стихийным резонансом.",al={"what is this crystal","sapphire of aku'mai lore","what are these gems","что за кристалл","сапфир аку'май предания","что за самоцветы"}},{q="Почему наги собирают эти сапфиры?",a="Их точные намерения неясны, но Дже'неу Санкри подозревает, что наги хотели использовать обильную водную и тайную энергию кристаллов для опасного колдовства в затопленном храме.",al={"why do naga want sapphires","naga crystal harvesting","зачем нагам сапфиры","сбор кристаллов нагами"}},{q="Кто ищет эти сапфиры?",a="Дже'неу Санкри, шаман Служителей Земли из форта Зорам'гар на Зорамском взморье в Ясеневом лесу, поручает путникам собрать их, чтобы они не достались нагам.",al={"who wants sapphires of akumai","who turns in essence of akumai","кто хочет сапфиры аку'май","кому сдать сапфир аку'май"}},{q="Связаны ли эти кристаллы напрямую со зверем Аку'май?",a="Хотя они названы в честь Аку'май, чудовищной гидры, обитающей в глубинах, кристаллы растут в стенах пещер естественным образом. Название отражает их близость к темному присутствию, таящемуся в руинах.",al={"aku'mai connection","is it from akumai","связь с аку'май","из аку'май ли он"}}},fp="19,275,16.557.0,30.177.0,44.193.0,35.174.0,54.202.0"}
P.entries["item:sapphire-of-sky"] = {n="Небесный сапфир",s="Небесный сапфир — одна из четырех священных Реликвий Пробуждения, хранимых ночными эльфами в Обители Бен'этиль. Это важнейший фокус, с помощью которого безопасно призывают спящих Друидов Когтя из Изумрудного Сна.",h="Небесный сапфир — одна из четырех священных Реликвий Пробуждения, хранимых ночными эльфами в Обители...",kw={"athridas bearmantle","ban'ethil barrow den","chest of the sky","druid of the talon","emerald dream","relics of wakening","sapphire of sky","атридас медвежья шкура","обитель бен'этиль","сундук неба","друид когтя","изумрудный сон","реликвии пробуждения","небесный сапфир"},ang={["class:Druid"]="Сапфир показывает, насколько осторожными должны быть ритуалы при проекции духа в Изумрудный Сон и как легко единение без священных якорей может стать смертельным.",["race:NightElf"]="Сохранение священных артефактов в Обители Бен'этиль необходимо, чтобы защитить хрупкий порядок Тельдрассила в условиях нарастающей порчи."},sec={{t="Ритуал пробуждения",b="В глубине корней Тельдрассила Друиды Когтя общаются с дикой природой, пребывая в спячке в Обители Бен'этиль. Пробуждение из столь глубокого транса в явный мир — хрупкий и опасный процесс. Для безопасного перехода друиды полагаются на четыре освященных артефакта, известных как Реликвии Пробуждения: Черное перо, Талисман Когтя Ворона, Руна Размещения и Небесный сапфир. Без этого резонирующего самоцвета необходимая гармония для возвращения спящих духов из Изумрудного Сна остается неполной, и они рискуют остаться в плену навечно."},{t="Угроза в Бен'этиль",b="Когда оскверненные фурболги Скрюченной Сосны захватили обитель, священные артефакты остались в своих искусных хранилищах. Небесный сапфир надежно хранится в Сундуке неба среди извилистых подземных ходов. Поскольку друиды беспомощны или похищены неистовыми фурболгами, достать этот камень вместе с остальными реликвиями — срочное дело для Атридаса Медвежьей Шкуры в Доланааре, пока спящие не потеряны навсегда."}},faq={{q="Что такое Небесный сапфир?",a="Это священный драгоценный камень, одна из четырех Реликвий Пробуждения, хранимых в Обители Бен'этиль. Вместе с тремя птичьими талисманами он помогает безопасно вывести Друидов Когтя из Изумрудного Сна.",al={"sapphire of sky lore","what is this gem","sky sapphire","небесный сапфир предания","что за самоцвет","сапфир неба"}},{q="Где хранится Небесный сапфир?",a="Он хранится в Сундуке неба в подземном лабиринте Обители Бен'этиль в центре Тельдрассила.",al={"where to find sapphire of sky","chest of the sky location","sapphire location","где найти небесный сапфир","сундук неба","где сапфир"}},{q="Почему сапфир нужен прямо сейчас?",a="Оскверненные фурболги Скрюченной Сосны вторглись в Обитель Бен'этиль, и спящим друидам грозит серьезная опасность. Друиды в глубоком трансе не могут просто проснуться сами; Атридасу Медвежьей Шкуре нужны сапфир и другие реликвии, чтобы провести тонкий ритуал пробуждения, пока спящие не потеряны навсегда.",al={"why get the sapphire","relics of wakening purpose","зачем нужен сапфир","назначение реликвий пробуждения"}},{q="Кто использует этот артефакт?",a="Друиды Когтя и хранители ритуалов, такие как Атридас Медвежья Шкура, используют его в общих обрядах, пробуждающих спящих братьев от глубокого единения с природой.",al={"who uses sapphire of sky","druid ritual gem","кто использует небесный сапфир","самоцвет друидов"}}},fp="15,218,19.602.0,23.452.0,28.211.0,34.132.0,37.303.0,23.172.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Мольба Сары Баллу",s="Просьба Сары Балу — рукописное послание, написанное скорбящей вдовой в Стальгорне. Не в силах предстать перед монархом из-за горя, она доверяет это письмо надежному защитнику Альянса, чтобы тот передал его королю Магни Бронзобороду.",h="Просьба Сары Балу — рукописное послание, написанное скорбящей вдовой в Стальгорне.",kw={"a king's tribute","high seat","ironforge","magni bronzebeard","sara balloo","sara balloo's plea","королевская дань","высокий трон","стальгорн","магни бронзобород","сара балу","просьба сары балу"},ang={["faction:Alliance"]="Сара доверяет свою просьбу только защитникам, известным службой Альянсу, надеясь, что их репутация обеспечит ей аудиенцию у короля.",["race:Dwarf"]="Для дворфов доставить послание Сары к Высокому трону — акт глубокого родства: даже в горе ни один горец и ни один горожанин не останется неуслышанным королем Магни."},sec={{t="Мольба вдовы",b="Написанная в тени глубокой личной трагедии, Просьба Сары Балу — это смиренное обращение к трону Стальгорна. Не решаясь в своем горе подойти к Высокому трону сама, Сара ищет искателя приключений, проявившего верность и доблесть перед Альянсом, чтобы он доставил ее слова. В послании она просит внимания короля Магни Бронзоборода и обращает взор государя к тихой скорби и жертвам обычных дворфийских семей, служащих королевству."}},faq={{q="Что такое Просьба Сары Балу?",a="Это рукописное письмо Сары Балу, адресованное королю Магни Бронзобороду, с просьбой о королевском внимании, пока она скорбит в уединении.",al={"sara balloo plea","widow note ironforge","sara note","просьба сары балу","записка вдовы стальгорн","записка сары"}},{q="Почему Саре Балу нужен кто-то, чтобы доставить письмо?",a="Сара убита горем и считает, что появление перед Королем Стальгорна в таком состоянии помешает ее просьбе, поэтому она полагается на защитника Альянса.",al={"why deliver note","why cant sara go","sara grief","зачем доставлять записку","почему сара не может пойти","горе сары"}},{q="Кто получает это послание?",a="Письмо адресовано и доставляется лично королю Магни Бронзобороду в Высоком троне Стальгорна.",al={"who gets plea","who to deliver to","magni letter","кто получает просьбу","кому доставить","письмо магни"}},{q="К чему приводит доставка письма?",a="Вручение письма королю Магни привлекает его внимание к утрате Сары Балу и вызывает королевский ответ в честь ее павшей семьи.",al={"plea questline","a kings tribute link","what happens next","цепочка заданий просьбы","королевская дань","что дальше"}}},fp="18,238,16.491.0,27.146.0,53.187.0,26.103.0,40.143.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Голова Сарилуса Грязнорожденного",s="Голова Сарилуса Грязнорожденного — жуткий трофей, снятый с мертвого чародея, осквернившего воды северного Калимдора. Доставленная из Степей в Ясеневый лес, она служит неопровержимым доказательством того, что вмешивавшийся в чужие дела некромант погиб от рук Часовых.",h="Голова Сарилуса Грязнорожденного — жуткий трофей, снятый с мертвого чародея, осквернившего воды северного...",kw={"barrens","dreadmist peak","head","mage summoner","sarilus foulborne","silverwind refuge","velene starstrike","water elementals","степи","вершина багрового тумана","голова","маг-призыватель","сарилус грязнорожденный","приют серебряного ветра","велена звездный всполох","элементали воды"},ang={["faction:Alliance"]="Для этого удара нужно проникнуть глубоко на враждебные земли Орды в Степях, чтобы уничтожить опасного чародея-отступника.",["race:NightElf"]="Отрубленная голова Грязнорожденного утоляет жажду мести Часовых безрассудному осквернителю, надругавшемуся над духами земли."},sec={{t="Осквернитель умолк",b="Perched high atop Dreadmist Peak in the northern Barrens, the Forsaken spellcaster Sarilus Foulborne drew the wrath of the night elves by corrupting and binding swarms of water elementals. From her post at Silverwind Refuge, Sentinel Velene Starstrike recognized his foul handiwork and dispatched champions across the frontier into Horde territory to end his reckless experiments. Severing the mage's head was the only proof Starstrike would accept to verify that his mocking grin was wiped away forever, securing a measure of peace for the troubled waters of Ashenvale."}},faq={{q="Кем был Сарилус Грязнорожденный?",a="Сарилус Грязнорожденный — маг-нежить, обосновавшийся на Вершине Багрового Тумана в северных Степях. Он навлек гнев ночных эльфов, искажая и призывая огромное число элементалей воды, из-за чего Часовой Велена Звездный Всполох приказала его убить.",al={"who is sarilus","sarilus foulborne lore","who is foulborne","кто такой сарилус","сарилус грязнорожденный предания","кто такой грязнорожденный"}},{q="Почему Часовой Велена Звездный Всполох хочет получить его голову?",a="Велена Звездный Всполох хотела быть абсолютно уверена, что высокомерный чародей мертв. Сарилус открыто насмехался над ней, оскверняя духов воды региона, и отрубленная голова была единственным доказательством, которое она принимала, что угроза устранена.",al={"why take his head","velene starstrike head","proof of death","зачем отрубать голову","голова велена звездный всполох","доказательство смерти"}},{q="Где находится Сарилус Грязнорожденный?",a="Он обитает на самой вершине Вершины Багрового Тумана — скалистой горы на севере Степей, к югу от границы с Ясеневым лесом.",al={"where to find foulborne","sarilus location","dreadmist peak mage","где найти грязнорожденного","где сарилус","маг на вершине багрового тумана"}},{q="Почему Грязнорожденный оскверняет элементалей воды?",a="Грязнорожденный с помощью тайных призываний подчинил своей воле множество элементалей воды, оскверняя их. Его безрассудные манипуляции нарушили естественный баланс вод близ Ясеневого леса и вызвали быстрый ответ Часовых.",al={"why corrupt elementals","water elemental corruption","foulborne motives","зачем осквернять элементалей","порча элементалей воды","мотивы грязнорожденного"}}},fp="24,293,18.570.0,26.261.0,50.261.0,35.146.0,44.251.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Уродливый коготь Саркота",s="Уродливый коготь Саркота — отрубленная клешня Саркота, чудовищного скорпида, бродящего по южным обрывам Долины Испытаний. Покрытый шрамами от руки умирающего тролля Хана'зуа, трофей служит и доказательством гибели зверя, и последним утешением для гордости раненого охотника.",h="Уродливый коготь Саркота — отрубленная клешня Саркота, чудовищного скорпида, бродящего по южным обрывам...",kw={"claw","durotar","hana'zua","mangled claw","sarkoth","scorpid","valley of trials","коготь","дуротар","хана'зуа","уродливый коготь","саркот","скорпид","долина испытаний"},ang={["faction:Horde"]="Для новобранцев в Долине Испытаний добыча этого трофея — одно из первых испытаний мужества и боевой силы в суровых землях Дуротара.",["race:Troll"]="Принеся уродливый коготь Хана'зуа, вы даруете умирающему сородичу из племени Черного Копья толику достоинства: он узнает, что его последний удар оставил след на звере."},sec={{t="Трофей мести",b="Охотясь в Долине Испытаний, молодой тролль из племени Черного Копья по имени Хана'зуа вступил в бой с огромным скорпидом Саркотом. Прежде чем ядовитое жало Саркота пронзило его грудь и оставило истекать кровью под деревом, Хана'зуа нанес сокрушительный удар по огромной клешне создания. Отсеченная клешня служит неопровержимым доказательством гибели чудовищного скорпида. Для Хана'зуа уродливый коготь подтверждает, что его отчаянный удар оставил след, и дарит мимолетную искру воинской чести, пока яд бежит по его жилам."}},faq={{q="Почему коготь изуродован?",a="Коготь был раздроблен в отчаянной схватке Саркота и тролля-охотника Хана'зуа. Хотя Саркот нанес Хана'зуа смертельный укол в грудь, тролль яростно ударил по клешне зверя, прежде чем она сомкнулась на его ноге.",al={"why broken claw","who crushed sarkoth claw","mangled claw lore","почему сломан коготь","кто раздробил коготь саркота","предания об уродливом когте"}},{q="Кому нужен Уродливый коготь Саркота?",a="Коготь просит Хана'зуа. Он лежит смертельно отравленный под деревом на севере Долины Испытаний и отчаянно хочет получить доказательство гибели своего последнего врага, пока не поддался яду скорпида.",al={"who needs sarkoth claw","who turned in to","hanazua claw","кому нужен коготь саркота","кому сдать","коготь хана'зуа"}},{q="Откуда взялся этот коготь?",a="Он взят у Саркота, крупного агрессивного скорпида, бродящего по возвышенному плато вдоль южных утесов Долины Испытаний в Дуротаре.",al={"sarkoth location","where is sarkoth","where to get mangled claw","где саркот","расположение саркота","где взять уродливый коготь"}}},fp="22,282,21.559.0,24.245.0,33.216.0,30.148.0"}
P.entries["item:sarltooth-s-talon"] = {n="Коготь Зарлозуба",s="Коготь Зарлозуба — отрубленный коготь вожака-ящера, обитающего над Раскопками Вельгара в Болотине. Он служит дворфу Ормеру Сталеплету осязаемым доказательством того, что свирепый зверь, захвативший археологические раскопки, убит.",h="Коготь Зарлозуба — отрубленный коготь вожака-ящера, обитающего над Раскопками Вельгара в Болотине.",kw={"excavation","ormer ironbraid","raptor","sarltooth","talon","wetlands","whelgar","раскопки","ормер сталеплет","ящер","зарлозуб","коготь","болотина","вельгар"},ang={["class:Hunter"]="Выследить хитрого вожака вроде Зарлозуба и взять его коготь как трофей — классическое испытание меткости и повелевания зверями.",["race:Dwarf"]="Возвращение этого когтя дарит долгожданную месть павшим дворфийским археологам, погибшим на службе Лиги исследователей по воле короля Магни Бронзоборода."},sec={{t="Трофей мести",b="Когда ящеры захватили Раскопки Вельгара и перебили дворфийскую экспедицию, Ормер Сталеплет наблюдал с гребня выше, не в силах помешать резне. Он выделил одного огромного, грозного ящера — Зарлозуба — как вероятного вожака нападения. Желая отомстить за павших сородичей, Ормер потребовал смерти зверя и попросил в доказательство один из его свирепых когтей. Отсеченный коготь означает конец власти террора Зарлозуба над древними дворфийскими руинами."}},faq={{q="Откуда берется Коготь Зарлозуба?",a="Коготь срезан с Зарлозуба, крупного вожака-ящера, бродящего по западным гребням над Раскопками Вельгара в Болотине.",al={"who drops sarltooths talon","sarltooth location","how to get talon","с кого падает коготь зарлозуба","где зарлозуб","как получить коготь"}},{q="Кому нужен Коготь Зарлозуба?",a="Ормер Сталеплет, дворф, стоящий на обзорной площадке над Раскопками Вельгара, просит коготь, чтобы убедиться, что зверь, перебивший его людей, уничтожен.",al={"who takes the talon","where to turn in talon","ormer ironbraid quest","кто принимает коготь","куда сдать коготь","задание ормера сталеплета"}},{q="Зачем Ормеру Сталеплету доказательство смерти Зарлозуба?",a="Ормер уверен, что Зарлозуб возглавлял стаю ящеров, которая согнала и убила дворфийских землекопов. Он считает коготь знаком справедливости и завершения для павших товарищей.",al={"why kill sarltooth","what did sarltooth do","зачем убивать зарлозуба","что сделал зарлозуб"}},{q="Что случилось с дворфами на раскопках?",a="Дворфийские раскопки должны были добыть древние артефакты для Лиги исследователей, но дикие ящеры напали на рабочих из засады, перебили большинство и загнали выживших на соседний гребень.",al={"whelgars excavation site lore","why are raptors at the dig","предания о раскопках вельгара","почему ящеры на раскопках"}}},fp="17,268,21.498.0,39.139.0,28.173.0,57.175.0,52.193.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Жертвоприношение Сатры",s="Жертвоприношение Сатры — серебристые прядильные органы, взятые у леди Сатры, могучего паука из Тельдрассила. Жрица А'моора вверяет их искателям приключений, чтобы те преподнесли дар у фонтана Храма Луны, очистили создание от порчи и упокоили ее дух.",h="Жертвоприношение Сатры — серебристые прядильные органы, взятые у леди Сатры, могучего паука из Тельдрассила.",kw={"darnassus","elune","lady sathrah","priestess a'moora","sathrah's sacrifice","silvery spinnerets","spider","teldrassil","temple of the moon","дарнасс","элуна","леди сатра","жрица а'моора","жертвоприношение сатры","серебристые прядильные органы","паук","тельдрассил","храм луны"},ang={["class:Priest"]="Жрицы, служащие Сестринству Элуны, видят в этом ритуале торжественный акт божественного милосердия: святые воды очищают скверну, а не просто избавляются от убитого зверя.",["race:NightElf"]="Для ночных эльфов упокоение оскверненных созданий — печальный долг; возвращая дух леди Сатры в милость Элуны, они обеспечивают возможность возрождения жизни в Тельдрассиле без безумия."},sec={{t="Очищение в священных водах",b="Леди Сатра была некогда почтенным созданием Тельдрассила, павшим жертвой подкрадывающегося безумия и порчи, поразивших ветви великого древа. По поручению Сестринства Элуны искатели приключений добывают ее серебристые прядильные органы не как простой трофей, а как освященный дар. Когда эти останки омывают в священном фонтане Храма Луны, мерзкая скверна, отравившая разум Сатры, смывается. Обряд освобождает ее встревоженную душу, позволяя духу мирно явиться в святилище и даруя ей обещание возрождения по милости Элуны."}},faq={{q="Что такое Жертвоприношение Сатры?",a="Жертвоприношение Сатры — ритуальный дар из серебристых прядильных органов леди Сатры, оскверненного гигантского паука, убитого в Тельдрассиле. Сестринство Элуны использует его в очищающем обряде, чтобы очистить душу создания.",al={"what are the spinnerets","sathrah sacrifice item","lady sathrah offering","что за прядильные органы","предмет жертвоприношение сатры","дар леди сатры"}},{q="Почему прядильные органы нужно поместить в фонтан?",a="Центральный фонтан Храма Луны в Дарнассе содержит святые воды, посвященные Элуне. Погружение останков Сатры в бассейн смывает мерзкую порчу, сводившую ее с ума, и освобождает ее дух от мучений.",al={"why temple fountain","why sacrifice sathrah","what does the fountain do","зачем фонтан храма","зачем приносить в жертву сатру","что делает фонтан"}},{q="Что происходит, когда дар преподнесен?",a="Когда дар помещен в священные воды, порча изгоняется, и появляется призрачный облик леди Сатры, безмятежно обходящей бассейн, что означает покой ее души.",al={"what happens at the fountain","spirit of sathrah appear","fountain event","что происходит у фонтана","появление духа сатры","событие у фонтана"}},{q="Кто руководит этим ритуалом?",a="Жрица А'моора, служительница Сестринства Элуны в Храме Луны, направляет искателей приключений упокоить создание и преподнести ее останки богине.",al={"who gives sathrahs sacrifice","priestess a'moora quest","who cleanses sathrah","кто выдает жертвоприношение сатры","задание жрицы а'моора","кто очищает сатру"}}},fp="19,300,31.580.0,28.222.0,50.227.0,44.178.1,25.182.0"}
P.entries["item:satyr-horns"] = {n="Рога сатира",s="Рога сатира — мрачные трофеи, добываемые с оскверненных сатиров, что наводнили древние чащи Ясеневого леса. Их ищут и скорбящие лесные жители, жаждущие возмездия, и предприимчивые торговцы из Кабестана; они служат неопровержимым доказательством того, что еще один слуга Пылающего Легиона пал.",h="Рога сатира — мрачные трофеи, добываемые с оскверненных сатиров, что наводнили древние чащи Ясеневого леса.",kw={"anilia","forest song","illiyana","night run","pixel","satyr horns","satyrnaar","splintertree post","xavian","анилия","лесная песнь","иллиана","ночная поляна","пиксель","рога сатира","сатирнаар","застава расщепленного дерева","ксавиан"},ang={["faction:Horde"]="Воины Орды, действующие с Заставы Расщепленного Дерева, истребляют мерзких сатиров, угрожающих лесозаготовкам, и при этом наживаются на гоблинских покупателях, едущих в Кабестан.",["race:NightElf"]="Для кальдораев добыча рогов сатиров — горький долг: так они очищают свой древний лес от сородичей, добровольно променявших наследие на демоническое рабство."},sec={{t="Трофеи мести и торговли",b="Завитые рога сатиров Ясеневого леса — яркий символ демонической скверны, пустившей корни в священном лесу. Для дриады Иллианы, уединившейся среди эльфийских руин Лесной Песни, сбор отрубленных рогов — дело скорби и мести за погибшую сестру Анилию. Но для приезжих торговцев, таких как странствующая гоблинша Пиксель, остановившаяся на Заставе Расщепленного Дерева, эти рога — настоящая возможность нажиться. Спрос на рога сатира в нейтральном порту Кабестан вырос, и мрачные останки убитых демонов превратились в выгодный товар для всякого, кто осмелится охотиться на их владельцев."},{t="Зачистка оскверненных логовищ",b="Рога сатира нельзя купить у обычных поставщиков: их приходится срезать прямо с тварей, прячущихся в темных уголках леса. Сатиры держат оплоты по всему Ясеневому лесу, самые известные из которых — оскверненные рощи Ксавиана, сумрачные лощины Сатирнаара и руины Ночной поляны. Зачистка этих логовищ избавляет землю от остатков демонической скверны и снабжает и скорбящих стражей, и жадных торговцев доказательствами истребления."}},faq={{q="Зачем Иллиане рога сатира?",a="Иллиане нужны рога сатира, чтобы отомстить за павшую сестру Анилию, убитую сатирами Ясеневого леса. Рога убитых демонов служат ей доказательством того, что их число сокращается, и приносят покой духу сестры.",al={"illiyana horns","anilia satyrs","forest song quest","иллиана рога","анилия сатиры","задание лесная песнь"}},{q="Зачем Пиксель собирает рога сатира?",a="Пиксель — предприимчивая путешественница, остановившаяся на Заставе Расщепленного Дерева по пути в Кабестан. Она узнала, что рога сатира высоко ценятся в гоблинском порту, и перед отъездом нанимает искателей приключений для опасной охоты вместо себя.",al={"pixel splintertree","why does pixel want horns","ratchet satyr horns","пиксель застава расщепленного дерева","зачем пикселю рога","рога сатира кабестан"}},{q="Где лучше всего искать сатиров с такими рогами?",a="Сатиры обитают в нескольких оскверненных местах Ясеневого леса. Крупные скопления находятся в Ксавиане и Сатирнааре на северо-востоке и на Ночной поляне в центре восточной части леса.",al={"satyr locations ashenvale","where are satyrs","satyr camps","сатиры ясеневый лес","где сатиры","лагеря сатиров"}},{q="Кто такие сатиры и почему у них рога?",a="Сатиры — древние ночные эльфы, превращенные в звероподобных демонических существ в результате демонических сделок, заключенных во время Войны Древних. Козлиные копыта, хвосты и злобные рога — физические приметы демонической скверны, дарованной Пылающим Легионом.",al={"what is a satyr","why do satyrs have horns","кто такие сатиры","почему у сатиров рога"}}},fp="11,308,34.595.0,30.461.0,35.245.0,36.240.0,58.180.0,44.256.0"}
P.entries["item:savannah-lion-tusk"] = {n="Клык равнинного льва",s="Клык равнинного льва — массивный клык хищных больших кошек, бродящих по засушливым равнинам Степей. Для путников это обычный охотничий трофей, но он служит необычным ингредиентом для легендарного крепкого эля Чэня Буйного Портера.",h="Клык равнинного льва — массивный клык хищных больших кошек, бродящих по засушливым равнинам Степей.",kw={"barrens","brewmaster drohn","chen stormstout","dishu","humar","ratchet","savannah lion tusk","степи","пивовар дрон","чэнь буйный портер","дишу","хумар","кабестан","клык равнинного льва"},ang={["class:Hunter"]="Охота на свирепые прайды в золотистых зарослях Степей — настоящее испытание для следопыта; она приносит опасные клыки, смертоносные в бою и ценные для местных пивоваров."},sec={{t="Необычный ингредиент для пива",b="Большие кошки Степей — от охотниц и сторожей до величественных прайдов под началом вожаков и таких зверей, как Хумар Повелитель Прайда, — вооружены острыми тяжелыми клыками. Большинство убивших этих хищников берут клыки как простое свидетельство доблести, но Пивовар Дрон в Кабестане ищет их для куда более крепкого ремесла. Дрон использует клыки вместе с почками степных бегунов и рогами громовых ящеров, чтобы воссоздать знаменитый эль Чэня Буйного Портера, дающий такой легендарный удар, что мало кто из смертных выдержит его."}},faq={{q="Зачем Пивовару Дрону клыки равнинного льва?",a="Пивовар Дрон в Кабестане воссоздает рецепт эля Чэня Буйного Портера, переданный ему наставником. Клыки — один из трех местных ингредиентов Степей, необходимых, чтобы повторить особый вкус и крепость этого эля.",al={"why tusks for beer","drohn lion tusks","brewmaster drohn recipe","зачем клыки для пива","дрон клыки льва","рецепт пивовара дрона"}},{q="У каких зверей можно добыть клыки равнинного льва?",a="Их можно добыть у любого члена прайда равнинных львов в Степях: у равнинных высокогривов, вожаков, матерей прайда, охотниц, сторожей и редких зверей, таких как Дишу и Хумар Повелитель Прайда.",al={"where do lion tusks drop","who drops lion tusk","savannah lion tusk source","где падают клыки льва","с кого падает клык льва","источник клыка равнинного льва"}},{q="Правда ли, что у львов есть клыки-бивни?",a="В суровых землях Калимдора огромные клыки равнинных больших кошек вырастают такими заметными и толстыми, что местные охотники и пограничники в разговоре называют их бивнями.",al={"why are lion teeth called tusks","lion tusks vs fangs","lion tusk anatomy","почему клыки львов зовут бивнями","бивни льва и клыки","строение клыка льва"}}},fp="18,251,28.529.0,51.251.0,39.212.0,29.185.0"}
P.entries["item:scaber-stalk"] = {n="Ножка струпника",s="Ножка струпника — редкие грибы, растущие в сырой уединенной пещере за Водопадом Скалистым на Темных берегах. Травники и алхимики ценят их необычные свойства, и их ищет Баритас Лунный Сумрак для своих зелий.",h="Ножка струпника — редкие грибы, растущие в сырой уединенной пещере за Водопадом Скалистым на Темных берегах.",kw={"auberdine","barithras moonshade","cave mushrooms","cliffspring falls","darkshore","death cap","scaber stalk","аубердин","баритас лунный сумрак","пещерные грибы","водопад скалистый","темные берега","мертвянка","ножка струпника"},ang={["profession:Herbalism"]="Хотя это не обычная торговая трава, подземные ножки показывают, как особый климат пещер и наступающая тьма меняют местную биологию грибов.",["race:NightElf"]="Прислушиваясь к предупреждениям Рощи Древних, ночные эльфы с большой осторожностью собирают эти пещерные грибы из-за гнетущего зла, поселившегося у Водопада Скалистого."},sec={{t="Редкий образец грибов",b="Ножки струпника — малоизвестные грибы, которые растут в глубине пещеры за Водопадом Скалистым, расположенным в северо-восточных горах Темных берегов. В отличие от обычной лесной флоры, эти бледные ножки растут только во влажной уединенной сети подземных пещер. Из-за отдаленного и опасного места произрастания собрать их крайне трудно, поэтому алхимики, такие как Баритас Лунный Сумрак в Аубердине, нанимают отважных разведчиков, готовых отправиться в темноту."},{t="Тень у водопада",b="Сбор ножек струпника куда опаснее обычного собирательства. Почтенные древесные духи Рощи Древних предупредили местных ночных эльфов, почувствовав, что в пещере Водопада Скалистого поселилось темное и растущее зло. Алхимики ценят ножки вместе с редкой мертвянкой для опытных настоев, но сборщики неизбежно сталкиваются с тем злом, что пустило корни под горами."}},faq={{q="Где растут ножки струпника?",a="Ножки струпника растут только в сырой пещере за Водопадом Скалистым, на северо-востоке Темных берегов, на горном хребте.",al={"scaber stalk location","where are scaber stalks","scaber stalk cave","где растет струпник","где ножка струпника","пещера струпника"}},{q="Кому нужны ножки струпника?",a="Баритас Лунный Сумрак, ученый ночной эльф из Аубердина, ищет ножки струпника вместе с мертвянкой, чтобы сварить особое зелье.",al={"who uses scaber stalk","barithras moonshade mushrooms","who needs scaber stalks","кому нужна ножка струпника","баритас лунный сумрак грибы","кто ищет струпник"}},{q="Почему Баритас Лунный Сумрак не собрал ножки сам?",a="Рощя Древних отговорила Баритаса от посещения пещеры: ее духи почувствовали, что за водопадом укрылось новое опасное зло.",al={"why not get them himself","barithras warning","cliffspring cave warning","почему не сам","предупреждение баритаса","предупреждение пещеры водопада"}},{q="Что еще растет рядом с ножками струпника?",a="В пещере также растет смертоносная мертвянка — еще один редкий образец, нужный Баритасу для алхимических исследований.",al={"other mushrooms in the cave","death cap and scaber stalk","cliffspring mushrooms","другие грибы в пещере","мертвянка и струпник","грибы водопада скалистого"}}},fp="12,247,22.463.0,21.462.1,28.147.0,24.136.0,58.155.0,40.128.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Чешуя Старого Мрачноглаза",s="Чешуя Старого Мрачноглаза снята с печально известного предводителя мурлоков, терроризирующего побережье Западного Края. Отделенная от шкуры твари, она служит неопровержимым доказательством его смерти для призрачного смотрителя Маяка в Западном Крае.",h="Чешуя Старого Мрачноглаза снята с печально известного предводителя мурлоков, терроризирующего побережье...",kw={"captain grayson","coastal menace","murloc","old murk-eye","scale of old murk-eye","westfall","westfall lighthouse","капитан грейсон","угроза побережью","мурлок","старый мрачноглаз","чешуя старого мрачноглаза","западный край","маяк в западном крае"},ang={["faction:Alliance"]="Для моряков Альянса, плывущих по Великому морю к водам Штормграда, расправа над Старым Мрачноглазом помогает сохранить огонь маяка в Западном Крае и уберечь будущие суда от крушения о скалы."},sec={{t="Трофей с бича побережья",b="Побережье Западного Края и так опасно из-за скрытых отмелей и непрерывных штормов, но Старый Мрачноглаз превратил навигационную угрозу в настоящую бойню. По словам капитана Грейсона, призрака, привязанного к Маяку в Западном Крае, этот мурлок обладал хитростью, невиданной среди его диких сородичей, и поднимал слабоумных мурлоков на набеги. Мрачноглаз прогнал семью смотрителя, и маяк был темен в ночь, когда корабль Грейсона разбился о скалы; когда семья вернулась, чтобы снова зажечь огонь, он напал снова и убил их. Чешуя этого существа — единственный способ удовлетворить мстительный дух и доказать, что берег очищен от самого свирепого хищника."}},faq={{q="Для чего нужна Чешуя Старого Мрачноглаза?",a="Чешуя служит доказательством смерти для капитана Грейсона, призрака, обитающего на скалистом острове с Маяком в Западном Крае. Грейсон мстит Старому Мрачноглазу за то, что маяк был темен в ночь крушения капитана, а позже мурлок убил семью смотрителя.",al={"who wants the scale","murk eye scale turn in","scale of old murk eye use","кому нужна чешуя","сдать чешую мрачноглаза","применение чешуи старого мрачноглаза"}},{q="Кто такой Старый Мрачноглаз?",a="Старый Мрачноглаз — печально известный жестокий и хитрый предводитель мурлоков, рыщущий по песчаным берегам Западного Края. В отличие от обычных мурлоков, он умеет организовывать и принуждать сородичей к согласованным смертоносным набегам на прибрежные заставы.",al={"who is murk eye","murk eye lore","old murk-eye","кто такой мрачноглаз","предание о мрачноглазе","старый мрачноглаз"}},{q="Почему Старый Мрачноглаз напал на маяк?",a="Сначала Старый Мрачноглаз напал на маяк, чтобы прогнать смотрителя с семьей и погрузить побережье во тьму. Когда смотрители вернулись, чтобы снова зажечь огонь, Мрачноглаз поднял сородичей на второй штурм, убил всю семью и оставил корабли слепыми перед коварными прибрежными отмелями.",al={"why attack lighthouse","lighthouse raid","murk eye lighthouse","зачем нападать на маяк","набег на маяк","мрачноглаз маяк"}}},fp="21,235,27.728.0,43.293.0,20.256.0,43.305.0"}
P.entries["item:scarlet-armband"] = {n="Алые поручи",s="Алые поручи — знаки отличия членов Алого ордена, обозначающие их фанатичную преданность истреблению всей нежити. В Могильнике Палач Аррен требует их как доказательство того, что молодые Отрекшиеся дали отпор фанатикам, вторгшимся на их земли.",h="Алые поручи — знаки отличия членов Алого ордена, обозначающие их фанатичную преданность истреблению всей...",kw={"deathknell","executor arren","scarlet armband","scarlet convert","scarlet crusade","scarlet initiate","tirisfal glades","могильник","палач аррен","алые поручи","алый новообращенный","алый орден","алый неофит","тирисфальские леса"},ang={["race:Undead"]="Для только что восставших Отрекшихся сбор этих поручей — мрачное знакомство с ненавистью мира живых, показывающее, что выжить можно лишь беспощадно обороняясь от Ордена."},sec={{t="Знак фанатизма",b="Алые поручи, которые носят на рукавах и алые неофиты, и новообращенные, — безошибочный знак Алого ордена. Для только что восставших Отрекшихся, выходящих из Могильника, эти полоски красной ткани — смертельная угроза у самого порога. Орден не делает различий между безвольными слугами Плети и свободными подданными Темной Госпожи: в его глазах любой ходячий мертвец должен быть предан огню. Палач Аррен использует сбор этих поручей как мрачный обряд посвящения: он подтверждает гибель вражеских разведчиков к юго-востоку от поселения и доказывает, что новые Отрекшиеся способны защитить свое молодое государство."}},faq={{q="Зачем Палачу Аррену Алые поручи?",a="Палачу Аррену нужны поручи как доказательство того, что лагерь вторгшегося Алого ордена к юго-востоку от Могильника истребляется. Орден представляет непосредственную смертельную угрозу для только что пробудившихся Отрекшихся, а сбор этих знаков гарантирует, что его передовые разведчики и новобранцы уничтожены.",al={"why collect armbands","arren armband quest","scarlet armband purpose","зачем собирать поручи","задание аррена поручи","назначение алых поручей"}},{q="Кто носит эти поручи?",a="Поручи носят члены Алого ордена низших рангов, расквартированные у Могильника: алые неофиты, алые новообращенные и их местный предводитель Мевен Коргал.",al={"who drops scarlet armbands","where to find armbands","с кого падают алые поручи","где найти поручи"}},{q="Почему Алый орден ненавидит Отрекшихся?",a="Движимый крайним фанатизмом, Алый орден отказывается видеть разницу между безвольной Плетью Короля-лича и свободными Отрекшимися. Они считают всю нежить мерзостью, которую необходимо истребить навсегда.",al={"why scarlet attack undead","crusade vs forsaken","scarlet zealots","почему алые нападают на нежить","орден против отрекшихся","алые фанатики"}},{q="Где находится лагерь, в котором можно найти эти поручи?",a="Лагерь расположен к юго-востоку от Могильника в Тирисфальских лесах, среди холмов за пределами поселения.",al={"scarlet camp location","deathknell scarlet camp","where are scarlet converts","лагерь алого ордена","лагерь алых у могильника","где алые новообращенные"}}},fp="15,281,21.661.0,46.309.0,25.183.0,47.222.0,52.125.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Бумаги Алого ордена",s="Эти перехваченные бумаги вез гонец Алого ордена, посланный из Монастыря Алого ордена в лагеря близ Могильника. В них содержатся приказы полевым командирам ордена в Тирисфальских лесах, и они дают Отрекшимся точные военные сведения, нужные, чтобы нанести удар по региональному руководству ордена.",h="Эти перехваченные бумаги вез гонец Алого ордена, посланный из Монастыря Алого ордена в лагеря близ Могильника.",kw={"brill","deathknell","executor arren","executor zygand","meven korgal","scarlet crusade documents","the red messenger","vital intelligence","брилл","могильник","палач аррен","палач зуганд","мевен коргал","бумаги алого ордена","красный гонец","важные сведения"},ang={["race:Undead"]="Доставка этих перехваченных бумаг означает, что пробужденный Отрекшийся перешел от испытаний на кладбище Могильника к большой войне, которой руководят из Брилла."},sec={{t="Перехваченные приказы",b="Гонец Мевен Коргал, отправленный прямо из Монастыря Алого ордена, вез эти бумаги в южный лагерь ордена близ Могильника. Распоряжения изданы по приказу Верховного лорда и адресованы капитанам Тирисфальского регионального командования ордена: капитан Перрин должен укрепить юго-западную башню и собрать сведения о нежити в Брилле, капитан Вакон — подавить передвижения нежити у северной башни, а капитан Мелроуз — следить за границами Чумных земель. Бумаги раскрывают имена, посты и приказы полевых офицеров Алого ордена в Тирисфальских лесах, и обычная доставка превращается для фанатиков в катастрофическую утечку сведений."},{t="Доставка в Брилл",b="Палач Аррен быстро понял, что силы Могильника не смогут использовать все эти сведения полностью. Захваченное досье служит пропуском для новопробужденного Отрекшегося из Могильника. Бумаги несут на северо-восток мимо Поместья «Остывший Очаг» в Брилл и передают прямо Палачу Зуганду у Ратуши Брилла. Имея эти приказы, военное руководство Отрекшихся планирует быстрые удары по командирам Алого ордена, засевшим в лесах."}},faq={{q="Кто вез эти бумаги?",a="Их вез Мевен Коргал, гонец Алого ордена, посланный из Монастыря Алого ордена в лагерь ордена к юго-востоку от Могильника.",al={"who dropped these","scarlet messenger","meven korgal","кто это уронил","гонец алого ордена","мевен коргал"}},{q="Какие сведения содержатся в бумагах?",a="В пачке лежат распоряжения по приказу Верховного лорда капитанам Тирисфальского регионального командования ордена: капитан Перрин должен укрепить юго-западную башню и разведать нежить в Брилле, капитан Вакон — разобраться с передвижениями нежити у северной башни, а капитан Мелроуз — следить за границами Чумных земель.",al={"what do the papers say","document contents","что написано в бумагах","содержание бумаг"}},{q="Кому нужно показать эти бумаги?",a="Их добывают для Палача Аррена в Могильнике, а затем поручают вам доставить Палачу Зуганду, который руководит региональными военными действиями у Ратуши Брилла.",al={"where do i take them","who do i give the documents to","куда их отнести","кому отдать бумаги"}},{q="Почему эти бумаги важны для Отрекшихся?",a="Захваченные приказы указывают расположение офицеров ордена в Тирисфальских лесах, что дает Отрекшимся преимущество, чтобы уничтожить вражеское руководство и сломить боевой дух фанатиков в регионе.",al={"why do forsaken want them","scarlet documents importance","зачем бумаги отрекшимся","важность бумаг алого ордена"}}},fp="25,328,18.718.0,17.502.0,33.150.0,41.325.0,33.178.0,50.191.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Перстень Алого ордена",s="Перстень Алого ордена — печатка, которую носят члены Алого ордена, расквартированные в Тирисфальских лесах. Для Отрекшихся защитников Брилла эти перстни — жуткое доказательство того, что еще одним фанатиком на земле Лордерона стало меньше.",h="Перстень Алого ордена — печатка, которую носят члены Алого ордена, расквартированные в Тирисфальских лесах.",kw={"brill","deathguard burgess","executor zygand","proof of demise","scarlet crusade","scarlet insignia ring","tirisfal glades","varimathras","брилл","страж смерти буржес","палач зуганд","доказательство гибели","алый орден","перстень алого ордена","тирисфальские леса","вариматрас"},ang={["faction:Horde"]="Сбор этих перстней помогает молодой Орде закрепиться в Восточных королевствах, ослабляя фанатиков, окруживших Подгород.",["race:Undead"]="Для Отрекшихся срывать эти перстни с рук мертвых бойцов ордена — прямое заявление, что Тирисфаль принадлежит мертвым, и исполнение приказов Темной Госпожи и Вариматраса."},sec={{t="Знаки фанатизма",b="Каждый боец Алого ордена в Тирисфальских лесах — от новичков и ревностных братьев до закаленных капитанов вроде Мелраш и Перрин — носит перстень. С огненным знаком ордена эти перстни отличают братьев и сестер в организации, одержимой паранойей. Но для чужаков и врагов эти безделушки значат совсем иное: это безошибочный признак самых фанатичных людей, оставшихся в Лордероне."},{t="Награда повелителя ужаса",b="По прямому поручению Вариматраса, повелителя ужаса и помощника леди Сильваны, Страж смерти Буржес в Брилле собирает эти перстни. Отрекшиеся считают Алый орден невыносимой заразой, расползшейся по их новой родине. Для новобранцев-Отрекшихся принести в Брилл стопки таких перстней — несомненное доказательство гибели врага и прямое подтверждение верности трону Подгорода."}},faq={{q="Кто носит эти перстни?",a="Почти каждый член Алого ордена в Тирисфальских лесах носит такой перстень. Это и рядовые бойцы — неофиты, миссионеры, фанатики и авангардисты, — и полевые офицеры, такие как капитан Перрин, капитан Мелраш и капитан Вакон.",al={"who drops rings","which crusaders have rings","ring owners","у кого есть перстни","какие храмовники носят перстни","владельцы перстней"}},{q="Почему Страж смерти Буржес хочет получить Перстни Алого ордена?",a="Страж смерти Буржес собирает перстни как вещественное доказательство того, что бойцов Алого ордена истребляют. Исполняя указы Вариматраса и Темной Госпожи, гарнизон Отрекшихся в Брилле использует перстни, чтобы оценить верность и эффективность новобранца в очистке Лордерона от людей.",al={"why collect rings","proof of demise reason","burgess rings","зачем собирать перстни","зачем доказательство гибели","перстни буржеса"}},{q="Что означает знак на перстне?",a="Перстень несет знак Алого ордена, символ их священной войны за истребление всякой нежити в Лордероне. Бойцы ордена носят его с яростной гордостью, считая знаком праведности, хотя одержимость толкает их убивать всякого, кто не принадлежит к ордену.",al={"scarlet symbol","what is the insignia","ring emblem","символ алого ордена","что за знак","эмблема перстня"}},{q="Какую роль играет Вариматрас в сборе этих перстней?",a="Вариматрас — главный помощник Сильваны Ветрокрылой в Подгороде. Он руководит стратегическими военными действиями по уничтожению враждебных живых людей в Тирисфальских лесах, и истребление Алого ордена — первоочередная задача для командиров Отрекшихся, таких как Палач Зуганд и Страж смерти Буржес.",al={"varimathras orders","why varimathras want rings","dreadlord involvement","приказы вариматраса","зачем вариматрасу перстни","участие повелителя ужаса"}}},fp="21,254,18.466.0,23.428.0,31.260.0,56.292.0,45.282.0,58.301.0"}
P.entries["item:scavenged-goods"] = {n="Ящики с добычей",s="Ящики с добычей — разрозненные предметы брошенного снаряжения и припасов, сложенные в ящики для снаряжения вокруг Могильника. Новопробужденные Отрекшиеся собирают их, чтобы бесконечный поток новобранцев можно было вооружить и одеть.",h="Ящики с добычей — разрозненные предметы брошенного снаряжения и припасов, сложенные в ящики для снаряжения...",kw={"deathguard saltain","deathknell","equipment boxes","forsaken supplies","scavenged goods","scavenging deathknell","страж смерти салтен","могильник","ящики для снаряжения","припасы отрекшихся","ящики с добычей","сбор добычи в могильнике"},ang={["race:Undead"]="Для Отрекшихся сбор брошенного снаряжения — необходимость для выживания, суровое напоминание о том, что живые не дадут им ни помощи, ни пощады."},sec={{t="Каждый сам за себя",b="Когда новые Отрекшиеся выбираются из земли на кладбище Могильника, у них почти нет ничего, кроме гнилых погребальных саванов. Окрестные поселения и королевства не помогают нежити, и она полностью зависит от того, что удастся найти. Страж смерти Салтен руководит сбором брошенного оружия, инструментов и одежды, сложенных в ящиках по всей деревне, и раздает их следующей партии восставших новобранцев."}},faq={{q="Для чего нужны ящики с добычей?",a="Страж смерти Салтен собирает их, чтобы снарядить новых новобранцев-Отрекшихся, встающих с кладбища. Без остатков из ближайших ящиков новопробужденной нежити пришлось бы брести в Тирисфальские леса совсем безоружной и раздетой.",al={"scavenged goods purpose","why collect scavenged goods","what does saltain do with scavenged goods","назначение ящиков с добычей","зачем собирать ящики с добычей","что салтен делает с добычей"}},{q="Где находят эти вещи?",a="Их достают из ящиков для снаряжения, стоящих у домов и среди разрушенных построек по всему Могильнику.",al={"where to find scavenged goods","scavenged goods location","where are equipment boxes","где найти ящики с добычей","местонахождение ящиков с добычей","где ящики для снаряжения"}},{q="Кто просит принести ящики с добычей?",a="Страж смерти Салтен, офицер в Могильнике, поручает новопробужденным Отрекшимся собрать эти припасы, чтобы научить их самостоятельности и подготовиться к новым поступлениям.",al={"who wants scavenged goods","deathguard saltain quest","кому нужны ящики с добычей","задание стража смерти салтена"}}},fp="15,225,22.454.0,34.236.0,28.111.0,33.178.0"}
P.entries["item:scavenger-paw"] = {n="Лапа падальщика",s="Лапы падальщиков — отрубленные конечности молодых оборванных волков, бродящих по холмам Могильника. Новопробужденные Отрекшиеся собирают их для местных целителей, которые сшивают из них грубое защитное снаряжение.",h="Лапы падальщиков — отрубленные конечности молодых оборванных волков, бродящих по холмам Могильника.",kw={"deathknell","novice elreth","ragged scavenger","scavenger paw","the damned","young scavenger","могильник","новобранец элрет","оборванный падальщик","лапа падальщика","проклятые","молодой падальщик"},ang={["profession:Tailoring"]="Грубая сборка из волчьих лап и крыльев летучих мышей, которую делает Новобранец Элрет, показывает, как импровизированное шитье поддерживает молодые поселения Отрекшихся.",["race:Undead"]="Пробуждаясь с разлагающейся плотью и почти без снаряжения, Отрекшиеся часто начинают со сбора частей местных хищников, чтобы собрать броню, способную выдержать опасности Тирисфаля."},sec={{t="Самодельная броня в Могильнике",b="Ресурсов у вернувшихся в Могильнике мало. Плеть и Алый орден давят на Тирисфаль, и каждый клочок шкуры и кости идет в дело. Новобранец Элрет, помощник жреца Тени Сарвиса, собирает лапы местных волков-падальщиков и крылья летучих мышей, чтобы шить одежду и броню для растерянных Отрекшихся, только что покинувших могилы."}},faq={{q="Для чего нужны лапы падальщиков?",a="Их собирает Новобранец Элрет в Могильнике: он делает из сырых частей животных простую броню и сшитую одежду для новых посвященных Отрекшихся.",al={"scavenger paw purpose","use for paws","why collect paws","назначение лап падальщика","зачем нужны лапы","зачем собирать лапы"}},{q="Где их найти?",a="Их берут с молодых и оборванных падальщиков — диких волков, бродящих по лесам и полям вокруг Могильника.",al={"paw drop location","where to get paws","which wolves drop paws","где достать лапы","откуда лапы","какие волки дают лапы"}},{q="Кто просит принести эти лапы?",a="Новобранец Элрет, который помогает жрецу Тени Сарвису: лечит раненых новобранцев, шьет снаряжение и снаряжает отправляемых в поле.",al={"who wants scavenger paws","paw quest giver","novice elreth paws","кому нужны лапы падальщика","задание на лапы","новобранец элрет лапы"}}},fp="13,213,27.397.0,33.148.0,23.144.0,24.140.0"}
P.entries["item:scorched-spider-fang"] = {n="Опаленный паучий клык",s="Опаленные паучьи клыки — особые материалы для ремесла, добываемые у хищных паукообразных из сырых пещер Болотины. Дворф-бронник Фьюрен Длиннобород требует много таких закаленных жаром клыков, чтобы выковать прочную закаленную огнем кольчугу для опытных воинов.",h="Опаленные паучьи клыки — особые материалы для ремесла, добываемые у хищных паукообразных из сырых пещер...",kw={"cave stalker","fire hardened mail","furen longbeard","leech stalker","scorched spider fang","stormwind","wetlands","пещерный сторож","закаленная огнем кольчуга","фьюрен длиннобород","сторож-пиявка","опаленный паучий клык","штормград","болотина"},ang={["class:Warrior"]="Сбор пятидесяти таких клыков — одно из тяжелых испытаний, назначаемых Фьюреном Длиннобородом, чтобы проверить вашу выносливость и добыть сырье для вашей особой кольчуги.",["profession:Blacksmithing"]="Метод Фьюрена, добавляющего опаленный хитин и клыки в звенья кольчуги, позволяет заглянуть в редкие дворфийские традиции бронного дела, выходящие далеко за рамки обычной плавки."},sec={{t="Формула дворфа-кузнеца",b="Чтобы выковать броню, способную отражать клинки и выдерживать сильные удары, нужно больше, чем обычное железо. В оживленном районе Штормграда искусный кузнец Фьюрен Длиннобород применяет малоизвестные приемы металлургии, сочетая части зверей с редкими реагентами. Фьюрен требует пятьдесят опаленных клыков гигантских паукообразных болот: их плотная, ядовитая и от природы прочная основа укрепляет звенья кольчуги при закалке."},{t="Stalkers of the Wetlands",b="These fangs are harvested directly from the lethal arachnids inhabiting the sunken valleys and burrows of the Wetlands, notably Cave Stalkers and Leech Stalkers. Despite the damp, rotting environment of the marsh, these predators possess peculiarly hardened, scorched mandibles. Gathering them in the quantities Furen demands requires venturing into deep hollows and clearing out entire swarms of monstrous vermin."}},faq={{q="Для чего нужны опаленные паучьи клыки?",a="Их собирают для Фьюрена Длиннобороду, бронника из Штормграда. Ему нужно пятьдесят штук, а также компоненты из Когтистых гор и Лабиринтов Иглошкурых, чтобы выковать исключительно прочный нагрудник для воинов Альянса.",al={"what do i do with scorched spider fangs","scorched spider fang purpose","who needs scorched spider fangs","что делать с опаленными паучьими клыками","назначение опаленного паучьего клыка","кому нужны опаленные паучьи клыки"}},{q="Где найти опаленные паучьи клыки?",a="Их берут у паукообразных Болотины, а именно у сторожей-пиявок и пещерных сторожей, прячущихся в сырых норах, на склонах холмов и в раскопочных пещерах региона.",al={"scorched spider fang drop location","which spiders drop scorched spider fang","where to farm scorched spider fangs","где падает опаленный паучий клык","какие пауки дают опаленный паучий клык","где добыть опаленные паучьи клыки"}},{q="Почему кузнецу нужно так много паучьих клыков для брони?",a="Фьюрен Длиннобород использует необычные дворфийские приемы ковки. Плотные от минералов, огнестойкие свойства этих клыков делают их нетрадиционным упрочняющим средством, укрепляющим звенья кольчуги при обработке вместе с флогистоном и рогами зверей.",al={"why 50 fangs","why does furen need spider fangs","почему 50 клыков","зачем фьюрену паучьи клыки"}},{q="Может ли любой искатель приключений собрать и сдать эти клыки?",a="Хотя любой путник в Болотине может убивать пауков и добывать их жвалы, Фьюрен Длиннобород поручает работу над изделием только начинающим воинам, стремящимся получить закаленную огнем кольчугу.",al={"is scorched spider fang warrior only","who can turn in scorched spider fangs","только ли воинам нужен опаленный паучий клык","кто может сдать опаленные паучьи клыки"}}},fp="20,292,25.454.0,24.414.0,40.225.0,39.175.0,62.250.0,51.211.0"}
P.entries["item:scroll-of-messaging"] = {n="Свиток с посланием",s="Свиток с посланием — зачарованный пергамент с особым заклинанием магической передачи. Его добывают для гнома-инженера Гаксима Ржавошиппи в Когтистых горах, и служит он необычной цели: дает магический запуск, нужный для подрыва взрывчатки на расстоянии.",h="Свиток с посланием — зачарованный пергамент с особым заклинанием магической передачи.",kw={"explosives","gaxim rustfizzle","ng-5","remote detonator","scroll of messaging","stonetalon","venture co","взрывчатка","гаксим ржавошиппи","дистанционный детонатор","свиток с посланием","когтистые горы","торговая компания"},ang={["faction:Alliance"]="Свиток играет важную роль: он помогает агентам Альянса саботировать технику Торговой Компании и остановить разрушение природы в Когтистых горах.",["profession:Engineering"]="Свиток, достойный гномьей изобретательности, показывает, как теоретическую тайную магию можно превратить в дистанционный приемник для механических подрывных устройств."},sec={{t="Взрывоопасное послание",b="Хотя на вид это тайное письмо для связи на расстоянии, Гаксим Ржавошиппи задумал для свитка с посланием куда более разрушительное применение. Соединив его заклинание передачи с нестабильными зарядами NG-5, гном собирается создать взрывное устройство с дистанционной детонацией. Взрыв должен вызвать сильный переполох на лесозаготовках Торговой Компании в Когтистых горах, и у агентов появится возможность проскользнуть мимо стражи и похитить секретные чертежи и конфиденциальную переписку."}},faq={{q="Для чего нужен Свиток с посланием?",a="Хотя свиток написан как заклинание для передачи сообщений, Гаксим Ржавошиппи использует его магию передачи, чтобы сделать дистанционный запал. В сочетании со взрывчаткой NG-5 он позволяет ему устроить взрыв с безопасного расстояния.",al={"scroll of messaging use","what does scroll of messaging do","why gaxim wants scroll","для чего свиток с посланием","что делает свиток с посланием","зачем гаксиму свиток"}},{q="Кому предназначен этот свиток?",a="Свиток доставляют Гаксиму Ржавошиппи, лояльному Альянсу гному-инженеру, который действует в Когтистых горах.",al={"who gets scroll of messaging","where do i bring scroll of messaging","scroll recipient","кому отдать свиток с посланием","куда нести свиток с посланием","получатель свитка"}},{q="Зачем Гаксиму дистанционная взрывчатка?",a="Гаксиму нужно отвлечь внимание на местных предприятиях Торговой Компании. Возникшая суматоха позволит проникнуть на их территорию, украсть ценные инженерные чертежи и забрать документы, чтобы остановить их хищническую вырубку леса.",al={"gaxim explosive reason","why blow up venture co","stonetalon distraction","зачем гаксиму взрывчатка","зачем взрывать торговую компанию","отвлечение в когтистых горах"}},{q="Что такое NG-5?",a="NG-5 — взрывчатый химический заряд, которым пользуется Гаксим Ржавошиппи. В сочетании с магическим сигналом, начертанным на свитке с посланием, он образует самодельное устройство дистанционного подрыва.",al={"ng-5","what is ng-5","ng5 explosive","что такое ng-5","взрывчатка ng-5"}}},fp="19,268,18.543.0,41.200.0,25.118.0,39.244.0,13.186.0"}
P.entries["item:sea-creature-bones"] = {n="Кости морской твари",s="Кости морской твари — скелетные образцы с огромных морских туш, которые выбрасывает на берег окутанного туманом побережья Темных берегов. Их отправляют прямо в Храм Луны в Дарнассе, и они играют ключевую роль в расследовании того, что заставляет этих огромных зверей выбрасываться на пляжи.",h="Кости морской твари — скелетные образцы с огромных морских туш, которые выбрасывает на берег окутанного...",kw={"auberdine","beached sea creature","darkshore","greymist murlocs","gwennyth bly'leggonde","mist's edge","sea creature bones","temple of the moon","аубердин","выброшенная морская тварь","темные берега","мурлоки серой мглы","гвеннид блай'леггонд","туманный предел","кости морской твари","храм луны"},ang={["class:Druid"]="Необъяснимая гибель древних морских хищников говорит о глубоком неблагополучии в водах у берегов Калимдора и тревожит любого стража, призванного хранить равновесие природы.",["race:NightElf"]="Внезапные массовые выбросы на Темных берегах глубоко тревожат ночных эльфов, которые чтят гармонию природного мира и видят в них мрачное предзнаменование, требующее внимания Храма Луны."},sec={{t="Знамение на берегу",b="На окутанных туманом пляжах Темных берегов в последнее время наблюдается тревожный рост числа огромных морских существ, в том числе гигантских молотильщиков, намного крупнее местных обитателей мелководья. Они выбрасываются на мелководье, пока не погибнут. Ночные эльфы видят в этом зловещее знамение. Гвеннид Блай'Леггонд, следователь, отправленная Храмом Луны в Аубердин, собирает образцы костей этих выброшенных левиафанов и отправляет их на гиппогрифе в Дарнасс для тщательного изучения."},{t="Падаль и падальщики",b="Добывать эти кости опасно, ведь огромные туши неизбежно привлекают местных падальщиков. Мурлоки Серой Мглы на побережье часто собираются вокруг мертвых и умирающих левиафанов, питаются остатками и яростно защищают места кормежки. Хотя мурлоки слишком слабы, чтобы охотиться на таких гигантов в одиночку, их присутствие у Туманного Предела вынуждает следователей и искателей приключений пробиваться сквозь стаи падальщиков, чтобы добыть пригодные для изучения фрагменты костей."}},faq={{q="Почему эти существа выбрасываются на берег?",a="Точная причина неизвестна. Единичные случаи выбрасывания — естественное явление, но их внезапный и резкий рост жрицы Элуны считают неестественным и тревожным, поэтому они начали официальное расследование.",al={"why are threshers beaching","darkshore dead whales","why do creatures strand darkshore","почему молотильщики выбрасываются","мертвые киты темные берега","почему существа выбрасываются на темных берегах"}},{q="Кому нужны эти кости?",a="Гвеннид Блай'Леггонд, следователь, расквартированная в Аубердине, собирает кости для Храма Луны в Дарнассе, где ученые и жрицы надеются выяснить, что тревожит море.",al={"who takes the bones","who turns in sea creature bones","gwennyth darkshore","кто принимает кости","кому сдать кости морской твари","гвеннид темные берега"}},{q="Это мурлоки убили этих огромных зверей?",a="Нет. Местные мурлоки Серой Мглы слишком слабы, чтобы одолеть морских зверей такого размера. Они лишь падальщики, которые собираются толпами и питаются тушами, когда те оказываются на берегу.",al={"did murlocs kill the thresher","greymist murlocs killed sea monster","мурлоки убили молотильщика","мурлоки серой мглы убили морского монстра"}},{q="Откуда берут эти кости?",a="Их достают прямо из огромных туш, выброшенных на берег Темных берегов, особенно на песках к югу от Аубердина и у Туманного Предела.",al={"where to find sea creature bones","beached sea creature locations","где найти кости морской твари","где лежат выброшенные морские твари"}}},fp="18,328,22.507.0,22.505.0,39.221.0,22.208.0,40.195.0,35.165.0"}
P.entries["item:sea-turtle-remains"] = {n="Останки морской черепахи",s="Останки морской черепахи — скелетные образцы, добытые из туш гигантских морских черепах на побережье Темных берегов. Они служат важными образцами для исследователей-ночных эльфов в Аубердине, изучающих тревожный рост числа выбросов морских существ.",h="Останки морской черепахи — скелетные образцы, добытые из туш гигантских морских черепах на побережье Темных...",kw={"auberdine","beached sea turtle","darkshore","gwennyth bly'leggonde","sea turtle remains","teldrassil","temple of the moon","washed ashore","аубердин","выброшенная морская черепаха","темные берега","гвеннид блай'леггонд","останки морской черепахи","тельдрассил","храм луны","выброшено на берег"},ang={["class:Druid"]="Неестественная гибель диких морских левиафанов говорит о более глубокой порче, нарушающей равновесие природы на побережье Калимдора.",["race:NightElf"]="Массовые выбросы морских обитателей у берегов вашей родины — зловещий знак, особенно потому, что подозрения падают на воды вокруг Тельдрассила."},sec={{t="Тревожный выброс",b="Гигантские морские существа начали выбрасываться на берега Темных берегов, окутанные туманом, а другие лежат под водой недалеко от берега, у затонувших обломков. Гвеннид Блай'Леггонд, расквартированная в Аубердине, руководит сбором фрагментов скелетов и тканей этих туш. Храм Луны в Дарнассе срочно требует эти образцы: есть предположения, что звери бегут от неестественного возмущения в водах вокруг недавно выросшего мирового древа Тельдрассил."},{t="Падальщики мелководья",b="Добывать эти останки опасно. Прибрежные племена мурлоков обычно собираются вокруг огромных туш, обгладывают кости дочиста и устраивают рядом гнезда. Ученым нужны свежие фрагменты костей и ткани, пока падальщики не уничтожили уцелевшие улики, способные объяснить роковую миграцию этих существ."}},faq={{q="Для чего нужны эти останки?",a="Останки собирает Гвеннид Блай'Леггонд в Аубердине. Она готовит их для ученых и жриц Храма Луны в Дарнассе, которые пытаются выяснить, почему вдоль Темных берегов гибнет так много морских созданий.",al={"why collect turtle remains","turtle bones use","sea turtle quest darkshore","зачем собирать останки черепах","кости черепах для чего","задание про морскую черепаху темные берега"}},{q="Почему морские черепахи выбрасываются на берег на Темных берегах?",a="Точная причина еще выясняется, но исследователи опасаются, что морские обитатели бегут от чего-то тревожного в водах вокруг Тельдрассила. Выбросы — не единичные случаи, что указывает на повсеместное неблагополучие в природе.",al={"why are turtles dying","turtle strandings darkshore","beached sea creatures","почему гибнут черепахи","выбросы черепах темные берега","выброшенные морские твари"}},{q="Где находят эти туши?",a="Скелеты гигантских морских черепах разбросаны вдоль побережья Темных берегов: одни лежат на мелководье у затонувших кораблей к западу от Аубердина, другие — на пляжах среди лагерей мурлоков.",al={"turtle remains locations","where to find skeletal sea turtle","где останки черепах","где найти скелет морской черепахи"}},{q="Кто изучает эти останки?",a="Гвеннид Блай'Леггонд, исследовательница в Аубердине, собирает находки и отправляет подробные отчеты прямо Сестринству Элуны в Храме Луны в Дарнассе.",al={"who wants the remains","gwennyth blyleggonde","кому нужны останки","гвеннид блай'леггонд"}}},fp="18,241,19.497.0,26.321.0,32.236.0,53.229.0,32.204.0,30.176.0"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Запечатанное описание посетителя Тредда",s="Запечатанное описание посетителя Тредда — конфиденциальный отчет Тюремщика Телвотера о загадочном человеке, который навещал заключенного главаря Братства Справедливости Базиля Тредда в Тюрьме Штормграда. Его содержание помогает выследить тайного агента, незаметно действующего в политических и преступных кругах Штормграда.",h="Запечатанное описание посетителя Тредда — конфиденциальный отчет Тюремщика Телвотера о загадочном человеке...",kw={"baros alexston","bazil thredd","maelik","mathias shaw","sealed description","stockade","warden thelwater","барос алекстон","базиль тредд","маелик","матиас шоу","запечатанное описание","тюрьма","тюремщик телвотер"},ang={["class:Rogue"]="Это досье — прямой урок оперативной работы: ложные имена, поддельные документы и визиты в камеры раскрываются, когда Матиас Шоу сверяет внешние описания с данными разведки ШРУ.",["faction:Alliance"]="Документ выявляет тревожные бреши во внутренней безопасности Штормграда: он доказывает, что заговорщики могут спокойно пройти через ворота Тюрьмы Штормграда по поддельным документам."},sec={{t="Загадочный покровитель",b="Годами в Тюрьме заключенный Базиль Тредд сидел в камере без посетителей. Все изменилось, когда молчаливый человек начал приходить раз или два в неделю с вполне действительными документами. Заметив эти необычные визиты, Тюремщик Телвотер составил письменное описание этого человека, у которого были документы на имя «Маелик». Тюремщик запечатал описание, чтобы никто посторонний не прочел его до того, как за дело возьмутся настоящие следователи."},{t="От каменщиков к шпионам",b="Когда описание показали городскому архитектору Баросу Алекстону, он никого не узнал, но слабо заподозрил, что посетитель может быть агентом, связанным с мятежом Братства Справедливости. Алекстон быстро переслал запечатанный конверт Мастеру Матиасу Шоу, главе разведывательной службы Штормграда, ШРУ. Шоу сразу раскусил обман: описание подходило смертоносному наемнику, который действует под разными прозвищами, в том числе Марзон, и сейчас выполняет грязную работу для лорда Грегора Лесковара."}},faq={{q="Кто написал это описание?",a="Тюремщик Телвотер, начальник тюремщиков Тюрьмы Штормграда, написал и запечатал документ. Он стал подозрительным, когда неизвестный начал регулярно навещать заключенного главаря Братства Справедливости Базиля Тредда.",al={"who wrote it","author of description","who penned the note","кто написал","автор описания","кто составил записку"}},{q="Кто посетитель, описанный в бумаге?",a="Он предъявил документы на имя Маелика. Тюремщик Телвотер записал его внешность, чтобы следователи смогли установить его личность.",al={"who was visiting thredd","who is maelik","visitor identity","кто навещал тредда","кто такой маелик","личность посетителя"}},{q="Зачем посетитель встречался с Базилем Треддом?",a="Телвотер насторожился, когда к Тредду начали приходить регулярно после многих лет без посетителей. Цель визитов выясняют с помощью запечатанного описания.",al={"why visit thredd","thredd visitor purpose","зачем навещать тредда","цель визитов к тредду"}},{q="Куда нужно отнести этот запечатанный документ?",a="Сначала документ приносят городскому архитектору Баросу Алекстону в Штормграде. Осмотрев его и не узнав описанного человека, Алекстон велит вам доставить его прямо Мастеру Матиасу Шоу в штаб-квартиру ШРУ в Старом городе.",al={"where do i bring it","who wants the description","куда его отнести","кому нужно описание"}}},fp="38,322,19.481.0,25.494.1,27.212.0,42.130.2,46.163.2,49.244.1"}
P.entries["item:sealed-envelope"] = {n="Запечатанный конверт",s="В этом плотно запечатанном пакете лежат конфиденциальные технические документы Торговой Компании и украденные чертежи. Их собрал изгнанный инженер-гоблин Физзикс; это закрытые разработки, предназначенные для передачи Пароклапану в Кабестане.",h="В этом плотно запечатанном пакете лежат конфиденциальные технические документы Торговой Компании и украденные...",kw={"blueprints","fizziks","ratchet","sealed envelope","sputtervalve","stonetalon","super reaper 6000","venture company","чертежи","физзикс","кабестан","запечатанный конверт","пароклапан","когтистые горы","супер-дровосек 6000","торговая компания"},ang={["faction:Horde"]="Доставка этих бумаг на юг из Когтистых гор помогает нейтральным гоблинам Кабестана подорвать агрессивную, хищническую лесозаготовительную деятельность Торговой Компании.",["profession:Engineering"]="В конверте лежат технические чертежи Супер-дровосека 6000 — одного из самых разрушительных и прибыльных механических устройств, созданных руками гоблинов."},sec={{t="Корпоративный шпионаж",b="Когда инженера-гоблина Физзикса внезапно выставили из лесозаготовительных предприятий Торговой Компании в Когтистых горах, он ушел не с пустыми руками. Сложив в этот конверт внутренние руководства, рабочие инструкции и технические спецификации, он сумел вынести секреты компании из-под носа прежних надсмотрщиков. Самое ценное среди украденных бумаг — технические чертежи Супер-дровосека 6000, разрушительной промышленной машины для сплошной вырубки леса."},{t="Доставка в Кабестан",b="Вместо того чтобы похоронить опасные торговые секреты, Физзикс отправляет пакет на юг, к Пароклапану — инженеру, живущему в нейтральном гоблинском порту Кабестан. Хотя соперники по бизнесу из Картеля Хитрая Шестеренка не питают к Физзиксу ни симпатии, ни доверия, инженерная ценность чертежей в конверте неоспорима. Документы дают ясное представление о механическом гении Торговой Компании и позволяют независимым инженерам воспользоваться передовыми технологиями вырубки леса, которыми располагает картель."}},faq={{q="Что внутри предмета «Запечатанный конверт»?",a="В конверте лежат внутренние документы Торговой Компании, технические руководства по эксплуатации и чертежи лесозаготовительной машины «Супер-дровосек 6000». Все это Физзикс прихватил при поспешном уходе.",al={"envelope contents","what is in sealed envelope","sealed envelope items","содержимое конверта","что в запечатанном конверте","предметы запечатанного конверта"}},{q="Кто подготовил этот пакет?",a="Конверт подготовил Физзикс, обиженный инженер-гоблин, которого Торговая Компания выставила со своего лесозаготовительного предприятия в Когтистых горах.",al={"who made the envelope","who gave sealed envelope","fizziks envelope","кто сделал конверт","кто дал запечатанный конверт","конверт физзикса"}},{q="Кому он предназначен?",a="Он адресован Пароклапану, гоблину-изобретателю, живущему в портовом городке Кабестан в Степях.",al={"who gets the envelope","where does envelope go","sputtervalve delivery","кто получает конверт","куда нести конверт","доставка пароклапану"}},{q="Зачем Пароклапану эти документы?",a="Хотя Пароклапан недолюбливает Торговую Компанию и с опаской относится к Физзиксу, в документах есть ценные усовершенствования и чертежи, позволяющие сторонним изобретателям понять и перенять мощные механические разработки компании.",al={"why sputtervalve wants it","venture company tech ratchet","зачем пароклапану конверт","технологии торговой компании кабестан"}}},fp="15,232,19.494.0,19.506.0,35.206.0,25.165.0,30.107.0,43.227.0"}
P.entries["item:sealed-note-to-elling"] = {n="Запечатанная записка Эллингу",s="Запечатанная записка Эллингу — конфиденциальное послание, написанное штормградским рыбаком Йоргеном. Она предназначена для Иллинга Триаса, владельца сырной лавки «Сыры Триаса», и служит одним из первых звеньев негласного расследования исчезновения дипломата.",h="Запечатанная записка Эллингу — конфиденциальное послание, написанное штормградским рыбаком Йоргеном.",kw={"elling trias","jorgen","sealed note to elling","stormwind","the missing diplomat","trade district","trias cheese","иллинг триас","йорген","запечатанная записка эллингу","штормград","пропавший дипломат","торговый квартал","сыры триаса"},ang={["class:Rogue"]="Разбойники, знакомые с теневыми сетями Штормграда, знают, что Иллинг Триас — далеко не просто торговец сыром, и потому такая скрытная переписка их не удивляет: это обычный прием тайной работы.",["faction:Alliance"]="Доставить послание Йоргена — значит напрямую послужить Короне и продвинуть расследование, важное для политической стабильности Штормграда."},sec={{t="Тихая передача",b="Нести запечатанную записку по оживленным улицам Штормграда может показаться делом будничным, но строгие указания Йоргена ясно дают понять, что поставлено на кон: вручить пергамент лично Иллингу Триасу и молчать. Хотя внешне Триас — тихий торговец сыром из Торгового квартала, это тайное послание направляет расследование исчезновения дипломата прямо к его прилавку, намекая на сети куда глубже молочной торговли."}},faq={{q="Что написано в запечатанной записке?",a="Записка остается запечатанной, пока ее не вручат Иллингу Триасу. В ней — донесение Йоргена и рекомендация, направляющая посыльного к Триасу для более глубокого расследования исчезновения дипломата.",al={"note contents","what does the note say","letter text","содержимое записки","что сказано в записке","текст письма"}},{q="Почему торговец сыром получает секретные сведения?",a="Иллинг Триас держит скромную сырную лавку в Торговом квартале как прикрытие. Под фартуком у Триаса скрывается обширная подпольная сеть глаз и ушей по всему городу, что делает его незаменимым помощником в деликатных расследованиях.",al={"why elling trias","why cheese shop","is trias a spy","почему иллинг триас","почему сырная лавка","триас шпион"}},{q="Кто такой Йорген?",a="Йорген — рыбак, которого можно найти у воды в штормградской Аллее Героев. Его что-то связывает с Иллингом Триасом и епископом Делавеем, и епископ обращается к нему по деликатным делам, скрытым от посторонних глаз.",al={"who wrote the note","jorgen lore","watchman jorgen","кто написал записку","йорген предания","дозорный йорген"}},{q="О чем дело о пропавшем дипломате?",a="Дипломат из Штормграда, отправленный в Терамор на встречу с Джайной Праудмур, так и не прибыл, а королевские власти тихо проверяют каждый подозрительный след, не вызывая паники на улицах.",al={"missing diplomat lore","who is the diplomat","why missing diplomat","пропавший дипломат","кто дипломат","почему пропал дипломат"}}},fp="21,244,16.451.0,39.188.0,53.251.0,14.221.0,40.191.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Запечатанная записка дозорному Бакусу",s="Запечатанная записка дозорному Бакусу — конфиденциальное послание, написанное опытным торговцем сырами и осведомителем Иллингом Триасом. Она адресована бойцу Ночного Дозора, патрулирующему дорогу у Темнолесья, и содержит личную просьбу собрать сведения о деятельности Братства Справедливости в Сумеречном лесу.",h="Запечатанная записка дозорному Бакусу — конфиденциальное послание, написанное опытным торговцем сырами и...",kw={"darkshire","duskwood","elling trias","night watch","sealed note","the missing diplomat","watcher backus","темнолесье","сумеречный лес","иллинг триас","ночной дозор","запечатанная записка","пропавший дипломат","дозорный бакус"},ang={["class:Rogue"]="То, что Триас использует обычного стража как местного осведомителя, — образцовый пример тихого сбора сведений далеко за городскими стенами.",["faction:Alliance"]="Это послание показывает, как неформальная разведка и личные связи удерживают истрепанные земли Альянса, когда официальные каналы подводят."},sec={{t="Слово для Дозора",b="Когда первые зацепки по пропавшему дипломату в Штормграде иссякают, торговец сыром Иллинг Триас решает обойти упрямого осведомителя Йоргена и задействовать собственную тайную сеть. Он пишет это скрепленное сургучом послание дозорному Бакусу, стражу Ночного Дозора в Сумеречном лесу. Триас отправляет искателя приключений на юг через мрачный лес, чтобы тот вручил записку лично: давнее доверие Бакуса должно помочь получить любые сведения о Братстве Справедливости, бродящем близ Темнолесья."},{t="Дальнозоркие глаза Триаса",b="Хотя Триас на вид всего лишь торговец, продающий тонкие сорта сыра в Торговом квартале, его переписка со стражем из Сумеречного леса показывает, насколько широка его разведывательная сеть. Ночной Дозор Темнолесья известен замкнутостью и недоверием к чужакам: он выживает под постоянной угрозой нежити и свирепых зверей. И все же радушный прием, который Бакус оказал записке Триаса, доказывает, что кажущийся скромным лавочник пользуется подлинной преданностью и уважением далеко за стенами Штормграда."}},faq={{q="Кто написал эту записку?",a="Записку написал Иллинг Триас, владелец сырной лавки «Сыры Триаса» в Торговом квартале Штормграда, втайне работающий умелым шпионом и торговцем информацией.",al={"who wrote sealed note to watcher backus","author of note","who gives note","кто написал записку дозорному бакусу","автор записки","кто дает записку"}},{q="Почему ее отправляют дозорному Бакусу?",a="Дозорный Бакус служит в Ночном Дозоре Темнолесья и является доверенным лицом Иллинга Триаса. Триасу нужно, чтобы он поделился любыми местными наблюдениями и слухами о деятельности Братства Справедливости в окрестностях Сумеречного леса.",al={"who is watcher backus","why send to backus","what is backus role","кто такой дозорный бакус","зачем отправлять бакусу","роль бакуса"}},{q="Где найти дозорного Бакуса?",a="Дозорный Бакус патрулирует дорогу, ведущую на север от Темнолесья в Сумеречном лесу, и следит за лесными подступами к городку.",al={"where is backus","watcher backus location","find watcher backus","где бакус","где найти дозорного бакуса","местонахождение бакуса"}},{q="Что происходит после доставки записки?",a="Узнав имя Триаса и доверяя ему, Бакус отбрасывает обычную настороженность к странствующим искателям приключений и соглашается помочь в расследовании подозрительной деятельности в окрестных лесах.",al={"what does backus say","after delivering note","что говорит бакус","после доставки записки"}}},fp="29,286,20.471.0,25.489.1,20.167.0,39.203.0,34.140.0,41.187.0"}
P.entries["item:searing-collar"] = {n="Обжигающий ошейник",s="Обжигающие ошейники — ритуальные гривны, которые носят члены культа Пылающего Клинка, скрывающиеся в Скале Черепа в Дуротаре. Их раскаляют так, что они прожигают плоть владельца, и культисты используют их, чтобы настроиться на демонические силы.",h="Обжигающие ошейники — ритуальные гривны, которые носят члены культа Пылающего Клинка, скрывающиеся в Скале...",kw={"burning blade","demon","durotar","fel","margoz","searing collar","skull rock","пылающий клинок","демон","дуротар","скверна","маргоз","обжигающий ошейник","скала черепа"},ang={["class:Warlock"]="Чернокнижники видят в Обжигающих ошейниках грубые, но действенные проводники, направляющие скверну прямо в смертную плоть.",["race:Orc"]="Для орков, стремящихся освободить свой народ от наследия демонического рабства, обнаружить культистов с такими ошейниками на пороге Дуротара — мрачное напоминание о том, что тень все еще не рассеялась."},sec={{t="Орудия порчи",b="В сумрачной пещере Скалы Черепа к востоку от Оргриммара собирается Пылающий Клинок для темных ритуалов. Культисты, неофиты и головорезы культа надевают Обжигающие ошейники на шею, добровольно подвергая себя палящему жару, который клеймит и опаляет кожу. Отшельник Маргоз изучает эти жестокие приспособления и полагает, что ощущение жжения и темные чары, заключенные в металле, напрямую настраивают носителей на демоническую энергию. Исследование ошейников показывает, что они — значительный проводник демонической порчи, расползающейся в орочьем обществе прямо под носом у Орды."}},faq={{q="Что такое Обжигающий ошейник?",a="Обжигающий ошейник — ритуальный обруч, который носят на шее культисты Пылающего Клинка. Он прожигает плоть владельца и направляет демоническую энергию, настраивая культиста на темную магию.",al={"what are searing collars","searing collar lore","what does the collar do","что такое обжигающие ошейники","предания об обжигающем ошейнике","что делает ошейник"}},{q="Кто носит эти ошейники?",a="Их носят члены культа Пылающего Клинка, скрывающиеся в Скале Черепа, в том числе культисты, фанатики, головорезы, ученики и неофиты.",al={"who uses them","who drops searing collars","burning blade collars","кто носит их","с кого падают обжигающие ошейники","ошейники пылающего клинка"}},{q="Зачем культисты жгут собственную плоть?",a="Пылающий Клинок использует раскаленный металл как ритуальное средство. Терпя ожоги и демонические чары, культисты настраивают свои тела и души на демоническую силу.",al={"why burn their flesh","why wear searing collar","purpose of collar","зачем жечь плоть","зачем носить обжигающий ошейник","назначение ошейника"}},{q="Кто хочет осмотреть Обжигающие ошейники?",a="Маргоз, следователь, разбивший лагерь в Дуротаре, собирает ошейники, чтобы изучить их чары и раскрыть тайны темного влияния Пылающего Клинка.",al={"who needs searing collars","who is studying the collars","margoz collars","кому нужны обжигающие ошейники","кто изучает ошейники","маргоз ошейники"}}},fp="14,216,25.614.0,25.179.0,24.141.0,41.175.0,41.159.0"}
P.entries["item:searing-coral"] = {n="Тлеющий коралл",s="Тлеющий коралл — редкое прочное минеральное вещество, которое добывают из живых железных кораллов у побережья Болотины. Механики и кузнецы ценят его за удивительные тепловые свойства: его можно плавить и ковать в защитные доспехи.",h="Тлеющий коралл — редкое прочное минеральное вещество, которое добывают из живых железных кораллов у побережья...",kw={"furen longbeard","iron coral","ironforge","klockmort spannerspan","menethil harbor","searing coral","warrior armor","wetlands","фьюрен длиннобород","железный коралл","стальгорн","клацморт гайкокрут","гавань менетилов","тлеющий коралл","доспехи воина","болотина"},ang={["class:Warrior"]="Сбор Тлеющего коралла — важный шаг к тому, чтобы доказать свою преданность мастерам-оружейникам Стальгорна; в награду вы получите нагрудник, выкованный на заказ и рассчитанный на тяжелые бои на передовой.",["profession:Blacksmithing"]="Использование Тлеющего коралла показывает изобретательное слияние гномьей смекалки и классической дворфийской обработки металла: океанские минералы превращаются в закаленные латы."},sec={{t="Редкий прибрежный ресурс",b="Тлеющий коралл растет только в холодных океанских водах вдоль побережья к югу от Гавани Менетилов в Болотине. Хотя этот необычный морской организм процветает в холодной соленой воде, он дает богатый минералами материал, способный выдерживать сильный жар. Сборщики рискуют, пробираясь через коварный прибой Болотины и мимо прибрежных хищников, чтобы отломать затвердевшие наросты."},{t="Применение в кузнечном деле",b="Хотя Тлеющий коралл традиционно не входит в обычную дворфийскую металлургию, он привлек внимание пытливых умов Стальгорна. Мастера-гномы, такие как Клацморт Гайкокрут, перенимают приемы опытного оружейника Фьюрена Длинноборода: плавят и куют коралл прямо в металлические сплавы, получая легкие и исключительно прочные доспехи для начинающих воинов."}},faq={{q="Где растет Тлеющий коралл?",a="Тлеющий коралл добывают со дна вдоль береговой линии к югу от Гавани Менетилов в Болотине. Он растет в естественных зарослях железного коралла под мелкой прибрежной водой.",al={"searing coral location","where to find searing coral","iron coral location","где растет тлеющий коралл","где найти тлеющий коралл","железный коралл"}},{q="Кому в Стальгорне нужен Тлеющий коралл?",a="Тлеющий коралл ищет Клацморт Гайкокрут, гном-изобретатель из Города механиков в Стальгорне. Он применяет его в опытах с приемами ковки, которым научился у легендарного дворфийского оружейника Фьюрена Длинноборода.",al={"who uses searing coral","klockmort spannerspan coral","furen longbeard coral","кто использует тлеющий коралл","клацморт гайкокрут коралл","фьюрен длиннобород коралл"}},{q="Как можно выковать доспехи из коралла?",a="Тлеющий коралл обладает необычайно плотной, жаростойкой структурой. Если расплавить его в горне и выковать в металлические сплавы, он усиливает составную броню, и получается исключительно прочное защитное снаряжение.",al={"coral forging","can you smelt coral","searing coral metallurgy","ковка коралла","можно ли плавить коралл","металлургия тлеющего коралла"}},{q="Опасно ли добывать Тлеющий коралл?",a="Сам коралл безопасно собирать, когда он найден, но для этого нужно плыть по открытой воде у побережья Болотины, где бродят дикие мурлоки и агрессивные водные звери.",al={"is searing coral hot","harvesting iron coral","горячий ли тлеющий коралл","добыча железного коралла"}}},fp="13,254,23.353.0,23.367.0,30.193.0,37.206.0,35.213.0,38.188.0"}
P.entries["item:secure-crate"] = {n="Надежный ящик",s="Надежный ящик — плотно упакованная посылка с зельями, алхимическими реагентами и прочими товарами, предназначенными для Восточных королевств. Ее доверяют путникам в Степях, и ее нужно доставить в оживленный порт Кабестан к отливу.",h="Надежный ящик — плотно упакованная посылка с зельями, алхимическими реагентами и прочими товарами...",kw={"barrens","blackwater cove","potions","ratchet","reagents","secure crate","shipping","wharfmaster dizzywig","степи","бухта черноводья","зелья","кабестан","реагенты","надежный ящик","доставка","управляющий пристанью головокружилкинс"},ang={["faction:Horde"]="Доставка грузов через Кабестан напоминает путникам из Орды о важных нейтральных торговых связях, которые гоблинские порты обеспечивают между Калимдором и Восточными королевствами.",["profession:Herbalism"]="Надежная упаковка реагентов показывает, насколько алхимики и травники по обе стороны моря зависят от пограничных торговых путей для обмена сырьем."},sec={{t="Груз курьера",b="Торговые пути между Калимдором и Восточными королевствами держатся на хрупкой цепочке курьеров, караванов через пустыни и гоблинских торговых судов. Когда сухопутные караваны в Степях пропускают назначенный срок отправления, хрупкие грузы вроде этого надежного ящика приходится доставлять на побережье независимым путникам. Внутри лежат алхимические товары, зелья и различные реагенты для партнеров за Великим морем. Из-за хрупкого и ценного содержимого ящик надежно запечатан, чтобы он выдержал и засушливые тропы Степей, и соленые брызги морского пути."},{t="Через порт Кабестан",b="Наземный отрезок пути ящика заканчивается на причале Кабестана, которым заведует Управляющий пристанью Головокружилкинс. Гавань Кабестана — главный нейтральный пункт, через который припасы отправляются за море, например в Бухту Черноводья. Работая по учетным книгам Картеля Хитрая Шестеренка, Головокружилкинс следит, чтобы и мелкие посылки, и тяжелые грузы были должным образом внесены в декларацию и погружены на ближайший отходящий корабль, обеспечивая важную торговую связь между Старым Светом и пограничьем."}},faq={{q="Что находится в надежном ящике?",a="В ящике лежит хрупкий набор зелий, алхимических реагентов и прочих припасов, предназначенных для партнеров в Восточных королевствах.",al={"crate contents","what is in the crate","secure crate items","содержимое ящика","что в ящике","вещи в надежном ящике"}},{q="Куда отправляют ящик?",a="Пешком его нужно доставить Управляющему пристанью Головокружилкинсу на причалы Кабестана. Оттуда Головокружилкинс записывает его на торговый корабль, плывущий через море в Бухту Черноводья в Старом Свете.",al={"crate destination","where does secure crate go","куда отправляют ящик","пункт назначения ящика","куда идет надежный ящик"}},{q="Почему ящик доверили искателю приключений, а не каравану?",a="У отправителя не хватило времени самому добраться до Кабестана, а назначенный торговый караван уже ушел, поэтому понадобился нанятый курьер, чтобы успеть к отливу.",al={"why do i have the crate","missed caravan","почему у меня ящик","пропущенный караван"}},{q="Кто принимает ящик в Кабестане?",a="Управляющий пристанью Головокружилкинс принимает ящик на причалах Кабестана, записывает его в свой судовой гроссбух и грузит на ближайший корабль, уходящий с приливом.",al={"who gets the crate","dizzywig crate","кто получает ящик","головокружилкинс ящик"}}},fp="12,268,17.595.0,27.488.0,32.138.0,30.191.0,62.176.0,31.159.0"}
P.entries["item:senir-s-report"] = {n="Донесение Сенира",s="Донесение Сенира — отправленный документ, написанный горным пехотинцем Сениром Белобородом об угрозе троллей Мерзлогривов в Дун Мороге. В нем изложены выводы, полученные по королевскому поручению, и он предназначен для сенатора Борина Краснокамня в Стальгорне.",h="Донесение Сенира — отправленный документ, написанный горным пехотинцем Сениром Белобородом об угрозе троллей...",kw={"barin redstone","frostmane","ironforge","magni bronzebeard","senate","senir whitebeard","senir's report","the reports","борин краснокамень","мерзлогрив","стальгорн","магни бронзобород","сенат","сенир белобород","донесение сенира","донесения"},ang={["faction:Alliance"]="Доставка Донесения Сенира помогает обороне Дун Морога и позволяет разобраться в непростой внутренней политике правящего класса Стальгорна.",["race:Dwarf"]="Доставка Донесения Сенира показывает резкий политический раскол между королевскими указами короля Магни Бронзоборода и традиционной властью, которой требует сенат Стальгорна."},sec={{t="Королевское поручение",b="Этот полевой отчет составлен после разведывательных вылазок против троллей Мерзлогривов, обосновавшихся в скалах Дун Морога, и содержит наблюдения горного пехотинца, предназначенные для сената дворфов. Сенир Белобород, стоявший в холодных предгорьях, написал документ и приложил отчет своего брата Грелина о Холодной долине, где сказано, что Грелин действовал с разрешения короля Магни Бронзоборода. Сенир поручает искателям приключений доставить сведения прямо сенатору Борину Краснокамню на Высокий трон Стальгорна, осторожно советуя курьерам умолчать о том, сколько посторонней помощи ему потребовалось."},{t="Разногласия на Высоком троне",b="По доставке королевскому двору документ тут же вызывает переполох. Читая отчет Белоборода, сенатор Борин Краснокамень возмущен не только содержанием сведений об угрозе троллей, но и исполнительной властью, стоящей за ним. То, что Магни обходит надзор законодательной власти, а Белобород действует по неконтролируемым королевским приказам, разжигает давнее недовольство в сенате дворфов и показывает политическое напряжение между решительным правлением короля Магни и возмущенными сенаторами, требующими процедурного контроля."}},faq={{q="Что такое Донесение Сенира?",a="Это официальное письменное донесение горного пехотинца Сенира Белоборода с итогами его расследований о троллях Мерзлогривах в Дун Мороге, которое нужно доставить напрямую сенату дворфов в Стальгорне.",al={"senirs report","what is this report","the report","донесение сенира","что это за донесение","донесение"}},{q="Кому должно быть передано донесение?",a="Донесение адресовано сенатору Борину Краснокамню, угрюмому дворфийскому политику, который находится возле трона короля Магни Бронзоборода на Высоком троне Стальгорна.",al={"who gets the report","who do i give the report to","report recipient","кто получает донесение","кому отдать донесение","получатель донесения"}},{q="Почему сенатор Краснокамень так злится, прочитав его?",a="Сенатор Краснокамень в ярости, потому что приложенный отчет брата Сенира, Грелина Белоборода, показывает, что Грелин действовал по полномочию короля Магни, а не советовался с сенатом дворфов. Краснокамень возмущен тем, что корона в вопросах обороны действует в одиночку, без одобрения сената.",al={"why is barin mad","why is the senator angry","redstone reaction","почему борин зол","почему сенатор в гневе","реакция краснокамня"}},{q="Почему Сенир просит вас не упоминать о помощи ему?",a="Сенир Белобород предпочитает, чтобы начальство считало, что он выполнил опасную разведку в заснеженных холмах полностью сам, желая сберечь репутацию старательного и умелого горного пехотинца.",al={"why keep quiet","senir secret","senir credit","почему молчать","тайна сенира","заслуга сенира"}}},fp="14,242,17.601.0,25.516.1,23.216.0,38.153.0,56.296.1,50.201.0"}
P.entries["item:serena-s-head"] = {n="Голова Серены",s="Голова Серены — жуткий трофей, снятый с предводительницы гарпий Сухих холмов на севере Степей. Дарсок Быстрый Нож с Перекрестка потребовал ее как доказательство гибели гарпии, намереваясь выставить ее на повозках снабжения Орды как суровое средство устрашения против новых налетов с воздуха.",h="Голова Серены — жуткий трофей, снятый с предводительницы гарпий Сухих холмов на севере Степей.",kw={"crossroads","darsok swiftdagger","dry hills","harpy","rexxar","serena bloodfeather","serena's head","witchwing","перекресток","дарсок быстрый нож","сухие холмы","гарпия","рексар","серена кровавое перо","голова серены","зачарованное крыло"},ang={["class:Rogue"]="Дарсок Быстрый Нож ценит чистую, безжалостную работу и хвалит наемников, способных подкрасться к вражескому насесту и без колебаний убить цель.",["faction:Horde"]="Караваны — это жизненная артерия, связывающая Дуротар с Мулгором и дальними форпостами; голова Серены на повозках снабжения ясно заявляет о господстве Орды над дикими пустошами."},sec={{t="Предупреждение на дороге",b="Гарпии Зачарованного Крыла из Сухих холмов давно досаждали торговле на севере Степей, но при Серене Кровавое Перо их нападения стали особенно жестокими. Ее набеги на линии снабжения Орды были местью за сестру, павшую от руки укротителя зверей Рексара. Чтобы окончательно сломить боевой дух стаи, орк-разбойник Дарсок Быстрый Нож приказал выследить Серену. Он не хотел, чтобы ее смерть прошла незамеченной, и потребовал ее отрубленную голову, чтобы закрепить на следующем уходящем караване — как суровое кровавое предупреждение любой гарпии, наблюдающей со скал."}},faq={{q="Зачем Дарсоку Быстрому Ножу голова Серены?",a="Дарсоку нужно неоспоримое доказательство смерти Серены Кровавое Перо, и он собирается закрепить ее голову на караване снабжения Орды. Он надеется, что вид останков предводительницы устрашит уцелевших гарпий Зачарованного Крыла и отобьет у них охоту нападать на путников.",al={"why take serenas head","darsok serena head","what does darsok do with the head","зачем голова серены","дарсок голова серены","что дарсок сделает с головой"}},{q="Почему Серена Кровавое Перо нападала на караваны Орды?",a="Нападениями Серены двигала кровная месть Орде. Ее сестра, Кровавое Перо, была убита чемпионом мок'наталь Рексаром, и Серена мстила, нападая на линии снабжения Орды и путников по всем Степям.",al={"why did serena attack caravans","serena bloodfeather motive","harpy attacks barrens","почему серена нападала на караваны","мотив серены кровавое перо","нападения гарпий степи"}},{q="Откуда взялся этот трофей?",a="Он отсечен от Серены Кровавое Перо, предводительницы, гнездящейся среди скал Сухих холмов на дальнем северо-западе Степей.",al={"where to find serena's head","serena bloodfeather location","how to get serenas head","где найти голову серены","где серена кровавое перо","как получить голову серены"}}},fp="13,282,21.609.0,47.263.0,53.228.0,33.145.0"}
P.entries["item:serpentbloom"] = {n="Змеецвет",s="Змеецвет — редкая подземная трава, растущая только в темных глубинах Пещер Стенаний. Ее мощные природные свойства вызвали живой интерес Королевского фармацевтического общества Отрекшихся.",h="Змеецвет — редкая подземная трава, растущая только в темных глубинах Пещер Стенаний.",kw={"apothecary zamah","barrens","herb","royal apothecary society","serpentbloom","thunder bluff","wailing caverns","аптекарь зама","степи","трава","королевское фармацевтическое общество","змеецвет","громовой утес","пещеры стенаний"},ang={["profession:Herbalism"]="Обученные травники обладают острым глазом, необходимым, чтобы найти эти редкие пещерные цветы там, где другие видят лишь влажный камень.",["race:Undead"]="Добыча змеецвета напрямую помогает аптекарю Заме и Королевскому фармацевтическому обществу в поисках ботанических ресурсов в чужих землях для укрепления Отрекшихся."},sec={{t="Редкое подземное растение",b="Змеецвет растет только во влажных темных туннелях Пещер Стенаний под Степями. Он укоренился в экосистеме, искаженной необузданной энергией Изумрудного Сна, процветает вдали от солнца, и среди его стеблей нередко гнездятся ядовитые змеи. Поскольку система пещер кишит враждебными тварями и испорченными друидами, лишь немногие, кто туда входит, возвращаются с годными образцами."},{t="Интерес аптекарей",b="Аптекарь Зама, работающая в Прудах Видений под Громовым Утесом, собирает змеецвет по поручению Королевского фармацевтического общества Подгорода. Отрекшиеся постоянно ищут по всему Калимдору ядовитые, странные и химически активные растения для исследований во имя Темной Госпожи. Зама считает, что сбор змеецвета в больших количествах может привести к ценным открытиям в алхимии Отрекшихся."}},faq={{q="Где растет змеецвет?",a="Змеецвет встречается только в глубине Пещер Стенаний — лабиринта пещер к юго-западу от Перекрестка в Степях. Он стелется по земле в темных влажных уголках пещеры.",al={"where to find serpentbloom","serpentbloom location","wailing caverns herb","где найти змеецвет","местонахождение змеецвета","трава пещер стенаний"}},{q="Зачем Королевскому фармацевтическому обществу змеецвет?",a="Аптекарь Зама, представительница Королевского фармацевтического общества в Громовом Утесе, ищет это растение для исследований. Отрекшиеся изучают необычную и опасную флору со всего Калимдора, чтобы создавать новые химические составы и поддерживать более широкие цели Сильваны Ветрокрылой.",al={"who wants serpentbloom","apothecary zamah herb","why collect serpentbloom","кому нужен змеецвет","аптекарь зама трава","зачем собирать змеецвет"}},{q="Чем опасен сбор змеецвета?",a="Помимо общих опасностей Пещер Стенаний, где кишат ящеры, кроколиски и испорченные друиды, само растение часто укрывает ядовитых змей. Потревожив его, можно спровоцировать скрытых змей на укус.",al={"serpentbloom danger","serpentbloom snake","опасность змеецвета","змея в змеецвете"}},{q="Могут ли травники находить змеецвет легче?",a="Да. Обученные травничеству от природы настроены замечать растительность и способны отслеживать заросли змеецвета в темных уголках пещерного пола.",al={"find serpentbloom herbalism","tracking serpentbloom","найти змеецвет травничество","отслеживание змеецвета"}}},fp="12,206,25.409.0,19.424.0,29.205.0,56.276.0,41.232.0,45.164.0"}
P.entries["item:sethir-s-journal"] = {n="Записи Сетира",s="Записи Сетира — личный дневник, который носит неуловимый сатир Сетир Древний в Тельдрассиле. Добытые скрытно, они подтверждают тревожное распространение порчи с материка Калимдора на Мировое Древо.",h="Записи Сетира — личный дневник, который носит неуловимый сатир Сетир Древний в Тельдрассиле.",kw={"darkshore","destiny calls","oracle glade","satyr","sethir the ancient","sethir's journal","syurna","teldrassil","темные берега","зов судьбы","поляна оракула","сатир","сетир древний","записи сетира","сиарна","тельдрассил"},ang={["class:Rogue"]="Добыча дневника доказывает, что скрытное проникновение и кража могут раскрыть важные сведения там, где полностью потерпели неудачу воины на передовой и дипломаты.",["race:NightElf"]="Дневник дает тревожные доказательства того, что Тельдрассил не защищен от древней демонической порчи, расползающейся по материку Калимдора."},sec={{t="Ключ к разгадке порчи",b="Тельдрассил был выращен в надежде вернуть эльфийское бессмертие, но невидимая болезнь все глубже пускает корни в его ветвях. Сиарна в Дарнассе подозревала, что ответы знает Сетир Древний, одинокий сатир, обитающий на дальней ветви возле Поляны Оракула. Когда прямые переговоры и открытая сила привели лишь к гибели прежних разведчиков, записи Сетира удалось добыть тихой кражей. Они открывают мрачную правду: таинственная порча, отравляющая леса и воды за морем, на Темных берегах, перекинулась на сам Тельдрассил."}},faq={{q="Что такое Записи Сетира?",a="Это дневник, который носит Сетир Древний, враждебный сатир, живущий на внешних ветвях возле Поляны Оракула в Тельдрассиле. В нем есть заметки о распространяющейся порче, поражающей этот край.",al={"what is sethirs journal","sethir journal lore","who owns sethirs journal","что такое записи сетира","дневник сетира предания","чей дневник сетира"}},{q="Как получить дневник?",a="Поскольку прежние попытки договориться с Сетиром или сразиться с ним закончились неудачей и гибелью, дневник нужно стащить прямо из его сумок, действуя скрытно.",al={"how do i get sethirs journal","where to get sethir journal","pickpocket sethir","как получить записи сетира","где взять дневник сетира","обокрасть сетира"}},{q="О чем говорит дневник?",a="По словам наставницы разбойников Сиарны, дневник доказывает, что странная болезнь, поражающая леса и воды Темных берегов, проникла в Тельдрассил.",al={"what does sethir journal say","what is in sethir journal","что говорится в дневнике сетира","что в дневнике сетира"}},{q="Кто такой Сетир Древний?",a="Сетир — одинокий сатир, гнездящийся на уединенной ветви на окраине Поляны Оракула. Он известен жестокой расправой над чужаками и владеет важными сведениями о подкрадывающейся порче Мирового Древа.",al={"who is sethir","sethir the ancient","кто такой сетир","сетир древний"}}},fp="16,226,19.554.1,25.205.0,28.154.0,29.169.0,26.217.0"}
P.entries["item:sevren-s-orders"] = {n="Приказы Севрена",s="Приказы Севрена — письменные донесения, написанные мировым судьей Севреном из Брилла. Они предписывают опытному агенту Отрекшихся явиться к Бетору Ледострелу, могущественному магу в Магическом квартале Подгорода.",h="Приказы Севрена — письменные донесения, написанные мировым судьей Севреном из Брилла.",kw={"bethor iceshard","brill","magic quarter","magistrate sevren","prodigal lich","sevren's orders","undercity","бетор ледострел","брилл","магический квартал","мировой судья севрен","блудный лич","приказы севрена","подгород"},ang={["class:Mage"]="Для чародеев доставка этих приказов означает встречу с Бетором Ледострелом, одним из ведущих заклинателей королевства Отрекшихся.",["race:Undead"]="Печать Севрена отмечает переход агента от местной службы в Тирисфале к прямой помощи магической элите Подгорода."},sec={{t="Вызов в столицу",b="Пока Отрекшиеся укрепляют власть над руинами Лордерона, умелых агентов, проявивших себя в борьбе с Плетью в Тирисфальских лесах, вызывают на юг, в столицу. Эти письменные приказы, выданные мировым судьей Севреном, служат официальной рекомендацией и удостоверением для Бетора Ледострела, одного из ведущих чародеев Темной Госпожи в Магическом квартале. Хотя Севрен знает немногое, кроме того, что задание связано с поиском заблудшего лича, вызов несет абсолютную власть верховных магов Подгорода."}},faq={{q="Кто написал эти приказы?",a="Приказы составил мировой судья Севрен, надзиратель Отрекшихся, управляющий делами города Брилл в Тирисфальских лесах.",al={"author of sevren's orders","who is sevren","who gives sevrens orders","автор приказов севрена","кто такой севрен","кто выдает приказы севрена"}},{q="Кому предназначены эти приказы?",a="Они адресованы Бетору Ледострелу, высокопоставленному магу Отрекшихся в Магическом квартале Подгорода.",al={"who gets the orders","where do i bring sevren's orders","who is bethor iceshard","кто получает приказы","куда нести приказы севрена","кто такой бетор ледострел"}},{q="О каком задании говорится в приказах?",a="Задание состоит в том, чтобы привлечь на сторону Отрекшихся заблудшего лича. Это опасное дело, требующее агента, уже проявившего себя в борьбе с Плетью.",al={"what is the lich mission","what does bethor want","prodigal lich mission","задание про лича","чего хочет бетор","задание блудный лич"}},{q="Почему доставить их выбрали меня?",a="Бетор запросил агента, проявившего себя в борьбе с Плетью. Мировой судья Севрен счел, что ваших дел в Тирисфальских лесах достаточно для опасного задания Бетора.",al={"why me","why did sevren pick me","почему я","почему севрен выбрал меня"}}},fp="15,204,22.555.0,23.127.0,40.114.0,44.154.0,33.174.0"}
P.entries["item:shadowhide-pendant"] = {n="Подвеска Темношкуров",s="Подвески Темношкуров — грубые украшения-обереги гноллов Темношкуров, обитающих в Красногорье. Их собирают как законное доказательство исполнения награды: они означают, что местные защитники привели в исполнение закон Приозерья против гноллов, сотрудничающих с отступником-магом Моргантом.",h="Подвески Темношкуров — грубые украшения-обереги гноллов Темношкуров, обитающих в Красногорье.",kw={"bailiff conacher","gnoll","lakeshire","lieutenant fangore","morganth","pendant","redridge","shadowhide","solomon's law","помощник судьи конах","гнолл","приозерье","лейтенант фангор","моргант","подвеска","красногорье","темношкуры","закон соломона"},ang={["class:Warrior"]="Гноллы Темношкуры — агрессивные и физически мощные противники, ряды которых испытывают защитников переднего края, охраняющих дороги в Приозерье.",["faction:Alliance"]="Пограничные поселения вроде Приозерья получают скудную помощь от гарнизона Штормграда, и местным судьям приходится полагаться на верных Альянсу искателей приключений для соблюдения законов королевства."},sec={{t="Знаки неповиновения",b="Воины, громилы и заклинатели клана Темношкуров носят эти подвески как грубые личные тотемы или знаки отличия. В глубине холмов Красногорья клан сплотился под началом лейтенанта Фангора и подпал под влияние Морганта, мага-отступника, владеющего тайной магией. Для жителей Приозерья эти обереги — не просто примитивные украшения, а знаки организованной угрозы, нападающей на поселения региона по воле врага Короны."},{t="Правосудие Приозерья",b="По власти мирового судьи Соломона и законам Штормграда, за прямое пособничество известному преступнику королевства полагается смертная казнь. Не имея достаточной королевской поддержки, помощник судьи Конах в Ратуше Приозерья полагается на независимых искателей приключений в охране мира. Десять подвесок Темношкуров — осязаемое доказательство того, что гноллы, подчинявшиеся приказам Морганта, понесли пограничное правосудие."}},faq={{q="Что такое подвеска Темношкуров?",a="Это оберег, который носят гноллы клана Темношкуров в Красногорье. Местный судья принимает их как доказательство того, что вторгшиеся гноллы убиты при защите поселения.",al={"what are shadowhide pendants","shadowhide pendant lore","redridge pendant","что такое подвески темношкуров","подвеска темношкуров предание","подвеска красногорья"}},{q="Зачем помощнику судьи Конах эти подвески?",a="Помощник судьи Конах собирает их как доказательство исполнения награды по Закону Соломона. Поскольку клан Темношкуров сотрудничает с мятежным чародеем Моргантом, терроризируя местных жителей, город считает каждого гнолла из этого клана врагом, которому грозит смертная казнь.",al={"why collect pendants","bailiff conacher bounty","conacher quest","зачем собирать подвески","награда помощника судьи конах","задание конах"}},{q="Кто носит эти подвески?",a="Их носят все в иерархии клана Темношкуров — от обычных разбойников, громил и бешеных гноллов до таких фигур, как Рох Безмолвный и лейтенант Фангор в дебрях Красногорья.",al={"who drops pendants","which gnolls have pendants","shadowhide pendant source","кто роняет подвески","у каких гноллов есть подвески","где взять подвеску темношкуров"}},{q="Какова связь между кланом Темношкуров и Моргантом?",a="Моргант, маг-отступник, владеющий тайной магией и скрывающийся в восточных предгорьях, зловещими силами подчинил гноллов Темношкуров своей воле и использует их как пехоту, чтобы терроризировать Приозерье и осуществлять свои замыслы.",al={"gnolls and morganth","why are gnolls working with morganth","shadowhide morganth","гноллы и моргант","почему гноллы служат морганту","темношкуры моргант"}}},fp="18,282,18.485.0,19.409.0,29.196.0,46.276.0,27.193.0,66.230.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Шаманский оберег Вуду",s="Шаманский оберег Вуду — темный ритуальный амулет, который носят шаманы фурболгов Седой Сосны в глубине Обители Бен'этиль. Источая мерзкую ауру, оберег направляет неестественную магию, способную отделить дух спящего друида от его плоти.",h="Шаманский оберег Вуду — темный ритуальный амулет, который носят шаманы фурболгов Седой Сосны в глубине...",kw={"ban'ethil barrow den","emerald dream","furbolg","gnarlpine","oben rageclaw","shaman voodoo charm","sleeping druid","teldrassil","обитель бен'этиль","изумрудный сон","фурболг","седая сосна","обен яростный коготь","шаманский оберег вуду","спящий друид","тельдрассил"},ang={["class:Druid"]="Для друида оберег — ужасающее извращение священного сна: темная магия запирает спящего в Изумрудном Сне, а его телом управляют как марионеткой.",["race:NightElf"]="Находка этих оберегов в Обители Бен'этиль показывает, насколько глубоко племя Седой Сосны осквернило одно из самых священных общинных мест упокоения кальдораев."},sec={{t="Извращенная магия",b="Племя Седой Сосны в Тельдрассиле впало в безумие и порчу, но в Обители Бен'этиль их шаманы владеют силами, далеко превосходящими обычное колдовство дикой природы. С помощью этих странных оберегов Вуду шаманы нашли способ вырывать сознание спящего друида из мира смертных и беспомощно запирать его изнутри Изумрудного Сна. Отделяя душу от оболочки, фурболги оживляют пустое тело, превращая почтенных защитников-ночных эльфов в безвольных стражей, убивающих любого, кто забредет в курганы."},{t="Разгадать проклятие",b="Когда друид Обен Яростный Коготь стал жертвой этого ритуала, его дух оказался в ловушке Сна, а оживленное тело терроризировало глубины курганов. Обратившись сквозь завесу, Обен поручил искателям приключений убить шаманов Седой Сосны и добыть один из их оберегов Вуду. Изучив мерзкие чары амулета, Обен надеялся разгадать извращенное мастерство фурболгов и найти способ разорвать путы на своей украденной плоти."}},faq={{q="Для чего нужен Шаманский оберег Вуду?",a="Шаманы Седой Сосны используют оберег для мощного ритуала, отделяющего дух спящего друида от тела: разум оказывается в ловушке Изумрудного Сна, а пустая плоть оживает и нападает на незваных гостей.",al={"voodoo charm purpose","what does the charm do","shaman charm use","назначение оберега вуду","что делает оберег","использование шаманского оберега"}},{q="Кто носит эти обереги?",a="Обереги носят шаманы Седой Сосны, обитающие в извилистых глубинах Обители Бен'этиль в Тельдрассиле.",al={"who drops the charm","where to find shaman voodoo charm","gnarlpine shaman charm","кто роняет оберег","где найти шаманский оберег вуду","оберег шамана седой сосны"}},{q="Зачем Обену Яростному Когтю нужен оберег?",a="Обен Яростный Коготь сейчас заперт в Изумрудном Сне, а его оживленное тело неистовствует. Ему нужно изучить мерзкую ауру и магическое плетение оберега, чтобы понять, как разрушить чары фурболгов.",al={"why does oben want it","oben rageclaw charm","the sleeping druid item","зачем обену оберег","обен яростный коготь оберег","предмет спящего друида"}},{q="Откуда у фурболгов магия Вуду?",a="Хотя традиционные шаманы фурболгов почитают духов природы и стихии, порча, охватившая Тельдрассил, толкнула племя Седой Сосны к темной, извращенной магии. Оберег обладает неестественной, мерзкой аурой, совсем не похожей на традиционное поклонение природе.",al={"why do furbolgs use voodoo","furbolg voodoo lore","почему фурболги используют вуду","предание о вуду фурболгов"}}},fp="19,260,17.570.0,20.458.1,41.215.0,25.117.0,32.213.0,34.254.0"}
P.entries["item:shard-of-water"] = {n="Осколок Воды",s="Осколок Воды — стихийный осколок, собираемый во время общения шамана с духами воды. Доставленный Ислен Заклинательнице Воды на побережье Степей, он служит осязаемым доказательством того, что посвящаемый постиг животворную природу воды и победил ее порчу.",h="Осколок Воды — стихийный осколок, собираемый во время общения шамана с духами воды.",kw={"barrens","call of water","islen waterseer","shard of water","silverpine","water totem","степи","зов воды","ислен заклинатель воды","осколок воды","серебряный бор","тотем воды"},ang={["class:Shaman"]="Получение этого осколка — последний шаг в настройке на духов воды, завершающий долгий путь к обретению вашего Тотема воды."},sec={{t="Знак стихийной чистоты",b="Шаманам, стремящимся к власти над стихиями, общение с водой требует глубокого понимания равновесия, жизни и сохранения. В испытаниях Зова Воды шаманов направляют бороться с порчей, просочившейся в природные источники, — даже за море, в оскверненные земли вроде Серебряного бора. Осколок Воды вручается после очищения этих оскверненных вод. Вернув этот кристальный знак Ислен Заклинательнице Воды на скалистых берегах Степей, посвящаемый доказывает свою доблесть и получает последний ключ для создания Тотема воды."}},faq={{q="Для чего нужен Осколок Воды?",a="Он служит доказательством вашего испытания для Ислен Заклинательницы Воды на восточном берегу Степей. Передав ей осколок, вы завершаете общение с водой и получаете свой Тотем воды.",al={"shard of water purpose","what does shard of water do","why do i have shard of water","назначение осколка воды","что делает осколок воды","почему у меня осколок воды"}},{q="Кому нужен этот предмет?",a="Ислен Заклинатель Воды, шаманка, живущая в хижине к югу от Кабестана на Торговом побережье, просит осколок, чтобы убедиться, что вы успешно очистили оскверненную воду.",al={"who wants shard of water","where to turn in shard of water","islen waterseer shard","кто хочет осколок воды","куда сдать осколок воды","ислен заклинатель воды осколок"}},{q="Почему испытание назначено так далеко, как Серебряный бор?",a="Вода олицетворяет исцеление и сохранение, а порча останавливает жизнь. Оскверненные воды Серебряного бора — суровое испытание способности шамана восстановить стихийную гармонию среди глубокого разложения.",al={"silverpine water quest","why silverpine forest","shaman silverpine","задание воды серебряного бора","почему серебряный бор","шаман серебряный бор"}}},fp="14,277,25.555.0,36.188.0,23.157.0,48.194.0"}
P.entries["item:shaw-s-report"] = {n="Донесение Шоу",s="Донесение Шоу — секретное послание мастера Матиаса Шоу из ШРУ для Гриана Камнегрива в Западном Крае. В нем изложены сведения разведки о Гильдии каменщиков, ее предводителе Эдвине ван Клифе и их обиде на корону после восстановления Штормграда.",h="Донесение Шоу — секретное послание мастера Матиаса Шоу из ШРУ для Гриана Камнегрива в Западном Крае.",kw={"defias","edwin vancleef","gryan stoutmantle","mathias shaw","shaw's report","si:7","stonemasons guild","westfall","братство справедливости","эдвин ван клиф","гриан камнегрив","матиас шоу","донесение шоу","шру","гильдия каменщиков","западный край"},ang={["class:Rogue"]="Донесение показывает размах и методы мастера Матиаса Шоу, бесспорного главы разведывательной сети Штормграда и руководителя ШРУ.",["faction:Alliance"]="Документ вскрывает внутреннюю гниль Штормграда: неоплаченный долг перед зодчими королевства породил мятеж, угрожающий землям фермеров."},sec={{t="Сведения о каменщиках",b="Донесение Шоу, доставленное из тайной штаб-квартиры ШРУ в Штормграде в Сторожевой холм, впервые ясно объясняет Народному ополчению, кто командует бандитами, разоряющими Западный Край. В документе рассказано, как Гильдия каменщиков под началом Эдвина ван Клифа кропотливо отстроила Штормград после его разрушения в Первую войну. Когда корона и знать отказались справедливо заплатить каменщикам по завершении работ, зародилась жгучая обида. Сведения Шоу устанавливают важную связь между лишившимися места, недовольными мастерами и преступным мятежом, охватывающим окраины королевства."}},faq={{q="Что такое Донесение Шоу?",a="Это запечатанное разведывательное досье, составленное мастером Матиасом Шоу, главой тайной службы ШРУ в Штормграде, для Гриана Камнегрива. В нем содержатся сведения короны о Гильдии каменщиков и прошлом Эдвина ван Клифа.",al={"shaw report","what does shaw write","shaws report contents","донесение шоу","что пишет шоу","содержание донесения шоу"}},{q="Что донесение сообщает об Эдвине ван Клифе?",a="В нем ван Клиф назван бывшим главой Гильдии каменщиков, руководившим восстановлением Штормграда после Первой войны. Объясняется, что ван Клиф и его мастера восстали после того, как правители королевства отказались должным образом им заплатить.",al={"vancleef in report","what does it say about vancleef","ван клиф в донесении","что сказано о ван клифе"}},{q="Зачем Гриану Камнегриву это донесение?",a="Камнегрив возглавляет Народное ополчение, защищающее Западный Край от согласованных набегов бандитов. Не имея помощи регулярных королевских войск, он полагается на разведку Матиаса Шоу, чтобы выяснить, кто направляет разбойников и каковы их истинные мотивы.",al={"why send report to gryan","why stoutmantle needs report","зачем отправлять донесение гриану","зачем камнегриву донесение"}},{q="Как Камнегрив отреагировал на донесение?",a="Камнегрив глубоко встревожен. Он знает Эдвина ван Клифа как трудолюбивого и умелого мастера и с трудом верит, что столь уважаемый строитель мог скатиться к злодейству без более веских доказательств.",al={"gryan reaction","stoutmantle reaction","реакция гриана","реакция камнегрива"}}},fp="13,296,31.642.1,22.241.0,49.242.0,44.242.0,41.224.0"}
P.entries["item:shimmering-frond"] = {n="Мерцающий росток",s="Мерцающий росток — образец, собранный со странного светящегося растения, которое растет на Поляне Оракула в Тельдрассиле. Необычное свечение и извивающаяся аура показывают, что это экзотический вид, совершенно чуждый ветвям Мирового Древа.",h="Мерцающий росток — образец, собранный со странного светящегося растения, которое растет на Поляне Оракула в...",kw={"botany","denalan","lake al'ameth","oracle glade","shimmering frond","strange fronded plant","swamp of sorrows","teldrassil","ботаника","деналан","озеро аль'амет","поляна оракула","мерцающий росток","странное растение","болото печали","тельдрассил"},ang={["class:Druid"]="Появление чужеродного болотного растения, процветающего на молодых ветвях Тельдрассила, — любопытная экологическая аномалия, достойная внимания любого друида.",["profession:Herbalism"]="Травники, бродящие по Тельдрассилу, оценят редкую стойкость, которая понадобилась уроженцу Болота Печали, чтобы пересечь океан и прижиться на чужой почве."},sec={{t="Образец издалека",b="Бродя под зелеными кронами вокруг Поляны Оракула, путники могут наткнуться на странное растение с пульсирующей сияющей аурой. Ростки, сорванные с него, неестественно ловят рассеянный лесной свет и мерцают яркой жизненной силой. Деналан, ботаник, ухаживающий за своими грядками у Озера Аль'Амет, сразу узнает это растение как вид, родом из далекого Болота Печали в Восточных королевствах. Как семена из болота, лежащего так далеко за Великим морем, смогли прорасти и расцвести на недавно поднятом Тельдрассиле, остается интригующей загадкой, и Деналан выращивает и изучает образцы в собственной почве."}},faq={{q="Откуда берется мерцающий росток?",a="Росток собирают со странного растения с длинными листьями на Поляне Оракула в Тельдрассиле. Растение выделяется извивающимся пульсирующим сиянием, которое разливается по его листьям в лесном свете.",al={"where do i get shimmering frond","shimmering frond location","strange fronded plant","где достать мерцающий росток","где найти мерцающий росток","странное растение с листьями"}},{q="Кого интересует мерцающий росток?",a="Деналан, ночной эльф-натуралист, проводящий ботанические исследования у Озера Аль'Амет, охотно изучит образец. Он очень интересуется странной растительностью, укореняющейся по всему Тельдрассилу.",al={"who wants shimmering frond","who to give shimmering frond","denalan shimmering frond","кому нужен мерцающий росток","кому отдать мерцающий росток","деналан мерцающий росток"}},{q="Чем это растение так необычно для Тельдрассила?",a="Растение не родом из Калимдора или Мирового Древа. Деналан узнает в нем вид, обитающий в мутных водах Болота Печали, далеко за Великим морем в Восточных королевствах, поэтому его процветание на Тельдрассиле весьма неожиданно.",al={"why is shimmering frond special","plant origin","swamp of sorrows plant","чем особенный мерцающий росток","происхождение растения","растение болота печали"}},{q="Что происходит после передачи ростка Деналану?",a="Деналан сразу высаживает и выращивает образец на своих грядках у Озера Аль'Амет, чтобы проверить его быстрый рост и экзотические свойства.",al={"what does denalan do with it","sprouted fronds lore","что деналан делает с ним","проросшие ростки предания"}}},fp="16,244,20.650.0,42.208.0,42.194.0,47.264.0,47.151.0"}
P.entries["item:shimmerweed"] = {n="Звездолист",s="Звездолист — особая трава, которую выращивают тролли Мерзлогривы на Мерцающем хребте в заснеженных высотах Дун Морога. Тролли собирают ее для собственных племенных обрядов, а местные дворфы-пивовары ценят ее резкий неповторимый вкус для экспериментального эля.",h="Звездолист — особая трава, которую выращивают тролли Мерзлогривы на Мерцающем хребте в заснеженных высотах...",kw={"brewnall village","dun morogh","frostmane","perfect stout","rejold barleybrew","shimmer ridge","shimmerweed","поселок пивоваров","дун морог","мерзлогрив","идеальный стаут","регольд ячменовар","мерцающий хребет","звездолист"},ang={["profession:Herbalism"]="Хотя звездолист не входит в обычный набор полевого ботаника, он показывает, как местную флору нередко приспосабливают и для местных пивоваренных традиций, и для ритуальной алхимии.",["race:Dwarf"]="Верные дворфийской изобретательности, они знают: если на соседнем утесе растет странное растение, кто-нибудь непременно попробует сварить из него пиво."},sec={{t="Тролльская культура",b="Высоко над низинами Дун Морога тролли Мерзлогривы выращивают звездолист на ледяных утесах Мерцающего хребта. Они собирают и хранят растение в плетеных корзинах, расставленных по лагерям, и используют его в своих священных и загадочных обрядах. За пределами общества троллей горцы мало обращают внимания на эту траву, хотя ее сильные свойства привлекли взгляды изобретательных чужаков."},{t="Тайный ингредиент",b="В соседнем Поселке Пивоваров мастер-пивовар Регольд Ячменовар очень заинтересовался этой травой. Он верит, что пивоварение у него в крови, хочет сварить лучший дворфийский стаут и подозревает, что резкий, ни с чем не сравнимый вкус звездолиста может стать недостающим звеном. Он часто нанимает отважных путников, чтобы те пробрались в лагеря Мерзлогривов, обошли враждебных троллей и притащили охапки травы для его чанов."}},faq={{q="Где растет звездолист?",a="Звездолист растет на Мерцающем хребте, ледяной возвышенности к северо-западу от Поселка Пивоваров в Дун Мороге. Его выращивают и собирают тролли Мерзлогривы, хранящие его в корзинах в своих лагерях.",al={"shimmerweed location","where to find shimmerweed","shimmer ridge plant","где растет звездолист","где найти звездолист","растение мерцающего хребта"}},{q="Для чего тролли Мерзлогривы используют звездолист?",a="Тролли Мерзлогривы используют звездолист в своих загадочных племенных обрядах и церемониях. Подробности ритуалов остаются неясными для чужаков, но трава играет активную роль в их культурной и духовной жизни на Мерцающем хребте.",al={"troll shimmerweed use","why do trolls want shimmerweed","звездолист у троллей","зачем троллям звездолист"}},{q="Зачем Регольду Ячменовару звездолист?",a="Регольд Ячменовар стремится сварить идеальный дворфийский стаут в Поселке Пивоваров. Почувствовав уникальный вкус дикой травы, он хочет бросить свежие охапки звездолиста в свою экспериментальную сусло-смесь, чтобы проверить, даст ли она яркий вкус, нужный его рецепту.",al={"rejold barleybrew quest","who wants shimmerweed","why brew with shimmerweed","задание регольда ячменовара","кому нужен звездолист","пиво со звездолистом"}},{q="Растет ли звездолист где-нибудь за пределами Дун Морога?",a="Разновидности звездолиста собирали в засушливых землях вроде Дуротара, где провидцы, такие как Дрек'Тар, ценят растение за сильные травяные отвары и лечебные настои, что доказывает: трава приспосабливается и за пределами замерзших пиков Каз Модана.",al={"shimmerweed durotar","shimmerweed outside dun morogh","звездолист дуротар","звездолист за пределами дун морога"}}},fp="11,252,15.413.0,19.442.0,28.203.0,49.250.0,44.263.0,50.237.0"}
P.entries["item:shindrell-s-note"] = {n="Записка Шиндрелл",s="Записка Шиндрелл — письменное послание с описанием недавних наблюдений порчи вокруг Астранаара и побережья Ясеневого леса. Ее написала ночная эльфийка-часовая Шиндрелл Огненный Всполох, и она служит разведывательным донесением, отправленным на восток через лес друиду Кайнету Штилю.",h="Записка Шиндрелл — письменное послание с описанием недавних наблюдений порчи вокруг Астранаара и побережья...",kw={"ashenvale","astranaar","forest song","kayneth stillwind","nightsong woods","shindrell swiftfire","shindrell's note","ясеневый лес","астранаар","лесная песнь","кайнет штиль","леса ночной песни","шиндрелл огненный всполох","записка шиндрелл"},ang={["class:Druid"]="Доставляя наблюдения Шиндрелл Кайнету Штилю, вы помогаете собратьям-друидам найти корни неестественной скверны, терзающей лес.",["race:NightElf"]="Послание показывает постоянное сотрудничество между Часовыми, защищающими поселения Ясеневого леса, и друидами Кенария, изучающими болезнь его природы."},sec={{t="Послание через лес",b="Пока в Ясеневом лесу растет беспокойство, часовые и друиды ночных эльфов согласуют действия, чтобы следить за границами леса. Это донесение, написанное Шиндрелл Огненный Всполох в Астранааре, описывает тревожные происшествия на западном побережье и в центральных кронах. Оно адресовано Кайнету Штилю, друиду, расположившемуся у святилища Лесная Песнь в Лесах Ночной Песни на востоке. Отправляя гонцов со своими личными наблюдениями, Шиндрелл помогает расследованию Кайнета о неявной порче, ползущей по священным рощам."}},faq={{q="Что такое Записка Шиндрелл?",a="Это полевое донесение Шиндрелл Огненный Всполох о происшествиях и подозреваемой порче возле Астранаара и вдоль побережья Ясеневого леса.",al={"what is this note","shindrell note","what does the note say","что это за записка","записка шиндрелл","что написано в записке"}},{q="Кому предназначена записка?",a="Записка адресована Кайнету Штилю, друиду-ночному эльфу в Лесной Песни, в восточной части Ясеневого леса, известной как Леса Ночной Песни.",al={"who do I give this to","where does it go","who is the note for","кому это отдать","куда ее нести","для кого записка"}},{q="Зачем была написана записка?",a="Кайнет Штиль просил сведения о необычных событиях в западных лесах, опасаясь, что в лесу укореняется коварная порча. Шиндрелл собрала свои наблюдения, чтобы помочь ему оценить угрозу.",al={"why write the note","what corruption is shindrell talking about","purpose of report","зачем писать записку","о какой порче говорит шиндрелл","цель донесения"}},{q="Где живет Шиндрелл Огненный Всполох?",a="Шиндрелл Огненный Всполох — часовая ночных эльфов, расквартированная в поселении Астранаар в центральной части Ясеневого леса.",al={"where is shindrell","shindrell swiftfire location","who sent this","где шиндрелл","где найти шиндрелл огненный всполох","кто отправил это"}}},fp="16,283,26.562.0,25.166.0,33.150.0,25.226.0,38.115.0"}
P.entries["item:shipment-of-boots"] = {n="Партия сапог",s="Ящик с обувью, отправленный из Пиратской бухты торговцем Дриззликом для торговой сети Газлоу в Кабестане. Его перехватили у побережья Флибустьеры Южных морей и спрятали в своем лагере к югу от порта.",h="Ящик с обувью, отправленный из Пиратской бухты торговцем Дриззликом для торговой сети Газлоу в Кабестане.",kw={"booty bay","drizzlik","gazlowe","ratchet","shipment of boots","southsea freebooters","stolen booty","пиратская бухта","дризлик","газлоу","кабестан","партия сапог","флибустьеры южных морей","украденная добыча"},ang={["class:Rogue"]="Проникновение в лагеря Южных морей на побережье требует обходить плотные пиратские патрули, поэтому бесшумный подход — самый безопасный способ вернуть украденный груз Газлоу."},sec={{t="Разграбленный груз",b="Управление гоблинским торговым портом требует бесконечных поставок, и Газлоу заказал новую партию сапог у Дризлика, торговца одеждой из Пиратской бухты. Груз так и не добрался до доков Кабестана. Флибустьеры Южных морей, рыскавшие у Торгового побережья, напали на транспортное судно и увезли ящики в свои прибрежные лагеря к югу от гавани. Пираты разбросали краденый груз по палаткам и лачугам, и Газлоу остался без ожидаемого товара, пока не наняли отважных наемников прочесать берег."}},faq={{q="Кто отправил эту партию сапог?",a="Сапоги отправил из Пиратской бухты Дризлик, гоблин-торговец, управляющий лавкой одежды и припасов в южном порту.",al={"who made the boots","where did the boots come from","drizzlik boots","кто сделал сапоги","откуда сапоги","дризлик сапоги"}},{q="Кто должен был получить сапоги?",a="Газлоу, главный инженер и управляющий Кабестана, заказал обувь для своих рабочих и торговых нужд.",al={"who owns the boots","gazlowe boot shipment","чьи сапоги","газлоу партия сапог"}},{q="Как сапоги оказались у пиратов?",a="Флибустьеры Южных морей перехватили грузовой корабль у побережья Степей, разграбили судно и увезли ящики в свои лагеря к югу от Кабестана.",al={"why do southsea pirates have boots","who stole the boots","почему у пиратов южных морей сапоги","кто украл сапоги"}},{q="Где найти партию?",a="Ящик лежит в лагере пиратов Южных морей на побережье к югу от Кабестана, спрятанный среди награбленного.",al={"boots location","where is shipment of boots","find boot shipment","где сапоги","где партия сапог","найти партию сапог"}}},fp="17,233,17.555.0,32.141.0,38.131.0,42.161.0,32.140.0"}
P.entries["item:shipment-of-iron"] = {n="Партия железа",s="Ящик с сырым металлом, хранящийся в человеческой кузнице на Хилсбрадских полях. Это важный запас для местного производства оружия, поэтому он — главная цель Отрекшихся, стремящихся перерезать снабжение Южнобережья.",h="Ящик с сырым металлом, хранящийся в человеческой кузнице на Хилсбрадских полях.",kw={"battle of hillsbrad","darthalia","hillsbrad fields","shipment of iron","tarren mill","verringtan","битва за хилсбрад","дарталия","хилсбрадские поля","партия железа","мельница таррен","верринтан"},ang={["faction:Horde"]="Лишив Хилсбрад припасов, Орда подорвет вооруженное сопротивление крестьян прежде, чем кампания обернется против Южнобережья.",["profession:Blacksmithing"]="Запас — это источник жизни человеческого производства оружия в долине; без сырых железных слитков кузница Верринтана совершенно бесполезна."},sec={{t="Топливо для сопротивления",b="В затянувшейся борьбе в Предгорьях Хилсбрада человеческие крестьяне оказали на удивление упорное сопротивление Мельнице Таррен. Большая часть их боеспособности исходит от кузницы на юго-западной окраине Хилсбрадских полей, где кузнец Верринтан и его подмастерья круглосуточно куют оружие и доспехи из тяжелых партий железа. Чтобы сломить волю земледельцев, командиры Отрекшихся приказали погасить горн, убить кузнецов и захватить запасы металла для военных нужд Орды."}},faq={{q="Где хранится партия железа?",a="Партия лежит прямо в кузнице на юго-западной окраине Хилсбрадских полей, ее усиленно охраняют кузнец Верринтан и его подмастерья.",al={"shipment of iron location","where is the iron","hillsbrad iron location","партия железа где","где железо","железо хилсбрада"}},{q="Зачем Отрекшимся это железо?",a="Захват железа перекрывает поставки оружия местному человеческому ополчению. Верховный палач Дарталия также намерена использовать запасы металла для военной машины Орды, когда наступление перейдет к уничтожению Южнобережья.",al={"why steal iron","tarren mill iron","battle of hillsbrad iron purpose","зачем красть железо","железо мельницы таррен","цель железа битвы за хилсбрад"}},{q="Кто изначально использовал это железо?",a="Кузнец Верринтан и его четверо подмастерьев использовали железо, чтобы вооружать горожан и работников полей, превращая простых земледельцев в вооруженные местные силы обороны от нежити.",al={"who owns the iron","verringtan iron","hillsbrad blacksmiths","чье железо","железо верринтана","кузнецы хилсбрада"}},{q="Кто приказывает забрать партию железа?",a="Верховный палач Дарталия, командующая действиями Отрекшихся из Мельницы Таррен, лично приказывает убить кузнецов и забрать железо во время Битвы за Хилсбрад.",al={"who gives the quest","darthalia iron quest","кто дает задание","задание дарталии железо"}}},fp="16,220,22.546.0,35.179.0,37.231.0,35.193.0,46.173.0"}
P.entries["item:shipping-schedule"] = {n="Расписание поставок",s="Расписание поставок — логистический документ, который хранится у начальника причала Братства Справедливости в Лагере Джерода. В нем описаны перевозки незаконных грузов через Элвиннский лес между Красногорьем и Западным Краем, что привлекает пристальное внимание разведки Штормграда.",h="Расписание поставок — логистический документ, который хранится у начальника причала Братства Справедливости в...",kw={"defias","dockmaster","elwynn forest","jerod's landing","mathias shaw","shipping schedule","si:7","smuggling","братство справедливости","начальник причала","элвиннский лес","лагерь джерода","матиас шоу","расписание поставок","шру","контрабанда"},ang={["class:Rogue"]="Добыча расписания из карманов начальника причала — главное испытание скрытности и воровства для начинающих агентов, стремящихся вступить в ряды ШРУ."},sec={{t="Контрабанда в Лагере Джерода",b="К югу от Златоземья, на элвиннском берегу реки Назферити, Братство Справедливости захватило Лагерь Джерода и превратило его в узел речных перевозок. Через эту скрытую пристань Братство перевозит большие партии контрабанды между Красногорьем и Западным Краем, проскальзывая по водным путям прямо под носом у Стражи Штормграда. Расписание поставок фиксирует эти тайные перевозки и находится под строгой охраной у самого начальника причала."},{t="На прицеле ШРУ",b="Мастер Матиас Шоу, глава ШРУ, поручил похитить расписание, чтобы изучить цепочки снабжения Братства Справедливости и испытать новичков-агентов. Проникновение в дом на причале и кража документа из карманов начальника причала дают короне полезные разведданные и служат вступительным испытанием. Если агента поймают, ШРУ отречется от любой связи с ним, не оставив следов, ведущих к казармам в Штормграде."}},faq={{q="Что такое Расписание поставок?",a="Это рабочий журнал, который ведет начальник причала Братства Справедливости в Лагере Джерода. В нем подробно описано движение контрабанды и припасов, перевозимых между Красногорьем и Западным Краем по внутренним водам Элвиннского леса.",al={"defias shipping schedule","what is this document","dockmaster schedule","расписание поставок братства справедливости","что это за документ","расписание начальника причала"}},{q="Кто хочет вернуть это расписание?",a="Мастер Матиас Шоу, глава разведывательной службы Штормграда — ШРУ. Он использует эти сведения, чтобы отслеживать контрабандную сеть Братства Справедливости и оценивать перспективных разбойников в полевых условиях.",al={"who needs the schedule","mathias shaw schedule","who takes the shipping schedule","кому нужно расписание","матиас шоу расписание","кто забирает расписание поставок"}},{q="Где найти расписание?",a="Документ носит при себе начальник причала Братства Справедливости в доме на причале в Лагере Джерода, на реке Назферити к югу от Златоземья в Элвиннском лесу. Агенту нужно проникнуть в здание и украсть документ из карманов начальника причала или забрать его с трупа.",al={"shipping schedule location","where is the dockmaster","how to get the schedule","где расписание поставок","где начальник причала","как получить расписание"}},{q="Для чего используется Лагерь Джерода?",a="Лагерь Джерода захватили бандиты Братства Справедливости, чтобы использовать его как транзитный пункт. Через выход к реке они переправляют незаконные грузы по всему королевству, напрямую связывая свои операции в Красногорье с оплотами в Западном Крае.",al={"jerods landing defias","why do defias have jerods landing","defias dock elwynn","лагерь джерода братство справедливости","почему братство справедливости в лагере джерода","причал братства элвиннский лес"}}},fp="17,271,28.453.0,25.408.0,30.224.0,34.184.0,28.235.0,33.225.0"}
P.entries["item:sida-s-bag"] = {n="Сумка Сиды",s="Сумка Сиды — личная сумка Сиды, жительницы Гавани Менетилов. Во время похода к Гробнице Железноборода сумку целиком проглотила ползучая слизь, и чтобы вернуть ее вместе с таинственным содержимым, придется тщательно прочесать кислотные слизи Болотины.",h="Сумка Сиды — личная сумка Сиды, жительницы Гавани Менетилов.",kw={"dun modr","ironbeard's tomb","menethil harbor","ooze","sida","sida's bag","wetlands","дун модр","гробница железноборода","гавань менетилов","слизь","сида","сумка сиды","болотина"},ang={["faction:Alliance"]="Осажденные беженцы и горожане Гавани Менетилов целиком полагаются на проезжих путников в борьбе с хищными тварями, ползущими из затопленной Болотины."},sec={{t="Паническая оборона",b="Во время своего обычного еженедельного визита к Гробнице Железноборода близ Дун Модра Сида попала в засаду жутких капающих слизней, которыми кишит эта местность. Запаниковав при виде наползающей жижи, она швырнула свою сумку прямо в одно из существ. Вместо того чтобы отогнать тварь, слизь просто поглотила сумку своим желеобразным телом. Это отвлечение дало Сиде несколько драгоценных мгновений, чтобы спастись бегством в безопасную Гавань Менетилов, оставив свои вещи внутри неведомой слизи."},{t="Возвращена из слизи",b="Поскольку колышущиеся слизи, бродящие у Гробницы Железноборода, — от багровых до чудовищных — выглядят почти одинаково, чтобы найти сумку, нужно рубить болотную слизь, пока проглоченная сумка не выйдет целой. Несмотря на то что сумка лежала в кислотной пищеварительной жиже, прочный мешок сохранил содержимое. Когда ее приносят Сиде, она с радостью забирает свои вещи и выбрасывает испорченную, покрытую слизью оболочку, отдавая отмытый мешок тому, кто отважился отправиться в болото ради нее."}},faq={{q="Почему сумка Сиды оказалась внутри слизи?",a="Сида запаниковала, когда на нее напали капающие слизи во время визита к Гробнице Железноборода. Отчаянно пытаясь спастись, она швырнула сумку в одно из чудовищ, и оно тут же поглотило ее целиком.",al={"how did ooze get bag","why is bag in slime","how did sida lose bag","как слизь получила сумку","почему сумка в слизи","как сида потеряла сумку"}},{q="Какие слизи носят Сумку Сиды?",a="Сида не может отличить слизи друг от друга, поэтому сумку могла проглотить любая из хищных слизей вокруг Гробницы Железноборода на северо-востоке Болотины, включая багровых, черных или чудовищных слизей.",al={"where to find sida's bag","what drops sida's bag","which slime has bag","где найти сумку сиды","с кого падает сумка сиды","какая слизь проглотила сумку"}},{q="Зачем Сида ходит к Гробнице Железноборода?",a="Сида каждую неделю отправляется из Гавани Менетилов к древнему дворфийскому склепу близ Дун Модра, но личные причины этих регулярных визитов держит при себе.",al={"sida ironbeard connection","why ironbeard's tomb","сида и гробница железноборода","зачем гробница железноборода"}},{q="Что было внутри сумки Сиды?",a="Сида быстро высыпает возвращенные вещи на землю и собирает их, не показывая, что это, лишь замечая, что содержимое было слишком важным, чтобы оставлять его растворяться внутри слизи.",al={"what does sida take out of the bag","bag contents","что сида достает из сумки","содержимое сумки"}}},fp="10,265,18.532.0,24.496.0,34.209.0,29.208.0,37.175.0,27.196.0"}
P.entries["item:signed-recruitment-letter"] = {n="Подписанное письмо о найме",s="Подписанное письмо о найме — официальное донесение, выданное Каргалом Боевым Шрамом на Дальней заставе. С отметкой Каргала оно направляет новобранцев вглубь засушливых Степей, чтобы те явились на службу на Перекресток.",h="Подписанное письмо о найме — официальное донесение, выданное Каргалом Боевым Шрамом на Дальней заставе.",kw={"conscription","crossroads","far watch post","kargal battlescar","sergra darkthorn","signed recruitment letter","the barrens","thrall","призыв","перекресток","дальняя застава","каргал боевой шрам","сергра черный шип","подписанное письмо о найме","степи","тралл"},ang={["class:Shaman"]="Документ отправляет вас на службу к Сергре Черный Шип, видной орчанке-шаманке, которой Тралл поручил помогать защищать Степи.",["faction:Horde"]="Письмо о найме означает ваш переход от базовой службы в Дуротаре к более широкому военному аппарату Орды на границе."},sec={{t="Перевод новобранца",b="Дальняя застава — восточные врата Степей — проверяет новичков, пересекающих реку Строптивую из Дуротара. Когда новобранец доказывает Каргалу Боевому Шраму свою готовность, тот скрепляет печатью и подписью это рекомендательное письмо. Оно служит военным приказом, направляющим новобранцев на запад по дороге к Перекрестку, где Сергра Черный Шип руководит снабжением и обороной территории на сухих равнинах."},{t="Напряжение на заставах",b="Хотя письмо является официальным документом Орды, Каргал не скрывает личного презрения к офицеру, ожидающему новобранца. Он считает Сергру Черный Шип резкой шаманкой, которая заговаривает солдат, и открыто сомневается в высоком мнении вождя Тралла о ней. Несмотря на сомнения, донесение нужно вручить прямо в руки Сергры, прежде чем на Перекрестке дадут какие-либо дальнейшие поручения."}},faq={{q="Для чего нужно Подписанное письмо о найме?",a="Письмо служит официальным документом о военном переводе. Оно подтверждает Сергре Черный Шип на Перекрестке, что Каргал Боевой Шрам проверил вас на Дальней заставе и счел готовым к службе в Степях.",al={"what does this letter do","recruitment letter use","signed letter barrens","что делает это письмо","зачем письмо о найме","подписанное письмо степи"}},{q="Кто подписал письмо?",a="Каргал Боевой Шрам, орк-ветеран, управляющий Дальней заставой на границе Дуротара и Степей. Он подписывает письмо после того, как новобранец выполнит первые обязанности на границе.",al={"who wrote the letter","kargal letter","who signed this","кто написал письмо","письмо каргала","кто это подписал"}},{q="Кому нужно доставить письмо?",a="Его нужно доставить Сергре Черный Шип, влиятельной орчанке-шаманке, которая находится на центральном перекрестке дорог на Перекрестке.",al={"where do i take the letter","who gets the letter","letter recipient","куда нести письмо","кто получает письмо","адресат письма"}},{q="Почему Каргал плохо отзывается о Сергре Черный Шип?",a="Каргал считает Сергру острой на язык, трудной офицершей, которая тратит время на разговоры, когда нужно работать. Хотя вождь Тралл высоко ее ценит, Каргал по-прежнему скептически относится к ее руководству.",al={"kargal sergra feud","why does kargal hate sergra","вражда каргала и сергры","почему каргал ненавидит сергру"}}},fp="25,236,22.437.0,23.422.0,53.209.0,22.186.0,31.118.0,49.214.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Яйцо силитида (Степи)",s="Яйца силитидов — развивающееся потомство насекомоподобных существ, гнездящихся на юге Степей. Эти кладки, зарытые в земляных холмах вокруг Полей Великанов, собирают исследователи Орды, стремящиеся выяснить происхождение и разум наступающего роя.",h="Яйца силитидов — развивающееся потомство насекомоподобных существ, гнездящихся на юге Степей.",kw={"crossroads","digging claw","egg hunt","field of giants","korran","mounds","silithid","silithid egg","the barrens","перекресток","коготь для копания","охота за яйцами","поля великанов","корран","холмы","силитид","яйцо силитида","степи"},ang={["faction:Horde"]="Появление разумных роев насекомых так близко к Перекрестку создает тревожную опасность для торговых путей и земель Орды в центральном Калимдоре."},sec={{t="Таинственный рой",b="В засушливой котловине Полей Великанов странные насекомоподобные существа принялись перерывать землю, воздвигая высокие холмы. Глубоко в этих гнездах лежат их яйца, погребенные под затвердевшей землей, под охраной территориальных выводков. Орда почти ничего не знает о силитидах, но разведчики на Перекрестке заметили признаки согласованного поведения и странного разума, намного превосходящего обычных диких зверей. Сбор невылупившихся яиц дает ученым Оргриммара наилучший шанс изучить жизненный цикл и природу этой возникающей угрозы."},{t="Раскопки и опасность",b="Чтобы добраться до яиц, нужно вскрывать холмы силитидов специальными когтями для копания. Тревожить эти кладки — опасное дело: силитиды яростно реагируют на вторжение возле своих подземных гнезд и набрасываются роем на всех, кто угрожает их невылупившемуся потомству. Для исследователей вроде тролля Коррана добыть целые, неповрежденные образцы крайне важно для анализа, пока рой не распространился дальше по Калимдору."}},faq={{q="Что такое яйца силитидов?",a="They are the unhatched clutches of the insectoid silithid found nesting inside earthen mounds in the southern Barrens, particularly throughout the Field of Giants.",al={"silithid egg","what is silithid egg","silithid mounds","яйцо силитида","что такое яйцо силитида","холмы силитидов"}},{q="Кто хочет собрать эти яйца?",a="Корран, тролль-исследователь на Перекрестке, собирает их по поручению своих начальников в Оргриммаре, чтобы изучать странную биологию и поведение силитидов.",al={"who needs eggs","korran quest","egg hunt questgiver","кому нужны яйца","задание коррана","охота за яйцами"}},{q="Почему силитидов изучают?",a="Орда почти ничего не знает о силитидах. Корран отмечает, что они проявляют признаки разума и согласованности действий, намного превосходящие обычных диких животных, что тревожит лидеров Орды в связи с их внезапным появлением в Степях.",al={"why study silithid","silithid threat","are silithid smart","зачем изучать силитидов","угроза силитидов","умны ли силитиды"}},{q="Как собирают яйца?",a="Их нужно осторожно выкапывать из холмов силитидов с помощью приспособленного когтя для копания, отбиваясь от агрессивного роя, защищающего гнезда.",al={"how to get eggs","digging claw","harvest silithid eggs","как достать яйца","коготь для копания","сбор яиц силитидов"}}},fp="26,282,18.552.0,21.406.0,23.163.0,31.165.0,35.230.0,26.145.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Ключ башни Силиксиза",kw={"barrens","foreman silixiz","shattered hand","shenthul","silixiz","sludge fen","tower key","venture co","степи","штейгер силиксиз","изувеченная длань","шентул","силиксиз","нефтяное болото","ключ башни","торговая компания"},ang={["class:Rogue"]="Добыча Ключа башни Силиксиза — важное испытание для разбойников Орды, вступающих в ряды Изувеченной Длани, требующее мастерства скрытности и воровства.",["faction:Horde"]="Ключ — важный трофей в борьбе с эксплуатацией Торговой Компании и химическими опытами, угрожающими северным Степям."},sec={{t="Испытание на скрытность",b="The Venture Company operation north of the Sludge Fen runs under tight security, centered on an isolated lookout tower supervised by Grand Foreman Puzik Gallywix. Outside the compound patrolled by goblin mercenaries, Foreman Silixiz carries the tower key that the Shattered Hand operative is instructed to steal and keep. For the rogue network of the Shattered Hand operating out of Orgrimmar, obtaining this key is not a matter of blunt force; field operatives must slip into the compound undetected and pick the foreman's pockets cleanly, proving their mastery of stealth before climbing into the toxic upper levels."}},faq={{q="Где найти штейгера Силиксиза?",a="Штейгер Силиксиз находится у башни Торговой Компании, расположенной прямо к северу от Нефтяного болота, на северо-востоке Степей.",al={"silixiz location","where is foreman silixiz","find silixiz","где силиксиз","где штейгер силиксиз","найти силиксиза"}},{q="Можно ли получить ключ, убив штейгера Силиксиза?",a="Нет. Ключ нельзя снять с его трупа. Чтобы получить предмет, агентам нужно действовать скрытно и обчистить его карманы, пока он жив.",al={"silixiz key drop","can i kill silixiz","loot silixiz key","ключ силиксиза с трупа","можно ли убить силиксиза","добыть ключ силиксиза"}},{q="Кому нужен этот ключ?",a="Ключ — цель, поставленная связными Изувеченной Длани, для передачи Шентулу, тренеру разбойников, обитающему в тенях Оргриммара.",al={"who wants the key","turn in silixiz key","silixiz tower key quest","кому нужен ключ","сдать ключ силиксиза","задание ключ башни силиксиза"}},{q="Для чего нужен этот ключ?",a="Ключ служит доказательством проникновения в башню Торговой Компании близ Нефтяного болота и сдается Изувеченной Длани вместе с головой главного смотрителя Пузика Галливикса и тайником с измененной смесью Занзила.",al={"what does silixiz key unlock","silixiz key purpose","use tower key","что открывает ключ силиксиза","назначение ключа силиксиза","использование ключа башни"}}},fp="19,274,18.618.0,32.149.0,48.155.0,22.146.0,25.221.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="Денежный ящик Серебряной Зари",s="Денежный ящик Серебряной Зари — прочный сундук в затонувших обломках корабля «Серебряная Заря» у побережья Темных берегов. В нем лежат личные вещи и судовой журнал погибшего капитана, убитого в засаде прибрежных мурлоков.",h="Денежный ящик Серебряной Зари — прочный сундук в затонувших обломках корабля «Серебряная Заря» у побережья...",kw={"auberdine","darkshore","gorbold steelhand","lockbox","murloc","shipwreck","silver dawning","аубердин","темные берега","горбольд сталерук","ящик","мурлок","кораблекрушение","серебряная заря"},ang={["race:Dwarf"]="Горбольд Сталерук берет на себя заботу о том, чтобы павших капитанов почтили, а их вещи вернули выжившим товарищам.",["race:NightElf"]="В ящике сохранились последние записи и памятные вещи капитана кальдораев, погибшего при защите своего корабля у берегов северного Калимдора."},sec={{t="Затонувшие обломки",b="Корабль «Серебряная Заря» шел через море к порту Аубердин, когда случилась беда. Прибрежные мурлоки облепили судно и утопили его в темном прибое к северу от гавани. Капитан погиб при нападении вместе с командой, а обломки остались под водой как мрачный памятник, доставшийся тварям. В затопленном трюме сохранился личный ящик капитана с судовым журналом и личными вещами. Возвращение этих вещей приносит последнее успокоение выжившим морякам на берегу."}},faq={{q="Где находится Денежный ящик Серебряной Зари?",a="Ящик лежит внутри затонувших обломков «Серебряной Зари» — перевернутого судна на морском дне к северу от Аубердина, у побережья Темных берегов.",al={"lockbox location","where is silver dawning box","silver dawning wreck","где ящик","где ящик серебряной зари","обломки серебряной зари"}},{q="Что случилось с «Серебряной Зарей»?",a="Когда «Серебряная Заря» плыла через океан к Аубердину, на нее напали местные мурлоки. Судно было захвачено, разбито и затонуло, а его капитан погиб.",al={"why did silver dawning sink","silver dawning backstory","how did ship wreck","почему затонула серебряная заря","история серебряной зари","как разбился корабль"}},{q="Что внутри ящика?",a="В сундуке хранятся личные вещи и судовой журнал капитана «Серебряной Зари», сохранившиеся в морской глубине.",al={"silver dawning contents","what is in the box","содержимое серебряной зари","что в ящике"}},{q="Кто ищет ящик?",a="Горбольд Сталерук, дворф из Аубердина, просит смелых пловцов нырнуть к обломкам и достать ящик, чтобы выжившая команда погибшего капитана могла почтить его память.",al={"who wants the lockbox","who gives the quest","turn in lockbox","кому нужен ящик","кто выдает задание","сдать ящик"}}},fp="24,255,15.550.0,46.161.0,36.193.0,27.130.0,27.191.0"}
P.entries["item:silvery-spinnerets"] = {n="Серебристые паутинные железы",s="Серебристые паутинные железы добывают у огромной паучихи леди Сатры на севере Тельдрассила. Когда-то она плела паутину, собиравшую целебную вечернюю росу для Храма Луны. Теперь жрицы Элуны ищут железы, чтобы почтить душу павшего создания священным обрядом возрождения.",h="Серебристые паутинные железы добывают у огромной паучихи леди Сатры на севере Тельдрассила.",kw={"lady sathrah","priestess a'moora","sathrah's sacrifice","silvery spinnerets","tears of the moon","temple of the moon","wellspring lake","леди сатра","жрица а'моора","жертвоприношение сатры","серебристые паутинные железы","слезы луны","храм луны","родниковое озеро"},ang={["class:Priest"]="Для слуг Элуны добыча желез — не заказ на истребление, а священный погребальный обряд, в котором они просят Матерь-Луну об искуплении создания.",["race:NightElf"]="Трагический конец леди Сатры напоминает кальдораям, что даже любимые Элуной создания уязвимы для подкрадывающейся болезни, поражающей Тельдрассил."},sec={{t="Священная паутина и порча",b="Леди Сатра когда-то считалась одним из любимых созданий Элуны и славилась мерцающей паутиной, которую плела в лунном свете у Родникового озера. Ее серебряный шелк собирал вечерний туман, образуя целебную росу, ценимую Сестринством Элуны в Дарнассе. К несчастью, порча, расползающаяся по ветвям Тельдрассила, не пощадила и ее. Впав в яростное безумие, Сатра стала опасна для собственного потомства и окрестного леса. Жрица А'моора просит путников прекратить страдания паучихи и добыть ее железы как акт милосердия, завершив историю почитаемой обитательницы великих ветвей."},{t="Жертва ради возрождения",b="Добытые железы нужны не как простой трофей или материал для ремесла. Сестринство приносит их прямо в дар Богине Луны на вершине Храма Луны. Посредством этого освящения, известного как Жертвоприношение Сатры, жрицы молятся, чтобы Элуна приняла дух создания, очистила безумие, овладевшее ее смертным телом, и даровала ей покой в перерождении."}},faq={{q="Где достать Серебристые паутинные железы?",a="Их добывают у леди Сатры, крупной паучихи, обитающей на северных границах Тельдрассила близ Родникового озера.",al={"where to find silvery spinnerets","silvery spinnerets drop","who drops silvery spinnerets","где найти серебристые паутинные железы","серебристые паутинные железы добыча","кто дает серебристые паутинные железы"}},{q="Зачем жрице А'мооре паутинные железы?",a="Жрица А'моора хочет принести их Элуне как священную жертву. Этот обряд чтит прежнюю чистоту леди Сатры и молит богиню очистить дух чудовища и даровать ей покой и возрождение.",al={"why amoora wants spinnerets","tears of the moon purpose","зачем аморе железы","слезы луны назначение"}},{q="Чем была особенной паутина леди Сатры?",a="Леди Сатра плела светящийся серебряный шелк, собиравший вечерний туман в лунном свете. Роса с ее паутины обладала сильной целебной магией, и Сестринство Элуны хранило ее в Храме Луны для исцеления.",al={"lady sathrah webs","what did lady sathrah do","паутина леди сатры","что делала леди сатра"}},{q="Почему убили леди Сатру, если она была священной?",a="Она впала в неизлечимое безумие, как и другие зараженные порчей животные Тельдрассила. Ее агрессия угрожала лесу и будущему потомству, и жрицы сочли ее убийство печальным актом милосердия.",al={"why kill lady sathrah","why did sathrah go crazy","зачем убивать леди сатру","почему сатра сошла с ума"}}},fp="18,293,29.621.0,23.379.1,40.121.0,47.206.0,37.233.0,46.227.0"}
P.entries["item:simple-memorandum"] = {n="Записка",s="Записка — официальное уведомление, которое получают гномы-воины-новички в Холодной долине. Написанная от имени учителя воинов Трана Кормана, она велит новичкам явиться к нему в Старую Наковальню для совершенствования боевой выучки.",h="Записка — официальное уведомление, которое получают гномы-воины-новички в Холодной долине.",kw={"anvilmar","coldridge valley","dun morogh","gnomeregan","simple memorandum","thran khorman","warrior training","старая наковальня","холодная долина","дун морог","гномреган","записка","тран корман","обучение воинов"},ang={["class:Warrior"]="Эта записка — первый шаг воина от простых стычек к формальному боевому обучению у Трана Кормана в Старой Наковальне.",["race:Gnome"]="Для изгнанных гномов записка напоминает об общей цели: оттачивать боевые навыки вместе с союзниками-дворфами, готовясь к освобождению Гномрегана."},sec={{t="Вызов в Старую Наковальню",b="Начинающим искателям приключений в Холодной долине часто поручают рекомендательные письма, пока они доказывают свою доблесть в схватках с местными зверями и троггами. Для молодых гномов-бойцов эта записка — официальный вызов от Трана Кормана, местного учителя воинов в Старой Наковальне. Ветераны-дворфы понимают: хотя гномы полагаются на разум и механизмы, для возвращения Гномрегана нужны твердая воля и боевая выучка. Записка велит владельцу отложить предварительные дела и обратиться за личным обучением военному искусству."}},faq={{q="Что такое Записка?",a="Это письменное послание гномам-воинам-новичкам в Холодной долине, велящее им явиться к дворфу — учителю воинов в Старой Наковальне.",al={"simple memorandum","what is this note","memorandum item","записка","что это за записка","предмет записка"}},{q="Кто написал Записку?",a="Записка исходит от Трана Кормана, дворфа — учителя воинов в Старой Наковальне, который стремится находить и готовить перспективных новых бойцов.",al={"who wrote memorandum","who sent note","author of simple memorandum","кто написал записку","кто прислал записку","автор записки"}},{q="Что будет после прочтения Записки?",a="Прочитав документ, вы относите его Трану Кормана в Старую Наковальню. Он признает вашу решимость вернуть потерянный дом и предлагает обучить вас основам воинского искусства.",al={"what do i do with memorandum","where do i take it","turn in simple memorandum","что делать с запиской","куда нести записку","сдать записку"}},{q="Почему дворф обучает гномов-воинов?",a="После падения Гномрегана гномы-беженцы нашли приют в Стальгорне и Старой Наковальне. Ветераны-дворфы, такие как Тран Корман, пообещали передать свое боевое мастерство изгнанным союзникам, чтобы те смогли обучиться и вернуть свой облученный город.",al={"why thran training gnomes","dwarves training gnomes","почему тран обучает гномов","дворфы обучают гномов"}}},fp="17,254,21.599.0,30.160.0,32.151.0,49.194.0,39.260.0"}
P.entries["item:simple-rune"] = {n="Простая руна",s="Простая руна — каменный жетон с надписью, который вручают начинающим дворфийским воинам, обучающимся в Холодной долине. Он служит вызовом от учителя воинов Трана Кормана и направляет новобранцев на обучение в Старую Наковальню.",h="Простая руна — каменный жетон с надписью, который вручают начинающим дворфийским воинам, обучающимся в...",kw={"anvilmar","coldridge valley","dun morogh","dwarf rune","simple rune","thran khorman","warrior training","старая наковальня","холодная долина","дун морог","руна дворфов","простая руна","тран корман","обучение воинов"},ang={["class:Warrior"]="Для дворфийских воинов этот камень с надписью — первый шаг к официальной военной подготовке под руководством опытного наставника Трана Кормана.",["race:Dwarf"]="Дворфы традиционно используют для приказов, напоминаний и боевых вызовов прочные руны с надписями, а не хрупкий пергамент."},sec={{t="Вызов к оружию",b="Простую руну с простыми боевыми знаками вручают перспективным новобранцам, начавшим очищать окрестности Холодной долины от угроз. Это не магический талисман, а официальный вызывной камень от Трана Кормана, местного учителя воинов в Старой Наковальне. Прочитав надпись, молодой боец должен явиться прямо к Трану, чтобы освоить основы боя и получить практические советы о том, как выжить в суровых землях Дун Морога."}},faq={{q="Для чего нужна Простая руна?",a="Простая руна — обучающая табличка, которую выдают новичкам-воинам в Холодной долине. Прочтя ее, рекрут должен явиться к Трану Корману в Старую Наковальню для официального обучения.",al={"simple rune use","what does rune do","simple rune quest item","применение простой руны","что делает руна","простая руна задание"}},{q="Кто присылает Простую руну?",a="Ее присылает Тран Корман, дворф — учитель воинов в Старой Наковальне, который присматривается к перспективным бойцам, помогающим в долине.",al={"who wrote rune","who gave me simple rune","sender of rune","кто написал руну","кто дал простую руну","отправитель руны"}},{q="Куда нести Простую руну?",a="Отнесите ее Трану Корману в большой кузнечный зал Старой Наковальни в центре Холодной долины.",al={"where do i go","rune turn in","thran khorman location","куда идти","сдать руну","где тран корман"}}},fp="11,227,17.463.0,39.198.0,26.145.0,32.102.0"}
P.entries["item:simple-sigil"] = {n="Простой знак",s="Простой знак — скромный учебный жетон, который получают начинающие воины из числа ночных эльфов в Тенистой долине. Он вручается как вызов от наставницы воинов Алайссии и знаменует официальное вступление молодого бойца в ряды защитников Тельдрассила.",h="Простой знак — скромный учебный жетон, который получают начинающие воины из числа ночных эльфов в Тенистой...",kw={"alyissia","ilthalaine","kaldorei warrior","shadowglen","simple sigil","teldrassil","warrior training","алайссия","илталайн","воин кальдораев","тенистая долина","простой знак","тельдрассил","обучение воинов"},ang={["class:Warrior"]="Для воинов-кальдораев этот простой жетон — первое удостоверение, знакомящее вас с воинскими традициями, необходимыми для защиты Тельдрассила.",["race:NightElf"]="Знак подчеркивает остроту положения кальдораев: наставники вроде Алайссии привлекают любые способные руки, чтобы сдержать растущую порчу в ветвях Мирового Древа."},sec={{t="Вызов к оружию",b="В защищенных ветвях Тенистой долины Опекун Илталайн помогает молодым ночным эльфам найти призвание. Будущим воинам Илталайн вручает Простой знак, присланный с гонцом от учителя воинов Алайссии. Надпись на нем велит новобранцу явиться на обучение: этот жетон означает начало строгой военной подготовки в тревожные для Мирового Древа времена."},{t="Бремя защиты",b="Когда знак приносят Алайссии, начинается разговор о тяжелом положении кальдораев. Недавний рост Тельдрассила, расползающаяся порча, поражающая лесных зверей, и повторное открытие дальних земель вроде Фераласа сильно растянули силы защитников ночных эльфов. Знак — не артефакт силы, а практическое удостоверение, принимающее новобранца в ряды стражей, призванных защищать свой народ от новых угроз."}},faq={{q="Что такое Простой знак?",a="Это вводный жетон с надписью, который Опекун Илталайн в Тенистой долине выдает ночным эльфам — воинам-новичкам. Он велит владельцу явиться к Алайссии для официального обучения воинов.",al={"simple sigil item","what does simple sigil do","what is this sigil","предмет простой знак","что делает простой знак","что за знак"}},{q="Кто присылает Простой знак?",a="Знак отправляет гонец от имени Алайссии, местного учителя воинов в Тенистой долине, которая хочет начать обучение новых воинов защите Тельдрассила.",al={"who made the sigil","who sent simple sigil","кто сделал знак","кто прислал простой знак"}},{q="Что с ним делать?",a="Прочитайте надпись и отнесите знак Алайссии у подножия Альдрассила в Тенистой долине, чтобы начать обучение воина.",al={"where to turn in simple sigil","who takes simple sigil","куда сдать простой знак","кто принимает простой знак"}},{q="Дает ли знак особые способности?",a="Нет. Это лишь письменное уведомление и удостоверение, представляющее начинающих воинов их наставнику.",al={"sigil powers","simple sigil stats","силы знака","характеристики простого знака"}}},fp="12,238,17.413.0,21.439.0,25.188.0,27.178.0,25.126.0,43.102.0"}
P.entries["item:simple-tablet"] = {n="Простая табличка",s="Простая табличка — письменное послание, которое получают тролли — воины-новички, прибывающие в Долину Испытаний. Ее вручает Горнек, и она направляет начинающего бойца к Франгу, местному учителю воинов.",h="Простая табличка — письменное послание, которое получают тролли — воины-новички, прибывающие в Долину...",kw={"darkspear","durotar","frang","gornek","simple tablet","the den","valley of trials","warrior trainer","черное копье","дуротар","франг","горнек","простая табличка","логово","долина испытаний","учитель воинов"},ang={["class:Warrior"]="Табличка знаменует официальное знакомство тролля-воина с Франгом и начало его боевого обучения в рядах Орды.",["race:Troll"]="Для троллей Черного Копья, находящих свое место рядом с орками в Дуротаре, получение вызова означает долг усилить передовые ряды."},sec={{t="Вызов на битву",b="В суровых красных пределах Долины Испытаний новобранцев быстро берут в работу. Молодым троллям, избравшим путь воина, Горнек передает эту простую плитку или пергамент. Ее написал тролль Тар'сере для Франга, мастера боевых искусств, отдыхающего возле Логова. Это официальное представление к военному обучению в Дуротаре. Она призывает новобранца выйти вперед, представиться и доказать готовность владеть оружием под знаменем Орды."}},faq={{q="Что такое Простая табличка?",a="Это вводное письменное послание, которое Горнек вручает троллям — начинающим воинам в Долине Испытаний. Оно велит прочитать его и найти Франга для настоящего боевого обучения.",al={"simple tablet","what is this tablet","troll warrior tablet","простая табличка","что за табличка","табличка воина-тролля"}},{q="Кто присылает табличку?",a="The message is signed by the troll Tar'sere, who sends the recruit to Frang, the warrior trainer stationed outside the Den in the Valley of Trials.",al={"who sent simple tablet","who wrote the tablet","tablet sender","кто прислал простую табличку","кто написал табличку","отправитель таблички"}},{q="Куда нести табличку?",a="Отнесите ее Франгу, которого можно найти отдыхающим в тени у входа в Логово в Долине Испытаний.",al={"who do i give simple tablet to","where to bring tablet","frang location","кому отдать простую табличку","куда нести табличку","где франг"}},{q="Кто получает эту табличку?",a="Простую табличку выдают именно троллям-воинам, начинающим обряд посвящения в Долине Испытаний.",al={"can anyone get simple tablet","which class gets simple tablet","кто получает простую табличку","какой класс получает простую табличку"}}},fp="13,219,19.491.0,26.186.0,21.147.0,27.113.0,25.118.0"}
P.entries["item:singed-scale"] = {n="Оплавленная чешуя",s="Оплавленная чешуя — обугленные, закаленные ударами молний пластины, которые добывают у электрических громовых ящеров Дуротара. Их добыча — обряд посвящения для молодых воинов Орды, стремящихся овладеть искусством защиты в бою.",h="Оплавленная чешуя — обугленные, закаленные ударами молний пластины, которые добывают у электрических громовых...",kw={"far watch post","lightning hide","path of defense","singed scale","thunder lizard","thunder ridge","uzzek","дальняя застава","молниевая шкура","путь защиты","оплавленная чешуя","громовой ящер","громовой хребет","уззек"},ang={["class:Warrior"]="Для начинающего воина принести эту чешую Уззеку — важная веха в постижении искусства защиты и умения стоять непробиваемым щитом Орды.",["faction:Horde"]="Испытания на Дальней заставе гарантируют, что стражи и бойцы авангарда, охраняющие границы Дуротара и Степей, обладают несокрушимой выносливостью."},sec={{t="Испытание выносливости",b="Для ветеранов Орды истинный воин измеряется не только кровью, пролитой его топором, но и ударами, которые он способен принять, защищая союзников. В засушливом каньоне Громового хребта на западе Дуротара молниевые шкуры и громовые ящеры потрескивают переменчивой энергией бури. Охота на этих зверей требует от воина выдерживать непрерывные удары тока и сокрушительные физические атаки. Почерневшая обожженная чешуя, содранная с их шкур, — бесспорное доказательство способности бойца переносить сокрушительные нападения и стоять там, где более слабые воины пали бы."},{t="Путь щита",b="На Дальней заставе на границе Дуротара и Степей воин-ветеран Уззек требует от новичков пять таких чешуек, прежде чем передать свои знания. По мнению Уззека, новичок должен обладать природной физической стойкостью, прежде чем постигнуть тонкую дисциплину стоек и тактической обороны. Предъявив чешую, воин показывает, что у него хватит стойкости соединить толстую шкуру, тяжелые доспехи и расчетливую работу ног в несокрушимую стену против врагов Орды."}},faq={{q="Для чего нужна оплавленная чешуя?",a="Оплавленная чешуя служит доказательством боевой выносливости. Учитель воинов Уззек требует пять штук, чтобы убедиться, что новичок обладает физической стойкостью, необходимой для изучения продвинутых приемов защиты.",al={"singed scale use","who wants singed scales","singed scale quest","применение оплавленной чешуи","кому нужна оплавленная чешуя","задание оплавленная чешуя"}},{q="Где найти оплавленную чешую?",a="Ее добывают у громовых ящеров и молниевых шкур, обитающих на Громовом хребте — в каньоне на западе Дуротара, прямо через реку от Степей.",al={"singed scale location","where to get singed scales","how to get singed scale","где найти оплавленную чешую","где взять оплавленную чешую","как получить оплавленную чешую"}},{q="Почему чешуя оплавленная?",a="Громовые ящеры пропускают через свои тела молнии и грозовые разряды. Постоянный треск стихийной энергии обжигает и чернит их внешнюю шкуру, придавая чешуе обугленный вид.",al={"why singed","why are the scales burnt","почему оплавленная","почему чешуя обожженная"}},{q="Кто такой Уззек и почему ему нужна эта чешуя?",a="Уззек — воин-ветеран, служащий на Дальней заставе в восточных Степях. Он обучает молодых воинов Орды защитному бою, но сначала требует, чтобы они доказали свою стойкость в схватках со смертоносными зверями.",al={"who is uzzek","uzzek","кто такой уззек","уззек"}}},fp="12,221,19.575.0,21.515.0,32.205.0,32.155.0,26.215.0,53.237.0"}
P.entries["item:skeleton-finger"] = {n="Палец скелета",s="Отрубленный костяной палец, добытый у ходячих мертвецов, бродящих по проклятым рощам и кладбищам Сумеречного леса. Мадам Ева из Темнолесья собирает эти жуткие остатки вместе с клыками вурдалаков и паучьим ядом для создания защитных талисманов.",h="Отрубленный костяной палец, добытый у ходячих мертвецов, бродящих по проклятым рощам и кладбищам Сумеречного...",kw={"darkshire","duskwood","ghoul fang","madame eva","skeletal raider","skeleton finger","totem of infliction","темнолесье","сумеречный лес","клык вурдалака","мадам ева","скелет-налетчик","палец скелета","тотем кары"},ang={["class:Mage"]="Маги, изучающие народные гадания, найдут метод Мадам Евы — превращать пальцы скелетов и природные яды в ответное зачарование — необычным сплавом деревенского колдовства и симпатической магии.",["class:Paladin"]="Паладины могут содрогаться от осквернения останков и ношения отрубленных частей, но в мрачной тьме Сумеречного леса использовать кости нечестивых для защиты живых — суровая необходимость."},sec={{t="Кости неупокоенных",b="Проклятый Сумеречный лес наводнен неупокоенными останками мертвецов — от скелетов-налетчиков и воинов до некротических магов и исчадий. Обычные путники избегают прикасаться к мерзким останкам восставших, но гадалки и мистики ценят их холодную сущность. Мадам Ева, местная провидица Темнолесья, собирает эти костяные пальцы, чтобы связать их остаточную некротическую энергию в оберег ответной магии — Тотем Кары."}},faq={{q="С каких существ падает палец скелета?",a="Пальцы скелетов добывают у разных скелетов-нежити Сумеречного леса, включая скелетов-налетчиков, лекарей, стражей, воинов, ужасов, исчадий и скелетов-магов.",al={"where do skeleton fingers drop","what drops skeleton fingers","skeleton finger source","где падает палец скелета","с кого падает палец скелета","источник пальца скелета"}},{q="Кому нужны пальцы скелетов в Сумеречном лесу?",a="Мадам Еве, гадалке из Темнолесья: они нужны как ритуальные компоненты для создания защитного оберега.",al={"who needs skeleton fingers","skeleton finger quest giver","what are skeleton fingers for","кому нужны пальцы скелетов","персонаж, выдающий задание пальцы скелета","для чего нужны пальцы скелетов"}},{q="Что такое Тотем Кары?",a="Это зачарованный оберег, который Мадам Ева создает из пальцев скелетов, клыков вурдалаков и паучьего яда. Она вплетает их темную энергию в ауру, наносящую ответный вред любому, кто попытается напасть на владельца.",al={"totem of infliction purpose","what does madame eva make","назначение тотема кары","что делает мадам ева"}},{q="Зачем Мадам Еве останки нежити для защитного амулета?",a="Ритуалы Мадам Евы направляют скрытую скверну и агрессию местных чудовищ. Соединяя яростные сущности скелетов, вурдалаков и ядовитых тварей Сумеречного леса, она превращает их собственную злобу в оберег, карающий враждебных нападающих.",al={"why bone magic","why skeleton fingers for totem","зачем костяная магия","зачем пальцы скелета для тотема"}}},fp="15,234,21.460.0,38.179.0,39.130.0,32.235.0,63.269.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Бурдюк со сладким ромом",s="Бурдюк со сладким ромом — особый напиток из таверны Гордость Льва в Златоземье. Его ищет Кабатчик Дэниэлс из Приозерья, отчаянно пытающийся пополнить запасы таверны, пока орки Черной Горы отрезали Красногорье от торговых путей.",h="Бурдюк со сладким ромом — особый напиток из таверны Гордость Льва в Златоземье.",kw={"barkeep daniels","dry times","goldshire","lakeshire","lion's pride inn","skin of sweet rum","sweet rum","кабатчик дэниэлс","засуха","златоземье","приозерье","таверна гордость льва","бурдюк со сладким ромом","сладкий ром"},ang={["faction:Alliance"]="Добыча этого рома показывает, какое логистическое бремя вторжение орков Черной Горы возложило на небольшие поселения, защищающие восточные границы королевства Штормград."},sec={{t="Редкое утешение для Приозерья",b="В измученном войной Приозерье запасы таверны опасно истощаются. Вторжение орков Черной горы перекрыло снабженческие дороги в Красногорье, и Кабатчик Дэниэлс изо всех сил пытается утолить жажду осажденных стражников и беженцев. Чтобы пополнить опустевшие полки, Дэниэлс отправляет путников по королевству за местными особенностями, в том числе за бурдюком с особым сладким ромом, который варят и подают в таверне Гордость Льва в Златоземье."}},faq={{q="Где найти бурдюк со сладким ромом?",a="Бурдюк со сладким ромом можно купить у трактирщика или кабатчика в таверне Гордость Льва в Златоземье, в Элвиннском лесу.",al={"sweet rum location","where buy sweet rum","who sells sweet rum","где найти сладкий ром","где купить сладкий ром","кто продает сладкий ром"}},{q="Кому нужен этот ром?",a="Кабатчику Дэниэлсу, хозяину таверны в Приозерье: он просит бурдюк сладкого рома вместе с несколькими другими местными напитками, чтобы пополнить запасы, в задании «Засуха».",al={"who needs sweet rum","sweet rum turn in","sweet rum quest","кому нужен сладкий ром","сдать сладкий ром","задание сладкий ром"}},{q="Почему в Приозерье заканчивается выпивка?",a="Внезапное усиление вторжения орков Черной Горы в Красногорье оборвало торговые связи и задержало поставки в город. Купеческие повозки не могут безопасно проехать по дорогам, и местные запасы почти иссякли.",al={"why are they out of booze","why lakeshire dry","dry times reason","почему нет выпивки","почему в приозерье сухо","причина засухи"}},{q="Какие еще напитки нужны вместе с ромом?",a="Помимо бурдюка со сладким ромом из Златоземья, Кабатчику Дэниэлсу нужны бочонок громоварского лагера из Западного Края, бочка мерло из Штормграда и бутылка самогона из Темнолесья.",al={"dry times drinks","daniels drinks list","other booze needed","напитки для засухи","список напитков дэниэлса","другая выпивка"}}},fp="17,252,28.488.0,37.140.0,19.186.0,39.216.0,48.196.0"}
P.entries["item:skittering-blood"] = {n="Летящая кровь",s="Летящая кровь — алхимический реагент, добываемый из паукообразных, обитающих в Струящейся Тьме Серебряного бора. Это важный ядовитый ингредиент для исследований Королевского фармацевтического общества над Новой чумой, призванной уничтожить и Плеть, и человечество.",h="Летящая кровь — алхимический реагент, добываемый из паукообразных, обитающих в Струящейся Тьме Серебряного...",kw={"faranell","new plague","renferrel","royal apothecary society","silverpine forest","skittering blood","skittering dark","skitterweb","фаранелл","новая чума","ренферрел","королевское фармацевтическое общество","серебряный бор","летящая кровь","струящаяся тьма","паутинник"},ang={["faction:Horde"]="Пока аптекари Отрекшихся рады сырью для защиты Лордерона, остальные члены Орды часто смотрят на ядовитые смеси из этой крови с моральным беспокойством.",["race:Undead"]="Передавая летящую кровь, вы напрямую помогаете королеве Сильване и Королевскому фармацевтическому обществу создать совершенное биологическое оружие против Артаса и живого человечества."},sec={{t="Ядовитый дистиллят",b="Эта ядовитая гемолимфа, добываемая у паучих-засадниц, охотников и их матери Кретис Тенепряхи, обладает вирулентными свойствами, ценимыми алхимиками Отрекшихся. Аптекарь Ренферрел обнаружил, что в сочетании с токсинами из сердец седых медведей эта кровь становится основой исключительно смертоносного эликсира. Соединения в жидкости проявляют сильное заражающее действие, что делает ее идеальным биологическим катализатором для химических опытов Апотекариума."},{t="Топливо для Новой чумы",b="Под руководством Мастера аптекаря Фаранелла в Подгороде Королевское фармацевтическое общество собирает реагенты вроде летящей крови, чтобы создать разрушительную Новую чуму. Перед лицом огромных орд Плети и враждебных остатков людей Отрекшиеся прибегают к биологической войне как к уравнителю сил. Фаранелл исследует ядовитую силу крови, чтобы создать заразу, способную уничтожить и нежить, и живую плоть."}},faq={{q="Для чего нужна летящая кровь?",a="Королевское фармацевтическое общество использует летящую кровь для создания Новой чумы Отрекшихся. Смешанная с токсинами из медвежьих сердец, она дает нестабильную смесь, которую изучает Мастер аптекарь Фаранелл, чтобы уничтожить и нежить Плети, и живых людей.",al={"skittering blood use","why gather spider blood","what does faranell do with skittering blood","применение летящей крови","зачем собирать паучью кровь","что фаранелл делает с летящей кровью"}},{q="Где найти летящую кровь?",a="Ее собирают с тел пауков Паутинного леса — засадников, охотников и Кретис Тенепряхи, — обитающих в Струящейся Тьме и вокруг нее, мрачном лесу, затянутом паутиной, на северо-западе Серебряного бора.",al={"where to get skittering blood","skittering blood location","who drops skittering blood","где взять летящую кровь","где находится летящая кровь","с кого падает летящая кровь"}},{q="Кто просит эти образцы?",a="Аптекарь Ренферрел в Гробнице в Серебряном бору поручает собирать кровь и велит искателям приключений доставить собранную жидкость прямо Мастеру аптекарю Фаранеллу в Апотекариум Подгорода.",al={"who wants skittering blood","quest giver for skittering blood","кому нужна летящая кровь","персонаж, выдающий задание летящая кровь"}},{q="Зачем Отрекшимся яд местных тварей?",a="Королевское фармацевтическое общество постоянно выделяет природные токсины из искаженной фауны Лордерона. Яд гигантских паукообразных Серебряного бора дает сырые биологические патогены, которые можно сконцентрировать и превратить в оружие — синтетические чумы.",al={"why spider venom","apothecary beast research","зачем паучий яд","исследования ядов зверей"}}},fp="16,277,18.498.0,22.420.0,34.266.0,32.226.0,27.229.0,49.251.0"}
P.entries["item:sleepers-key"] = {n="Ключ Спящих",s="Ключ Спящих — один из трех зачарованных ключей, созданных друидами ночных эльфов, чтобы запечатать их священное хранилище в Пещере Когтей на Пике Каменного Когтя. Он хранится в тайнике, запертом Ключом Хранителя Врат, и олицетворяет спящих друидов дикой природы, оберегающих глубочайшие тайны горы.",h="Ключ Спящих — один из трех зачарованных ключей, созданных друидами ночных эльфов, чтобы запечатать их...",kw={"gatekeeper's key","sleepers cache","sleepers key","sleepers' key","stonetalon peak","talon den","talon den hoard","the den","ключ хранителя врат","тайник спящих","ключ спящих","пик каменного когтя","пещера когтей","клад пещеры когтей","пещера"},ang={["class:Druid"]="Ключи и тайники Пещеры Когтей показывают многослойную защиту друидов ночных эльфов, использующих древние знания об Изумрудном Сне и могильниках, чтобы запечатать реликвии силы.",["faction:Horde"]="Получение Ключа Спящих — часть организованного набега в сердце Пика Каменного Когтя, чтобы снять защитные чары ночных эльфов и завладеть реликвиями из их клада."},sec={{t="Защита друидов",b="Пещера Когтей, высеченная на вершинах Пика Каменного Когтя, служит оплотом и святилищем друидов Калимдора. Зная, что их священные реликвии и могущественные сокровища могут привлечь нежелательное внимание, ночные эльфы-хранители создали сложную систему замков и тайников для защиты своих богатств. Ключ Спящих — треть этой защиты. Он лежит в уединенном тайнике в глубине пещеры, и достать его можно лишь Ключом Хранителя Врат, спрятанным у входа. Вместе с Ключом-когтем и Могильным ключом Ключ Спящих нужно вставить в каменные замки Клада Пещеры Когтей, чтобы снять защиту и открыть древние предметы внутри."}},faq={{q="Для чего нужен Ключ Спящих?",a="Ключ Спящих используется вместе с Могильным ключом и Ключом-когтем, чтобы открыть Клад Пещеры Когтей — защищенное каменное хранилище в глубине могильной пещеры на Пике Каменного Когтя.",al={"what does sleepers key do","sleepers key purpose","talon den hoard keys","что делает ключ спящих","назначение ключа спящих","ключи клада пещеры когтей"}},{q="Как был спрятан Ключ Спящих?",a="Друиды поместили его в Тайник Спящих в северо-западных туннелях Пещеры Когтей. Чтобы открыть тайник, нужен Ключ Хранителя Врат, который друиды спрятали в неприметном фонаре у входа в пещеру.",al={"where is sleepers key","opening sleepers cache","gatekeepers key requirement","где ключ спящих","открыть тайник спящих","нужен ключ хранителя врат"}},{q="Почему друиды спрятали реликвии с помощью нескольких ключей?",a="Друиды ночных эльфов создали сложные защитные средства, чтобы их могущественные предметы и священные реликвии никогда не попали в руки врага при нападении на пещеру. Ключи, разбросанные по тайникам, не давали захватчикам легко разграбить их клад.",al={"why so many keys","talon den defense","druid hoard puzzle","почему так много ключей","защита пещеры когтей","головоломка клада друидов"}},{q="Почему он называется Ключом Спящих?",a="Он назван в честь спящих друидов, погружающихся в глубокий транс, чтобы бродить по Изумрудному Сну. Как и Могильный ключ и Ключ-коготь, его название чтит священный долг и традиции кругов ночных эльфов в горах.",al={"who are the sleepers","sleepers key name meaning","кто такие спящие","значение названия ключа спящих"}}},fp="13,300,19.668.0,35.167.0,38.224.0,56.258.0,35.230.0"}
P.entries["item:smoky-iron-ingot"] = {n="Закопченый железный слиток",s="Закопченые железные слитки — грубо обработанные металлические бруски, выплавленные кобольдами с раскопок Ветрорезов в Когтистых горах. Орочьи бронники ценят эти слитки как сырье для ковки прочных кольчужных доспехов, достойных воинов Орды.",h="Закопченые железные слитки — грубо обработанные металлические бруски, выплавленные кобольдами с раскопок...",kw={"brutal armor","kobold","smoky iron ingot","stonetalon","thun'grim firegaze","warrior","windshear","доспехи жестокости","кобольд","закопченый железный слиток","когтистые горы","тун'грим огневзор","воин","ветрорезы"},ang={["class:Warrior"]="Для воинов Орды добыча этих слитков в Когтистых горах — испытание на выносливость и необходимый компонент для ковки хауберка жестокости.",["profession:Blacksmithing"]="Грубое качество этих слитков показывает примитивные способы плавки кобольдов-землекопов в сравнении с отточенными приемами опытных кузнецов."},sec={{t="Грубая металлургия кобольдов",b="В закопченных туннелях Утеса Ветрорезов в Когтистых горах кобольды глубоко вгрызаются в каменистую землю, добывают со склонов необработанную руду и плавят ее на грубых дымных кострах. Получившиеся закопченые железные слитки далеки от совершенства — они полны шлака и древесного угля, — но достаточно плотны, чтобы сохранять значительную прочность на разрыв."},{t="Ковка Доспехов Жестокости",b="Почти слепой орк-бронник Тун'грим Огневзор, работающий в суровом лагере с видом на Степи, особо просит такие слитки, когда создает доспехи для проверенных воинов Орды. В сочетании с очищенными железными слитками, порошком азурита и летучим флогистоном закопченый металл служит прочной основой для создания хауберков жестокости."}},faq={{q="Откуда берутся закопченые железные слитки?",a="Закопченые железные слитки носят с собой кобольды, населяющие раскопки и туннели Ветрорезов в восточной части Когтистых гор, в том числе землекопы, каменотесы, паразиты, геоманты и их повелители.",al={"where to find smoky iron ingot","smoky iron ingot location","who drops smoky iron ingots","где найти закопченый железный слиток","закопченый железный слиток где добыть","с кого падают закопченые железные слитки"}},{q="Для чего нужны закопченые железные слитки?",a="Их собирают воины, откликнувшиеся на призыв Тун'грима Огневзора, мастера-бронника, живущего на утесах возле Перекрестка в Степях. Для ковки легендарного хауберка жестокости ему нужно пятнадцать таких слитков.",al={"smoky iron ingot use","what is smoky iron ingot for","brutal armor quest item","применение закопченого железного слитка","для чего нужен закопченый железный слиток","доспехи жестокости задание"}},{q="Почему слитки называют «закопченными»?",a="Кобольды используют в своих тусклых туннелях грубые низкотемпературные способы плавки. Полученный металл сохраняет сажу, угольную пыль и золу из их дымных подземных печей и не очищается до чистого блеска.",al={"why is it smoky","smoky iron lore","почему закопченый","закопченое железо предания"}},{q="Может ли любой кузнец работать с этими слитками?",a="Нет. Закопченые железные слитки — неровные, покрытые сажей бруски, непригодные для обычного кузнечного дела. Лишь немногие кузнецы-специалисты, такие как Тун'грим Огневзор, умеют использовать их для создания особого боевого снаряжения.",al={"can players smith smoky iron","is smoky iron a trade good","можно ли ковать закопченое железо","торговый товар закопченое железо"}}},fp="16,233,23.354.0,24.338.0,37.202.0,36.215.0,40.215.0,43.196.0"}
P.entries["item:smoldering-embers"] = {n="Тлеющие угли",s="Тлеющие угли — раскаленные, пропитанные жаром останки, добываемые с яростных элементалей огня Обугленной долины. Часовые ночных эльфов отслеживают эти угли как вещественное доказательство того, что огненных чудовищ, терзающих опустошенные леса, удается подавить.",h="Тлеющие угли — раскаленные, пропитанные жаром останки, добываемые с яростных элементалей огня Обугленной...",kw={"burning destroyer","burning ravager","charred vale","enraged spirits","kaela shadowspear","rogue flame spirit","smoldering embers","stonetalon","venture co","пылающий разрушитель","пылающий разоритель","обугленная долина","яростные духи","кела копье тени","дух пламени-изгой","тлеющие угли","когтистые горы","торговая компания"},ang={["class:Druid"]="Друиды видят в углях печальное свидетельство природы, нарушенной промышленной алчностью, где необузданная ярость стихий не дает покрытой пеплом почве возродиться.",["race:NightElf"]="Для ночных эльфов вид Обугленной долины в огне — горестная рана на теле Калимдора. Сбор этих углей — священный долг: очистить землю от чужеродного осквернения и вернуть мир под взор Эльюны."},sec={{t="Остатки Обугленной долины",b="Беспощадная вырубка и промышленное опустошение Торговой Компании прошлись по Обугленной долине, подожгли лес и выпустили разрушительную ярость из глубин земли. Следом за ними по выжженной котловине хлынули элементали живого огня — пылающие разорители, пылающие разрушители и бродячие духи пламени-изгои. Тлеющие угли — это оставшиеся покрытые пеплом ядра, которые остаются после уничтожения элементаля; они служат доказательством того, что неистовые пожары долины планомерно подавляются."}},faq={{q="Откуда берутся тлеющие угли?",a="Тлеющие угли собирают с огненных элементалей, обитающих в Обугленной долине на юге Когтистых гор, в том числе с пылающих разорителей, пылающих разрушителей и духов пламени-изгоев.",al={"where do i find smoldering embers","who drops smoldering embers","smoldering ember source","где найти тлеющие угли","с кого падают тлеющие угли","источник тлеющих углей"}},{q="Зачем Келе Копье Тени эти угли?",a="Кела Копье Тени ищет их как неопровержимое доказательство того, что неистовых огненных элементалей в Обугленной долине истребляют. Она считает, что израненная земля никогда не исцелится по милости Эльюны, пока эти яростные духи бродят безнаказанно.",al={"why collect smoldering embers","kaela shadowspear embers","enraged spirits goal","зачем собирать тлеющие угли","кела копье тени угли","цель яростные духи"}},{q="Что вызвало появление огненных элементалей в Обугленной долине?",a="Торговая Компания использовала агрессивные механизмы и беспорядочные поджоги, чтобы расчистить древний лес. Их безрассудная эксплуатация нарушила равновесие земли, вскрыв и выпустив враждебных элементалей огня и камня, которые в итоге выгнали гоблинов.",al={"what happened to charred vale","why are there fire elementals in stonetalon","venture co fire spirits","что случилось с обугленной долиной","почему в когтистых горах огненные элементали","торговая компания огненные духи"}}},fp="17,253,28.538.0,37.189.0,45.228.0,62.255.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Табакерка Снеллига",s="Табакерка Снеллига — личная памятная вещь, добытая у неупокоенного первого помощника Снеллига среди обломков Погибшего Флота. Если вернуть эту безделушку Первому помощнику Фитсиммонсу в Гавани Менетилов, это станет доказательством того, что его проклятый бывший товарищ наконец обрел покой.",h="Табакерка Снеллига — личная памятная вещь, добытая у неупокоенного первого помощника Снеллига среди обломков...",kw={"cursed crew","fitzsimmons","kul tiras","lost fleet","snellig","snuffbox","third fleet","wetlands","проклятая команда","фитсиммонс","кул тирас","погибший флот","снеллиг","табакерка","третья флотилия","болотина"},ang={["faction:Alliance"]="Вернуть вещи павших култирасских моряков и упокоить их проклятые души — мрачный долг перед давним морским союзником Альянса."},sec={{t="Память о Третьей флотилии",b="Когда Третья флотилия Кул Тираса села на мель у северных берегов Болотины, ее матросы и офицеры не обрели мирной смерти. Скованные таинственной темной силой, связанной со спрятанным на кораблях сокровищем, утонувшие члены команды восстали вновь как измученные духи и скелеты-нежить. Среди них был первый помощник Снеллиг, который до сих пор бродит по гниющему трюму ближайшего к берегу корабля. Даже после смерти он держался за свою табакерку — маленькое будничное напоминание о земной жизни на море. Для единственного выжившего в катастрофе, Первого помощника Фитсиммонса, возвращение этой вещицы — ощутимое доказательство того, что хотя бы один из его погибших товарищей освобожден от вечных мук."}},faq={{q="Что такое Табакерка Снеллига?",a="Это небольшая личная коробочка, когда-то принадлежавшая первому помощнику Снеллигу, офицеру несчастной Третьей флотилии Кул Тираса. Ее носит его неупокоенный остаток на борту кораблекрушений у северного побережья Болотины.",al={"what is this item","snelligs snuffbox","snuff box","что это за предмет","табакерка снеллига","табакерка"}},{q="Где найти Табакерку Снеллига?",a="Табакерку забирают у первого помощника Снеллига, который бродит по трюму южного разбитого корабля, ближайшего к берегу, у Погибшего Флота на северо-востоке Болотины.",al={"where does snellig drop snuffbox","find snellig","first mate snellig location","где снеллиг роняет табакерку","найти снеллига","первый помощник снеллиг где находится"}},{q="Кому нужна эта табакерка?",a="Первый помощник Фитсиммонс, единственный выживший из Третьей флотилии, просит искателей приключений принести ему табакерку в Гавань Менетилов как доказательство того, что Снеллиг упокоен.",al={"who takes the snuffbox","who do i turn this into","fitzsimmons quest","кто принимает табакерку","кому сдать табакерку","задание фитсиммонса"}},{q="Почему первый помощник Снеллиг проклят?",a="По словам Фитсиммонса, темное и ужасное сокровище, спрятанное на одном из кораблей Третьей флотилии, обрекло команды при крушении, заточив их души в гниющих досках и лишив покоя.",al={"why is snellig undead","lost fleet curse","curse of third fleet","почему снеллиг нежить","проклятие погибшего флота","проклятие третьей флотилии"}}},fp="18,283,29.710.0,27.215.0,35.157.0,24.174.0,33.204.0"}
P.entries["item:snufflenose-command-stick"] = {n="Палочка-погонялочка для шмыгуносов",s="Палочка-погонялочка для шмыгуносов — тренировочный жезл, выдаваемый гоблином-предпринимателем Мебоком Миззриксом в Кабестане. С его помощью направляют обученных шмыгуносов-гоферов, чтобы они находили и откапывали ценные корни синелиста, зарытые глубоко в Лабиринтах Иглошкурых.",h="Палочка-погонялочка для шмыгуносов — тренировочный жезл, выдаваемый гоблином-предпринимателем Мебоком...",kw={"blueleaf tuber","command stick","gopher","mebok mizzyrix","ratchet","razorfen kraul","snufflenose","the barrens","корни синелиста","палочка-погонялочка","гофер","мебок миззрикс","кабестан","лабиринты иглошкурых","шмыгунос","степи"},ang={["profession:Cooking"]="Хотя корни синелиста считаются изысканным кулинарным деликатесом по всему миру, для их добычи нужны обученный зверек и палочка погонщика, а не обычные кухонные инструменты."},sec={{t="Жезл для грызунов",b="Корни синелиста — желанный деликатес по всему Азероту, но найти их почти невозможно без особой помощи. Зарытые в колючих подземных глубинах Лабиринтов Иглошкурых, корни полностью скрыты от глаз. Чтобы воспользоваться этим прибыльным рынком, не рискуя соваться в логова свинобразов самому, торговец из Кабестана Мебок Миззрикс приучил чутких шмыгуносов-гоферов выкапывать корни. Палочка-погонялочка для шмыгуносов — инструмент, которым искатели приключений направляют этих обученных зверьков, заставляя их вынюхивать и обнаруживать корневые залежи на расстоянии до пятидесяти шагов."}},faq={{q="Для чего нужна Палочка-погонялочка для шмыгуносов?",a="Палочкой приказывают обученному шмыгуносу-гоферу искать скрытые корни синелиста в колючих туннелях Лабиринтов Иглошкурых. Если направить жезл на призванного гофера, он идет по запаху и выкапывает корневые залежи.",al={"how to use command stick","what does command stick do","command stick purpose","как пользоваться палочкой-погонялочкой","что делает палочка-погонялочка","назначение палочки-погонялочки"}},{q="Где получить Палочку-погонялочку для шмыгуносов?",a="Ее можно взять в Кабестане в Степях прямо у мастерской Мебока Миззрикса, рядом с ящиком, в котором лежат обученный гофер и справочник.",al={"where to get command stick","command stick location","who gives the command stick","где взять палочку-погонялочку","где находится палочка-погонялочка","кто выдает палочку-погонялочку"}},{q="Зачем Мебоку Миззриксу корни синелиста?",a="Корни синелиста — редкий деликатес, который с большой выгодой продается состоятельным кулинарным знатокам по всему миру. Поскольку они растут только глубоко под Степями на территории свинобразов, Мебок нанимает искателей приключений для их сбора.",al={"why tubers","blueleaf tuber purpose","why does mebok want tubers","зачем корни","назначение корней синелиста","зачем мебоку корни"}},{q="Остается ли палочка у вас после сбора корней?",a="Нет. Когда вы соберете нужные корни, Мебок требует вернуть ему в Кабестане и палочку, и транспортный ящик вместе с добычей.",al={"can i keep command stick","returning command stick","можно ли оставить палочку-погонялочку","вернуть палочку-погонялочку"}}},fp="25,241,17.569.0,47.250.0,50.159.0,45.231.0,54.165.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Справочник владельца Шмыгуноса",s="Справочник владельца Шмыгуноса — инструктивная брошюра Марвига Ржавоболта из компании «Понюшка», хранящаяся рядом с гоблином-предпринимателем Мебоком Миззриксом в Кабестане. В ней описано, как выпускать и направлять обученного шмыгуноса-гофера, чтобы находить редкие корни синелиста, зарытые в Лабиринтах Иглошкурых.",h="Справочник владельца Шмыгуноса — инструктивная брошюра Марвига Ржавоболта из компании «Понюшка», хранящаяся...",kw={"blueleaf tuber","gopher","manual","mebok mizzyrix","ratchet","razorfen kraul","snufflenose","корни синелиста","гофер","справочник","мебок миззрикс","кабестан","лабиринты иглошкурых","шмыгунос"},ang={["profession:Cooking"]="В справочнике описан процесс добычи корней синелиста — подземного корнеплода, считающегося редким деликатесом у гурманов и торговцев по всему Азероту."},sec={{t="Руководство по эксплуатации от гоблина",b="Это краткое руководство, написанное Марвигом Ржавоболтом, владельцем компании «Понюшка», рассказывает, как работать с обученными шмыгуносами-гоферами компании. Эти звери обладают острым чутьем и способны обнаружить подземные корни синелиста за пятьдесят шагов. Справочник учит старателей выпускать гофера из вентилируемого ящика и направлять его роющий инстинкт палочкой-погонялочкой, ведя зверька сквозь враждебные колючки и туннели свинобразов Лабиринтов Иглошкурых к желанным кулинарным деликатесам."}},faq={{q="Для чего нужен Справочник владельца Шмыгуноса?",a="Это инструкция по обращению с обученными шмыгуносами-гоферами Мебока Миззрикса. Искатели приключений читают ее, чтобы понять, как выпустить зверька из ящика и направить его палочкой-погонялочкой на поиски зарытых корней синелиста в Лабиринтах Иглошкурых.",al={"what does the manual do","why read the manual","manual purpose","что дает справочник","зачем читать справочник","назначение справочника"}},{q="Где найти справочник?",a="Справочник хранится в Кабестане в Степях, прямо возле Мебока Миззрикса, рядом со специальными ящиками и палочками-погонялочками, нужными для сбора корней.",al={"manual location","where is the book","how to get the manual","где справочник","где книга","как получить справочник"}},{q="Зачем нужны шмыгуносы-гоферы для поиска корней синелиста?",a="Корни синелиста растут скрытно глубоко в земле в Лабиринтах Иглошкурых, и гуманоиды почти не способны их заметить. У обученных гоферов острое чутье, и они чуют запах зарытого корня за пятьдесят шагов.",al={"why use gophers","can i find tubers without gophers","зачем гоферы","можно ли найти корни без гоферов"}},{q="Кто написал справочник?",a="Он подписан Марвигом Ржавоболтом, владельцем компании «Понюшка», который написал его, чтобы научить новых владельцев кормить, выгуливать гоферов и командовать ими с помощью запатентованной палочки-погонялочки.",al={"author of manual","who made it","автор справочника","кто сделал"}}},fp="26,280,26.513.0,54.249.0,28.152.0,59.233.0,21.163.0"}
P.entries["item:sodium-nitrate"] = {n="Натриевая селитра",s="Натриевая селитра — нестабильный химический реагент, который носят дворфийские землекопы и гарнизон, расквартированные в Бейл Модане на юге Степей. Хотя экспедиция Стальгорна привезла ее, чтобы взрывать древний камень, изгнанный таурен Ганн Каменное Копье стремится забрать ее и собрать взрывной заряд против захватчиков.",h="Натриевая селитра — нестабильный химический реагент, который носят дворфийские землекопы и гарнизон...",kw={"bael modan","bael'dun","blackforge","gann stonespire","nitroglycerin","revenge of gann","sodium nitrate","wood pulp","бейл модан","бейл'дан","черноков","ганн каменное копье","нитроглицерин","месть ганна","натриевая селитра","древесная масса"},ang={["profession:Engineering"]="Инженеры сразу узнают в сочетании натриевой селитры, нитроглицерина и древесной массы классический рецепт стабилизированного динамита, что подтверждает железную логику самодельных подрывных зарядов Ганна.",["race:Tauren"]="Для тауренов использование дворфийских химикатов — горькое отступление от традиций, но Ганн Каменное Копье считает отчаянные меры оправданными ради ответа на разорение земель предков."},sec={{t="Промышленные подрывные работы",b="Экспедиция Бейл'дана вторглась в земли предков племени Каменного Копья, вооружившись тяжелой землеройной техникой и взрывчатыми реагентами. Чтобы вскрыть упрямые каменные пласты юга Степей, дворфы использовали нестабильные химические соединения. Натриевая селитра — важный стабилизирующий и окисляющий компонент мощной взрывчатки; ее обычно носят с собой стрелки, солдаты и офицеры Бейл'дана на раскопках и в соседней крепости."},{t="Месть и расплата",b="После разорения родных земель своего племени Ганн Каменное Копье внимательно следил за захватчиками и собирал их инженерные чертежи. Поняв, что обычными атаками хорошо защищенную крепость не взять, Ганн решил обратить промышленные взрывчатые припасы дворфов против них самих. Смешивая похищенную натриевую селитру с нитроглицерином и древесной массой, изгнанный таурен мастерит самодельные заряды, способные потрясти основания Бейл Модана."}},faq={{q="Для чего нужна натриевая селитра в Степях?",a="Дворфы Стальгорна используют ее как химический компонент взрывчатки, чтобы взрывать скалистую местность на месте раскопок. Ганн Каменное Копье намерен смешать ее с нитроглицерином и древесной массой, чтобы создать мощные подрывные заряды и нанести ответный удар по крепости Бейл Модан.",al={"sodium nitrate purpose","what does sodium nitrate do","для чего нужна натриевая селитра","что делает натриевая селитра"}},{q="Откуда берется натриевая селитра?",a="Она есть у дворфийских военных, расквартированных в Бейл Модане на юге Степей. Солдаты, стрелки, офицеры и их командиры, например лорд Сайрик Черноков, носят запасы реагента при себе.",al={"who drops sodium nitrate","where to get sodium nitrate","с кого падает натриевая селитра","где достать натриевую селитру"}},{q="Зачем Ганну Каменному Копью это вещество?",a="Ганн потерял родную деревню из-за дворфийских раскопок. Не имея тяжелой осадной техники, он изучил дворфийские чертежи, чтобы воспроизвести их горные заряды и разрушить их укрепленные позиции их же боеприпасами.",al={"why does gann want sodium nitrate","gann stonespire explosives","зачем ганну натриевая селитра","ганн каменное копье взрывчатка"}},{q="Опасна ли натриевая селитра сама по себе?",a="Сама по себе натриевая селитра — окислитель и химическая соль, а не мгновенная взрывчатка. Она становится опасной и нестабильной, если правильно смешать ее с горючим и чувствительными к удару веществами вроде нитроглицерина.",al={"is sodium nitrate an explosive","взрывоопасна ли натриевая селитра","натриевая селитра взрывчатка"}}},fp="14,325,21.442.0,25.465.1,47.266.0,36.206.0,44.225.0,39.216.0"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Обращение Соломона к Темнолесью",s="Обращение Соломона к Темнолесью — срочное послание мирового судьи Соломона из Приозерья, адресованное лорду Элло Чернодреву. Перед лицом растущей угрозы со стороны орков Черной горы и гноллов письмо умоляет руководство Темнолесья направить элитное ополчение, Ночной Дозор, для усиления изнуренной обороны Приозерья.",h="Обращение Соломона к Темнолесью — срочное послание мирового судьи Соломона из Приозерья, адресованное лорду...",kw={"darkshire","duskwood","lakeshire","lord ello ebonlocke","magistrate solomon","messenger to darkshire","night watch","redridge","solomon's plea","темнолесье","сумеречный лес","приозерье","лорд элло чернодрев","мировой судья соломон","посыльный в темнолесье","ночной дозор","красногорье","обращение соломона"},ang={["faction:Alliance"]="Послание показывает раскол южных земель Великого Альянса, где далеким поселениям приходится умолять друг друга о помощи, пока Штормград остается равнодушным.",["race:Human"]="Для путешествующих людей доставка этого послания показывает общую опасность, грозящую и границам Красногорья, и мрачным чащам Сумеречного леса."},sec={{t="Отчаянный призыв о помощи",b="Приозерье вот-вот будет захвачено орками Черной горы, гноллами и мурлоками, а официальная помощь из Штормграда почти не приходит. В отчаянии мировой судья Соломон составил это официальное обращение к мэру Темнолесья Элло Эбонлоку с просьбой направить бойцов Ночного Дозора на север, в Красногорье. Документ отражает глубокий упадок военной поддержки центра на юге Азерота, из-за которого человеческим поселениям приходится рассчитывать друг на друга ради выживания."},{t="Мрачное положение Темнолесья",b="Хотя просьба Соломона срочная, она подчеркивает, что Приозерье не знает истинных ужасов, терзающих его соседей. Сам Сумеречный лес осажден нежитью, голодными тварями и всепроникающей тьмой, и Ночной Дозор уже предельно перегружен защитой границ деревни. Вместо свежего резерва солдат гонцы, доставившие прошение, находят город в столь же бедственном положении, не способный выделить защитников для Красногорья."}},faq={{q="Что такое «Обращение Соломона к Темнолесью»?",a="Это официальное письмо мирового судьи Соломона из Приозерья к лорду Элло Чернодреву, градоначальнику Темнолесья. В послании срочно содержится просьба к Темнолесью направить ополчение, Ночной Дозор, для защиты Красногорья от орков Черной горы и гноллов.",al={"solomons letter to darkshire","what is solomons plea","lakeshire letter to duskwood","письмо соломона в темнолесье","что такое обращение соломона","письмо из приозерья в сумеречный лес"}},{q="Почему Приозерье просит о военной помощи Темнолесье, а не Штормград?",a="Центральное правительство Штормграда в основном не смогло обеспечить окраины достаточными гарнизонными войсками из-за политической инертности и внутренних раздоров. Оставшись один на один с растущими вторжениями, мировой судья Соломон обратился к соседним человеческим поселениям в надежде получить союзные силы.",al={"why ask darkshire","why not stormwind","why does solomon need night watch","почему просят темнолесье","почему не штормград","зачем соломону ночной дозор"}},{q="Кто такой лорд Элло Чернодрев?",a="Лорд Элло Чернодрев — градоначальник и главный гражданский руководитель Темнолесья в Сумеречном лесу. Он управляет городом и координирует Ночной Дозор, гражданские силы обороны, сдерживающие ужасы, таящиеся в лесу.",al={"who is ebonlocke","mayor of darkshire","lord ello","кто такой чернодрев","градоначальник темнолесья","лорд элло"}},{q="Может ли Темнолесье на самом деле выделить Ночной Дозор для помощи Приозерью?",a="Нет. Сумеречный лес охвачен собственным кошмаром: вокруг нежить, дикие воргены и темная магия. Ночному Дозору едва хватает людей, чтобы удерживать периметр Темнолесья, и он не может выделить ни одного бойца для похода в Красногорье.",al={"does darkshire help","will the night watch come","did ebonlocke send guards","поможет ли темнолесье","придет ли ночной дозор","прислал ли чернодрев стражу"}}},fp="27,313,24.521.0,23.468.1,36.274.0,73.318.0,27.226.0,63.228.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Обращение Соломона к Западному Краю",s="Обращение Соломона к Западному Краю — срочное письменное прошение мирового судьи Соломона из Приозерья. Отчаянно нуждаясь в подкреплении против орков Черной горы и гноллов, Соломон отправляет это послание Гриану Камнегриву в Западный Край, надеясь, что недавно созданное Народное ополчение поможет, пока королевская армия Штормграда не отвечает.",h="Обращение Соломона к Западному Краю — срочное письменное прошение мирового судьи Соломона из Приозерья.",kw={"gryan stoutmantle","lakeshire","magistrate solomon","people's militia","redridge","solomon's plea","stormwind army","westfall","гриан камнегрив","приозерье","мировой судья соломон","народное ополчение","красногорье","обращение соломона","армия штормграда","западный край"},ang={["faction:Alliance"]="Документ показывает нарастающий управленческий паралич в сердце земель Альянса, где окраинным городам приходится полагаться на местных добровольцев, а не на королевские войска.",["race:Human"]="Для людей южных провинций это прошение показывает, насколько ослаблены сельские поселения: пропавший король и политическое небрежение оставляют пограничные земли уязвимыми."},sec={{t="Отчаянный призыв о помощи",b="Пока угроза клана Черной горы и враждебных гноллов нависает над Красногорьем, мировой судья Соломон оказывается в опасной изоляции в Приозерье. Королевская армия Штормграда необъяснимым образом так и не прибыла в силе защищать границы региона. Не в силах ждать официальной помощи из столицы королевства, Соломон пишет это прошение в отчаянной попытке привлечь помощь вне обычной военной структуры. Услышав о добровольческих силах обороны, собирающихся в Элвиннском лесу к западу, он обращается прямо к Народному ополчению."},{t="Через границу",b="Послание адресовано лично Гриану Камнегриву, ветерану-воину, организующему оборону рубежей Западного Края. Соломон надеется, что Камнегрив сможет выделить бойцов для усиления Приозерья, пока корона Штормграда наконец не пришлет регулярные резервы. Документ, доверенный искателю приключений в роли гонца, отражает разлад управленческой координации на окраинах Штормграда, где местным судьям приходится по собственной инициативе договариваться о взаимопомощи."}},faq={{q="Что такое «Обращение Соломона к Западному Краю»?",a="Это официальное письменное прошение мирового судьи Соломона из Приозерья, в котором он просит Гриана Камнегрива и Народное ополчение в Западном Крае прислать военные подкрепления для защиты Красногорья.",al={"what is solomon's plea","solomon plea to westfall letter","lakeshire westfall letter","что такое обращение соломона","письмо соломона в западный край","письмо из приозерья в западный край"}},{q="Почему мировой судья Соломон просит помощи у Западного Края, а не у Штормграда?",a="Соломон отмечает, что с Армией Штормграда происходит что-то странное: королевские войска не прибыли в силе, несмотря на усугубляющуюся опасность для Приозерья. Не имея времени ждать корону, Соломон обращается к любой ближайшей боевой силе, готовой помочь.",al={"why ask westfall","why not ask stormwind","why send plea to westfall","почему просят западный край","почему не просят штормград","зачем посылать обращение в западный край"}},{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — заслуженный ветеран Второй войны, возглавляющий Народное ополчение, низовую оборонительную лигу, организованную местными фермерами и поселенцами для защиты Западного Края от Братства Справедливости.",al={"who is stoutmantle","gryan stoutmantle role","кто такой камнегрив","гриан камнегрив роль"}},{q="Какие угрозы заставили Соломона отправить это письмо?",a="Приозерью угрожают агрессивные вторжения орков Черной горы, а также набеги гноллов по всему Красногорью, из-за чего местная городская стража измотана сверх предела.",al={"why is lakeshire in danger","what threatens redridge","почему приозерью грозит опасность","что угрожает красногорью"}}},fp="26,327,24.556.0,26.487.0,35.197.0,72.257.0,25.210.0,53.177.0"}
P.entries["item:soran-ruk-fragment"] = {n="Фрагмент Соран'рука",s="Фрагмент Соран'рука — расколотый осколок демонической сферы-темницы, некогда связанной с духом опального слуги Пылающего Легиона. Хотя сфера разбита и рассеяна среди культистов в глубинах Ясеневого леса, каждый осколок все еще излучает остаточную энергию скверны.",h="Фрагмент Соран'рука — расколотый осколок демонической сферы-темницы, некогда связанной с духом опального...",kw={"blackfathom deeps","doan karhan","fel","orb of soran'ruk","soran'ruk","soranruk","twilight acolyte","непроглядная пучина","доан кархан","скверна","сфера соран'рука","соран'рук","сумеречный послушник"},ang={["class:Warlock"]="Демонические сосуды-темницы вроде Сферы Соран'рука — ценные проводники для чернокнижников, стремящихся подчинять и направлять сырую энергию скверны без прямого порабощения демона."},sec={{t="Расколотая темница",b="Когда демоны Пылающего Легиона теряют расположение хозяев, их духи порой обрекают на заточение в особых сферах и раздают чернокнижникам скверны как проводники сырой силы. Такая участь постигла сферу Соран'рука, но где-то в ее истории она раскололась. Одна половина была разбита на мелкие осколки и попала в руки культистов Сумеречного Молота, обитающих в затопленных руинах Непроглядной Пучины; они черпают остатки демонической сущности для своих темных дел."},{t="Восстановление в Степях",b="Несмотря на раздробленность, каждый фрагмент хранит след жизненной силы заключенного существа. На юге Степей затворник-ученый Доан Кархан всю жизнь изучал эти демонические сосуды, и у него есть похожая сфера — Сфера Заргаина. Добыв три малых осколка вместе с крупным фрагментом, хранящимся в Серебряном бору, амбициозный чернокнижник может вновь выковать реликвию целой, как орудие власти."}},faq={{q="Кто такой Соран'рук?",a="Соран'рук был демоном Пылающего Легиона, впавшим в немилость у демонического руководства. В наказание его дух извлекли и заточили в кристаллическую сферу, чтобы он служил смертным чернокнижникам и магам хранилищем энергии.",al={"who is soranruk","soran'ruk lore","is soranruk a demon","кто такой соран'рук","предание о соран'руке","демон ли соран'рук"}},{q="Где находят эти фрагменты?",a="Малые осколки носят Сумеречные послушники в пещерных залах Непроглядной Пучины на Зорамском взморье.",al={"where to get soranruk fragment","who drops soran'ruk fragments","soranruk fragment location","где достать фрагмент соран'рука","с кого падают фрагменты соран'рука","где фрагмент соран'рука"}},{q="Почему эти осколки есть у Сумеречного Молота?",a="Даже разбитые, осколки сохраняют магическую сущность заточенного демона. Культисты Сумеречного Молота подбирают такие оскверненные артефакты, чтобы питать свои темные ритуалы и направлять запретную магию.",al={"why do cultists have it","twilights hammer soranruk","почему у культистов он есть","сумеречный молот соран'рук"}},{q="Кто может восстановить Сферу Соран'рука?",a="Доан Кархан, отшельник-одиночка, живущий на юге Степей возле границы Тысячи Игл, специализируется на изучении и перековке демонических сфер Легиона.",al={"who fixes the orb","where to turn in soranruk fragment","doan karhan orb","кто чинит сферу","куда сдать фрагмент соран'рука","доан кархан сфера"}}},fp="18,249,18.527.0,29.424.1,18.226.0,32.123.0,49.203.0,37.168.0"}
P.entries["item:southsea-treasure"] = {n="Сокровище Южного моря",s="Сокровище Южного моря — ценный клад, хранящийся в глубине трюма корабля флибустьеров Южных морей «Приливный Клинок». Его ищет Реникс Презренный в Кабестане, и добыча клада проверяет навыки взлома замков и проникновения у начинающих воров.",h="Сокровище Южного моря — ценный клад, хранящийся в глубине трюма корабля флибустьеров Южных морей «Приливный...",kw={"e.c.a.c.","lockpicking","polly","ratchet","shattered hand","southsea treasure","tide razor","wrenix the wretched","хочу","взлом замков","полли","кабестан","изувеченная длань","сокровище южного моря","приливный клинок","реникс презренный"},ang={["class:Rogue"]="Добыча Сокровища Южного моря — обряд посвящения для растущих разбойников: это и настоящая практика взлома замков, и знакомство с теневым синдикатом, известным как Изувеченная Длань.",["faction:Horde"]="Флибустьеры Южных морей регулярно досаждают торговле в Степях и порту Кабестана, поэтому любая кража их главного тайника — желанная помеха для местных властей."},sec={{t="Смертельное ограбление",b="Пиратский корабль «Приливный Клинок» стоит на якоре у Торгового побережья к югу от Кабестана и служит передовой базой и учебной площадкой для Флибустьеров Южных морей. В самом нижнем трюме спрятан желанный клад добычи — Сокровище Южного моря. Реникс Презренный, гоблин-мошенник из Кабестана, считает его высшим испытанием для начинающих карманников. По словам Реникса, последние пять лазутчиков, посланных похитить сундук, вернулись по частям: на борту бдительные пираты, а трюм охраняет на удивление свирепый страж."},{t="Память о Полли",b="Воры, сумевшие обойти пиратов-наставников и вскрыть замок нужного сундука, обнаруживают злобный сюрприз. Настоящее Сокровище Южного моря не лежит в ларце просто так: его охраняет Полли, неестественно враждебный попугай. Одолеть свирепую птицу — часто с помощью гоблинских изобретений вроде устройства ХОЧУ у Реникса — единственный способ забрать сокровище и в целости доставить его в Кабестан."}},faq={{q="Где находится Сокровище Южного моря?",a="Сокровище хранится на борту «Приливного Клинка», корабля Флибустьеров Южных морей, что стоит на якоре у побережья к югу от Кабестана в Степях. Оно лежит в нижнем трюме под учебными помещениями пиратов.",al={"where is the treasure","tide razor location","how to find southsea treasure","где сокровище","где находится приливный клинок","как найти сокровище южного моря"}},{q="Кому нужно Сокровище Южного моря?",a="Реникс Презренный, беспринципный гоблин из Кабестана, нанимает тайных агентов, чтобы они проникли на корабль и забрали добычу для него.",al={"who gives the quest","who is wrenix","who wants it","кто выдает задание","кто такой реникс","кому оно нужно"}},{q="Почему сундук пуст после взлома?",a="Взлом замка сундука с сокровищем вызывает появление Полли, чудовищно агрессивного попугая, охраняющего трюм. Сокровище Южного моря достается только после победы над Полли.",al={"where did polly come from","why did polly spawn","why isn't the treasure in the box","откуда взялась полли","почему появилась полли","почему сокровища нет в сундуке"}},{q="Что такое ХОЧУ и зачем оно нужно?",a="ХОЧУ — экспериментальное гоблинское устройство, которое выдает Реникс Презренный. Оно предназначено для ослабления необычайно свирепых летающих противников — в частности, смертоносного попугая-стража Полли, скрывающегося в трюме пиратского корабля.",al={"what is ecac","how to beat polly","hostile parrot","что такое хочу","как победить полли","враждебный попугай"}},{q="Для чего Флибустьеры Южных морей используют корабль?",a="«Приливный Клинок» служит для Флибустьеров Южных морей опорной базой и воровским логовом: на втором уровне там стоят учебные сундуки, на которых команда тренирует своих головорезов.",al={"what is tide razor","pirate den barrens","southsea ship hold","что такое приливный клинок","пиратское логово степи","трюм корабля южных морей"}}},fp="17,242,14.555.0,16.443.1,39.196.0,32.148.0,35.186.1,41.227.0,50.176.0"}
P.entries["item:spectral-comb"] = {n="Призрачный гребень",s="Призрачный гребень — неосязаемый инструмент для ухода за волосами, который используют при общении с неупокоенными мертвецами Сумеречного леса. Он создан так, чтобы проходить сквозь бестелесные формы, и его приносят скорбному духу Слепой Мэри, чтобы собрать пряди призрачных волос.",h="Призрачный гребень — неосязаемый инструмент для ухода за волосами, который используют при общении с...",kw={"blind mary","comb","darkshire","duskwood","ghost","ghost hair thread","spectral comb","слепая мэри","гребень","темнолесье","сумеречный лес","призрак","прядь призрачных волос","призрачный гребень"},ang={["faction:Alliance"]="Путь с гребнем к югу от Темнолесья напоминает о трагических судьбах бывших поселенцев Сумеречного леса.",["profession:Tailoring"]="Призрачный гребень показывает, что портняжное дело в мрачных местах требует необычных способов сбора: призрачные волокна получают у согласных призраков, а не обычной стрижкой."},sec={{t="Инструмент для неупокоенных",b="Обычные предметы не могут коснуться духа или расчесать его, поэтому смертным мастерам почти невозможно собрать неосязаемые материалы. Призрачный гребень особенно подходит для работы с призрачными формами: он скользит сквозь иначе неосязаемые пряди. Его несут к югу от Темнолесья, на разрушенную ферму, где в одиночестве рыдает плачущий призрак Слепая Мэри. Находя утешение в привычном занятии — расчесывании испорченных волос, — Мэри охотно пользуется гребнем и оставляет призрачные волокна, нужные для плетения Пряди призрачных волос."}},faq={{q="Для чего нужен Призрачный гребень?",a="Гребень отдают Слепой Мэри, плачущему призраку, обитающему к югу от Темнолесья. Когда она расчесывает им волосы, на нем остаются призрачные пряди, из которых позже можно спрясть сверхъестественную нить.",al={"spectral comb purpose","why do i need spectral comb","what does the comb do","зачем призрачный гребень","почему мне нужен призрачный гребень","что делает гребень"}},{q="Кто такая Слепая Мэри?",a="Слепая Мэри — измученный дух, обитающий в заброшенном доме в холмах к югу от Темнолесья. Обезумев от трагедии, она выдрала себе глаза и по-прежнему боится, что после смерти другие находят ее уродливой.",al={"blind mary lore","who is the ghost with the comb","blind mary","предания о слепой мэри","кто призрак с гребнем","слепая мэри"}},{q="Почему нельзя использовать обычный гребень?",a="Духов нельзя коснуться обычными физическими орудиями без особой магии или чар. Призрачный гребень создан именно для работы с неосязаемыми волосами призрака.",al={"why spectral comb","normal comb ghost","почему призрачный гребень","обычный гребень призрак"}}},fp="13,226,24.517.0,35.189.0,18.203.0,37.187.0"}
P.entries["item:spells-of-shadow"] = {n="Заклинания Тьмы",s="Заклинания Тьмы — темный гримуар, который носят культисты Пламенеющего Клинка, скрывающиеся под Оргриммаром в Огненной пропасти. Он полон магии Скверны, дарованной Пылающим Легионом, и его стремится добыть руководство Отрекшихся в Подгороде.",h="Заклинания Тьмы — темный гримуар, который носят культисты Пламенеющего Клинка, скрывающиеся под Оргриммаром в...",kw={"incantations from the nether","ragefire chasm","searing blade","spells of shadow","sylvanas","the power to destroy","undercity","varimathras","магическая формула пустоты","огненная пропасть","пламенеющий клинок","заклинания тьмы","сильвана","подгород","вариматрас"},ang={["class:Warlock"]="Фолиант — прямое демоническое покровительство Легиона, показывающее, как отколовшиеся культы вроде Пламенеющего Клинка владеют искусством Тьмы и Пустоты.",["race:Undead"]="Добыча гримуара напрямую служит леди Сильване: опасные демонические знания забирают под Оргриммаром, чтобы укрепить Подгород против Плети."},sec={{t="Фолианты Пламенеющего Клинка",b="Глубоко в раскаленных пещерах Огненной пропасти члены Пламенеющего Клинка — раскольничьего культа, связанного с Советом Теней, — применяют темные обряды, дарованные повелителями-демонами Пылающего Легиона. Среди их самых охраняемых сокровищ — Заклинания Тьмы, текст с коварным колдовством Тьмы и Скверны. Культисты и чернокнижники секты держат книгу под рукой, замышляя козни прямо под ногами Орды в Дуротаре."},{t="Амбиции Темной Госпожи",b="Слухи о демонических дарах Пламенеющего Клинка дошли до Королевского квартала Подгорода. Леди Сильвана Ветрокрылая и ее помощник-повелитель ужаса Вариматрас решили, что такие могущественные реликвии растрачены на культистов с мелкими замыслами. Вариматрас поручает героям Орды проникнуть в пропасть и забрать Заклинания Тьмы вместе с парным томом — Магической формулой Пустоты, — направив их силу на дело Отрекшихся против Плети и Короля-лича."}},faq={{q="Что такое Заклинания Тьмы?",a="Это демоническая книга заклинаний, принадлежащая культистам Пламенеющего Клинка в Огненной пропасти. В ней собраны дары магии Тьмы, пожалованные Пылающим Легионом.",al={"spells of shadow book","what is spells of shadow","shadow spells book rfc","книга заклинания тьмы","что такое заклинания тьмы","книга заклинаний тьмы огненная пропасть"}},{q="Кому нужна эта книга?",a="Вариматрас, повелитель ужаса и советник леди Сильваны Ветрокрылой, ищет фолиант для Темной Госпожи. Он находится в Королевском квартале Подгорода.",al={"who needs spells of shadow","who turns in spells of shadow","spells of shadow quest giver","кому нужны заклинания тьмы","кому сдать заклинания тьмы","кто выдает задание заклинания тьмы"}},{q="Где можно найти эту книгу?",a="Ее носят культисты и чернокнижники Пламенеющего Клинка в Огненной пропасти — сети огненных пещер под городом Оргриммар.",al={"spells of shadow location","where to get spells of shadow","how to get spells of shadow","где заклинания тьмы","где взять заклинания тьмы","как получить заклинания тьмы"}},{q="Почему Отрекшиеся хотят получить этот гримуар?",a="Леди Сильвана считает, что темные дары Легиона лучше использовать Отрекшимся, чем мелким культистам, и с помощью этой магии усилить свою войну против Плети и Короля-лича.",al={"why does sylvanas want the book","why does varimathras want spells of shadow","зачем сильване книга","зачем вариматрасу заклинания тьмы"}}},fp="16,244,26.428.0,24.478.0,29.149.0,20.156.0,28.146.0,39.195.0"}
P.entries["item:spotted-sunfish"] = {n="Пятнистая рыба-луна",s="Пятнистая рыба-луна — пресноводная рыба, обитающая в Озере Безмолвия в Красногорье. Она славится местным вкусом и служит основным товаром на причалах Приозерья, хотя растущее нашествие мурлоков делает ее добычу опасной.",h="Пятнистая рыба-луна — пресноводная рыба, обитающая в Озере Безмолвия в Красногорье.",kw={"dockmaster baren","lake everstill","lakeshire","murloc","redridge mountains","selling fish","spotted sunfish","начальник порта барен","озеро безмолвия","приозерье","мурлок","красногорье","продажа рыбы","пятнистая рыба-луна"},ang={["profession:Cooking"]="Местная пресноводная рыба, например пятнистая рыба-луна, составляет кулинарную основу Озера Безмолвия и неизменно присутствует на столах таверн Красногорья."},sec={{t="Ценный улов",b="Озеро Безмолвия издавна славится пятнистой рыбой-луной, которая стабильно ценится у местных торговцев и гостей. Начальник порта Барен ведет постоянную торговлю ею на причалах Приозерья, снабжая едой и товаром город, находящийся в тяжелом положении. Однако агрессивные племена мурлоков, бродящие на мелководье, нарушили обычный лов и часто копят собственные уловы, которые героям приходится отбирать силой."}},faq={{q="Где найти пятнистую рыбу-луну?",a="Она водится в водах Озера Безмолвия в Красногорье. Рыбаки могут ловить ее прямо в озере, но местные мурлоки тоже постоянно ее добывают, поэтому лагеря мурлоков вдоль берега — отличное место, чтобы ее раздобыть.",al={"where to get spotted sunfish","spotted sunfish location","lake everstill fish","где взять пятнистую рыбу-луну","где найти пятнистую рыбу-луну","рыба озера безмолвия"}},{q="Кто покупает пятнистую рыбу-луну или нуждается в ней?",a="Начальник порта Барен на причалах Приозерья покупает партии пятнистой рыбы-луны. Он торгует этим деликатесом и платит всем, кто принесет ему свежий товар.",al={"who wants spotted sunfish","dockmaster baren fish","selling fish quest","кому нужна пятнистая рыба-луна","начальник порта барен рыба","задание продажа рыбы"}},{q="Почему мурлоки носят с собой эту рыбу?",a="Мурлоки, живущие у Озера Безмолвия, собирают и добывают местных животных, чтобы кормить свои растущие племена. Они вытаскивают рыбу-луну из озера так же, как люди-рыбаки, и хранят ее в своих лагерях на мелководье.",al={"murloc spotted sunfish","why murlocs drop fish","мурлоки пятнистая рыба-луна","почему с мурлоков падает рыба"}},{q="Можно ли получить ее без рыбалки?",a="Да. Начальник порта Барен отмечает, что путники без удочки могут просто победить враждебных мурлоков на берегах Озера Безмолвия и забрать пойманную ими рыбу.",al={"get sunfish without fishing rod","no fishing rod sunfish","рыба-луна без удочки","нет удочки рыба-луна"}}},fp="15,243,14.430.0,32.242.0,34.172.0,36.212.0,36.184.0"}
P.entries["item:stalker-claws"] = {n="Когти равнинного охотника",s="Когти равнинного охотника — когти, добываемые у равнинных охотников, бродящих по холмистым равнинам Мулгора. Таурены-шаманы используют их как важнейшую часть при резьбе традиционных тотемов очищения для очистки оскверненных колодцев.",h="Когти равнинного охотника — когти, добываемые у равнинных охотников, бродящих по холмистым равнинам Мулгора.",kw={"cleansing totem","mulgore","mull thunderhorn","prairie stalker","stalker claws","thunderhorn totem","water well","тотем очищения","мулгор","мулл громовой рог","равнинный охотник","когти равнинного охотника","тотем громового рога","колодец"},ang={["class:Shaman"]="Когти диких хищников равнин несут яростную чистоту природы — это важнейший материал для создания и усиления тотемов очищения.",["race:Tauren"]="Добыча этих когтей служит священному долгу вашего племени — восстановить священные воды, отравленные беспечными промышленными захватчиками."},sec={{t="Хищники равнин",b="Травянистые степи Мулгора населяют смертоносные природные хищники, среди них — скрытные равнинные охотники. Эти звери выживают благодаря чистому инстинкту и смертельной точности, что важно для равновесия в замысле Матери-Земли. Мулл Громовой Рог, стремящийся исцелить испорченную землю, нуждается в этих когтях не из злобы к зверям, а потому, что чистая природная свирепость их охоты обладает духовным резонансом, необходимым для противодействия искусственной порче."},{t="Очищение колодцев",b="Когда гоблинские предприятия начали бурение и добычу по всему центральному Калимдору, химические яды глубоко просочились в подземные воды, питающие древние колодцы тауренов. Колодец Громового Рога особенно сильно пострадал от мерзкой порчи. Соединяя Когти равнинного охотника и Когти пумы в Тотем очищения колодца Громового Рога, шаманы племени создают духовный проводник, способный выжечь грязь и неестественную жижу из природных источников земли."}},faq={{q="Откуда берутся Когти равнинного охотника?",a="Их добывают, охотясь на равнинных охотников на травянистых холмах Мулгора, главным образом к востоку и западу от Деревни Кровавого Копыта.",al={"where to find stalker claws","who drops stalker claws","stalker claws source","где найти когти равнинного охотника","с кого падают когти равнинного охотника","источник когтей равнинного охотника"}},{q="Зачем Муллу Громовому Рогу нужны эти когти?",a="Мулл Громовой Рог использует эти когти вместе с Когтями пумы, чтобы создать Тотем очищения колодца Громового Рога. Врожденные чистота и сила коренных охотников равнин нужны, чтобы очистить отравленные колодцы.",al={"why gather stalker claws","mull thunderhorn purpose","use of stalker claws","зачем собирать когти равнинного охотника","зачем мулл громовой рог","применение когтей равнинного охотника"}},{q="Почему Колодец Громового Рога осквернен?",a="Колодец страдает от неестественного промышленного загрязнения, вызванного деятельностью гоблинов в Мулгоре, которая нарушает природное равновесие и отравляет местные грунтовые воды.",al={"who poisoned the well","why is thunderhorn well sick","thunderhorn pollution","кто отравил колодец","почему колодец громового рога болен","загрязнение колодца громового рога"}},{q="Что происходит после сбора когтей?",a="После сбора Мулл вырезает из когтей тотем очищения, который затем нужно отнести прямо к Колодцу Громового Рога, чтобы изгнать оставшуюся порчу.",al={"what comes next","next step after claws","cleansing totem ritual","что дальше","следующий шаг после когтей","ритуал тотема очищения"}}},fp="13,218,23.477.0,19.437.0,33.127.0,43.214.0,42.165.0,42.162.0"}
P.entries["item:steelgrill-s-tools"] = {kw={"beldin","depot","kharanos","ratchet","siege engine","spanner","steelgrill","tools","белдин","поселок","каранос","трещотка","осадная машина","гаечный ключ","сталежар","инструменты"},ang={["profession:Engineering"]="Любой инженер поймет затруднение Белдина: сложный ремонт тяжелых осадных машин регулярно губит тангенциальные вращатели и хрупкие инструменты.",["race:Dwarf"]="Обслуживать бронированные осадные машины Альянса — дело дворфийской гордости, а снабжение Белдина помогает бронированному авангарду Стальгорна оставаться готовым к бою."},sec={{t="Тяжелая рука мастера",b="Белдин Сталежар считается одним из лучших техников по осадным машинам в Дун Мороге, но его грубая манера ремонта известна среди местных торговцев. Белдин неустанно трудится над бронированными танками и механическими устройствами и ломает хрупкие инструменты почти так же быстро, как их успевают выковать. Он то ломает тангенциальные вращатели, то срывает клыкастые трещотки, и потому постоянно делает новые заказы в Каранос, чтобы пополнять запасы на своих ремонтных верстаках."},{t="Чтобы машины не останавливались",b="Эта партия инструментов жизненно важна для боеспособности боевых машин Стальгорна. В своем поселке к северо-востоку от Караноса Белдин обслуживает боевые машины для опытных водителей, таких как Пилот Камнекожиц. Без свежих гаечных ключей и трещоток важнейшие осадные машины так и остались бы наполовину собранными в снегу, а поселок и местная оборона встали бы."}},faq={{q="What are Steelgrill's Tools used for?",a="Это сменные механические инструменты, которые доставляют Белдину Сталежару в Поселок Сталежара. Они нужны ему для ремонта тяжелых дворфийских машин, особенно поврежденной осадной машины Пилота Камнекожица.",al={"what are these tools","steelgrill tools purpose"}},{q="Почему Белдин Сталежар расходует так много инструментов?",a="Белдин — исключительно грубый механик, который доводит снаряжение до поломки. По словам поставщиков из Караноса, он ломает тангенциальные вращатели и клыкастые трещотки почти быстрее, чем местные мастера успевают их делать.",al={"why broken tools","why does beldin need tools","почему сломанные инструменты","зачем белдину инструменты"}},{q="Откуда взялся этот ящик с инструментами?",a="Партия собирается и комплектуется в ближнем поселении Каранос, после чего ее передают путникам, идущим на северо-восток к Поселку Сталежара.",al={"where do i get tools","tool shipment origin","где взять инструменты","откуда поставка инструментов"}},{q="Кто такой Белдин Сталежар?",a="Белдин — мастер-механик из дворфов, владелец и руководитель Поселка Сталежара к северо-востоку от Караноса. Его считают лучшим техником по осадным машинам в регионе.",al={"who is beldin","beldin steelgrill lore","кто такой белдин","белдин сталежар предания"}}},fp="18,328,24.468.0,27.376.0,37.220.0,52.224.0,40.154.0,25.174.0"}
P.entries["item:steelsnap-s-rib"] = {n="Ребро Сталезуба",s="Ребро Сталезуба — мрачный трофей, добытый из туши свирепой гиены Сталезуба в Тысяче Игл. Его приносят в Громовой Утес как вещественное доказательство того, что существо, лишенное благословения Матери-Земли, уничтожено.",h="Ребро Сталезуба — мрачный трофей, добытый из туши свирепой гиены Сталезуба в Тысяче Игл.",kw={"camp e'thok","hunter rise","hyena","melor stonehoof","steelsnap","steelsnap's rib","thousand needles","thunder bluff","лагерь э'ток","вершина охотников","гиена","мелор каменное копыто","сталезуб","ребро сталезуба","тысяча игл","громовой утес"},ang={["class:Hunter"]="Добыча ребра вожака стаи проверяет умение охотника выслеживать опасную дичь и устранять угрозы, нарушающие равновесие дикой природы.",["race:Tauren"]="Для тауренов этот трофей — исполнение долга перед Матерью-Землей: уничтожено существо, чья безудержная жестокость оскверняет священное равновесие."},sec={{t="Охота вне благословения",b="Большинство охот тауренов ведется ради пропитания, чести или гармонии с природой. Но Сталезуб — добыча иного рода. Эта злобная гиена-вожак бродит по дну каньона Тысячи Игл к югу от Лагеря Э'Ток, терроризирует мирных животных и подстрекает стаи мелких хищников к бессмысленной бойне. Когда охотничий наставник Мелор Каменное Копыто с Вершины Охотников назначает Сталезуба к уничтожению, он требует тяжелую кость — ребро Сталезуба — как неоспоримое подтверждение того, что тиран убит, а каньон очищен от скверны."}},faq={{q="Для чего нужно Ребро Сталезуба?",a="Ребро приносят Мелору Каменному Копыту на Вершину Охотников в Громовом Утесе, чтобы завершить охоту на Сталезуба. Оно служит вещественным доказательством победы над свирепой гиеной.",al={"steelsnap rib quest","who wants steelsnaps rib","what do i do with steelsnaps rib","задание ребро сталезуба","кому нужно ребро сталезуба","что делать с ребром сталезуба"}},{q="Где найти Сталезуба, чтобы получить ребро?",a="Сталезуб бродит на северо-западе Тысячи Игл, по дну каньона к югу от Лагеря Э'Ток, обычно в окружении верных сородичей по стае.",al={"steelsnap location","where is steelsnap","find steelsnap","где сталезуб","местонахождение сталезуба","найти сталезуба"}},{q="Почему Мелор Каменное Копыто хочет убить Сталезуба?",a="Мелор считает Сталезуба противоестественным тираном, существующим вне благословения Матери-Земли. В отличие от обычных хищников, охотящихся ради выживания, Сталезуб сеет среди мирных зверей беспричинную кровавую бойню и страх, поэтому его необходимо уничтожить.",al={"why kill steelsnap","melor stonehoof motive","steelsnap lore","зачем убивать сталезуба","мотив мелора каменного копыта","предания сталезуба"}},{q="Кто такой Мелор Каменное Копыто?",a="Мелор Каменное Копыто — опытный охотник-таурен с Вершины Охотников в Громовом Утесе, который поручает начинающим следопытам выслеживать опасных зверей по всему Калимдору.",al={"who is melor","melor stonehoof location","hunter rise melor","кто такой мелор","где мелор каменное копыто","вершина охотников мелор"}}},fp="15,245,27.553.0,33.177.0,42.148.0,47.240.0,23.165.0"}
P.entries["item:stolen-silver"] = {n="Украденное серебро",s="Похищенное серебро — найденный денежный ларец Орды, предназначавшийся гарнизону стражи Перекрестка. Свирепые ящеры Степей странным образом утащили его в глушь, чем вызвали недоумение у управляющих заставы.",h="Похищенное серебро — найденный денежный ларец Орды, предназначавшийся гарнизону стражи Перекрестка.",kw={"barrens payroll","crossroads","gazrog","raptor grounds","silver lockbox","stolen silver","sunscale raptor","жалованье степей","перекресток","газрог","земли ящеров","ларец с серебром","похищенное серебро","ящер солнечной чешуи"},ang={["faction:Horde"]="Перекресток — стратегический центр присутствия Орды в Степях. Возвращение этого жалованья гарантирует, что местные воины будут сыты, получат плату и смогут удерживать рубеж против вторжений кентавров и Альянса."},sec={{t="Звериное ограбление",b="Обширные просторы Степей постоянно угрожают линиям снабжения, но мало кто ожидал, что местные ящеры Солнечной Чешуи нацелятся на ларцы с монетами. Когда перехватили груз с жалованьем для гарнизона Перекрестка, ящеры утащили ларец в свои общие гнезда на Землях Ящеров к югу от Кабестана. Таким, как Газрог, эта кража говорит о тревожной хитрости хищников, которые то ли любят блестящие безделушки, то ли разумнее обычных диких зверей."}},faq={{q="Что такое Похищенное серебро?",a="Это тяжелый ларец, наполненный серебряными монетами для оплаты стражи Перекрестка. Его похитили дикие ящеры во время засады и унесли в свои места гнездования.",al={"what is stolen silver","what is the silver","что такое похищенное серебро","что за серебро"}},{q="Зачем ящерам понадобился ларец с монетами?",a="Мотив хищников остается загадкой даже для опытных воинов вроде Газрога. Обычно звери ищут пищу, но ящеры Степей известны необычной хитростью, и этих зверей привлек блестящий металлический сундук, который они утащили вглубь логова.",al={"why do raptors want silver","raptor intelligence","why silver","зачем ящерам серебро","ум ящеров","почему серебро"}},{q="Куда унесли серебро?",a="Ящеры утащили ларец на Земли Ящеров — неровный каньон с гнездами к югу от Кабестана, в восточных Степях.",al={"stolen silver location","where is the silver","где похищенное серебро","где серебро"}},{q="Кто ищет Похищенное серебро?",a="Сундук ищет Газрог, орк, находящийся на Перекрестке. Эти деньги — полное месячное жалованье стесненных в средствах защитников заставы.",al={"who wants the silver","who turns in stolen silver","кто хочет серебро","кому сдать похищенное серебро"}}},fp="13,239,15.530.0,26.173.0,41.248.0,27.128.0,37.141.0"}
P.entries["item:stone-of-relu"] = {n="Камень Релу",s="Камень Релу — древняя археологическая реликвия, найденная в Болотине. Археолог Бутылопуз полагает, что он открывает скрытые силы в первобытных окаменелостях; камень ненадолго был утерян, когда местные ящеры напали на ученого на дороге.",h="Камень Релу — древняя археологическая реликвия, найденная в Болотине.",kw={"archaeologist flagongut","explorers league","fossil","mottled raptor","prospector whelgar","stone of relu","wetlands","археолог бутылопуз","лига исследователей","окаменелость","пятнистый ящер","геолог вельгар","камень релу","болотина"},ang={["faction:Alliance"]="Экспедиции Альянса в Гавани Менетилов рассчитывают на найденные артефакты вроде Камня Релу, чтобы оправдать тяжелые раскопки в опасных болотах.",["race:Dwarf"]="Для Лиги исследователей Камень Релу — важное средство, помогающее восстановить происхождение древней жизни и забытое наследие мира."},sec={{t="Ключ к древним реликвиям",b="Камень Релу, обнаруженный в ходе работ Лиги исследователей, как полагают, обладает силой расшифровки, необходимой для раскрытия доисторических окаменелостей, собранных в Калимдоре и Восточных королевствах. Археолог Бутылопуз определил, что артефакт — катализатор, нужный для раскрытия тайн как его собственных образцов из Болотины, так и окаменелости, найденной Геологом Сомнамбулером на Темных берегах."},{t="Потерян в болотах",b="Когда Бутылопуз шел по дорогам Болотины на встречу с Геологом Вельгаром, на него напала стая пятнистых ящеров. В суматохе реликвия была потеряна: ее проглотил один из голодных зверей. Лиге пришлось нанять искателей приключений, чтобы они охотились на болотных ящеров и извлекли древний камень из их глоток."}},faq={{q="Что такое Камень Релу?",a="Камень Релу — древний артефакт, который ищет Археолог Бутылопуз. Он считает, что камень служит шифром или катализатором, способным раскрыть скрытые тайны и силу, дремлющие в доисторических окаменелостях.",al={"stone of relu","what is this stone","relu artifact","камень релу","что за камень","артефакт релу"}},{q="Как камень оказался внутри ящера?",a="Археолог Бутылопуз нес реликвию по дороге в Болотине на встречу с Геологом Вельгаром, когда пятнистые ящеры напали на его отряд. В суматохе камень был потерян и проглочен одним из падальщиков.",al={"why do raptors have it","who dropped the stone","how was it lost","почему камень у ящеров","кто уронил камень","как потеряли камень"}},{q="Что Бутылопуз собирается делать с камнем?",a="Бутылопуз намерен соединить камень со своей найденной окаменелостью и окаменелостью, обнаруженной Геологом Сомнамбулером на Темных берегах, и с помощью реликвии расшифровать и освободить их скрытые магические тайны.",al={"what does flagongut want","stone of relu purpose","чего хочет бутылопуз","зачем нужен камень релу"}}},fp="13,258,23.387.0,19.330.0,26.207.0,41.217.0,48.190.0"}
P.entries["item:stonetalon-sap"] = {n="Слизь Каменного Когтя",s="Слизь Каменного Когтя — липкое сильное вещество, добываемое прямо из неповоротливых слизевиков, бродящих по скалистым высотам Когтистых гор. Она служит ключевым реагентом для тролля Черного Копья, знахаря Джин'Зила, который использует ее лесные свойства для приготовления злобного зелья.",h="Слизь Каменного Когтя — липкое сильное вещество, добываемое прямо из неповоротливых слизевиков, бродящих по...",kw={"jin'zil","malaka'jin","mirkfallon lake","sap beast","stonetalon peak","stonetalon sap","джин'зил","малака'джин","мутное озеро","слизевик","пик каменного когтя","слизь каменного когтя"},ang={["race:NightElf"]="Осквернение коренных стихий Когтистых гор знахарем Орды ради отравления пленных часовых — оскорбление природы и Элуны.",["race:Troll"]="Знахарь Джин'Зил демонстрирует талант Черного Копья обращать любимую врагом природу в смертоносное орудие вуду."},sec={{t="Горький урожай",b="Эта тяжелая жидкость стекает с древесных слизевиков близ Мутного озера и Пика Каменного Когтя и несет в себе сконцентрированную сущность древней флоры гор. В природе она безвредна, но в руках опытного алхимика или знахаря легко становится чем-то куда более темным. Джин'Зил из Малака'джина жаждет ее, чтобы сварить то, что он насмешливо зовет «лесной магией» — смертельное зелье, призванное мучить пленных часовых ночных эльфов самой сущностью их любимой природы."}},faq={{q="Какие существа носят Слизь Каменного Когтя?",a="Ее собирают со слизевиков — странных лесных существ, обитающих близ Мутного озера и выше по склонам, ведущим к Пику Каменного Когтя.",al={"where do you get stonetalon sap","who drops stonetalon sap","sap beasts","где взять слизь каменного когтя","кто дает слизь каменного когтя","слизевики"}},{q="Для чего Знахарь Джин'Зил использует слизь?",a="Джин'Зил смешивает слизь с глазами скакунов, сумеречными усами и чешуей волшебного дракончика, получая ядовитое варево, которое применяет к своим пленным ночным эльфам в клетках.",al={"why does jin'zil want sap","jin'zil forest magic recipe","зачем джин'зилу слизь","рецепт лесной магии джин'зила"}},{q="Где лучше всего искать слизевиков?",a="Слизевики обитают в рощах вокруг Мутного озера и на зеленых тропах, поднимающихся к Пику Каменного Когтя.",al={"sap beast location","mirkfallon lake sap beasts","где слизевики","слизевики мутного озера"}},{q="Обладает ли слизь магией сама по себе?",a="Она от природы наполнена изначальной жизненной силой Когтистых гор, но чтобы превратить ее в смертельный яд, нужны тролльское мойо и особые реагенты.",al={"is stonetalon sap magic","properties of stonetalon sap","магична ли слизь каменного когтя","свойства слизи каменного когтя"}}},fp="14,283,16.519.1,36.148.0,47.163.1,43.109.0,30.160.0"}
P.entries["item:stormpike-banner"] = {n="Знамя Грозовой Вершины",s="Знамя Грозовой Вершины — военный стяг, спрятанный в глубине коварной Пещеры Ледяного Крыла в Альтеракской долине. Новобранцы Альянса должны пройти через диких гарпий, чтобы добыть его в качестве испытания при посвящении и доказать, что достойны носить знак Грозовой Вершины.",h="Знамя Грозовой Вершины — военный стяг, спрятанный в глубине коварной Пещеры Ледяного Крыла в Альтеракской...",kw={"alterac valley","dun baldar","haggerdin","icewing caverns","insignia","proving grounds","stormpike banner","альтеракская долина","дун болдар","хаггердин","пещера ледяного крыла","знак","испытание","знамя грозовой вершины"},ang={["faction:Alliance"]="Возвращение знамени знаменует ваше официальное вступление в Стражу Грозовой Вершины и дает право носить ее боевой знак против Клана Северного Волка.",["race:Dwarf"]="Знамя олицетворяет суверенные притязания Стальгорна и священную миссию клана Грозовой Вершины — находить реликвии титанов по всей долине."},sec={{t="Обряд посвящения",b="Чтобы официально вступить в ряды экспедиции Грозовой Вершины в Альтеракской долине, новобранцы должны проявить доблесть еще до столкновений с орками Клана Северного Волка. Лейтенант Хаггердин отправляет только что прибывших солдат Альянса в Пещеру Ледяного Крыла к юго-западу от Дун Болдара. Знамя Грозовой Вершины, установленное в глубине этого ледяного подземного логова, служит испытанием: тот, кто осмелится пройти мимо местных гарпий, захватить стяг и вернуть его живым, получает звание и знак новобранца Стражи Грозовой Вершины."}},faq={{q="Где находится Знамя Грозовой Вершины?",a="Знамя установлено в глубине Пещеры Ледяного Крыла — скованной морозом системы пещер к юго-западу от Дун Болдара в Альтеракской долине.",al={"banner location","where is the stormpike banner","how to find banner","местонахождение знамени","где знамя грозовой вершины","как найти знамя"}},{q="Почему новобранцы должны добыть знамя?",a="Лейтенант Хаггердин требует от всех новобранцев Альянса показать мужество перед отправкой на передовую. Возвращение знамени из опасной пещеры, кишащей гарпиями, приносит новобранцу первый знак Грозовой Вершины.",al={"proving grounds trial","why get banner","haggerdin quest","испытание","зачем знамя","задание хаггердина"}},{q="Какие опасности охраняют знамя в пещере?",a="Пещеру Ледяного Крыла яростно защищают свирепые местные гарпии, которые безжалостно нападают на любого, кто ищет стяг.",al={"monsters near banner","icewing cavern enemies","монстры у знамени","враги пещеры ледяного крыла"}},{q="Кому сдать знамя после того, как оно найдено?",a="Доставьте найденное знамя лейтенанту Хаггердину, офицеру Альянса, который стоит у входа в Альтеракских горах.",al={"turn in banner","banner hand in","сдать знамя","передать знамя"}}},fp="16,248,19.546.0,38.137.0,44.232.0,46.129.0,41.131.0"}
P.entries["item:stormpike-s-request"] = {n="Грозовая Вершина: требование",s="«Грозовая Вершина: требование» — письменный заказ, отправленный горным пехотинцем Грозовой Вершины из холмов Лок Модана в Штормград. В письме мастера-оружейника Фьюрена Длинноборода просят выковать особый щит непревзойденного дворфийского качества.",h="«Грозовая Вершина: требование» — письменный заказ, отправленный горным пехотинцем Грозовой Вершины из холмов...",kw={"blacksmith","dun morogh","dwarven district","furen longbeard","request","shield","stormpike","stormwind","кузнец","дун морог","квартал дворфов","фьюрен длиннобород","требование","щит","грозовая вершина","штормград"},ang={["profession:Blacksmithing"]="Это требование свидетельствует о славе мастеров-оружейников: великое дворфийское кузнечное искусство находит заказчиков по всем королевствам.",["race:Dwarf"]="Для дворфов доставка этого требования поддерживает узы клана и ремесла между горными пехотинцами, охраняющими Каз Модан, и мастерами, живущими в человеческих городах."},sec={{t="Заказ с севера",b="Горному пехотинцу Грозовая Вершина, несущему службу далеко на севере, в Лок Модане, нужен прочный новый щит, чтобы выдерживать опасности дворфийского пограничья. Он не доверяет обычному кузнецу и настаивает на заказе у Фьюрена Длинноборода, оружейника, чьему легендарному мастерству он отдает величайшее уважение. Фьюрен теперь живет далеко на юге среди людей Квартала Дворфов Штормграда — по мнению Грозовой Вершины, его переманили из Стальгорна за королевский выкуп, — поэтому пехотинец полагается на странствующих искателей приключений, которые доставят его официальную просьбу через королевства."},{t="Род Грозовой Вершины",b="Письмо, доставленное в шумный Квартал Дворфов Штормграда, попадает прямо в умелые руки Фьюрена Длинноборода. Заказ гордого и известного по всему Каз Модану дворфийского клана, славного воинской доблестью и богатством, имеет вес. Фьюрен рад вестям и работе с родных северных земель предков, поэтому соглашается выполнить заказ и принимается ковать щит для пехотинца."}},faq={{q="Что такое «Грозовая Вершина: требование»?",a="Это письменный заказ, который Горный пехотинец Грозовая Вершина отправил из Лок Модана: он просит мастера-оружейника Фьюрена Длинноборода выковать ему качественный щит.",al={"what is this letter","stormpike order item","stormpike request","что это за письмо","предмет заказ грозовая вершина","грозовая вершина требование"}},{q="Кто написал это письмо?",a="Его написал Горный пехотинец Грозовая Вершина, дворфийский страж, охраняющий перевалы Лок Модана и глубоко восхищающийся кузнечным мастерством Фьюрена Длинноборода.",al={"who sent stormpikes request","who wrote it","mountaineer stormpike","кто отправил требование грозовой вершины","кто его написал","горный пехотинец грозовая вершина"}},{q="Куда нужно доставить это письмо?",a="Оно адресовано Фьюрену Длиннобороду, который работает в своей кузнице в Квартале Дворфов города Штормград.",al={"where do i take stormpikes request","who gets this letter","deliver stormpikes request","куда отнести требование грозовой вершины","кому отдать письмо","доставить требование грозовой вершины"}},{q="Почему Грозовая Вершина нанимает кузнеца аж в Штормграде?",a="Горный пехотинец Грозовая Вершина считает мастерство Фьюрена непревзойденным и не согласен ни на какого другого оружейника, хотя Фьюрен сам покинул Стальгорн, чтобы заниматься ремеслом среди людей на юге.",al={"why furen","why not forge in ironforge","why send to stormwind","почему фьюрен","почему не в стальгорне","почему отправлять в штормград"}}},fp="19,237,21.578.0,18.448.0,28.154.0,22.144.0,34.105.0,57.191.0"}
P.entries["item:stormwind-armor-marker"] = {n="Знак брони Штормграда",s="Знак брони Штормграда — официальный военный знак снабжения, выдаваемый искателям приключений, помогавшим королевству. Его можно обменять у уполномоченных мастеров, например у Сары Тимберлейн на Лесопилке Восточной долины, на свежеизготовленное снаряжение.",h="Знак брони Штормграда — официальный военный знак снабжения, выдаваемый искателям приключений, помогавшим...",kw={"armor marker","cloth and leather armor","eastvale logging camp","elwynn forest","requisition","sara timberlain","stormwind armor marker","знак брони","тканевая и кожаная броня","лесопилка восточной долины","элвиннский лес","снабжение","сара тимберлейн","знак брони штормграда"},ang={["faction:Alliance"]="Знак отражает логистические связи, напрямую соединяющие пограничные поселения вроде Лесопилки Восточной долины с военным командованием Штормграда."},sec={{t="Военное снабжение",b="Поддержание порядка в Элвиннском лесу до предела истощает ресурсы королевства. Вместо выдачи стандартного снаряжения прямо с военных застав командиры порой выдают официальные знаки, известные как знаки брони. Эти расписки подтверждают, что предъявитель доблестно служил Штормграду, и дают местным мастерам, работающим по контракту, право изготовить для него броню по мерке."},{t="Снабжение Восточной долины",b="Одно из главных мест, где принимают эти знаки, — Лесопилка Восточной долины на восточной границе Элвиннского леса. Там мастера вроде Сары Тимберлейн работают по заказу Армии Штормграда, превращая местные материалы в защитную тканевую и кожаную одежду. Предъявив знак, новобранцы получают подогнанную защиту для охраны окрестных лесов."}},faq={{q="Для чего нужен Знак брони Штормграда?",a="Это официальный военный талон, выдаваемый искателям приключений, которые помогают стражам Штормграда. Знак подтверждает вашу службу и позволяет получить предмет защитной брони у мастера, работающего по контракту с армией.",al={"what is armor marker","marker purpose","stormwind marker use","что такое знак брони","для чего знак","применение знака штормграда"}},{q="Кто принимает знак?",a="Его принимает Сара Тимберлейн на Лесопилке Восточной долины, расположенной к востоку, за рекой, в Элвиннском лесу. Она работает по контракту с Армией Штормграда и изготавливает тканевое и кожаное снаряжение по мерке.",al={"who takes the marker","where to turn in marker","sara timberlain marker","кто принимает знак","где сдать знак","сара тимберлейн знак"}},{q="Почему в Штормграде используют знаки вместо прямой выдачи брони?",a="На отдаленных заставах часто нет складов или кузнечных и портняжных мастерских, чтобы экипировать новобранцев на месте. Выдавая знаки снабжения, полевые командиры поручают экипировку местным мастерам вроде Сары Тимберлейн, у которых есть постоянные мастерские.",al={"why tokens instead of armor","why army markers","military vouchers elwynn","почему знаки а не броня","почему армейские знаки","военные талоны элвинн"}},{q="Какое снаряжение дает знак?",a="Талон дает предъявителю право выбрать между новыми предметами тканевой или кожаной брони, изготовленными на заказ поставщиками армии по контракту.",al={"what armor do i get","marker rewards","cloth or leather","какую броню я получу","награды знака","ткань или кожа"}}},fp="22,251,21.397.0,21.379.0,50.208.0,23.204.0,69.259.0,47.137.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Ответ Камнегрива Соломону",s="«Ответ Камнегрива Соломону» — письменное донесение, доставляемое со Сторожевого холма в Приозерье. В нем Гриан Камнегрив мрачно сообщает Мировому судье Соломону, что осажденное Народное ополчение не может выделить ни одного солдата для защиты Красногорья.",h="«Ответ Камнегрива Соломону» — письменное донесение, доставляемое со Сторожевого холма в Приозерье.",kw={"gryan","lakeshire","letter","magistrate solomon","messenger to westfall","peoples militia","redridge","solomon","stoutmantle","westfall","гриан","приозерье","письмо","мировой судья соломон","посыльный в западный край","народное ополчение","красногорье","соломон","камнегрив","западный край"},ang={["faction:Alliance"]="Доставка этого письма обнажает политическую гниль, парализующую ядро Альянса: отдаленные поселения вынуждены просить друг друга о помощи, пока столица удерживает свои силы.",["race:Human"]="Для людей-защитников это донесение — мрачное напоминание о том, что сельские края вроде Западного Края и Красногорья ведут ту же отчаянную борьбу за выживание без королевской стражи Штормграда."},sec={{t="Отклоненная мольба",b="Под неослабным натиском орков Черной горы и гноллов Мировой судья Соломон из Приозерья обратился к Сторожевому холму в надежде, что местные силы Западного Края пришлют подкрепление. Письменный ответ Гриана Камнегрива приносит горькие вести. Огорченный просьбой судьи, Камнегрив ясно дает понять, что Соломон не понимает тяжести конфликта, пожирающего Западный Край. Народное ополчение было создано от отчаяния именно потому, что Корона вывела гарнизон, оставив фермеров и добровольцев одних сражаться с Братством Справедливости. Камнегрив объясняет, что его силы истекают кровью и растянуты, и он не может жертвовать людьми ради спасения еще одного брошенного рубежа."},{t="Пренебрежение королевства",b="Письмо показывает общую беду южных человеческих земель в 25 году после открытия Темного портала. И Красногорье, и Западный Край оказались совершенно брошенными королевским двором в Штормграде. Король Вариан Ринн пропал, а регулярная армия королевства таинственным образом не выводится к границам провинций, поэтому окраинные города вынуждены создавать самостоятельные добровольческие дозоры или погибать. Получив запечатанный ответ, Соломон понимает, что ни один город не спасет другой: все королевство расползается, а столица молчит."}},faq={{q="Что написано в ответе Камнегрива?",a="Гриан Камнегрив объясняет, что Западный Край охвачен жестокой войной с Братством Справедливости и брошен армией Штормграда так же, как Красногорье. Он выражает скорбь о павших защитниках, но твердо отклоняет просьбу Мирового судьи Соломона о военном подкреплении.",al={"what does the letter say","stoutmantle letter contents","response to solomon text","что сказано в письме","содержание письма камнегрива","текст ответа соломону"}},{q="Почему Соломон вообще попросил помощи у Западного Края?",a="Приозерье подвергается сильным нападениям гноллов и орков Черной горы, а его просьба к генералу Маркусу Джонатану в Штормграде пока не привела ни к каким войскам. Не имея официальной поддержки, Мировой судья Соломон обратился через весь Элвиннский лес к Народному ополчению в надежде, что такие же защитники рубежей смогут выделить солдат.",al={"why ask westfall","solomon asking stoutmantle","why did lakeshire ask for the militia","почему просить западный край","соломон просит камнегрива","почему приозерье просило ополчение"}},{q="Почему Народное ополчение не может выделить солдат?",a="Народное ополчение — армия добровольцев, едва удерживающая Сторожевой холм и окрестные равнины от Братства Справедливости. Из-за растущих с каждым днем потерь и отсутствия поддержки регулярной армии отправка бойцов в Приозерье оставила бы Западный Край совершенно беззащитным.",al={"why won't militia help","can westfall help redridge","why refuse solomon","почему ополчение не поможет","может ли западный край помочь красногорью","почему отказ соломону"}},{q="Почему Армия Штормграда не защищает эти города?",a="Никто в обоих городах этого не знает. Камнегрив пишет лишь, что Штормград вывел свои войска и оставил Западный Край без защиты, а Мировой судья Соломон гадает, какое дело может быть настолько важным, чтобы увести Армию Штормграда от ее народа. Оба сельских края вынуждены полагаться на местных добровольцев.",al={"where is stormwind army","why won't stormwind help","stormwind desertion","где армия штормграда","почему штормград не поможет","бегство штормграда"}}},fp="33,251,13.687.0,21.551.1,42.282.0,57.293.0,48.269.0,52.322.0"}
P.entries["item:strange-smelling-powder"] = {n="Странно пахнущий порошок",s="«Странно пахнущий порошок» — загадочный остаток, обнаруженный при расследовании подозрительных диверсий вокруг Лок Модана. Опасаясь, что это нестабильное взрывчатое вещество, Главный инженер Хиндервейр отправляет срочного курьера на север на поиски специалиста по взрывчатке.",h="«Странно пахнущий порошок» — загадочный остаток, обнаруженный при расследовании подозрительных диверсий...",kw={"a dark threat looms","ashlan stonesmirk","dun modr","hinderweir","loch modan","strange smelling powder","thandol span","надвигается темная угроза","ашлан камнехмыл","дун модр","хиндервейр","лок модан","странно пахнущий порошок","мост тандола"},ang={["profession:Engineering"]="Инженеры узнают запах серных нестабильных взрывчатых смесей, не соответствующих стандартным рецептам, которые используются на горных заставах Альянса.",["race:Dwarf"]="Для дворфов защита каменных сооружений и водохранилищ Лок Модана превыше всего, поэтому любой намек на вражескую взрывчатку сразу становится кризисом для клана."},sec={{t="Опасная находка",b="Этот необычный порошок, найденный среди следов диверсий, угрожающих инфраструктуре Лок Модана, сразу встревожил Главного инженера Хиндервейра. Резкий запах и мелкая консистенция говорят скорее о специально созданном взрывчатом составе, чем об обычном горном порохе. Не зная химической природы смеси и ее происхождения, Хиндервейр отказывается трогать ее сам, понимая, что даже слабая искра может вызвать катастрофу."},{t="Дорога на север",b="Поскольку дворфийские инженеры не рискуют с нестабильными реагентами, Хиндервейр посылает образцы порошка через Врата Альгаза в Болотину. Там, в Дун Модре близ Моста Тандола, опытному специалисту по взрывчатке Ашлану Камнехмылу поручено исследовать крупицы и определить, какой катастрофический взрыв готовят диверсанты."}},faq={{q="Что такое «Странно пахнущий порошок»?",a="Это подозрительный химический остаток, найденный в Лок Модане при расследовании местных диверсий. Резкая вонь и состав заставляют дворфийских инженеров подозревать, что это взрывчатое вещество.",al={"what is strange smelling powder","what is this powder","powder loch modan","что такое странно пахнущий порошок","что за порошок","порошок лок модан"}},{q="Почему Главный инженер Хиндервейр хочет его исследовать?",a="Хиндервейр подозревает, что порошок — особая взрывчатка. Чтобы понять масштаб и угрозу заговора против Лок Модана, ему нужен профессиональный анализ от того, кто хорошо разбирается в тяжелой подрывной работе.",al={"why examine powder","hinderweir powder","who needs this powder","зачем исследовать порошок","хиндервейр порошок","кому нужен порошок"}},{q="Кто может определить порошок?",a="Главный инженер Хиндервейр велит путникам отнести образец Ашлану Камнехмылу, специалисту по взрывчатке, служащему далеко на севере вместе с полком в Дун Модре, близ Моста Тандола.",al={"who identifies the powder","where do i take the powder","powder expert","кто определит порошок","куда отнести порошок","эксперт по порошку"}},{q="Чем опасна перевозка порошка?",a="Помимо присущей неизвестному взрывчатому веществу нестабильности, перенос образца требует преодолеть опасный путь через Врата Альгаза по болотистым враждебным дорогам Болотины.",al={"is the powder dangerous","why dangerous","опасен ли порошок","почему опасно"}}},fp="23,268,20.427.0,14.358.1,32.197.0,52.214.0,28.180.0,41.189.0"}
